#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_SINGLE_SHOT 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_ENDED_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000   // +/- 4.096V range
#define CONFIG_MODE_SINGLE 0x0100  // Single-shot mode
#define CONFIG_DR_128SPS 0x0080   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000  // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// MLX91219 sensitivity (40mV/A)
#define MLX91219_SENSITIVITY 0.040

// Function prototypes
int init_i2c(int i2c_bus, int i2c_address);
int16_t read_adc(int i2c_handle);
float convert_to_current(int16_t adc_value);
void signal_handler(int signal);

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Initialize I2C communication
int init_i2c(int i2c_bus, int i2c_address) {
    int handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read ADC value from ADS1115
int16_t read_adc(int i2c_handle) {
    // Configure the ADS1115 for single-shot mode
    uint16_t config = CONFIG_SINGLE_SHOT | CONFIG_MUX_SINGLE_ENDED_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;

    // Write the configuration to the ADS1115
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    buf[0] = ADS1115_REG_CONVERT;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C for read: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];

    return adc_value;
}

// Convert ADC value to current in amperes
float convert_to_current(int16_t adc_value) {
    // Convert ADC value to voltage (assuming +/- 4.096V range)
    float voltage = (float)adc_value * 4.096 / 32768.0;

    // Convert voltage to current using MLX91219 sensitivity
    float current = voltage / MLX91219_SENSITIVITY;

    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_handle = init_i2c(1, ADS1115_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        int16_t adc_value = read_adc(i2c_handle);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Try again
        }

        // Convert ADC value to current
        float current = convert_to_current(adc_value);

        // Print the current value
        printf("Current: %.3f A\n", current);

        // Wait 500ms
        gpioDelay(500000);
    }

    // The following lines will never be reached because of the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

