#define BUZZER_GPIO 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define TEMPERATURE_THRESHOLD 60.0
#define DEBOUNCE_DELAY 50 // milliseconds
#define BUZZER_DURATION 2 // seconds

// Global variables
static volatile int running = 1;
static volatile unsigned int last_flame_time = 0;
static int i2c_handle;
static FILE *log_file;

// Function prototypes
int init_gpio();
int init_i2c();
int read_temperature();
void flame_detected_callback(int gpio, int level, unsigned int tick);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Configure ADS1115 for single-shot mode, AIN0, gain ±4.096V, 128 SPS
    uint16_t config = 0x4003; // Single-shot, AIN0, +/-4.096V, 128 SPS
    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read temperature from ADS1115
int read_temperature() {
    char buf[1];
    char read_buf[2];
    int16_t adc_value;
    float voltage, temperature;

    // Request a single conversion
    buf[0] = ADS1115_CONFIG_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion to complete (at least 8.5ms)
    gpioDelay(8500); // 8.5ms

    // Read the conversion result
    buf[0] = ADS1115_CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }

    adc_value = (read_buf[0] << 8) | read_buf[1];

    // Convert ADC value to voltage (assuming gain of 4.096V)
    voltage = (float)adc_value * 4.096 / 32768.0;

    // Convert voltage to temperature (linear mapping 0V-3.3V to 20°C-80°C)
    temperature = (voltage / 3.3) * 60.0 + 20.0;

    return (int)temperature;
}

// Callback function for flame sensor
void flame_detected_callback(int gpio, int level, unsigned int tick) {
    unsigned int current_time = gpioTick();

    if (level == 0) { // Falling edge detected
        if (current_time - last_flame_time > DEBOUNCE_DELAY * 1000) { // Debounce
            last_flame_time = current_time;
            int temperature = read_temperature();
            if (temperature > TEMPERATURE_THRESHOLD) {
                log_event("Fire detected!");
                gpioWrite(BUZZER_GPIO, 1); // Activate buzzer
                gpioDelay(BUZZER_DURATION * 1000000); // Keep buzzer on for 2 seconds
                gpioWrite(BUZZER_GPIO, 0); // Deactivate buzzer
            } else {
                log_event("Flame detected!");
            }
        }
    }
}

// Function to log events to file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL); // Deregister ISR
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register ISR for flame sensor
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, flame_detected_callback, NULL);

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int temperature = read_temperature();
        if (temperature > TEMPERATURE_THRESHOLD) {
            char temp_str[50];
            snprintf(temp_str, sizeof(temp_str), "Temperature above threshold: %.2f°C", (float)temperature);
            log_event(temp_str);
        }
        gpioDelay(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

