#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <getopt.h>
#include <errno.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_CHIP_ALT_NAME "gpiochip0"
#define GPIO_PIN 18
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define DEFAULT_SENSITIVITY 100.0 // mV/A
#define DEFAULT_THRESHOLD 5.0 // A
#define LOG_FILE "current_log.txt"

// Global variables (to be minimized, used for signal handling)
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static double sensitivity = DEFAULT_SENSITIVITY;
static double threshold = DEFAULT_THRESHOLD;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_open(const char *device);
int spi_configure(int fd, uint8_t mode, uint8_t bits, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
double adc_to_voltage(int adc_value, double vref);
double voltage_to_current(double voltage, double sensitivity);
int gpio_export(struct gpiod_chip *chip, int pin);
int gpio_set_direction(struct gpiod_line *line, int direction);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_unexport(struct gpiod_chip *chip, int pin);
void log_data(double current);
void signal_handler(int sig);
char* get_iso8601_timestamp();

// SPI functions
int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }
    return fd;
}

int spi_configure(int fd, uint8_t mode, uint8_t bits, uint32_t speed) {
    uint8_t mode_reg = SPI_MODE_3; // Default mode
    if (mode == SPI_MODE_0) mode_reg = SPI_MODE_0;
    else if (mode == SPI_MODE_1) mode_reg = SPI_MODE_1;
    else if (mode == SPI_MODE_2) mode_reg = SPI_MODE_2;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_reg) == -1) {
        perror("Error setting SPI mode");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        return -1;
    }

    return 0;
}

int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// ADC to voltage conversion
double adc_to_voltage(int adc_value, double vref) {
    return ((double)adc_value / 1023.0) * vref;
}

// Voltage to current conversion
double voltage_to_current(double voltage, double sensitivity) {
    return voltage / (sensitivity / 1000.0); // Convert mV/A to V/A
}

// GPIO functions
int gpio_export(struct gpiod_chip *chip, int pin) {
    if (!chip) {
        fprintf(stderr, "Error: GPIO chip is NULL in gpio_export\n");
        return -1;
    }
    if (gpiod_line_request_output(chip, pin, "current_sensor", 0) < 0) {
        perror("Error requesting GPIO line for output");
        return -1;
    }
    return 0;
}

int gpio_set_direction(struct gpiod_line *line, int direction) {
    if (!line) {
        fprintf(stderr, "Error: GPIO line is NULL in gpio_set_direction\n");
        return -1;
    }
    if (gpiod_line_set_value(line, direction) < 0) {
        perror("Error setting GPIO direction");
        return -1;
    }
    return 0;
}

int gpio_set_value(struct gpiod_line *line, int value) {
    if (!line) {
        fprintf(stderr, "Error: GPIO line is NULL in gpio_set_value\n");
        return -1;
    }
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

int gpio_unexport(struct gpiod_chip *chip, int pin) {
    if (!chip) {
        fprintf(stderr, "Error: GPIO chip is NULL in gpio_unexport\n");
        return -1;
    }
    if (gpiod_line_release(chip->lines[pin]) < 0) {
        perror("Error releasing GPIO line");
        return -1;
    }
    return 0;
}

// Logging function
void log_data(double current) {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return;
    }

    fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Get ISO-8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

int main(int argc, char *argv[]) {
    int opt;
    const char *gpio_chip_name = GPIO_CHIP_NAME;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (spi_configure(spi_fd, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED) < 0) {
        close(spi_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(gpio_chip_name);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip '%s', trying '%s'\n", gpio_chip_name, GPIO_CHIP_ALT_NAME);
        gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP_ALT_NAME);
        if (!gpio_chip) {
            perror("Error opening GPIO chip");
            close(spi_fd);
            fclose(log_file);
            return EXIT_FAILURE;
        }
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpio_export(gpio_chip, GPIO_PIN) < 0) {
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t tx_buf[3] = {0x01, 0x80, 0x00};
        uint8_t rx_buf[3] = {0};

        if (spi_transfer(spi_fd, tx_buf, rx_buf, sizeof(tx_buf)) < 0) {
            fprintf(stderr, "SPI transfer failed, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Sensor absent check
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent or malfunctioning (ADC value: %d)\n", adc_value);
            log_data(-1.0); // Log -1.0 to indicate an error
            sleep(1);
            continue;
        }

        double voltage = adc_to_voltage(adc_value, 3.3);
        double current = voltage_to_current(voltage, sensitivity);

        // Control cooling fan
        if (current > threshold) {
            gpio_set_value(gpio_line, 1); // Turn fan ON
        } else {
            gpio_set_value(gpio_line, 0); // Turn fan OFF
        }

        log_data(current);

        sleep(1); // Sample once per second
    }

    // Cleanup
    gpio_set_value(gpio_line, 0); // Turn fan OFF
    gpio_unexport(gpio_chip, GPIO_PIN);
    gpiod_chip_close(gpio_chip);
    close(spi_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

