#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define ADS1115_ADDRESS 0x48 // Example address for ADS1115
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0060
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000
#define ADS1115_CONFIG_COMP_POL_LOW 0x0002
#define ADS1115_CONFIG_COMP_LAT_NON 0x0004
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003

#define LOG_FILE "co_log.txt"

// Calibration parameters (example values, replace with your sensor's calibration data)
#define A 0.1
#define B 1.0
#define C 0.01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t co_raw;
    float co_ppm;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_ads1115(int16_t *value);
float convert_to_ppm(int16_t raw_value);
int log_data(float ppm_value);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115 ADC
int read_ads1115(int16_t *value) {
    char config[3];
    char data[2];

    // Configure ADS1115 for single-ended AIN0 measurement
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE) >> 8;
    config[2] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE) & 0xFF;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    data[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register\n");
        return -1;
    }

    *value = (data[0] << 8) | data[1];
    return 0;
}

// Convert raw ADC value to CO concentration in PPM
float convert_to_ppm(int16_t raw_value) {
    // Implement the logarithmic conversion formula here
    // This is a placeholder, replace with your sensor's calibration data
    float resistance = (float)raw_value; // Assuming raw_value is proportional to resistance
    float ppm = A * log10(resistance) + B * resistance + C;
    return ppm;
}

// Log data to file
int log_data(float ppm_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f PPM\n", timestamp, ppm_value);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            float ppm_value = convert_to_ppm(raw_value);
            log_data(ppm_value);
            printf("CO concentration: %.2f PPM\n", ppm_value);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000000); // 5 seconds
    }

    cleanup();
    return 0;
}

