#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_GPIO 4
#define SPI_CE0 8
#define SPI_SCLK 11
#define SPI_MOSI 10
#define SPI_MISO 9

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define temperature scaling parameters
#define TEMP_MIN 10.0
#define TEMP_MAX 40.0
#define ADC_MIN 0
#define ADC_MAX 1023

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_flame_sensor();
int read_mcp3008(int channel);
float adc_to_temperature(int adc_value);
int log_data(int flame_detected, float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int flame_gpio;
    int spi_ce;
    int spi_sclk;
    int spi_mosi;
    int spi_miso;
    int spi_channel;
    int spi_speed;
    int spi_mode;
    float temp_min;
    float temp_max;
    int adc_min;
    int adc_max;
} config_t;

config_t config = {
    FLAME_SENSOR_GPIO, SPI_CE0, SPI_SCLK, SPI_MOSI, SPI_MISO, SPI_CHANNEL, SPI_SPEED, SPI_MODE, TEMP_MIN, TEMP_MAX, ADC_MIN, ADC_MAX
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int flame_detected = read_flame_sensor();
        int adc_value = read_mcp3008(0);
        float temperature = adc_to_temperature(adc_value);

        if (flame_detected != -1 && adc_value != -1) {
            if (log_data(flame_detected, temperature) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input
    gpioSetMode(config.flame_gpio, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("flame_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,FlameDetected,Temperature\n");
    }

    return 0;
}

int read_flame_sensor() {
    int value = gpioRead(config.flame_gpio);
    if (value >= 0) {
        return value;
    } else {
        fprintf(stderr, "Failed to read flame sensor: %d\n", value);
        return -1;
    }
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
