int read_sensor_data(uint16_t *ox, uint16_t *red);
float calculate_co_ppm(uint16_t ox, uint16_t red);
int log_co_level(float co_ppm);
int log_alert(float co_ppm);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    uint16_t ox;
    uint16_t red;
} sensor_data_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MICS4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

