int read_sensor_data(uint16_t *ox, uint16_t *red) {
    char buf[4];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    *ox = (buf[0] << 8) | buf[1];
    *red = (buf[2] << 8) | buf[3];

    return 0;
}

