float calculate_co_ppm(uint16_t ox, uint16_t red) {
    // Simple linear conversion (replace with actual calibration data)
    // This is a placeholder; refer to the MICS-4514 datasheet for proper calibration.
    float ox_ratio = (float)ox / 65535.0;
    float red_ratio = (float)red / 65535.0;
    float co_ppm = 100.0 * ox_ratio / (ox_ratio + red_ratio); // Example formula

    return co_ppm;
}

