        fprintf(stderr, "Error opening alert file: %s\n", ALERT_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ALERT: CO level %.2f PPM exceeds threshold %.2f PPM\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm, CO_PPM_THRESHOLD);
    fclose(fp);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t ox, red;
    float co_ppm;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&ox, &red) == 0) {
            // Calculate CO level
            co_ppm = calculate_co_ppm(ox, red);

            // Log CO level
            if (log_co_level(co_ppm) != 0) {
                fprintf(stderr, "Error logging CO level\n");
            }

            // Check for alert
            if (co_ppm > CO_PPM_THRESHOLD) {
                if (log_alert(co_ppm) != 0) {
                    fprintf(stderr, "Error logging alert\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for the next reading
        sleep(READ_INTERVAL_SEC);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

