#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Define I2C addresses for the microphones
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49

// Define the register to read from
#define ADC_REG 0x00

// Define the sampling interval in milliseconds
#define SAMPLE_INTERVAL_MS 100

// Define the microphone sensitivity in dBV/Pa
#define MIC_SENSITIVITY_DBV 38.0

// Define the reference pressure in Pascals
#define REFERENCE_PRESSURE_PA 20e-6

// Global variables for I2C handles and program state
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_microphone(int i2c_handle);
float calculate_spl(int16_t raw_data);
void log_data(float spl1, float spl2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from a microphone
int read_microphone(int i2c_handle) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, ADC_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1; // Indicate an error
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t raw_data = (buf[0] << 8) | buf[1];

    return raw_data;
}

// Function to calculate the sound pressure level (SPL)
float calculate_spl(int16_t raw_data) {
    // Convert the raw data to a voltage (assuming a full-scale range of +/- 3.3V)
    float voltage = (float)raw_data / 32768.0 * 3.3;

    // Calculate the SPL in dB
    float spl = 20 * log10(voltage / (10^(-MIC_SENSITIVITY_DBV / 20.0)));

    return spl;
}

// Function to log the data to a file
void log_data(float spl1, float spl2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen("audio_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, spl1, spl2);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both microphones
    i2c_handle1 = i2cOpen(1, MIC1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(1, MIC2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Acoustic leak detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int16_t raw_data1 = read_microphone(i2c_handle1);
        int16_t raw_data2 = read_microphone(i2c_handle2);

        float spl1, spl2;

        if (raw_data1 == -1) {
            spl1 = -999.0; // Log error value
            fprintf(stderr, "Error reading microphone 1, logging -999.0\n");
        } else {
            spl1 = calculate_spl(raw_data1);
        }

        if (raw_data2 == -1) {
            spl2 = -999.0; // Log error value
            fprintf(stderr, "Error reading microphone 2, logging -999.0\n");
        } else {
            spl2 = calculate_spl(raw_data2);
        }

        log_data(spl1, spl2);

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Close I2C handles and terminate pigpio
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    printf("Acoustic leak detection system stopped.\n");

    return 0;
}

