#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 27
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_INTERVAL_US 1000 // 1 ms
#define RMS_THRESHOLD 0.7
#define NUM_SAMPLES (SAMPLE_WINDOW_MS * 1000) / SAMPLE_INTERVAL_US

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int16_t mic1_data[NUM_SAMPLES];
    int16_t mic2_data[NUM_SAMPLES];
} MicrophoneData;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float calculate_rms(int16_t *data, int num_samples);
void log_data(float mic1_rms, float mic2_rms);
void signal_handler(int signal);
void cleanup();

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the SPI message to send to the MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    // Extract the ADC value from the response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate the RMS value of an array of data
float calculate_rms(int16_t *data, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)data[i] * data[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Function to log data to a CSV file
void log_data(float mic1_rms, float mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    MicrophoneData mic_data;

    // Main loop
    while (!terminate) {
        // Sample microphone data
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int mic1_adc = read_mcp3008(0);
            int mic2_adc = read_mcp3008(1);

            if (mic1_adc < 0 || mic2_adc < 0) {
                fprintf(stderr, "Error reading ADC data, retrying...\n");
                gpioDelay(1000); // Wait 1ms before retrying
                i--; // Retry the current sample
                continue;
            }

            mic_data.mic1_data[i] = (int16_t)mic1_adc;
            mic_data.mic2_data[i] = (int16_t)mic2_adc;

            gpioDelay(SAMPLE_INTERVAL_US); // Sample every 1 ms
        }

        // Calculate RMS values
        float mic1_rms = calculate_rms(mic_data.mic1_data, NUM_SAMPLES);
        float mic2_rms = calculate_rms(mic_data.mic2_data, NUM_SAMPLES);

        // Normalize RMS values (assuming 10-bit ADC, max value is 1023)
        mic1_rms /= 1023.0;
        mic2_rms /= 1023.0;

        // Check if RMS values exceed threshold
        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            gpioWrite(LED_GPIO, 1); // Turn on LED
            gpioDelay(500000); // Wait 500 ms
            gpioWrite(LED_GPIO, 0); // Turn off LED
        }

        // Log data
        log_data(mic1_rms, mic2_rms);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

