#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define SAMPLE_RATE_HZ 10
#define BUFFER_SIZE 100
#define OVERCURRENT_THRESHOLD 50.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int configure_ads1115();
int16_t read_adc();
float convert_to_current(int16_t adc_value);
void update_circular_buffer(float current);
float calculate_average_current();
void control_led(float average_current);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_pin;
    float overcurrent_threshold;
} Config;

Config config = {I2C_BUS, ADS1115_ADDR, LED_GPIO, OVERCURRENT_THRESHOLD};

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        fprintf(stderr, "Failed to configure ADS1115. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_pin, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_adc();
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value. Continuing.\n");
            gpioDelay(1000000 / SAMPLE_RATE_HZ); // Delay even on error
            continue;
        }

        // Convert ADC value to current
        float current = convert_to_current(adc_value);

        // Update circular buffer
        update_circular_buffer(current);

        // Calculate average current
        float average_current = calculate_average_current();

        // Control LED based on average current
        control_led(average_current);

        // Delay for sampling rate
        gpioDelay(1000000 / SAMPLE_RATE_HZ); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(config.led_pin, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure ADS1115 for single-ended input on channel A0, 4.096V range, continuous conversion mode
int configure_ads1115() {
    // Configuration register value: Single-ended A0, 4.096V, Continuous, 128 SPS
    uint16_t config_value = 0x4003; //0b0100000000000011

    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int16_t read_adc() {
    char buf[1];
    buf[0] = CONVERSION_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to conversion register: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read conversion register: %d\n", result);
        return -1;
    }

    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];
    return adc_value;
}

// Convert ADC value to current (0.5V to 4.5V corresponds to 0-100A)
float convert_to_current(int16_t adc_value) {
    // Assuming 16-bit ADC (2^15 = 32768)
    float voltage = (adc_value / 32768.0) * 5.0; // Convert ADC value to voltage (0-5V)
    float current = (voltage - 0.5) * (100.0 / 4.0); // Convert voltage to current (0-100A)
    return current;
}

// Update circular buffer with new current reading
void update_circular_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average current from circular buffer
float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > config.overcurrent_threshold) {
        gpioWrite(config.led_pin, 1); // Turn on LED
    } else {
        gpioWrite(config.led_pin, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

