#define TCS34725_CONTROL_REG 0x0F
#define TCS34725_ENABLE_REG 0x00
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ENABLE_AIEN 0x10
#define TCS34725_CDATA_REG 0x14
#define TCS34725_RDATA_REG 0x16
#define TCS34725_GDATA_REG 0x18
#define TCS34725_BDATA_REG 0x1A
#define TCS34725_INTEGRATION_TIME 0xFF // 2.4ms
#define TCS34725_GAIN_4X 0x01
#define SLEEP_MS 1000 // 1 second

