static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_color_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to initialize the TCS34725 sensor
int initialize_sensor() {
    int retries = 3;
    int status;

    // Verify sensor ID
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, TCS34725_ID_REG);
        if (status >= 0) {
            if ((status & 0x0F) == 0x44) {
                break; // Sensor ID is correct
            } else {
                fprintf(stderr, "Error: Incorrect sensor ID: 0x%02X\n", status);
                return -1;
            }
        } else {
            fprintf(stderr, "Error reading sensor ID: %d, retrying...\n", status);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to read sensor ID after multiple retries.\n");
        return -1;
    }

    // Set integration time
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME_REG, TCS34725_INTEGRATION_TIME) < 0) {
        fprintf(stderr, "Error setting integration time.\n");
        return -1;
    }

    // Set gain
    if (i2cWriteByteData(i2c_handle, TCS34725_CONTROL_REG, TCS34725_GAIN_4X) < 0) {
