        return -1;
    }

    // Power on and enable ADC
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE_REG, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Error enabling sensor.\n");
        return -1;
    }

    gpioDelay(3000); // Wait 3ms after power-on

    return 0;
}

