    int status;

    status = i2cReadWordData(i2c_handle, TCS34725_CDATA_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading clear data: %d\n", status);
        return -1;
    }
    *clear = (uint16_t)status;

    status = i2cReadWordData(i2c_handle, TCS34725_RDATA_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading red data: %d\n", status);
        return -1;
    }
    *red = (uint16_t)status;

    status = i2cReadWordData(i2c_handle, TCS34725_GDATA_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading green data: %d\n", status);
        return -1;
    }
    *green = (uint16_t)status;

    status = i2cReadWordData(i2c_handle, TCS34725_BDATA_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading blue data: %d\n", status);
        return -1;
    }
    *blue = (uint16_t)status;

    return 0;
}

