        gpiod_line_set_value(chip_select_line, 1);
        return -1;
    }

    // De-assert chip select
    if (gpiod_line_set_value(chip_select_line, 1) < 0) {
        perror("Error de-asserting chip select");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Map raw ADC value to moisture percentage
float map_moisture(int raw_value) {
    return ((float)raw_value / 1023.0) * 100.0;
}

// Log data to CSV file
int log_data(float moisture1, float moisture2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, moisture1, moisture2);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up...\n");

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Release GPIO line
    if (chip_select_line) {
        gpiod_line_release(chip_select_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    chip_select_line = gpiod_chip_get_line(gpio_chip, CHIP_SELECT_PIN);
    if (!chip_select_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(chip_select_line, "moisture_sensor", 1) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(MOISTURE_LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");
    }

    // Main loop
    while (!terminate) {
        // Read sensor values
        int raw_value1 = read_mcp3008(0);
        int raw_value2 = read_mcp3008(1);

        if (raw_value1 == -1 || raw_value2 == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue; // Retry
        }

        // Map to moisture percentage
        float moisture1 = map_moisture(raw_value1);
        float moisture2 = map_moisture(raw_value2);

        // Log data
        if (log_data(moisture1, moisture2) < 0) {
            fprintf(stderr, "Error logging data. Check file permissions.\n");
        }

        printf("Moisture 1: %.2f%%, Moisture 2: %.2f%%\n", moisture1, moisture2);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

