// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *shutdown_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void log_current(float current);
void shutdown_motor();
void enable_motor();
void signal_handler(int sig);
int setup_gpio();
int cleanup_gpio();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];
    int retries = 3;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    while (retries > 0) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
            perror("SPI transaction failed");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        } else {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        }
    }

    fprintf(stderr, "Failed to read MCP3008 after multiple retries.\n");
    return -1; // Indicate error
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3 / 1023.0;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    return (voltage - OFFSET) / SENSITIVITY;
}

