    if (shutdown_line != NULL) {
        gpiod_line_set_value(shutdown_line, 1); // Set pin HIGH
        printf("Motor enabled!\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

