int setup_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    shutdown_line = gpiod_chip_get_line(gpio_chip, MOTOR_SHUTDOWN_PIN);
    if (!shutdown_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(shutdown_line, "motor_shutdown", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO resources
int cleanup_gpio() {
    if (shutdown_line) {
        gpiod_line_release(shutdown_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup_gpio();
        return 1;
    }

    // Configure SPI mode
    unsigned char mode = 0; // SPI_MODE_0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Convert to voltage and current
        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage);

        // Log current reading
        log_current(current);

        // Check for overcurrent condition
        if (current > OVERCURRENT_THRESHOLD) {
            shutdown_motor();
            sleep(1);
            enable_motor();
        }

        sleep(1); // Sample every 1 second
    }

