#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define PRESSURE_REGISTER 0x00
#define LOG_FILE "pressure_log.csv"
#define SLEEP_SECONDS 1

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_pressure(int i2c_handle, uint16_t *raw_value);
float convert_to_kPa(uint16_t raw_value);
int log_pressure(FILE *log_file, float pressure_kPa);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold program state
typedef struct {
    int i2c_handle;
    FILE *log_file;
} ProgramState;

ProgramState state;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read pressure from the sensor
int read_pressure(int i2c_handle, uint16_t *raw_value) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading pressure register: %d\n", result);
        return -1; // Indicate failure
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0; // Indicate success
}

// Function to convert raw value to kPa
float convert_to_kPa(uint16_t raw_value) {
    return (float)raw_value / 65535.0 * 500.0;
}

// Function to log pressure to a file
int log_pressure(FILE *log_file, float pressure_kPa) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file);
    return 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
        fflush(log_file);
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    uint16_t raw_value;
    float pressure_kPa;
    int read_attempts = 0;
    const int max_read_attempts = 3;

    // Main loop
    while (!terminate) {
        // Read pressure
        if (read_pressure(i2c_handle, &raw_value) == 0) {
            // Convert to kPa
            pressure_kPa = convert_to_kPa(raw_value);

            // Log pressure
            if (log_pressure(log_file, pressure_kPa) != 0) {
                fprintf(stderr, "Failed to log pressure.\n");
            }
            read_attempts = 0; // Reset read attempts on success
        } else {
            fprintf(stderr, "Failed to read pressure. Attempt: %d\n", read_attempts + 1);
            read_attempts++;
            if (read_attempts >= max_read_attempts) {
                fprintf(stderr, "Max read attempts reached. Exiting.\n");
                terminate = 1; // Exit loop after max attempts
            }
        }

        // Sleep for 1 second
        gpioSleep(PI_TIME_RELATIVE, SLEEP_SECONDS, 0);
    }

    // Cleanup
    cleanup();

    return 0;
}

