        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
        fflush(log_file);
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    uint16_t raw_value;
    float pressure_kPa;
    int read_attempts = 0;
    const int max_read_attempts = 3;

    // Main loop
    while (!terminate) {
        // Read pressure
        if (read_pressure(i2c_handle, &raw_value) == 0) {
            // Convert to kPa
            pressure_kPa = convert_to_kPa(raw_value);

            // Log pressure
            if (log_pressure(log_file, pressure_kPa) != 0) {
                fprintf(stderr, "Failed to log pressure.\n");
            }
            read_attempts = 0; // Reset read attempts on success
        } else {
            fprintf(stderr, "Failed to read pressure. Attempt: %d\n", read_attempts + 1);
            read_attempts++;
            if (read_attempts >= max_read_attempts) {
                fprintf(stderr, "Max read attempts reached. Exiting.\n");
                terminate = 1; // Exit loop after max attempts
            }
        }

        // Sleep for 1 second
        gpioSleep(PI_TIME_RELATIVE, SLEEP_SECONDS, 0);
    }

    // Cleanup
    cleanup();

    return 0;
