        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC values
        int pressure_adc = read_adc(0);
        int temperature_adc = read_adc(1);

        // Convert ADC values to voltage (assuming 16-bit ADC and 6.144V FSR)
        float pressure_voltage = (float)pressure_adc / 32767.0 * 6.144;
        float temperature_voltage = (float)temperature_adc / 32767.0 * 6.144;

        // Convert voltage to pressure and temperature
        float pressure = voltage_to_pressure(pressure_voltage);
        float temperature = voltage_to_temperature(temperature_voltage);

        // Display data
        display_data(pressure, temperature);

        // Control LED
        control_led(pressure);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup resources
    cleanup();

    return 0;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure ADS1115 for single-ended mode, AIN0 and AIN1, gain 2/3, 128 SPS
    // Single-shot mode, disable comparator, continuous conversion
    unsigned short config_value = 0x4003; // Single-ended AIN0, 2/3 gain, 128 SPS, start single conversion
    char config_data[3];
    config_data[0] = ADS1115_REG_CONFIG;
    config_data[1] = (config_value >> 8) & 0xFF;
    config_data[2] = config_value & 0xFF;

