    if (result != 0) {
        fprintf(stderr, "Failed to write config to ADS1115: %d\n", result);
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read ADC value from specified channel
int read_adc(int channel) {
    // Set the channel in the configuration register
    unsigned short config_value = 0x4003; // Single-ended AIN0, 2/3 gain, 128 SPS, start single conversion
    if (channel == 1) {
        config_value = 0x5003; // Single-ended AIN1, 2/3 gain, 128 SPS, start single conversion
    }

    char config_data[3];
    config_data[0] = ADS1115_REG_CONFIG;
    config_data[1] = (config_value >> 8) & 0xFF;
    config_data[2] = config_value & 0xFF;

    int result = i2cWriteDevice(i2c_handle, config_data, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write config to ADS1115 for channel %d: %d\n", channel, result);
        return -1; // Indicate error
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    char read_data[2];
    result = i2cReadDevice(i2c_handle, read_data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from ADS1115: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes to form the 16-bit ADC value
    int16_t adc_value = (read_data[0] << 8) | read_data[1];

    // Sign extend if necessary (ADS1115 is a signed ADC)
    if (adc_value & 0x8000) {
        adc_value |= 0xFFFF0000; // Sign extend to 32 bits
    }

    return adc_value;
}

