#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_REG_CONFIG_DEFAULT 0x4003 // Single-shot, AIN0, +/-4.096V, 128 SPS
#define VREF 4.096
#define SENSITIVITY 0.1
#define OFFSET 0.5
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int16_t read_adc();
float convert_to_voltage(int16_t raw_value);
float convert_to_pressure(float voltage);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    float vref;
    float sensitivity;
    float offset;
} sensor_config_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read ADC value
int16_t read_adc() {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_REG_CONFIG_DEFAULT >> 8) & 0xFF;
    config[2] = ADS1115_REG_CONFIG_DEFAULT & 0xFF;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    char read_buffer[2];
    if (i2cReadDevice(i2c_handle, read_buffer, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    int16_t raw_value = (read_buffer[0] << 8) | read_buffer[1];
    return raw_value;
}

// Function to convert raw ADC value to voltage
float convert_to_voltage(int16_t raw_value) {
    return ((float)raw_value / 32767.0) * VREF;
}

// Function to convert voltage to pressure
float convert_to_pressure(float voltage) {
    return (voltage - OFFSET) / SENSITIVITY;
}

// Function to log pressure data
int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f kPa\n", buf, pressure);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t raw_value = read_adc();
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Convert to voltage
        float voltage = convert_to_voltage(raw_value);

        // Convert to pressure
        float pressure = convert_to_pressure(voltage);

        // Validate pressure range
        if (pressure >= MIN_PRESSURE && pressure <= MAX_PRESSURE) {
            // Log pressure data
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Error logging pressure data.\n");
            }
        } else {
            fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

