#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0 // Channel 0 for humidity, Channel 1 for temperature
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define SSMTP_COMMAND "ssmtp recipient@example.com" // Replace with your ssmtp command

// HIH-4602-A Transfer Function Constants
#define VOUT_OFFSET 0.824
#define VOUT_SCALE 0.0315
#define SUPPLY_VOLTAGE 5.0

// Thermistor Constants
#define BETA 3950.0
#define R0 10000.0 // 10kΩ
#define T0 298.15 // 25°C in Kelvin

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int initialize();
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void log_data(float humidity, float temperature);
void send_email_alert(float humidity);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3208_channel;
    float humidity_threshold;
    char *log_file;
    char *ssmtp_command;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3208_CHANNEL,
    HUMIDITY_THRESHOLD,
    LOG_FILE,
    SSMTP_COMMAND
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int humidity_adc = read_mcp3208(config.mcp3208_channel);
        int temperature_adc = read_mcp3208(config.mcp3208_channel + 1);

        if (humidity_adc < 0 || temperature_adc < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying.\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        float humidity = calculate_humidity(humidity_adc);
        float temperature = calculate_temperature(temperature_adc);

        log_data(humidity, temperature);

        if (humidity > config.humidity_threshold) {
            send_email_alert(humidity);
        }

        gpioDelay(5000); // Read every 5 seconds
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3208 channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3208 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract 12-bit ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

float calculate_humidity(int adc_value) {
    float voltage = (float)adc_value / 4095.0 * SUPPLY_VOLTAGE; // 2^12 - 1 = 4095
    float humidity = (voltage - VOUT_OFFSET) / VOUT_SCALE;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

float calculate_temperature(int adc_value) {
    float voltage = (float)adc_value / 4095.0 * SUPPLY_VOLTAGE;
    float resistance = (SUPPLY_VOLTAGE * 10.0 / voltage) - 10.0; // Assuming 10kOhm series resistor

    float temperature = BETA / (BETA / T0 + log(resistance / R0) / 298.15) - 273.15; // Temperature in Celsius
    return temperature;
}

void log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written to file immediately

    printf("%s,%.2f,%.2f\n", timestamp, humidity, temperature);
}

void send_email_alert(float humidity) {
    char command[256];
    snprintf(command, sizeof(command), "%s -s \"Humidity Alert\" \"Humidity exceeded %.2f%%\"", config.ssmtp_command, humidity);
    system(command);
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

