#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0
#define VREF 3.3f
#define TMP36_MIN_TEMP -40.0f
#define TMP36_MAX_TEMP 125.0f
#define LOG_FILE "temperature_log.csv"

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3208(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_celsius(float voltage);
int log_temperature(float temperature);
void signal_handler(int sig);
int gpio_init(void);
void gpio_set_cs(int value);
void gpio_release(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read from MCP3208
int read_mcp3208(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message for MCP3208 (single-ended, channel selection)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (12 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 4095.0f) * VREF;
}

// Function to convert voltage to Celsius
float voltage_to_celsius(float voltage) {
    return (voltage - 0.5f) / 0.01f;
}

// Function to log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Check if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// GPIO initialization function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, 8); // GPIO8 (CE0)
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "temperature_sensor", 1) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to set the CS line
void gpio_set_cs(int value) {
    gpiod_line_set_value(cs_line, value);
}

// Function to release GPIO resources
void gpio_release(void) {
    gpiod_line_release(cs_line);
    gpiod_chip_close(gpio_chip);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpio_release();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        close(spi_fd);
        gpio_release();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3208(MCP3208_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to Celsius
        float temperature = voltage_to_celsius(voltage);

        // Validate temperature range
        if (temperature < TMP36_MIN_TEMP || temperature > TMP36_MAX_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
            continue; // Skip logging
        }

        // Log temperature
        if (log_temperature(temperature) < 0) {
            fprintf(stderr, "Failed to log temperature\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up resources
    close(spi_fd);
    fclose(log_file);
    gpio_release();

    return 0;
}

