#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define ADC_VREF 3.3
#define ADXL335_SENSITIVITY 0.300 // 300 mV/g
#define ADXL335_ZERO_G_VOLTAGE 1.65
#define IMPACT_THRESHOLD 2.0
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_PERIOD (1000000 / SAMPLE_RATE) // microseconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int x;
    int y;
    int z;
} accelerometer_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
accelerometer_data_t read_accelerometer_data();
float calculate_acceleration_magnitude(accelerometer_data_t data);
int log_data(accelerometer_data_t data, float magnitude);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Ensure CS is initially high

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    data.x = read_mcp3008(0);
    data.y = read_mcp3008(1);
    data.z = read_mcp3008(2);

    if (data.x < 0 || data.x > 1023 || data.y < 0 || data.y > 1023 || data.z < 0 || data.z > 1023) {
        fprintf(stderr, "ADC value out of range\n");
        data.x = -1; // Indicate error
        data.y = -1;
        data.z = -1;
    }

    return data;
}

// Function to calculate acceleration magnitude
float calculate_acceleration_magnitude(accelerometer_data_t data) {
    if (data.x == -1 || data.y == -1 || data.z == -1) {
        return -1.0; // Indicate error
    }

    float x_g = (data.x * ADC_VREF / 1023.0 - ADXL335_ZERO_G_VOLTAGE) / ADXL335_SENSITIVITY;
    float y_g = (data.y * ADC_VREF / 1023.0 - ADXL335_ZERO_G_VOLTAGE) / ADXL335_SENSITIVITY;
    float z_g = (data.z * ADC_VREF / 1023.0 - ADXL335_ZERO_G_VOLTAGE) / ADXL335_SENSITIVITY;

    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Function to log data to file
int log_data(accelerometer_data_t data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (data.x == -1 || data.y == -1 || data.z == -1) {
        fprintf(log_file, "%s,ERROR,ERROR,ERROR,ERROR\n", timestamp);
        return -1;
    }

    fprintf(log_file, "%s,%d,%d,%d,%.3f\n", timestamp, data.x, data.y, data.z, magnitude);

    if (magnitude > IMPACT_THRESHOLD) {
        fprintf(log_file, "%s,IMPACT DETECTED\n", timestamp);
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Data logging started. Press Ctrl+C to stop.\n");

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        float magnitude = calculate_acceleration_magnitude(data);

        if (data.x != -1) {
            log_data(data, magnitude);
        }

        gpioDelay(SAMPLE_PERIOD); // Delay to achieve 100 Hz sampling rate
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

