#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1172_ADDR 0x49
#define SI1172_REG_COMMAND 0xC0
#define SI1172_REG_FIFO_DATA 0xC1
#define SI1172_REG_FIFO_DATA_HIGH 0xC2
#define SI1172_REG_FIFO_DATA_LOW 0xC3
#define SI1172_REG_FIFO_DATA_CONFIG 0xC4

#define SI1172_CMD_TRIGGER_MEASUREMENT 0x01

#define LOG_FILE "biometric_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int ir_value;
    int red_value;
    int error_flag;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from the Si1172 sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int result;

    // Trigger measurement
    result = i2cWriteByteData(i2c_handle, SI1172_REG_COMMAND, SI1172_CMD_TRIGGER_MEASUREMENT);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        data->error_flag = 1; // I2C write error
        return -1;
    }

    // Wait for a short period for the measurement to complete (adjust as needed)
    gpioDelay(10); // 10 milliseconds

    // Read FIFO data (IR and RED)
    result = i2cReadI2CBlockData(i2c_handle, SI1172_REG_FIFO_DATA, buf, 4);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        data->error_flag = 1; // I2C read error
        return -1;
    }

    // Combine high and low bytes for IR and RED values
    data->ir_value = (buf[0] << 8) | buf[1];
    data->red_value = (buf[2] << 8) | buf[3];
    data->error_flag = 0; // No error

    return 0;
}

// Log data to a CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.ir_value, data.red_value, data.error_flag);
    fflush(log_file); // Flush the buffer to ensure data is written immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,HR (bpm),SpO2 (%),Error Flag\n");
    }
    fflush(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
            // Log an error row with error flag set
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,0,0,%d\n", timestamp, sensor_data.error_flag);
            fflush(log_file);
        }

        gpioDelay(1000); // Sample once per second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

