#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x67
#define MEASUREMENT_COMMAND 0x6845
#define DATA_LENGTH 6
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients (replace with actual values from your sensor)
// These are placeholder values.  You MUST read the calibration data from the sensor.
float T_cal[3] = {25.0, 0.01, 0.0001}; // Example temperature calibration coefficients
float P_cal[3] = {100000.0, 10.0, 0.001}; // Example pressure calibration coefficients

// Function prototypes
int initialize_i2c();
int read_sensor_data(unsigned char *data);
float convert_temperature(unsigned char *data);
float convert_pressure(unsigned char *data);
int log_data(float temperature, float pressure);
void display_data(float temperature, float pressure);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Pressure (Pa)\n");
    }

    // Main loop
    while (!terminate) {
        unsigned char data[DATA_LENGTH];
        float temperature, pressure;

        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Convert data
            temperature = convert_temperature(data);
            pressure = convert_pressure(data);

            // Log data
            if (log_data(temperature, pressure) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Display data
            display_data(temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(unsigned char *data) {
    char cmd[2];
    cmd[0] = (MEASUREMENT_COMMAND >> 8) & 0xFF;
    cmd[1] = MEASUREMENT_COMMAND & 0xFF;

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write measurement command\n");
        return 1;
    }

    // Wait for conversion to complete (adjust as needed based on sensor datasheet)
    gpioDelay(10); // 10 ms delay

    if (i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH) != DATA_LENGTH) {
        fprintf(stderr, "Failed to read sensor data\n");
        return 1;
    }

    return 0;
}

// Convert raw temperature data to Celsius
float convert_temperature(unsigned char *data) {
    // Extract raw temperature data (adjust based on sensor datasheet)
    int32_t raw_temperature = (data[0] << 8) | data[1];

    // Apply calibration formula (replace with actual formula from datasheet)
    float temperature = T_cal[0] + T_cal[1] * raw_temperature + T_cal[2] * raw_temperature * raw_temperature;

    return temperature;
}

// Convert raw pressure data to Pascals
float convert_pressure(unsigned char *data) {
    // Extract raw pressure data (adjust based on sensor datasheet)
    int32_t raw_pressure = (data[2] << 8) | data[3];

    // Apply calibration formula (replace with actual formula from datasheet)
    float pressure = P_cal[0] + P_cal[1] * raw_pressure + P_cal[2] * raw_pressure * raw_pressure;

    return pressure;
}

// Log data to CSV file
int log_data(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Display data on console
void display_data(float temperature, float pressure) {
    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

