    while (!terminate) {
        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value >= 0) {
            // Log moisture reading
            if (log_moisture_reading(adc_value) != 0) {
                fprintf(stderr, "Error: Failed to log moisture reading\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Clean up resources
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");

    return 0;
}

