#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define FLAME_THRESHOLD 1.0
#define ADC_MAX_VALUE 1023
#define ADC_MIN_VALUE 0
#define MAX_ADC_RETRIES 3
#define SAMPLE_INTERVAL_MS 500

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float read_temperature();
float calculate_compensated_voltage(int raw_adc, float temperature);
int detect_flame(float compensated_voltage);
void control_buzzer(int flame_detected);
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int adc_value = -1;
    int retries = 0;

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    while (retries < MAX_ADC_RETRIES) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            if (adc_value >= ADC_MIN_VALUE && adc_value <= ADC_MAX_VALUE) {
                return adc_value;
            } else {
                fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
                log_data(-1, -1.0, -1.0, -1.0, -1); // Log error
            }
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d)\n", retries + 1);
            log_data(-1, -1.0, -1.0, -1.0, -1); // Log error
        }
        retries++;
        gpioDelay(10); // Small delay before retrying
    }

    fprintf(stderr, "Error: Max ADC retries reached\n");
    log_data(-1, -1.0, -1.0, -1.0, -1); // Log error
    return -1; // Indicate failure
}

// Function to read temperature from file
float read_temperature() {
    FILE *temp_file = fopen("ambient_temp.txt", "r");
    float temperature = 25.0;

    if (temp_file != NULL) {
        if (fscanf(temp_file, "%f", &temperature) != 1) {
            fprintf(stderr, "Error: Invalid temperature in file, using default 25.0\n");
            temperature = 25.0;
        }
        fclose(temp_file);
    } else {
        fprintf(stderr, "Warning: ambient_temp.txt not found, using default 25.0\n");
    }

    return temperature;
}

// Function to calculate compensated voltage
float calculate_compensated_voltage(int raw_adc, float temperature) {
    float voltage = (float)raw_adc / ADC_MAX_VALUE * 3.3; // Assuming 3.3V reference
    float compensated_voltage = voltage + (temperature - 25.0) * 0.001;
    return compensated_voltage;
}

// Function to detect flame
int detect_flame(float compensated_voltage) {
    return (compensated_voltage > FLAME_THRESHOLD) ? 1 : 0;
}

// Function to control the buzzer
void control_buzzer(int flame_detected) {
    gpioWrite(BUZZER_GPIO, flame_detected);
}

// Function to log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.1f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int raw_adc = read_adc(0);
        if (raw_adc == -1) {
            gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer on error
            gpioDelay(SAMPLE_INTERVAL_MS); // Wait before next sample
            continue; // Skip to the next iteration
        }

        // Read temperature
        float temperature = read_temperature();

        // Calculate compensated voltage
        float compensated_voltage = calculate_compensated_voltage(raw_adc, temperature);

        // Detect flame
        int flame_detected = detect_flame(compensated_voltage);

        // Control buzzer
        control_buzzer(flame_detected);

        // Log data
        float voltage = (float)raw_adc / ADC_MAX_VALUE * 3.3; // Calculate voltage for logging
        log_data(raw_adc, voltage, compensated_voltage, temperature, flame_detected);

        // Wait before next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

