    static char buf[30]; // Static buffer to hold the timestamp
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct);
    snprintf(buf + strlen(buf), sizeof(buf) - strlen(buf), ".%03ldZ", ts.tv_nsec / 1000000);
    return buf;
}

