    static int led_state = 0; // 0 = off, 1 = on

    if (percentage > WATER_LEVEL_THRESHOLD_HIGH && led_state == 0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        led_state = 1;
    } else if (percentage < WATER_LEVEL_THRESHOLD_LOW && led_state == 1) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
        led_state = 0;
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

