#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0

// Define sensor parameters
#define VOLTAGE_MIN 0.5
#define VOLTAGE_MAX 4.5
#define PRESSURE_MIN 10.0
#define PRESSURE_MAX 150.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int adc_channel;
    double voltage_min;
    double voltage_max;
    double pressure_min;
    double pressure_max;
} config_t;

// Function prototypes
int initialize_pigpio();
int initialize_spi(config_t *config);
int read_adc(int channel);
double adc_to_voltage(int adc_value);
double voltage_to_pressure(double voltage);
char* get_iso8601_timestamp();
void log_data(double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi(config_t *config) {
    spi_handle = spiOpen(config->spi_channel, config->spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Convert ADC value to voltage
double adc_to_voltage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0;
    }
    return (double)adc_value * 3.3 / 1023.0;
}

// Convert voltage to pressure
double voltage_to_pressure(double voltage) {
    return (voltage - 0.5) * (150.0 - 10.0) / (4.5 - 0.5) + 10.0;
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to console
void log_data(double pressure) {
    char *timestamp = get_iso8601_timestamp();
    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
    free(timestamp); // Free the allocated memory
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    config_t config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .adc_channel = ADC_CHANNEL,
        .voltage_min = VOLTAGE_MIN,
        .voltage_max = VOLTAGE_MAX,
        .pressure_min = PRESSURE_MIN,
        .pressure_max = PRESSURE_MAX
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi(&config) != 0) {
        cleanup();
        return 1;
    }

    printf("Pressure sensor data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        double voltage = adc_to_voltage(adc_value);
        if (voltage < 0) {
            fprintf(stderr, "Failed to convert ADC to voltage\n");
            continue;
        }

        double pressure = voltage_to_pressure(voltage);

        // Sensor absent detection
        if (voltage <= 0.1 || voltage >= 3.2) {
            fprintf(stderr, "Sensor absent or malfunctioning (Voltage: %.2f V)\n", voltage);
        } else {
            log_data(pressure);
        }

        sleep(1); // Read every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

