#define ERROR_ADC_VALUE -1

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *ce0_line, *sclk_line, *mosi_line, *miso_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(struct gpiod_line *sclk_line, struct gpiod_line *mosi_line, struct gpiod_line *miso_line, uint8_t data);
int read_adc_channel(struct gpiod_line *sclk_line, struct gpiod_line *mosi_line, struct gpiod_line *miso_line, int channel);
float convert_to_moisture_percentage(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);

// SPI transfer function
int spi_transfer(struct gpiod_line *sclk_line, struct gpiod_line *mosi_line, struct gpiod_line *miso_line, uint8_t data) {
    int i;
    int ret;

    for (i = 0; i < 8; i++) {
        // Set MOSI bit
        ret = gpiod_line_set_value(mosi_line, (data >> (7 - i)) & 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting MOSI line: %s\n", strerror(-ret));
            return -1;
        }

        // Clock high
        ret = gpiod_line_set_value(sclk_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting SCLK line high: %s\n", strerror(-ret));
            return -1;
        }

        // Read MISO bit
        ret = gpiod_line_get_value(miso_line);
        if (ret < 0) {
            fprintf(stderr, "Error getting MISO line value: %s\n", strerror(-ret));
            return -1;
        }

        // Clock low
        ret = gpiod_line_set_value(sclk_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting SCLK line low: %s\n", strerror(-ret));
            return -1;
        }
    }

    return 0;
}

// Read ADC channel function
int read_adc_channel(struct gpiod_line *sclk_line, struct gpiod_line *mosi_line, struct gpiod_line *miso_line, int channel) {
    uint8_t command[3];
    int adc_value;
    int ret;

    // Construct SPI command
    command[0] = 0x01; // Start bit
    command[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    command[2] = 0x00; // Don't care

    // Send command
    for (int i = 0; i < 3; i++) {
        ret = spi_transfer(sclk_line, mosi_line, miso_line, command[i]);
        if (ret < 0) {
            fprintf(stderr, "Error during SPI transfer: %s\n", strerror(-ret));
            return ERROR_ADC_VALUE;
        }
    }

    // Read ADC value
    adc_value = 0;
    for (int i = 0; i < 12; i++) {
        ret = gpiod_line_get_value(miso_line);
        if (ret < 0) {
            fprintf(stderr, "Error getting MISO line value: %s\n", strerror(-ret));
            return ERROR_ADC_VALUE;
        }
        adc_value = (adc_value << 1) | ret;
    }

    // Check for wiring faults
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Wiring fault detected! ADC value: %d\n", adc_value);
        return ERROR_ADC_VALUE;
    }

    return adc_value >> 2; // Right-shift to get 10-bit value
}

// Convert ADC value to moisture percentage function
float convert_to_moisture_percentage(int adc_value) {
    float moisture_percentage;

    if (adc_value < MIN_ADC_VALUE) {
        moisture_percentage = 0.0;
    } else if (adc_value > MAX_ADC_VALUE) {
        moisture_percentage = 100.0;
    } else {
        moisture_percentage = ((float)(adc_value - MIN_ADC_VALUE) / (MAX_ADC_VALUE - MIN_ADC_VALUE)) * 100.0;
    }

    return moisture_percentage;
}

// Log data function
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Moisture: %.2f%%\n", timestamp, moisture_percentage);
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup GPIO function
int setup_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
