#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define PUMP_GPIO 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE 20

// Data Structures
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

// Global Variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Circular Buffer
LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function Prototypes
int read_mcp3008(int channel);
void control_pump(int moisture_level);
void log_data(int moisture_level, int pump_state);
void print_log_buffer();
void signal_handler(int signal);
int initialize();
void cleanup();

// Function Implementations

// Reads the MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Controls the water pump based on moisture level
void control_pump(int moisture_level) {
    static int pump_state = 0; // 0 = off, 1 = on

    if (moisture_level < LOW_THRESHOLD && pump_state == 0) {
        if (gpioWrite(PUMP_GPIO, 1) != 0) {
            fprintf(stderr, "Error: Failed to turn pump ON\n");
        } else {
            pump_state = 1;
            printf("Pump turned ON\n");
        }
    } else if (moisture_level > HIGH_THRESHOLD && pump_state == 1) {
        if (gpioWrite(PUMP_GPIO, 0) != 0) {
            fprintf(stderr, "Error: Failed to turn pump OFF\n");
        } else {
            pump_state = 0;
            printf("Pump turned OFF\n");
        }
    }
}

// Logs data to the circular buffer
void log_data(int moisture_level, int pump_state) {
    time(&log_buffer[buffer_index].timestamp);
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Prints the contents of the log buffer
void print_log_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Correct order
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[index].timestamp));
        printf("[%d] Timestamp: %s, Moisture: %d, Pump: %s\n", index, timestamp_str, log_buffer[index].moisture_level, log_buffer[index].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Initializes the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleans up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    // Main loop
    while (program_running) {
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
        } else {
            control_pump(moisture_level);
            log_data(moisture_level, gpioRead(PUMP_GPIO));
            print_log_buffer();
        }

        gpioDelay(5000); // 5 seconds
    }

    cleanup();
    return 0;
}

