#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define PART_ID_REG 0xFF
#define MODE_CONFIG_REG 0x06
#define SPO2_CONFIG_REG 0x08
#define LED1_PA_REG 0x09
#define LED2_PA_REG 0x0A
#define FIFO_DATA_REG 0x07
#define FIFO_WR_PTR 0x04
#define FIFO_RD_PTR 0x05
#define FIFO_DATA_LEN 6 // 3 bytes Red, 3 bytes IR

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint32_t red;
    uint32_t ir;
} sensor_data_t;

// Function prototypes
int init_i2c();
int verify_sensor();
int init_sensor();
int read_fifo_data(sensor_data_t *data);
float calculate_spo2(uint32_t red, uint32_t ir);
int calculate_hr(uint32_t ir);
void log_data(float spo2, int hr);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify sensor presence
int verify_sensor() {
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x15) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }
    return 0;
}

// Initialize sensor
int init_sensor() {
    // Reset sensor
    if (i2cWriteByteData(i2c_handle, MODE_CONFIG_REG, 0x40) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Clear interrupts
    if (i2cWriteByteData(i2c_handle, 0x0C, 0x40) < 0) {
        fprintf(stderr, "Error clearing interrupts\n");
        return -1;
    }

    // Configure SpO2 mode
    if (i2cWriteByteData(i2c_handle, MODE_CONFIG_REG, 0x03) < 0) {
        fprintf(stderr, "Error setting SpO2 mode\n");
        return -1;
    }

    // Set SPO2 configuration
    if (i2cWriteByteData(i2c_handle, SPO2_CONFIG_REG, 0x27) < 0) {
        fprintf(stderr, "Error setting SPO2 config\n");
        return -1;
    }

    // Set LED pulse amplitudes
    if (i2cWriteByteData(i2c_handle, LED1_PA_REG, 0x24) < 0) {
        fprintf(stderr, "Error setting LED1 PA\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, LED2_PA_REG, 0x24) < 0) {
        fprintf(stderr, "Error setting LED2 PA\n");
        return -1;
    }

    return 0;
}

// Read FIFO data
int read_fifo_data(sensor_data_t *data) {
    uint8_t buffer[FIFO_DATA_LEN];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, FIFO_DATA_REG, (char *)buffer, FIFO_DATA_LEN);

    if (bytes_read != FIFO_DATA_LEN) {
        fprintf(stderr, "Error reading FIFO data: %d\n", bytes_read);
        return -1;
