#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define RELAY_GPIO 17
#define REED_SENSOR_GPIO 27
#define NUM_BASELINE_SAMPLES 10
#define BASELINE_SAMPLE_DELAY_MS 50
#define POLLING_INTERVAL_MS 200
#define RELAY_ACTIVATION_DURATION_S 3
#define THRESHOLD_PERCENTAGE 0.8
#define LOG_FILE "/var/log/door_events.log"

// ADS1115 Registers
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// ADS1115 Configuration Values
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start a single conversion
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0000  // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0060   // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0002  // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0004 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_ads1115(int16_t *value);
double calculate_threshold(int16_t *baseline_samples, int num_samples);
int control_relay(int state);
int read_reed_sensor();
int log_event(const char *message);
void signal_handler(int sig);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to initialize GPIO lines
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    relay_line = gpiod_chip_get_line(gpio_chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Error getting relay GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    reed_line = gpiod_chip_get_line(gpio_chip, REED_SENSOR_GPIO);
    if (!reed_line) {
        perror("Error getting reed sensor GPIO line");
        gpiod_line_release(relay_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "door_lock", 0) < 0) {
        perror("Error requesting relay GPIO line as output");
        gpiod_line_release(reed_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_input(reed_line, "reed_sensor") < 0) {
        perror("Error requesting reed sensor GPIO line as input");
        gpiod_line_release(relay_line);
        gpiod_line_release(reed_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to read from ADS1115
int read_ads1115(int16_t *value) {
    uint8_t write_buf[3];
    uint8_t read_buf[2];

    // Configure ADS1115 for single conversion
    write_buf[0] = ADS1115_REG_CONFIG;
    write_buf[1] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE) >> 8;
    write_buf[2] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE) & 0xFF;

    if (write(i2c_fd, write_buf, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read conversion result
    write_buf[0] = ADS1115_REG_CONVERT;
    if (write(i2c_fd, write_buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(i2c_fd, read_buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1];

    return 0;
}

// Function to calculate the threshold
double calculate_threshold(int16_t *baseline_samples, int num_samples) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += baseline_samples[i];
    }
    double average = sum / num_samples;
    return average * THRESHOLD_PERCENTAGE;
}

// Function to control the relay
int control_relay(int state) {
    int ret = gpiod_line_set_value(relay_line, state);
    if (ret < 0) {
        perror("Error setting relay state");
        return -1;
    }
    return 0;
}

// Function to read the reed sensor
int read_reed_sensor() {
    int value = gpiod_line_get_value(reed_line);
    if (value < 0) {
        perror("Error reading reed sensor value");
        return -1;
    }
    return value;
}

// Function to log events
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld.%03ld: %s\n", ts.tv_sec, ts.tv_nsec / 1000000, message);
    fclose(fp);
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (reed_line) {
        gpiod_line_release(reed_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        log_event("I2C initialization failed. Exiting.");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        log_event("GPIO initialization failed. Exiting.");
        cleanup();
        return 1;
    }

    // Take baseline samples
    int16_t baseline_samples[NUM_BASELINE_SAMPLES];
    for (int i = 0; i < NUM_BASELINE_SAMPLES; i++) {
        if (read_ads1115(&baseline_samples[i]) < 0) {
            log_event("Failed to read baseline sample. Continuing with previous samples.");
            break; // Continue with available samples
        }
        usleep(BASELINE_SAMPLE_DELAY_MS * 1000); // Delay between samples
    }

    // Calculate threshold
    double threshold = calculate_threshold(baseline_samples, NUM_BASELINE_SAMPLES);
    char threshold_message[100];
    snprintf(threshold_message, sizeof(threshold_message), "Calculated threshold: %.2f", threshold);
    log_event(threshold_message);

    // Main loop
    while (!terminate) {
        int16_t distance_reading;
        if (read_ads1115(&distance_reading) < 0) {
            log_event("Failed to read distance reading. Continuing.");
            usleep(POLLING_INTERVAL_MS * 1000);
            continue;
        }

        if (distance_reading < threshold) {
            log_event("Distance below threshold, activating relay.");
            if (control_relay(1) < 0) {
                log_event("Failed to activate relay.");
            } else {
                usleep(RELAY_ACTIVATION_DURATION_S * 1000000); // Activate for 3 seconds
                if (control_relay(0) < 0) {
                    log_event("Failed to deactivate relay.");
                } else {
                    int reed_value = read_reed_sensor();
                    if (reed_value < 0) {
                        log_event("Failed to read reed sensor.");
                    } else {
                        if (reed_value == 0) {
                            log_event("Door opened.");
                        } else {
                            log_event("Door not opened.");
                        }
                    }
                }
            }
        }

        usleep(POLLING_INTERVAL_MS * 1000); // Poll every 200ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

