#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Define GPIO pins for chip select lines
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

// SPI device path
#define SPI_DEVICE "/dev/spidev0.0"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int spi_fd = -1;
FILE *log_file = NULL;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *cs0_line = NULL;
struct gpiod_line *cs1_line = NULL;
struct gpiod_line *cs2_line = NULL;

// Function prototypes
int read_mcp3008(int chip_select_pin, int channel);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3);
void signal_handler(int signal);
int setup_gpio(int pin, struct gpiod_line **line);
int cleanup_gpio(struct gpiod_line *line);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int chip_select_pin, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];
    int ret;

    // Construct the SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    // Configure the SPI transfer
    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;
    transfer[0].delay_usecs = 0;

    // Assert chip select
    if (chip_select_pin == CS0_PIN) {
        if (gpiod_line_set_value(cs0_line, 0) < 0) {
            perror("Error setting CS0 low");
            return -1;
        }
    } else if (chip_select_pin == CS1_PIN) {
        if (gpiod_line_set_value(cs1_line, 0) < 0) {
            perror("Error setting CS1 low");
            return -1;
        }
    } else if (chip_select_pin == CS2_PIN) {
        if (gpiod_line_set_value(cs2_line, 0) < 0) {
            perror("Error setting CS2 low");
            return -1;
        }
    } else {
        fprintf(stderr, "Invalid chip select pin: %d\n", chip_select_pin);
        return -1;
    }

    // Perform the SPI transfer
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer);
    if (ret < 0) {
        perror("SPI transfer failed");
        // De-assert chip select in case of error
        if (chip_select_pin == CS0_PIN) gpiod_line_set_value(cs0_line, 1);
        if (chip_select_pin == CS1_PIN) gpiod_line_set_value(cs1_line, 1);
        if (chip_select_pin == CS2_PIN) gpiod_line_set_value(cs2_line, 1);
        return -1;
    }

    // De-assert chip select
    if (chip_select_pin == CS0_PIN) {
        if (gpiod_line_set_value(cs0_line, 1) < 0) {
            perror("Error setting CS0 high");
            return -1;
        }
    } else if (chip_select_pin == CS1_PIN) {
        if (gpiod_line_set_value(cs1_line, 1) < 0) {
            perror("Error setting CS1 high");
            return -1;
        }
    } else if (chip_select_pin == CS2_PIN) {
        if (gpiod_line_set_value(cs2_line, 1) < 0) {
            perror("Error setting CS2 high");
            return -1;
