#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define DRY_VALUE 200
#define WET_VALUE 800
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_INTERVAL 60

// Global variables
int spi_handle;
FILE *log_file;
int threshold = DEFAULT_THRESHOLD;
int duration_seconds = DEFAULT_DURATION;
int sleep_interval = DEFAULT_INTERVAL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int state);
void log_data(int adc_value, float moisture_percentage, int pump_state);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int retries = 3;
    while (retries > 0) {
        if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI read failed (channel %d), retrying...\n", channel);
            log_data(-1, -1.0, -1); // Log error
            gpioDelay(1000); // Wait 1ms before retry
            retries--;
        }
    }

    fprintf(stderr, "Error: SPI read failed (channel %d) after multiple retries.\n", channel);
    log_data(-1, -1.0, -1); // Log error
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    float percentage = (float)(adc_value - DRY_VALUE) / (float)(WET_VALUE - DRY_VALUE) * 100.0;

    // Clamp to 0-100%
    if (percentage < 0.0) {
        percentage = 0.0;
    } else if (percentage > 100.0) {
        percentage = 100.0;
    }

    return percentage;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Function to log data to file
void log_data(int adc_value, float moisture_percentage, int pump_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, ADC: %d, Moisture: %.2f%%, Pump: %s\n",
                timestamp, adc_value, moisture_percentage, pump_state ? "ON" : "OFF");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Turn off the pump
    control_pump(0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration_seconds = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Irrigation system started. Threshold: %d%%, Duration: %d s, Interval: %d s\n", threshold, duration_seconds, sleep_interval);

    // Main loop
    while (!terminate) {
        // Read soil moisture sensor
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC value, skipping irrigation cycle.\n");
            gpioDelay(sleep_interval * 1000); // Sleep for the interval
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);

        // Log data
        log_data(adc_value, moisture_percentage, -1); // -1 indicates pump state is unknown

        // Check if irrigation is needed
        if (moisture_percentage < threshold) {
            printf("Moisture level below threshold (%.2f%% < %d%%). Activating pump for %d seconds.\n", moisture_percentage, threshold, duration_seconds);
            log_data(adc_value, moisture_percentage, 1); // Log pump activation
            control_pump(1); // Turn on pump
            gpioDelay(duration_seconds * 1000); // Wait for specified duration
            control_pump(0); // Turn off pump
            log_data(adc_value, moisture_percentage, 0); // Log pump deactivation
            printf("Pump deactivated.\n");
        }

        // Sleep for the specified interval
        gpioDelay(sleep_interval * 1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

