        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC value, skipping irrigation cycle.\n");
            gpioDelay(sleep_interval * 1000); // Sleep for the interval
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);

        // Log data
        log_data(adc_value, moisture_percentage, -1); // -1 indicates pump state is unknown

        // Check if irrigation is needed
        if (moisture_percentage < threshold) {
            printf("Moisture level below threshold (%.2f%% < %d%%). Activating pump for %d seconds.\n", moisture_percentage, threshold, duration_seconds);
            log_data(adc_value, moisture_percentage, 1); // Log pump activation
            control_pump(1); // Turn on pump
            gpioDelay(duration_seconds * 1000); // Wait for specified duration
            control_pump(0); // Turn off pump
            log_data(adc_value, moisture_percentage, 0); // Log pump deactivation
            printf("Pump deactivated.\n");
        }

        // Sleep for the specified interval
        gpioDelay(sleep_interval * 1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

