#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define EMA_ALPHA 0.1
#define THRESHOLD_MARGIN 0.2
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "/var/log/sound_events.log"
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    double ema_alpha;
    double threshold_margin;
    int sample_interval_ms;
    char *log_file;
    char *server_ip;
    int server_port;
} Config;

// Function prototypes
int init_pigpio();
int init_spi();
int read_mcp3008(int channel);
double calculate_ema(double new_value, double current_ema);
int detect_peak(int raw_value, double ema_value, double threshold_margin);
int log_event(int raw_value, double ema_value);
int send_data(int raw_value, double ema_value);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI communication
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Calculate Exponential Moving Average (EMA)
double calculate_ema(double new_value, double current_ema) {
    return EMA_ALPHA * new_value + (1 - EMA_ALPHA) * current_ema;
}

// Detect peak based on threshold margin
int detect_peak(int raw_value, double ema_value, double threshold_margin) {
    return raw_value > ema_value * (1 + threshold_margin);
}

// Log event to file
int log_event(int raw_value, double ema_value) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, Raw: %d, EMA: %.2f\n", buf, raw_value, ema_value);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Send data to server
int send_data(int raw_value, double ema_value) {
    int sock = 0;
    struct sockaddr_in serv_addr;
    char buffer[1024] = {0};

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation error");
        return -1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(SERVER_PORT);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, SERVER_IP, &serv_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Connection Failed");
        close(sock);
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "%d,%.2f", raw_value, ema_value);
    send(sock, buffer, strlen(buffer), 0);
    close(sock);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    Config config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .ema_alpha = EMA_ALPHA,
        .threshold_margin = THRESHOLD_MARGIN,
        .sample_interval_ms = SAMPLE_INTERVAL_MS,
        .log_file = LOG_FILE,
        .server_ip = SERVER_IP,
        .server_port = SERVER_PORT
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", config.log_file);
        cleanup();
        return 1;
    }

    double ema_value = 0.0; // Initial EMA value

    // Main loop
    while (!terminate) {
        int raw_value = read_mcp3008(0); // Read from channel 0
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        ema_value = calculate_ema(raw_value, ema_value);

        if (detect_peak(raw_value, ema_value, config.threshold_margin)) {
            printf("Peak detected! Raw: %d, EMA: %.2f\n", raw_value, ema_value);
            log_event(raw_value, ema_value);
            send_data(raw_value, ema_value);
        }

        gpioDelay(config.sample_interval_ms * 1000); // Delay for 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

