#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Dummy read to discard the previous conversion result
        unsigned char dummy_data[1];
        if (read(i2c_fd, dummy_data, 1) != 1) {
            perror("Error during dummy read");
            close(i2c_fd);
            return 1;
        }

        // Write the control byte (0x40 for AIN0, single-ended)
        unsigned char control_byte = 0x40;
        if (write(i2c_fd, &control_byte, 1) != 1) {
            perror("Error writing control byte");
            close(i2c_fd);
            return 1;
        }

        // Read the analog value from AIN0
        unsigned char analog_value[1];
        if (read(i2c_fd, analog_value, 1) != 1) {
            perror("Error reading analog value");
            close(i2c_fd);
            return 1;
        }

        // Print the analog value
        printf("Analog Value: %d\n", analog_value[0]);

        // Wait for 100 ms
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // This point should not be reached due to the infinite loop
    close(i2c_fd);
    return 0;
}

