#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define AIN0 0
#define GPIO_SHUTDOWN 27
#define THRESHOLD_GAUSS 500.0
#define BUFFER_SIZE 10
#define VCC 3.3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_pigpio();
int init_i2c();
int16_t read_adc(int channel);
float voltage_to_gauss(int16_t raw_value);
void buffer_init(CircularBuffer *cb);
void buffer_add(CircularBuffer *cb, float value);
float buffer_average(CircularBuffer *cb);
void shutdown_gpio();
void signal_handler(int signal);
void cleanup();

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from specified channel
int16_t read_adc(int channel) {
    uint8_t config[3];
    int16_t raw_value;

    // Configure ADS1115 for single-ended read on the specified channel
    config[0] = 0x01; // Configuration register address
    config[1] = 0x44 | (channel << 1); // Single-ended mode, channel selection
    config[2] = 0x83; // 4.096V, 128 SPS, disable comparator

    if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
        syslog(LOG_ERR, "Failed to write configuration to ADS1115");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    config[0] = 0x00; // Conversion register address
    if (i2cWriteDevice(i2c_handle, (char *)config, 1) != 0) {
        syslog(LOG_ERR, "Failed to write register address for reading");
        return -1;
    }

    char buffer[2];
    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        syslog(LOG_ERR, "Failed to read ADC value");
        return -1;
    }

    raw_value = (buffer[0] << 8) | buffer[1];

    return raw_value;
}

// Convert raw ADC value to voltage
float voltage_to_gauss(int16_t raw_value) {
    float voltage = (float)raw_value * VCC / 32768.0; // Assuming 16-bit ADC
    float gauss = (voltage - 2.5) / 0.0014; // SS49E transfer function
    return gauss;
}

// Initialize circular buffer
void buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        cb->buffer[i] = 0.0;
    }
}

// Add value to circular buffer
void buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average of values in circular buffer
float buffer_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Shutdown GPIO
void shutdown_gpio() {
    gpioWrite(GPIO_SHUTDOWN, 1); // Set GPIO HIGH
    syslog(LOG_INFO, "Motor shutdown initiated");
}

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(GPIO_SHUTDOWN, 0); // Set GPIO LOW
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure GPIO for shutdown
    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0); // Set GPIO LOW initially

    // Initialize circular buffer
    CircularBuffer gauss_buffer;
    buffer_init(&gauss_buffer);

