    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure GPIO for shutdown
    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0); // Set GPIO LOW initially

    // Initialize circular buffer
    CircularBuffer gauss_buffer;
    buffer_init(&gauss_buffer);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t raw_value = read_adc(AIN0);
        if (raw_value < 0) {
            syslog(LOG_WARNING, "Failed to read ADC value, skipping sample");
            gpioDelay(1000000); // 1 second delay
            continue;
        }

        // Convert to Gauss
        float gauss = voltage_to_gauss(raw_value);

        // Add to circular buffer
        buffer_add(&gauss_buffer, gauss);

        // Calculate rolling average
        float average_gauss = buffer_average(&gauss_buffer);

        // Log data
        syslog(LOG_INFO, "Raw ADC: %d, Voltage: %.3f V, Gauss: %.3f, Average Gauss: %.3f",
               raw_value, (float)raw_value * VCC / 32768.0, gauss, average_gauss);

