    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("watering_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring and watering system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read soil moisture level
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            log_event(-1); // Log error
            break; // Exit loop on error
        }

        // Log the moisture level
        log_event(moisture_level);

        // Check if watering is needed
        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Activating pump.\n");
            control_pump(1); // Turn pump ON
            gpioDelay(WATERING_DURATION * 1000); // Water for specified duration
            control_pump(0); // Turn pump OFF
            printf("Pump deactivated.\n");
        }

        // Wait before next reading
        gpioDelay(READ_INTERVAL * 1000);
    }

    // Cleanup
    printf("Cleaning up resources...\n");
    control_pump(0); // Ensure pump is OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

