#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_adc(int handle);
double adc_to_voltage(int adc_value);
double voltage_to_gauss(double voltage);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Structure for program configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_gpio;
    double threshold;
} program_config;

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int read_adc(int handle) {
    char config[3];
    int16_t adc_value;

    // Configure ADS1115 for single-ended AIN0, PGA=4.096V, single conversion mode
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0xC2; // 0b11000010: OS=1, MUX=100 (AIN0), PGA=011 (4.096V), MODE=1 (Single-shot)
    config[2] = 0x83; // 0b10000011: DR=100 (128 SPS), COMP_MODE=0 (Traditional), COMP_POL=0 (Active low), COMP_LAT=0 (Non-latching), COMP_QUE=011 (Disable comparator)

    if (i2cWriteDevice(handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write configuration to ADS1115\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10); // Wait 10ms

    // Read the conversion result
    char read_buffer[2];
    if (i2cReadDevice(handle, read_buffer, 2) != 2) {
        fprintf(stderr, "Failed to read ADC value from ADS1115\n");
        return -1;
    }

    adc_value = (read_buffer[0] << 8) | read_buffer[1];
    return adc_value;
}

// Convert ADC value to voltage
double adc_to_voltage(int adc_value) {
    // ADS1115 is a 16-bit ADC, but the sign bit is only 15 bits.
    // The remaining bit is for the sign.
    int16_t signed_adc_value = (int16_t)adc_value; // Cast to signed 16-bit integer

    // The full-scale range of the ADC is 4.096V with PGA=4.096V
    // The resolution is 4.096V / 2^15 = 0.000125 V/LSB
    double voltage = signed_adc_value * 0.000125;
    return voltage;
}

// Convert voltage to Gauss
double voltage_to_gauss(double voltage) {
    // Zero-gauss output is approximately 1.65V
    // Sensitivity is approximately 1.0 mV/Gauss = 0.001 V/Gauss
    double gauss = (voltage - 1.65) / 0.001;
    return gauss;
}

// Control the LED state
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize program configuration
    program_config config = {
        .i2c_bus = I2C_BUS,
        .ads1115_address = ADS1115_ADDR,
        .led_gpio = LED_GPIO,
        .threshold = threshold
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(i2c_handle);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC value to voltage
        double voltage = adc_to_voltage(adc_value);

        // Convert voltage to Gauss
        double gauss = voltage_to_gauss(voltage);

        // Print magnetic field strength
        printf("Magnetic Field Strength: %.2f Gauss\n", gauss);

        // Check if threshold is exceeded
        if (fabs(gauss) > threshold) {
            // Blink LED for 1 second
            for (int i = 0; i < 10; i++) {
                control_led(1);
                gpioDelay(50);
                control_led(0);
                gpioDelay(50);
            }
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup resources
    cleanup();

    return 0;
}

