#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <time.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_HOST "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "soil_moisture_sensor"
#define MQTT_TOPIC_MOISTURE "soil_moisture"
#define MQTT_TOPIC_CONTROL "pump_control"
#define ADC_MAX_VALUE 1023 // MCP3008 is 10-bit ADC

// Global variables
int spi_handle;
struct mosquitto *mqtt_client;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_relay(int state);
void publish_moisture(float moisture);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void connect_callback(struct mosquitto *mosq, void *userdata, int result);
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void signal_handler(int sig);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0; // Indicate error
    }

    // Linear mapping: 0 ADC = 100% moisture, ADC_MAX_VALUE = 0% moisture
    float moisture = 100.0 - ((float)adc_value / ADC_MAX_VALUE) * 100.0;
    return moisture;
}

// Function to control the relay (and thus the water pump)
void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", RELAY_GPIO);
    } else {
        syslog(LOG_INFO, "Relay set to %s", state ? "ON" : "OFF");
    }
}

// Function to publish moisture reading to MQTT
void publish_moisture(float moisture) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", moisture);

    int ret = mosquitto_publish(mqtt_client, NULL, MQTT_TOPIC_MOISTURE, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
    } else {
        syslog(LOG_INFO, "Published moisture: %s to topic %s", payload, MQTT_TOPIC_MOISTURE);
    }
}

// MQTT message callback function
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, (char *)message->payload);

        if (strcmp(message->topic, MQTT_TOPIC_CONTROL) == 0) {
            if (strcmp((char *)message->payload, "pump_on") == 0) {
                control_relay(1); // Turn pump ON
            } else if (strcmp((char *)message->payload, "pump_off") == 0) {
                control_relay(0); // Turn pump OFF
            } else {
                syslog(LOG_WARNING, "Invalid command received: %s", (char *)message->payload);
            }
        }
    }
}

// MQTT connect callback function
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);
        int ret = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_CONTROL, 0);
        if (ret != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT subscribe error: %s", mosquitto_strerror(ret));
        }
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_strerror(result));
    }
}

// MQTT disconnect callback function
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "MQTT disconnected with code %d", rc);
}

// Signal handler for clean shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("soil_moisture_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0); // Ensure relay is initially OFF

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mqtt_client = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mqtt_client) {
        syslog(LOG_ERR, "MQTT client creation failed");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mqtt_client, connect_callback);
    mosquitto_disconnect_callback_set(mqtt_client, disconnect_callback);
    mosquitto_message_callback_set(mqtt_client, message_callback);

    int ret = mosquitto_connect(mqtt_client, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mqtt_client);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int relay_state = 0; // 0 = OFF, 1 = ON
    float moisture;

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calculate moisture percentage
        moisture = calculate_moisture(adc_value);
        if (moisture < 0.0) {
            syslog(LOG_ERR, "Failed to calculate moisture");
            sleep(1); // Wait before retrying
            continue;
        }

        // Publish moisture reading
        publish_moisture(moisture);

        // Hysteresis control
        if (moisture < MOISTURE_THRESHOLD_LOW && relay_state == 0) {
            control_relay(1);
            relay_state = 1;
        } else if (moisture > MOISTURE_THRESHOLD_HIGH && relay_state == 1) {
            control_relay(0);
            relay_state = 0;
        }

        sleep(60); // Wait 60 seconds
    }

    // Clean up resources before exiting
    mosquitto_loop_stop(mqtt_client, false);
    mosquitto_disconnect(mqtt_client);
