#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define NUM_CHANNELS 3
#define SLEEP_SECONDS 5

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi_channel();
int read_mcp3008(int channel);
float convert_to_voltage(int raw_value);
int log_data(float channel0_voltage, float channel1_voltage, float channel2_voltage);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float channel0_voltage;
    float channel1_voltage;
    float channel2_voltage;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open SPI channel
    if (open_spi_channel() != 0) {
        fprintf(stderr, "Failed to open SPI channel. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open data file
    fp = fopen("sensor_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open sensor_data.csv. Exiting.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC values from each channel
        int raw_channel0 = read_mcp3008(0);
        int raw_channel1 = read_mcp3008(1);
        int raw_channel2 = read_mcp3008(2);

        // Convert raw values to voltages
        float channel0_voltage = convert_to_voltage(raw_channel0);
        float channel1_voltage = convert_to_voltage(raw_channel1);
        float channel2_voltage = convert_to_voltage(raw_channel2);

        // Log the data
        if (log_data(channel0_voltage, channel1_voltage, channel2_voltage) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Sleep for 5 seconds
        gpioSleep(PI_TIME_RELATIVE, SLEEP_SECONDS, 0);
    }

    // Clean up resources
    fclose(fp);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open SPI channel
int open_spi_channel() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert raw ADC value to voltage
float convert_to_voltage(int raw_value) {
    return ((float)raw_value / 1023.0) * VREF;
}

// Log data to file
int log_data(float channel0_voltage, float channel1_voltage, float channel2_voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, channel0_voltage, channel1_voltage, channel2_voltage);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating program.\n", signal);
    terminate = 1;
}

