#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_MOTOR1 17
#define GPIO_MOTOR2 27
#define PWM_FREQUENCY 100
#define NOISE_THRESHOLD 500
#define SAMPLE_INTERVAL_MS 10

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int read_adc(int spi_fd, int channel);
void set_motor_pwm(int gpio, int duty_cycle);
void log_event(int adc_value, int duty_cycle);
void signal_handler(int signal);

// SPI initialization function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Configure SPI max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// ADC read function
int read_adc(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Motor control function
void set_motor_pwm(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Logging function
void log_event(int adc_value, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - ADC Value: %d, Duty Cycle: %d\n", timestamp, adc_value, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_MOTOR1, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR2, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_MOTOR1, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_MOTOR2, PWM_FREQUENCY);

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration motor control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping iteration\n");
            usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 10ms
            continue;
        }

        // Check noise threshold
        if (adc_value > NOISE_THRESHOLD) {
            // Calculate duty cycle
            int duty_cycle = (int)(((float)(adc_value - NOISE_THRESHOLD) / (1023.0 - NOISE_THRESHOLD)) * 255.0);

            // Set motor PWM
            set_motor_pwm(GPIO_MOTOR1, duty_cycle);
            set_motor_pwm(GPIO_MOTOR2, duty_cycle);

            // Log event
            log_event(adc_value, duty_cycle);
        } else {
            // Turn off motors
            set_motor_pwm(GPIO_MOTOR1, 0);
            set_motor_pwm(GPIO_MOTOR2, 0);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 10ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_motor_pwm(GPIO_MOTOR1, 0);
    set_motor_pwm(GPIO_MOTOR2, 0);
    close(spi_fd);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

