    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int pump_state = 0; // 0 = OFF, 1 = ON

    // Main loop
    while (!terminate) {
        // Read ADC value from MCP3008 channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);
        if (moisture_percentage < 0.0) {
            fprintf(stderr, "Error: Failed to calculate moisture percentage\n");
            continue; // Skip to the next iteration
        }

        // Control the pump based on moisture level
        if (moisture_percentage < MOISTURE_THRESHOLD && pump_state == 0) {
            control_pump(1); // Turn pump ON
            pump_state = 1;
            printf("Moisture below threshold, turning pump ON\n");
        } else if (moisture_percentage >= MOISTURE_THRESHOLD && pump_state == 1) {
            control_pump(0); // Turn pump OFF
            pump_state = 0;
            printf("Moisture above threshold, turning pump OFF\n");
        }

        // Log the data
        log_data(moisture_percentage, pump_state);

        // Wait for 60 seconds
        gpioDelay(60000); // 60 seconds = 60000 ms
    }

    // Clean up resources before exiting
    control_pump(0); // Ensure pump is OFF
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

