#include <signal.h>
#include <string.h>

// Define constants
#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"
#define NUM_SENSORS 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_average(int *values, int num_values);
int map_to_valve_position(float average);
void set_valve_position(int position);
void log_data(int *sensor_values, float average, int valve_position);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate the average of sensor readings
float calculate_average(int *values, int num_values) {
    float sum = 0.0;
    int valid_count = 0;

    for (int i = 0; i < num_values; i++) {
        if (values[i] >= 0) { // Only include valid readings
            sum += values[i];
            valid_count++;
        }
    }

    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return 0.0; // Return 0 if no valid readings
    }
}

// Function to map the average sensor reading to a valve position (0-100%)
int map_to_valve_position(float average) {
    // Invert the average reading (dry soil = high opening, wet soil = low opening)
    float inverted_average = 1023.0 - average;

    // Scale the inverted average to a percentage (0-100)
    float percentage = (inverted_average / 1023.0) * 100.0;

    // Clamp the percentage to the range 0-100
    if (percentage < 0.0) {
        percentage = 0.0;
    } else if (percentage > 100.0) {
        percentage = 100.0;
    }

    return (int)percentage;
}

// Function to set the valve position using PWM
void set_valve_position(int position) {
    if (position < 0 || position > 100) {
        fprintf(stderr, "Error: Invalid valve position: %d\n", position);
        return;
    }

    // Set PWM duty cycle
    gpioPWM(VALVE_GPIO, position);
}

