    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor 0: %d, Sensor 1: %d, Sensor 2: %d, Average: %.2f, Valve Position: %d\n",
            timestamp, sensor_values[0], sensor_values[1], sensor_values[2], average, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for PWM
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor_values[NUM_SENSORS];
    float average;
    int valve_position;

    // Main loop
    while (!terminate) {
        // Read sensor values
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
        }

        // Calculate average
        average = calculate_average(sensor_values, NUM_SENSORS);

        // Map to valve position
        valve_position = map_to_valve_position(average);

        // Set valve position
        set_valve_position(valve_position);

        // Log data
        log_data(sensor_values, average, valve_position);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Graceful shutdown
    printf("Shutting down...\n");
    set_valve_position(0); // Close the valve
    spiClose(spi_handle); // Close SPI
    fclose(log_file); // Close log file
    gpioTerminate(); // Terminate pigpio

    return 0;
}

