#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define MAX_RETRIES 5
#define RETRY_DELAY_BASE 100 // milliseconds
#define LOG_FILE "soil_data.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int signal);
int initialize_spi();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int adc_value;
    int retries = 0;
    int delay = RETRY_DELAY_BASE;

    // Construct SPI command
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value (10 bits)
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

            // Validate ADC value
            if (adc_value >= 0 && adc_value <= 1023) {
                return adc_value;
            } else {
                fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
                return -1; // Indicate an error
            }
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d). Retrying in %d ms...\n", retries + 1, delay);
            gpioDelay(delay * 1000); // pigpioDelay takes microseconds
            delay *= 2; // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate an error
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            log_data(moisture_percentage);
            printf("Moisture: %.2f%%\n", moisture_percentage);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        gpioDelay(5000000); // 5 seconds (microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

