#define ULTRASONIC_TIMEOUT 50000 // 50ms

// Global variables
volatile sig_atomic_t program_running = 1;
float distance_min = 0.0;
float distance_max = 100.0;
int ldr_min = 0;
int ldr_max = 1023;

// Function prototypes
float read_distance();
int read_ldr();
float map_distance_to_frequency(float distance);
int map_ldr_to_duty_cycle(int ldr_value);
void set_pwm_frequency(float frequency);
void set_pwm_duty_cycle(int duty_cycle);
void signal_handler(int signal);
int load_calibration_data();
int save_calibration_data();

// Function to read distance from ultrasonic sensor
float read_distance() {
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < ULTRASONIC_TIMEOUT) {
        count++;
        gpioDelay(1); // Check every microsecond
    }
    if (count >= ULTRASONIC_TIMEOUT) {
        fprintf(stderr, "Error: Ultrasonic sensor timeout (echo high).\n");
        return -1.0; // Indicate error
    }
    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < ULTRASONIC_TIMEOUT) {
        count++;
        gpioDelay(1);
    }
    if (count >= ULTRASONIC_TIMEOUT) {
        fprintf(stderr, "Error: Ultrasonic sensor timeout (echo low).\n");
        return -1.0; // Indicate error
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (float)diff / 2.0 / 29.1; // Speed of sound: 29.1 us/cm

    return distance;
}

// Function to read LDR value from MCP3008 ADC
int read_ldr() {
    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = 0x80; // Single-ended mode, channel 0
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    if (distance < 0) return MIN_FREQUENCY; // Handle error case
    if (distance > distance_max) distance = distance_max;
    if (distance < distance_min) distance = distance_min;

    float frequency_range = MAX_FREQUENCY - MIN_FREQUENCY;
    float distance_range = distance_max - distance_min;

    float frequency = MIN_FREQUENCY + (distance - distance_min) * (frequency_range / distance_range);
    return frequency;
}

