    int duty_cycle_range = 1000000; // Full range for 1MHz PWM
    int ldr_range = ldr_max - ldr_min;

    int duty_cycle = (int)(((float)(ldr_value - ldr_min) / ldr_range) * duty_cycle_range);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > duty_cycle_range) duty_cycle = duty_cycle_range;
    return duty_cycle;
}

