    fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open PWM duty cycle file.\n");
        return;
    }
    fprintf(fp, "%d", duty_cycle);
    fclose(fp);

    sprintf(buffer, "/sys/class/pwm/pwmchip0/pwm%d/enable", PWM_CHANNEL);
    fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open PWM enable file.\n");
        return;
    }
    fprintf(fp, "1");
    fclose(fp);
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    char buffer[50];
    sprintf(buffer, "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", PWM_CHANNEL);
    FILE *fp = fopen(buffer, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open PWM duty cycle file.\n");
        return;
    }
    fprintf(fp, "%d", duty_cycle);
    fclose(fp);
}

// Signal handler for Ctrl+C
