#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1

// Speed limits
#define MIN_SPEED 50
#define MAX_SPEED 255

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float map_potentiometer_to_speed(int pot_value);
void set_motor_speed(int motor_enable_pin, int motor_direction_pin, int speed);
void motion_profile(int motor1_enable_pin, int motor1_direction_pin, int motor2_enable_pin, int motor2_direction_pin, float speed_factor1, float speed_factor2);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to map potentiometer value to speed factor (logarithmic)
float map_potentiometer_to_speed(int pot_value) {
    if (pot_value < 0 || pot_value > 1023) {
        fprintf(stderr, "Error: Invalid potentiometer value: %d\n", pot_value);
        return 0.0;
    }

    // Logarithmic mapping
    float normalized_value = (float)pot_value / 1023.0;
    float log_value = log10(1.0 + 9.0 * normalized_value) / log10(10.0); // Map 0-1 to 0-1 logarithmically
    return log_value;
}

// Function to set motor speed and direction
void set_motor_speed(int motor_enable_pin, int motor_direction_pin, int speed) {
    if (speed < 0 || speed > 255) {
        fprintf(stderr, "Error: Invalid motor speed: %d\n", speed);
        return;
    }

    gpioPWM(motor_enable_pin, speed);

    // Set direction (example: HIGH for forward, LOW for backward)
    gpioWrite(motor_direction_pin, (speed > 0) ? 1 : 0); // Example: Forward if speed > 0
}

// Function to implement motion profile
void motion_profile(int motor1_enable_pin, int motor1_direction_pin, int motor2_enable_pin, int motor2_direction_pin, float speed_factor1, float speed_factor2) {
    int speed1, speed2;
    int i;

    // Acceleration
    for (i = MIN_SPEED; i <= MAX_SPEED; i++) {
        speed1 = i * speed_factor1;
        speed2 = i * speed_factor2;
        set_motor_speed(motor1_enable_pin, motor1_direction_pin, speed1);
        set_motor_speed(motor2_enable_pin, motor2_direction_pin, speed2);
        gpioDelay(10000); // 10ms delay
    }

    // Constant speed
    gpioDelay(2000000); // 2 seconds

    // Deceleration
    for (i = MAX_SPEED; i >= MIN_SPEED; i--) {
        speed1 = i * speed_factor1;
        speed2 = i * speed_factor2;
        set_motor_speed(motor1_enable_pin, motor1_direction_pin, speed1);
        set_motor_speed(motor2_enable_pin, motor2_direction_pin, speed2);
        gpioDelay(10000); // 10ms delay
    }

    // Pause
    gpioDelay(5000000); // 5 seconds
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int pot_value1, pot_value2;
    float speed_factor1, speed_factor2;

    // Main loop
    while (!terminate) {
        // Read potentiometer values
        pot_value1 = read_mcp3008(MCP3008_CHANNEL_0);
        pot_value2 = read_mcp3008(MCP3008_CHANNEL_1);

        if (pot_value1 == -1 || pot_value2 == -1) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            break; // Exit loop on error
        }

        // Map potentiometer values to speed factors
        speed_factor1 = map_potentiometer_to_speed(pot_value1);
        speed_factor2 = map_potentiometer_to_speed(pot_value2);

        // Run motion profile
        motion_profile(MOTOR1_ENABLE, MOTOR1_DIRECTION, MOTOR2_ENABLE, MOTOR2_DIRECTION, speed_factor1, speed_factor2);

        // Reverse directions (example: toggle direction pins)
        gpioWrite(MOTOR1_DIRECTION, !gpioRead(MOTOR1_DIRECTION));
        gpioWrite(MOTOR2_DIRECTION, !gpioRead(MOTOR2_DIRECTION));

        // Small delay to avoid busy-waiting
        gpioDelay(100000); // 100ms
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

