#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define constants
#define CALIBRATION_TIME 5 // seconds
#define THRESHOLD_MULTIPLIER 1.1 // 10% above average
#define DEBOUNCE_DELAY 10 // milliseconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_average(int *samples, int num_samples);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate the average of an array of integers
double calculate_average(int *samples, int num_samples) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += samples[i];
    }
    return sum / num_samples;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Calibrate ambient noise level
    int num_calibration_samples = 100; // 100 samples over 5 seconds
    int calibration_samples[num_calibration_samples];
    printf("Calibrating ambient noise level for %d seconds...\n", CALIBRATION_TIME);
    for (int i = 0; i < num_calibration_samples; i++) {
        calibration_samples[i] = read_mcp3008(0);
        if (calibration_samples[i] == -1) {
            fprintf(stderr, "Error: Failed to read calibration sample\n");
            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }
        gpioDelay(50000); // 50ms delay (50000 microseconds)
    }
    double average_ambient_level = calculate_average(calibration_samples, num_calibration_samples);
    double threshold = average_ambient_level * THRESHOLD_MULTIPLIER;
    printf("Calibration complete. Average ambient level: %.2f, Threshold: %.2f\n", average_ambient_level, threshold);

    // Main loop
    int led_state = 0; // 0 = off, 1 = on
    int last_led_change = 0; // Timestamp of last LED change
    while (!terminate) {
        int sound_level = read_mcp3008(0);
        if (sound_level == -1) {
            fprintf(stderr, "Error: Failed to read sound level\n");
            break; // Exit loop on error
        }

        // Check if sound level exceeds threshold
        if (sound_level > threshold) {
            // Debounce LED activation
            int current_time = gpioTick();
            if (led_state == 0 && (current_time - last_led_change) > (DEBOUNCE_DELAY * 1000)) {
                gpioWrite(LED_PIN, 1); // Turn LED on
                led_state = 1;
                last_led_change = current_time;
                printf("Sound level exceeded threshold. LED ON\n");
            }
        } else {
            // Debounce LED deactivation
            int current_time = gpioTick();
            if (led_state == 1 && (current_time - last_led_change) > (DEBOUNCE_DELAY * 1000)) {
                gpioWrite(LED_PIN, 0); // Turn LED off
                led_state = 0;
                last_led_change = current_time;
                printf("Sound level below threshold. LED OFF\n");
            }
        }

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

