    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Calibrate ambient noise level
    int num_calibration_samples = 100; // 100 samples over 5 seconds
    int calibration_samples[num_calibration_samples];
    printf("Calibrating ambient noise level for %d seconds...\n", CALIBRATION_TIME);
    for (int i = 0; i < num_calibration_samples; i++) {
        calibration_samples[i] = read_mcp3008(0);
        if (calibration_samples[i] == -1) {
            fprintf(stderr, "Error: Failed to read calibration sample\n");
            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }
        gpioDelay(50000); // 50ms delay (50000 microseconds)
    }
    double average_ambient_level = calculate_average(calibration_samples, num_calibration_samples);
    double threshold = average_ambient_level * THRESHOLD_MULTIPLIER;
    printf("Calibration complete. Average ambient level: %.2f, Threshold: %.2f\n", average_ambient_level, threshold);

    // Main loop
    int led_state = 0; // 0 = off, 1 = on
    int last_led_change = 0; // Timestamp of last LED change
    while (!terminate) {
        int sound_level = read_mcp3008(0);
        if (sound_level == -1) {
            fprintf(stderr, "Error: Failed to read sound level\n");
            break; // Exit loop on error
        }

        // Check if sound level exceeds threshold
        if (sound_level > threshold) {
            // Debounce LED activation
            int current_time = gpioTick();
            if (led_state == 0 && (current_time - last_led_change) > (DEBOUNCE_DELAY * 1000)) {
                gpioWrite(LED_PIN, 1); // Turn LED on
                led_state = 1;
                last_led_change = current_time;
                printf("Sound level exceeded threshold. LED ON\n");
            }
        } else {
            // Debounce LED deactivation
            int current_time = gpioTick();
            if (led_state == 1 && (current_time - last_led_change) > (DEBOUNCE_DELAY * 1000)) {
                gpioWrite(LED_PIN, 0); // Turn LED off
                led_state = 0;
                last_led_change = current_time;
                printf("Sound level below threshold. LED OFF\n");
            }
        }

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

