#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8
#define SAMPLE_RATE 1000 // Hz
#define SAMPLE_PERIOD_NS 1000000 // 1 ms in nanoseconds
#define LOG_FILE "audio_log.txt"

// Global variables (to be cleaned up on exit)
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3008(int spi_fd, uint8_t channel);
int log_data(FILE *fp, uint32_t timestamp_ns, uint16_t raw_adc_value);
void signal_handler(int sig);
int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **line);
int cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line);
int open_spi(const char *device);
int close_spi(int fd);
int open_log_file(const char *filename);
int close_log_file(FILE *fp);

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
        .delay_usecs = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

// Read MCP3008 function
int read_mcp3008(int spi_fd, uint8_t channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the command to read from the specified channel
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "SPI transfer failed during MCP3008 read.\n");
        return -1;
    }

    // Extract the 10-bit ADC value from the response
    uint16_t raw_adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return raw_adc_value;
}

// Log data function
int log_data(FILE *fp, uint32_t timestamp_ns, uint16_t raw_adc_value) {
    if (fprintf(fp, "%u|%u\n", timestamp_ns, raw_adc_value) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("Failed to flush log file");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup GPIO function
int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_PIN);
    if (!*line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line, "audio_sampler", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO function
int cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

// Open SPI device function
int open_spi(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(fd);
        return -1;
    }

    // Configure max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Close SPI device function
int close_spi(int fd) {
    if (close(fd) < 0) {
        perror("Failed to close SPI device");
        return -1;
    }
    return 0;
}

// Open log file function
int open_log_file(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }
    return (int)(intptr_t)fp; // Cast FILE* to int to store in global variable
}

// Close log file function
int close_log_file(FILE *fp) {
    if (fclose(fp) != 0) {
        perror("Failed to close log file");
        return -1;
    }
    return 0;
}

int main() {
    struct timespec ts;
    uint32_t timestamp_ns;
    uint16_t raw_adc_value;
    struct sigaction sa;

    // Install signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install signal handler");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (setup_gpio(&gpio_chip, &gpio_line) < 0) {
        return EXIT_FAILURE;
    }

    // Open SPI device
    spi_fd = open_spi(SPI_DEVICE);
    if (spi_fd < 0) {
        cleanup_gpio(gpio_chip, gpio_line);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = (FILE*)open_log_file(LOG_FILE);
    if (log_file == (FILE*)-1) {
        close_spi(spi_fd);
        cleanup_gpio(gpio_chip, gpio_line);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == -1) {
            perror("Failed to get timestamp");
            break;
        }
        timestamp_ns = (uint32_t)(ts.tv_sec * 1000000000 + ts.tv_nsec);

        // Read ADC value
        raw_adc_value = read_mcp3008(spi_fd, 0); // Channel 0
        if (raw_adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value.\n");
            break;
        }

        // Log data
        if (log_data(log_file, timestamp_ns, raw_adc_value) < 0) {
            fprintf(stderr, "Failed to log data.\n");
            break;
        }

        // Sleep until the next sample
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = SAMPLE_PERIOD_NS;
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    close_log_file(log_file);
    close_spi(spi_fd);
    cleanup_gpio(gpio_chip, gpio_line);

    return EXIT_SUCCESS;
}

