    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(fd);
        return -1;
    }

    // Configure max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Close SPI device function
int close_spi(int fd) {
    if (close(fd) < 0) {
        perror("Failed to close SPI device");
        return -1;
    }
    return 0;
}

// Open log file function
int open_log_file(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }
    return (int)(intptr_t)fp; // Cast FILE* to int to store in global variable
}

// Close log file function
int close_log_file(FILE *fp) {
    if (fclose(fp) != 0) {
        perror("Failed to close log file");
        return -1;
    }
    return 0;
}

int main() {
    struct timespec ts;
    uint32_t timestamp_ns;
    uint16_t raw_adc_value;
    struct sigaction sa;

    // Install signal handlers
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install signal handler");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (setup_gpio(&gpio_chip, &gpio_line) < 0) {
        return EXIT_FAILURE;
    }

    // Open SPI device
    spi_fd = open_spi(SPI_DEVICE);
    if (spi_fd < 0) {
        cleanup_gpio(gpio_chip, gpio_line);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = (FILE*)open_log_file(LOG_FILE);
    if (log_file == (FILE*)-1) {
        close_spi(spi_fd);
        cleanup_gpio(gpio_chip, gpio_line);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == -1) {
            perror("Failed to get timestamp");
            break;
        }
        timestamp_ns = (uint32_t)(ts.tv_sec * 1000000000 + ts.tv_nsec);

        // Read ADC value
        raw_adc_value = read_mcp3008(spi_fd, 0); // Channel 0
        if (raw_adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value.\n");
            break;
        }

        // Log data
        if (log_data(log_file, timestamp_ns, raw_adc_value) < 0) {
            fprintf(stderr, "Failed to log data.\n");
            break;
        }

        // Sleep until the next sample
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = SAMPLE_PERIOD_NS;
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    close_log_file(log_file);
    close_spi(spi_fd);
    cleanup_gpio(gpio_chip, gpio_line);

    return EXIT_SUCCESS;
}

