#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define MCP3008 pins
#define MCP3008_CS 8
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define ADXL335 sensitivity and zero-g bias
#define ADXL335_SENSITIVITY 0.300 // 300 mV/g
#define ADXL335_ZERO_G 1.500 // 1.5V

// Define scaling factor for ADC reading to voltage
#define VREF 3.3 // Reference voltage

// Define scaling factor for voltage to g
#define G_PER_VOLT (1.0 / ADXL335_SENSITIVITY)

// Define Kalman filter parameters
#define PROCESS_NOISE 0.01
#define MEASUREMENT_NOISE 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold Kalman filter state
typedef struct {
    float x;
    float p;
} KalmanState;

KalmanState kalman_x, kalman_y, kalman_z;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_g(float voltage);
void kalman_filter(KalmanState *state, float measurement);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC reading to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to convert voltage to g
float voltage_to_g(float voltage) {
    return (voltage - ADXL335_ZERO_G) * G_PER_VOLT;
}

// Function to apply Kalman filter
void kalman_filter(KalmanState *state, float measurement) {
    // Prediction step
    state->p += PROCESS_NOISE;

    // Update step
    float k = state->p / (state->p + MEASUREMENT_NOISE);
    state->x += k * (measurement - state->x);
    state->p *= (1 - k);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure MCP3008 CS pin as output
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Kalman filter states
    kalman_x.x = 0.0;
    kalman_x.p = 1.0;
    kalman_y.x = 0.0;
    kalman_y.p = 1.0;
    kalman_z.x = 0.0;
    kalman_z.p = 1.0;

    // Main loop
    while (!terminate) {
        // Read ADC values from MCP3008
        int adc_x = read_mcp3008(0);
        int adc_y = read_mcp3008(1);
        int adc_z = read_mcp3008(2);

        if (adc_x == -1 || adc_y == -1 || adc_z == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            break;
        }

        // Convert ADC values to voltages
        float voltage_x = adc_to_voltage(adc_x);
        float voltage_y = adc_to_voltage(adc_y);
        float voltage_z = adc_to_voltage(adc_z);

        // Convert voltages to g
        float g_x = voltage_to_g(voltage_x);
        float g_y = voltage_to_g(voltage_y);
        float g_z = voltage_to_g(voltage_z);

        // Apply Kalman filter
        kalman_filter(&kalman_x, g_x);
        kalman_filter(&kalman_y, g_y);
        kalman_filter(&kalman_z, g_z);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", kalman_x.x, kalman_y.x, kalman_z.x);

        // Delay for 100 ms (10 Hz sampling rate)
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

