#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define constants for magnetic field calculation
#define VCC 3.3
#define V_QUIESCENT (VCC / 2.0)
#define SENSITIVITY 0.025 // V/mT

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor value from a GPIO pin
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to calculate the magnetic field strength in millitesla
float calculate_magnetic_field(int sensor_value) {
    float voltage = (float)sensor_value * VCC; // Digital value is 0 or 1, so voltage is 0 or VCC
    float magnetic_field = (voltage - V_QUIESCENT) / SENSITIVITY;
    return magnetic_field;
}

// Function to log the sensor readings to a file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen("magnetic_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for logging!\n");
        return -1; // Indicate an error
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(fp); // Ensure data is written to disk immediately
    fclose(fp);
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

