    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Channel0,Channel1,Channel2\n");
    }
    rewind(csv_file);

    // Main loop
    while (!terminate) {
        int channel0_value = read_mcp3008(0);
        int channel1_value = read_mcp3008(1);
        int channel2_value = read_mcp3008(2);

        if (channel0_value == -1 || channel1_value == -1 || channel2_value == -1) {
            fprintf(stderr, "Error reading ADC values. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        log_data(channel0_value, channel1_value, channel2_value);
        sleep(1); // Log data every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

