#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>
#include <pigpio.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_PIN 17

static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function to log errors with timestamps
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

// Signal handler for clean shutdown
void signal_handler(int sig) {
    running = 0;
    printf("Signal received, cleaning up...\n");
}

// Callback function for MQTT connection
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_error("MQTT connection error");
    }
}

// Callback function for MQTT message
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        cJSON *json = cJSON_Parse(message->payload);
        if (json == NULL) {
            const char *error_ptr = cJSON_GetErrorPtr();
            if (error_ptr != NULL) {
                char error_message[256];
                snprintf(error_message, sizeof(error_message), "JSON parse error: %s", error_ptr);
                log_error(error_message);
            }
            return;
        }

        cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
        if (!cJSON_IsBool(led_state)) {
            log_error("Invalid 'led_state' type in JSON");
            cJSON_Delete(json);
            return;
        }

        int state = led_state->valueint;
        gpioWrite(GPIO_PIN, state);
        printf("LED set to %d\n", state);

        cJSON_Delete(json);
    } else {
        log_error("Empty MQTT message received");
    }
}

// Function to handle MQTT reconnection with exponential backoff
void reconnect(struct mosquitto *mosq) {
    static int delay = 1;
    if (delay > 60) delay = 60;
    printf("Attempting to reconnect in %d seconds...\n", delay);
    sleep(delay);
    mosquitto_reconnect(mosq);
    delay *= 2;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn off LED on startup

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto instance");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to MQTT broker
    int result = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (result != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Start MQTT loop
    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int rc = mosquitto_loop(mosq, 100, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("MQTT loop error");
            reconnect(mosq);
        }
    }

    // Clean up
    printf("Disconnecting from MQTT broker...\n");
    mosquitto_disconnect(mosq);
    mosquitto_loop_stop(mosq, false);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    printf("Turning off LED...\n");
    gpioWrite(GPIO_PIN, 0);

    printf("Terminating pigpio...\n");
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

