#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

// Function to read the sound sensor
int read_sound_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to control the alarm LED
void control_alarm_led(int gpio_pin, int state, int duration_ms) {
    gpioWrite(gpio_pin, state);
    gpioDelay(duration_ms * 1000); // Convert ms to microseconds
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);

    // Set GPIO18 as output
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the sound sensor
        int sound_level = read_sound_sensor(SOUND_SENSOR_PIN);

        // Print the sound level
        printf("Sound Level: %d\n", sound_level);

        // If sound is detected (DO = LOW)
        if (sound_level == 0) {
            // Blink the alarm LED
            control_alarm_led(ALARM_LED_PIN, 1, 1000); // ON for 1 second
            control_alarm_led(ALARM_LED_PIN, 0, 1000); // OFF for 1 second
        }

        // Delay for 100 ms
        gpioDelay(100 * 1000); // Convert ms to microseconds
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

