#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_fp = NULL;

// Signal handler
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log message to file and stdout
void log_message(const char *message) {
    char *timestamp = get_timestamp();
    char log_entry[256];

    snprintf(log_entry, sizeof(log_entry), "%s: %s\n", timestamp, message);

    if (log_fp != NULL) {
        if (fputs(log_entry, log_fp) == EOF) {
            perror("Error writing to log file");
        } else {
            fflush(log_fp); // Ensure immediate write
        }
    } else {
        fprintf(stderr, "Log file not opened, printing to stderr: %s", log_entry);
    }

    printf("%s", log_entry);
}

int main() {
    int ret;

    // Register signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Error registering signal handler");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for falling edge events
    ret = gpiod_line_request_rising_edge_events(line, "vibration-monitor");
    if (ret < 0) {
        perror("Error requesting rising edge events");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Error opening log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Vibration monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        struct gpiod_line_event event;
        int event_value;

        // Wait for event
        ret = gpiod_line_event_wait(line, -1); // Wait indefinitely
        if (ret < 0) {
            perror("Error waiting for event");
            break;
        }

        // Read event
        event_value = gpiod_line_event_read(line, &event);
        if (event_value < 0) {
            perror("Error reading event");
            break;
        }

        // Log message and shutdown
        log_message("Vibration detected! Shutting down...");
        system("sudo shutdown -h now");
        break; // Exit loop after shutdown is initiated
    }

    // Cleanup
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fp) {
        fclose(log_fp);
    }

    printf("Vibration monitor stopped.\n");
    return 0;
}

