#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define NUM_CHANNELS 3
#define BUFFER_SIZE 120
#define SLEEP_SECONDS 5

// Global variables
int spi_handle;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void log_temperature(float temperatures[NUM_CHANNELS]);
void write_buffer_to_file(float temperatures[NUM_CHANNELS]);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80 | (channel << 4); // Single-ended mode + channel number
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value / 1023.0) * VREF;
    float temperature = voltage / 0.01; // LM35: 10mV/°C
    return temperature;
}

// Function to log temperature readings
void log_temperature(float temperatures[NUM_CHANNELS]) {
    printf("Temperature: ");
    for (int i = 0; i < NUM_CHANNELS; i++) {
        printf("Channel %d: %.2f \u00b0C ", i, temperatures[i]);
    }
    printf("\n");
}

// Function to write the circular buffer to a file
void write_buffer_to_file(float temperatures[NUM_CHANNELS]) {
    FILE *fp = fopen("temp_log.dat", "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open file for writing\n");
        return;
    }

    // Write the entire buffer to the file
    size_t elements_written = fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, fp);
    if (elements_written != BUFFER_SIZE) {
        fprintf(stderr, "Error: Could not write all elements to file\n");
    }

    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperatures[NUM_CHANNELS];

        // Read temperature from each channel
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error: Failed to read ADC value from channel %d\n", i);
                temperatures[i] = -999.0; // Indicate error
            } else {
                temperatures[i] = convert_to_celsius(adc_value);
            }
        }

        // Log temperature readings
        log_temperature(temperatures);

        // Update circular buffer
        for (int i = 0; i < NUM_CHANNELS; i++) {
            temperature_buffer[buffer_index] = temperatures[i];
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        }

        // Write buffer to file every 5 seconds
        write_buffer_to_file(temperatures);

        // Sleep for 5 seconds
        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

