            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        }

        // Write buffer to file every 5 seconds
        write_buffer_to_file(temperatures);

        // Sleep for 5 seconds
        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

