#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define MCP3008_CHANNEL 0
#define LOG_FILE "environmental_log.txt"

// Global variables for file descriptors and program state
int i2c_fd = -1;
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(const char *bus);
int init_spi(const char *bus);
int read_bh1750(int fd);
int read_mcp3008(int fd, int channel);
char* format_log_entry(int light_level, int sound_level);
int write_to_log(const char *log_entry);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize SPI bus
int init_spi(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI bus");
        return -1;
    }

    // Configure SPI mode and speed
    int mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    int speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Read ambient light level from BH1750 sensor
int read_bh1750(int fd) {
    unsigned char buf[2];
    int lux;

    // Send start measurement command (High Resolution Mode)
    buf[0] = 0x10; // Continuous H-Resolution Mode
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement to complete (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Convert data to lux value
    lux = (buf[0] << 8) | buf[1];
    return lux;
}

// Read sound level from MCP3008 ADC
int read_mcp3008(int fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Format log entry with timestamp
char* format_log_entry(int light_level, int sound_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    static char log_entry[100]; // Static to persist across calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(log_entry, sizeof(log_entry), "%s, Light: %d, Sound: %d", timestamp, light_level, sound_level);
    return log_entry;
}

// Write log entry to file
int write_to_log(const char *log_entry) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s\n", log_entry);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_BUS);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    printf("Environmental logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int light_level = read_bh1750(i2c_fd);
        int sound_level = read_mcp3008(spi_fd, MCP3008_CHANNEL);

        if (light_level >= 0 && sound_level >= 0) {
            char *log_entry = format_log_entry(light_level, sound_level);
            if (write_to_log(log_entry) != 0) {
                fprintf(stderr, "Error writing to log file.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_fd != -1) close(i2c_fd);
    if (spi_fd != -1) close(spi_fd);
    if (log_file != NULL) fclose(log_file);

    printf("Exiting.\n");
    return 0;
}

