#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define MCP3008_CHANNEL 0
#define MCP4725_I2C_ADDR 0x62
#define I2C_BUS 1
#define TEMP_MIN 0.0
#define TEMP_MAX 50.0
#define VREF 3.3
#define DAC_MIN 0.0
#define DAC_MAX 3.3
#define SAMPLE_INTERVAL 0.5 // seconds

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_celsius(int adc_value);
int celsius_to_dac(int temperature);
int write_dac(int dac_value);
void log_data(int adc_value, float temperature, int dac_value);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float adc_to_celsius(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to convert Celsius to DAC value
int celsius_to_dac(int temperature) {
    float voltage = (float)temperature / 50.0 * 3.3;
    int dac_value = (int)(voltage / 3.3 * 4095.0); // 12-bit DAC
    if (dac_value < 0) dac_value = 0;
    if (dac_value > 4095) dac_value = 4095;
    return dac_value;
}

// Function to write to MCP4725 DAC
int write_dac(int dac_value) {
    char i2c_tx_buf[3];

    // Construct I2C message (MCP4725 datasheet)
    i2c_tx_buf[0] = 0x40; // Write DAC register
    i2c_tx_buf[1] = (dac_value >> 4) & 0x0F; // Upper 8 bits
