    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value >= 0) {
                float moisture = convert_to_moisture(adc_value);
                if (moisture >= 0.0) {
                    log_data(i, moisture);
                } else {
                    fprintf(stderr, "Error: Failed to convert ADC value to moisture for channel %d\n", i);
                }
            } else {
                fprintf(stderr, "Error: Failed to read ADC value for channel %d\n", i);
            }
        }

        gpioDelay(60000); // Sleep for 60 seconds
    }

    // Cleanup
    printf("Closing SPI, log file, and terminating pigpio.\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Goodbye!\n");
    return 0;
}

