#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Global variables for GPIO lines and chip
struct gpiod_chip *gpio_chip;
struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;

// Function prototypes
int initialize_gpio(void);
void activate_relay(struct gpiod_line *line);
void deactivate_relay(struct gpiod_line *line);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Deactivate all relays
    deactivate_relay(relay1_line);
    deactivate_relay(relay2_line);
    deactivate_relay(relay3_line);
    deactivate_relay(relay4_line);

    // Release GPIO lines
    gpiod_line_release(relay1_line);
    gpiod_line_release(relay2_line);
    gpiod_line_release(relay3_line);
    gpiod_line_release(relay4_line);

    // Close GPIO chip
    gpiod_chip_close(gpio_chip);

    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines for each relay
    relay1_line = gpiod_chip_get_line(gpio_chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(gpio_chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(gpio_chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(gpio_chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request GPIO lines as output
    ret = gpiod_line_request_output(relay1_line, "relay1", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting relay1 line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(relay2_line, "relay2", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting relay2 line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(relay3_line, "relay3", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting relay3 line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(relay4_line, "relay4", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting relay4 line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to activate a relay (set GPIO line HIGH)
void activate_relay(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting relay HIGH");
    }
}

// Function to deactivate a relay (set GPIO line LOW)
void deactivate_relay(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting relay LOW");
    }
}

int main(void) {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    // Main loop to activate and deactivate relays in sequence
    while (1) {
        // Activate relay 1
        activate_relay(relay1_line);
        sleep(1);
        deactivate_relay(relay1_line);
        sleep(1);

        // Activate relay 2
        activate_relay(relay2_line);
        sleep(1);
        deactivate_relay(relay2_line);
        sleep(1);

        // Activate relay 3
        activate_relay(relay3_line);
        sleep(1);
        deactivate_relay(relay3_line);
        sleep(1);

        // Activate relay 4
        activate_relay(relay4_line);
        sleep(1);
        deactivate_relay(relay4_line);
        sleep(1);
    }

    return 0;
}

