    relay3_line = gpiod_chip_get_line(gpio_chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(gpio_chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request GPIO lines as output
    ret = gpiod_line_request_output(relay1_line, "relay1", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting relay1 line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(relay2_line, "relay2", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting relay2 line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(relay3_line, "relay3", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting relay3 line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(relay4_line, "relay4", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting relay4 line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to activate a relay (set GPIO line HIGH)
void activate_relay(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting relay HIGH");
    }
}

// Function to deactivate a relay (set GPIO line LOW)
void deactivate_relay(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting relay LOW");
    }
}

int main(void) {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    // Main loop to activate and deactivate relays in sequence
    while (1) {
        // Activate relay 1
        activate_relay(relay1_line);
        sleep(1);
        deactivate_relay(relay1_line);
        sleep(1);

        // Activate relay 2
        activate_relay(relay2_line);
