        deactivate_relay(relay2_line);
        sleep(1);

        // Activate relay 3
        activate_relay(relay3_line);
        sleep(1);
        deactivate_relay(relay3_line);
        sleep(1);

        // Activate relay 4
        activate_relay(relay4_line);
        sleep(1);
        deactivate_relay(relay4_line);
        sleep(1);
    }

    return 0;
}

