#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define IN1 17
#define IN2 18
#define ENA 27

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define rain level threshold
#define RAIN_THRESHOLD 5

// Define motor speed
#define MOTOR_SPEED 150

// Define motor run time
#define MOTOR_RUN_TIME 3

// Define log file name
#define LOG_FILE "rain_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int convert_adc_to_rain_level(int adc_value);
void control_motor(int direction, int speed);
void log_rain_level(int rain_level);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate error
    }

    // Parse ADC value
    int adc_value = ((rx[1] & 0x03) << 8) + rx[2];

    return adc_value;
}

// Function to convert ADC value to rain level
int convert_adc_to_rain_level(int adc_value) {
    // Linear mapping: ADC 1023 -> Rain level 0, ADC 0 -> Rain level 10
    return 10 - (int)(((float)adc_value / 1023.0) * 10.0);
}

// Function to control the DC motor
void control_motor(int direction, int speed) {
    if (direction == 1) { // Forward
        gpioWrite(IN1, 1);
        gpioWrite(IN2, 0);
    } else if (direction == -1) { // Reverse
        gpioWrite(IN1, 0);
        gpioWrite(IN2, 1);
    } else { // Stop
        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
    }

    gpioPWM(ENA, speed);
}

// Function to log rain level to file
void log_rain_level(int rain_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);

    // Set PWM range and duty cycle
    gpioSetPWMrange(ENA, 255);
    gpioSetPWMrange(ENA, 255);
    gpioPWM(ENA, 0); // Initially stop the motor

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int rain_level = 0; // Initialize rain level
    int motor_direction = -1; // Initialize motor direction (open)
    while (!terminate) {
        // Read rain sensor
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to rain level
        rain_level = convert_adc_to_rain_level(adc_value);

        // Log rain level
        log_rain_level(rain_level);

        // Control motor based on rain level
        if (rain_level >= RAIN_THRESHOLD && motor_direction != 1) {
            printf("Rain detected, closing window...\n");
            control_motor(1, MOTOR_SPEED); // Close window
            gpioDelay(MOTOR_RUN_TIME * 1000); // Run for 3 seconds
            control_motor(0, 0); // Stop motor
            motor_direction = 1; // Update motor direction
        } else if (rain_level < RAIN_THRESHOLD && motor_direction != -1) {
            printf("Rain stopped, opening window...\n");
            control_motor(-1, MOTOR_SPEED); // Open window
            gpioDelay(MOTOR_RUN_TIME * 1000); // Run for 3 seconds
            control_motor(0, 0); // Stop motor
            motor_direction = -1; // Update motor direction
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_motor(0, 0); // Stop motor
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

