#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MICROPHONE_PIN 26
#define LED_PIN 16

// Define constants
#define THRESHOLD 700
#define LED_ON_TIME 500 // milliseconds
#define DEBOUNCE_TIME 50 // milliseconds
#define SAMPLE_RATE 1000 // Hz
#define SAMPLE_PERIOD (1000000 / SAMPLE_RATE) // microseconds

// Global variables
volatile sig_atomic_t program_running = 1;
volatile unsigned long last_detection_time = 0;

// Function prototypes
int initialize_gpio();
int read_adc();
void detect_clap(int adc_value);
void control_led(int on);
void print_timestamped_message();
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int microphone_pin;
    int led_pin;
    int threshold;
    int led_on_time;
    int debounce_time;
    int sample_rate;
} Config;

Config config = {MICROPHONE_PIN, LED_PIN, THRESHOLD, LED_ON_TIME, DEBOUNCE_TIME, SAMPLE_RATE};

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    printf("Clap detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_adc();

        if (adc_value >= 0) {
            detect_clap(adc_value);
        } else {
            fprintf(stderr, "Error reading ADC value.\n");
        }

        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Clean up and exit
    gpioTerminate();
    printf("Clap detector stopped.\n");
    return 0;
}

// Initialize pigpio and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO26 as input
    if (gpioSetMode(config.microphone_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", config.microphone_pin);
        gpioTerminate();
        return 1;
    }

    // Set GPIO16 as output
    if (gpioSetMode(config.led_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", config.led_pin);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read ADC value using bit-banging
int read_adc() {
    int adc_value = 0;
    int i;

    // Discharge capacitor
    gpioSetMode(config.microphone_pin, PI_OUTPUT);
    gpioWrite(config.microphone_pin, 0);
    gpioDelay(1); // 1 us discharge

    // Set as input for sampling
    gpioSetMode(config.microphone_pin, PI_INPUT);

    // Measure charge time
    unsigned long start_time = gpioTick();
    while (gpioRead(config.microphone_pin) == 0) {
        if (gpioTick() - start_time > 10000) { // Timeout after 10ms
            return -1; // Indicate error
        }
    }
    unsigned long end_time = gpioTick();

    adc_value = (int)(end_time - start_time);

    return adc_value;
}

// Detect clap and trigger LED
