int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO26 as input
    if (gpioSetMode(config.microphone_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", config.microphone_pin);
        gpioTerminate();
        return 1;
    }

