    int adc_value = 0;
    int i;

    // Discharge capacitor
    gpioSetMode(config.microphone_pin, PI_OUTPUT);
    gpioWrite(config.microphone_pin, 0);
    gpioDelay(1); // 1 us discharge

    // Set as input for sampling
    gpioSetMode(config.microphone_pin, PI_INPUT);

    // Measure charge time
    unsigned long start_time = gpioTick();
    while (gpioRead(config.microphone_pin) == 0) {
        if (gpioTick() - start_time > 10000) { // Timeout after 10ms
            return -1; // Indicate error
        }
    }
    unsigned long end_time = gpioTick();

    adc_value = (int)(end_time - start_time);

