#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio"
#define LOG_FILE "distance_log.txt"

// Global variable to track if the program should exit
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to export the GPIO pin
int export_gpio(int pin) {
    char export_path[64];
    int fd;

    snprintf(export_path, sizeof(export_path), GPIO_PATH "/export");
    fd = open(export_path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening /sys/class/gpio/export");
        return -1;
    }

    char pin_str[3];
    snprintf(pin_str, sizeof(pin_str), "%d", pin);
    if (write(fd, pin_str, strlen(pin_str)) < 0) {
        perror("Error writing to /sys/class/gpio/export");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport the GPIO pin
int unexport_gpio(int pin) {
    char unexport_path[64];
    int fd;

    snprintf(unexport_path, sizeof(unexport_path), GPIO_PATH "/unexport");
    fd = open(unexport_path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening /sys/class/gpio/unexport");
        return -1;
    }

    char pin_str[3];
    snprintf(pin_str, sizeof(pin_str), "%d", pin);
    if (write(fd, pin_str, strlen(pin_str)) < 0) {
        perror("Error writing to /sys/class/gpio/unexport");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the GPIO direction to input
int set_gpio_direction(int pin, const char *direction) {
    char direction_path[64];
    int fd;

    snprintf(direction_path, sizeof(direction_path), GPIO_PATH "/gpio%d/direction", pin);
    fd = open(direction_path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) < 0) {
        perror("Error writing to GPIO direction file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the GPIO value
int read_gpio_value(int pin) {
    char value_path[64];
    int fd;
    char value_str[2];

    snprintf(value_path, sizeof(value_path), GPIO_PATH "/gpio%d/value", pin);
    fd = open(value_path, O_RDONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }

    if (read(fd, value_str, 1) < 0) {
        perror("Error reading GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return (value_str[0] == '1') ? 1 : 0;
}

// Function to calculate distance from voltage
float calculate_distance(float voltage) {
    float A = 26.0;
    float B = -6.0;
    return A / voltage + B;
}

// Function to log the distance to a file
int log_distance(float distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, distance);
    fclose(fp);
    return 0;
}

// Function to check if the pet feeder should be activated
void check_feeder_activation(float distance) {
    if (distance < 200.0) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (export_gpio(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO %d. Exiting.\n", GPIO_PIN);
        return 1;
    }

    // Set GPIO direction to input
    if (set_gpio_direction(GPIO_PIN, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input. Exiting.\n", GPIO_PIN);
        unexport_gpio(GPIO_PIN);
        return 1;
    }

    printf("Pet Feeder Program Started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read GPIO value
        int gpio_value = read_gpio_value(GPIO_PIN);
        if (gpio_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d value. Retrying in 1 second.\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        // Convert GPIO value to voltage
        float voltage = (gpio_value == 1) ? 3.3 : 0.0;

        // Calculate distance
        float distance = calculate_distance(voltage);

        // Log distance
        if (log_distance(distance) < 0) {
            fprintf(stderr, "Failed to log distance. \n");
        }

        // Check feeder activation
        check_feeder_activation(distance);

        // Wait for 1 second
        sleep(1);
    }

    // Unexport GPIO pin before exiting
    if (unexport_gpio(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to unexport GPIO %d. \n", GPIO_PIN);
    }

    printf("Program exited cleanly.\n");
    return 0;
}

