    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value, retrying in 60 seconds...\n");
            sleep(60);
            continue;
        }

        // Calculate moisture percentage
        float moisture = calculate_moisture(adc_value);

        // Control pump based on moisture level
        int pump_state = (moisture < MOISTURE_THRESHOLD) ? 1 : 0;
        control_pump(pump_state);

        // Log data
        log_data(moisture, pump_state);

        printf("Moisture: %.2f%%, Pump: %s\n", moisture, pump_state ? "ON" : "OFF");

        // Wait 60 seconds
        sleep(60);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

