#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <linux/spi/spidev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_PIN 17
#define ADC_CHANNEL 0
#define VREF 5.0
#define SENSITIVITY 0.1
#define LOG_FILE "current_log.txt"

// Global variables for signal handling
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold program state
typedef struct {
    int spi_fd;
    FILE *log_file;
    int gpio_pin;
} ProgramState;

// Function prototypes
int spi_init(const char *device);
int read_adc(int spi_fd, int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_current(float voltage, float sensitivity);
int log_current(float current, const char *filename);
void signal_handler(int signal);
void cleanup(ProgramState *state);

// SPI initialization function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Configure SPI max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from the MCP3008 ADC
int read_adc(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value, float vref) {
    return ((float)adc_value / 1023.0) * vref;
}

// Function to convert voltage to current
float voltage_to_current(float voltage, float sensitivity) {
    return voltage / sensitivity;
}

// Function to log current reading to a file
int log_current(float current, const char *filename) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(filename, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.3f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(ProgramState *state) {
    printf("Cleaning up...\n");
    if (state->spi_fd != -1) {
        close(state->spi_fd);
    }
    if (state->log_file != NULL) {
        fclose(state->log_file);
    }
    gpioTerminate();
}

int main() {
    ProgramState state = { .spi_fd = -1, .log_file = NULL, .gpio_pin = GPIO_PIN };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    state.spi_fd = spi_init(SPI_DEVICE);
    if (state.spi_fd == -1) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output (not strictly needed for MCP3008, but good practice)
    gpioSetMode(state.gpio_pin, PI_OUTPUT);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(state.spi_fd, ADC_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value\n");
            break; // Exit loop on error
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value, VREF);

        // Convert voltage to current
        float current = voltage_to_current(voltage, SENSITIVITY);

        // Log current reading
        if (log_current(current, LOG_FILE) != 0) {
            fprintf(stderr, "Error logging current reading\n");
            break; // Exit loop on error
        }

        printf("Current: %.3f A\n", current);

        sleep(1); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup(&state);
    return 0;
}

