#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define VREF 5.0
#define FULL_SCALE_CURRENT 50.0
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_voltage(int raw_value);
float convert_to_current(float voltage);
void log_current(float current);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = 0x80 | (channel << 4); // Single-ended mode, channel selection
    tx[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract 10-bit result
    int raw_value = ((rx[1] & 0x03) << 8) | rx[2];
    return raw_value;
}

// Function to convert raw ADC value to voltage
float convert_to_voltage(int raw_value) {
    return ((float)raw_value / 1023.0) * VREF;
}

// Function to convert voltage to current
float convert_to_current(float voltage) {
    return (voltage - 2.5) * (FULL_SCALE_CURRENT / 2.5);
}

// Function to log current to file
void log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int raw_value = read_mcp3008(MCP3008_CHANNEL);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to next iteration
        }

        // Convert to voltage
        float voltage = convert_to_voltage(raw_value);

        // Validate voltage
        if (voltage < 0.0 || voltage > VREF) {
            fprintf(stderr, "Warning: Voltage out of range: %.2f V\n", voltage);
            continue; // Skip to next iteration
        }

        // Convert to current
        float current = convert_to_current(voltage);

        // Log current
        log_current(current);

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

