#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17

// Debounce samples
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to read the sensor value with debouncing
int read_sensor(int gpio) {
    int low_count = 0;
    int high_count = 0;

    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int value = gpioRead(gpio);
        if (value == 0) {
            low_count++;
        } else {
            high_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }

    // Return 0 if LOW is the majority, 1 otherwise
    return (low_count > high_count) ? 0 : 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Set pull-up resistors (optional, but recommended for open-collector)
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        // Log sensor states
        printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_value, sensor2_value);

        // Check for alert condition
        if (sensor1_value == 0 && sensor2_value == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // Delay in microseconds
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

