// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

// Global flag for graceful shutdown
volatile sig_atomic_t terminate = 0;

// SPI configuration structure
typedef struct {
    int channel;
    int baud;
} spi_config_t;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
void log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(spi_config_t config);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// SPI setup function
int spi_setup(spi_config_t config) {
    int spi_handle = spiOpen(config.channel, config.baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", config.channel, spi_handle);
        return -1;
    }
    return spi_handle;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    int spi_handle = spi_setup((spi_config_t){SPI_CHANNEL, SPI_BAUD});
    if (spi_handle < 0) {
        return -1; // Indicate error
    }

    char tx_buf[3];
    char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80 | (channel << 4); // Single-ended mode + channel select
    tx_buf[2] = 0x00; // Dummy byte

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        spiClose(spi_handle);
        return -1; // Indicate error
    }

    spiClose(spi_handle);

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to calculate moisture level percentage
double calculate_moisture_level(int adc_value) {
    double moisture = 100.0 - ((adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
    if (moisture < 0.0) {
        moisture = 0.0;
    } else if (moisture > 100.0) {
        moisture = 100.0;
    }
    return moisture;
}

// Function to log data to file
