#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pigpio.h>
#include <errno.h>
#include <sys/stat.h>
#include <fcntl.h>

// Configuration
#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_WIDTH 1280
#define CAPTURE_HEIGHT 720
#define CAPTURE_QUALITY 85
#define CAPTURE_DIRECTORY "/home/pi/security_cam/"
#define LOGGING_INTERVAL_SEC 60

// Global variables
volatile sig_atomic_t terminate = 0;
int last_state = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
int debounce();
int capture_image();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received: %d. Terminating...", signal);
    terminate = 1;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    syslog(LOG_INFO, "GPIO initialized on pin %d", GPIO_PIN);
    return 0;
}

// Read sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Debounce function
int debounce() {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    return read_sensor();
}

// Capture image
int capture_image() {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[256];
    char command[512];
    pid_t pid;
    int status;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    snprintf(command, sizeof(command), "libcamera-still -o %s/%s.jpg -n -q %d -w %d -h %d",
             CAPTURE_DIRECTORY, filename, CAPTURE_QUALITY, CAPTURE_WIDTH, CAPTURE_HEIGHT);

    pid = fork();

    if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        // execl only returns on error
        syslog(LOG_ERR, "execl failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    } else if (pid < 0) {
        // Fork failed
        syslog(LOG_ERR, "fork failed: %s", strerror(errno));
        return -1;
    } else {
        // Parent process
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            syslog(LOG_INFO, "Image captured: %s/%s.jpg", CAPTURE_DIRECTORY, filename);
            return 0;
        } else {
            syslog(LOG_ERR, "Image capture failed with status: %d", status);
