// Configuration
#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_WIDTH 1280
#define CAPTURE_HEIGHT 720
#define CAPTURE_QUALITY 85
#define CAPTURE_DIRECTORY "/home/pi/security_cam/"
#define LOGGING_INTERVAL_SEC 60

// Global variables
volatile sig_atomic_t terminate = 0;
int last_state = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
int debounce();
int capture_image();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received: %d. Terminating...", signal);
    terminate = 1;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    syslog(LOG_INFO, "GPIO initialized on pin %d", GPIO_PIN);
    return 0;
}

// Read sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Debounce function
int debounce() {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    return read_sensor();
}

