#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define WIDTH 640
#define HEIGHT 480
#define NUM_BUFFERS 1

// Structure to hold program state
typedef struct {
    int fd;
    struct v4l2_buffer buf;
    void *buffer[1];
    unsigned int buffer_size[1];
    int buffer_count;
    int image_count;
    char *device_name;
    int running;
} AppState;

// Signal handler function
void signal_handler(int signum) {
    AppState *app_state = (AppState *)malloc(sizeof(AppState)); // Allocate memory for the AppState
    if (app_state == NULL) {
        perror("Failed to allocate memory for AppState in signal handler");
        exit(EXIT_FAILURE);
    }
    app_state->running = 0; // Set running to 0 to stop the main loop
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
    free(app_state);
}

// Function to initialize the V4L2 device
int init_device(AppState *app_state) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Check if the device is a video capture device
    if (ioctl(app_state->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", app_state->device_name);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", app_state->device_name);
        return -1;
    }

    // Set the image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(app_state->fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(app_state->fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    // Map the buffers
    for (app_state->buffer_count = 0; app_state->buffer_count < NUM_BUFFERS; app_state->buffer_count++) {
        memset(&app_state->buf, 0, sizeof(app_state->buf));
        app_state->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        app_state->buf.memory = V4L2_MEMORY_MMAP;
        app_state->buf.index = app_state->buffer_count;

        if (ioctl(app_state->fd, VIDIOC_QUERYBUF, &app_state->buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        app_state->buffer_size[app_state->buffer_count] = app_state->buf.length;

        app_state->buffer[app_state->buffer_count] = mmap(NULL, app_state->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, app_state->fd, app_state->buf.m.offset);
        if (app_state->buffer[app_state->buffer_count] == MAP_FAILED) {
            perror("mmap");
            return -1;
        }
    }

    return 0;
}

// Function to start streaming
int start_streaming(AppState *app_state) {
    for (app_state->buffer_count = 0; app_state->buffer_count < NUM_BUFFERS; app_state->buffer_count++) {
        memset(&app_state->buf, 0, sizeof(app_state->buf));
        app_state->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        app_state->buf.memory = V4L2_MEMORY_MMAP;
        app_state->buf.index = app_state->buffer_count;

        if (ioctl(app_state->fd, VIDIOC_QBUF, &app_state->buf) < 0) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(app_state->fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(AppState *app_state) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(app_state->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(app_state->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    memset(&app_state->buf, 0, sizeof(app_state->buf));
    app_state->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    app_state->buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(app_state->fd, VIDIOC_DQBUF, &app_state->buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    return 0;
}

// Function to save the frame as a PGM file
int save_frame(AppState *app_state) {
    char filename[20];
    FILE *fp;

    snprintf(filename, sizeof(filename), "image_%04d.pgm", app_state->image_count++);
    fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", WIDTH, HEIGHT);
    fwrite(app_state->buffer[app_state->buf.index], 1, app_state->buf.bytesused, fp);

    fclose(fp);
    return 0;
}

// Function to stop streaming
int stop_streaming(AppState *app_state) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(app_state->fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }
    return 0;
}

// Function to unmap the buffers
int unmap_buffers(AppState *app_state) {
    for (app_state->buffer_count = 0; app_state->buffer_count < NUM_BUFFERS; app_state->buffer_count++) {
        if (munmap(app_state->buffer[app_state->buffer_count], app_state->buffer_size[app_state->buffer_count]) < 0) {
            perror("munmap");
            return -1;
        }
    }
    return 0;
}

// Function to close the device
int close_device(AppState *app_state) {
    if (close(app_state->fd) < 0) {
        perror("close");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    AppState app_state;
    int fd;

    // Set default device name
    app_state.device_name = "/dev/video0";
    if (argc > 1) {
        app_state.device_name = argv[1];
    }

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open(app_state.device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }
    app_state.fd = fd;

    // Initialize the device
    if (init_device(&app_state) < 0) {
        close_device(&app_state);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(&app_state) < 0) {
        unmap_buffers(&app_state);
        close_device(&app_state);
        return EXIT_FAILURE;
    }

    app_state.image_count = 1;
    app_state.running = 1;

    // Main loop
    while (app_state.running) {
        if (capture_frame(&app_state) == 0) {
            if (save_frame(&app_state) != 0) {
                fprintf(stderr, "Error saving frame %d\n", app_state.image_count - 1);
            }
            if (ioctl(app_state.fd, VIDIOC_QBUF, &app_state->buf) < 0) {
                perror("VIDIOC_QBUF");
                app_state.running = 0;
            }
        } else {
            fprintf(stderr, "Error capturing frame %d\n", app_state.image_count);
            app_state.running = 0;
        }
    }

    // Stop streaming
    if (stop_streaming(&app_state) < 0) {
        fprintf(stderr, "Error stopping streaming\n");
    }

    // Unmap buffers
    if (unmap_buffers(&app_state) < 0) {
        fprintf(stderr, "Error unmapping buffers\n");
    }

    // Close the device
    if (close_device(&app_state) < 0) {
        fprintf(stderr, "Error closing device\n");
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

