#include <signal.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FRAME_LOG_FILE "frame_log.txt"

// Structure to hold video device information
typedef struct {
    int fd;
    struct v4l2_buffer buf;
    void *buffer;
    size_t buffer_size;
    FILE *log_file;
} video_device_t;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize the video device
int init_video_device(video_device_t *device) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_streamparm streamparm;

    // Open the video device
    device->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (device->fd < 0) {
        perror("Error opening video device");
        return -1;
    }

    // Check device capabilities
    if (ioctl(device->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(device->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(device->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(device->fd);
        return -1;
    }

    // Set video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(device->fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(device->fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer for simplicity
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(device->fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(device->fd);
        return -1;
    }

    // Map the buffer
    memset(&device->buf, 0, sizeof(device->buf));
    device->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    device->buf.memory = V4L2_MEMORY_MMAP;
    device->buf.index = 0;

    if (ioctl(device->fd, VIDIOC_QUERYBUF, &device->buf) < 0) {
        perror("Error querying buffer");
        close(device->fd);
        return -1;
    }

    device->buffer_size = device->buf.length;
    device->buffer = mmap(NULL, device->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, device->fd, device->buf.m.offset);
    if (device->buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(device->fd);
        return -1;
    }

    // Queue the buffer
    if (ioctl(device->fd, VIDIOC_QBUF, &device->buf) < 0) {
        perror("Error queuing buffer");
        munmap(device->buffer, device->buf.length);
        close(device->fd);
        return -1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(device->fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(device->buffer, device->buf.length);
        close(device->fd);
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(video_device_t *device) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(device->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(device->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error in select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Error: select timeout\n");
        return -1;
    }

    if (ioctl(device->fd, VIDIOC_DQBUF, &device->buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    return 0;
}

// Function to log the frame timestamp
int log_timestamp(video_device_t *device) {
    struct timeval tv;
    char timestamp[30];

    if (gettimeofday(&tv, NULL) < 0) {
        perror("Error getting time");
        return -1;
    }

    snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", tv.tv_sec, tv.tv_usec);
    fprintf(device->log_file, "%s\n", timestamp);
    fflush(device->log_file);

    return 0;
}

// Function to uninitialize the video device
int uninit_video_device(video_device_t *device) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(device->fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
    }

    if (munmap(device->buffer, device->buf.length) < 0) {
        perror("Error unmapping buffer");
    }

    if (close(device->fd) < 0) {
        perror("Error closing device");
    }

    if (fclose(device->log_file) < 0) {
        perror("Error closing log file");
    }

    return 0;
}

int main() {
    video_device_t device;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize the video device
    if (init_video_device(&device) < 0) {
        fprintf(stderr, "Failed to initialize video device\n");
        return EXIT_FAILURE;
    }

    // Open the log file
    device.log_file = fopen(FRAME_LOG_FILE, "a");
    if (device.log_file == NULL) {
        perror("Error opening log file");
        uninit_video_device(&device);
        return EXIT_FAILURE;
    }

    printf("Capturing frames... Press Ctrl+C to exit.\n");

    // Capture frames until termination signal is received
    while (!terminate) {
        if (capture_frame(&device) == 0) {
            if (log_timestamp(&device) != 0) {
                fprintf(stderr, "Failed to log timestamp\n");
            }
            if (ioctl(device.fd, VIDIOC_QBUF, &device.buf) < 0) {
                perror("Error requeuing buffer");
                break;
            }
        } else {
            fprintf(stderr, "Failed to capture frame\n");
            break;
        }
    }

    // Uninitialize the video device
    if (uninit_video_device(&device) != 0) {
        fprintf(stderr, "Failed to uninitialize video device\n");
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

