    unsigned int header[3];
    header[0] = frame_index; // Frame index
    header[1] = fragment_index; // Fragment index
    header[2] = total_fragments; // Total fragments

    // Determine payload size
    size_t payload_size = (data_len < MAX_UDP_PAYLOAD) ? data_len : MAX_UDP_PAYLOAD;

    // Create packet
    char packet[UDP_PACKET_SIZE];
    memcpy(packet, header, 8); // Copy header
    memcpy(packet + 8, data, payload_size); // Copy payload

    // Send packet
    if (sendto(sockfd, packet, 8 + payload_size, 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr)) < 0) {
        perror("Error sending packet");
        return -1;
    }

    return 0;
}

