#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <poll.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH  1920
#define IMAGE_HEIGHT 1080
#define NUM_BUFFERS 4
#define IMAGE_FILE "image.jpg"

typedef struct {
    void   *start;
    size_t  length;
} buffer;

buffer *buffers;
int fd = -1;
FILE *image_file = NULL;

void signal_handler(int signum) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signum);

    if (fd != -1) {
        // Stop streaming
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
            perror("VIDIOC_STREAMOFF");
        }

        // Unmap buffers
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (buffers[i].start != NULL && buffers[i].length != 0) {
                if (munmap(buffers[i].start, buffers[i].length) == -1) {
                    perror("munmap");
                }
            }
        }

        // Free buffer array
        if (buffers != NULL) {
            free(buffers);
        }

        // Close device
        if (close(fd) == -1) {
            perror("close");
        }
    }

    if (image_file != NULL) {
        if (fclose(image_file) == EOF) {
            perror("fclose");
        }
    }

    exit(0);
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    int i;

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open device
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Query capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Allocate buffers
    buffers = calloc(req.count, sizeof(buffer));
    if (!buffers) {
        perror("calloc");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map buffers
    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            close(fd);
            return EXIT_FAILURE;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Queue buffers
    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        close(fd);
        return EXIT_FAILURE;
    }

    // Dequeue buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        close(fd);
        return EXIT_FAILURE;
    }

    // Verify buffer data
    if (buf.bytesused == 0) {
        fprintf(stderr, "Error: No data captured\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Write to file
    image_file = fopen(IMAGE_FILE, "wb");
    if (image_file == NULL) {
        perror("fopen");
        close(fd);
        return EXIT_FAILURE;
    }

    if (fwrite(buffers[buf.index].start, 1, buf.bytesused, image_file) != buf.bytesused) {
        perror("fwrite");
        fclose(image_file);
        close(fd);
        return EXIT_FAILURE;
    }

    // Requeue buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        fclose(image_file);
        close(fd);
        return EXIT_FAILURE;
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
        fclose(image_file);
        close(fd);
        return EXIT_FAILURE;
    }

    // Unmap buffers
    for (i = 0; i < NUM_BUFFERS; i++) {
        if (buffers[i].start != NULL && buffers[i].length != 0) {
            if (munmap(buffers[i].start, buffers[i].length) == -1) {
                perror("munmap");
            }
        }
    }

    // Free buffer array
    if (buffers != NULL) {
        free(buffers);
    }

    // Close file
    if (fclose(image_file) == EOF) {
        perror("fclose");
    }

    // Close device
    if (close(fd) == -1) {
        perror("close");
    }

    printf("Image captured and saved to %s\n", IMAGE_FILE);

    return EXIT_SUCCESS;
}

