#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 4
#define JPEG_QUALITY 75

// Structure to hold camera buffer information
struct buffer {
    void   *start;
    size_t  length;
};

// Global variables for cleanup
static int                  fd                  = -1;
static struct buffer        buffers[NUM_BUFFERS];
static unsigned char        *rgb_buffer         = NULL;
static unsigned char        *blurred_buffer     = NULL;
static int                  image_width         = IMAGE_WIDTH;
static int                  image_height        = IMAGE_HEIGHT;
static int                  running             = 1;

// Function prototypes
static int  xioctl(int fd, int request, void *arg);
static void signal_handler(int signum);
static int  init_camera(int fd);
static int  capture_frame(int fd, struct buffer *buffers, int num_buffers);
static void yuyv_to_rgb24(unsigned char *yuyv, unsigned char *rgb, int width, int height);
static void box_blur(unsigned char *rgb, unsigned char *blurred, int width, int height, int radius);
static int  save_jpeg(unsigned char *image, int width, int height, char *filename);

// Signal handler for graceful shutdown
static void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        running = 0;
    }
}

// Helper function to handle errors
static void error_exit(const char *message) {
    fprintf(stderr, "%s error %d, %s\n", message, errno, strerror(errno));
    exit(EXIT_FAILURE);
}

// Helper function to handle xioctl calls
static int xioctl(int fd, int request, void *arg) {
    int r;

    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

// Initialize the camera device
static int init_camera(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    // Check device capabilities
    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        error_exit("VIDIOC_QUERYCAP");
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = image_width;
    fmt.fmt.pix.height = image_height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        error_exit("VIDIOC_S_FMT");
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        error_exit("VIDIOC_REQBUFS");
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    // Map the buffers
    for (i = 0; i < req.count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            error_exit("VIDIOC_QUERYBUF");
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[i].start) {
            error_exit("mmap");
        }
    }

    return 0;
}

// Capture a single frame from the camera
static int capture_frame(int fd, struct buffer *buffers, int num_buffers) {
    unsigned int i;
    fd_set fds;
    struct timeval tv;
    int r;

    // Queue the buffers
    for (i = 0; i < num_buffers; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            error_exit("VIDIOC_QBUF");
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        error_exit("VIDIOC_STREAMON");
    }

    // Wait for frame readiness with timeout
    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (-1 == r) {
        error_exit("select");
    } else if (0 == r) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    // Dequeue the buffer
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
        error_exit("VIDIOC_DQBUF");
    }

    // Stop streaming
    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        error_exit("VIDIOC_STREAMOFF");
    }

    return buf.index;
}

// Convert YUYV to RGB24
static void yuyv_to_rgb24(unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    int i, j;
    unsigned char *yuyv_ptr = yuyv;
    unsigned char *rgb_ptr = rgb;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j += 2) {
            unsigned char y1 = yuyv_ptr[0];
            unsigned char u = yuyv_ptr[1];
            unsigned char y2 = yuyv_ptr[2];
            unsigned char v = yuyv_ptr[3];

            int c = y1 - 16;
            int d = u - 128;
            int e = v - 128;

            int r = (298 * c + 409 * e + 128) >> 8;
            int g = (298 * c - 100 * d - 208 * e + 128) >> 8;
            int b = (298 * c + 516 * d + 128) >> 8;

            r = (r < 0) ? 0 : ((r > 255) ? 255 : r);
            g = (g < 0) ? 0 : ((g > 255) ? 255 : g);
            b = (b < 0) ? 0 : ((b > 255) ? 255 : b);

            rgb_ptr[0] = r;
            rgb_ptr[1] = g;
            rgb_ptr[2] = b;

            c = y2 - 16;
            r = (298 * c + 409 * e + 128) >> 8;
            g = (298 * c - 100 * d - 208 * e + 128) >> 8;
            b = (298 * c + 516 * d + 128) >> 8;

            r = (r < 0) ? 0 : ((r > 255) ? 255 : r);
            g = (g < 0) ? 0 : ((g > 255) ? 255 : g);
            b = (b < 0) ? 0 : ((b > 255) ? 255 : b);

            rgb_ptr[3] = r;
            rgb_ptr[4] = g;
            rgb_ptr[5] = b;

            yuyv_ptr += 4;
            rgb_ptr += 6;
        }
    }
}

// Apply a 5x5 box blur filter
static void box_blur(unsigned char *rgb, unsigned char *blurred, int width, int height, int radius) {
    int i, j, k, l;
    int r_sum, g_sum, b_sum;
    int count;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            r_sum = g_sum = b_sum = 0;
            count = 0;

            for (k = i - radius; k <= i + radius; k++) {
                for (l = j - radius; l <= j + radius; l++) {
                    if (k >= 0 && k < height && l >= 0 && l < width) {
                        r_sum += rgb[(k * width + l) * 3 + 0];
                        g_sum += rgb[(k * width + l) * 3 + 1];
                        b_sum += rgb[(k * width + l) * 3 + 2];
                        count++;
                    }
                }
            }

            blurred[(i * width + j) * 3 + 0] = r_sum / count;
            blurred[(i * width + j) * 3 + 1] = g_sum / count;
            blurred[(i * width + j) * 3 + 2] = b_sum / count;
        }
    }
}

// Save the image as a JPEG file
static int save_jpeg(unsigned char *image, int width, int height, char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        fprintf(stderr, "can't open %s\n", filename);
        return -1;
    }
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3; // RGB
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3; // RGB

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &image[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

int main() {
    int frame_index;
    char filename[64];
    time_t rawtime;
    struct tm *timeinfo;

