    }

    // Capture a frame
    frame_index = capture_frame(fd, buffers, NUM_BUFFERS);
    if (frame_index == -1) {
        fprintf(stderr, "Frame capture failed\n");
        goto cleanup;
    }

    // Convert YUYV to RGB24
    yuyv_to_rgb24(buffers[frame_index].start, rgb_buffer, image_width, image_height);

    // Apply box blur
