#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_fmtdesc fmtdesc;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_control control;
    struct v4l2_queryctrl queryctrl;
    int autofocus_supported = 0;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return 1;
    }

    // Query device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    printf("Device capabilities: 0x%08x\n", cap.capabilities);

    // Enumerate supported formats
    fmtdesc.index = 0;
    fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    printf("Supported formats:\n");
    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) == 0) {
        printf("  Format: %s\n", fmtdesc.description);
        fmtdesc.index++;
    }

    if (errno != EINVAL) {
        fprintf(stderr, "Error enumerating formats: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Enumerate supported frame sizes
    frmsize.index = 0;
    frmsize.pixel_format = V4L2_PIX_FMT_YUYV; // Example format, adjust as needed

    printf("Supported frame sizes:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        if (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);
        } else if (frmsize.type == V4L2_FRMSIZE_TYPE_CONTINUOUS) {
            printf("  %d-%dx%d\n", frmsize.stepwise.min_width, frmsize.stepwise.max_width, frmsize.stepwise.min_height, frmsize.stepwise.max_height);
        }
        frmsize.index++;
    }

    if (errno != EINVAL) {
        fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Enumerate supported frame intervals
    frmival.index = 0;
    frmival.pixel_format = V4L2_PIX_FMT_YUYV; // Example format, adjust as needed
    frmival.width = 640; // Example width, adjust as needed
    frmival.height = 480; // Example height, adjust as needed

    printf("Supported frame intervals:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
        if (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
            printf("  %d fps\n", (int)(1000000.0 / frmival.discrete.numerator) / frmival.discrete.denominator);
        } else if (frmival.type == V4L2_FRMIVAL_TYPE_CONTINUOUS) {
            printf("  %d-%d fps\n", (int)(1000000.0 / frmival.stepwise.min_numerator) / frmival.stepwise.min_denominator, (int)(1000000.0 / frmival.stepwise.max_numerator) / frmival.stepwise.max_denominator);
        }
        frmival.index++;
    }

    if (errno != EINVAL) {
        fprintf(stderr, "Error enumerating frame intervals: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Check for autofocus support
    queryctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == 0) {
        if (queryctrl.type == V4L2_CTRL_TYPE_BOOLEAN) {
            autofocus_supported = 1;
        }
    } else {
        if (errno != EINVAL) {
            fprintf(stderr, "Error querying control: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
    }

    printf("Autofocus supported: %s\n", autofocus_supported ? "Yes" : "No");

    close(fd);
    return 0;
}

