#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <curl/curl.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2.0 // seconds
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_QUALITY 85
#define MOTION_CAPTURE_DIR "motion_captures"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
CURL *curl = NULL;

// Structure to hold command-line arguments
typedef struct {
    char *server_ip;
    int server_port;
} ProgramArgs;

// Function prototypes
int initialize_pigpio();
int configure_gpio(int gpio_pin);
int read_sensor(int gpio_pin);
int capture_image(const char *filename);
int create_motion_captures_directory();
int send_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin, const char *server_ip, int server_port);
void signal_handler(int signal);
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size);

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to configure GPIO pin as input with pull-down resistor
int configure_gpio(int gpio_pin) {
    gpioSetMode(gpio_pin, PI_INPUT);
    gpioSetPullUpDown(gpio_pin, PI_PUD_DOWN);
    return 0;
}

// Function to read the sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s -n -q %d -w %d -h %d", filename, CAPTURE_QUALITY, CAPTURE_WIDTH, CAPTURE_HEIGHT);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing libcamera-still command\n");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still command failed with exit status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

// Function to create the motion_captures directory
int create_motion_captures_directory() {
    if (mkdir(MOTION_CAPTURE_DIR, 0777) == -1) {
        if (errno != EEXIST) {
            fprintf(stderr, "Error creating directory: %s\n", MOTION_CAPTURE_DIR);
            return -1;
        }
    }
    return 0;
}

// Function to send data to the server using libcurl
int send_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin, const char *server_ip, int server_port) {
    char json_payload[512];
    snprintf(json_payload, sizeof(json_payload), 
             "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": %d, \"gpio_pin\": %d}",
             filename, timestamp, motion_status, gpio_pin);

    char url[64];
    snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_payload));

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        return -1;
    }

    long response_code;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
    if (response_code != 200) {
        fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
        return -1;
    }

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "Signal received, exiting gracefully...\n");
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp_str + strlen(timestamp_str), timestamp_str_size - strlen(timestamp_str), ".%09ldZ", ts.tv_nsec);
    return timestamp_str;
}

int main(int argc, char *argv[]) {
    ProgramArgs args;

    // Parse command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    args.server_ip = argv[1];
    args.server_port = atoi(argv[2]);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Configure GPIO pin
    if (configure_gpio(GPIO_PIN) != 0) {
        gpioTerminate();
        return 1;
    }

    // Create motion_captures directory
    if (create_motion_captures_directory() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "libcurl initialization failed\n");
        gpioTerminate();
        curl_global_cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_motion_time = 0;
    int motion_detected = 0;

    // Main loop
    while (program_running) {
        int sensor_value = read_sensor(GPIO_PIN);

        if (sensor_value == 1) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_motion_time) >= DEBOUNCE_TIME) {
                // Motion detected
                motion_detected = 1;
                last_motion_time = current_time;

                // Generate filename
                char filename[128];
                snprintf(filename, sizeof(filename), "%s/motion_%ld.jpg", MOTION_CAPTURE_DIR, current_time);

                // Capture image
                if (capture_image(filename) == 0) {
                    // Get timestamp
                    char timestamp[32];
                    get_iso8601_timestamp(timestamp, sizeof(timestamp));

                    // Send data to server
                    if (send_data(filename, timestamp, 1, GPIO_PIN, args.server_ip, args.server_port) != 0) {
                        fprintf(stderr, "Failed to send data to server\n");
                    }
                } else {
                    fprintf(stderr, "Failed to capture image\n");
                }
            }
        } else {
            motion_detected = 0;
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Clean up
    curl_easy_cleanup(curl);
    curl_global_cleanup();
    gpioTerminate();

    return 0;
}

