#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>
#include <sys/wait.h>

// Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define CAPTURE_TIMEOUT_SEC 2

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int detect_motion(void);
int capture_image(const char *filename);
int log_event(const char *message);
void cleanup(void);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    log_event("Signal received, exiting...");
}

// Initialize GPIO
int init_gpio(void) {
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

