#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <unistd.h>

#define DEVICE_NAME "/dev/video0"
#define CROPPED_FILE "cropped.yuv"
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150

// Structure to hold device information
typedef struct {
    int fd;
    struct v4l2_buffer buf;
    void *buffer;
    size_t buffer_size;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
} device_info_t;

device_info_t device_info;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);
    if (device_info.fd != -1) {
        // Stop streaming
        if (ioctl(device_info.fd, VIDIOC_STREAMOFF, &device_info.fmt) == -1) {
            perror("VIDIOC_STREAMOFF");
        }

        // Unmap the buffer
        if (munmap(device_info.buffer, device_info.buffer_size) == -1) {
            perror("munmap");
        }

        // Close the device
        if (close(device_info.fd) == -1) {
            perror("close");
        }
    }
    exit(EXIT_SUCCESS);
}

// Function to initialize the V4L2 device
int init_device(device_info_t *info) {
    info->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (info->fd == -1) {
        perror("open");
        return -1;
    }

    if (ioctl(info->fd, VIDIOC_QUERYCAP, &info->cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        close(info->fd);
        return -1;
    }

    if (!(info->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(info->fd);
        return -1;
    }

    if (!(info->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(info->fd);
        return -1;
    }

    info->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    info->fmt.fmt.pix.width = 640;
    info->fmt.fmt.pix.height = 480;
    info->fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    info->fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(info->fd, VIDIOC_S_FMT, &info->fmt) == -1) {
        perror("VIDIOC_S_FMT");
        close(info->fd);
        return -1;
    }

    return 0;
}

// Function to allocate and map the buffer
int init_mmap(device_info_t *info) {
    struct v4l2_requestbuffers req;

    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(info->fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(info->fd);
        return -1;
    }

    memset(&info->buf, 0, sizeof(info->buf));
    info->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    info->buf.memory = V4L2_MEMORY_MMAP;
    info->buf.index = 0;

    if (ioctl(info->fd, VIDIOC_QUERYBUF, &info->buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        return -1;
    }

    info->buffer_size = info->buf.length;
    info->buffer = mmap(NULL, info->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, info->fd, info->buf.m.offset);
    if (info->buffer == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    return 0;
}

// Function to start streaming
int start_streaming(device_info_t *info) {
    if (ioctl(info->fd, VIDIOC_STREAMON, &info->fmt) == -1) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

// Function to capture a frame with timeout
int capture_frame(device_info_t *info) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(info->fd, &fds);

    tv.tv_sec = 2; // 2-second timeout
    tv.tv_usec = 0;

    r = select(info->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    if (ioctl(info->fd, VIDIOC_DQBUF, &info->buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    return 0;
}

// Function to verify the captured frame
int verify_frame(device_info_t *info) {
    if (info->buf.bytesused != info->fmt.fmt.pix.width * info->fmt.fmt.pix.height * 2) {
        fprintf(stderr, "Frame size mismatch\n");
        return -1;
    }

    if (info->fmt.fmt.pix.width != 640 || info->fmt.fmt.pix.height != 480) {
        fprintf(stderr, "Resolution mismatch\n");
        return -1;
    }

    if (info->fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Pixel format mismatch\n");
        return -1;
    }

    return 0;
}

// Function to crop the frame
void crop_frame(void *src, void *dst, int crop_x, int crop_y, int crop_width, int crop_height, int src_width) {
    unsigned char *src_ptr = (unsigned char *)src;
    unsigned char *dst_ptr = (unsigned char *)dst;
    int i, j;

    for (i = 0; i < crop_height; i++) {
        for (j = 0; j < crop_width; j++) {
            // Calculate the source index
            int src_index = ((crop_y + i) * src_width + (crop_x + j)) * 2; // YUYV, so *2
            // Copy the 4 bytes (Y0, U, Y1, V)
            memcpy(dst_ptr, &src_ptr[src_index], 4);
            dst_ptr += 4; // Move to the next macroblock in the destination
        }
    }
}

// Function to save the cropped frame to a file
int save_cropped_frame(void *cropped_frame, int width, int height) {
    FILE *fp = fopen(CROPPED_FILE, "wb");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    size_t bytes_written = fwrite(cropped_frame, 1, width * height * 2, fp);
    if (bytes_written != width * height * 2) {
        fprintf(stderr, "fwrite error: wrote %zu bytes, expected %d\n", bytes_written, width * height * 2);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) == EOF) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the device
    if (init_device(&device_info) == -1) {
        return EXIT_FAILURE;
    }

    // Initialize memory mapping
    if (init_mmap(&device_info) == -1) {
        close(device_info.fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(&device_info) == -1) {
        munmap(device_info.buffer, device_info.buffer_size);
        close(device_info.fd);
        return EXIT_FAILURE;
    }

    // Capture a frame
    if (capture_frame(&device_info) == -1) {
        ioctl(device_info.fd, VIDIOC_STREAMOFF, &device_info.fmt);
        munmap(device_info.buffer, device_info.buffer_size);
        close(device_info.fd);
        return EXIT_FAILURE;
    }

    // Verify the frame
    if (verify_frame(&device_info) == -1) {
        ioctl(device_info.fd, VIDIOC_STREAMOFF, &device_info.fmt);
        munmap(device_info.buffer, device_info.buffer_size);
        close(device_info.fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for the cropped frame
    unsigned char *cropped_frame = (unsigned char *)malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (cropped_frame == NULL) {
        perror("malloc");
        ioctl(device_info.fd, VIDIOC_STREAMOFF, &device_info.fmt);
        munmap(device_info.buffer, device_info.buffer_size);
        close(device_info.fd);
        return EXIT_FAILURE;
    }

    // Crop the frame
    crop_frame(device_info.buffer, cropped_frame, CROP_X, CROP_Y, CROP_WIDTH, CROP_HEIGHT, device_info.fmt.fmt.pix.width);

    // Save the cropped frame to a file
    if (save_cropped_frame(cropped_frame, CROP_WIDTH, CROP_HEIGHT) == -1) {
        free(cropped_frame);
        ioctl(device_info.fd, VIDIOC_STREAMOFF, &device_info.fmt);
        munmap(device_info.buffer, device_info.buffer_size);
        close(device_info.fd);
        return EXIT_FAILURE;
    }

    // Clean up
    free(cropped_frame);
    ioctl(device_info.fd, VIDIOC_STREAMOFF, &device_info.fmt);
    munmap(device_info.buffer, device_info.buffer_size);
    close(device_info.fd);

    printf("Cropped frame saved to %s\n", CROPPED_FILE);

    return EXIT_SUCCESS;
}

