#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define angle limits
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define PWM frequency and pulse width limits
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define angle increment
#define ANGLE_INCREMENT 5

// Global variables for pan and tilt angles
int pan_angle = 90;
int tilt_angle = 90;

// Function prototypes
int angle_to_pulse_width(int angle);
void set_servo_angle(int gpio, int angle);
void handle_input(char input);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, setting servos to neutral position...\n", signal);
    set_servo_angle(PAN_GPIO, 90);
    set_servo_angle(TILT_GPIO, 90);
    gpioTerminate();
    exit(0);
}

// Function to convert angle to pulse width
int angle_to_pulse_width(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d). Must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1; // Indicate an error
    }
    return (int)(((float)(angle) / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);
}

// Function to set servo angle
void set_servo_angle(int gpio, int angle) {
    int pulse_width = angle_to_pulse_width(angle);
    if (pulse_width == -1) {
        return; // Don't set the servo if the angle is invalid
    }

    if (gpioServo(gpio, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width for GPIO %d.\n", gpio);
    }
}

// Function to handle user input
void handle_input(char input) {
    switch (input) {
        case 'w': // Up
            tilt_angle -= ANGLE_INCREMENT;
            if (tilt_angle < MIN_ANGLE) {
                tilt_angle = MIN_ANGLE;
            }
            break;
        case 's': // Down
            tilt_angle += ANGLE_INCREMENT;
            if (tilt_angle > MAX_ANGLE) {
                tilt_angle = MAX_ANGLE;
            }
            break;
        case 'a': // Left
            pan_angle -= ANGLE_INCREMENT;
            if (pan_angle < MIN_ANGLE) {
                pan_angle = MIN_ANGLE;
            }
            break;
        case 'd': // Right
            pan_angle += ANGLE_INCREMENT;
            if (pan_angle > MAX_ANGLE) {
                pan_angle = MAX_ANGLE;
            }
            break;
        case 'q':
            printf("Exiting...\n");
            set_servo_angle(PAN_GPIO, 90);
            set_servo_angle(TILT_GPIO, 90);
            gpioTerminate();
            exit(0);
            break;
        default:
            printf("Invalid input. Use 'w', 'a', 's', 'd' to move, 'q' to quit.\n");
            break;
    }

    set_servo_angle(PAN_GPIO, pan_angle);
    set_servo_angle(TILT_GPIO, tilt_angle);
    usleep(100000); // 100 ms delay
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for pan and tilt servos
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency for pan and tilt servos
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    // Set initial servo positions
    set_servo_angle(PAN_GPIO, 90);
    set_servo_angle(TILT_GPIO, 90);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop to read user input
    char input;
    printf("Use 'w', 'a', 's', 'd' to move, 'q' to quit.\n");
    while (1) {
        input = getchar();
        handle_input(input);
    }

    return 0;
}

