// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_cpu_temp();
float calculate_cpu_usage();
void oled_init();
void oled_clear();
void oled_draw_char(int x, int y, char c);
void oled_draw_string(int x, int y, const char *str);
void oled_update();
void signal_handler(int signal);

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    float temp = -1.0f;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1.0f;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temp = atoi(buffer) / 1000.0f;
    } else {
        fprintf(stderr, "Error reading temperature from file: %s\n", strerror(errno));
        fclose(fp);
        return -1.0f;
    }

    fclose(fp);
    return temp;
}

// Function to calculate CPU usage from /proc/stat
float calculate_cpu_usage() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    float usage = 0.0f;

    // Read initial CPU stats
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return 0.0f;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return 0.0f;
    }
    fclose(fp);

    // Wait for 1 second
    sleep(1);

    // Read CPU stats again
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return 0.0f;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return 0.0f;
    }
    fclose(fp);

    // Calculate deltas
    unsigned long long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;

    unsigned long long delta_total = total - prev_total;
    unsigned long long delta_idle = idle - prev_idle;

    // Calculate usage
    usage = 100.0f * (1.0f - (float)delta_idle / (float)delta_total);

    return usage;
}

// Function to initialize the OLED display
void oled_init() {
    // Initialization sequence (SSD1306)
    char init_commands[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio (0x80 = 100Hz)
        0xA8, 0x3F, // Multiplex ratio (63 = 64 rows)
        0xD3, 0x00, // Display offset
        0x40,       // Start line
        0x8D, 0x14, // Charge pump setting (0x14 = enable)
        0x20, 0x00, // Memory addressing mode (0x00 = horizontal)
        0xA1,       // Segment remap
        0xC8,       // COM scan direction
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Precharge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF (0xA4 = normal, 0xA5 = all ON)
        0xA6,       // Normal/Inverse display (0xA6 = normal, 0xA7 = inverse)
        0xAF        // Display on
    };

    for (int i = 0; i < sizeof(init_commands); i++) {
        if (i2cWriteByteData(i2c_handle, 0x00, init_commands[i]) < 0) {
