    int current_y = y;

    while (*str) {
        oled_draw_char(current_x, current_y, *str);
        current_x += 6; // Character width + 1 pixel spacing
        str++;
    }
}

// Function to update the OLED display
void oled_update() {
    // No explicit update function needed with SSD1306 in this implementation.
    // The display is updated whenever data is written to it.
