#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for the water flow sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Define I2C parameters for the LCD
#define I2C_BUS 1
#define LCD_ADDR 0x27

// Define LCD dimensions
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Define pulse calibration factor (pulses per liter)
#define PULSES_PER_LITER 450.0

// Global variables
volatile int sensor1_pulse_count = 0;
volatile int sensor2_pulse_count = 0;
double total_volume1 = 0.0;
double total_volume2 = 0.0;
int i2c_handle;

// Function prototypes
void sensor1_isr(int gpio, int level, uint32_t tick, void *user);
void sensor2_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_flow_rate(int pulse_count);
void log_data(double flow_rate1, double flow_rate2, double total_volume1, double total_volume2);
void update_lcd(double flow_rate1, double total_volume1, double flow_rate2, double total_volume2);
void signal_handler(int signal);

// LCD command functions
void lcd_init();
void lcd_clear();
void lcd_set_cursor(int row, int col);
void lcd_write_string(const char *str);

// Helper function to send data to the LCD
void lcd_send_data(unsigned char data);

// Helper function to send command to the LCD
void lcd_send_command(unsigned char command);

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Set up interrupt handlers for the water flow sensors
    if (gpioSetISRFuncEx(SENSOR1_GPIO, RISING_EDGE, 0, sensor1_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for sensor 1\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(SENSOR2_GPIO, RISING_EDGE, 0, sensor2_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for sensor 2\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C communication
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the LCD
    lcd_init();

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Calculate flow rates
        double flow_rate1 = calculate_flow_rate(sensor1_pulse_count);
        double flow_rate2 = calculate_flow_rate(sensor2_pulse_count);

        // Update total volumes
        total_volume1 += flow_rate1 / 60.0; // Convert LPM to L/s and add to total
        total_volume2 += flow_rate2 / 60.0;

        // Log data to the console
        log_data(flow_rate1, flow_rate2, total_volume1, total_volume2);

        // Update LCD every 10 seconds
        if (time(NULL) % 10 == 0) {
            update_lcd(flow_rate1, total_volume1, flow_rate2, total_volume2);
        }

        // Reset pulse counts
        sensor1_pulse_count = 0;
        sensor2_pulse_count = 0;

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

// Interrupt service routine for sensor 1
void sensor1_isr(int gpio, int level, uint32_t tick, void *user) {
    sensor1_pulse_count++;
}

// Interrupt service routine for sensor 2
void sensor2_isr(int gpio, int level, uint32_t tick, void *user) {
    sensor2_pulse_count++;
}

// Function to calculate flow rate in liters per minute
double calculate_flow_rate(int pulse_count) {
    return (double)pulse_count / PULSES_PER_LITER * 60.0;
}

// Function to log data to the console
