#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_ADDR 0x27
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ANEMOMETER_GPIO 17
#define WIND_VANE_CHANNEL 0
#define WIND_SPEED_SCALE 0.5 // m/s per pulse
#define SAMPLE_INTERVAL 500 // ms
#define ADC_MIN 0
#define ADC_MAX 1023
#define DEGREES_MIN 0
#define DEGREES_MAX 359

// Global variables
static volatile int pulse_count = 0;
static int i2c_handle;
static int spi_handle;
static volatile int running = 1;

// Function prototypes
void anemometer_isr(int gpio, int level, uint32_t tick, void *user);
int read_mcp3008(int channel);
float calculate_wind_speed(int pulse_count);
float calculate_wind_direction(int adc_value);
void display_data(float wind_speed, float wind_direction);
void signal_handler(int signal);

// Anemometer interrupt service routine
void anemometer_isr(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char spi_data[3];
    int adc_value;

    // Construct SPI message
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    spi_data[2] = 0x00;

    // Transfer SPI data
    if (spiXfer(spi_handle, spi_data, spi_data, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value
    adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];

    return adc_value;
}

// Function to calculate wind speed
float calculate_wind_speed(int pulse_count) {
    return (float)pulse_count * WIND_SPEED_SCALE;
}

// Function to calculate wind direction
float calculate_wind_direction(int adc_value) {
    return ((float)adc_value / ADC_MAX) * (DEGREES_MAX - DEGREES_MIN) + DEGREES_MIN;
}

// Function to display data on LCD (Placeholder - implement LCD control)
void display_data(float wind_speed, float wind_direction) {
    // This is a placeholder.  You'll need to implement the LCD control
    // using pigpio's I2C functions to communicate with the PCF8574.
    // For example, you might use i2cWriteByteData to send commands and data.
    // This example just prints to stdout for demonstration.
    printf("Wind Speed: %.2f m/s, Wind Direction: %.2f degrees\n", wind_speed, wind_direction);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x27, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open SPI connection
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set anemometer GPIO as input with pull-down resistor
    gpioSetMode(ANEMOMETER_GPIO, PI_INPUT);
    gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_DOWN);

    // Set interrupt handler for anemometer
    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR for anemometer\n");
        spiClose(spi_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read wind vane ADC value
        int adc_value = read_mcp3008(WIND_VANE_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            // Continue to the next iteration even if ADC read fails
        }

        // Calculate wind speed and direction
        float wind_speed = calculate_wind_speed(pulse_count);
        float wind_direction = calculate_wind_direction(adc_value);

        // Display data
        display_data(wind_speed, wind_direction);

        // Reset pulse count for the next sample interval
        pulse_count = 0;

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Close I2C and SPI connections
    i2cClose(i2c_handle);
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

