#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"

// Row GPIO pins (anodes)
const int row_pins[] = {17, 18, 27, 22, 23, 24, 25, 4};
// Column GPIO pins (cathodes)
const int col_pins[] = {5, 6, 12, 13, 19, 16, 26, 20};

// Number of rows and columns
const int num_rows = sizeof(row_pins) / sizeof(row_pins[0]);
const int num_cols = sizeof(col_pins) / sizeof(col_pins[0]);

// Wave pattern data
const int wave_pattern[] = {0x00, 0x80, 0xC0, 0xE0, 0xF0, 0xF8, 0xFC, 0xFE};
const int wave_pattern_size = sizeof(wave_pattern) / sizeof(wave_pattern[0]);

// Global variables for GPIO lines and chip
struct gpiod_line *row_lines[num_rows];
struct gpiod_line *col_lines[num_cols];
struct gpiod_chip *gpio_chip = NULL;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize GPIO lines
int initialize_gpio() {
    int i;

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    // Open row GPIO lines
    for (i = 0; i < num_rows; i++) {
        row_lines[i] = gpiod_chip_get_line(gpio_chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Error getting row GPIO line %d\n", row_pins[i]);
            perror("gpiod_chip_get_line");
            goto cleanup;
        }
    }

    // Open column GPIO lines
    for (i = 0; i < num_cols; i++) {
        col_lines[i] = gpiod_chip_get_line(gpio_chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Error getting column GPIO line %d\n", col_pins[i]);
            perror("gpiod_chip_get_line");
            goto cleanup;
        }
    }

    // Request row GPIO lines for output
    for (i = 0; i < num_rows; i++) {
        if (gpiod_line_request_output(row_lines[i], "wave_animation", 0) < 0) {
            fprintf(stderr, "Error requesting row GPIO line %d for output\n", row_pins[i]);
            perror("gpiod_line_request_output");
            goto cleanup;
        }
    }

    // Request column GPIO lines for output
    for (i = 0; i < num_cols; i++) {
        if (gpiod_line_request_output(col_lines[i], "wave_animation", 0) < 0) {
            fprintf(stderr, "Error requesting column GPIO line %d for output\n", col_pins[i]);
            perror("gpiod_line_request_output");
            goto cleanup;
        }
    }

    return 0;

cleanup:
    // Cleanup in case of error
    for (i = 0; i < num_rows; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
        }
    }
    for (i = 0; i < num_cols; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
        }
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    return -1;
}

// Function to set the state of a GPIO line
void set_gpio_line(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO line value\n");
        perror("gpiod_line_set_value");
    }
}

// Function to display a frame on the LED matrix
void display_frame(const int *frame_data) {
    int i, j;

    // Set row HIGH and column LOW to light an LED (common-anode logic)
    for (i = 0; i < num_rows; i++) {
        set_gpio_line(row_lines[i], 1); // Set row HIGH
        for (j = 0; j < num_cols; j++) {
            if ((frame_data[i] >> j) & 1) {
                set_gpio_line(col_lines[j], 0); // Set column LOW
            } else {
                set_gpio_line(col_lines[j], 1); // Set column HIGH
            }
        }
        usleep(800); // Scan delay
        for (j = 0; j < num_cols; j++) {
            set_gpio_line(col_lines[j], 1); // Turn off all columns
        }
        set_gpio_line(row_lines[i], 0); // Set row LOW
    }
}

// Function to shift the wave pattern left
void shift_left(int *pattern) {
    int temp = pattern[0];
    for (int i = 0; i < wave_pattern_size - 1; i++) {
        pattern[i] = pattern[i + 1];
    }
    pattern[wave_pattern_size - 1] = temp;
}

// Function to shift the wave pattern right
void shift_right(int *pattern) {
    int temp = pattern[wave_pattern_size - 1];
    for (int i = wave_pattern_size - 1; i > 0; i--) {
        pattern[i] = pattern[i - 1];
    }
    pattern[0] = temp;
}

// Function to cleanup GPIO lines
void cleanup_gpio() {
    int i;

    // Release GPIO lines
    for (i = 0; i < num_rows; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
        }
    }
    for (i = 0; i < num_cols; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
        }
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    int i;
    int current_pattern[wave_pattern_size];
    int direction = 1; // 1 for left, -1 for right

    // Install signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize wave pattern
    for (i = 0; i < wave_pattern_size; i++) {
        current_pattern[i] = wave_pattern[i];
    }

    // Main loop
    while (!terminate) {
        // Display the current frame
        display_frame(current_pattern);

        // Shift the wave pattern
        if (direction == 1) {
            shift_left(current_pattern);
        } else {
            shift_right(current_pattern);
        }

        // Change direction every 5 seconds
        if (rand() % 10 == 0) {
            direction *= -1;
        }
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

