#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for rows and columns
const int row_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int col_pins[] = {14, 15, 18, 23, 24, 25, 8, 7};
const int num_pins = 8;

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *row_lines[8];
struct gpiod_line *col_lines[8];

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Set all pins to input (safe state)
    for (int i = 0; i < num_pins; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
        }
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
        }
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request row pins as outputs
    for (int i = 0; i < num_pins; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            perror("Error getting row line");
            return -1;
        }

        struct gpiod_line_request_config config;
        config.consumer = "led_matrix";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(row_lines[i], &config, 0) < 0) {
            perror("Error requesting row line as output");
            return -1;
        }
    }

    // Request column pins as outputs
    for (int i = 0; i < num_pins; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            perror("Error getting column line");
            return -1;
        }

        struct gpiod_line_request_config config;
        config.consumer = "led_matrix";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(col_lines[i], &config, 0) < 0) {
            perror("Error requesting column line as output");
            return -1;
        }
    }

    return 0;
}

// Function to clear the LED matrix
void clear_matrix() {
    for (int i = 0; i < num_pins; i++) {
        if (gpiod_line_set_value(col_lines[i], 1) < 0) {
