    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance_mm,Distance_mm\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, attempting to re-open I2C\n");
            i2cClose(i2c_handle);
