#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define COMMAND_REG 0x18
#define ALS_VIS_DATA0 0x22
#define ALS_IR_DATA0 0x24
#define PS1_DATA0 0x26
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_si1145_data(int *proximity, int *ambient_light);
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int init_si1145() {
    // Verify PART ID
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART ID: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    // Initialize the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x00) < 0) { // Reset
        fprintf(stderr, "Error writing to COMMAND register (reset): %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Wait for reset

    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x01) < 0) { // PS1_ADCMUX = Large IR
        fprintf(stderr, "Error writing to COMMAND register (PS1_ADCMUX): %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x02) < 0) { // PS2_ADCMUX = Large IR
        fprintf(stderr, "Error writing to COMMAND register (PS2_ADCMUX): %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x03) < 0) { // PS3_ADCMUX = Large IR
        fprintf(stderr, "Error writing to COMMAND register (PS3_ADCMUX): %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x0F) < 0) { // MEAS_RATE = 8
        fprintf(stderr, "Error writing to COMMAND register (MEAS_RATE): %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x07) < 0) { // ALS_RATE = 8
        fprintf(stderr, "Error writing to COMMAND register (ALS_RATE): %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x0D) < 0) { // PS_RATE = 8
        fprintf(stderr, "Error writing to COMMAND register (PS_RATE): %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x0B) < 0) { // PS_LED21_SELECT = LED2
        fprintf(stderr, "Error writing to COMMAND register (PS_LED21_SELECT): %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x0A) < 0) { // PS_LED3_SELECT = LED3
        fprintf(stderr, "Error writing to COMMAND register (PS_LED3_SELECT): %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x0C) < 0) { // PS_LED12_SELECT = LED1
        fprintf(stderr, "Error writing to COMMAND register (PS_LED12_SELECT): %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x0E) < 0) { // PS_LED_SELECT = LED1
        fprintf(stderr, "Error writing to COMMAND register (PS_LED_SELECT): %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x0F) < 0) { // PS_EN = Enable
        fprintf(stderr, "Error writing to COMMAND register (PS_EN): %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x10) < 0) { // ALS_EN = Enable
        fprintf(stderr, "Error writing to COMMAND register (ALS_EN): %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x11) < 0) { // PS_EN = Enable
        fprintf(stderr, "Error writing to COMMAND register (PS_EN): %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read proximity and ambient light data from the Si1145 sensor
int read_si1145_data(int *proximity, int *ambient_light) {
    int als_vis_low, als_vis_high, als_ir_low, als_ir_high, ps1_low, ps1_high;

    als_vis_low = i2cReadByteData(i2c_handle, ALS_VIS_DATA0);
    als_vis_high = i2cReadByteData(i2c_handle, ALS_VIS_DATA0 + 1);
    als_ir_low = i2cReadByteData(i2c_handle, ALS_IR_DATA0);
    als_ir_high = i2cReadByteData(i2c_handle, ALS_IR_DATA0 + 1);
    ps1_low = i2cReadByteData(i2c_handle, PS1_DATA0);
    ps1_high = i2cReadByteData(i2c_handle, PS1_DATA0 + 1);

    if (als_vis_low < 0 || als_vis_high < 0 || als_ir_low < 0 || als_ir_high < 0 || ps1_low < 0 || ps1_high < 0) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    *ambient_light = (als_ir_high << 8) | als_ir_low;
    *proximity = (ps1_high << 8) | ps1_low;

    return 0;
}

// Log data to file with ISO-8601 timestamp
void log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_si1145() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    int proximity, ambient_light;

    // Main loop
    while (!terminate) {
        if (read_si1145_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Failed to read sensor data, continuing...\n");
        }

        gpioDelay(500); // Sample every 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

