#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_PIN 4
#define LED_PIN 17

// Define GPIO chip names
#define GPIOCHIP4 "gpiochip4"
#define GPIOCHIP0 "gpiochip0"

// Define log file name
#define LOG_FILE "proximity.log"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int open_gpio_chip(const char *chip_name);
int open_gpio_line(struct gpiod_chip *chip, int pin, int direction);
int read_sensor(struct gpiod_line *line);
int control_led(struct gpiod_line *line, int value);
int log_event(const char *message);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Function to open a GPIO chip
int open_gpio_chip(const char *chip_name) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Error opening GPIO chip");
        return NULL;
    }
    return chip;
}

// Function to open a GPIO line
int open_gpio_line(struct gpiod_chip *chip, int pin, int direction) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        return NULL;
    }

    int ret;
    if (direction == GPIOD_LINE_REQUEST_DIRECTION_INPUT) {
        ret = gpiod_line_request(line, NULL, direction);
    } else {
        ret = gpiod_line_request(line, NULL, direction);
    }

    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        return NULL;
    }

    return line;
}

// Function to read the sensor value
