#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_KEY_REG 0x07
#define CH_LIST_REG 0x4F
#define COMMAND_REG 0x30
#define PS1_REG 0x18
#define ALS_VIS_REG 0x22

#define ALS_FORCE 0x06
#define PS_FORCE 0x07

#define LOG_FILE "biometric_data.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_si1145_data(int *proximity, int *ambient_light);
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int init_si1145() {
    int status;

    // Verify PART_ID
    status = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", status);
        return -1;
    }
    if (status != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02x\n", status);
        return -1;
    }

    // Write HW_KEY
    status = i2cWriteByteData(i2c_handle, HW_KEY_REG, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error writing HW_KEY: %d\n", status);
        return -1;
    }

    // Set CH_LIST
    status = i2cWriteByteData(i2c_handle, CH_LIST_REG, 0x03); // Enable PS1 and ALS_VIS
    if (status < 0) {
        fprintf(stderr, "Error writing CH_LIST: %d\n", status);
        return -1;
    }

    return 0;
}

// Read proximity and ambient light data from the Si1145 sensor
int read_si1145_data(int *proximity, int *ambient_light) {
    int status;
    uint8_t data[4];

    // Trigger ALS measurement
    status = i2cWriteByteData(i2c_handle, COMMAND_REG, ALS_FORCE);
    if (status < 0) {
        fprintf(stderr, "Error writing COMMAND (ALS_FORCE): %d\n", status);
        return -1;
    }
    gpioDelay(10); // Small delay for measurement

    // Trigger PS measurement
    status = i2cWriteByteData(i2c_handle, COMMAND_REG, PS_FORCE);
    if (status < 0) {
        fprintf(stderr, "Error writing COMMAND (PS_FORCE): %d\n", status);
        return -1;
    }
    gpioDelay(10); // Small delay for measurement

    // Read PS1 data
    status = i2cReadI2CBlockData(i2c_handle, PS1_REG, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading PS1 data: %d\n", status);
        return -1;
    }
    *proximity = (data[1] << 8) | data[0];

    // Read ALS_VIS data
    status = i2cReadI2CBlockData(i2c_handle, ALS_VIS_REG, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading ALS_VIS data: %d\n", status);
        return -1;
    }
    *ambient_light = (data[1] << 8) | data[0];

    return 0;
}

// Log data to a CSV file
void log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Flush the buffer to ensure data is written immediately
}

int main() {
    int proximity, ambient_light;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_si1145_data(&proximity, &ambient_light) == 0) {
            // Log data
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

