#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 30000      // 30ms timeout
#define MIN_DISTANCE 2       // cm
#define MAX_DISTANCE 400     // cm
#define REMINDER_THRESHOLD 15 // cm

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold timestamp data
typedef struct {
    struct timespec start;
    struct timespec end;
} Timestamps;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_sensor();
long long measure_pulse_width(Timestamps *timestamps);
double calculate_distance(long long pulse_width);
void log_data(double distance, const char *message);
void log_error(const char *message);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); // Wait 1ms

    return 0;
}

// Generate a 10us trigger pulse
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the echo pulse width using edge events
long long measure_pulse_width(Timestamps *timestamps) {
    long long start_time = 0, end_time = 0;
    int start_sec, start_micros, end_sec, end_micros;

    // Wait for the echo pin to go high (rising edge)
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        log_error("Timeout waiting for rising edge.");
        return -1; // Indicate timeout
    }

    clock_gettime(CLOCK_MONOTONIC, &timestamps->start);
    start_sec = timestamps->start.tv_sec;
    start_micros = timestamps->start.tv_nsec / 1000;

    // Wait for the echo pin to go low (falling edge)
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        log_error("Timeout waiting for falling edge.");
        return -1; // Indicate timeout
    }

    clock_gettime(CLOCK_MONOTONIC, &timestamps->end);
    end_sec = timestamps->end.tv_sec;
    end_micros = timestamps->end.tv_nsec / 1000;

    // Calculate pulse width in microseconds
    start_time = (long long)start_sec * 1000000 + start_micros;
    end_time = (long long)end_sec * 1000000 + end_micros;

    return end_time - start_time;
}

// Calculate distance in centimeters
double calculate_distance(long long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Log data to file with ISO-8601 timestamp
void log_data(double distance, const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, %s\n", timestamp, distance, message);
    fflush(log_file); // Ensure data is written to disk
}

// Log error messages to file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
    gpioTerminate();           // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file); // Close log file
    }
}

int main() {
    // Set up signal handling for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_error("GPIO initialization failed. Exiting.");
        cleanup();
        return 1;
    }

    printf("Plant watering reminder system started. Press Ctrl+C to exit.\n");

    Timestamps timestamps;

    while (running) {
        trigger_sensor();
        long long pulse_width = measure_pulse_width(&timestamps);

