int i2c_fd = -1;
FILE *csv_file = NULL;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int configure_sensor(int fd);
int read_proximity_data(int fd);
int calculate_bpm(int proximity);
int log_data(FILE *fp, int bpm);
void signal_handler(int sig);

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Sensor configuration function
int configure_sensor(int fd) {
    // Verify PART_ID
    int part_id = i2c_read_reg(fd, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID register.\n");
        return -1;
    }
    if (part_id != 0x82) { // Expected Si1182 part ID
        fprintf(stderr, "Incorrect PART_ID: 0x%02X (expected 0x82)\n", part_id);
        return -1;
    }

    // Configure continuous proximity measurement
    if (i2c_write_reg(fd, MEAS_RATE0_REG, MEASUREMENT_RATE) < 0) {
        fprintf(stderr, "Failed to write MEAS_RATE0 register.\n");
        return -1;
    }

    // Reset and start the sensor
    if (i2c_write_reg(fd, COMMAND_REG, RESET_START_CMD) < 0) {
        fprintf(stderr, "Failed to write COMMAND register.\n");
        return -1;
    }

    return 0;
}

// Read proximity data function
int read_proximity_data(int fd) {
    int ps_data0 = i2c_read_reg(fd, PS_DATA0_REG);
    int ps_data1 = i2c_read_reg(fd, PS_DATA1_REG);

    if (ps_data0 < 0 || ps_data1 < 0) {
        fprintf(stderr, "Failed to read proximity data registers.\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit value (little-endian)
    int proximity = (ps_data1 << 8) | ps_data0;
    return proximity;
}

