    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (fprintf(fp, "%s,%d\n", buf, bpm) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }

