// Function to read the distance from the VL53L0X sensor
int read_distance(uint16_t *distance) {
    uint8_t status;
    uint8_t range_status;
    uint8_t buffer[2];
    uint32_t start_tick, current_tick;

    // Start a single measurement
    if (write_register(i2c_handle, SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting range measurement\n");
        return -1;
    }

    // Wait for the measurement to complete (with timeout)
    start_tick = gpioTick();
    do {
        if (read_register(i2c_handle, RESULT_INTERRUPT_STATUS, &status) != 0) {
            fprintf(stderr, "Error reading interrupt status\n");
            return -1;
        }
        if (status & 0x01) break; // Check bit 0

        current_tick = gpioTick();
        if ((current_tick - start_tick) > (TIMEOUT_MS * 1000)) {
            fprintf(stderr, "Timeout waiting for measurement\n");
            return -1;
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    } while (1);

    // Read the range status
    if (read_register(i2c_handle, RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read the distance data
    if (i2cWriteDevice(i2c_handle, (char[]){0x14}, 1) != 1) {
        fprintf(stderr, "Error writing register address for distance read\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)buffer, 2) != 2) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    // Extract the distance
    *distance = (buffer[0] << 8) | buffer[1];

    // Clear the interrupt
    if (write_register(i2c_handle, SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }

    return 0;
}

// Function to log the distance to a file
void log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick) {
    uint16_t distance;

    if (level == FALLING_EDGE) {
        if (read_distance(&distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Error reading distance in interrupt handler\n");
        }
    }
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input with pull-up
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set interrupt handler
    gpioSetAlertFuncEx(GPIO_PIN, interrupt_handler, NULL);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep to reduce CPU usage
    }

    // Cleanup
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable interrupt handler
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

