    if (result < 0) {
        fprintf(stderr, "Failed to read distance: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *distance_mm = (buffer[0] << 8) | buffer[1];
    return 0;
}

