    if (open_i2c_connection() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int distance_mm;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() == 0) {
            // Read distance
            if (read_distance(&distance_mm) == 0) {
                // Log distance
                log_distance(distance_mm);

                // Print to stdout
                printf("Distance: %d mm\n", distance_mm);
            } else {
                fprintf(stderr, "Failed to read distance. Retrying.\n");
            }
        } else {
            fprintf(stderr, "Failed to trigger measurement. Retrying.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

