#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define PROXIMITY_REGISTER 0x18
#define AMBIENT_LIGHT_REGISTER 0x16
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int handle, uint16_t *proximity, uint16_t *ambient_light);
int log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to read sensor data with retries
int read_sensor_data(int handle, uint16_t *proximity, uint16_t *ambient_light) {
    int result;
    int retries = 0;

    // Read proximity data
    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(handle, PROXIMITY_REGISTER);
        if (result >= 0) {
            *proximity = (uint16_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading proximity data (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read proximity data after %d retries.\n", RETRY_COUNT);
        return -1; // Indicate failure
    }

    retries = 0;
    // Read ambient light data
    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(handle, AMBIENT_LIGHT_REGISTER);
        if (result >= 0) {
            *ambient_light = (uint16_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading ambient light data (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read ambient light data after %d retries.\n", RETRY_COUNT);
        return -1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to log data to file
int log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

int main() {
    uint16_t proximity, ambient_light;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        result = read_sensor_data(i2c_handle, &proximity, &ambient_light);
        if (result == 0) {
            // Log data
            if (log_data(log_file, proximity, ambient_light) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(500000); // 500 ms delay
    }

    // Clean up resources
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

