#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x50
#define COMMAND_LENGTH 4
#define RESPONSE_LENGTH 15
#define SAMPLES_PER_CYCLE 10
#define INTRUSION_THRESHOLD 1000 // mm
#define LOG_FILE "intrusion_log.txt"
#define SLEEP_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write(int fd, unsigned char addr, unsigned char *data, int length);
int i2c_read(int fd, unsigned char addr, unsigned char *data, int length);
int request_distance_measurement(int fd);
int read_distance_response(int fd, unsigned char *data);
unsigned short parse_distance(const unsigned char *data);
float calculate_average_distance(unsigned short *distances, int num_samples);
void log_intrusion(float average_distance);
void signal_handler(int signal);

// I2C write function
int i2c_write(int fd, unsigned char addr, unsigned char *data, int length) {
    unsigned char buffer[length + 1];
    buffer[0] = addr;
    memcpy(buffer + 1, data, length);

    if (write(fd, buffer, length + 1) != length + 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char addr, unsigned char *data, int length) {
    if (write(fd, &addr, 1) != 1) {
        perror("I2C address write failed");
        return -1;
    }
    if (read(fd, data, length) != length) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Request distance measurement
int request_distance_measurement(int fd) {
    unsigned char command[COMMAND_LENGTH] = {0x50, 0x0A, 0x00, 0x01};
    if (i2c_write(fd, SENSOR_ADDRESS, command, COMMAND_LENGTH) != 0) {
        fprintf(stderr, "Failed to request distance measurement\n");
        return -1;
    }
    usleep(10000); // 10 ms
    return 0;
}

// Read distance response
int read_distance_response(int fd, unsigned char *data) {
    if (i2c_read(fd, SENSOR_ADDRESS, data, RESPONSE_LENGTH) != 0) {
        fprintf(stderr, "Failed to read distance response\n");
        return -1;
    }
    return 0;
}

// Parse distance from response
unsigned short parse_distance(const unsigned char *data) {
    if (data[0] != 0x50) {
        fprintf(stderr, "Invalid response header\n");
        return 0; // Indicate error
    }
    return (data[11] << 8) | data[12];
}

// Calculate average distance
float calculate_average_distance(unsigned short *distances, int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return sum / num_samples;
}

// Log intrusion event
void log_intrusion(float average_distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Intrusion detected! Average distance: %.2f mm\n", timestamp, average_distance);
    fflush(log_file); // Ensure data is written to disk
    printf("%s - Intrusion detected! Average distance: %.2f mm\n", timestamp, average_distance);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        unsigned short distances[SAMPLES_PER_CYCLE];
        int valid_samples = 0;

        for (int i = 0; i < SAMPLES_PER_CYCLE; i++) {
            unsigned char response[RESPONSE_LENGTH];

            if (request_distance_measurement(i2c_fd) == 0) {
                if (read_distance_response(i2c_fd, response) == 0) {
                    unsigned short distance = parse_distance(response);
                    if (distance > 0) { // Basic validation
                        distances[valid_samples++] = distance;
                    }
                }
            }
            usleep(SLEEP_MS * 1000); // 100 ms delay
        }

        if (valid_samples > 0) {
            float average_distance = calculate_average_distance(distances, valid_samples);
            printf("Average distance: %.2f mm\n", average_distance);

            if (average_distance < INTRUSION_THRESHOLD) {
                log_intrusion(average_distance);
            }
        } else {
            fprintf(stderr, "No valid distance samples received\n");
        }
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    printf("Exiting.\n");
    return 0;
}

