#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0xC0
#define VL53L0X_REG_SYSRANGE_START 0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B

// Global variables for signal handling
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal)
{
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read a single byte from the VL53L0X
int read_byte(int handle, uint8_t reg, uint8_t *data)
{
    int result = i2cReadI2CBlockData(handle, reg, (char *)data, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading byte from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write a single byte to the VL53L0X
int write_byte(int handle, uint8_t reg, uint8_t data)
{
    int result = i2cWriteI2CBlockData(handle, reg, (char *)&data, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing byte to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a 16-bit word from the VL53L0X
int read_word(int handle, uint8_t reg, uint16_t *data)
{
    char buffer[2];
    int result = i2cReadI2CBlockData(handle, reg, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading word from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *data = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8); // Little-endian
    return 0;
}

// Function to initialize the VL53L0X sensor
int init_sensor(int handle)
{
    uint8_t model_id;

    // Read the model ID
    if (read_byte(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }

    // Verify the model ID
    if (model_id != 0xEE) {
        fprintf(stderr, "Incorrect model ID: 0x%02X (expected 0xEE)\n", model_id);
        return -1;
    }

    return 0;
}

// Function to perform a single-shot ranging measurement
int perform_ranging(int handle, uint16_t *distance)
{
    // Start the measurement
    if (write_byte(handle, VL53L0X_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    // Poll for interrupt status with timeout
    int timeout = 100; // Timeout in milliseconds
    while (timeout > 0) {
        uint8_t interrupt_status;
        if (read_byte(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &interrupt_status) == 0) {
            if (interrupt_status & 0x01) {
                break; // Measurement ready
            }
        } else {
            fprintf(stderr, "Error reading interrupt status\n");
        }
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read the distance
    if (read_word(handle, VL53L0X_REG_RESULT_RANGE_STATUS, distance) != 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    // Clear the interrupt
    if (write_byte(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }

    return 0;
}

// Function to get the current timestamp
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t distance;

        // Perform ranging
        if (perform_ranging(i2c_handle, &distance) == 0) {
            // Get timestamp
            char timestamp[20];
            get_timestamp(timestamp);

            // Print the distance
            printf("%s Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Ranging failed\n");
        }

        // Wait 500 ms
        gpioDelay(500);
    }

    // Close the I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

