    if (write_byte(handle, VL53L0X_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    // Poll for interrupt status with timeout
    int timeout = 100; // Timeout in milliseconds
    while (timeout > 0) {
        uint8_t interrupt_status;
        if (read_byte(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &interrupt_status) == 0) {
            if (interrupt_status & 0x01) {
                break; // Measurement ready
            }
        } else {
            fprintf(stderr, "Error reading interrupt status\n");
        }
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read the distance
    if (read_word(handle, VL53L0X_REG_RESULT_RANGE_STATUS, distance) != 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    // Clear the interrupt
    if (write_byte(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }

    return 0;
}

// Function to get the current timestamp
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t distance;

        // Perform ranging
        if (perform_ranging(i2c_handle, &distance) == 0) {
            // Get timestamp
            char timestamp[20];
            get_timestamp(timestamp);

            // Print the distance
            printf("%s Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Ranging failed\n");
        }

        // Wait 500 ms
        gpioDelay(500);
    }

    // Close the I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

