#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <stdint.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG 0x00
#define SCALE_FACTOR 0.125

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read distance from the MLX75030 sensor
int read_distance(int fd) {
    uint8_t buffer[2];
    int result;

    // Write the register address to be read
    if (write(fd, &DISTANCE_REG, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    // Read two bytes from the sensor
    result = read(fd, buffer, 2);
    if (result != 2) {
        perror("Failed to read distance data");
        return -1;
    }

    // Combine the two bytes into a 16-bit value (little-endian)
    uint16_t raw_distance = (buffer[1] << 8) | buffer[0];

    // Convert the raw value to millimetres
    float distance_mm = (float)raw_distance * SCALE_FACTOR;

    return (int)distance_mm;
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify the device responds (optional, but good practice)
    uint8_t test_buf[1];
    if (read(i2c_fd, test_buf, 1) != 1) {
        fprintf(stderr, "Device not responding. Check connection.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print distance data
    while (1) {
        int distance = read_distance(i2c_fd);
        if (distance != -1) {
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        // Sleep for 500 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 500 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // The program should never reach here due to the infinite loop,
    // but it's good practice to include a close statement.
    close(i2c_fd);
    return 0;
}

