#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for trigger and echo
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define timeout duration in microseconds
#define TIMEOUT_US 200000 // 200 ms

// Define maximum valid pulse duration in microseconds
#define MAX_PULSE_US 38000 // 38 ms

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger high
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
}

// Function to measure the echo pulse width
long measure_pulse() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo rising edge timeout.\n");
        return -1; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo falling edge timeout.\n");
        return -1; // Indicate timeout error
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;

    // Handle potential tick rollover
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF + 1; // Add 2^32 to correct for rollover
    }

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width <= 0) {
        fprintf(stderr, "Error: Invalid pulse width (<= 0).\n");
        return -1.0; // Indicate invalid pulse width
    }

    if (pulse_width > MAX_PULSE_US) {
        fprintf(stderr, "Error: Invalid pulse width (> %d us).\n", MAX_PULSE_US);
        return -1.0; // Indicate invalid pulse width
    }

    return (pulse_width * 0.0343) / 2.0;
}

// Function to log the distance with a timestamp
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

