#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define RANGE_BINS 64
#define RANGE_RESOLUTION 0.0486
#define DISTANCE_THRESHOLD 1.0
#define MAGIC_WORD_LENGTH 8
#define DATA_FRAME_LENGTH (MAGIC_WORD_LENGTH + RANGE_BINS * 2) // 8 bytes header + 64 * 2 bytes data
#define LED_ON_TIME 2 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Structure for configuration
typedef struct {
    char uart_device[20];
    int baud_rate;
    int gpio_led;
    float distance_threshold;
} Config;

// Function prototypes
int uart_init(const char *device, int baud_rate);
int uart_read(int fd, unsigned char *buffer, int count);
int uart_write(int fd, const unsigned char *buffer, int count);
int validate_magic_word(const unsigned char *buffer, int length);
float calculate_distance(int bin_index, float range_resolution);
int detect_intrusion(float distance, float threshold);
void control_led(int gpio_pin, int on);
void log_intrusion(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// UART initialization
int uart_init(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// UART read
int uart_read(int fd, unsigned char *buffer, int count) {
    ssize_t bytes_read = read(fd, buffer, count);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    }
    return (int)bytes_read;
}

// UART write
int uart_write(int fd, const unsigned char *buffer, int count) {
    ssize_t bytes_written = write(fd, buffer, count);
    if (bytes_written == -1) {
        perror("Error writing to UART");
        return -1;
    }
    return (int)bytes_written;
}

// Validate magic word
int validate_magic_word(const unsigned char *buffer, int length) {
    const unsigned char magic_word[] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    if (length != sizeof(magic_word)) return 0;
    return memcmp(buffer, magic_word, sizeof(magic_word)) == 0;
}

// Calculate distance
float calculate_distance(int bin_index, float range_resolution) {
    return bin_index * range_resolution;
}

// Detect intrusion
int detect_intrusion(float distance, float threshold) {
    return (distance <= threshold) ? 1 : 0;
}

// Control LED
void control_led(int gpio_pin, int on) {
    gpioWrite(gpio_pin, on);
}

// Log intrusion
void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.4f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Configuration
    Config config = {
        .uart_device = UART_DEVICE,
        .baud_rate = BAUD_RATE,
        .gpio_led = GPIO_LED,
        .distance_threshold = DISTANCE_THRESHOLD
    };

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.gpio_led, PI_OUTPUT);

    // Initialize UART
    uart_fd = uart_init(config.uart_device, config.baud_rate);
    if (uart_fd == -1) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    unsigned char buffer[DATA_FRAME_LENGTH];
    int bytes_read;
    int i;

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        bytes_read = uart_read(uart_fd, buffer, DATA_FRAME_LENGTH);
        if (bytes_read > 0) {
            if (validate_magic_word(buffer, MAGIC_WORD_LENGTH)) {
                // Process range profile data
                for (i = 0; i < RANGE_BINS; i++) {
                    // Extract 16-bit integer from the buffer (little-endian)
                    short range_bin_value = (short)((buffer[MAGIC_WORD_LENGTH + i * 2 + 1] << 8) | buffer[MAGIC_WORD_LENGTH + i * 2]);

                    float distance = calculate_distance(i, config.range_resolution);

                    if (detect_intrusion(distance, config.distance_threshold)) {
                        printf("Intrusion detected at distance: %.4f meters\n", distance);
                        control_led(config.gpio_led, 1); // Turn on LED
                        log_intrusion(distance);
                        sleep(LED_ON_TIME);
                        control_led(config.gpio_led, 0); // Turn off LED
                    }
                }
            } else {
                fprintf(stderr, "Invalid magic word received\n");
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, retrying...\n");
            sleep(1); // Wait before retrying
        }
    }

    cleanup();
    return 0;
}

