    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_sensor_state = 1; // Initialize to no obstacle (active-low)

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
