            last_sensor_state = sensor_state;
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup before exiting
    control_buzzer(0); // Ensure buzzer is off
    gpioTerminate(); // Terminate pigpio

    printf("Program terminated.\n");
    return 0;
}

