#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define DISTANCE_HIGH_REG 0x31
#define DISTANCE_LOW_REG 0x32
#define ALERT_GPIO 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_distance(int i2c_handle);
void log_distance(FILE *log_file, int distance);
void trigger_alert(int gpio_pin, int distance);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Function to read distance from the sensor
int read_distance(int i2c_handle) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_HIGH_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine high and low bytes into a 16-bit value
    int distance = (buf[0] << 8) | buf[1];
    return distance;
}

// Function to log distance to a file
void log_distance(FILE *log_file, int distance) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    fprintf(log_file, "%s, %d\n", buf, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to trigger an alert based on distance
void trigger_alert(int gpio_pin, int distance) {
    if (distance < DISTANCE_THRESHOLD * 10) { // Convert cm to mm
        gpioWrite(gpio_pin, 1); // Set GPIO HIGH
        gpioDelay(500);          // Wait 500ms
        gpioWrite(gpio_pin, 0); // Set GPIO LOW
    }
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALERT_GPIO, 0); // Ensure GPIO is LOW on exit
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Starting distance measurement...\n");

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            log_distance(log_file, distance);
            trigger_alert(ALERT_GPIO, distance);
        } else {
            fprintf(stderr, "Error reading distance, skipping log and alert.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Sample every 100ms
    }

    // Cleanup
    cleanup();

    return 0;
}

