#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_MODEL_ID 0x010F
#define VL53L1X_RESET 0x0000
#define VL53L1X_MODE_START 0x007
#define VL53L1X_SYSRANGE_START 0x000
#define VL53L1X_RESULT_INTERRUPT_STATUS 0x013
#define VL53L1X_RANGE_STATUS 0x078
#define VL53L1X_INTERRUPT_CLEAR 0x014

// I2C bus
#define I2C_BUS 1

// File to log distance readings
#define LOG_FILE "distance_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void log_distance(FILE *log_file, int distance);
void print_guidance(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// VL53L1X initialization function
int vl53l1x_init(int i2c_handle) {
    // Verify sensor presence
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID (0x%02X)\n", model_id);
        return -1;
    }

    // Perform software reset
    if (i2cWriteByteData(i2c_handle, VL53L1X_RESET, 0x00) < 0) {
        fprintf(stderr, "Error writing reset command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2); // Wait 2 ms

    // Start continuous back-to-back ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error writing mode start command: %s\n", strerror(errno));
        return -1;
    }

    // Wait for SYSRANGE__START to self-clear (timeout 100ms)
    int timeout = 100;
    while (i2cReadByteData(i2c_handle, VL53L1X_SYSRANGE_START) > 0) {
        gpioDelay(1); // Wait 1 ms
        timeout--;
        if (timeout <= 0) {
            fprintf(stderr, "Error: Timeout waiting for SYSRANGE__START to clear\n");
            return -1;
        }
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int i2c_handle) {
    // Poll for data-ready
    int timeout = 100;
    while ((i2cReadByteData(i2c_handle, VL53L1X_RESULT_INTERRUPT_STATUS) & 0x01) == 0) {
        gpioDelay(1); // Wait 1 ms
        timeout--;
        if (timeout <= 0) {
            fprintf(stderr, "Error: Timeout waiting for data-ready\n");
            return -1;
        }
    }

    // Read distance
    int distance = i2cReadWordData(i2c_handle, VL53L1X_RANGE_STATUS + 10);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    // Clear interrupt
    if (i2cWriteByteData(i2c_handle, VL53L1X_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error clearing interrupt: %s\n", strerror(errno));
        return -1;
    }

    return distance;
}

// Log distance to file function
void log_distance(FILE *log_file, int distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
}

// Print parking guidance message function
void print_guidance(int distance) {
    if (distance < 300) {
        printf("STOP\n");
    } else if (distance < 600) {
        printf("APPROACH\n");
    } else if (distance < 1200) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing VL53L1X sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END);

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        int distance = vl53l1x_read_distance(i2c_handle);
        if (distance >= 0) {
            // Log distance
            log_distance(log_file, distance);

            // Print parking guidance message
            print_guidance(distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        // Wait 100 ms
        gpioDelay(100);
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

