#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x45
#define LED_GPIO 18
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int handle, uint8_t reg, uint8_t *data, int count);
int i2c_write_register(int handle, uint8_t reg, uint8_t *data, int count);
float read_distance();
float map_distance_to_frequency(float distance);
void blink_led(float frequency);
void log_data(float distance, float frequency);
void signal_handler(int signal);

// I2C read function with retry logic
int i2c_read_register(int handle, uint8_t reg, uint8_t *data, int count) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(handle, reg, (char *)data, count);
        if (result >= 0) {
            return result; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X, count %d): %d. Retry %d/%d\n", reg, count, result, retries + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02X, count %d)\n", MAX_RETRIES, reg, count);
    return -1; // Failure
}

// I2C write function with retry logic
int i2c_write_register(int handle, uint8_t reg, uint8_t *data, int count) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteI2CBlockData(handle, reg, (char *)data, count);
        if (result >= 0) {
            return result; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, count %d): %d. Retry %d/%d\n", reg, count, result, retries + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "I2C write failed after %d retries (reg 0x%02X, count %d)\n", MAX_RETRIES, reg, count);
    return -1; // Failure
}

// Function to read distance from the sensor
float read_distance() {
    uint8_t data[2];
    int result;

    // Read distance data (example registers, adjust based on datasheet)
    result = i2c_read_register(i2c_handle, 0x00, data, 2); // Example register address
    if (result < 0) {
        fprintf(stderr, "Failed to read distance data\n");
        return -1.0; // Indicate error
    }

    // Convert raw data to distance (example conversion, adjust based on datasheet)
    int16_t raw_distance = (data[0] << 8) | data[1];
    float distance = (float)raw_distance / 10.0; // Example scaling

    return distance;
}

// Function to map distance to blink frequency
float map_distance_to_frequency(float distance) {
    float frequency;

    if (distance <= 50.0) {
        frequency = 10.0;
    } else if (distance >= 500.0) {
        frequency = 1.0;
    } else {
        frequency = 10.0 - (distance - 50.0) * (9.0 / 450.0); // Linear mapping
    }

    return frequency;
}

// Function to blink the LED
void blink_led(float frequency) {
    static int led_state = 0;
    static uint32_t last_toggle_time = 0;
