#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 10

// Structure to hold sensor data
typedef struct {
    int gpio;
    int sensor_id;
    int last_state;
    int debounce_count;
} sensor_data_t;

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int debounce_sensor(int gpio, int current_state, int *debounce_count);
int log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read sensor value
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Debounce sensor reading
int debounce_sensor(int gpio, int current_state, int *debounce_count) {
    int stable_state = gpioRead(gpio);
    if (stable_state != current_state) {
        (*debounce_count)++;
        if (*debounce_count >= (DEBOUNCE_MS / POLL_INTERVAL_MS)) {
            current_state = stable_state;
            *debounce_count = 0; // Reset debounce count after stable state
        }
    } else {
        *debounce_count = 0; // Reset debounce count if state is stable
    }
    return current_state;
}

// Log event to file
int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Cleanup resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor1 = {SENSOR_1_GPIO, 1, 1, 0}; // Initialize sensor 1
    sensor_data_t sensor2 = {SENSOR_2_GPIO, 2, 1, 0}; // Initialize sensor 2

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read and debounce sensor 1
        int sensor1_state = read_sensor(sensor1.gpio);
        sensor1_state = debounce_sensor(sensor1.gpio, sensor1_state, &sensor1.debounce_count);

        // Read and debounce sensor 2
        int sensor2_state = read_sensor(sensor2.gpio);
        sensor2_state = debounce_sensor(sensor2.gpio, sensor2_state, &sensor2.debounce_count);

        // Log events for sensor 1
        if (sensor1_state != sensor1.last_state) {
            if (sensor1_state == 0) {
                log_event(sensor1.sensor_id, "DETECTED");
            } else {
                log_event(sensor1.sensor_id, "CLEARED");
            }
            sensor1.last_state = sensor1_state;
        }

        // Log events for sensor 2
        if (sensor2_state != sensor2.last_state) {
            if (sensor2_state == 0) {
                log_event(sensor2.sensor_id, "DETECTED");
            } else {
                log_event(sensor2.sensor_id, "CLEARED");
            }
            sensor2.last_state = sensor2_state;
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Proximity sensor monitoring stopped.\n");
    return 0;
}

