// Helper function to get ISO-8601 timestamp
char* get_iso8601_timestamp(char* buf, size_t buf_size) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, buf_size, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(buf + strlen(buf), buf_size - strlen(buf), ".%09ldZ", ts.tv_nsec);
    return buf;
}

// I2C read register function
int i2c_read_register(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s (errno: %d)\n", reg, strerror(errno), errno);
        return -1;
    }
    return result;
}

// I2C write register function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s (errno: %d)\n", reg, value, strerror(errno), errno);
        return -1;
    }
    return 0;
}

// Read distance function
int read_distance(int fd) {
    // Trigger measurement
    if (i2c_write_register(fd, MEAS_TRIGGER, 0x01) < 0) {
        return -1;
    }

    // Wait for data ready
    int timeout_count = 0;
    while ((i2c_read_register(fd, MEAS_STATUS) & 0x01) == 0) {
        usleep(1000); // 1 ms
        timeout_count++;
        if (timeout_count > TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            return -1;
        }
    }

    // Read distance data
    int high = i2c_read_register(fd, DIST_HIGH);
    int low = i2c_read_register(fd, DIST_LOW);

    if (high < 0 || low < 0) {
        return -1;
    }

    return (high << 8) | low;
}

// Log data function
void log_data(FILE *fp, sensor_data_t data) {
    char timestamp_str[32];
    get_iso8601_timestamp(timestamp_str, sizeof(timestamp_str));
    fprintf(fp, "%s,%d\n", timestamp_str, data.distance_mm);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    keep_running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s (errno: %d)\n", strerror(errno), errno);
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s (errno: %d)\n", strerror(errno), errno);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s (errno: %d)\n", strerror(errno), errno);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        sensor_data_t data;
        int distance = read_distance(i2c_fd);
        if (distance >= 0) {
            data.timestamp_ns = (long long)time(NULL) * 1000000000LL; // Get current timestamp in nanoseconds
            data.distance_mm = distance;
            log_data(log_file, data);
        } else {
            fprintf(stderr, "Failed to read distance, skipping sample\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 500 ms
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

