#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C

// Define the register address for distance data (replace with actual value)
#define DISTANCE_REG 0x00 // Example register address

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read distance from the MLX75030 sensor
int read_distance(int i2c_handle) {
    int distance = -1; // Initialize to an error value
    int retries = 3;
    int bytes_read;
    uint8_t buffer[2]; // Assuming distance is a 16-bit value

    while (retries > 0) {
        // Write the register address to be read
        if (i2cWriteByteData(i2c_handle, DISTANCE_REG, 0) < 0) {
            fprintf(stderr, "Error writing to I2C device.\n");
            gpioDelay(10000); // 10 ms delay
            retries--;
            continue;
        }

        // Read the distance data
        bytes_read = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, (char *)buffer, 2);

        if (bytes_read == 2) {
            // Combine the two bytes into a 16-bit distance value
            distance = (buffer[0] << 8) | buffer[1];
            break; // Success, exit the retry loop
        } else {
            fprintf(stderr, "Error reading from I2C device. Bytes read: %d\n", bytes_read);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    if (distance == -1) {
        fprintf(stderr, "Failed to read distance after multiple retries.\n");
    }

    return distance;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
