    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the VL53L1X sensor
int vl53l1x_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to reset VL53L1X\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Set I2C slave address (optional, but good practice)
    if (i2cWriteByteData(i2c_handle, I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set VL53L1X I2C address\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, SYSTEM_MODE_START, 0x40) < 0) {
        fprintf(stderr, "Error: Failed to start VL53L1X ranging\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    return 0;
}

// Read distance from the VL53L1X sensor
int vl53l1x_read_distance(int *distance) {
    char buffer[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to read distance from VL53L1X (Error code: %d)\n", result);
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

