                fprintf(stderr, "Error: Could not open I2C bus (Error code: %d)\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (vl53l1x_init() < 0) {
                    fprintf(stderr, "Error: VL53L1X re-initialisation failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Delay for 500ms
    }

    // Clean up
    buzzer_off();
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

