#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <mqueue.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define MESSAGE_QUEUE_NAME "/distance_queue"
#define MAX_MSG_SIZE 256

// VL53L1X Registers
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RESET 0x0000
#define VL53L1X_REG_TIMING_BUDGET 0x0080
#define VL53L1X_REG_DATA_READY 0x0089
#define VL53L1X_REG_DISTANCE 0x0096

// Global variables
int i2c_handle;
mqd_t mq;
volatile sig_atomic_t terminate = 0;

// Structure for distance data
typedef struct {
    int distance;
} distance_data_t;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void buzzer_on();
void buzzer_off();
void signal_handler(int signal);
int send_distance_message(int distance);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, cleaning up...\n", signal);
}

// VL53L1X Initialization
int vl53l1x_init() {
    int status;
    uint8_t model_id;

    // Check sensor model ID
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", status);
        return -1;
    }
    model_id = (uint8_t)status;

    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Software reset
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_RESET, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing reset command: %d\n", status);
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_RESET, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing reset command: %d\n", status);
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Configure timing budget (50ms)
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_TIMING_BUDGET, 0x32); // 50ms
    if (status < 0) {
        fprintf(stderr, "Error writing timing budget: %d\n", status);
        return -1;
    }

    return 0;
}

// VL53L1X Read Distance
int vl53l1x_read_distance(int *distance) {
    int status;
    uint8_t data_ready;
    uint8_t distance_data[2];

    // Check data ready bit
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_DATA_READY);
    if (status < 0) {
        fprintf(stderr, "Error reading data ready bit: %d\n", status);
        return -1;
    }
    data_ready = (uint8_t)status;

    if (!(data_ready & 0x01)) {
        return 0; // Data not ready
    }

    // Read distance data
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_DISTANCE, (char *)distance_data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", status);
        return -1;
    }

    *distance = (distance_data[0] << 8) | distance_data[1];

    return 0;
}

// Buzzer control
void buzzer_on() {
    gpioWrite(BUZZER_GPIO, 1);
}

void buzzer_off() {
    gpioWrite(BUZZER_GPIO, 0);
}

// Send distance message
int send_distance_message(int distance) {
    distance_data_t data;
    data.distance = distance;

    if (mq_send(mq, (const char *)&data, sizeof(distance_data_t), 0) == -1) {
        perror("mq_send");
        return -1;
    }

    return 0;
}

int main() {
    int distance;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    buzzer_off(); // Ensure buzzer is off initially

    // Initialize message queue
    struct mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = 10; // Maximum number of messages
    attr.mq_msgsize = sizeof(distance_data_t);
    attr.mq_curmsgs = 0;

    mq = mq_open(MESSAGE_QUEUE_NAME, O_CREAT | O_WRONLY | O_NONBLOCK, 0644, &attr);
    if (mq == (mqd_t)-1) {
        perror("mq_open");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        status = vl53l1x_read_distance(&distance);
        if (status == 0) {
            printf("Distance: %d mm\n", distance);

            // Send distance message
            if (send_distance_message(distance) != 0) {
                fprintf(stderr, "Failed to send distance message\n");
            }

            // Activate buzzer if distance is below threshold
            if (distance < DISTANCE_THRESHOLD) {
                buzzer_on();
            } else {
                buzzer_off();
            }
        } else if (status < 0) {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup
    buzzer_off();
    i2cClose(i2c_handle);
    mq_close(mq);
    mq_unlink(MESSAGE_QUEUE_NAME);
    gpioTerminate();

    return 0;
}

