#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define BUZZER_THRESHOLD 30.0  // cm

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int timeout_flag = 0;
static volatile double distance = 0.0;
static volatile int buzzer_state = 0; // 0 = off, 1 = on

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick, void *user);
double calculateDistance(uint32_t pulse_width);
void displayDistance(double distance);
void controlBuzzer(double distance);
void signalHandler(int signal);

// Signal handler for clean shutdown
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();           // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger HIGH
    gpioDelay(10);             // Wait 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger LOW
}

// Callback function for echo pin interrupt
void echoCallback(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) {
        // Rising edge
        start_tick = tick;
        echo_received = 1;
        timeout_flag = 0; // Reset timeout flag
    } else if (level == 0) {
        // Falling edge
        if (echo_received) {
            end_tick = tick;
            uint32_t pulse_width = end_tick - start_tick;

            // Handle tick wraparound
            if (end_tick < start_tick) {
                pulse_width = (0xFFFFFFFF - start_tick) + end_tick;
            }

            distance = calculateDistance(pulse_width);
            echo_received = 0; // Reset echo received flag
        }
    }
}

// Function to calculate distance from pulse width
double calculateDistance(uint32_t pulse_width) {
    double time_taken = (double)pulse_width / 1000000.0; // Time in seconds
    double distance = (SPEED_OF_SOUND * time_taken) / 2.0; // Distance in cm
    return distance;
}

// Function to display the distance
void displayDistance(double distance) {
    printf("Distance: %.2f cm\n", distance);
}

// Function to control the buzzer
void controlBuzzer(double distance) {
    if (distance < BUZZER_THRESHOLD && !buzzer_state) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
        buzzer_state = 1;
    } else if (distance >= BUZZER_THRESHOLD && buzzer_state) {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
        buzzer_state = 0;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
