#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define MIN_PULSE_WIDTH 100   // us
#define MAX_PULSE_WIDTH 30000 // us
#define TIMEOUT_MS 60          // ms

// Global variables
static volatile int running = 1;
static volatile uint32_t rising_edge_tick = 0;
static volatile uint32_t falling_edge_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for ECHO pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        rising_edge_tick = tick;
        echo_received = 1;
    } else if (level == 0 && echo_received) {
        falling_edge_tick = tick;
        echo_received = 0;
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2.0;
}

// Function to log distance to stdout and file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);

    if (log_file != NULL) {
        fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Initialize log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register callback function for ECHO pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for echo or timeout
        uint32_t start_time = gpioTick();
        while (!echo_received && (gpioTick() - start_time) < TIMEOUT_MS * 1000) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        if (!echo_received) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

            fprintf(stderr, "%s Timeout: No echo received within %d ms\n", timestamp, TIMEOUT_MS);
            if (log_file != NULL) {
                fprintf(log_file, "%s Timeout: No echo received within %d ms\n", timestamp, TIMEOUT_MS);
                fflush(log_file);
            }
            echo_received = 0; // Reset flag for next iteration
            continue;
        }

        // Calculate pulse width
        uint32_t pulse_width;
        if (falling_edge_tick > rising_edge_tick) {
            pulse_width = falling_edge_tick - rising_edge_tick;
        } else {
            // Handle tick wraparound
            pulse_width = (0xFFFFFFFF - rising_edge_tick) + falling_edge_tick + 1;
        }

        // Validate pulse width
        if (pulse_width < MIN_PULSE_WIDTH) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

            fprintf(stderr, "%s Warning: Pulse width too short (%d us)\n", timestamp, pulse_width);
            if (log_file != NULL) {
                fprintf(log_file, "%s Warning: Pulse width too short (%d us)\n", timestamp, pulse_width);
                fflush(log_file);
            }
            echo_received = 0; // Reset flag for next iteration
            continue;
        }

        if (pulse_width > MAX_PULSE_WIDTH) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

            fprintf(stderr, "%s Warning: Pulse width too long (%d us)\n", timestamp, pulse_width);
            if (log_file != NULL) {
                fprintf(log_file, "%s Warning: Pulse width too long (%d us)\n", timestamp, pulse_width);
                fflush(log_file);
            }
            echo_received = 0; // Reset flag for next iteration
            continue;
        }

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Log distance
        log_distance(distance);

        // Reset echo_received flag for next iteration
        echo_received = 0;

        // Wait for 200ms (5Hz)
        gpioDelay(200);
    }

    // Clean up
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

