#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define DISTANCE_THRESHOLD_OPEN 50  // cm
#define DISTANCE_THRESHOLD_CLOSE 60 // cm
#define SERVO_OPEN_PULSE_WIDTH 2000 // us
#define SERVO_CLOSE_PULSE_WIDTH 1000 // us
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_get_distance();
void set_servo_angle(int angle);
void log_event(const char *event, int distance);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0049
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Helper function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int handle, uint8_t reg, uint8_t data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Helper function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int handle, uint8_t reg, uint8_t *data) {
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)data, 1) != 1) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Helper function to read a word (2 bytes) from a VL53L1X register
int vl53l1x_read_word(int handle, uint8_t reg, uint16_t *data) {
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    char read_buf[2];
    if (i2cReadDevice(handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02X\n", reg);
        return -1;
    }
    *data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// VL53L1X initialization function
int vl53l1x_init() {
    uint8_t model_id;
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading VL53L1X model ID\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect VL53L1X model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Basic initialization sequence (example, adjust as needed)
    if (vl53l1x_write_byte(i2c_handle, 0x002D, 0x04) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x002E, 0x01) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x002F, 0x02) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0030, 0x01) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0031, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0032, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0033, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0034, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0035, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0036, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0037, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0038, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0039, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x003A, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x003B, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x003C, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x003D, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x003E, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x003F, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0040, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0041, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0042, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0043, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0044, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0045, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0046, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0047, 0x00) != 0) return -1; // Recommended initialisation
    if (vl53l1x_write_byte(i2c_handle, 0x0048, 0x00) != 0) return -1; // Recommended initialisation

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_get_distance() {
    uint16_t distance;
    uint8_t range_status;

    // Start a single measurement
    if (vl53l1x_write_byte(i2c_handle, 0x0000, 0x01) != 0) return -1; // Start single measurement
    gpioDelay(100); // Wait for measurement to complete (adjust as needed)

    // Read the distance
    if (vl53l1x_read_word(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance) != 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    // Read range status
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Check for valid range
    if (range_status != 0) {
        fprintf(stderr, "Invalid range status: 0x%02X\n", range_status);
        return -1;
    }

    return distance / 10; // Convert mm to cm
}

// Servo motor control function
void set_servo_angle(int angle) {
    int pulse_width;

    // Map angle (0-180) to pulse width (1000-2000 us)
    pulse_width = 1000 + (int)((float)angle / 180.0 * 1000.0);

    gpioPWM(SERVO_PIN, pulse_width);
}

// Logging function
void log_event(const char *event, int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s: Distance = %d cm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event, distance);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int distance;
    int gate_open = 0; // 0 = closed, 1 = open

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("parking_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

