void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// VL53L1X initialization function
int vl53l1x_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SOFT_RESET, (char[2]){0x01, 0x00}, 2) != 0) {
        fprintf(stderr, "Error: VL53L1X soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Set I2C address (optional, but good practice)
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS, (char[2]){0x29, 0x00}, 2) != 0) {
        fprintf(stderr, "Error: VL53L1X I2C address setting failed\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Set timing budget (example: 50ms)
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_TIMING_BUDGET_MS, (char[2]){0x32, 0x00}, 2) != 0) {
        fprintf(stderr, "Error: VL53L1X timing budget setting failed\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Start ranging (example: continuous mode)
    if (i2cWriteI2CBlockData(i2c_handle, 0x0010, (char[2]){0x00, 0x01}, 2) != 0) {
        fprintf(stderr, "Error: VL53L1X ranging mode setting failed\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    return 0;
}

