        fprintf(stderr, "Error: VL53L1X data ready check failed\n");
        return -1;
    }

    if (data[0] & 0x01) {
        // Read distance data
        if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
            fprintf(stderr, "Error: VL53L1X distance read failed\n");
            return -1;
        }

        distance = (data[0] << 8) | data[1];
        return distance;
    } else {
        return -1; // Data not ready
    }
}

