    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_CLOSE, PI_OUTPUT);

    // Open log file
    log_file = fopen("gate_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = vl53l1x_read_distance(i2c_handle);
        if (distance >= 0) {
            control_gate(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_OPEN, 0);
    gpioWrite(GPIO_CLOSE, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

