#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_FORWARD 17
#define GPIO_BACKWARD 18
#define GPIO_TRIGGER 24
#define DISTANCE_THRESHOLD_LOW 100 // mm
#define DISTANCE_THRESHOLD_HIGH 300 // mm

// VL53L1X register addresses
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_START_MEASUREMENT 0x0000
#define VL53L1X_REG_DATA_READY 0x0089
#define VL53L1X_REG_DISTANCE 0x0096

// Global variables
int i2c_handle;
volatile int distance = 0; // Distance measured by the sensor
volatile int motor_state = 0; // 0: stopped, 1: forward, -1: backward

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void control_motor(int distance);
void trigger_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    control_motor(0); // Stop the motor
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// VL53L1X initialization function
int vl53l1x_init() {
    int status;
    int retries = 3;
    int delay_ms = 1;

    // Soft reset
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SOFT_RESET, 0x00);
        if (status == 0) break;
        fprintf(stderr, "Error: VL53L1X soft reset failed (attempt %d), retrying...\n", 4 - retries);
        gpioDelay(delay_ms * 1000); // Delay in microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }
    if (status != 0) {
        fprintf(stderr, "Error: VL53L1X soft reset failed after multiple retries.\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance() {
    int status;
    int retries = 3;
    int delay_ms = 1;
    unsigned char data[2];
    int distance_raw;

    // Start measurement
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_START_MEASUREMENT, 0x01);
        if (status == 0) break;
        fprintf(stderr, "Error: VL53L1X start measurement failed (attempt %d), retrying...\n", 4 - retries);
        gpioDelay(delay_ms * 1000); // Delay in microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }
    if (status != 0) {
        fprintf(stderr, "Error: VL53L1X start measurement failed after multiple retries.\n");
        return -1;
    }

    // Wait for data ready
    retries = 3;
    delay_ms = 1;
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_DATA_READY);
        if (status >= 0 && (status & 0x01)) break; // Check bit 0
        fprintf(stderr, "Error: VL53L1X data not ready (attempt %d), retrying...\n", 4 - retries);
        gpioDelay(delay_ms * 1000); // Delay in microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }
    if (status < 0 || !(status & 0x01)) {
        fprintf(stderr, "Error: VL53L1X data ready check failed after multiple retries.\n");
        return -1;
    }

    // Read distance
    retries = 3;
    delay_ms = 1;
    while (retries > 0) {
        status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_DISTANCE, (char *)data, 2);
        if (status == 2) break; // Expect 2 bytes
        fprintf(stderr, "Error: VL53L1X distance read failed (attempt %d), retrying...\n", 4 - retries);
        gpioDelay(delay_ms * 1000); // Delay in microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }
    if (status != 2) {
        fprintf(stderr, "Error: VL53L1X distance read failed after multiple retries.\n");
        return -1;
    }

    distance_raw = (data[0] << 8) | data[1];
    return distance_raw;
}

// Motor control function
void control_motor(int distance) {
    if (distance < DISTANCE_THRESHOLD_LOW) {
        gpioWrite(GPIO_FORWARD, 1);
        gpioWrite(GPIO_BACKWARD, 0);
        motor_state = 1;
        printf("Motor: Forward\n");
    } else if (distance > DISTANCE_THRESHOLD_HIGH) {
        gpioWrite(GPIO_FORWARD, 0);
        gpioWrite(GPIO_BACKWARD, 1);
        motor_state = -1;
        printf("Motor: Backward\n");
    } else {
        gpioWrite(GPIO_FORWARD, 0);
        gpioWrite(GPIO_BACKWARD, 0);
        motor_state = 0;
        printf("Motor: Stopped\n");
    }
}

// Trigger callback function
void trigger_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        int dist = vl53l1x_read_distance();
        if (dist >= 0) {
            distance = dist;
            printf("Distance: %d mm\n", distance);
            control_motor(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
            control_motor(0); // Stop the motor
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_BACKWARD, PI_OUTPUT);
    gpioSetMode(GPIO_TRIGGER, PI_INPUT);

    // Set pull-down resistor on trigger pin
    gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_DOWN);

    // Set ISR for rising edge detection on GPIO24
    gpioSetISRFuncEx(GPIO_TRIGGER, RISING_EDGE, 0, trigger_callback, NULL);

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        gpioDelay(100000); // Sleep for 0.1 seconds (100 ms)
    }

    return 0;
}

