#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define GPIO_LED1 17
#define GPIO_LED2 18
#define GPIO_LED3 27
#define GPIO_LED4 22

// Define LED patterns
const unsigned char led_patterns[12][4] = {
    {0x1, 0x2, 0x4, 0x8},   // Electrode 0
    {0x1, 0x2, 0x4, 0x0},   // Electrode 1
    {0x1, 0x2, 0x0, 0x8},   // Electrode 2
    {0x1, 0x0, 0x4, 0x8},   // Electrode 3
    {0x2, 0x4, 0x8, 0x0},   // Electrode 4
    {0x1, 0x4, 0x8, 0x0},   // Electrode 5
    {0x1, 0x2, 0x8, 0x0},   // Electrode 6
    {0x1, 0x0, 0x4, 0x0},   // Electrode 7
    {0x2, 0x0, 0x4, 0x8},   // Electrode 8
    {0x0, 0x2, 0x4, 0x8},   // Electrode 9
    {0x1, 0x2, 0x0, 0x0},   // Electrode 10
    {0x0, 0x0, 0x0, 0x0}    // Electrode 11
};

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_byte(int fd, unsigned char reg, unsigned char value);
int i2c_read_byte(int fd, unsigned char reg);
int mpr121_init(int fd);
int mpr121_read_touch_status(int fd, unsigned short *status);
void set_led_pattern(int gpio1, int gpio2, int gpio3, int gpio4, unsigned char pattern[4]);
void log_event(const char *message);
void signal_handler(int signal);

// I2C write function
int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_byte(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    unsigned char value;
    if (read(fd, &value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return value;
}

// MPR121 initialization function
int mpr121_init(int fd) {
    // Soft reset
    if (i2c_write_byte(fd, 0x80, 0x63) < 0) return -1;
    gpioDelay(10000); // 10ms delay

    // Verify sensor presence (check WHO_AM_I register, should return 0x5A)
    int who_am_i = i2c_read_byte(fd, 0x11);
    if (who_am_i < 0 || who_am_i != 0x5A) {
        fprintf(stderr, "MPR121 not found or WHO_AM_I returned 0x%X\n", who_am_i);
        return -1;
    }

    // Stop mode
    if (i2c_write_byte(fd, 0x5E, 0x00) < 0) return -1;

    // Baseline filtering
    if (i2c_write_byte(fd, 0x5B, 0x01) < 0) return -1; // MHDR
    if (i2c_write_byte(fd, 0x5C, 0x01) < 0) return -1; // NHDR
    if (i2c_write_byte(fd, 0x5D, 0x0E) < 0) return -1; // NCLR
    if (i2c_write_byte(fd, 0x5E, 0x00) < 0) return -1; // FDLR

    // Auto-configuration thresholds
    if (i2c_write_byte(fd, 0x5A, 0x0B) < 0) return -1;
    if (i2c_write_byte(fd, 0x5D, 0xC8) < 0) return -1;
    if (i2c_write_byte(fd, 0x5E, 0x82) < 0) return -1;
    if (i2c_write_byte(fd, 0x5F, 0xB4) < 0) return -1;

    // Enable all 12 electrodes in run mode
    if (i2c_write_byte(fd, 0x5E, 0x0C) < 0) return -1;

    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status(int fd, unsigned short *status) {
    unsigned char lsb = i2c_read_byte(fd, 0x00);
    unsigned char msb = i2c_read_byte(fd, 0x01);

    if (lsb < 0 || msb < 0) {
        return -1;
    }

    *status = (msb << 8) | lsb;
    return 0;
}

// Set LED pattern function
void set_led_pattern(int gpio1, int gpio2, int gpio3, int gpio4, unsigned char pattern[4]) {
    gpioWrite(gpio1, pattern[0]);
    gpioWrite(gpio2, pattern[1]);
    gpioWrite(gpio3, pattern[2]);
    gpioWrite(gpio4, pattern[3]);
}

// Log event function
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_LED1, PI_OUTPUT);
    gpioSetMode(GPIO_LED2, PI_OUTPUT);
    gpioSetMode(GPIO_LED3, PI_OUTPUT);
    gpioSetMode(GPIO_LED4, PI_OUTPUT);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned short touch_status;
    int electrode_active = -1; // Initialize to -1 to indicate no electrode is active

    // Main loop
    while (!terminate) {
        // Read touch status
        if (mpr121_read_touch_status(i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            log_event("Failed to read touch status");
        } else {
            // Determine which electrode is active
            int new_electrode_active = -1;
            for (int i = 0; i < 12; i++) {
                if (touch_status & (1 << i)) {
                    new_electrode_active = i;
                    break; // Only consider the first active electrode
                }
            }

            // Update LED pattern if the active electrode has changed
            if (new_electrode_active != electrode_active) {
                electrode_active = new_electrode_active;
                if (electrode_active != -1) {
                    char log_message[100];
                    snprintf(log_message, sizeof(log_message), "Electrode %d touched", electrode_active);
                    log_event(log_message);
                    set_led_pattern(GPIO_LED1, GPIO_LED2, GPIO_LED3, GPIO_LED4, led_patterns[electrode_active]);
                } else {
                    log_event("No electrode touched");
                    set_led_pattern(GPIO_LED1, GPIO_LED2, GPIO_LED3, GPIO_LED4, led_patterns[11]); // All LEDs off
                }
            }
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

