#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 30000       // 30 ms timeout

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_pulse();
long long measure_pulse_width();
double calculate_distance(long long pulse_width);
void log_distance(double distance);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);

    return 0;
}

// Generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the echo pulse width
long long measure_pulse_width() {
    long long start_tick, end_tick, pulse_width;

    // Wait for rising edge with timeout
    int timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        start_tick = gpioTick();
        if (start_tick < 0) {
            fprintf(stderr, "Error reading start tick: %s\n", strerror(errno));
            return -1;
        }
        if (timeout_counter++ > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1;
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Wait for falling edge with timeout
    timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        if (end_tick < 0) {
            fprintf(stderr, "Error reading end tick: %s\n", strerror(errno));
            return -1;
        }
        if (timeout_counter++ > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1;
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Calculate distance in centimeters
double calculate_distance(long long pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2.0;
}

// Log the distance to a file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
    gpioSetMode(TRIGGER_PIN, PI_INPUT); // Set trigger to input
    gpioSetMode(ECHO_PIN, PI_INPUT); // Set echo to input

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();
        long long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            double distance = calculate_distance(pulse_width);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_distance(distance);
                printf("Distance: %.2f cm\n", distance);
            } else {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[30];

