// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_pulse();
long long measure_pulse_width();
double calculate_distance(long long pulse_width);
void log_distance(double distance);
