// Define GPIO pins
#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 343.0 // Speed of sound in m/s
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds
#define MIN_PULSE_WIDTH 58 // Minimum pulse width in microseconds (1cm)
#define MAX_PULSE_WIDTH 25000 // Maximum pulse width in microseconds (4m)

// Global variables
static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
void trigger_pulse();
double calculate_distance(int pulse_width);
void log_distance(double distance);
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Structure to hold callback data
typedef struct {
    int gpio;
    int level;
    uint32_t tick;
} callback_data_t;

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Function to calculate distance in meters
double calculate_distance(int pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2e6 for cm to m conversion
}

// Function to log distance to a file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t diff;

    if (level == 1) {
        pulse_start = tick;
        echo_received = 1; // Indicate that an echo has been received
    } else if (level == 0 && echo_received == 1) {
        pulse_end = tick;
        echo_received = 0; // Reset echo received flag

        diff = pulse_end - pulse_start;

        // Handle tick wraparound
        if (diff < 0) {
            diff += 0xFFFFFFFF; // Add 2^32 to handle wraparound
        }

        if (diff > 0 && diff < MAX_PULSE_WIDTH) {
            double distance = calculate_distance(diff);
            log_distance(distance);
        } else {
            fprintf(stderr, "Error: Invalid pulse width: %d\n", diff);
        }
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL); // Disable ISR
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt callback
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: Could not set ISR function\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(1000000); // Wait 1 second
    }

    return 0;
}

