#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define XSHUT_PIN 27
#define CONTINUOUS_MODE_REG 0x0018
#define TIMEOUT_REG 0x0019
#define START_RANGING_REG 0x0020
#define DISTANCE_HIGH_REG 0x0014
#define DISTANCE_LOW_REG 0x0015
#define STATUS_REG 0x0016

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance(uint16_t *distance);
int read_status(uint8_t *status);
void log_data(uint16_t distance, uint8_t status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    terminate = 1;
}

// Initialize the VL53L1X sensor
int init_sensor() {
    // Set XSHUT pin high to enable the sensor
    gpioWrite(XSHUT_PIN, 1);
    gpioDelay(100); // Wait for the sensor to power up

    // Configure continuous mode
    if (i2cWriteByteData(i2c_handle, CONTINUOUS_MODE_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to set continuous mode");
        return -1;
    }

    // Configure no timeout
    if (i2cWriteByteData(i2c_handle, TIMEOUT_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to set no timeout");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, START_RANGING_REG, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to start ranging");
        return -1;
    }

    return 0;
}

// Read distance from the sensor
int read_distance(uint16_t *distance) {
    uint8_t high_byte, low_byte;

    high_byte = i2cReadByteData(i2c_handle, DISTANCE_HIGH_REG);
    if (high_byte < 0) {
        syslog(LOG_ERR, "Failed to read distance high byte");
        return -1;
    }

    low_byte = i2cReadByteData(i2c_handle, DISTANCE_LOW_REG);
    if (low_byte < 0) {
        syslog(LOG_ERR, "Failed to read distance low byte");
        return -1;
    }

    *distance = (uint16_t)((low_byte << 8) | high_byte);
    return 0;
}

// Read status from the sensor
int read_status(uint8_t *status) {
    *status = i2cReadByteData(i2c_handle, STATUS_REG);
    if (*status < 0) {
        syslog(LOG_ERR, "Failed to read status");
        return -1;
    }
    return 0;
}

// Log data to syslog
void log_data(uint16_t distance, uint8_t status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s - Distance: %d mm, Status: 0x%02X", timestamp, distance, status);
}

int main() {
    // Initialize syslog
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set XSHUT pin as output
    gpioSetMode(XSHUT_PIN, PI_OUTPUT);

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() < 0) {
        syslog(LOG_ERR, "Sensor initialization failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t distance;
    uint8_t status;
    while (!terminate) {
        if (read_distance(&distance) == 0 && read_status(&status) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read sensor data");
        }
        gpioDelay(100); // Wait 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

