int read_distance();
void control_gate(int distance);
void log_data(int distance, int gate_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize the VL53L1X sensor
int init_sensor() {
    int status;
    char buf[2];

    // Check model ID
    buf[0] = VL53L1X_REG_MODEL_ID;
    status = i2cWriteDevice(i2c_handle, buf, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }
    status = i2cReadDevice(i2c_handle, buf, 1);
    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }
    if (buf[0] != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", buf[0]);
        return -1;
    }

    // Set ranging mode to short
    buf[0] = VL53L1X_REG_RANGING_MODE;
    buf[1] = 0x00;
    status = i2cWriteDevice(i2c_handle, buf, 2);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    // Start ranging
    buf[0] = VL53L1X_REG_START_RANGING;
    buf[1] = 0x01;
    status = i2cWriteDevice(i2c_handle, buf, 2);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    return 0;
}

