int read_distance() {
    int status;
    char buf[1];
    char data[2];

    // Read distance data
    buf[0] = VL53L1X_REG_DISTANCE;
    status = i2cWriteDevice(i2c_handle, buf, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
