    status = i2cReadDevice(i2c_handle, data, 2);
    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }

    // Convert to millimeters
    int distance_mm = (data[0] << 8) | data[1];

    // Convert to centimeters
    int distance_cm = distance_mm / 10;

    return distance_cm;
