#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000        // 30 ms timeout
#define MOVING_AVG_SIZE 5
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_NEUTRAL_PULSE_WIDTH 1500

// Global variables
volatile sig_atomic_t terminate_flag = 0;
FILE *log_file = NULL;
int echo_start_tick = 0;
int echo_end_tick = 0;
int pulse_width = -1; // Initialize to an invalid value
double distance_history[MOVING_AVG_SIZE] = {0.0}; // Initialize history
int history_index = 0;

// Function prototypes
void triggerSensor();
double calculateDistance(int pulseWidth);
double applyMovingAverage(double newDistance);
double mapDistanceToAngle(double distance);
int setServoAngle(double angle);
void logData(double distance, double angle);
void signalHandler(int signal);
void echo_callback(int gpio, int level, uint32_t tick);

// Signal handler function
void signalHandler(int signal) {
    terminate_flag = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Calculate distance from pulse width
double calculateDistance(int pulseWidth) {
    if (pulseWidth < 0) return -1.0; // Indicate error
    return (double)pulseWidth * SPEED_OF_SOUND / 2000000.0; // cm
}

// Apply moving average filter
double applyMovingAverage(double newDistance) {
    distance_history[history_index] = newDistance;
    history_index = (history_index + 1) % MOVING_AVG_SIZE;

    double sum = 0.0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        sum += distance_history[i];
    }
    return sum / MOVING_AVG_SIZE;
}

// Map distance to servo angle (non-linear mapping)
double mapDistanceToAngle(double distance) {
    if (distance < 2.0 || distance > 400.0) return -1.0; // Indicate error

    // Non-linear mapping (logarithmic)
    double normalized_distance = (distance - 2.0) / (400.0 - 2.0);
    double angle = 90.0 + 45.0 * log10(normalized_distance * 9.0 + 1.0); // Map to 45-135 degrees

    // Clamp the angle to 0-180 degrees
    if (angle < 0.0) angle = 0.0;
    if (angle > 180.0) angle = 180.0;

    return angle;
}

// Set servo angle
int setServoAngle(double angle) {
    if (angle < 0.0 || angle > 180.0) return -1; // Indicate error

    // Map angle to pulse width (500-2500 us)
    int pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + (angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    int result = gpioServo(SERVO_PIN, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo angle: %d\n", result);
        return -1;
    }
    return 0;
}

// Log data to CSV file
void logData(double distance, double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
        fflush(log_file); // Flush the buffer to ensure data is written
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t diff;

    if (level == 1) {
        echo_start_tick = tick;
        last_tick = tick;
    } else if (level == 0) {
        echo_end_tick = tick;

        diff = tick - last_tick;
        if (diff < 0) {
            diff = (0xFFFFFFFF - last_tick) + tick; // Handle wrap-around
        }

        if (diff > TIMEOUT_US) {
            pulse_width = -1; // Timeout
        } else {
            pulse_width = diff;
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize trigger pin to low
    gpioWrite(TRIGGER_PIN, 0);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
    }

    // Set up alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (!terminate_flag) {
        triggerSensor();
        gpioDelay(100); // 100 ms delay

        // Calculate distance
        double distance = calculateDistance(pulse_width);

        // Apply moving average filter
        double filtered_distance = applyMovingAverage(distance);

        // Map distance to servo angle
        double angle = mapDistanceToAngle(filtered_distance);

        // Set servo angle
        if (angle < 0.0) {
            angle = 90.0; // Default to 90 degrees
            fprintf(stderr, "Invalid distance, setting servo to 90 degrees.\n");
        }
        if (setServoAngle(angle) != 0) {
            fprintf(stderr, "Error setting servo, logging -1.0 and setting servo to 90 degrees.\n");
            angle = 90.0;
            setServoAngle(angle);
        }

        // Log data
        if (filtered_distance < 2.0 || filtered_distance > 400.0 || pulse_width == -1) {
            logData(-1.0, -1.0);
        } else {
            logData(filtered_distance, angle);
        }

        gpioDelay(50); // Small delay to avoid busy-waiting
    }

    // Cleanup
    setServoAngle(90.0); // Set servo to neutral position
    gpioDelay(500);       // Allow servo to move
    fclose(log_file);
    gpioTerminate();

    return 0;
}

