        fprintf(stderr, "Error: Failed to set I2C address.\n");
        return -1;
    }

    // Example: Start the sensor (Simplified - refer to datasheet for full sequence)
    data[0] = VL53L1X_REG_SYSTEM_START;
    data[1] = 0x01; // Start ranging

    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error: Failed to start sensor.\n");
        return -1;
    }

    gpioDelay(10000); // Wait for sensor to start (10ms)

