#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_REGISTER_HIGH 0x08
#define PROXIMITY_REGISTER_LOW 0x09
#define GPIO_INTERRUPT 27

// Global variables
int i2c_handle;
int proximity_threshold = DEFAULT_THRESHOLD;
int i2c_address = DEFAULT_I2C_ADDRESS;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int address);
int configure_si1102();
int read_proximity_value(int *proximity);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void log_proximity_data(int proximity);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int i2c_handle;
    int proximity_threshold;
    int i2c_address;
    FILE *log_file;
} program_state_t;

program_state_t state;

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                if (sscanf(optarg, "%x", &i2c_address) != 1) {
                    fprintf(stderr, "Error: Invalid I2C address format. Using default 0x60.\n");
                    i2c_address = DEFAULT_I2C_ADDRESS;
                }
                break;
            case 't':
                proximity_threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize program state
    state.i2c_handle = -1;
    state.proximity_threshold = proximity_threshold;
    state.i2c_address = i2c_address;
    state.log_file = NULL;

    // Register signal handler for clean shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(state.i2c_address) != 0) {
        fprintf(stderr, "Failed to initialize I2C.\n");
        cleanup();
        return 1;
    }

    // Configure Si1102 sensor
    if (configure_si1102() != 0) {
        fprintf(stderr, "Failed to configure Si1102 sensor.\n");
        cleanup();
        return 1;
    }

    // Configure GPIO interrupt
    if (gpioSetISRFuncEx(GPIO_INTERRUPT, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set GPIO interrupt handler.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Do other tasks here, if any
        sleep(1); // Reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure Si1102 sensor (minimal configuration)
int configure_si1102() {
    // Example configuration: Reset the device (refer to Si1102 datasheet)
    if (i2cWriteByteData(i2c_handle, 0x17, 0x01) < 0) { // Reset command
        fprintf(stderr, "Error writing to I2C: %d\n", i2c_handle);
        return 1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Enable proximity sensor (refer to Si1102 datasheet)
    if (i2cWriteByteData(i2c_handle, 0x18, 0x0F) < 0) { // Enable proximity
        fprintf(stderr, "Error writing to I2C: %d\n", i2c_handle);
        return 1;
    }

    return 0;
}

// Read proximity value from Si1102 sensor
int read_proximity_value(int *proximity) {
    int high_byte, low_byte;

    high_byte = i2cReadByteData(i2c_handle, PROXIMITY_REGISTER_HIGH);
    if (high_byte < 0) {
        fprintf(stderr, "Error reading high byte from I2C: %d\n", i2c_handle);
        return 1;
    }

    low_byte = i2cReadByteData(i2c_handle, PROXIMITY_REGISTER_LOW);
    if (low_byte < 0) {
        fprintf(stderr, "Error reading low byte from I2C: %d\n", i2c_handle);
        return 1;
    }

    *proximity = (high_byte << 8) | low_byte;
    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    int proximity;

    if (read_proximity_value(&proximity) == 0) {
        log_proximity_data(proximity);
    }
}

// Log proximity data to file
void log_proximity_data(int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char status[6];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (proximity > state.proximity_threshold) {
        strcpy(status, "ALERT");
    } else {
        strcpy(status, "SAFE");
    }

    fprintf(state.log_file, "%s, %d, %s\n", timestamp, proximity, status);
    fflush(state.log_file); // Ensure data is written to disk immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

