#define MAX_DISTANCE 50.0 // cm
#define MIN_FREQUENCY 200.0 // Hz
#define MAX_FREQUENCY 2000.0 // Hz
#define TIMEOUT_US 100000 // 100 ms timeout

// Global variables
volatile sig_atomic_t program_running = 1;
double last_valid_distance = 50.0; // Initialize to max distance

// Function prototypes
void signal_handler(int signal);
double measure_distance();
double distance_to_frequency(double distance);
void set_buzzer_frequency(double frequency);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

