double measure_distance() {
    long long start_tick, end_tick, diff;

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioDelay(2); // Wait 2 us

    gpioWrite(TRIGGER_PIN, 1); // Send 10 us pulse
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal timeout\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

