    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1);
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal timeout (low)\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    if (diff < 0) {
        diff += 0xFFFFFFFF; // Handle tick rollover
    }

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    double distance = (double)diff / 2.0 / 29.1; // cm

    return distance;
}

