        distance = MAX_DISTANCE;
    }

    // Linear mapping
    frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE);

    return frequency;
}

