    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Install signal handler
    signal(SIGINT, signal_handler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        double distance = measure_distance();

        if (distance > 0) {
            last_valid_distance = distance;
        } else {
            distance = last_valid_distance; // Use last valid distance
        }

        double frequency = distance_to_frequency(distance);

        set_buzzer_frequency(frequency);

        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        gpioDelay(10); // Delay 10 ms
    }

    // Cleanup (should not reach here if signal handler works)
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio

    return 0;
}

