#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 29.1 // cm/us
#define MIN_DISTANCE 2.0   // cm
#define MAX_DISTANCE 400.0  // cm
#define TOO_CLOSE_DISTANCE 10.0 // cm

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance using HC-SR04 sensor
float measure_distance() {
    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure the echo pulse width
    uint32_t start_tick = 0, end_tick = 0;
    int start_sec, start_micros, end_sec, end_micros;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 50000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 50000) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0; // Timeout
    }

    gpioTime(PI_TIME_RELATIVE, &start_sec, &start_micros);
    start_tick = start_sec * 1000000 + start_micros;

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 50000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 50000) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0; // Timeout
    }

    gpioTime(PI_TIME_RELATIVE, &end_sec, &end_micros);
    end_tick = end_sec * 1000000 + end_micros;

    // Calculate pulse width in microseconds
    uint32_t pulse_width = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)pulse_width / 2.0 / SPEED_OF_SOUND;

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Measure distance
        float distance = measure_distance();

        // Check for timeout
        if (distance < 0.0) {
            fprintf(stderr, "Timeout occurred\n");
        } else {
            // Validate reading
            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                printf("Invalid reading\n");
            } else {
                // Print distance
                printf("Distance: %.2f cm\n", distance);

                // Check if too close
                if (distance < TOO_CLOSE_DISTANCE) {
                    printf("Too close!\n");
                }
            }
        }

        // Wait 500 ms
        gpioDelay(500);
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

