#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor and SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)
#define CONTINUOUS_MODE_REG 0x01
#define RANGE_REG 0x02
#define TRIGGER_REG 0x00
#define DISTANCE_LOW_REG 0x0C
#define DISTANCE_HIGH_REG 0x0D
#define MIN_DISTANCE 200
#define MAX_DISTANCE 5000

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance(uint16_t *distance);
void log_distance(uint16_t distance);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int cs_pin;
    int continuous_mode_reg;
    int range_reg;
    int trigger_reg;
    int distance_low_reg;
    int distance_high_reg;
    int min_distance;
    int max_distance;
} sensor_config_t;

// Initialize sensor configuration
sensor_config_t sensor_config = {
    SPI_CHANNEL,
    SPI_SPEED,
    CS_PIN,
    CONTINUOUS_MODE_REG,
    RANGE_REG,
    TRIGGER_REG,
    DISTANCE_LOW_REG,
    DISTANCE_HIGH_REG,
    MIN_DISTANCE,
    MAX_DISTANCE
};

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating program.\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to initialize the sensor
int init_sensor() {
    char buf[2];

    // Set continuous measurement mode
    buf[0] = CONTINUOUS_MODE_REG;
    buf[1] = 0x01;
    if (spiWrite(spi_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to continuous mode register: %s\n", strerror(errno));
        return -1;
    }

    // Set range to 5 meters
    buf[0] = RANGE_REG;
    buf[1] = 0x00;
    if (spiWrite(spi_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to range register: %s\n", strerror(errno));
        return -1;
    }

    // Trigger a measurement
    buf[0] = TRIGGER_REG;
    buf[1] = 0x01;
    if (spiWrite(spi_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to trigger register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the distance from the sensor
int read_distance(uint16_t *distance) {
    char tx_buf[1];
    char rx_buf[2];

    // Read low byte
    tx_buf[0] = DISTANCE_LOW_REG;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error reading low byte: %s\n", strerror(errno));
        return -1;
    }

    // Read high byte
    tx_buf[0] = DISTANCE_HIGH_REG;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error reading high byte: %s\n", strerror(errno));
        return -1;
    }

    // Combine the bytes to form the distance
    *distance = (rx_buf[1] << 8) | rx_buf[0];

    return 0;
}

// Function to log the distance to a file
void log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    uint16_t distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Distance out of range: %u mm\n", distance);
            }
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

