#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define SI1120_RESET_REG 0x30
#define SI1120_RESET_VALUE 0x01
#define SI1120_PART_ID_REG 0x00
#define SI1120_PART_ID_VALUE 0x41
#define SI1120_ALS_LOW_REG 0x22
#define SI1120_ALS_HIGH_REG 0x23
#define SI1120_PS1_LOW_REG 0x18
#define SI1120_PS1_HIGH_REG 0x19
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_byte(int handle, int reg, int val);
int i2c_read_byte(int handle, int reg);
int i2c_read_word(int handle, int reg);
int reset_sensor(int handle);
int verify_part_id(int handle);
int read_als_data(int handle, uint16_t *als_value);
int read_ps1_data(int handle, uint16_t *ps1_value);
int log_data(FILE *fp, uint16_t als_value, uint16_t ps1_value);
void signal_handler(int signal);

// I2C write function with retry
int i2c_write_byte(int handle, int reg, int val) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(handle, reg, val);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to I2C (reg 0x%02X, val 0x%02X): %d. Retry %d/%d\n", reg, val, result, retries + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to write to I2C after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// I2C read function with retry
int i2c_read_byte(int handle, int reg) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result; // Success
        } else {
            fprintf(stderr, "Error reading from I2C (reg 0x%02X): %d. Retry %d/%d\n", reg, result, retries + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read from I2C after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// I2C read word function (little-endian)
int i2c_read_word(int handle, int reg) {
    int low_byte = i2c_read_byte(handle, reg);
    int high_byte = i2c_read_byte(handle, reg + 1);

    if (low_byte < 0 || high_byte < 0) {
        return -1; // Indicate failure
    }

    return (high_byte << 8) | low_byte; // Combine into little-endian word
}

// Sensor reset function
int reset_sensor(int handle) {
    if (i2c_write_byte(handle, SI1120_RESET_REG, SI1120_RESET_VALUE) != 0) {
        fprintf(stderr, "Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete (10ms)
    return 0;
}

// Sensor part ID verification function
int verify_part_id(int handle) {
    int part_id = i2c_read_byte(handle, SI1120_PART_ID_REG);
