#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x39
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define AMBIENT_LOW_REG 0x22
#define AMBIENT_HIGH_REG 0x23
#define PROXIMITY_LOW_REG 0x24
#define PROXIMITY_HIGH_REG 0x25

int i2c_fd = -1;
FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signum);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(0);
    }
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to write a byte to an I2C register
int write_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int read_register(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from two I2C registers (little-endian)
int read_16bit(int fd, unsigned char low_reg, unsigned char high_reg, unsigned short *value) {
    unsigned char low, high;
    if (read_register(fd, low_reg, &low) != 0) return -1;
    if (read_register(fd, high_reg, &high) != 0) return -1;
    *value = (high << 8) | low;
    return 0;
}

// Function to initialize the Si1182 sensor
int init_sensor(int fd) {
    unsigned char part_id;

    // Verify Part ID
    if (read_register(fd, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Error reading Part ID register.\n");
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X (expected 0x82).\n", part_id);
        return -1;
    }

    // Configure Measurement Rate
    if (write_register(fd, MEAS_RATE_REG, 0x07) != 0) {
        fprintf(stderr, "Error writing to Measurement Rate register.\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, float *lux, unsigned short *proximity) {
    unsigned short ambient_raw, proximity_raw;

    if (read_16bit(fd, AMBIENT_LOW_REG, AMBIENT_HIGH_REG, &ambient_raw) != 0) {
        fprintf(stderr, "Error reading ambient light data.\n");
        return -1;
    }
    if (read_16bit(fd, PROXIMITY_LOW_REG, PROXIMITY_HIGH_REG, &proximity_raw) != 0) {
        fprintf(stderr, "Error reading proximity data.\n");
        return -1;
    }

    *lux = (float)ambient_raw * 0.1;
    *proximity = proximity_raw;

    return 0;
}

// Function to log data to a file
int log_data(FILE *fp, float lux, unsigned short proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), 4, ".%03d", (int)(1000 * (rawtime - (time_t)rawtime)));

    if (fprintf(fp, "%s,%f,%u\n", timestamp, lux, proximity) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (init_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    float lux;
    unsigned short proximity;

    // Main loop
    while (1) {
        if (read_sensor_data(i2c_fd, &lux, &proximity) == 0) {
            if (log_data(log_file, lux, proximity) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
            printf("Timestamp: %ld, Lux: %.2f, Proximity: %u\n", time(NULL), lux, proximity);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        usleep(100000); // 100 ms
    }

    // The following lines will never be reached due to the infinite loop.
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

