#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define DISTANCE_THRESHOLD 20.0 // cm
#define TRIGGER_PULSE_DURATION 10 // us

// Global variables
volatile static uint32_t start_tick = 0;
volatile static uint32_t end_tick = 0;
volatile static int echo_active = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to generate a 10 us trigger pulse
void trigger_pulse() {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: Failed to set TRIGGER_PIN high\n");
        gpioTerminate();
        exit(1);
    }
    gpioDelay(TRIGGER_PULSE_DURATION);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to set TRIGGER_PIN low\n");
        gpioTerminate();
        exit(1);
    }
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Rising edge
        start_tick = tick;
        echo_active = 1;
    } else if (level == 0 && echo_active) {
        // Falling edge
        end_tick = tick;
        echo_active = 0;

        // Calculate pulse width
        uint32_t pulse_width = end_tick - start_tick;

        // Calculate distance in cm
        float distance = (pulse_width * SPEED_OF_SOUND) / 2.0;

        // Print distance
        printf("Distance: %.2f cm\n", distance);

        // Control buzzer
        if (distance < DISTANCE_THRESHOLD) {
            if (gpioWrite(BUZZER_PIN, 1) < 0) {
                fprintf(stderr, "Error: Failed to set BUZZER_PIN high\n");
                gpioTerminate();
                exit(1);
            }
        } else {
            if (gpioWrite(BUZZER_PIN, 0) < 0) {
                fprintf(stderr, "Error: Failed to set BUZZER_PIN low\n");
                gpioTerminate();
                exit(1);
            }
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set TRIGGER_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set ECHO_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set BUZZER_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Set alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(50); // Delay between measurements
    }

    return 0;
}

