#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds (50ms)

// Global variable for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance using HC-SR04 sensor
float measureDistance() {
    long long start_tick, end_tick, diff_tick;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0; // Timeout
    }

    start_tick = gpioTick();

    // Wait for echo to end
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0; // Timeout
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to set servo angle
void setServoAngle(int angle) {
    // Map angle (0-180) to pulse width (500-2500 us)
    int pulse_width = 500 + (int)((float)angle / 180.0 * 2000.0);
    gpioServo(SERVO_PIN, pulse_width);
}

// Function to map distance to servo angle
int mapDistanceToAngle(float distance) {
    int angle;

    if (distance >= 200.0) {
        angle = 0;
    } else if (distance <= 20.0) {
        angle = 180;
    } else {
        angle = (int)((distance - 20.0) / (200.0 - 20.0) * 180.0);
    }

    return angle;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float distance = measureDistance();

        if (distance > 0) {
            int angle = mapDistanceToAngle(distance);
            setServoAngle(angle);

            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    setServoAngle(90); // Set servo to a safe position
    gpioTerminate();

    return 0;
}

