#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define TIMEOUT_US 50000

// Global variable for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Stopping servo and terminating pigpio...\n");
    program_running = 0;
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measurePulseWidth() {
    long start_tick, end_tick, pulse_duration;

    // Wait for rising edge with timeout
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for falling edge with timeout
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_duration = end_tick - start_tick;
    if (pulse_duration < 0) {
        // Handle tick rollover
        pulse_duration += 0xFFFFFFFF + 1; // Add 2^32
    }

    return pulse_duration;
}

// Function to calculate distance in centimeters
float calculateDistance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate error
    }
    return (pulse_duration * SPEED_OF_SOUND) / 2.0;
}

// Function to map distance to servo angle
int mapDistanceToAngle(float distance) {
    if (distance < 0) {
        return -1; // Indicate error
    }
    if (distance <= 20) {
        return 0;
    } else if (distance >= 200) {
        return 180;
    } else {
        return (int)(((distance - 20) / (200 - 20)) * 180);
    }
}

// Function to set the servo angle
void setServoAngle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid angle: %d\n", angle);
        return;
    }
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the echo pulse width
        long pulse_duration = measurePulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulse_duration);

        // Map the distance to a servo angle
        int angle = mapDistanceToAngle(distance);

        // Set the servo angle
        if (angle != -1) {
            setServoAngle(angle);
        }

        // Print the distance and angle
        printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Stop the servo and terminate pigpio before exiting
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();

    return 0;
}

