int read_sensor_data(int *temperature_raw, int *humidity_raw);
float convert_temperature(int raw_temperature);
float convert_humidity(int raw_humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Opens the I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configures the Si7005 sensor
int configure_sensor() {
    int result = i2cWriteByteData(i2c_handle, CONFIG_REGISTER, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // 10 ms delay
    return 0;
}

// Reads temperature and humidity data from the sensor
int read_sensor_data(int *temperature_raw, int *humidity_raw) {
    int temp_result, hum_result;

    // Read temperature
    temp_result = i2cWriteByte(i2c_handle, TEMPERATURE_REGISTER);
    if (temp_result < 0) {
        fprintf(stderr, "Failed to write temperature register address: %d\n", temp_result);
        return -1;
    }
    gpioDelay(10000); // 10 ms delay
    *temperature_raw = i2cReadWordData(i2c_handle, TEMPERATURE_REGISTER);
    if (*temperature_raw < 0) {
        fprintf(stderr, "Failed to read temperature data: %d\n", *temperature_raw);
        return -1;
    }

    // Read humidity
    hum_result = i2cWriteByte(i2c_handle, HUMIDITY_REGISTER);
    if (hum_result < 0) {
        fprintf(stderr, "Failed to write humidity register address: %d\n", hum_result);
        return -1;
    }
    gpioDelay(10000); // 10 ms delay
    *humidity_raw = i2cReadWordData(i2c_handle, HUMIDITY_REGISTER);
    if (*humidity_raw < 0) {
        fprintf(stderr, "Failed to read humidity data: %d\n", *humidity_raw);
        return -1;
    }

    return 0;
}

// Converts raw temperature data to Celsius
float convert_temperature(int raw_temperature) {
    return (175.72 * raw_temperature) / 65536.0 - 46.85;
}

// Converts raw humidity data to percentage relative humidity
float convert_humidity(int raw_humidity) {
    return (125.0 * raw_humidity) / 65536.0 - 6.0;
}

// Logs the temperature and humidity data to the console
void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int temperature_raw, humidity_raw;
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&temperature_raw, &humidity_raw) == 0) {
            // Convert data
            temperature = convert_temperature(temperature_raw);
            humidity = convert_humidity(humidity_raw);

            // Log data
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Re-initializing I2C.\n");
            i2cClose(i2c_handle);
            if (open_i2c_bus() != 0) {
                fprintf(stderr, "Failed to re-open I2C bus. Exiting.\n");
                break;
            }
            if (configure_sensor() != 0) {
                fprintf(stderr, "Failed to re-configure sensor. Exiting.\n");
                break;
            }
        }

        // Sleep for 2 seconds
        sleep(SLEEP_SECONDS);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

