int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *temp, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[14];
    int result = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    *temp = (int16_t)((buf[6] << 8) | buf[7]);
    *gyro_x = (int16_t)((buf[8] << 8) | buf[9]);
    *gyro_y = (int16_t)((buf[10] << 8) | buf[11]);
    *gyro_z = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

