    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPU-6050 data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z;

        if (read_raw_data(&accel_x, &accel_y, &accel_z, &temp, &gyro_x, &gyro_y, &gyro_z) == 0) {
            printf("%d %d %d %d %d %d %d\n", accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("MPU-6050 data logging stopped.\n");

    return 0;
}

