    int raw_ambient = read_16bit_value(fd, AMBIENT_TEMP_REG);
    int raw_object = read_16bit_value(fd, OBJECT_TEMP_REG);

    if (raw_ambient == -1 || raw_object == -1) {
        data.ambient_temp = -273.15; // Indicate error
        data.object_temp = -273.15;  // Indicate error
    } else {
        data.ambient_temp = convert_to_celsius(raw_ambient);
        data.object_temp = convert_to_celsius(raw_object);
    }
    return data;
