#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define SAMPLE_INTERVAL_SEC 5
#define TEMP_MIN -40.0
#define TEMP_MAX 125.0

// Global variables
int i2c_handle;
FILE *temp_log_file = NULL;
FILE *error_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    float temperature;
    time_t timestamp;
} sensor_data_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Read temperature from the sensor
int read_temperature(float *temperature) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buf[3];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command");
        return -1;
    }

    gpioDelay(20); // Wait for measurement (adjust as needed)

    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        log_error("Failed to read temperature data");
        return -1;
    }

    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = -45.0 + (175.0 * raw_temp / 65535.0);

    // Data validation
    if (*temperature < TEMP_MIN || *temperature > TEMP_MAX) {
        log_error("Temperature out of range");
        return -1;
    }

    return 0;
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (temp_log_file == NULL) {
        log_error("Temperature log file is not open");
        return -1;
    }

    fprintf(temp_log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(temp_log_file); // Ensure data is written immediately
    return 0;
}

// Log errors to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (error_log_file == NULL) {
        fprintf(stderr, "Error log file is not open: %s\n", message);
        return -1;
    }

    fprintf(error_log_file, "%s, %s\n", timestamp, message);
    fflush(error_log_file);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Exiting...\n");
        terminate = 1;
    }
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (temp_log_file != NULL) {
        fclose(temp_log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    temp_log_file = fopen("enclosure_temp_log.txt", "a");
    if (temp_log_file == NULL) {
        fprintf(stderr, "Failed to open temperature log file\n");
        cleanup();
        return 1;
    }

    error_log_file = fopen("error_log.txt", "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                log_error("Failed to log temperature");
            }
        } else {
            log_error("Failed to read temperature");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

