#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASURE_COMMAND_1 0x36
#define MEASURE_COMMAND_2 0x08
#define DATA_FRAME_SIZE 9
#define LOG_FILE "pressure_log.csv"
#define POLLING_INTERVAL_MS 1000 // 1 second

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int initialize_i2c();
int configure_sensor();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t data[], int len);
SensorData process_sensor_data(uint8_t *data);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the sensor for continuous measurement
int configure_sensor() {
    char command[2] = {MEASURE_COMMAND_1, MEASURE_COMMAND_2};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Wait at least 1 ms
    return 0;
}

// Read data from the sensor
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, DATA_FRAME_SIZE);
    if (result != DATA_FRAME_SIZE) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int len) {
    for (int i = 0; i < len / 3; i++) {
        uint8_t crc = crc8(&data[i * 3], 2);
        if (crc != data[i * 3 + 2]) {
            fprintf(stderr, "CRC validation failed for data segment %d\n", i);
            return -1;
        }
    }
    return 0;
}

// Process sensor data and convert to physical units
SensorData process_sensor_data(uint8_t *data) {
    SensorData sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t pressure_scale_factor = (data[6] << 8) | data[7];

    // Convert raw values to physical units
    sensor_data.pressure = (float)raw_pressure / (float)pressure_scale_factor;
    sensor_data.temperature = (float)raw_temperature / 200.0; // Temperature is in 200ths of degrees Celsius

    return sensor_data;
}

// Log data to file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.3f,%.3f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure(Pa),Temperature(C)\n");
    }
    rewind(log_file);

    uint8_t data[DATA_FRAME_SIZE];
    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate CRC
            if (validate_crc(data, DATA_FRAME_SIZE) == 0) {
                // Process sensor data
                sensor_data = process_sensor_data(data);

                // Log data
                log_data(sensor_data);
            } else {
                fprintf(stderr, "CRC validation failed, skipping data logging.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(POLLING_INTERVAL_MS); // Wait before next reading
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

