volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *bus);
int i2c_write(int fd, unsigned char addr, unsigned char *data, int len);
int i2c_read(int fd, unsigned char addr, unsigned char *data, int len);
unsigned char crc8(const unsigned char *data, int len);
int read_sht40(int fd, float *temperature, float *humidity);
void log_data(FILE *fp, float temperature, float humidity);
