            temperature, humidity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("sht40_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    float temperature, humidity;
    // Main loop
    while (program_running) {
        if (read_sht40(i2c_fd, &temperature, &humidity) == 0) {
            log_data(log_file, temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", RETRY_DELAY_SEC);
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, ERROR: Failed to read sensor data\n",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
            fflush(log_file);
        }

        sleep(5);
    }

    // Clean up resources
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

