#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP31_ADDR 0x28
#define MEASURE_CMD_1 0x21
#define MEASURE_CMD_2 0x96
#define SAMPLE_INTERVAL_MS 100
#define RETRY_COUNT 3
#define BACKOFF_DELAY_MS 10

// Global variables
static volatile sig_atomic_t terminate_flag = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint8_t cmd1, uint8_t cmd2);
int read_data(int handle, uint8_t *data, int count);
sensor_data_t convert_data(uint8_t *raw_data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate_flag = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to SDP31 with retry logic
int send_command(int handle, uint8_t cmd1, uint8_t cmd2) {
    uint8_t cmd[2] = {cmd1, cmd2};
    int retries = 0;
    int result = -1;

    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(handle, (char *)cmd, 2);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries)); // Exponential backoff
            retries++;
        }
    }
    fprintf(stderr, "I2C write failed after %d attempts.\n", RETRY_COUNT);
    return -1; // Failure
}

// Read data from SDP31 with retry logic
int read_data(int handle, uint8_t *data, int count) {
    int retries = 0;
    int result = -1;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(handle, (char *)data, count);
        if (result == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries)); // Exponential backoff
            retries++;
        }
    }
    fprintf(stderr, "I2C read failed after %d attempts.\n", RETRY_COUNT);
    return -1; // Failure
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(uint8_t *raw_data) {
    sensor_data_t data;
    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];

    data.pressure_pa = (float)raw_pressure / 60.0;
    data.temperature_c = (float)raw_temperature / 200.0;

    return data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure_pa, data.temperature_c);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("airflow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate_flag) {
        uint8_t raw_data[6];
        sensor_data_t sensor_data;

        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD_1, MEASURE_CMD_2) != 0) {
            fprintf(stderr, "Failed to send measurement command.\n");
            continue; // Try again
        }

        gpioDelay(1); // Wait at least 1 ms

        // Read data
        if (read_data(i2c_handle, raw_data, 6) != 0) {
            fprintf(stderr, "Failed to read data.\n");
            continue; // Try again
        }

        // Convert data
        sensor_data = convert_data(raw_data);

        // Log data
        log_data(sensor_data);

        gpioDelay(SAMPLE_INTERVAL_MS); // Sample every 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

