#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int write_i2c(int handle, int reg, int val);
int read_i2c(int handle, int reg, char *buf, int count);
int read_sensor_data(int handle, int command, unsigned int *raw_value);
float convert_temperature(unsigned int raw_value);
float convert_humidity(unsigned int raw_value);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Write to I2C register
int write_i2c(int handle, int reg, int val) {
    int result = i2cWriteByteData(handle, reg, val);
    if (result < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read from I2C register
int read_i2c(int handle, int reg, char *buf, int count) {
    int result = i2cReadI2CBlockData(handle, reg, buf, count);
    if (result < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return result;
}

// Read sensor data with retry logic
int read_sensor_data(int handle, int command, unsigned int *raw_value) {
    char buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        if (write_i2c(handle, 0, command) < 0) {
            fprintf(stderr, "Failed to write command, retry %d\n", retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(20000); // Wait for measurement (20ms)

        result = read_i2c(handle, 0, buf, 2);
        if (result == 2) {
            *raw_value = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to read data, retry %d\n", retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Convert raw temperature to Celsius
float convert_temperature(unsigned int raw_value) {
    return (175.72 * raw_value / 65536.0) - 46.85;
}

// Convert raw humidity to %RH
float convert_humidity(unsigned int raw_value) {
    float humidity = (125.0 * raw_value / 65536.0) - 6.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() < 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned int raw_temperature, raw_humidity;
        float temperature, humidity;

        // Read temperature
        if (read_sensor_data(i2c_handle, TEMP_CMD, &raw_temperature) == 0) {
            temperature = convert_temperature(raw_temperature);
        } else {
            temperature = -999.0; // Indicate error
        }

        // Read humidity
        if (read_sensor_data(i2c_handle, HUMID_CMD, &raw_humidity) == 0) {
            humidity = convert_humidity(raw_humidity);
        } else {
            humidity = -999.0; // Indicate error
        }

        // Log data
        log_data(temperature, humidity);

        // Print to console
        printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temperature, humidity);

        // Wait for next sample
        gpioDelay(SAMPLE_INTERVAL_S * 1000000); // Delay in microseconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

