#define SDP800_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F
#define DATA_LENGTH 9
#define LOG_FILE "airflow_data.txt"
#define SAMPLE_INTERVAL_MS 100

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *device);
int i2c_write(int fd, unsigned char addr, unsigned char *data, int len);
int i2c_read(int fd, unsigned char addr, unsigned char *data, int len);
unsigned char crc8(const unsigned char *data, int len);
int read_sensor_data(int fd, sensor_data_t *data);
float convert_pressure(unsigned int raw_pressure, unsigned int scale_factor);
float convert_temperature(unsigned int raw_temperature);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int sig);
int i2c_close(int fd);
int file_close(FILE *fp);

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, unsigned char addr, unsigned char *data, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    ssize_t bytes_written = write(fd, data, len);
    if (bytes_written != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char addr, unsigned char *data, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    ssize_t bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Read sensor data function
int read_sensor_data(int fd, sensor_data_t *data) {
    unsigned char buffer[DATA_LENGTH];
    unsigned char command[2] = {(MEASURE_COMMAND >> 8) & 0xFF, MEASURE_COMMAND & 0xFF};

    // Trigger continuous measurement
    if (i2c_write(fd, SDP800_ADDRESS, command, 2) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for measurement (at least 45ms)
    usleep(45000); // 45ms

    // Read 9 bytes of data
    if (i2c_read(fd, SDP800_ADDRESS, buffer, DATA_LENGTH) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "Pressure CRC error\n");
        return -1;
    }
    if (crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "Temperature CRC error\n");
        return -1;
    }
    if (crc8(buffer + 6, 2) != buffer[8]) {
        fprintf(stderr, "Scale factor CRC error\n");
        return -1;
    }

    // Extract raw values
    unsigned int raw_pressure = (buffer[0] << 8) | buffer[1];
    unsigned int raw_temperature = (buffer[3] << 8) | buffer[4];
    unsigned int scale_factor = (buffer[6] << 8) | buffer[7];

    // Convert to physical units
    data->pressure = convert_pressure(raw_pressure, scale_factor);
    data->temperature = convert_temperature(raw_temperature);

    return 0;
}

// Convert raw pressure to Pascal
float convert_pressure(unsigned int raw_pressure, unsigned int scale_factor) {
    return (float)raw_pressure / (float)scale_factor;
}

// Convert raw temperature to Celsius
float convert_temperature(unsigned int raw_temperature) {
    return (float)raw_temperature / 200.0f - 45.0f;
}

// Log data to file
int log_data(FILE *fp, float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    keep_running = 0;
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C device");
        return -1;
    }
    return 0;
}

// File close function
int file_close(FILE *fp) {
    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_DEVICE);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2c_close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (keep_running) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            // Log data
            if (log_data(log_file, sensor_data.pressure, sensor_data.temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Clean up resources
    i2c_close(i2c_fd);
    file_close(log_file);

    return EXIT_SUCCESS;
}

