// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define SAMPLE_INTERVAL 5 // seconds
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

// Global variables
int i2c_handle;
FILE *temp_log_file = NULL;
FILE *error_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sts30(float *temperature);
uint8_t crc8(const uint8_t *data, size_t len);
int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t raw_temperature;
    float temperature_celsius;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Function to read temperature from STS30-DIS sensor
int read_sts30(float *temperature) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buffer[3];
    uint8_t crc;
    uint16_t raw_temperature;

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        log_error("Failed to write measurement command");
        return -1;
    }

    // Wait for conversion (at least 15 ms)
    gpioDelay(15000); // 15 ms

    // Read 3 bytes (2 data bytes + 1 CRC byte)
    if (i2cReadDevice(i2c_handle, buffer, 3) != 3) {
        log_error("Failed to read temperature data");
        return -1;
    }

    // Extract data and CRC
    raw_temperature = (buffer[0] << 8) | buffer[1];
    crc = buffer[2];

    // CRC validation
    uint8_t data[2] = {buffer[0], buffer[1]};
    uint8_t calculated_crc = crc8(data, 2);

    if (calculated_crc != crc) {
        log_error("CRC validation failed");
        return -1;
    }

    // Convert raw value to temperature (degrees Celsius)
    *temperature = -45 + 175 * ((float)raw_temperature / 65535.0);

    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INITIAL;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (temp_log_file == NULL) {
        temp_log_file = fopen("enclosure_temp_log.txt", "a");
        if (temp_log_file == NULL) {
            log_error("Failed to open temperature log file");
            return -1;
        }
    }

    fprintf(temp_log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(temp_log_file); // Ensure data is written to disk
    return 0;
}

// Function to log errors to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (error_log_file == NULL) {
        error_log_file = fopen("error_log.txt", "a");
        if (error_log_file == NULL) {
            perror("Failed to open error log file");
            return -1;
        }
    }

    fprintf(error_log_file, "%s, %s\n", timestamp, message);
    fflush(error_log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        terminate = 1;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_sts30(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    if (temp_log_file != NULL) {
        fclose(temp_log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();

    return 0;
}

