void log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int signum);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t addr, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    ssize_t bytes_written = write(fd, data, len);
    if (bytes_written != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t addr, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    ssize_t bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from SHT40
int read_sht40(int fd, float *temperature, float *humidity) {
    uint8_t data[6];
    uint8_t cmd[1] = {MEASURE_CMD};

    if (i2c_write(fd, SHT40_ADDR, cmd, 1) != 0) {
        fprintf(stderr, "Error writing measurement command\n");
        return -1;
    }

    usleep(8500); // Wait for at least 8.5 ms

    if (i2c_read(fd, SHT40_ADDR, data, 6) != 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    *humidity = 100.0 * (float)raw_humidity / 65535.0;

    return 0;
}

// Function to log data to file
void log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (program_running) {
        if (read_sht40(i2c_fd, &sensor_data.temperature, &sensor_data.humidity) == 0) {
            log_data(log_file, sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds.\n");
        }

        sleep(5);
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

