#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_CMD 0xE3
#define HUMID_CMD 0xE5
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60

// Structure for sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} SensorData;

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular buffer
SensorData data_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, float *temperature, float *humidity);
void control_fan(int gpio_pin, float temperature);
void log_data(SensorData data);
void signal_handler(int signal);
void print_buffer();

// Function to read sensor data
int read_sensor_data(int i2c_handle, float *temperature, float *humidity) {
    unsigned char buf[2];
    int raw_temp, raw_humidity;
    int retries = 3;

    // Read temperature
    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, TEMP_CMD) != 0) {
            fprintf(stderr, "Error writing temperature command. Retries remaining: %d\n", retries);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }
        gpioDelay(10000); // 10ms delay
        if (i2cReadDevice(i2c_handle, (char *)buf, 2) == 2) {
            raw_temp = (buf[0] << 8) | buf[1];
            break;
        } else {
            fprintf(stderr, "Error reading temperature data. Retries remaining: %d\n", retries);
            retries--;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read temperature after multiple retries.\n");
        return -1; // Indicate failure
    }

    // Read humidity
    retries = 3;
    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, HUMID_CMD) != 0) {
            fprintf(stderr, "Error writing humidity command. Retries remaining: %d\n", retries);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }
        gpioDelay(10000); // 10ms delay
        if (i2cReadDevice(i2c_handle, (char *)buf, 2) == 2) {
            raw_humidity = (buf[0] << 8) | buf[1];
            break;
        } else {
            fprintf(stderr, "Error reading humidity data. Retries remaining: %d\n", retries);
            retries--;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read humidity after multiple retries.\n");
        return -1; // Indicate failure
    }

    // Convert raw values to temperature and humidity
    *temperature = 175.72 * raw_temp / 65536.0 - 46.85;
    *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

    return 0; // Indicate success
}

// Function to control the fan
void control_fan(int gpio_pin, float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpioWrite(gpio_pin, 1); // Turn fan ON
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpioWrite(gpio_pin, 0); // Turn fan OFF
    }
}

// Function to log data
void log_data(SensorData data) {
    data_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to print the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&data_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp_str, data_buffer[index].temperature, data_buffer[index].humidity);
    }
    printf("--- End of Log ---\n\n");
}

int main() {
    float temperature, humidity;
    SensorData data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan OFF

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Smart Agriculture Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &temperature, &humidity) == 0) {
            // Get current timestamp
            data.timestamp = time(NULL);
            data.temperature = temperature;
            data.humidity = humidity;

            // Log the data
            log_data(data);

            // Control the fan
            control_fan(FAN_GPIO, temperature);

            // Print the data buffer every 60 seconds
            if (buffer_index % 30 == 0) {
                print_buffer();
            }

            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 2 seconds.\n");
        }

        gpioDelay(2000000); // 2 seconds delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn off the fan
    gpioTerminate();

    return 0;
}

