    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&data_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp_str, data_buffer[index].temperature, data_buffer[index].humidity);
    }
    printf("--- End of Log ---\n\n");
}

int main() {
    float temperature, humidity;
    SensorData data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan OFF

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Smart Agriculture Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &temperature, &humidity) == 0) {
            // Get current timestamp
            data.timestamp = time(NULL);
            data.temperature = temperature;
            data.humidity = humidity;

            // Log the data
            log_data(data);

            // Control the fan
            control_fan(FAN_GPIO, temperature);

            // Print the data buffer every 60 seconds
            if (buffer_index % 30 == 0) {
                print_buffer();
            }

            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 2 seconds.\n");
        }

        gpioDelay(2000000); // 2 seconds delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn off the fan
    gpioTerminate();

    return 0;
}

