// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Send command to SCD40
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return 1;
    }
    return 0;
}

// Read data from SCD40
int read_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return 1;
    }
    return 0;
}

// Check if data is ready
int check_data_ready() {
    uint8_t data[3];
    if (send_command(CMD_DATA_READY) != 0) {
        return 0;
    }
    gpioDelay(1); // Small delay after sending the command
    if (read_data(data, 3) != 0) {
        return 0;
    }

    uint16_t data_ready = (data[0] << 8) | data[1];
    return (data_ready == 0x0000) ? 0 : 1; // Return 0 if data is ready, 1 otherwise
}

// Read measurement data
int read_measurement(uint16_t *co2, uint16_t *temperature, uint16_t *humidity) {
    uint8_t data[9];

    if (send_command(CMD_READ_MEASUREMENT) != 0) {
        return 1;
    }
    gpioDelay(1); // Small delay after sending the command
    if (read_data(data, 9) != 0) {
        return 1;
    }

    // CRC check
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5] || crc8(data + 6, 2) != data[8]) {
        fprintf(stderr, "CRC check failed\n");
        return 1;
    }

    *co2 = (data[0] << 8) | data[1];
    *temperature = (data[3] << 8) | data[4];
    *humidity = (data[6] << 8) | data[7];

    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Log data to file
int log_data(uint16_t co2, uint16_t temperature, uint16_t humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    float temp_celsius = -45 + 175 * (float)temperature / (float)(0xFFFF);
    float humidity_percent = 100 * (float)humidity / (float)(0xFFFF);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temp_celsius, humidity_percent);
    fflush(log_file);

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Terminating...\n");
    terminate = 1;
}

