#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_GET_DATA_READY_STATUS 0xE4B8
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// GPIO pin for LED
#define LED_PIN 17

// Measurement interval (seconds)
#define MEASUREMENT_INTERVAL 5

// Circular buffer size
#define BUFFER_SIZE 20

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int start_periodic_measurement();
int is_data_ready();
int read_measurement(sensor_data_t *data);
int stop_periodic_measurement();
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
sensor_data_t get_latest_reading(circular_buffer_t *buffer);
void print_reading(sensor_data_t data);
void control_led(uint16_t co2);
void signal_handler(int signal);
uint8_t crc8(const uint8_t *data, int len);

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Start periodic measurement failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Check if data is ready
int is_data_ready() {
    char buf[2];
    buf[0] = (CMD_GET_DATA_READY_STATUS >> 8) & 0xFF;
    buf[1] = CMD_GET_DATA_READY_STATUS & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Get data ready status write failed: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Get data ready status read failed: %d\n", result);
        return -1;
    }

    uint16_t status = (read_buf[0] << 8) | read_buf[1];
    return (status & 0x01) ? 1 : 0;
}

// Read measurement data
int read_measurement(sensor_data_t *data) {
    char buf[2];
    buf[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_READ_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Read measurement write failed: %d\n", result);
        return -1;
    }

    char read_buf[9];
    result = i2cReadDevice(i2c_handle, read_buf, 9);
    if (result != 9) {
        fprintf(stderr, "Read measurement read failed: %d\n", result);
        return -1;
    }

    // Extract data and CRC
    uint16_t co2_raw = (read_buf[0] << 8) | read_buf[1];
    uint8_t co2_crc = read_buf[2];
    uint16_t temperature_raw = (read_buf[3] << 8) | read_buf[4];
    uint8_t temperature_crc = read_buf[5];
    uint16_t humidity_raw = (read_buf[6] << 8) | read_buf[7];
    uint8_t humidity_crc = read_buf[8];

    // CRC validation
    uint8_t co2_data[2] = {read_buf[0], read_buf[1]};
    uint8_t temperature_data[2] = {read_buf[3], read_buf[4]};
    uint8_t humidity_data[2] = {read_buf[6], read_buf[7]};

    if (crc8(co2_data, 2) != co2_crc) {
        fprintf(stderr, "CO2 CRC check failed\n");
        return -1;
    }
    if (crc8(temperature_data, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }
    if (crc8(humidity_data, 2) != humidity_crc) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Store data
    data->co2 = co2_raw;
    data->temperature = temperature_raw;
    data->humidity = humidity_raw;

    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Stop periodic measurement failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get the latest reading from the circular buffer
sensor_data_t get_latest_reading(circular_buffer_t *buffer) {
