#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 4
#define TIMEOUT_US 50000 // 50ms timeout
#define MAX_FAILURES 3

static volatile int running = 1;
static FILE *log_file = NULL;
static int failure_count = 0;

// Structure to hold timestamps
typedef struct {
    uint32_t start;
    uint32_t end;
} Timestamps;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to get ISO-8601 timestamp
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
}

// Function to log data to file
void log_data(const char *timestamp, float temperature, const char *status) {
    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f, %s\n", timestamp, temperature, status);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to read temperature from TMP05 sensor
float read_temperature() {
    uint32_t start_tick, end_tick;
    uint32_t th = 0, tl = 0;
    int i;

    // Measure TH (High time)
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for low signal (TH).\n");
            return -1000.0; // Indicate error
        }
    }
    end_tick = gpioTick();
    th = end_tick - start_tick;

    // Measure TL (Total cycle time)
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for high signal (TL).\n");
            return -1000.0; // Indicate error
        }
    }
    end_tick = gpioTick();
    tl = end_tick - start_tick;

    // Check for division by zero
    if (tl == 0) {
        fprintf(stderr, "Error: TL is zero, cannot divide.\n");
        return -1000.0; // Indicate error
    }

    // Calculate temperature
    float temperature = 4215.0 - (2143.0 * th / tl);

    return temperature;
}

int main() {
    char timestamp[21];
    float temperature;
    int consecutive_failures = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        temperature = read_temperature();

        if (temperature > -999.0) { // Valid reading
            consecutive_failures = 0; // Reset failure count
            get_iso8601_timestamp(timestamp);
            log_data(timestamp, temperature, "OK");

            // Validate temperature range
            if (temperature < -40.0 || temperature > 150.0) {
                fprintf(stderr, "Warning: Temperature out of range: %.2f\n", temperature);
            }
        } else {
            consecutive_failures++;
            get_iso8601_timestamp(timestamp);
            log_data(timestamp, 0.0, "ERROR");
            fprintf(stderr, "Error: Failed to read temperature. Failure count: %d\n", consecutive_failures);

            if (consecutive_failures >= MAX_FAILURES) {
                get_iso8601_timestamp(timestamp);
                log_data(timestamp, 0.0, "SENSOR MALFUNCTION");
                fprintf(stderr, "Error: Sensor malfunction detected!\n");
                consecutive_failures = MAX_FAILURES; // Prevent further increments
            }
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Clean up
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

