#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD_HIGH 0x24
#define MEASURE_CMD_LOW 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 1000
#define LOG_FILE "environmental_data.txt"
#define LOG_INTERVAL_SEC 5
#define SINE_PERIOD_SEC 3600 // 1 hour
#define SINE_TEMP_OFFSET 2.0
#define SINE_HUMID_OFFSET 5.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_pigpio();
int open_i2c();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
SensorData convert_raw_data(const uint8_t *data);
SensorData apply_sine_wave(SensorData data, time_t timestamp);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(15000); // Wait 15 ms

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    return 0;
}

// Calculate CRC
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc_calculated = calculate_crc(data, len - 1);
    return (crc_calculated == data[len - 1]);
}

// Convert raw data to temperature and humidity
SensorData convert_raw_data(const uint8_t *data) {
    SensorData sensor_data;
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    sensor_data.temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    sensor_data.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return sensor_data;
}

