float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    sensor_data_t sensor_data;
    uint8_t raw_data[6];
    uint16_t raw_temperature, raw_humidity;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Error sending measurement command. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in milliseconds
            continue;
        }

        // Wait for measurement to complete (at least 15ms)
        gpioDelay(15000); // 15ms

        // Read sensor data
        if (read_sensor_data(raw_data) != 0) {
            fprintf(stderr, "Error reading sensor data. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in milliseconds
            continue;
        }

        // Validate CRC
        if (validate_crc(raw_data, 6) != 0) {
            fprintf(stderr, "CRC validation failed. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in milliseconds
            continue;
        }

        // Convert raw data to temperature and humidity
        raw_temperature = (raw_data[0] << 8) | raw_data[1];
        raw_humidity = (raw_data[3] << 8) | raw_data[4];

        sensor_data.temperature = convert_temperature(raw_temperature);
        sensor_data.humidity = convert_humidity(raw_humidity);

        // Log data
        if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
            fprintf(stderr, "Error logging data. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in milliseconds
    }

