int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return 1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksums
int validate_crc(const uint8_t *data, int len) {
    if (len != 6) {
        fprintf(stderr, "Invalid data length for CRC validation: %d\n", len);
        return 1;
    }

    uint8_t temp_crc = calculate_crc(data, 2);
    if (temp_crc != data[2]) {
        fprintf(stderr, "Temperature CRC validation failed: expected 0x%02X, got 0x%02X\n", data[2], temp_crc);
        return 1;
    }

    uint8_t humidity_crc = calculate_crc(data + 3, 2);
    if (humidity_crc != data[5]) {
        fprintf(stderr, "Humidity CRC validation failed: expected 0x%02X, got 0x%02X\n", data[5], humidity_crc);
        return 1;
    }

    return 0;
}

