float convert_temperature(uint16_t raw_temp) {
    return -45.0 + 175.0 * (float)raw_temp / 65535.0;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Log data to CSV file
int log_data(float temperature, float humidity) {
    FILE *fp = fopen(CSV_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return 1;
    }

    // Check if the file is empty or doesn't have a header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    }
    fseek(fp, 0, SEEK_END);

    // Get current timestamp
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20]; // YYYY-MM-DDTHH:MM:SSZ

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Write data to CSV file
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

    fclose(fp);
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

