#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_HUMIDITY 0xF5
#define MEASURE_TEMPERATURE 0xF3
#define PAIRED_READ 0xE0
#define RESET_COMMAND 0xFE

int i2c_handle;
FILE *log_file;

// Function to calculate CRC-8 checksum
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from the Si7021 sensor
int read_sensor(float *temperature, float *humidity) {
    unsigned char buf[3];
    int result;

    // Measure Humidity
    result = i2cWriteByte(i2c_handle, MEASURE_HUMIDITY);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Wait for measurement

    result = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }

    // CRC Check for Humidity
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    unsigned int raw_humidity = (buf[0] << 8) | buf[1];
    *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

    // Measure Temperature (Paired Reading)
    result = i2cWriteByte(i2c_handle, PAIRED_READ);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Wait for measurement

    result = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }

    // CRC Check for Temperature
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    unsigned int raw_temperature = (buf[0] << 8) | buf[1];
    *temperature = 175.72 * raw_temperature / 65536.0 - 46.85;

    return 0;
}

// Function to log data to a CSV file
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return;
    }

    if (temperature == -999.0 && humidity == -999.0) {
        fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
        fprintf(stderr, "ERROR: Sensor read failed. Logging ERROR to file.\n");
    } else {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    }
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_C,humidity_percent\n");
    }
    fflush(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        temperature = -999.0; // Initialize with error value
        humidity = -999.0;    // Initialize with error value

        result = read_sensor(&temperature, &humidity);
        if (result != 0) {
            fprintf(stderr, "Sensor read failed. Attempting reset.\n");
            i2cWriteByte(i2c_handle, RESET_COMMAND);
            gpioDelay(100); // Wait for reset
        } else {
            log_data(temperature, humidity);
        }

        sleep(5);
    }

    return 0;
}

