#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define DATA_FILE "airflow.dat"

// Global variables
int i2c_handle = -1;
FILE *data_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int write_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len, uint8_t crc);
int convert_data(uint8_t *data, sensor_data_t *sensor_data);
int log_data(FILE *file, sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    int handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Write command to the sensor
int write_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Convert raw data to pressure and temperature
int convert_data(uint8_t *data, sensor_data_t *sensor_data) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    uint8_t pressure_crc = data[2];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    uint8_t temperature_crc = data[5];
    uint8_t scale_factor_msb = data[6];
    uint8_t scale_factor_lsb = data[7];
    uint8_t scale_factor_xlsb = data[8];

    uint32_t scale_factor = ((uint32_t)scale_factor_msb << 16) | ((uint32_t)scale_factor_lsb << 8) | scale_factor_xlsb;

    if (!validate_crc(data, 2, pressure_crc)) {
        fprintf(stderr, "Pressure CRC validation failed\n");
        return -1;
    }

    if (!validate_crc(data + 3, 2, temperature_crc)) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return -1;
    }

    sensor_data->pressure = (float)raw_pressure / (float)scale_factor - 1000.0f;
    sensor_data->temperature = (float)raw_temperature / 200.0f - 45.0f;

    return 0;
}

// Log data to file
int log_data(FILE *file, sensor_data_t data) {
    if (fwrite(&data.pressure, sizeof(float), 1, file) != 1) {
        fprintf(stderr, "Failed to write pressure to file: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(&data.temperature, sizeof(float), 1, file) != 1) {
        fprintf(stderr, "Failed to write temperature to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c_connection();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open data file
    data_file = fopen(DATA_FILE, "wb");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    uint8_t sensor_data[9];
    sensor_data_t processed_data;
    while (!terminate) {
        // Write measurement command
        if (write_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
            break;
        }

        // Wait for conversion time
        gpioDelay(50); // 50ms

        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data, 9) != 0) {
