    while (!terminate) {
        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for conversion time
        gpioDelay(50); // 50 ms

        // Read sensor data
        if (read_sensor_data(&sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // CRC validation
        uint8_t data[2] = {(sensor_data.pressure >> 8) & 0xFF, sensor_data.pressure & 0xFF};
        uint8_t calculated_crc = calculate_crc(data, 2);

        if (calculated_crc != sensor_data.crc) {
            fprintf(stderr, "CRC validation failed! Calculated: 0x%02X, Received: 0x%02X\n", calculated_crc, sensor_data.crc);
            continue; // Skip logging if CRC fails
        }

        // Convert pressure
        float pressure = convert_pressure(sensor_data.pressure);

        // Log pressure
        if (log_pressure(pressure) != 0) {
            fprintf(stderr, "Error logging pressure\n");
        }

        // Sleep for 5 seconds
        gpioDelay(SLEEP_TIME * 1000); // Convert seconds to milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

