FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, uint16_t *raw_data);
float convert_to_flow_rate(uint16_t raw_data);
void set_fan_speed(int gpio_pin, float flow_rate);
void log_data(FILE *log_file, float flow_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");
    terminate = 1;
}

// Function to read sensor data from I2C
int read_sensor_data(int i2c_handle, uint16_t *raw_data) {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1; // Indicate failure
    }

    *raw_data = ((uint16_t)buffer[0] << 8) | (uint16_t)buffer[1];
    return 0; // Indicate success
}

// Function to convert raw data to flow rate (SLPM)
float convert_to_flow_rate(uint16_t raw_data) {
    // Mask off status bits and shift right by 2
    uint16_t flow_reading = (raw_data >> 2) & 0x3FFF; // Keep only 14 bits

    // Linear transfer function
    float flow_rate = (float)(flow_reading - 1638) * 10.0 / (14745 - 1638);
    return flow_rate;
}

// Function to set fan speed based on flow rate
void set_fan_speed(int gpio_pin, float flow_rate) {
    // Scale flow rate to PWM duty cycle (0-100%)
    int duty_cycle = (int)(flow_rate * 100.0 / 10.0); // Assuming max flow rate is 10 SLPM

    // Clamp duty cycle to 0-100
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    // Set PWM duty cycle
    gpioPWM(gpio_pin, duty_cycle * 255 / 100); // pigpio duty cycle is 0-255
}

// Function to log data to file
void log_data(FILE *log_file, float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255); // Set PWM range to 0-255

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t raw_data;
    float flow_rate;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &raw_data) == 0) {
            // Convert to flow rate
            flow_rate = convert_to_flow_rate(raw_data);

            // Set fan speed
            set_fan_speed(FAN_GPIO, flow_rate);

            // Log data
            log_data(log_file, flow_rate);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Shutdown sequence
    fprintf(stderr, "Shutting down...\n");
    gpioPWM(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle); // Close I2C connection
    fclose(log_file); // Close log file
    gpioTerminate(); // Terminate pigpio

    return 0;
}

