#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5D

// LPS33HW register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lps33hw();
int read_pressure(int32_t *pressure);
int read_temperature(int16_t *temperature);
void log_data(int32_t pressure, int16_t temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        terminate = 1;
        fprintf(stderr, "Received SIGINT. Exiting gracefully.\n");
    }
}

// Initialize the LPS33HW sensor
int init_lps33hw() {
    int who_am_i;

    // Read WHO_AM_I register
    who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        fprintf(log_file, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        fflush(log_file);
        return -1;
    }

    if (who_am_i != 0xB1) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0xB1, got 0x%X\n", who_am_i);
        fprintf(log_file, "WHO_AM_I check failed. Expected 0xB1, got 0x%X\n", who_am_i);
        fflush(log_file);
        return -1;
    }

    // Configure CTRL_REG1
    int result = i2cWriteByteData(i2c_handle, CTRL_REG1, 0xB0);
    if (result < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 register: %s\n", strerror(errno));
        fprintf(log_file, "Error writing to CTRL_REG1 register: %s\n", strerror(errno));
        fflush(log_file);
        return -1;
    }

    return 0;
}

// Read pressure data from the sensor
int read_pressure(int32_t *pressure) {
    char buffer[3];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3);
    if (result < 0) {
        fprintf(stderr, "Error reading pressure data: %s\n", strerror(errno));
        fprintf(log_file, "Error reading pressure data: %s\n", strerror(errno));
        fflush(log_file);
        return -1;
    }

    *pressure = (int32_t)((((uint32_t)buffer[2]) << 16) | (((uint32_t)buffer[1]) << 8) | (uint32_t)buffer[0]);
    *pressure = (*pressure << 8) >> 8; // Sign extend 24-bit to 32-bit

    return 0;
}

// Read temperature data from the sensor
int read_temperature(int16_t *temperature) {
    char buffer[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        fprintf(log_file, "Error reading temperature data: %s\n", strerror(errno));
        fflush(log_file);
        return -1;
    }

    *temperature = (int16_t)(((uint16_t)buffer[1] << 8) | (uint16_t)buffer[0]);
    *temperature = (*temperature << 8) >> 8; // Sign extend 16-bit to 32-bit

    return 0;
}

// Log data to file
void log_data(int32_t pressure, int16_t temperature) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];
    float pressure_hpa, temperature_celsius;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    pressure_hpa = (float)pressure / 4096.0;
    temperature_celsius = 42.5 + (float)temperature / 480.0;

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure_hpa, temperature_celsius);
    fflush(log_file);

    printf("%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure_hpa, temperature_celsius);
}

int main() {
    int32_t pressure;
    int16_t temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LPS33HW sensor
    if (init_lps33hw() != 0) {
        fprintf(stderr, "LPS33HW initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read pressure and temperature
        if (read_pressure(&pressure) == 0 && read_temperature(&temperature) == 0) {
            // Log data
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying.\n");
            fprintf(log_file, "Error reading sensor data. Retrying.\n");
            fflush(log_file);
        }

        // Delay for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

