#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temp_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
void signal_handler(int signal);
float read_temperature();
void update_buffer(float temperature);
float calculate_average();
void control_led(float average_temp);

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read temperature from STLM75
float read_temperature() {
    char buf[2];
    int result;
    int16_t raw_temp;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Swap bytes (little-endian to big-endian)
    raw_temp = (buf[1] << 8) | buf[0];

    // Extract temperature (9-bit resolution)
    raw_temp = raw_temp >> 7;

    // Convert to Celsius
    return (float)raw_temp / 2.0;
}

// Function to update the circular buffer
void update_buffer(float temperature) {
    temp_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the running average
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temp_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the LED
void control_led(float average_temp) {
    if (average_temp > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            update_buffer(temperature);
            float average_temp = calculate_average();
            control_led(average_temp);
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temp);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping update.\n");
        }

        sleep(1);
    }

    // Cleanup
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

