#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD30 I2C address
#define SCD30_I2C_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_PERIODIC_MEASUREMENT 0x0010
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_GET_DATA_READY 0x0202

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int write_scd30_command(uint16_t command, uint8_t *data, uint16_t data_len);
int read_scd30_data(uint8_t *data, uint16_t data_len);
int check_data_ready();
int read_sensor_data(sensor_data_t *data);
void log_sensor_data(sensor_data_t data);
void control_ventilation(float co2);
void signal_handler(int signal);
uint8_t crc8(const uint8_t *data, size_t len);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write command to SCD30 with CRC
int write_scd30_command(uint16_t command, uint8_t *data, uint16_t data_len) {
    uint8_t buffer[3];
    buffer[0] = (command >> 8) & 0xFF;
    buffer[1] = command & 0xFF;

    uint8_t crc = crc8(buffer, 2);
    buffer[2] = crc;

    int result = i2cWriteDevice(i2c_handle, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to write command 0x%04X: %d\n", command, result);
        return -1;
    }

    if (data_len > 0) {
        result = i2cWriteDevice(i2c_handle, (char *)data, data_len);
        if (result != data_len) {
            fprintf(stderr, "Failed to write data for command 0x%04X: %d\n", command, result);
            return -1;
        }
    }

    return 0;
}

// Read data from SCD30
int read_scd30_data(uint8_t *data, uint16_t data_len) {
    int result = i2cReadDevice(i2c_handle, (char *)data, data_len);
    if (result != data_len) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Check if data is ready
int check_data_ready() {
    uint8_t data[3];
    if (write_scd30_command(SCD30_CMD_GET_DATA_READY, NULL, 0) != 0) {
        return -1;
    }
    if (read_scd30_data(data, 3) != 0) {
        return -1;
    }

    uint16_t data_ready = (data[0] << 8) | data[1];
    return (data_ready & 0x0001) ? 1 : 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[18];
    uint8_t crc;

    if (write_scd30_command(SCD30_CMD_READ_MEASUREMENT, NULL, 0) != 0) {
        return -1;
    }

    if (read_scd30_data(buffer, 18) != 0) {
        return -1;
    }

    // CRC check for CO2
    crc = crc8(buffer, 4);
    if (crc != buffer[4]) {
        fprintf(stderr, "CRC check failed for CO2\n");
        return -1;
    }

    // CRC check for Temperature
    crc = crc8(buffer + 6, 4);
    if (crc != buffer[10]) {
        fprintf(stderr, "CRC check failed for Temperature\n");
        return -1;
    }

    // CRC check for Humidity
    crc = crc8(buffer + 12, 4);
    if (crc != buffer[16]) {
        fprintf(stderr, "CRC check failed for Humidity\n");
        return -1;
    }

    // Convert data
    uint32_t co2_raw = (buffer[0] << 24) | (buffer[1] << 16) | (buffer[2] << 8) | buffer[3];
    uint32_t temperature_raw = (buffer[6] << 24) | (buffer[7] << 16) | (buffer[8] << 8) | buffer[9];
    uint32_t humidity_raw = (buffer[12] << 24) | (buffer[13] << 16) | (buffer[14] << 8) | buffer[15];

    data->co2 = *((float*)&co2_raw);
    data->temperature = *((float*)&temperature_raw);
    data->humidity = *((float*)&humidity_raw);

    return 0;
}

// Log sensor data to file
void log_sensor_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file);
}

// Control ventilation system based on CO2 level
void control_ventilation(float co2) {
    if (co2 < 800) {
        printf("Ventilation: OFF\n");
    } else if (co2 < 1200) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    uint8_t interval[2] = {0x00, 0x02}; // 2 seconds
    if (write_scd30_command(SCD30_CMD_START_PERIODIC_MEASUREMENT, interval, 2) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Check if data is ready
        if (check_data_ready() == 1) {
            // Read sensor data
            if (read_sensor_data(&sensor_data) == 0) {
                // Log sensor data
                log_sensor_data(sensor_data);

                // Control ventilation
                control_ventilation(sensor_data.co2);
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        } else {
            //printf("Data not ready\n");
        }

        sleep(5);
    }

    // Stop periodic measurement
    uint8_t stop_command[2] = {0x00, 0x00};
    write_scd30_command(SCD30_CMD_START_PERIODIC_MEASUREMENT, stop_command, 2);

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

