#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP32_ADDR 0x21
#define SAMPLE_INTERVAL_MS 1000 // Default sample interval
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sdp32(float *pressure_pa);
uint8_t crc8(const uint8_t *data, int len);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int16_t pressure_raw;
    int16_t temperature_raw;
    uint16_t scale_factor_raw;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SDP32 sensor
int read_sdp32(float *pressure_pa) {
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t buffer[9];
    sensor_data_t sensor_data;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (i2cReadDevice(i2c_handle, (char *)buffer, 9) != 9) {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // CRC Check
        if (crc8(&buffer[0], 1) != buffer[2] ||
            crc8(&buffer[3], 1) != buffer[5] ||
            crc8(&buffer[6], 1) != buffer[8]) {
            fprintf(stderr, "CRC check failed (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Extract data
        sensor_data.pressure_raw = (int16_t)((buffer[0] << 8) | buffer[1]);
        sensor_data.temperature_raw = (int16_t)((buffer[3] << 8) | buffer[4]);
        sensor_data.scale_factor_raw = (uint16_t)((buffer[6] << 8) | buffer[7]);

        // Calculate pressure in Pascals
        *pressure_pa = (float)sensor_data.pressure_raw / (float)sensor_data.scale_factor_raw;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SDP32 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int sample_interval = SAMPLE_INTERVAL_MS;

    // Parse command-line arguments
    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Invalid sample interval. Using default: %d ms\n", SAMPLE_INTERVAL_MS);
            sample_interval = SAMPLE_INTERVAL_MS;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float pressure_pa;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    while (!terminate) {
        if (read_sdp32(&pressure_pa) == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the data
            printf("%s Pressure: %.2f Pa\n", timestamp, pressure_pa);
        } else {
            fprintf(stderr, "Failed to read pressure.\n");
        }

        gpioDelay(sample_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

