        return -1;
    }

    // Wait for conversion (at least 45 ms)
    gpioDelay(45000); // 45 ms

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2] ||
        crc8(buffer + 3, 2) != buffer[5] ||
        crc8(buffer + 6, 2) != buffer[8]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Extract raw values
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    uint16_t scale_factor_pressure = (buffer[6] << 8) | buffer[7];

    // Convert raw values to physical units
    *pressure = (float)raw_pressure / (float)scale_factor_pressure;
    *temperature = (float)raw_temperature / 200.0;

    return 0;
}

