    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float pressure, temperature;
    time_t last_log_time = 0;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            // Log data every 1 second
            time_t current_time = time(NULL);
            if (current_time - last_log_time >= 1) {
                printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
                last_log_time = current_time;
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 1 second
        gpioDelay(1000000); // 1 second
    }

    // Close I2C handle and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

