#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40

// Define register addresses
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HUMID_REG 0x01

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the HDC1000 sensor
int init_hdc1000(int fd) {
    uint8_t config_data[2];
    config_data[0] = CONFIG_REG;
    config_data[1] = 0x00; // Enable temperature and humidity measurement, 14-bit resolution

    if (write(fd, config_data, 2) != 2) {
        fprintf(stderr, "Error writing to configuration register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity data from the HDC1000 sensor
int read_hdc1000(int fd, float *temperature, float *humidity) {
    uint8_t read_data[4];
    uint8_t reg_addr = TEMP_REG;

    // Write the temperature register address to the sensor
    if (write(fd, &reg_addr, 1) != 1) {
        fprintf(stderr, "Error writing to temperature register: %s\n", strerror(errno));
        return -1;
    }

    // Wait for at least 20 ms for the conversion to complete
    usleep(20000); // 20 ms

    // Read 4 bytes of data (2 bytes temperature, 2 bytes humidity)
    if (read(fd, read_data, 4) != 4) {
        fprintf(stderr, "Error reading data from sensor: %s\n", strerror(errno));
        return -1;
    }

    // Convert the raw data to temperature and humidity
    int16_t raw_temperature = (read_data[0] << 8) | read_data[1];
    int16_t raw_humidity = (read_data[2] << 8) | read_data[3];

    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize the HDC1000 sensor
    if (init_hdc1000(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing HDC1000 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print temperature and humidity data
    while (1) {
        float temperature, humidity;

        if (read_hdc1000(i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading temperature and humidity data.\n");
        }

        sleep(5);
    }

    // Close the I2C bus (this will never be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

