#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define SLEEP_MS 5000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read temperature from Si7051
float read_temperature() {
    int raw_temperature;
    float temperature;

    // Send measurement command
    if (i2cWriteByte(i2c_handle, MEASURE_TEMP_CMD) != 0) {
        fprintf(stderr, "Error: Failed to send measurement command.\n");
        return -1000.0; // Indicate error
    }

    // Wait for measurement (typical conversion time is 11ms)
    gpioDelay(20); // Wait 20ms

    // Read temperature data (2 bytes)
    raw_temperature = i2cReadWordData(i2c_handle, 0); // Register address is not used with Si7051
    if (raw_temperature < 0) {
        fprintf(stderr, "Error: Failed to read temperature data. Error code: %d\n", raw_temperature);
        return -1000.0; // Indicate error
    }

    // Convert raw temperature to Celsius
    temperature = (175.72 * raw_temperature / 65536.0) - 46.85;

    return temperature;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Error: Failed to read temperature.\n");
        }

        gpioDelay(SLEEP_MS); // Sleep for 5 seconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

