#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MLX90819_ADDR 0x60
#define MEASURE_CMD 0x30 // Example command, check datasheet
#define PRESSURE_MSB_REG 0xAA
#define PRESSURE_LSB_REG 0xAB
#define SCALING_FACTOR 0.1
#define SLEEP_SECONDS 1

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read pressure from MLX90819 sensor
float read_pressure() {
    unsigned char buffer[2];
    int raw_pressure;
    float pressure_kPa;

    // Trigger measurement
    if (i2c_smbus_write_byte_data(i2c_fd, MEASURE_CMD, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement: %s\n", strerror(errno));
        return -1.0;
    }

    // Wait for measurement to complete (adjust as needed)
    usleep(10000); // 10ms

    // Read pressure MSB
    if (i2c_smbus_read_byte_data(i2c_fd, PRESSURE_MSB_REG) < 0) {
        fprintf(stderr, "Error: Failed to read pressure MSB: %s\n", strerror(errno));
        return -1.0;
    }

    // Read pressure LSB
    if (i2c_smbus_read_byte_data(i2c_fd, PRESSURE_LSB_REG) < 0) {
        fprintf(stderr, "Error: Failed to read pressure LSB: %s\n", strerror(errno));
        return -1.0;
    }

    // Combine MSB and LSB into raw pressure value
    raw_pressure = ((buffer[0] << 8) | buffer[1]);

    // Convert raw value to kPa
    pressure_kPa = (float)raw_pressure * SCALING_FACTOR;

    return pressure_kPa;
}

int main() {
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];
    float pressure;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address 0x%02X: %s\n", MLX90819_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read pressure
        pressure = read_pressure();

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Log pressure reading
        if (pressure >= 0) {
            printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
        } else {
            fprintf(stderr, "%s Error: Failed to read pressure\n", timestamp);
        }

        // Sleep for 1 second
        sleep(SLEEP_SECONDS);
    }

    // Close I2C bus (should not reach here due to signal handler)
    close(i2c_fd);

    return 0;
}

