    struct tm *time_info;
    char timestamp[20];
    float pressure;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address 0x%02X: %s\n", MLX90819_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read pressure
        pressure = read_pressure();

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Log pressure reading
        if (pressure >= 0) {
            printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
        } else {
            fprintf(stderr, "%s Error: Failed to read pressure\n", timestamp);
        }

        // Sleep for 1 second
        sleep(SLEEP_SECONDS);
    }

    // Close I2C bus (should not reach here due to signal handler)
    close(i2c_fd);

    return 0;
}

