#include <unistd.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASUREMENT_COMMAND_1 0x36
#define MEASUREMENT_COMMAND_2 0x2F
#define DATA_LENGTH 3
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define SCALE_FACTOR 60.0
#define LOG_FILE "airflow_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int16_t *raw_pressure);
uint8_t calculate_crc(uint8_t data[], int len);
float convert_to_pressure(int16_t raw_pressure);
int log_data(float pressure);
void signal_handler(int signal);
int check_sensor_presence();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to check if the sensor is present on the I2C bus
int check_sensor_presence() {
    int handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (handle >= 0) {
        i2cClose(handle);
        return 1; // Sensor present
    } else {
        return 0; // Sensor not present
    }
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the sensor
int read_sensor_data(int16_t *raw_pressure) {
    char write_data[2] = {MEASUREMENT_COMMAND_1, MEASUREMENT_COMMAND_2};
    char read_data[DATA_LENGTH];

    if (i2cWriteDevice(i2c_handle, write_data, 2) != 2) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(8000); // Wait 8 ms

    if (i2cReadDevice(i2c_handle, read_data, DATA_LENGTH) != DATA_LENGTH) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *raw_pressure = (int16_t)((read_data[0] << 8) | read_data[1]);

    return 0;
}

// Function to calculate the CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw pressure to Pascals
float convert_to_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / SCALE_FACTOR;
}

// Function to log the data to a CSV file
int log_data(float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Check if the file exists and is empty
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        // File doesn't exist, create it and write the header
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file for writing: %s\n", strerror(errno));
            return -1;
        }
        fprintf(log_file, "Timestamp,Pressure (Pa)\n");
    } else {
        // File exists, check if it's empty
        fseek(fp, 0, SEEK_END);
        long file_size = ftell(fp);
        fclose(fp);

        if (file_size == 0) {
            // File is empty, write the header
            log_file = fopen(LOG_FILE, "w");
            if (log_file == NULL) {
                fprintf(stderr, "Failed to open log file for writing: %s\n", strerror(errno));
                return -1;
            }
            fprintf(log_file, "Timestamp,Pressure (Pa)\n");
        } else {
            // File is not empty, append to it
            log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Failed to open log file for appending: %s\n", strerror(errno));
                return -1;
            }
        }
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fclose(log_file);

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check if the sensor is present
    if (!check_sensor_presence()) {
        fprintf(stderr, "SDP800 sensor not found on I2C bus %d at address 0x%02X\n", I2C_BUS, SDP800_ADDRESS);
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    int16_t raw_pressure;
    float pressure;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_pressure) == 0) {
            // Calculate CRC
            uint8_t data[2] = {(uint8_t)(raw_pressure >> 8), (uint8_t)(raw_pressure & 0xFF)};
            uint8_t crc = calculate_crc(data, 2);

            // Verify CRC
            if (crc == (uint8_t)read_sensor_data[2]) {
                // Convert to pressure
                pressure = convert_to_pressure(raw_pressure);

                // Log the data
                if (log_data(pressure) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

