    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

