#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define MEASUREMENT_COMMAND 0x00
#define DATA_LENGTH 4
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE 1048576 // 1 MB

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
int validate_sensor_data(const uint8_t *data);
sensor_data_t convert_raw_data(const uint8_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_sensor_data(uint8_t *data) {
    int result = i2cWriteByte(i2c_handle, MEASUREMENT_COMMAND);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(50000); // 50 ms delay

    result = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate sensor data
int validate_sensor_data(const uint8_t *data) {
    uint16_t status = (data[0] << 8) | data[1];
    if (status & 0x8000) {
        fprintf(stderr, "Sensor not present or busy\n");
        return -1;
    }
    if (status & 0x4000) {
        fprintf(stderr, "Bus error\n");
        return -1;
    }
    return 0;
}

// Convert raw data to temperature and humidity
sensor_data_t convert_raw_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    uint16_t raw_humidity = ((uint16_t)data[0] << 6) | (data[1] >> 2);
    uint16_t raw_temperature = ((uint16_t)(data[2] & 0x3F) << 8) | data[3];

    sensor_data.humidity = (float)raw_humidity * 100.0 / 16383.0;
    sensor_data.temperature = (float)raw_temperature * 165.0 / 16383.0 - 40.0;

    return sensor_data;
}

// Log data to file
int log_data(const sensor_data_t *data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity);
    fclose(fp);

    // Check log file size and truncate if necessary
    FILE *fp_check = fopen(LOG_FILE, "r");
    if (fp_check == NULL) {
        fprintf(stderr, "Error opening log file for size check\n");
        return -1;
    }

    fseek(fp_check, 0, SEEK_END);
    long file_size = ftell(fp_check);
    fclose(fp_check);

    if (file_size > MAX_LOG_SIZE) {
        FILE *fp_truncate = fopen(LOG_FILE, "w");
        if (fp_truncate == NULL) {
            fprintf(stderr, "Error opening log file for truncation\n");
            return -1;
        }
        fclose(fp_truncate);
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    uint8_t data[DATA_LENGTH];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate sensor data
            if (validate_sensor_data(data) == 0) {
                // Convert raw data
                sensor_data = convert_raw_data(data);

                // Log data
                if (log_data(&sensor_data) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            }
        }

        gpioDelay(5000000); // 5 second delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

