#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define SENT protocol parameters
#define SYNC_PULSE_TICKS 56
#define NIBBLE_TICKS 12
#define MAX_NIBBLE_TICKS 271
#define TIMEOUT_US 10000 // 10ms timeout

// Define pressure conversion parameters
#define SCALE 0.1
#define OFFSET 0.0

// Define error codes
#define NO_ERROR 0
#define TIMEOUT_ERROR 1
#define BUS_ERROR 2
#define SENSOR_ABSENT 3

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int gpio;
    int status;
    unsigned int raw_value;
    float pressure;
} sensor_data_t;

// Function prototypes
int read_sensor(int gpio);
int decode_sent_signal(int gpio, unsigned int *raw_value);
int validate_checksum(unsigned int raw_value);
float convert_to_pressure(unsigned int raw_value);
void log_pressure(int sensor_id, float pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from a single sensor
int read_sensor(int gpio) {
    unsigned int raw_value = 0;
    int status = NO_ERROR;

    // Read the SENT signal from the specified GPIO pin
    if (decode_sent_signal(gpio, &raw_value) != NO_ERROR) {
        return BUS_ERROR; // Indicate a bus error
    }

    // Validate the checksum
    if (validate_checksum(raw_value) != NO_ERROR) {
        return BUS_ERROR; // Indicate a bus error
    }

    // Convert the raw value to pressure
    float pressure = convert_to_pressure(raw_value);

    // Log the pressure reading
    log_pressure(gpio, pressure);

    return NO_ERROR;
}

// Function to decode the SENT signal
int decode_sent_signal(int gpio, unsigned int *raw_value) {
    int i, j;
    int tick_count;
    int pulse_width;
    unsigned int data = 0;

