#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define DEVICE_ID_REG 0x00
#define TEMP_REG 0x01
#define DEVICE_ID 0x117
#define SAMPLE_INTERVAL_SEC 60
#define FILENAME "greenhouse_temps.dat"

// Global variables
int i2c_handle = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int verify_device_id();
float read_temperature();
int write_temperature_to_file(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Verify device ID
int verify_device_id() {
    int device_id = i2cReadWordData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Failed to read device ID: %s\n", strerror(errno));
        return -1;
    }
    if (device_id != DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID: 0x%04X (expected 0x%04X)\n", device_id, DEVICE_ID);
        return -1;
    }
    printf("Device ID verified: 0x%04X\n", device_id);
    return 0;
}

// Read temperature
float read_temperature() {
    int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw temperature to Celsius
    float temperature = (float)raw_temp * 0.0078125;
    return temperature;
}

// Write temperature to file
int write_temperature_to_file(float temperature) {
    if (fp == NULL) {
        fprintf(stderr, "File not opened\n");
        return -1;
    }

    size_t bytes_written = fwrite(&temperature, sizeof(float), 1, fp);
    if (bytes_written != 1) {
        fprintf(stderr, "Failed to write temperature to file\n");
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        cleanup();
        return 1;
    }

    // Open file for writing
    fp = fopen(FILENAME, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Greenhouse monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            // Write temperature to file
            if (write_temperature_to_file(temperature) != 0) {
                fprintf(stderr, "Failed to write temperature to file\n");
            } else {
                printf("Temperature: %.4f °C\n", temperature);
            }
        } else {
            fprintf(stderr, "Failed to read temperature, skipping file write.\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

