    if (read_i2c(handle, SHT40_ADDR, buf, 6) < 0) {
        return -1;
    }

    // Extract raw temperature and humidity values
    raw_temp = (buf[0] << 8) | buf[1];
    raw_hum = (buf[3] << 8) | buf[4];

    // Validate CRC checksums
    uint8_t temp_data[3] = {buf[0], buf[1], buf[2]};
    uint8_t hum_data[3] = {buf[3], buf[4], buf[5]};

    if (!validate_crc(temp_data, 3)) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return -1;
    }

    if (!validate_crc(hum_data, 3)) {
        fprintf(stderr, "Humidity CRC validation failed\n");
        return -1;
    }

    // Convert raw values to temperature and humidity
    *temperature = -45 + 175 * ((float)raw_temp / 65535.0);
    *humidity = -6 + 125 * ((float)raw_hum / 65535.0);

    return 0;
}

