#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define MAG_REG 0x00 // Example register address for magnetic field
#define TEMP_REG 0x01 // Example register address for temperature
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float magnetic_field;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(int *raw_mag, int *raw_temp);
sensor_data_t convert_raw_data(int raw_mag, int raw_temp);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw sensor data from the Si7202
int read_sensor_data(int *raw_mag, int *raw_temp) {
    char buf[2];
    int result;

    // Read magnetic field data
    result = i2cReadI2CBlockData(i2c_handle, MAG_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading magnetic field data: %d\n", result);
        return -1;
    }
    *raw_mag = (buf[0] << 8) | buf[1];

    // Read temperature data
    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    *raw_temp = (buf[0] << 8) | buf[1];

    return 0;
}

// Convert raw data to magnetic field (Gauss) and temperature (Celsius)
sensor_data_t convert_raw_data(int raw_mag, int raw_temp) {
    sensor_data_t data;
    data.magnetic_field = (float)raw_mag * 0.1;
    data.temperature = (float)raw_temp * 0.01 - 25.0;
    return data;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.magnetic_field, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        int raw_mag, raw_temp;

        if (read_sensor_data(&raw_mag, &raw_temp) == 0) {
            sensor_data_t data = convert_raw_data(raw_mag, raw_temp);
            log_data(data);
        } else {
            fprintf(stderr, "Error reading sensor data. Logging NaN values.\n");
            sensor_data_t nan_data = {NAN, NAN};
            log_data(nan_data);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

