#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_RESOLUTION 0.0078125
#define LOG_FILE "temperature_log.txt"
#define MAX_REINIT_ATTEMPTS 3

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_temperature(int i2c_handle, float *temperature);
int log_temperature(FILE *log_file, float temperature);
void signal_handler(int signal);
int initialize_i2c();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from TMP117
int read_temperature(int i2c_handle, float *temperature) {
    char buf[2];
    int16_t raw_temp;
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1;
    }

    raw_temp = (buf[0] << 8) | buf[1];
    *temperature = raw_temp * TEMP_RESOLUTION;
    return 0;
}

// Function to log temperature to file
int log_temperature(FILE *log_file, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s, Temperature: %.4f C\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    float temperature;
    int reinit_attempts = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (log_temperature(log_file, temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature. Re-initializing I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1; // Reset handle
            reinit_attempts++;

            if (reinit_attempts > MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                terminate = 1; // Exit loop
            } else {
                if (initialize_i2c() != 0) {
                    fprintf(stderr, "I2C re-initialization failed.\n");
                } else {
                    reinit_attempts = 0; // Reset attempts on success
                }
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

