        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (log_temperature(log_file, temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature. Re-initializing I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1; // Reset handle
            reinit_attempts++;

            if (reinit_attempts > MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                terminate = 1; // Exit loop
            } else {
                if (initialize_i2c() != 0) {
                    fprintf(stderr, "I2C re-initialization failed.\n");
                } else {
                    reinit_attempts = 0; // Reset attempts on success
                }
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

