#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define FLOW_SCALE_FACTOR 25.0
#define TEMPERATURE_SCALE_FACTOR 80.0
#define FLOW_OFFSET 0.1
#define TEMPERATURE_OFFSET -40.0
#define FLOW_DIVISOR 0.8
#define TEMPERATURE_DIVISOR 0.8
#define FLOW_MAX 25.0
#define TEMPERATURE_MAX 80.0
#define FLOW_MIN -25.0
#define TEMPERATURE_MIN -40.0
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow;
    float temperature;
} SensorData;

// Function prototypes
int initialize_i2c();
SensorData read_sensor_data();
SensorData convert_raw_data(int raw_flow, int raw_temp);
void log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read raw sensor data
SensorData read_sensor_data() {
    char buffer[4];
    int result = i2cReadDevice(i2c_handle, buffer, 4);

    if (result != 4) {
        fprintf(stderr, "Error reading I2C data: %d\n", result);
        return (SensorData){.flow = -999.0, .temperature = -999.0}; // Indicate error
    }

    int raw_flow = (buffer[0] << 8) | buffer[1];
    int raw_temp = (buffer[2] << 8) | buffer[3];

    return convert_raw_data(raw_flow, raw_temp);
}

// Function to convert raw data to SLPM and Celsius
SensorData convert_raw_data(int raw_flow, int raw_temp) {
    float flow = ((raw_flow / 16384.0) - FLOW_OFFSET) / FLOW_DIVISOR * FLOW_SCALE_FACTOR;
    float temperature = ((raw_temp / 4096.0) - FLOW_OFFSET) / TEMPERATURE_DIVISOR * TEMPERATURE_SCALE_FACTOR + TEMPERATURE_OFFSET;

    // Data validation
    if (flow < FLOW_MIN || flow > FLOW_MAX) {
        fprintf(stderr, "Warning: Flow rate out of range: %.2f SLPM\n", flow);
    }
    if (temperature < TEMPERATURE_MIN || temperature > TEMPERATURE_MAX) {
        fprintf(stderr, "Warning: Temperature out of range: %.2f °C\n", temperature);
    }

    return (SensorData){.flow = flow, .temperature = temperature};
}

// Function to log data to file
void log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f SLPM, %.2f °C\n", timestamp, data.flow, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    int first_read = 1;
    while (!terminate) {
        SensorData data = read_sensor_data();

        if (data.flow != -999.0 && data.temperature != -999.0) {
            log_data(data);
        } else {
            fprintf(stderr, "Error reading sensor data. Re-initializing I2C.\n");
            fprintf(log_file, "Error reading sensor data. Re-initializing I2C.\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                cleanup();
                return 1;
            }
        }

        if (first_read) {
            first_read = 0;
        }

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL, 0); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

