#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define DHT11_GPIO 4
#define MAX_TIMINGS 85
#define SAMPLE_INTERVAL 2 // seconds

// Error codes
#define NO_ERROR 0
#define TIMEOUT_ERROR 1
#define CHECKSUM_ERROR 2
#define SENSOR_NOT_PRESENT 3

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold DHT11 data
typedef struct {
    int humidity;
    int temperature;
    int checksum;
} DHT11Data;

// Function prototypes
int initialize_gpio();
DHT11Data read_dht11_data();
int validate_checksum(int data[5]);
void log_data(DHT11Data data, int error_code);
void log_error(const char *message, int error_code);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    return 0;
}

// Read DHT11 data
DHT11Data read_dht11_data() {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;
    int timings[MAX_TIMINGS];
    int i, j;

    // 1. Send start signal
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(18000); // 18ms
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(20); //20us

    // 2. Switch to input and read response
    gpioSetMode(DHT11_GPIO, PI_INPUT);

    // Wait for the DHT11 to pull the line low (response signal)
    int timeout = 0;
    while (gpioRead(DHT11_GPIO) == 1) {
        gpioDelay(1); // Wait 1us
        timeout++;
        if (timeout > 100) { // 100us timeout
            log_error("DHT11 response timeout", TIMEOUT_ERROR);
            DHT11Data error_data = {0, 0, 0};
            error_data.checksum = TIMEOUT_ERROR;
            return error_data;
        }
    }

    timeout = 0;
    while (gpioRead(DHT11_GPIO) == 0) {
        gpioDelay(1); // Wait 1us
        timeout++;
        if (timeout > 100) { // 100us timeout
            log_error("DHT11 response timeout (low)", TIMEOUT_ERROR);
            DHT11Data error_data = {0, 0, 0};
            error_data.checksum = TIMEOUT_ERROR;
            return error_data;
        }
    }

    timeout = 0;
    while (gpioRead(DHT11_GPIO) == 1) {
        gpioDelay(1); // Wait 1us
        timeout++;
        if (timeout > 100) { // 100us timeout
            log_error("DHT11 response timeout (high)", TIMEOUT_ERROR);
            DHT11Data error_data = {0, 0, 0};
            error_data.checksum = TIMEOUT_ERROR;
            return error_data;
        }
    }

    // 3. Read 40 bits of data
    for (i = 0; i < MAX_TIMINGS; i++) {
        timeout = 0;
        while (gpioRead(DHT11_GPIO) == 0) {
            gpioDelay(1); // Wait 1us
            timeout++;
            if (timeout > 100) { // 100us timeout
                log_error("DHT11 data timeout (low)", TIMEOUT_ERROR);
                DHT11Data error_data = {0, 0, 0};
                error_data.checksum = TIMEOUT_ERROR;
                return error_data;
            }
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(DHT11_GPIO) == 1) {
            gpioDelay(1); // Wait 1us
            timeout++;
            if (timeout > 100) { // 100us timeout
                log_error("DHT11 data timeout (high)", TIMEOUT_ERROR);
                DHT11Data error_data = {0, 0, 0};
                error_data.checksum = TIMEOUT_ERROR;
                return error_data;
            }
        }
        long end = gpioTick();
        timings[i] = end - start;
    }

    // 4. Decode data
    for (i = 0; i < 40; i++) {
        int index = i / 8;
        int bit = i % 8;

        if (timings[2 * i + 2] > 40) { // Check if the pulse is longer than 40us
            data[index] |= (1 << (7 - bit));
        }
    }

    // 5. Validate checksum
    if (validate_checksum(data) != NO_ERROR) {
        log_error("DHT11 checksum error", CHECKSUM_ERROR);
        DHT11Data error_data = {0, 0, 0};
        error_data.checksum = CHECKSUM_ERROR;
        return error_data;
    }

    // 6. Create DHT11Data struct
    DHT11Data dht11_data;
    dht11_data.humidity = data[0];
    dht11_data.temperature = data[2];
    dht11_data.checksum = data[4];

    return dht11_data;
}

// Validate checksum
int validate_checksum(int data[5]) {
    if ((data[0] + data[1] + data[2] + data[3]) % 256 == data[4]) {
        return NO_ERROR;
    } else {
        return CHECKSUM_ERROR;
    }
}

// Log data to file
void log_data(DHT11Data data, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (error_code == NO_ERROR) {
        fprintf(log_file, "%s, Temperature: %d, Humidity: %d\n", timestamp, data.temperature, data.humidity);
    } else {
        fprintf(log_file, "%s, Error: %d, Temperature: %d, Humidity: %d\n", timestamp, error_code, data.temperature, data.humidity);
    }
    fflush(log_file);
}

// Log error to file
void log_error(const char *message, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, ERROR: %s (Code: %d)\n", timestamp, message, error_code);
    fflush(log_file);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        fclose(log_file);
        return 1;
    }

    printf("DHT11 sensor reading started. Press Ctrl+C to exit.\n");

    while (running) {
        DHT11Data data = read_dht11_data();
        log_data(data, data.checksum);
        gpioDelay(SAMPLE_INTERVAL * 1000000); // Sample every 2 seconds
    }

    cleanup();
    return 0;
}

