    fprintf(log_file, "%s, ERROR: %s (Code: %d)\n", timestamp, message, error_code);
    fflush(log_file);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        fclose(log_file);
        return 1;
    }

    printf("DHT11 sensor reading started. Press Ctrl+C to exit.\n");

    while (running) {
        DHT11Data data = read_dht11_data();
        log_data(data, data.checksum);
        gpioDelay(SAMPLE_INTERVAL * 1000000); // Sample every 2 seconds
    }

    cleanup();
    return 0;
}

