// Constants
#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2C06
#define RETRY_COUNT 3
#define SLEEP_DURATION 5 // seconds

// Global variables for signal handling
static volatile int running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int write_i2c(int handle, uint16_t command);
int read_i2c(int handle, uint8_t *data, int count);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
sensor_data_t read_sensor_data(int handle);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write to I2C device
int write_i2c(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Read from I2C device
int read_i2c(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

