                }
            } else {
                fprintf(stderr, "I2C read failed\n");
            }
        } else {
            fprintf(stderr, "I2C write failed\n");
        }
        retries--;
        gpioDelay(1000); // Wait 1 second before retrying
    }

    // Log error if all retries failed
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);
    fprintf(stderr, "%s,ERROR,Failed to read sensor data after multiple retries\n", buf);
    if (log_file != NULL) {
        fprintf(log_file, "%s,ERROR,Failed to read sensor data after multiple retries\n", buf);
        fflush(log_file);
    }

    return sensor_data; // Return default values
}

// Log data to file
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", buf, temperature, humidity);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not opened\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SHT31_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sht31d_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        sensor_data_t sensor_data = read_sensor_data(i2c_handle);
        log_data(sensor_data.temperature, sensor_data.humidity);
        sleep(SLEEP_DURATION);
    }

