#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65

// Define register addresses
#define DEVICE_ID_REG 0x00
#define RED_REG 0x64
#define GREEN_REG 0x66
#define BLUE_REG 0x68

// Define I2C bus
#define I2C_BUS 1

// Define log file name
#define LOG_FILE "cct_log.csv"

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C handles if they are open
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file if it is open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read a 16-bit value from an I2C register
int read_i2c_register(int i2c_handle, uint8_t reg_addr) {
    int data = i2cReadWordData(i2c_handle, reg_addr);
    if (data < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg_addr, data);
        return -1;
    }
    return data;
}

// Function to read red, green, and blue channel data from a sensor
int read_sensor_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int red_val = read_i2c_register(i2c_handle, RED_REG);
    int green_val = read_i2c_register(i2c_handle, GREEN_REG);
    int blue_val = read_i2c_register(i2c_handle, BLUE_REG);

    if (red_val < 0 || green_val < 0 || blue_val < 0) {
        return -1; // Indicate error
    }

    *red = (uint16_t)red_val;
    *green = (uint16_t)green_val;
    *blue = (uint16_t)blue_val;

    return 0; // Indicate success
}

// Function to calculate CCT using McCamy's formula
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float X = red;
    float Y = green;
    float Z = blue;

    float xc = X / (X + Y + Z);
    float yc = Y / (X + Y + Z);

    float n = (xc - 0.3320) / (0.1858 - yc);

    float cct = 449.0 * n * n * n + 3525.0 * n * n + 6823.3 * n + 5520.33;

    return cct;
}

// Function to log data to a CSV file
int log_data(float cct1, float cct2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Check if the file exists and is empty to write the header
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        // File doesn't exist, create it and write the header
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file for writing: %s\n", strerror(errno));
            return -1;
        }
        fprintf(log_file, "Timestamp,Average_CCT\n");
    } else {
        // File exists, check if it's empty
        fseek(fp, 0, SEEK_END);
        long file_size = ftell(fp);
        fclose(fp);

        if (file_size == 0) {
            // File is empty, write the header
            log_file = fopen(LOG_FILE, "w");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file for writing: %s\n", strerror(errno));
                return -1;
            }
            fprintf(log_file, "Timestamp,Average_CCT\n");
        } else {
            // File is not empty, append to it
            log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file for appending: %s\n", strerror(errno));
                return -1;
            }
        }
    }

    float average_cct = (cct1 + cct2) / 2.0;
    fprintf(log_file, "%s,%.2f\n", timestamp, average_cct);

    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Verify device ID for both sensors
    int device_id1 = i2cReadByteData(i2c_handle1, DEVICE_ID_REG);
    if (device_id1 != 0x2A) {
        fprintf(stderr, "Error: Sensor 1 device ID is 0x%02X, expected 0x2A\n", device_id1);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    int device_id2 = i2cReadByteData(i2c_handle2, DEVICE_ID_REG);
    if (device_id2 != 0x2A) {
        fprintf(stderr, "Error: Sensor 2 device ID is 0x%02X, expected 0x2A\n", device_id2);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        uint16_t red1, green1, blue1;
        uint16_t red2, green2, blue2;
        float cct1 = 0.0, cct2 = 0.0;

        // Read data from sensor 1
        if (read_sensor_data(i2c_handle1, &red1, &green1, &blue1) == 0) {
            cct1 = calculate_cct(red1, green1, blue1);
        } else {
            fprintf(stderr, "Error reading data from sensor 1\n");
        }

        // Read data from sensor 2
        if (read_sensor_data(i2c_handle2, &red2, &green2, &blue2) == 0) {
            cct2 = calculate_cct(red2, green2, blue2);
        } else {
            fprintf(stderr, "Error reading data from sensor 2\n");
        }

        // Log the data
        if (cct1 > 0 && cct2 > 0) {
            log_data(cct1, cct2);
        } else {
            fprintf(stderr, "Skipping log entry due to sensor read error\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function takes milliseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness in case the loop is ever modified.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

