    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Check if the file exists and is empty to write the header
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        // File doesn't exist, create it and write the header
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file for writing: %s\n", strerror(errno));
            return -1;
        }
        fprintf(log_file, "Timestamp,Average_CCT\n");
    } else {
        // File exists, check if it's empty
        fseek(fp, 0, SEEK_END);
        long file_size = ftell(fp);
        fclose(fp);

        if (file_size == 0) {
            // File is empty, write the header
            log_file = fopen(LOG_FILE, "w");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file for writing: %s\n", strerror(errno));
                return -1;
            }
            fprintf(log_file, "Timestamp,Average_CCT\n");
        } else {
            // File is not empty, append to it
            log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file for appending: %s\n", strerror(errno));
                return -1;
            }
        }
    }

    float average_cct = (cct1 + cct2) / 2.0;
    fprintf(log_file, "%s,%.2f\n", timestamp, average_cct);

    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Verify device ID for both sensors
    int device_id1 = i2cReadByteData(i2c_handle1, DEVICE_ID_REG);
    if (device_id1 != 0x2A) {
        fprintf(stderr, "Error: Sensor 1 device ID is 0x%02X, expected 0x2A\n", device_id1);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    int device_id2 = i2cReadByteData(i2c_handle2, DEVICE_ID_REG);
    if (device_id2 != 0x2A) {
        fprintf(stderr, "Error: Sensor 2 device ID is 0x%02X, expected 0x2A\n", device_id2);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        uint16_t red1, green1, blue1;
        uint16_t red2, green2, blue2;
        float cct1 = 0.0, cct2 = 0.0;

        // Read data from sensor 1
        if (read_sensor_data(i2c_handle1, &red1, &green1, &blue1) == 0) {
            cct1 = calculate_cct(red1, green1, blue1);
        } else {
            fprintf(stderr, "Error reading data from sensor 1\n");
        }

        // Read data from sensor 2
        if (read_sensor_data(i2c_handle2, &red2, &green2, &blue2) == 0) {
            cct2 = calculate_cct(red2, green2, blue2);
        } else {
            fprintf(stderr, "Error reading data from sensor 2\n");
        }

        // Log the data
        if (cct1 > 0 && cct2 > 0) {
            log_data(cct1, cct2);
        } else {
            fprintf(stderr, "Skipping log entry due to sensor read error\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function takes milliseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness in case the loop is ever modified.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

