        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_pressure = read_raw_pressure(i2c_handle);
        int raw_temperature = read_raw_temperature(i2c_handle);

        if (raw_pressure != -1 && raw_temperature != -1) {
            float pressure_kPa = convert_pressure(raw_pressure);
            float temperature_C = convert_temperature(raw_temperature);
            log_data(log_file, pressure_kPa, temperature_C);
        } else {
            // Log error to file
