            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);
            fprintf(log_file, "%s, Error reading sensor data\n", timestamp);
            fflush(log_file);
        }

        sleep(2);
    }

    // Clean up resources
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

