#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define SCALE_FACTOR_PRESSURE 60.0f
#define SCALE_FACTOR_TEMPERATURE 200.0f
#define PRESSURE_THRESHOLD 5.0f
#define LOG_FILE "airflow.log"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
SensorData process_data(const uint8_t *data);
void log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    uint8_t cmd[2] = {(command >> 8) & 0xFF, command & 0xFF};
    int result = i2cWriteDevice(handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(const uint8_t *data, int len) {
    for (int i = 0; i < len; i += 2) {
        uint8_t crc = crc8(data + i, 1);
        if (crc != data[i + 1]) {
            fprintf(stderr, "CRC mismatch at index %d: calculated 0x%02X, received 0x%02X\n", i, crc, data[i + 1]);
            return -1;
        }
    }
    return 0;
}

