#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define I2C_RETRIES 3

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
float convert_to_celsius(int16_t raw_temp);
void set_led_state(struct gpiod_line *line, int state);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// I2C read function
int i2c_read_word(int fd, uint8_t reg) {
    int retries = I2C_RETRIES;
    int result;

    while (retries > 0) {
        if (i2c_smbus_write_byte(fd, reg) < 0) {
            fprintf(stderr, "I2C write error: %s\n", strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        result = i2c_smbus_read_word_data(fd, reg);
        if (result < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        return result;
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", I2C_RETRIES);
    return -1; // Indicate failure
}

// Temperature conversion function
float convert_to_celsius(int16_t raw_temp) {
    return (float)raw_temp * 0.0625;
}

// LED control function
void set_led_state(struct gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        fprintf(stderr, "GPIO set value error: %s\n", strerror(errno));
    }
}

int main() {
    int16_t raw_temp;
    float temperature;
    int led_state = 0; // 0 = off, 1 = on

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "temperature_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature
        raw_temp = i2c_read_word(i2c_fd, TEMP_REG);
        if (raw_temp < 0) {
            fprintf(stderr, "Failed to read temperature, exiting.\n");
            break;
        }

        // Convert to Celsius
        temperature = convert_to_celsius(raw_temp);

        // Log temperature
        printf("Temperature: %.2f °C\n", temperature);

        // Control LED with hysteresis
        if (temperature > TEMP_THRESHOLD_HIGH && !led_state) {
            set_led_state(gpio_line, 1);
            led_state = 1;
        } else if (temperature < TEMP_THRESHOLD_LOW && led_state) {
            set_led_state(gpio_line, 0);
            led_state = 0;
        }

        sleep(1);
    }

    // Cleanup
    set_led_state(gpio_line, 0); // Turn off LED
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

