#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x362F
#define SCALE_FACTOR_OFFSET 6
#define SCALE_FACTOR_SIZE 2
#define DATA_LENGTH 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define TEMPERATURE_DIVISOR 200.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
void close_i2c();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len);
int16_t extract_scale_factor(uint8_t *data);
sensor_data_t convert_raw_data(uint8_t *data, int16_t scale_factor);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Close I2C communication
void close_i2c() {
    i2cClose(i2c_handle);
}

// Send measurement command to the sensor
int send_measurement_command() {
    uint8_t command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the I2C device
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = calculate_crc(data, len - 1);
    return (crc == data[len - 1]);
}

// Extract scale factor from the data
int16_t extract_scale_factor(uint8_t *data) {
    return (int16_t)((data[SCALE_FACTOR_OFFSET] << 8) | data[SCALE_FACTOR_OFFSET + 1]);
}

// Convert raw data to differential pressure and temperature
sensor_data_t convert_raw_data(uint8_t *data, int16_t scale_factor) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temperature = (int16_t)((data[3] << 8) | data[4]);

    sensor_data.differential_pressure = (float)raw_pressure / scale_factor;
    sensor_data.temperature = (float)raw_temperature / TEMPERATURE_DIVISOR;

    return sensor_data;
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f Pa, %.2f C\n", timestamp, data.differential_pressure, data.temperature);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        close_i2c();
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
