    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retry
int read_sensor_data(uint16_t *temperature, uint16_t *humidity) {
    int retries = RETRY_COUNT;
    int status;

    // Measure Humidity
    while (retries > 0) {
        status = i2cWriteDevice(i2c_handle, &MEASURE_HUMIDITY_CMD, 1);
        if (status == 0) {
            gpioDelay(20); // Wait for measurement
            char buf[2];
            status = i2cReadDevice(i2c_handle, buf, 2);
            if (status == 2) {
                *humidity = (buf[0] << 8) | buf[1];
                break; // Success
            } else {
                fprintf(stderr, "I2C read humidity failed: %d\n", status);
            }
        } else {
            fprintf(stderr, "I2C write humidity failed: %d\n", status);
        }
        retries--;
        gpioDelay(10); // Small delay before retry
    }
    if (retries == 0) {
        log_error("Failed to read humidity after multiple retries.");
        return -1;
    }

    // Measure Temperature
    retries = RETRY_COUNT;
    while (retries > 0) {
        status = i2cWriteDevice(i2c_handle, &MEASURE_TEMPERATURE_CMD, 1);
        if (status == 0) {
            gpioDelay(20); // Wait for measurement
            char buf[2];
            status = i2cReadDevice(i2c_handle, buf, 2);
            if (status == 2) {
                *temperature = (buf[0] << 8) | buf[1];
                break; // Success
            } else {
                fprintf(stderr, "I2C read temperature failed: %d\n", status);
            }
        } else {
            fprintf(stderr, "I2C write temperature failed: %d\n", status);
        }
        retries--;
        gpioDelay(10); // Small delay before retry
    }
    if (retries == 0) {
        log_error("Failed to read temperature after multiple retries.");
        return -1;
    }

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return 175.72 * raw_temp / 65536.0 - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    float humidity = 125.0 * raw_humidity / 65536.0 - 6.0;
    if (humidity < 0.0) return 0.0;
    if (humidity > 100.0) return 100.0;
    return humidity;
}

// Validate sensor presence
int validate_sensor() {
    int retries = RETRY_COUNT;
    int status;
    char buf[1];

    while (retries > 0) {
        status = i2cWriteDevice(i2c_handle, buf, 0); // Send no-op command
        if (status == 0) {
            status = i2cReadDevice(i2c_handle, buf, 1);
            if (status == 1) {
                // Basic check: if we can read a byte, assume the sensor is present
                return 0; // Success
            } else {
                fprintf(stderr, "Sensor ID read failed: %d\n", status);
            }
        } else {
            fprintf(stderr, "Sensor ID write failed: %d\n", status);
        }
        retries--;
        gpioDelay(10);
    }
    log_error("Failed to validate sensor after multiple retries.");
    return -1;
}

