// HDC1080 I2C address
#define HDC1080_ADDR 0x40

// HDC1080 register addresses
#define HDC1080_TEMP_REG 0x00
#define HDC1080_HUMID_REG 0x02
#define HDC1080_CONFIG_REG 0x0F

// Global variables for I2C handle and program termination
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the pigpio library and I2C bus
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0); // I2C bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Configure HDC1080 for 14-bit temperature and humidity resolution
    char config_data[2] = {0x00, 0x00}; // Default configuration
    if (i2cWriteDevice(i2c_handle, config_data, 2) != 0) {
        fprintf(stderr, "Failed to write to configuration register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

