#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define STS40_ADDR 0x44
#define MEASURE_CMD_HIGH 0x2C
#define MEASURE_CMD_LOW 0xE0
#define CRC_POLYNOMIAL 0x31

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float temperature;
    int raw_ticks;
    int crc_error;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *device);
int i2c_set_slave(int fd, int addr);
int i2c_write_bytes(int fd, const unsigned char *buf, int len);
int i2c_read_bytes(int fd, unsigned char *buf, int len);
int crc8(const unsigned char *data, int len);
float convert_ticks_to_celsius(int raw_ticks);
int log_temperature(float temperature);
void signal_handler(int signal);

// Function to open the I2C device
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to set the I2C slave address
int i2c_set_slave(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write bytes to the I2C device
int i2c_write_bytes(int fd, const unsigned char *buf, int len) {
    ssize_t bytes_written = write(fd, buf, len);
    if (bytes_written != len) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read bytes from the I2C device
int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    ssize_t bytes_read = read(fd, buf, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to calculate the CRC8 checksum
int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw ticks to Celsius
float convert_ticks_to_celsius(int raw_ticks) {
    return -45.0 + 175.0 * (float)raw_ticks / 65535.0;
}

// Function to log the temperature to a file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen("temperature_log.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = i2c_open(I2C_DEVICE);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Set the I2C slave address
    if (i2c_set_slave(i2c_fd, STS40_ADDR) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        unsigned char write_buf[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
        unsigned char read_buf[3];
        sensor_data_t sensor_data;

        // Send measurement command
        if (i2c_write_bytes(i2c_fd, write_buf, 2) < 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for conversion (10 ms)
        usleep(10000); // 10 ms

        // Read temperature data
        if (i2c_read_bytes(i2c_fd, read_buf, 3) < 0) {
            fprintf(stderr, "Error reading temperature data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // CRC validation
        int crc_calculated = crc8(read_buf, 2);
        if (crc_calculated != read_buf[2]) {
            fprintf(stderr, "CRC mismatch! Calculated: 0x%02X, Received: 0x%02X\n", crc_calculated, read_buf[2]);
            sensor_data.crc_error = 1; // Indicate CRC error
        } else {
            sensor_data.crc_error = 0; // No CRC error
        }

        // Convert raw ticks to Celsius
        int raw_ticks = (read_buf[0] << 8) | read_buf[1];
        sensor_data.raw_ticks = raw_ticks;
        sensor_data.temperature = convert_ticks_to_celsius(raw_ticks);

        // Log the temperature
        if (log_temperature(sensor_data.temperature) < 0) {
            fprintf(stderr, "Error logging temperature, retrying...\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Clean up
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

