#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x3615
#define SAMPLE_INTERVAL_MS 1000
#define LOG_FILE_NAME "hvac_pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_Pa;
    float temperature_C;
} SensorData;

// Function prototypes
int initialize();
void cleanup();
void signal_handler(int signal);
int read_sensor_data(SensorData *data);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
float convert_pressure(int16_t raw_pressure, int16_t scale_factor);
float convert_temperature(int16_t raw_temperature);
int log_data(const SensorData *data);
int log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

// Read sensor data
int read_sensor_data(SensorData *data) {
    uint8_t buffer[9];
    int result;

    // Send measurement command
    char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        log_error("I2C write failed");
        return 1;
    }

    // Wait for measurement (at least 50ms)
    gpioDelay(50);

    // Read 9 bytes from the sensor
    result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        log_error("I2C read failed");
        return 1;
    }

    // Validate CRCs
    if (validate_crc(buffer, 3) != 0 || validate_crc(buffer + 3, 3) != 0) {
        log_error("CRC validation failed");
        return 1;
    }

    // Extract raw values
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    int16_t scale_factor = (buffer[6] << 8) | buffer[7];

    // Convert to physical units
    data->pressure_Pa = convert_pressure(raw_pressure, scale_factor);
    data->temperature_C = convert_temperature(raw_temperature);

    return 0;
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(const uint8_t *data, int len) {
    uint8_t calculated_crc = crc8(data, len - 1);
    return (calculated_crc != data[len - 1]);
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure, int16_t scale_factor) {
    return (float)raw_pressure / (float)scale_factor;
}

// Convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / 200.0;
}

// Log data to file
int log_data(const SensorData *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->pressure_Pa, data->temperature_C);
    fflush(log_file);
    return 0;
}

// Log error to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,ERROR,%s\n", timestamp, message);
    fflush(log_file);
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
        } else {
            log_error("Failed to read sensor data");
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    cleanup();

    return 0;
}

