    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_CAPACITY;
    buffer->count++;
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Get data from circular buffer
int buffer_get(circular_buffer_t *buffer, int index, sensor_data_t *data) {
    pthread_mutex_lock(&buffer->mutex);
    if (index < 0 || index >= buffer->count) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Invalid index
    }

    int actual_index = (buffer->tail + index) % BUFFER_CAPACITY;
    *data = buffer->data[actual_index];
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Check if buffer is empty
int buffer_is_empty(circular_buffer_t *buffer) {
    pthread_mutex_lock(&buffer->mutex);
    int is_empty = (buffer->count == 0);
    pthread_mutex_unlock(&buffer->mutex);
    return is_empty;
}

// Check if buffer is full
int buffer_is_full(circular_buffer_t *buffer) {
    pthread_mutex_lock(&buffer->mutex);
    int is_full = (buffer->count == BUFFER_CAPACITY);
    pthread_mutex_unlock(&buffer->mutex);
    return is_full;
}

// Logging thread function
void *logging_thread_func(void *arg) {
    while (running) {
        gpioDelay(LOGGING_INTERVAL * 1000); // Sleep for LOGGING_INTERVAL seconds

        if (!buffer_is_empty(&buffer)) {
            // Create the data directory if it doesn't exist
            struct stat st = {0};
            if (stat(DATA_DIR, &st) == -1) {
                if (mkdir(DATA_DIR, 0777) == -1) {
                    log_error("Failed to create data directory");
                    continue; // Skip logging if directory creation fails
                }
            }

            // Create a timestamped filename
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char filename[256];
            strftime(filename, sizeof(filename), DATA_DIR "scd40_data_%Y%m%d_%H%M%S.csv", tstruct);

            // Write data to CSV file
            FILE *fp = fopen(filename, "w");
            if (fp == NULL) {
                log_error("Failed to open CSV file for writing");
                continue;
            }

            fprintf(fp, "timestamp,co2,temperature,humidity\n");
            for (int i = 0; i < buffer.count; i++) {
                sensor_data_t data;
                if (buffer_get(&buffer, i, &data) == 0) {
                    fprintf(fp, "%ld,%.2f,%.2f,%.2f\n", data.timestamp, data.co2, data.temperature, data.humidity);
                }
            }

            fclose(fp);
        }
    }
    return NULL;
}

// Log error messages to file
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    fprintf(fp, "%s: %s (errno: %d)\n", timestamp, message, errno);
    fclose(fp);
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    buffer_init(&buffer);

    // Create logging thread
    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        stop_periodic_measurement();
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        uint16_t co2, temperature, humidity;

        if (read_measurement(&co2, &temperature, &humidity) == 0) {
            // Convert raw values to ppm, degrees Celsius, and percentage
            float co2_ppm = (float)co2;
            float temp_celsius = -45 + 175 * (float)temperature / 65535;
            float humidity_percent = 100 * (float)humidity / 65535;

            // Get current timestamp
            time_t now = time(NULL);

            // Create sensor data
            sensor_data_t data;
            data.timestamp = now;
            data.co2 = co2_ppm;
            data.temperature = temp_celsius;
            data.humidity = humidity_percent;

            // Add data to circular buffer
            if (buffer_add(&buffer, data) != 0) {
                log_error("Failed to add data to buffer (buffer full)");
            }
        } else {
            log_error("Failed to read sensor data");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        log_error("Failed to stop periodic measurement during shutdown");
    }

    // Join logging thread
    pthread_join(logging_thread, NULL);

    // Flush remaining data to CSV file
    if (!buffer_is_empty(&buffer)) {
        // Create the data directory if it doesn't exist
        struct stat st = {0};
        if (stat(DATA_DIR, &st) == -1) {
            if (mkdir(DATA_DIR, 0777) == -1) {
                log_error("Failed to create data directory");
            }
        }

        // Create a timestamped filename
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char filename[256];
        strftime(filename, sizeof(filename), DATA_DIR "scd40_data_final.csv", tstruct);

        // Write data to CSV file
        FILE *fp = fopen(filename, "w");
        if (fp == NULL) {
            log_error("Failed to open CSV file for writing");
        } else {
            fprintf(fp, "timestamp,co2,temperature,humidity\n");
            for (int i = 0; i < buffer.count; i++) {
                sensor_data_t data;
                if (buffer_get(&buffer, i, &data) == 0) {
                    fprintf(fp, "%ld,%.2f,%.2f,%.2f\n", data.timestamp, data.co2, data.temperature, data.humidity);
                }
            }
            fclose(fp);
        }
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

