                if (buffer_get(&buffer, i, &data) == 0) {
                    fprintf(fp, "%ld,%.2f,%.2f,%.2f\n", data.timestamp, data.co2, data.temperature, data.humidity);
                }
            }

            fclose(fp);
        }
    }
    return NULL;
}

// Log error messages to file
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    fprintf(fp, "%s: %s (errno: %d)\n", timestamp, message, errno);
    fclose(fp);
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

