    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t raw_temperature = (buf[3] << 8) | buf[4];
    uint16_t scale_factor = (buf[6] << 8) | buf[7];

    data->pressure_Pa = convert_pressure(raw_pressure, scale_factor);
    data->temperature_C = convert_temperature(raw_temperature);

    return 0;
}

