#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ICP_10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VALUE 0x08
#define CALIB_START_REG 0x05
#define CALIB_END_REG 0x08
#define MEASURE_REG 0x00
#define DATA_START_REG 0x00
#define DATA_LENGTH 6
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
int32_t c0, c1, c2, c3;

// Function prototypes
int initialize();
int verify_sensor();
int read_calibration_data();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
double convert_pressure(uint32_t raw_pressure);
double convert_temperature(uint32_t raw_temperature);
int log_data(double pressure, double temperature);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    double pressure;
    double temperature;
} sensor_data_t;

int main() {
    sensor_data_t data;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio and I2C
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Verify sensor identity
    if (verify_sensor() != 0) {
        fprintf(stderr, "Sensor verification failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t raw_data[DATA_LENGTH];
        uint32_t raw_pressure, raw_temperature;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement. Skipping.\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Wait for measurement to complete (10ms)
        gpioDelay(10000); // 10ms

        // Read sensor data
        if (read_sensor_data(raw_data) != 0) {
            fprintf(stderr, "Failed to read sensor data. Skipping.\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Convert raw data to pressure and temperature
        raw_pressure = (raw_data[0] << 16) | (raw_data[1] << 8) | raw_data[2];
        raw_temperature = (raw_data[3] << 16) | (raw_data[4] << 8) | raw_data[5];

        data.pressure = convert_pressure(raw_pressure);
        data.temperature = convert_temperature(raw_temperature);

        // Log data
        if (log_data(data.pressure, data.temperature) != 0) {
            fprintf(stderr, "Failed to log data. Skipping.\n");
        }

        // Print data to stdout
        printf("Pressure: %.2f hPa, Temperature: %.2f °C\n", data.pressure, data.temperature);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP_10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Verify sensor identity
int verify_sensor() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return 1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        return 1;
    }

    return 0;
}

// Read calibration data
int read_calibration_data() {
    char data[CALIB_END_REG - CALIB_START_REG + 1];
    int result = i2cReadI2CBlockData(i2c_handle, CALIB_START_REG, data, CALIB_END_REG - CALIB_START_REG + 1);
    if (result < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        return 1;
    }

    c0 = (int32_t)data[0] << 24 | (int32_t)data[1] << 16 | (int32_t)data[2] << 8 | (int32_t)data[3];
    c1 = (int32_t)data[4] << 24 | (int32_t)data[5] << 16 | (int32_t)data[6] << 8 | (int32_t)data[7];
    c2 = (int32_t)data[8] << 24 | (int32_t)data[9] << 16 | (int32_t)data[10] << 8 | (int32_t)data[11];
    c3 = (int32_t)data[12] << 24 | (int32_t)data[13] << 16 | (int32_t)data[14] << 8 | (int32_t)data[15];

    return 0;
}

// Trigger measurement
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, MEASURE_REG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadI2CBlockData(i2c_handle, DATA_START_REG, (char *)data, DATA_LENGTH);
    if (result < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return 1;
    }
    return 0;
}

// Convert raw pressure to hPa
double convert_pressure(uint32_t raw_pressure) {
    // Implement the conversion formula from the ICP-10110 datasheet
    // This is a placeholder, replace with the actual formula
    return (double)raw_pressure / 4096.0; // Example conversion
}

// Convert raw temperature to Celsius
double convert_temperature(uint32_t raw_temperature) {
    // Implement the conversion formula from the ICP-10110 datasheet
    // This is a placeholder, replace with the actual formula
    return (double)raw_temperature / 4096.0; // Example conversion
}

// Log data to file
int log_data(double pressure, double temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, pressure, temperature);
    fflush(log_file);

