    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return 1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        return 1;
    }

    return 0;
}

// Read calibration data
