#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x63
#define OTP_START_ADDR 0x66
#define MEASURE_CMD 0x4011
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define NORMAL_BLINK_RATE 1.0  // Hz
#define WARNING_BLINK_RATE 5.0 // Hz
#define PRESSURE_THRESHOLD 95000.0 // Pa

// Global variables
static int i2c_fd = -1;
static struct gpiod_line *gpio_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration coefficients
static uint16_t c0, c1, c2, c3;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int read_calibration_coefficients(int fd);
int trigger_measurement(int fd);
int read_sensor_data(int fd, uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int len);
int verify_crc(uint8_t data[], int len);
double calculate_pressure(uint32_t raw_pressure, uint32_t raw_temperature);
double calculate_temperature(uint32_t raw_temperature);
void set_led_state(struct gpiod_line *line, int state);
void blink_led(struct gpiod_line *line, double frequency);
void signal_handler(int sig);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (write(fd, buf, len + 1) != len + 1) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Read calibration coefficients from OTP memory
int read_calibration_coefficients(int fd) {
    uint8_t data[8];
    if (i2c_read_bytes(fd, OTP_START_ADDR, data, 8) != 0) {
        fprintf(stderr, "Error reading calibration coefficients\n");
        return -1;
    }

    c0 = (data[1] << 8) | data[0];
    c1 = (data[3] << 8) | data[2];
    c2 = (data[5] << 8) | data[4];
    c3 = (data[7] << 8) | data[6];

    return 0;
}

// Trigger a measurement
int trigger_measurement(int fd) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    if (i2c_write_bytes(fd, 0x00, cmd, 2) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int fd, uint8_t *data) {
    if (i2c_read_bytes(fd, 0x00, data, 6) != 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }
    return 0;
}

// Calculate CRC
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Verify CRC
int verify_crc(uint8_t data[], int len) {
    uint8_t crc = calculate_crc(data, len - 1);
    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }
    return 0;
}

// Calculate pressure in Pascals
double calculate_pressure(uint32_t raw_pressure, uint32_t raw_temperature) {
    double p = (double)raw_pressure;
    double t = (double)raw_temperature;

    double p_comp = c0 + c1 * t + c2 * p + c3 * p * p;

    return p_comp;
}

// Calculate temperature in Celsius
double calculate_temperature(uint32_t raw_temperature) {
    return (double)raw_temperature / 100.0;
}

// Set LED state
void set_led_state(struct gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        perror("Failed to set LED state");
    }
}

// Blink LED
void blink_led(struct gpiod_line *line, double frequency) {
    struct timespec on_time, off_time;
    on_time.tv_sec = 0;
    on_time.tv_nsec = (long)(0.5 / frequency * 1000000000); // 0.5 seconds
    off_time.tv_sec = 0;
    off_time.tv_nsec = (long)(0.5 / frequency * 1000000000); // 0.5 seconds

    while (!terminate) {
        set_led_state(line, 1);
        nanosleep(&on_time, NULL);
        set_led_state(line, 0);
        nanosleep(&off_time, NULL);
    }
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients(i2c_fd) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients, exiting\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "barometer_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        uint32_t raw_pressure, raw_temperature;
        double pressure, temperature;

        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying...\n");
            sleep(1);
            continue;
        }

        // Wait for measurement to complete (20ms)
        usleep(20000); // 20ms

        // Read sensor data
        if (read_sensor_data(i2c_fd, data) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            sleep(1);
            continue;
        }

        // Verify CRC
        if (verify_crc(data, 6) != 0) {
            fprintf(stderr, "CRC check failed, retrying...\n");
            sleep(1);
            continue;
        }

        // Extract raw pressure and temperature
        raw_pressure = (data[0] << 8) | data[1];
        raw_temperature = (data[3] << 8) | data[4];

        // Calculate pressure and temperature
        pressure = calculate_pressure(raw_pressure, raw_temperature);
        temperature = calculate_temperature(raw_temperature);

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Blink LED based on pressure
        if (pressure < PRESSURE_THRESHOLD) {
            blink_led(gpio_line, WARNING_BLINK_RATE);
        } else {
            blink_led(gpio_line, NORMAL_BLINK_RATE);
        }

        sleep(1);
    }

    // Cleanup
    set_led_state(gpio_line, 0); // Turn off LED
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

