int read_hdc2010(int i2c_handle, float *temperature, float *humidity) {
    int raw_temperature, raw_humidity;
    int retries = 3; // Maximum number of retries

    // Trigger measurement
    if (i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG register\n");
        return -1;
    }

    // Wait for measurement to complete (polling with timeout)
    int timeout = 500; // Timeout in milliseconds
    while (timeout > 0) {
        int config_value = i2cReadByteData(i2c_handle, MEASUREMENT_CONFIG);
        if (config_value < 0) {
            fprintf(stderr, "Error reading MEASUREMENT_CONFIG register\n");
            return -1;
        }
        if (config_value & 0x01) {
            gpioDelay(10); // Small delay to avoid busy-waiting
            timeout -= 10;
        } else {
            break; // Measurement complete
        }
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement to complete\n");
        return -1;
    }

    // Read temperature data
    raw_temperature = i2cReadWordData(i2c_handle, TEMP_MSB);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
