#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define sensor I2C address and bus
#define I2C_BUS 1
#define I2C_ADDRESS 0x25

// Define continuous measurement command
#define MEASURE_COMMAND 0x362F

// Define data structure for sensor readings
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    char cmd[2] = {(MEASURE_COMMAND >> 8) & 0xFF, MEASURE_COMMAND & 0xFF};

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for measurement to complete (at least 45ms)
    gpioDelay(50000); // 50ms

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, buf, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Extract pressure and temperature data
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);

    // CRC Check
    uint8_t pressure_crc = crc8((uint8_t *)buf, 2);
    uint8_t temperature_crc = crc8((uint8_t *)(buf + 3), 2);

    if (pressure_crc != buf[2] || temperature_crc != buf[5]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Print raw pressure and temperature values
            printf("Pressure: %d, Temperature: %d\n", sensor_data.pressure, sensor_data.temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 500ms
        gpioDelay(500000);
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

