#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define PROFILE_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define MAX_PROFILE_LENGTH 100

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
int spi_handle;
FILE *profile_file = NULL;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Data Structures
typedef struct {
    double time_seconds;
    double target_temp_celsius;
} ProfilePoint;

ProfilePoint profile[MAX_PROFILE_LENGTH];
int profile_length = 0;

// Function Prototypes
int initialize();
void cleanup();
void signal_handler(int signal);
double read_temperature();
double calculate_pid(double current_temp, double target_temp, double *integral, double *previous_error);
void set_relay(double duty_cycle);
void load_profile();
void log_data(double current_temp, double target_temp, double duty_cycle);

// Function Implementations

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    profile_file = fopen(PROFILE_FILE, "r");
    if (profile_file == NULL) {
        fprintf(stderr, "Failed to open profile file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        fclose(profile_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Timestamp,Current Temperature,Target Temperature,Duty Cycle\n");

    return 0;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) spiClose(spi_handle);
    if (profile_file != NULL) fclose(profile_file);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
}

void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

double read_temperature() {
    unsigned char data[2];
    int result;

    result = spiRead(spi_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -273.15; // Return absolute zero on error
    }

    // Check for open circuit
    if (data[0] & 0x04) {
        fprintf(stderr, "Thermocouple open circuit\n");
        return -273.15;
    }

    // Extract temperature data
    int raw_temp = ((data[0] << 8) | data[1]) >> 3;
    double temperature = raw_temp * 0.25;

    return temperature;
}

double calculate_pid(double current_temp, double target_temp, double *integral, double *previous_error) {
    double error = target_temp - current_temp;
    *integral += error;
    double derivative = error - *previous_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;

    // Clamp the output to the range [0, 1]
    if (output < 0) output = 0;
    if (output > 1) output = 1;

    return output;
}

void set_relay(double duty_cycle) {
    int on_time = (int)(duty_cycle * 1000000); // microseconds
    int off_time = 1000000 - on_time;

    gpioPWM(RELAY_GPIO, (int)(duty_cycle * 255)); // pigpio PWM range is 0-255
}

void load_profile() {
    char line[256];
    while (fgets(line, sizeof(line), profile_file) != NULL && profile_length < MAX_PROFILE_LENGTH) {
        if (sscanf(line, "%lf,%lf", &profile[profile_length].time_seconds, &profile[profile_length].target_temp_celsius) == 2) {
            profile_length++;
        } else {
            fprintf(stderr, "Invalid line in profile file: %s", line);
        }
    }
}

void log_data(double current_temp, double target_temp, double duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, current_temp, target_temp, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    if (initialize()) {
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    load_profile();

    double integral = 0;
    double previous_error = 0;
    int profile_index = 0;
    double elapsed_time = 0;

    while (!terminate && profile_index < profile_length) {
        double current_temp = read_temperature();
        if (current_temp < -200) {
            fprintf(stderr, "Error reading temperature, exiting\n");
            break;
        }

        double target_temp = profile[profile_index].target_temp_celsius;
        if (elapsed_time >= profile[profile_index].time_seconds) {
            profile_index++;
            if (profile_index >= profile_length) {
                profile_index = profile_length - 1; // Stay at the last point
            }
        }

        double duty_cycle = calculate_pid(current_temp, target_temp, &integral, &previous_error);
        set_relay(duty_cycle);
        log_data(current_temp, target_temp, duty_cycle);

        sleep(1);
        elapsed_time += 1.0;
    }

    // Shutdown sequence
    printf("Shutting down oven...\n");
    set_relay(0.0); // Turn off the relay
    sleep(5); // Allow time for cooling

    cleanup();
    return 0;
}

