#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define HEATER_GPIO 17
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define LOG_FILE "greenhouse.log"
#define MAX_SENSORS 10
#define SENSOR_PATH "/sys/bus/w1/devices/"
#define W1_DEVICES_DIR "28-"

// Global variables
double setpoint = 25.0; // Default setpoint
double Kp = 1.0;       // Default Kp
double Ki = 0.1;       // Default Ki
double Kd = 0.01;      // Default Kd
double integral = 0.0;
double previous_error = 0.0;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
double read_temperature(const char *sensor_id);
double calculate_pid(double setpoint, double actual_temperature, double *integral, double previous_error, double Kp, double Ki, double Kd);
void set_pwm_duty_cycle(int gpio, int duty_cycle);
void log_data(double setpoint, double average_temperature, double pid_output, int pwm_duty_cycle);
void signal_handler(int signal);
int find_sensors(char sensor_ids[][20], int max_sensors);

// Function to find DS18B20 sensor IDs
int find_sensors(char sensor_ids[][20], int max_sensors) {
    DIR *dir;
    struct dirent *ent;
    int count = 0;

    dir = opendir(SENSOR_PATH);
    if (dir == NULL) {
        perror("Error opening sensor directory");
        return -1;
    }

    while ((ent = readdir(dir)) != NULL && count < max_sensors) {
        if (strncmp(ent->d_name, W1_DEVICES_DIR, strlen(W1_DEVICES_DIR)) == 0) {
            strncpy(sensor_ids[count], ent->d_name, sizeof(sensor_ids[count]) - 1);
            sensor_ids[count][sizeof(sensor_ids[count]) - 1] = '\0'; // Ensure null termination
            count++;
        }
    }

    closedir(dir);
    return count;
}

// Function to read temperature from a DS18B20 sensor
double read_temperature(const char *sensor_id) {
    char filepath[100];
    snprintf(filepath, sizeof(filepath), "%s%s/w1_slave", SENSOR_PATH, sensor_id);

    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1000.0; // Indicate error
    }

    char line1[100], line2[100];
    if (fgets(line1, sizeof(line1), fp) == NULL || fgets(line2, sizeof(line2), fp) == NULL) {
        fclose(fp);
        return -1000.0; // Indicate error
    }

    fclose(fp);

    // Validate CRC (simplified check for demonstration)
    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return -1000.0; // Indicate error
    }

    // Extract temperature
    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found for sensor %s\n", sensor_id);
        return -1000.0; // Indicate error
    }

    long temperature_raw = strtol(temp_str + 2, NULL, 10);
    return (double)temperature_raw / 1000.0;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double previous_error, double Kp, double Ki, double Kd) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;
    gpioPWM(gpio, duty_cycle);
}

// Function to log data to file
void log_data(double setpoint, double average_temperature, double pid_output, int pwm_duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, setpoint, average_temperature, pid_output, pwm_duty_cycle);
    fflush(log_file); // Ensure data is written to disk
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    running = 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    setpoint = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);
    Kd = atof(argv[4]);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char sensor_ids[MAX_SENSORS][20];
    int num_sensors = find_sensors(sensor_ids, MAX_SENSORS);
    if (num_sensors < 0) {
        fprintf(stderr, "Failed to find sensors. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Found %d sensors.\n", num_sensors);

    // Main loop
    while (running) {
        double total_temperature = 0.0;
        int valid_sensor_count = 0;

        for (int i = 0; i < num_sensors; i++) {
            double temperature = read_temperature(sensor_ids[i]);
            if (temperature > -999.0) { // Basic error check
                total_temperature += temperature;
                valid_sensor_count++;
            } else {
                fprintf(stderr, "Error reading temperature from sensor %s\n", sensor_ids[i]);
            }
        }

        double average_temperature = 0.0;
        if (valid_sensor_count > 0) {
            average_temperature = total_temperature / valid_sensor_count;
        } else {
            fprintf(stderr, "No valid temperature readings.\n");
        }

        double pid_output = calculate_pid(setpoint, average_temperature, &integral, previous_error, Kp, Ki, Kd);
        previous_error = setpoint - average_temperature;

        // Limit PID output to 0-255
        int pwm_duty_cycle = (int)pid_output;
        if (pwm_duty_cycle < 0) pwm_duty_cycle = 0;
        if (pwm_duty_cycle > 255) pwm_duty_cycle = 255;

        set_pwm_duty_cycle(PWM_GPIO, pwm_duty_cycle);

        log_data(setpoint, average_temperature, pid_output, pwm_duty_cycle);

        sleep(5);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(HEATER_GPIO, 0); // Turn off heater
    set_pwm_duty_cycle(PWM_GPIO, 0); // Set PWM to 0
    fclose(log_file);
    gpioTerminate();

    return 0;
}

