#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_DELAY_MS 80
#define POLLING_INTERVAL_S 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_aht20();
int read_aht20_data(uint8_t *data);
float calculate_humidity(uint8_t *data);
void control_dehumidifier(float humidity);
void log_humidity(float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to initialize the AHT20 sensor
int initialize_aht20() {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, (char *)init_cmd, 3);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "AHT20 initialization failed, retrying... (retries left: %d)\n", retries);
            gpioDelay(10); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "AHT20 initialization failed after multiple retries.\n");
    return -1; // Failure
}

// Function to read data from the AHT20 sensor
int read_aht20_data(uint8_t *data) {
    uint8_t measure_cmd[3] = {0xAC, 0x33, 0x00};
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, (char *)measure_cmd, 3);
        if (result == 0) {
            gpioDelay(MEASUREMENT_DELAY_MS); // Wait for measurement

            result = i2cReadDevice(i2c_handle, (char *)data, 6);
            if (result == 6) {
                // Verify status byte (bit 7 should be 0 for calibrated and not busy)
                if ((data[0] & 0x80) == 0) {
                    return 0; // Success
                } else {
                    fprintf(stderr, "AHT20 busy or not calibrated.\n");
                    return -1;
                }
            } else {
                fprintf(stderr, "I2C read failed, retrying... (retries left: %d)\n", retries);
                gpioDelay(10); // 10 ms delay
                retries--;
            }
        } else {
            fprintf(stderr, "I2C write failed, retrying... (retries left: %d)\n", retries);
            gpioDelay(10); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "AHT20 read failed after multiple retries.\n");
    return -1; // Failure
}

// Function to calculate humidity from the raw data
float calculate_humidity(uint8_t *data) {
    uint32_t humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | ((uint32_t)data[3] >> 4);
    return ((float)humidity_raw / 0x100000) * 100;
}

// Function to control the dehumidifier relay
void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Turn on dehumidifier
        printf("Dehumidifier ON (Humidity: %.2f%%)\n", humidity);
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
        printf("Dehumidifier OFF (Humidity: %.2f%%)\n", humidity);
    }
}

// Function to log the humidity reading with a timestamp
void log_humidity(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (initialize_aht20() != 0) {
        fprintf(stderr, "AHT20 initialization failed. Continuing without humidity control.\n");
    }

    // Set GPIO 17 as output
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t data[6];
    float humidity;

