#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define MEASUREMENT_COMMAND 0xE5 // Trigger humidity measurement, no hold master
#define RETRY_COUNT 3
#define RETRY_DELAY_SEC 1

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int i2c_fd = -1;
int socket_fd = -1;

// Structure to hold sensor data
typedef struct {
    float humidity;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int i2c_init(const char *bus);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t data);
float read_humidity(int fd);
int crc8(const uint8_t *data, int len);
int http_post(const char *url, const char *json_data);
void signal_handler(int sig);
char* format_json(float humidity, time_t timestamp);

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// I2C initialization function
int i2c_init(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "Failed to write register address: %s", strerror(errno));
        return -1;
    }

    if (read(fd, data, len) != len) {
        syslog(LOG_ERR, "Failed to read data: %s", strerror(errno));
        return -1;
    }

    return 0;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2] = {reg, data};
    if (write(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "Failed to write data: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// CRC-8 checksum calculation function
int crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read humidity from the HTU21D sensor
float read_humidity(int fd) {
    uint8_t data[3];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2c_write_byte(fd, MEASUREMENT_COMMAND, 0) < 0) {
            syslog(LOG_ERR, "Failed to trigger humidity measurement");
            retries--;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        usleep(100000); // Wait for measurement (at least 50ms)

        if (i2c_read_bytes(fd, 0x00, data, 3) < 0) {
            syslog(LOG_ERR, "Failed to read humidity data");
            retries--;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        // CRC check
        if (crc8(data, 2) != data[2]) {
            syslog(LOG_ERR, "CRC check failed");
            retries--;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        // Convert raw data to humidity
        uint16_t raw_humidity = (data[0] << 8) | data[1];
        raw_humidity &= 0xFFFC; // Clear status bits

        float humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);

        // Validate humidity range
        if (humidity < 0.0 || humidity > 100.0) {
            syslog(LOG_ERR, "Humidity out of range: %.2f", humidity);
            retries--;
            sleep(RETRY_DELAY_SEC);
            continue;
        }

        return humidity;
    }

    syslog(LOG_ERR, "Failed to read humidity after multiple retries");
    return -1.0; // Indicate error
}

// Function to format data as JSON
char* format_json(float humidity, time_t timestamp) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string");
        return NULL;
    }
    snprintf(json_string, 100, "{\"humidity\": %.2f, \"timestamp\": %ld}", humidity, timestamp);
    return json_string;
}

// Function to perform HTTP POST request
int http_post(const char *url, const char *json_data) {
    int sock = 0;
    struct sockaddr_in serv_addr;

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation error: %s", strerror(errno));
        return -1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80); // HTTP port

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", strerror(errno));
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Connection Failed: %s", strerror(errno));
        close(sock);
        return -1;
    }

    char request[256];
    snprintf(request, sizeof(request), "POST /humidity HTTP/1.1\r\n" // Assuming /humidity is the endpoint
            "Host: api.example.com\r\n" // Replace with the actual host
            "Content-Type: application/json\r\n" // Set content type to JSON
            "Content-Length: %ld\r\n" // Calculate content length
            "Connection: close\r\n\r\n" // Close the connection after the request
            "%s", strlen(json_data), json_data);

    if (send(sock, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close(sock);
        return -1;
    }

    // Receive response (optional, for debugging)
    char buffer[1024] = {0};
    ssize_t bytes_received = recv(sock, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received > 0) {
        syslog(LOG_INFO, "Received response: %s", buffer);
    } else if (bytes_received < 0) {
        syslog(LOG_ERR, "Receive failed: %s", strerror(errno));
    }

    close(sock);
    return 0;
}

int main() {
    openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting humidity sensor program");

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "I2C initialization failed, exiting");
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "I2C initialized successfully");

    // Main loop
    while (!terminate) {
        // Read humidity
        float humidity = read_humidity(i2c_fd);
        if (humidity >= 0.0) {
            // Get current timestamp
            time_t now = time(NULL);

            // Format data as JSON
            char *json_data = format_json(humidity, now);
            if (json_data != NULL) {
                // Post data to API
                if (http_post(API_ENDPOINT, json_data) == 0) {
                    syslog(LOG_INFO, "Humidity data posted successfully: %s", json_data);
                } else {
                    syslog(LOG_ERR, "Failed to post humidity data");
                }
                free(json_data);
            } else {
                syslog(LOG_ERR, "Failed to format JSON data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        sleep(60); // Wait 60 seconds
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    if (i2c_fd != -1) {
        close(i2c_fd);
        syslog(LOG_INFO, "I2C bus closed");
    }
    if (socket_fd != -1) {
        close(socket_fd);
        syslog(LOG_INFO, "Socket closed");
    }
    closelog();
    return 0;
}

