#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO_CHIP 4
#define PIR_GPIO_LINE 17
#define LOG_FILE_DIR "/var/log/"
#define LOG_FILE_PREFIX "sensor_data_"
#define LOG_FILE_SUFFIX ".csv"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define BACKOFF_MS 10

// Global variables
static volatile sig_atomic_t keep_running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *pir_line = NULL;
static FILE *log_file = NULL;
static time_t last_file_creation_time = 0;

// Function prototypes
void signal_handler(int sig);
int i2c_read_bytes(int fd, unsigned char addr, unsigned char reg, unsigned char *data, int len);
int i2c_write_bytes(int fd, unsigned char addr, unsigned char *data, int len);
int init_aht20(int fd);
int read_aht20(int fd, float *temperature, float *humidity);
int read_tmp117(int fd, float *temperature);
int read_pir();
int create_log_file();
void log_data(float temperature, float humidity, int motion);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, exiting...\n", sig);
        keep_running = 0;
    }
}

// I2C read function with retries and backoff
int i2c_read_bytes(int fd, unsigned char addr, unsigned char reg, unsigned char *data, int len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            perror("Error: ioctl(I2C_SLAVE) failed");
            return -1;
        }

        data[0] = reg;
        if (write(fd, data, 1) != 1) {
            perror("Error: Write register address failed");
            return -1;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C read failed (attempt %d/%d), retrying...\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(BACKOFF_MS * 1000 * retries); // Exponential backoff
        }
    }

    fprintf(stderr, "Error: I2C read failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// I2C write function with retries and backoff
int i2c_write_bytes(int fd, unsigned char addr, unsigned char *data, int len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            perror("Error: ioctl(I2C_SLAVE) failed");
            return -1;
        }

        result = write(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C write failed (attempt %d/%d), retrying...\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(BACKOFF_MS * 1000 * retries); // Exponential backoff
        }
    }

    fprintf(stderr, "Error: I2C write failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Initialize AHT20 sensor
int init_aht20(int fd) {
    unsigned char init_cmd[] = {0xBE, 0x08, 0x00};
    if (i2c_write_bytes(fd, AHT20_ADDR, init_cmd, sizeof(init_cmd)) != 0) {
        fprintf(stderr, "Error: AHT20 initialization failed\n");
        return -1;
    }
    usleep(10000); // Wait for initialization
    return 0;
}

// Read temperature and humidity from AHT20 sensor
int read_aht20(int fd, float *temperature, float *humidity) {
    unsigned char measure_cmd[] = {0xAC, 0x33, 0x00};
    unsigned char data[7];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_bytes(fd, AHT20_ADDR, measure_cmd, sizeof(measure_cmd)) != 0) {
            fprintf(stderr, "Error: AHT20 measure command failed (attempt %d/%d), retrying...\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(BACKOFF_MS * 1000 * retries);
            continue;
        }

        usleep(80000); // Wait for measurement (at least 75ms)

        if (i2c_read_bytes(fd, AHT20_ADDR, 0x00, data, sizeof(data)) != 0) {
            fprintf(stderr, "Error: AHT20 data read failed (attempt %d/%d), retrying...\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(BACKOFF_MS * 1000 * retries);
            continue;
        }

        // Check busy bit
        if (data[0] & 0x80) {
            fprintf(stderr, "Error: AHT20 busy\n");
            return -1;
        }

        // Check status bits (bit 6 and 5 should be 0)
        if ((data[0] & 0x60) != 0) {
            fprintf(stderr, "Error: AHT20 status error\n");
            return -1;
        }

        // Convert data
        unsigned long humidity_raw = ((unsigned long)data[1] << 12) | ((unsigned long)data[2] << 4) | (data[3] >> 4);
        unsigned long temperature_raw = ((unsigned long)(data[3] & 0x0F) << 16) | ((unsigned long)data[4] << 8) | data[5];

        *humidity = ((float)humidity_raw / 0x100000) * 100;
        *temperature = ((float)temperature_raw / 0x100000) * 200 - 50;

        return 0; // Success
    }

    fprintf(stderr, "Error: AHT20 read failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

