#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *rain_sensor_line = NULL;
struct gpiod_line *motor_enable_line = NULL;
struct gpiod_line *motor_in1_line = NULL;
struct gpiod_line *motor_in2_line = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Function prototypes
int read_rain_sensor(struct gpiod_line *line);
int control_motor(struct gpiod_line *enable_line, struct gpiod_line *in1_line, struct gpiod_line *in2_line, int enable, int in1, int in2);
void log_event(const char *message);
void cleanup();
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    log_event("Signal received, cleaning up...");
    cleanup();
    exit(0);
}

// Function to read the rain sensor value
int read_rain_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        log_event("Error reading rain sensor value");
        return -1; // Indicate error
    }
    return value;
}

// Function to control the motor
int control_motor(struct gpiod_line *enable_line, struct gpiod_line *in1_line, struct gpiod_line *in2_line, int enable, int in1, int in2) {
    int ret;

    ret = gpiod_line_set_value(enable_line, enable);
    if (ret < 0) {
        log_event("Error setting motor enable line");
        return -1;
    }

    ret = gpiod_line_set_value(in1_line, in1);
    if (ret < 0) {
        log_event("Error setting motor IN1 line");
        return -1;
    }

    ret = gpiod_line_set_value(in2_line, in2);
    if (ret < 0) {
        log_event("Error setting motor IN2 line");
        return -1;
    }

    return 0;
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Function to cleanup GPIO lines and chip
void cleanup() {
    log_event("Cleaning up GPIO lines...");

    if (rain_sensor_line) {
        gpiod_line_release(rain_sensor_line);
        rain_sensor_line = NULL;
    }
    if (motor_enable_line) {
        gpiod_line_release(motor_enable_line);
        motor_enable_line = NULL;
    }
    if (motor_in1_line) {
        gpiod_line_release(motor_in1_line);
        motor_in1_line = NULL;
    }
    if (motor_in2_line) {
        gpiod_line_release(motor_in2_line);
        motor_in2_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }

    log_event("Cleanup complete.");
}

