#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "Signal received, turning off LED and exiting.\n");
    terminate = 1;
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
    exit(0);
}

// Function to read CPU statistics from /proc/stat
int read_cpu_stats(unsigned long long *user, unsigned long long *nice, unsigned long long *system, unsigned long long *idle, unsigned long long *iowait, unsigned long long *irq, unsigned long long *softirq)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat\n");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading /proc/stat\n");
        fclose(fp);
        return -1;
    }

    if (strncmp(line, "cpu ", 4) != 0) {
        fprintf(stderr, "Unexpected format in /proc/stat\n");
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu",
               user, nice, system, idle, iowait, irq, softirq) != 7) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to calculate CPU load
float calculate_cpu_load(unsigned long long prev_user, unsigned long long prev_nice, unsigned long long prev_system, unsigned long long prev_idle, unsigned long long prev_iowait, unsigned long long prev_irq, unsigned long long prev_softirq,
                         unsigned long long user, unsigned long long nice, unsigned long long system, unsigned long long idle, unsigned long long iowait, unsigned long long irq, unsigned long long softirq)
{
    unsigned long long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq;

    unsigned long long prev_idle_all = prev_idle + prev_iowait;
    unsigned long long idle_all = idle + iowait;

    unsigned long long delta_total = total - prev_total;
    unsigned long long delta_idle = idle_all - prev_idle_all;

    if (delta_total == 0) {
        return 0.0;
    }

    float idle_percentage = (float)delta_idle / (float)delta_total;
    return 1.0 - idle_percentage;
}

// Function to map CPU load to RGB color values
void map_load_to_color(float load, int *red, int *green, int *blue)
{
    if (load <= 0.5) {
        // Green to Yellow gradient
        *red = (int)(255.0 * load / 0.5);
        *green = 255;
        *blue = 0;
    } else {
        // Yellow to Red gradient
        *red = 255;
        *green = (int)(255.0 * (1.0 - (load - 0.5) / 0.5));
        *blue = 0;
    }
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, 255 - red);   // Common anode, so invert the value
    gpioPWM(GREEN_PIN, 255 - green); // Common anode, so invert the value
    gpioPWM(BLUE_PIN, 255 - blue);  // Common anode, so invert the value
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Variables to store CPU stats
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq;
    unsigned long long user, nice, system, idle, iowait, irq, softirq;

    // Read initial CPU stats
    if (read_cpu_stats(&prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read current CPU stats
        if (read_cpu_stats(&user, &nice, &system, &idle, &iowait, &irq, &softirq) != 0) {
            fprintf(stderr, "Error reading CPU stats, exiting.\n");
            break;
        }

        // Calculate CPU load
        float load = calculate_cpu_load(prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq,
                                        user, nice, system, idle, iowait, irq, softirq);

        // Map CPU load to RGB color
        int red, green, blue;
        map_load_to_color(load, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Update previous CPU stats
        prev_user = user;
        prev_nice = nice;
        prev_system = system;
        prev_idle = idle;
        prev_iowait = iowait;
        prev_irq = irq;
        prev_softirq = softirq;

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 us
    }

    // Turn off LED and terminate pigpio
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();

    return 0;
}

