#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define BUFFER_SIZE 20

// Temperature thresholds
#define TEMP_LOW 25.0
#define TEMP_MED_LOW 40.0
#define TEMP_MED_HIGH 60.0

// Structure for circular buffer entries
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} LogEntry;

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;
LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize();
int read_max31855(int *raw_data);
float convert_to_celsius(int raw_data);
int calculate_duty_cycle(float temperature);
void update_fan(int duty_cycle);
void log_data(float temperature, int duty_cycle);
void print_log_buffer();
void signal_handler(int signal);
void cleanup();

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read data from MAX31855
int read_max31855(int *raw_data) {
    char tx_buffer[4] = {0, 0, 0, 0};
    char rx_buffer[4];

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return 1;
    }

    *raw_data = (rx_buffer[0] << 24) | (rx_buffer[1] << 16) | (rx_buffer[2] << 8) | rx_buffer[3];
    return 0;
}

// Function to convert raw data to Celsius
float convert_to_celsius(int raw_data) {
    // Check for fault
    if (raw_data & 0x00000004) {
        fprintf(stderr, "MAX31855 Fault detected!\n");
        return -1000.0; // Indicate an error
    }

    // Extract thermocouple temperature (signed 14-bit)
    int16_t thermocouple_data = (raw_data >> 18) & 0x3FFF; // Mask and shift
    if (thermocouple_data & 0x2000) {
        thermocouple_data |= 0xC000; // Sign extend if negative
    }

    return thermocouple_data * 0.25;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    if (temperature < TEMP_LOW) {
        return 0;
    } else if (temperature < TEMP_MED_LOW) {
        return (int)((temperature - TEMP_LOW) / (TEMP_MED_LOW - TEMP_LOW) * 50.0);
    } else if (temperature < TEMP_MED_HIGH) {
        return (int)((temperature - TEMP_MED_LOW) / (TEMP_MED_HIGH - TEMP_MED_LOW) * 150.0 + 50.0);
    } else {
        return 255;
    }
}

// Function to update the fan speed
void update_fan(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to the circular buffer
void log_data(float temperature, int duty_cycle) {
    log_buffer[buffer_index].timestamp = time(NULL);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the log buffer
void print_log_buffer() {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        struct tm *timeinfo = localtime(&log_buffer[i].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] Temperature: %.2f°C, Duty Cycle: %d\n", timestamp_str, log_buffer[i].temperature, log_buffer[i].duty_cycle);
    }
    printf("--- End of Log Buffer ---\n\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(FAN_GPIO, 0); // Stop the fan
    spiClose(spi_handle);
    gpioTerminate();
    print_log_buffer();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize the system
    if (initialize()) {
        return 1;
    }

    int raw_data;
    float temperature;
    int duty_cycle;

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read temperature from MAX31855
        if (read_max31855(&raw_data) == 0) {
            temperature = convert_to_celsius(raw_data);

            if (temperature > -999.0) { // Check for conversion error
                // Calculate duty cycle
                duty_cycle = calculate_duty_cycle(temperature);

                // Update fan speed
                update_fan(duty_cycle);

                // Log data
                log_data(temperature, duty_cycle);

                printf("Temperature: %.2f°C, Duty Cycle: %d\n", temperature, duty_cycle);
            } else {
                fprintf(stderr, "Error reading temperature, skipping fan update.\n");
            }
        } else {
            fprintf(stderr, "Error reading MAX31855, skipping fan update.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

