#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define RTD_NOMINAL_RESISTANCE 100.0
#define RTD_REF_RESISTANCE 430.0
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len);
int rtd_read_raw(uint16_t *raw_value);
float rtd_to_temperature(uint16_t raw_value);
int log_data(float temperature);
void signal_handler(int sig);
int gpio_init(void);
void gpio_cleanup(void);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    terminate = 1;
}

// SPI initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Set max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting max speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read raw RTD value from MAX31865
int rtd_read_raw(uint16_t *raw_value) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Read RTD MSB and LSB registers (0x01 and 0x02)
    tx_buf[0] = 0x01 | 0x80; // Read command for RTD MSB
    tx_buf[1] = 0x02 | 0x80; // Read command for RTD LSB
    tx_buf[2] = 0x00; // Dummy byte

    if (spi_transfer(tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error reading RTD registers.\n");
        return -1;
    }

    *raw_value = ((uint16_t)rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

// Convert raw RTD value to temperature (Celsius)
float rtd_to_temperature(uint16_t raw_value) {
    float rtd_resistance = ((float)raw_value / 32768.0) * RTD_REF_RESISTANCE;

    // Callendar-Van Dusen equation (simplified for PT100)
    float temperature = (rtd_resistance - RTD_NOMINAL_RESISTANCE) / (RTD_NOMINAL_RESISTANCE * 0.00392);

    return temperature;
}

