#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_CHIPID 0xD0
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUMIDITY 0xF2
#define BME280_REG_CONFIG 0xF5

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_file = NULL; // Log file pointer
volatile sig_atomic_t terminate = 0; // Termination flag

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Function prototypes
int bme280_init(int fd);
int bme280_read_data(int fd, float *temperature, float *humidity, float *pressure);
int bme280_read_calibration_data(int fd, struct bme280_calib_data *calib);
int bme280_write_register(int fd, uint8_t reg, uint8_t value);
int bme280_read_register(int fd, uint8_t reg, uint8_t *value);
int bme280_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int bme280_compensate_data(int fd, int32_t adc_T, int32_t adc_P, int32_t adc_H, float *temperature, float *pressure, float *humidity);
