void signal_handler(int sig);
char* get_timestamp();

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    terminate = 1;
}

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to initialize the BME280 sensor
int bme280_init(int fd) {
    uint8_t chip_id;

    // Check the chip ID
    if (bme280_read_register(fd, BME280_REG_CHIPID, &chip_id) != 0) {
        fprintf(stderr, "Error reading chip ID.\n");
        return -1;
    }

    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    // Set humidity oversampling to 1x
    if (bme280_write_register(fd, BME280_REG_CTRL_HUMIDITY, 0x01) != 0) {
        fprintf(stderr, "Error writing humidity control register.\n");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and normal mode
    if (bme280_write_register(fd, BME280_REG_CTRL_MEAS, 0x27) != 0) { //0b00100111
        fprintf(stderr, "Error writing control measurement register.\n");
        return -1;
    }

    // Set the config register (t_sb = 0.5ms, filter = off)
    if (bme280_write_register(fd, BME280_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error writing config register.\n");
        return -1;
    }

    // Read calibration data
    if (bme280_read_calibration_data(fd, &calib) != 0) {
        fprintf(stderr, "Error reading calibration data.\n");
        return -1;
    }

    return 0;
}

// Function to read calibration data from the BME280
int bme280_read_calibration_data(int fd, struct bme280_calib_data *calib) {
    uint8_t data[26];
    uint8_t hum_data[7];

    if (bme280_read_block(fd, BME280_REG_CALIB_00, data, 26) != 0) {
        fprintf(stderr, "Error reading calibration data block 1.\n");
        return -1;
    }

    if (bme280_read_block(fd, 0xE1, hum_data, 7) != 0) {
        fprintf(stderr, "Error reading calibration data block 2.\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);
    calib->dig_H1 = data[25];
    calib->dig_H2 = (int16_t)hum_data[0] | ((int16_t)hum_data[1] << 8);
    calib->dig_H3 = hum_data[2];
    calib->dig_H4 = (int16_t)((hum_data[3] << 4) | (hum_data[4] & 0x0F));
    calib->dig_H5 = (int16_t)((hum_data[5] << 4) | ((hum_data[4] >> 4) & 0x0F));
    calib->dig_H6 = (int8_t)hum_data[6];

    return 0;
}

// Function to read data from the BME280 sensor
int bme280_read_data(int fd, float *temperature, float *humidity, float *pressure) {
    uint8_t data[8];
    int32_t adc_T, adc_P, adc_H;

    // Read temperature, pressure and humidity data
    if (bme280_read_block(fd, BME280_REG_PRESSURE_MSB, data, 8) != 0) {
        fprintf(stderr, "Error reading data block.\n");
        return -1;
    }

    adc_P = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    adc_T = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;
    adc_H = (int32_t)data[6] << 8 | (int32_t)data[7];

    // Compensate the data
    if (bme280_compensate_data(fd, adc_T, adc_P, adc_H, temperature, pressure, humidity) != 0) {
        fprintf(stderr, "Error compensating data.\n");
        return -1;
    }

    return 0;
}

// Function to compensate the raw data
int bme280_compensate_data(int fd, int32_t adc_T, int32_t adc_P, int32_t adc_H, float *temperature, float *pressure, float *humidity) {
    double var1, var2, var3, var4, var5, var6, var7, var8;

    var1 = (((double)adc_T) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)adc_T) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)adc_T) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    *temperature = (t_fine / 5120.0);

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);
    if (var1 == 0)
    {
        *pressure = 0;
        return 0;
    }
    double p = 1048576.0 - (double)adc_P;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    *pressure = (p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0) / 100.0; // in hPa

    double h = (t_fine - 76800.0);
    h = (adc_H - (((double)calib.dig_H4) * 64.0 + ((double)calib.dig_H5) / 16384.0 * h)) * (((double)calib.dig_H2) / 65536.0 * (1.0 + ((double)calib.dig_H6) / 67108864.0 * h * (1.0 + ((double)calib.dig_H3) / 67108864.0 * h)));
    *humidity = h * (1.0 - h / 100.0);
    if (*humidity > 100.0)
        *humidity = 100.0;
    else if (*humidity < 0.0)
        *humidity = 0.0;

    return 0;
}

// Function to write a register on the BME280
int bme280_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read a register on the BME280
int bme280_read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read a block of data from the BME280
int bme280_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for block read: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading block from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to log the data to a CSV file
void log_data(FILE *fp, float temperature, float humidity, float pressure) {
    char* timestamp = get_timestamp();
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, humidity, pressure);
    fflush(fp); // Ensure data is written to disk immediately
}

