volatile sig_atomic_t terminate = 0; // Termination flag

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Function prototypes
int bme280_init(int fd);
int bme280_read_data(int fd, float *temperature, float *humidity, float *pressure);
int bme280_read_calibration_data(int fd, struct bme280_calib_data *calib);
