// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to initialize the BME280 sensor
int bme280_init(int fd) {
    uint8_t chip_id;

    // Check the chip ID
    if (bme280_read_register(fd, BME280_REG_CHIPID, &chip_id) != 0) {
        fprintf(stderr, "Error reading chip ID.\n");
        return -1;
    }

    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    // Set humidity oversampling to 1x
    if (bme280_write_register(fd, BME280_REG_CTRL_HUMIDITY, 0x01) != 0) {
        fprintf(stderr, "Error writing humidity control register.\n");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and normal mode
    if (bme280_write_register(fd, BME280_REG_CTRL_MEAS, 0x27) != 0) { //0b00100111
        fprintf(stderr, "Error writing control measurement register.\n");
        return -1;
    }

    // Set the config register (t_sb = 0.5ms, filter = off)
    if (bme280_write_register(fd, BME280_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error writing config register.\n");
        return -1;
