// Function to read calibration data from the BME280
int bme280_read_calibration_data(int fd, struct bme280_calib_data *calib) {
    uint8_t data[26];
    uint8_t hum_data[7];

    if (bme280_read_block(fd, BME280_REG_CALIB_00, data, 26) != 0) {
        fprintf(stderr, "Error reading calibration data block 1.\n");
        return -1;
    }

    if (bme280_read_block(fd, 0xE1, hum_data, 7) != 0) {
        fprintf(stderr, "Error reading calibration data block 2.\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);
    calib->dig_H1 = data[25];
    calib->dig_H2 = (int16_t)hum_data[0] | ((int16_t)hum_data[1] << 8);
    calib->dig_H3 = hum_data[2];
    calib->dig_H4 = (int16_t)((hum_data[3] << 4) | (hum_data[4] & 0x0F));
    calib->dig_H5 = (int16_t)((hum_data[5] << 4) | ((hum_data[4] >> 4) & 0x0F));
    calib->dig_H6 = (int8_t)hum_data[6];

    return 0;
}

// Function to read data from the BME280 sensor
int bme280_read_data(int fd, float *temperature, float *humidity, float *pressure) {
    uint8_t data[8];
    int32_t adc_T, adc_P, adc_H;

    // Read temperature, pressure and humidity data
    if (bme280_read_block(fd, BME280_REG_PRESSURE_MSB, data, 8) != 0) {
