#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQUENCY 25000
#define MIN_TEMP 40000
#define MAX_TEMP 70000

static volatile int running = 1;
FILE *log_file = NULL;

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(int temperature) {
    int duty_cycle = 0;

    if (temperature < MIN_TEMP) {
        duty_cycle = 0;
    } else if (temperature > MAX_TEMP) {
        duty_cycle = 255;
    } else {
        duty_cycle = (int)(((float)(temperature - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * 255.0);
    }

    return duty_cycle;
}

// Function to set fan speed using pigpio
void set_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(int temperature, int duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Temperature: %d, Duty Cycle: %d\n", timestamp, temperature, duty_cycle);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    int temperature, duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
            // Consider adding a default temperature or handling the error more gracefully
            // For this example, we'll just continue with the previous temperature
            continue; // Skip to the next iteration
        }

        // Calculate duty cycle
        duty_cycle = calculate_duty_cycle(temperature);

        // Set fan speed
        set_fan_speed(duty_cycle);

        // Log data
        log_data(temperature, duty_cycle);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    set_fan_speed(0); // Stop the fan
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Fan control program stopped.\n");
    return 0;
}

