#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// BMP280 I2C addresses
#define BMP280_ADDR_1 0x76
#define BMP280_ADDR_2 0x77

// BMP280 registers
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_DATA_PRESS_MSB 0xF7
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_STATUS 0xF3

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
bmp280_calib_data calib;
int bmp280_address = BMP280_ADDR_1; // Default address

// Function prototypes
int i2c_read_byte(int fd, uint8_t reg);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int bmp280_init(int fd, bmp280_calib_data *calib);
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure);
double bmp280_compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib);
double bmp280_compensate_pressure(int32_t raw_pressure, bmp280_calib_data calib, double t_fine);
int log_data(FILE *fp, double temperature, double pressure);
void signal_handler(int signal);

// I2C read byte function
int i2c_read_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read byte");
        return -1;
    }
    return value;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t data[2] = {reg, value};
    if (write(fd, data, 2) != 2) {
        perror("Failed to write byte");
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read block");
        return -1;
    }
    return 0;
}

// BMP280 initialization function
int bmp280_init(int fd, bmp280_calib_data *calib) {
    // Read chip ID
    int chip_id = i2c_read_byte(fd, BMP280_REG_CHIPID);
    if (chip_id != 0x58) {
        fprintf(stderr, "Error: Invalid chip ID: 0x%X\n", chip_id);
        return -1;
    }

    // Read calibration data
    uint8_t calib_data[26];
    if (i2c_read_block(fd, BMP280_REG_CALIB_00, calib_data, 26) != 0) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)calib_data[0] | ((uint16_t)calib_data[1] << 8);
    calib->dig_T2 = (int16_t)calib_data[2] | ((int16_t)calib_data[3] << 8);
    calib->dig_T3 = (int16_t)calib_data[4] | ((int16_t)calib_data[5] << 8);
    calib->dig_P1 = (uint16_t)calib_data[6] | ((uint16_t)calib_data[7] << 8);
    calib->dig_P2 = (int16_t)calib_data[8] | ((int16_t)calib_data[9] << 8);
    calib->dig_P3 = (int16_t)calib_data[10] | ((int16_t)calib_data[11] << 8);
    calib->dig_P4 = (int16_t)calib_data[12] | ((int16_t)calib_data[13] << 8);
    calib->dig_P5 = (int16_t)calib_data[14] | ((int16_t)calib_data[15] << 8);
    calib->dig_P6 = (int16_t)calib_data[16] | ((int16_t)calib_data[17] << 8);
    calib->dig_P7 = (int16_t)calib_data[18] | ((int16_t)calib_data[19] << 8);
    calib->dig_P8 = (int16_t)calib_data[20] | ((int16_t)calib_data[21] << 8);
    calib->dig_P9 = (int16_t)calib_data[22] | ((int16_t)calib_data[23] << 8);

    return 0;
}

// BMP280 read raw data function
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];
    if (i2c_read_block(fd, BMP280_REG_DATA_PRESS_MSB, data, 6) != 0) {
        fprintf(stderr, "Error: Failed to read raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// BMP280 compensate temperature function
double bmp280_compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib) {
    double var1, var2, T;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// BMP280 compensate pressure function
double bmp280_compensate_pressure(int32_t raw_pressure, bmp280_calib_data calib, double t_fine) {
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;
    return p/100.0; // Return in hPa
}

// Log data function
int log_data(FILE *fp, double temperature, double pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Try initializing with address 0x76
    if (bmp280_init(i2c_fd, &calib) != 0) {
        // If initialization fails, try address 0x77
        close(i2c_fd);
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C bus");
            return 1;
        }
        bmp280_address = BMP280_ADDR_2;
        if (bmp280_init(i2c_fd, &calib) != 0) {
            fprintf(stderr, "Error: Failed to initialize BMP280 with both addresses\n");
            close(i2c_fd);
            return 1;
        }
    }

    // Open log file
    log_file = fopen("weather_data.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Configure sensor for forced mode
        if (i2c_write_byte(i2c_fd, BMP280_REG_CTRL_MEAS, 0x25) != 0) { // Oversampling x1, forced mode
            fprintf(stderr, "Error: Failed to write control register\n");
            break;
        }

        // Wait for measurement to complete (poll status register)
        int timeout = 100; // Timeout in milliseconds
        while (timeout > 0) {
            int status = i2c_read_byte(i2c_fd, BMP280_REG_STATUS);
            if (status < 0) {
                fprintf(stderr, "Error: Failed to read status register\n");
                break;
            }
            if ((status & 0x08) == 0) {
                break; // Measurement complete
            }
            usleep(1000); // Wait 1 ms
            timeout--;
        }

        if (timeout == 0) {
            fprintf(stderr, "Error: Timeout waiting for measurement\n");
            break;
        }

        // Read raw data
        int32_t raw_temperature, raw_pressure;
        if (bmp280_read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Error: Failed to read raw data\n");
            break;
        }

        // Compensate temperature and pressure
        double temperature = bmp280_compensate_temperature(raw_temperature, calib);
        double pressure = bmp280_compensate_pressure(raw_pressure, calib, temperature);

        // Log data
        if (log_data(log_file, temperature, pressure) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
            break;
        }

        sleep(5); // Wait 5 seconds
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

