#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <pthread.h>
#include <gpiod.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define GPIO_PIN 18 // BCM numbering
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SLEEP_SECONDS 1

// Global variables
static volatile sig_atomic_t running = 1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static int i2c_fd = -1;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

// Function prototypes
void signal_handler(int sig);
int init_i2c();
int read_temperature(float *temperature);
void add_temperature(float temperature);
float calculate_average();
void control_led(float average_temperature);
void cleanup();
void *data_acquisition_thread(void *arg);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        running = 0;
    }
}

// Initialize I2C
int init_i2c() {
    int fd;
    char *bus_name = "i2c-1"; // Use the actual I2C bus name

    fd = open(bus_name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read temperature from LM75
int read_temperature(float *temperature) {
    uint8_t buf[2];
    int16_t raw_temp;

    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }

    raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits

    *temperature = (float)raw_temp / 256.0;
    return 0;
}

// Add temperature to circular buffer
void add_temperature(float temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
    pthread_mutex_unlock(&buffer_mutex);
}

// Calculate running average
float calculate_average() {
    float sum = 0.0;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < buffer_count; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);
    return sum / buffer_count;
}

// Control LED based on temperature
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        }
    } else {
        if (gpiod_line_set_value(gpio_line, 0) < 0) {
            fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        }
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    // Close I2C
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Release GPIO
    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    // Destroy mutex
    pthread_mutex_destroy(&buffer_mutex);

    printf("Cleanup complete.\n");
}

// Data acquisition thread
void *data_acquisition_thread(void *arg) {
    float temperature;

    while (running) {
        if (read_temperature(&temperature) == 0) {
            add_temperature(temperature);
            float average = calculate_average();
            control_led(average);
            printf("Temperature: %.2f°C, Average: %.2f°C\n", temperature, average);
        } else {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
            // Attempt to re-initialize I2C
            close(i2c_fd);
            i2c_fd = init_i2c();
            if (i2c_fd < 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting thread.\n");
                break;
            }
        }
        sleep(SLEEP_SECONDS);
    }
    return NULL;
}

int main() {
    pthread_t thread_id;

    // Signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C, exiting.\n");
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "temperature_monitor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Create data acquisition thread
    if (pthread_create(&thread_id, NULL, data_acquisition_thread, NULL) != 0) {
        fprintf(stderr, "Error creating thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Wait for thread to finish (or SIGINT)
    pthread_join(thread_id, NULL);

    // Cleanup resources
    cleanup();

    return 0;
}

