#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>
#include <jansson.h>

// Constants
#define HEATER_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // Hz
#define MAX31865_CONFIG_REG 0x80
#define MAX31865_CONFIG_VALUE 0xC1
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07
#define MAX31865_VBIAS 0x08
#define MAX31865_AUTO_CONV 0x00
#define MAX31865_FAULT_NONE 0x00
#define MAX31865_FAULT_OPEN 0x01
#define MAX31865_FAULT_SHORT_GND 0x02
#define MAX31865_FAULT_SHORT_VCC 0x04
#define MAX31865_FAULT_OVERVOLTAGE 0x08
#define MAX31865_FAULT_UNDERRUN 0x10
#define TARGET_TEMPERATURE_DEFAULT 25.0
#define KP_DEFAULT 1.0
#define KI_DEFAULT 0.1
#define KD_DEFAULT 0.01
#define MAX_TEMPERATURE 80.0

// Global variables
static volatile int running = 1;
static int spi_handle;
static double target_temperature = TARGET_TEMPERATURE_DEFAULT;
static double Kp = KP_DEFAULT;
static double Ki = KI_DEFAULT;
static double Kd = KD_DEFAULT;
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
void signal_handler(int signal);
int initialize();
int load_config(const char *filename);
double read_temperature();
double rtd_to_resistance(uint16_t rtd_code);
double resistance_to_temperature(double resistance);
double calculate_pid(double setpoint, double actual_value);
void set_heater_duty_cycle(double duty_cycle);
void cleanup();
uint8_t spi_read_register(int handle, uint8_t reg);
void spi_write_register(int handle, uint8_t reg, uint8_t value);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");
    running = 0;
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MAX31865
    spi_write_register(spi_handle, MAX31865_CONFIG_REG, MAX31865_CONFIG_VALUE);

    return 0;
}

// Load configuration from JSON file
int load_config(const char *filename) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error loading config file: %s\n", error.text);
        return 1;
    }

    json_t *target_temp = json_object_get(root, "target_temperature");
    if (target_temp) {
        target_temperature = json_real_value(target_temp);
    }

    json_t *kp = json_object_get(root, "Kp");
    if (kp) {
        Kp = json_real_value(kp);
    }

    json_t *ki = json_object_get(root, "Ki");
    if (ki) {
        Ki = json_real_value(ki);
    }

    json_t *kd = json_object_get(root, "Kd");
    if (kd) {
        Kd = json_real_value(kd);
    }

    json_decref(root);
    return 0;
}

