#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// Temperature thresholds
#define TEMP_MIN 20.0
#define TEMP_MAX 30.0

// Pressure thresholds
#define PRESSURE_MIN 950.0
#define PRESSURE_MAX 1050.0

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
float calculate_temperature(int raw_temp);
float calculate_pressure(int raw_pressure, int raw_temp);
int log_breach(float temperature, float pressure);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read calibration data from BMP180
int read_calibration_data() {
    unsigned char data[22];
    if (read(i2c_fd, data, 22) != 22) {
        perror("Error reading calibration data");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Read raw temperature value
int read_raw_temperature(int *raw_temp) {
    unsigned char data[2];
    unsigned char write_data[2];

    write_data[0] = BMP180_REG_CONTROL;
    write_data[1] = 0x2E; // Temperature measurement command

    if (write(i2c_fd, write_data, 2) != 2) {
        perror("Error writing temperature measurement command");
        return -1;
    }

    usleep(5000); // Wait 4.5ms (minimum)

    write_data[0] = BMP180_REG_MSB;
    if (write(i2c_fd, write_data, 1) != 1) {
        perror("Error writing register address for temperature read");
        return -1;
    }

    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading raw temperature data");
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Read raw pressure value
int read_raw_pressure(int *raw_pressure) {
    unsigned char data[3];
    unsigned char write_data[2];

    write_data[0] = BMP180_REG_CONTROL;
    write_data[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (write(i2c_fd, write_data, 2) != 2) {
        perror("Error writing pressure measurement command");
        return -1;
    }

    usleep(26000); // Wait 25.5ms (OSS = 0)

    write_data[0] = BMP180_REG_MSB;
    if (write(i2c_fd, write_data, 1) != 1) {
        perror("Error writing register address for pressure read");
        return -1;
    }

    if (read(i2c_fd, data, 3) != 3) {
        perror("Error reading raw pressure data");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Calculate temperature in degrees Celsius
float calculate_temperature(int raw_temp) {
    long x1, x2, b5;
    long b6;
    long b3;
    long b4;
    long b7;

    x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    x2 = ((long)mc << 11) / (x1 + md);
    b5 = x1 + x2;

    float temperature = ((b5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Calculate pressure in hPa
float calculate_pressure(int raw_pressure, int raw_temp) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    long oss = BMP180_OSS;

    x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    x2 = ((long)mc << 11) / (x1 + md);
    b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << oss) + 2) >> 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (ac4 * (unsigned long)(x3 + 32768)) >> 15;

    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> oss);
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    float pressure = p / 100.0f; // Convert to hPa
    return pressure;
}

// Log temperature and pressure breaches
int log_breach(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Temperature: %.2f°C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() < 0) {
        fprintf(stderr, "Calibration data read failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    int raw_temp, raw_pressure;
    float temperature, pressure;

    // Main loop
    while (!terminate) {
        // Read raw temperature and pressure
        if (read_raw_temperature(&raw_temp) < 0) {
            fprintf(stderr, "Error reading raw temperature. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }
        if (read_raw_pressure(&raw_pressure) < 0) {
            fprintf(stderr, "Error reading raw pressure. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Calculate temperature and pressure
        temperature = calculate_temperature(raw_temp);
        pressure = calculate_pressure(raw_pressure, raw_temp);

        // Check for breaches
        if (temperature < TEMP_MIN || temperature > TEMP_MAX || pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
            log_breach(temperature, pressure);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

