        return -1;
    }

    usleep(26000); // Wait 25.5ms (OSS = 0)

    write_data[0] = BMP180_REG_MSB;
    if (write(i2c_fd, write_data, 1) != 1) {
        perror("Error writing register address for pressure read");
        return -1;
