float calculate_temperature(int raw_temp);
float calculate_pressure(int raw_pressure, int raw_temp);
void store_reading(float temperature, float pressure);
void print_latest_reading();
void control_fan(float temperature);
void timer_callback();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read calibration data from BMP180
int read_calibration_data() {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CALIBRATION, data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Read raw temperature data from BMP180
int read_raw_temperature(int *raw_temp) {
    char buf[1];
    buf[0] = BMP180_CMD_TEMP;

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_TEMPDATA, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Read raw pressure data from BMP180
int read_raw_pressure(int *raw_pressure) {
    char buf[1];
    buf[0] = BMP180_CMD_PRESSURE0;

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_PRESSUREDATA, data, 2) != 2) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = (data[0] << 8) | data[1];
    return 0;
}

// Calculate true temperature in degrees Celsius
float calculate_temperature(int raw_temp) {
    long X1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + (long)md);
    long B5 = X1 + X2;
    float temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Calculate true pressure in Pascals
float calculate_pressure(int raw_pressure, int raw_temp) {
    long X1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + (long)md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    long X4 = ((long)ac2 * B6) / pow(2, 11);
    long B3 = (((((long)ac1) * 4 + X3) << 0) + X4 + 2) / 4;

    unsigned long X1_pressure = ((unsigned long)ac3 * B6) / pow(2, 13);
    unsigned long X2_pressure = ((unsigned long)b1 * (B6 * B6) / pow(2, 12)) / pow(2, 16);
    unsigned long B4 = X1_pressure + X2_pressure + 32768;
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> 0);

    long pressure;
    if (B7 < 0x80000000)
    {
        pressure = (B7 * 2) / B4;
    }
    else
    {
        pressure = (B7 / B4) * 2;
    }

    X1 = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * pressure) / pow(2, 16);
    pressure = pressure + (X1 + X2 + 3791) / pow(2, 4);

    return pressure;
}

// Store temperature and pressure reading in the circular buffer
void store_reading(float temperature, float pressure) {
    time(&circular_buffer[buffer_index].timestamp);
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print the latest reading from the circular buffer
void print_latest_reading() {
    int index = (buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE; // Get the index of the latest reading
    if (circular_buffer[index].timestamp != 0) {
        printf("Timestamp: %ld, Temperature: %.2f °C, Pressure: %.2f Pa\n",
               circular_buffer[index].timestamp, circular_buffer[index].temperature, circular_buffer[index].pressure);
    } else {
        printf("No readings available yet.\n");
    }
}

// Control the cooling fan based on temperature
void control_fan(float temperature) {
    if (temperature > FAN_TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Timer callback function
void timer_callback() {
    int raw_temp, raw_pressure;
    float temperature, pressure;

    if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_temperature(raw_temp);
        pressure = calculate_pressure(raw_pressure, raw_temp);

        store_reading(temperature, pressure);
        print_latest_reading();
        control_fan(temperature);
    } else {
        fprintf(stderr, "Error reading sensor data in timer callback\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan off

    // Set up hardware timer callback
    gpioSetTimerFunc(0, SAMPLE_INTERVAL, timer_callback);

    // Main loop (wait for termination signal)
    while (!terminate) {
        sleep(1); // Sleep for 1 second
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

