#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_GPIO 17
#define SPI_CE0 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz

// Define PI controller parameters
#define TARGET_TEMPERATURE 25.0
#define KP 1.0
#define KI 0.1
#define MAX_DUTY_CYCLE 80.0
#define MIN_DUTY_CYCLE 0.0

// Define logging parameters
#define LOG_FILE "heater_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
double read_temperature();
double calculate_pwm(double current_temperature);
void set_heater_pwm(double duty_cycle);
void log_data(double temperature, double duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%)\n");
    }

    return 0;
}

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char data[4];
    int result = spiRead(spi_handle, data, 4);

    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -1000.0;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1000.0;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1000.0;
    }

    // Extract temperature data
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    double temperature = (double)raw_temp * 0.25;

    return temperature;
}

// Function to calculate PWM duty cycle using PI controller
double calculate_pwm(double current_temperature) {
    static double integral = 0.0;
    double error = TARGET_TEMPERATURE - current_temperature;
    integral += error;

    // Anti-windup
    if (integral > (TARGET_TEMPERATURE - MIN_TEMPERATURE) / KI) {
        integral = (TARGET_TEMPERATURE - MIN_TEMPERATURE) / KI;
    } else if (integral < 0) {
        integral = 0;
    }

    double duty_cycle = KP * error + KI * integral;

    // Limit duty cycle
    if (duty_cycle > MAX_DUTY_CYCLE) {
        duty_cycle = MAX_DUTY_CYCLE;
    } else if (duty_cycle < MIN_DUTY_CYCLE) {
        duty_cycle = MIN_DUTY_CYCLE;
    }

    return duty_cycle;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * 255.0 / 100.0); // pigpio PWM range is 0-255
    gpioPWM(HEATER_GPIO, pwm_value);
}

// Function to log data to file
void log_data(double temperature, double duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    set_heater_pwm(0.0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Temperature control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        double temperature = read_temperature();

        if (temperature < -900.0) {
            fprintf(stderr, "Error reading temperature, setting duty cycle to 0\n");
            set_heater_pwm(0.0);
            log_data(temperature, 0.0);
        } else {
            double duty_cycle = calculate_pwm(temperature);
            set_heater_pwm(duty_cycle);
            log_data(temperature, duty_cycle);
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

