    int pwm_value = (int)(duty_cycle * 255.0 / 100.0); // pigpio PWM range is 0-255
    gpioPWM(HEATER_GPIO, pwm_value);
}

// Function to log data to file
void log_data(double temperature, double duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    set_heater_pwm(0.0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Temperature control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        double temperature = read_temperature();

        if (temperature < -900.0) {
            fprintf(stderr, "Error reading temperature, setting duty cycle to 0\n");
            set_heater_pwm(0.0);
            log_data(temperature, 0.0);
        } else {
            double duty_cycle = calculate_pwm(temperature);
            set_heater_pwm(duty_cycle);
            log_data(temperature, duty_cycle);
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

