#define BLUE_PIN  27

// Define temperature thresholds (in millidegrees Celsius)
#define TEMP_BLUE  40000
#define TEMP_GREEN 60000

// Global flag to signal program termination
volatile sig_atomic_t terminate_flag = 0;

// Signal handler function
void signal_handler(int signal) {
    terminate_flag = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to read CPU temperature from file
int read_temperature() {
    FILE *fp;
    char buffer[10];
    int temperature = -1; // Default to -1 to indicate error

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1;
    }

    if (fread(buffer, 1, sizeof(buffer) - 1, fp) <= 0) {
        if (ferror(fp)) {
            fprintf(stderr, "Error: Could not read temperature from file.\n");
        }
        fclose(fp);
        return -1;
    }

    buffer[sizeof(buffer) - 1] = '\0'; // Ensure null termination
    temperature = atoi(buffer);
    fclose(fp);

    return temperature;
}

