void set_color(int temperature) {
    int red, green, blue;

    if (temperature < TEMP_BLUE) {
        red = 255;   // Common anode, so 255 is off
        green = 255;
        blue = 0;    // Blue on
    } else if (temperature < TEMP_GREEN) {
        red = 255;
        green = 0;   // Green on
        blue = 255;
    } else {
        red = 0;    // Red on
        green = 255;
        blue = 255;
    }

    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

