#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define SERVER_URL "http://yourserver.com/api/humidity"

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} SensorData;

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to terminate pigpio
void terminate_pigpio() {
    gpioTerminate();
}

// Function to read data from DHT22 sensor
SensorData read_dht22() {
    SensorData data = {0.0, 0.0, 0};
    int retries = 0;
    int bit_idx = 0;
    int byte_idx = 0;
    unsigned int raw_data[5] = {0, 0, 0, 0, 0};

    while (retries < MAX_RETRIES) {
        // Send start signal
        gpioSetMode(DHT22_GPIO, PI_OUTPUT);
        gpioWrite(DHT22_GPIO, 0);
        gpioDelay(1); // 1 ms
        gpioWrite(DHT22_GPIO, 1);
        gpioDelay(30); // Wait for sensor to respond

        // Check for sensor response
        gpioSetMode(DHT22_GPIO, PI_INPUT);
        gpioDelay(40); // Wait for response

        if (gpioRead(DHT22_GPIO) == 0) {
            gpioDelay(80); // Wait for end of response
            if (gpioRead(DHT22_GPIO) == 1) {
                // Read 40 bits of data
                for (int i = 0; i < 40; i++) {
                    // Wait for low
                    while (gpioRead(DHT22_GPIO) == 0);
                    // Measure high time
                    struct timeval start, end;
                    gettimeofday(&start, NULL);
                    while (gpioRead(DHT22_GPIO) == 1);
                    gettimeofday(&end, NULL);
                    unsigned int duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);

                    // Determine if it's a 0 or 1
                    raw_data[byte_idx] <<= 1;
                    if (duration > 50) { // Empirical threshold
                        raw_data[byte_idx] |= 1;
                    }

                    bit_idx++;
                    if (bit_idx == 8) {
                        bit_idx = 0;
                        byte_idx++;
                    }
                }

                // Validate checksum
                if ((raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) == raw_data[4]) {
                    // Convert data
                    data.humidity = (float)((raw_data[0] << 8) | raw_data[1]) / 10.0;
                    data.temperature = (float)(((raw_data[2] & 0x7F) << 8) | raw_data[3]) / 10.0;
                    if (raw_data[2] & 0x80) {
                        data.temperature *= -1;
                    }
                    data.valid = 1;
                    return data; // Success
                } else {
                    fprintf(stderr, "Checksum error, retry %d\n", retries + 1);
                }
            } else {
                fprintf(stderr, "No response from sensor, retry %d\n", retries + 1);
            }
        } else {
            fprintf(stderr, "No response from sensor, retry %d\n", retries + 1);
        }

        retries++;
        gpioDelay(1000); // Wait before retrying
    }

    fprintf(stderr, "Failed to read DHT22 after %d retries\n", MAX_RETRIES);
    return data; // Return invalid data
}

// Function to format data as JSON
char* format_json(float temperature, float humidity) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Failed to allocate memory for JSON string\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    return json_string;
}

// Function to send HTTP POST request
int send_http_post(const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        // Set content type to application/json
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 200 && response_code < 300) {
                printf("HTTP POST successful, response code: %ld\n", response_code);
            } else {
                fprintf(stderr, "HTTP POST failed, response code: %ld\n", response_code);
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        SensorData sensor_data = read_dht22();

        if (sensor_data.valid) {
            char *json_data = format_json(sensor_data.temperature, sensor_data.humidity);
            if (json_data != NULL) {
                send_http_post(json_data);
                free(json_data);
            }
        } else {
            fprintf(stderr, "Invalid sensor data, skipping HTTP POST\n");
        }

        sleep(5); // Wait 5 seconds
    }

    // Clean up resources
    terminate_pigpio();

    return 0;
}

