#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_START 0xAA
#define BMP180_REG_CAL_END 0xBF

// Oversampling Setting (OSS)
#define OSS 3

// GPIO pin for push-button interrupt
#define BUTTON_GPIO 4

// Debounce time in microseconds
#define DEBOUNCE_TIME 200000

// Global variables
static int i2c_handle;
static volatile int logging_enabled = 0;
static volatile uint32_t last_interrupt_time = 0;
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
double calculate_pressure(int raw_temp, int raw_pressure);
void log_data(double pressure);
void button_isr(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to read calibration data from BMP180
int read_calibration_data() {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_START, data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    // Basic validation (example: check if ac1 is not zero)
    if (ac1 == 0) {
        fprintf(stderr, "Error: Invalid calibration data (ac1 is zero).\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int *raw_temp) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing temperature command: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(5000); // Wait 4.5ms (minimum)

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature: %s\n", strerror(errno));
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
