#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <curl/curl.h>
#include <pigpio.h>
#include <time.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2 // seconds
#define SERVER_URL_DEFAULT "http://your-server.com/api/humidity"
#define MAX_JSON_LENGTH 256

// Structure to hold program configuration
typedef struct {
    char *server_url;
    int gpio_pin;
    int max_retries;
    int backoff_delay;
} ProgramConfig;

// Global variables
static volatile int running = 1;
static ProgramConfig config;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to read data from DHT22 sensor
int read_dht22_data(int gpio_pin, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int i, j;

    // Send start signal
    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0);
    gpioDelay(1); // 1 ms
    gpioWrite(gpio_pin, 1);
    gpioDelay(30); // 30 us
    gpioSetMode(gpio_pin, PI_INPUT);

    // Read data
    for (i = 0; i < 40; i++) {
        // Wait for low
        int count = 0;
        while (gpioRead(gpio_pin) == 0) {
            count++;
            if (count > 1000) {
                syslog(LOG_ERR, "DHT22 timeout waiting for low");
                return -1;
            }
            gpioDelay(1); // 1 us
        }

        // Wait for high
        count = 0;
        while (gpioRead(gpio_pin) == 1) {
            count++;
            if (count > 1000) {
                syslog(LOG_ERR, "DHT22 timeout waiting for high");
                return -1;
            }
            gpioDelay(1); // 1 us
        }

        // Determine if it's a 0 or 1 based on the length of the high pulse
        if (count > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Validate checksum
    if ((data[0] + data[1] + data[2] + data[3]) & 0xFF != data[4]) {
        syslog(LOG_ERR, "DHT22 checksum failure");
        return -1;
    }

    // Calculate humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;

    return 0;
}

// Function to format humidity data as JSON
int format_json(float humidity, char *json_string, size_t json_string_size) {
    int ret = snprintf(json_string, json_string_size, "{\"humidity\": %.1f}", humidity);
    if (ret < 0 || ret >= json_string_size) {
        syslog(LOG_ERR, "Failed to format JSON");
        return -1;
    }
    return 0;
}

// Function to post data to server using libcurl
int post_data(const char *url, const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 200 && response_code < 300) {
                syslog(LOG_INFO, "Data posted successfully, HTTP status: %ld", response_code);
            } else {
                syslog(LOG_ERR, "HTTP request failed, status code: %ld", response_code);
            }
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    } else {
        syslog(LOG_ERR, "curl_easy_init() failed");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

// Function to handle errors and retry
int handle_error(const char *message, int retries) {
    syslog(LOG_ERR, "%s, retry %d/%d", message, retries + 1, config.max_retries);
    if (retries < config.max_retries) {
        sleep(config.backoff_delay * (1 << retries)); // Exponential backoff
    }
    return retries + 1;
}

int main(int argc, char *argv[]) {
    int opt;
    char *server_url = NULL;

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set default configuration
    config.server_url = strdup(SERVER_URL_DEFAULT);
    config.gpio_pin = DHT22_GPIO;
    config.max_retries = MAX_RETRIES;
    config.backoff_delay = BACKOFF_DELAY;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                free(config.server_url);
                config.server_url = strdup(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio, exiting");
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        float humidity;
        char json_data[MAX_JSON_LENGTH];
        int retries = 0;

        // Read DHT22 data with retries
        while (retries <= config.max_retries) {
            if (read_dht22_data(config.gpio_pin, &humidity) == 0) {
                break; // Success
            } else {
                retries = handle_error("Failed to read DHT22 data", retries);
                if (retries > config.max_retries) {
                    syslog(LOG_ERR, "Max retries reached for DHT22, skipping this iteration");
                    break;
                }
            }
        }

        if (retries <= config.max_retries) {
            // Format data as JSON
            if (format_json(humidity, json_data, sizeof(json_data)) == 0) {
                // Post data to server with retries
                retries = 0;
                while (retries <= config.max_retries) {
                    if (post_data(config.server_url, json_data) == 0) {
                        break; // Success
                    } else {
                        retries = handle_error("Failed to post data to server", retries);
                        if (retries > config.max_retries) {
                            syslog(LOG_ERR, "Max retries reached for server post, skipping this iteration");
                            break;
                        }
                    }
                }
            } else {
                syslog(LOG_ERR, "Failed to format JSON data");
            }
        }

        sleep(10); // Read every 10 seconds
    }

    // Cleanup
    gpioTerminate();
    free(config.server_url);
    closelog();

    return 0;
}

