        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 200 && response_code < 300) {
                syslog(LOG_INFO, "Data posted successfully, HTTP status: %ld", response_code);
            } else {
                syslog(LOG_ERR, "HTTP request failed, status code: %ld", response_code);
            }
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    } else {
        syslog(LOG_ERR, "curl_easy_init() failed");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

// Function to handle errors and retry
int handle_error(const char *message, int retries) {
    syslog(LOG_ERR, "%s, retry %d/%d", message, retries + 1, config.max_retries);
    if (retries < config.max_retries) {
        sleep(config.backoff_delay * (1 << retries)); // Exponential backoff
    }
    return retries + 1;
}

int main(int argc, char *argv[]) {
    int opt;
    char *server_url = NULL;

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set default configuration
    config.server_url = strdup(SERVER_URL_DEFAULT);
    config.gpio_pin = DHT22_GPIO;
    config.max_retries = MAX_RETRIES;
    config.backoff_delay = BACKOFF_DELAY;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                free(config.server_url);
                config.server_url = strdup(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio, exiting");
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        float humidity;
        char json_data[MAX_JSON_LENGTH];
        int retries = 0;

        // Read DHT22 data with retries
        while (retries <= config.max_retries) {
            if (read_dht22_data(config.gpio_pin, &humidity) == 0) {
                break; // Success
            } else {
                retries = handle_error("Failed to read DHT22 data", retries);
                if (retries > config.max_retries) {
                    syslog(LOG_ERR, "Max retries reached for DHT22, skipping this iteration");
                    break;
                }
            }
        }

        if (retries <= config.max_retries) {
            // Format data as JSON
            if (format_json(humidity, json_data, sizeof(json_data)) == 0) {
                // Post data to server with retries
                retries = 0;
                while (retries <= config.max_retries) {
                    if (post_data(config.server_url, json_data) == 0) {
                        break; // Success
                    } else {
                        retries = handle_error("Failed to post data to server", retries);
                        if (retries > config.max_retries) {
                            syslog(LOG_ERR, "Max retries reached for server post, skipping this iteration");
                            break;
                        }
                    }
                }
            } else {
                syslog(LOG_ERR, "Failed to format JSON data");
            }
        }

        sleep(10); // Read every 10 seconds
    }

    // Cleanup
    gpioTerminate();
    free(config.server_url);
    closelog();

    return 0;
}

