#include <errno.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variable to track the current fan state
int current_fan_state = 0;

// Function prototypes
int read_cpu_temp();
int determine_fan_state(int temperature);
int write_fan_state(int state);
int log_fan_change(int state);
int get_max_fan_state();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        log_fan_change(0); // Log fan stop
        write_fan_state(0); // Stop the fan
        exit(0);
    }
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    int temp = -1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fp = fopen(TEMP_FILE, "r");
        if (fp == NULL) {
            perror("Error opening temperature file");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        if (fgets(buffer, sizeof(buffer), fp) == NULL) {
            perror("Error reading temperature file");
            fclose(fp);
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        fclose(fp);

        // Convert string to integer
        temp = atoi(buffer);
        if (temp == 0 && errno == EINVAL) {
            fprintf(stderr, "Error converting temperature to integer\n");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        break; // Exit loop if read is successful
    }

    if (temp == -1) {
        fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
    }

    return temp;
}

// Function to determine fan state based on temperature
int determine_fan_state(int temperature) {
    if (temperature < 45000) {
        return 0;
    } else if (temperature < 55000) {
        return 1;
    } else if (temperature < 65000) {
        return 2;
    } else {
        return 3;
    }
}

// Function to write fan state to file
int write_fan_state(int state) {
    FILE *fp;
    int max_state = get_max_fan_state();

    if (state < 0 || state > max_state) {
        fprintf(stderr, "Invalid fan state: %d. Max state is %d\n", state, max_state);
        return -1;
    }

    fp = fopen(FAN_STATE_FILE, "w");
    if (fp == NULL) {
        perror("Error opening fan state file");
        return -1;
    }

    fprintf(fp, "%d", state);
    fclose(fp);

    return 0;
}

// Function to log fan changes to file
int log_fan_change(int state) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s: Fan state changed to %d\n", timestamp, state);
    fclose(fp);

    return 0;
}

// Function to get the maximum fan state
int get_max_fan_state() {
    FILE *fp;
    char buffer[10];
    int max_state = 0;

    fp = fopen(FAN_STATE_FILE, "r");
    if (fp == NULL) {
        perror("Error opening fan state file for max state");
        return 0; // Default to 0 if we can't read the file
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Error reading max fan state");
        fclose(fp);
        return 0; // Default to 0 if we can't read the file
    }

    fclose(fp);

    max_state = atoi(buffer);
    if (max_state == 0 && errno == EINVAL) {
        fprintf(stderr, "Error converting max fan state to integer\n");
        return 0;
    }

    return max_state;
}

int main() {
    int temperature, fan_state;

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        temperature = read_cpu_temp();
        if (temperature == -1) {
            fprintf(stderr, "Failed to read temperature, skipping fan control\n");
            sleep(5);
            continue;
        }

        fan_state = determine_fan_state(temperature);

        if (fan_state != current_fan_state) {
            if (write_fan_state(fan_state) == 0) {
                log_fan_change(fan_state);
                current_fan_state = fan_state;
            } else {
                fprintf(stderr, "Failed to write fan state\n");
            }
        }

        sleep(5);
    }

    return 0;
}

