#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define TARGET_TEMPERATURE 50.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define LOG_FILE "heater_log.txt"

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// PID state
typedef struct {
    float integral;
    float previous_error;
} PIDState;

PIDState pid_state = {0.0, 0.0};

// Function prototypes
float read_temperature();
float calculate_pid(float current_temperature, float target_temperature, PIDState *pid_state);
void set_heater_duty_cycle(float duty_cycle);
void log_data(float temperature, float duty_cycle, float pid_output);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, 100); // Set range to 0-100 for percentage

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char data[4];
    int result = spiRead(spi_handle, data, 4);

    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "Thermocouple open circuit\n");
        return -1000.0;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "Thermocouple short to GND\n");
        return -1000.0;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "Thermocouple short to VCC\n");
        return -1000.0;
    }

    // Extract temperature data (ignoring fault bits)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2; // Shift right by 2 bits to remove fault bits
    float temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PID output
float calculate_pid(float current_temperature, float target_temperature, PIDState *pid_state) {
    float error = target_temperature - current_temperature;
    pid_state->integral += error;
    float derivative = error - pid_state->previous_error;
    float output = Kp * error + Ki * pid_state->integral + Kd * derivative;
    pid_state->previous_error = error;

    // Clamp the output to 0-100
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    return output;
}

// Function to set heater duty cycle
void set_heater_duty_cycle(float duty_cycle) {
    gpioPWM(HEATER_GPIO, (int)duty_cycle);
}

// Function to log data to file
void log_data(float temperature, float duty_cycle, float pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %.2f, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioPWM(HEATER_GPIO, 0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    while (running) {
        float temperature = read_temperature();

        if (temperature < -900.0) {
            fprintf(stderr, "Thermocouple fault detected, disabling heater\n");
            set_heater_duty_cycle(0.0);
            pid_state.integral = 0.0; // Reset PID state
            pid_state.previous_error = 0.0;
            log_data(temperature, 0.0, 0.0);
            sleep(1);
            continue;
        }

        if (temperature > 100.0 || temperature < 0.0) {
            fprintf(stderr, "Temperature out of range, disabling heater\n");
            set_heater_duty_cycle(0.0);
            pid_state.integral = 0.0; // Reset PID state
            pid_state.previous_error = 0.0;
            log_data(temperature, 0.0, 0.0);
            sleep(1);
            continue;
        }

        float pid_output = calculate_pid(temperature, TARGET_TEMPERATURE, &pid_state);
        set_heater_duty_cycle(pid_output);
        log_data(temperature, pid_output, pid_output);

        sleep(1);
    }

    cleanup();
    return 0;
}

