        }

        if (temperature > 100.0 || temperature < 0.0) {
            fprintf(stderr, "Temperature out of range, disabling heater\n");
            set_heater_duty_cycle(0.0);
            pid_state.integral = 0.0; // Reset PID state
            pid_state.previous_error = 0.0;
            log_data(temperature, 0.0, 0.0);
            sleep(1);
            continue;
        }

        float pid_output = calculate_pid(temperature, TARGET_TEMPERATURE, &pid_state);
        set_heater_duty_cycle(pid_output);
        log_data(temperature, pid_output, pid_output);

        sleep(1);
    }

    cleanup();
    return 0;
}

