#define LOG_FILE "cooling_log.csv"
#define PWM_FREQUENCY 25000 // 25 kHz

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_cpu_temp();
float calculate_duty_cycle(int temperature);
int set_fan_speed(int duty_cycle);
int log_data(int temperature, int duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp_milli_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temp_milli_celsius;
}

// Function to calculate PWM duty cycle based on temperature
float calculate_duty_cycle(int temperature) {
    float duty_cycle;

    if (temperature <= 40000) {
        duty_cycle = 0.0;
    } else if (temperature >= 70000) {
        duty_cycle = 100.0;
    } else {
        duty_cycle = (float)(temperature - 40000) / (70000 - 40000) * 100.0;
    }

    return duty_cycle;
}

// Function to set fan speed using pigpio
int set_fan_speed(int duty_cycle) {
    int gpio_range_result = gpioSetMode(FAN_GPIO, PI_OUTPUT);
    if (gpio_range_result != 0) {
        fprintf(stderr, "Error setting GPIO mode: %d\n", gpio_range_result);
        return -1;
    }

    int pwm_range_result = gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    if (pwm_range_result != 0) {
        fprintf(stderr, "Error setting PWM frequency: %d\n", pwm_range_result);
        return -1;
    }

    int pwm_range = gpioGetPWMrange(FAN_GPIO);
    if (pwm_range < 0) {
        fprintf(stderr, "Error getting PWM range: %d\n", pwm_range);
        return -1;
    }

    int pwm_value = (int)((duty_cycle / 100.0) * pwm_range);

    int gpioPWMresult = gpioPWM(FAN_GPIO, pwm_value);
    if (gpioPWMresult != 0) {
        fprintf(stderr, "Error setting PWM value: %d\n", gpioPWMresult);
        return -1;
    }

    return 0;
}

