        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
        fprintf(log_file, "Timestamp,Temperature (C),Duty Cycle (%%)\n"); // Write header if file is newly created
    }

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, (float)temperature / 1000.0, duty_cycle);
    fflush(log_file); // Ensure data is written to disk

