    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting.\n");
            // Consider exiting if temperature reading fails consistently
            sleep(5);
            continue; // Skip to the next iteration
        }

        // Calculate duty cycle
        duty_cycle = calculate_duty_cycle(temperature);

        // Set fan speed
        result = set_fan_speed((int)duty_cycle);
        if (result != 0) {
            fprintf(stderr, "Error setting fan speed, exiting.\n");
            program_running = 0; // Exit the loop if fan control fails
        }

        // Log data
        result = log_data(temperature, (int)duty_cycle);
        if (result != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    printf("Shutting down...\n");
    set_fan_speed(0); // Turn off the fan
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio

    return 0;
}

