#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09

// Define I2C bus
#define I2C_BUS 1

// Define measurement command
#define MEASURE_CMD 0x3608

// Define log file name
#define LOG_FILE "flow_log.txt"

// Global variables for I2C handles and program state
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int i2c_handle, int sensor_address, float *flow_rate);
int log_data(float flow_rate1, float flow_rate2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read flow rate from a sensor
int read_sensor(int i2c_handle, int sensor_address, float *flow_rate) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buffer[3];
    int retries = 3;
    int result;

    while (retries > 0) {
        // Set the I2C slave address
        if (i2cSetSlave(i2c_handle, sensor_address) != 0) {
            fprintf(stderr, "Error setting I2C slave address to 0x%02X\n", sensor_address);
            return -1;
        }

        // Send the measurement command
        result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device (address 0x%02X): %d\n", sensor_address, result);
            retries--;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        // Read the sensor data
        result = i2cReadDevice(i2c_handle, buffer, 3);
        if (result != 3) {
            fprintf(stderr, "Error reading from I2C device (address 0x%02X): %d\n", sensor_address, result);
            retries--;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        // CRC validation
        unsigned char crc = buffer[2];
        unsigned char crc_calculated = 0xFF;
        unsigned char data = buffer[0];

        for (int i = 0; i < 8; i++) {
            if ((crc_calculated ^ data) & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ 0x31;
            } else {
                crc_calculated <<= 1;
            }
            data <<= 1;
        }

        data = buffer[1];
        for (int i = 0; i < 8; i++) {
            if ((crc_calculated ^ data) & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ 0x31;
            } else {
                crc_calculated <<= 1;
            }
            data <<= 1;
        }

        if (crc_calculated != crc) {
            fprintf(stderr, "CRC validation failed for sensor 0x%02X\n", sensor_address);
            *flow_rate = -1.0; // Indicate CRC failure
            return -1;
        }

        // Convert raw value to flow rate
        int16_t raw_value = (buffer[0] << 8) | buffer[1];
        *flow_rate = (float)raw_value * 0.01;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor 0x%02X after multiple retries\n", sensor_address);
    return -1; // Failure after retries
}

// Function to log data to a file
int log_data(float flow_rate1, float flow_rate2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow_rate1, flow_rate2);
    fclose(fp);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles
    i2c_handle1 = i2cOpen(I2C_BUS, 0x00, 0); // Dummy address, will be set in read_sensor
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, 0x00, 0); // Dummy address, will be set in read_sensor
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow_rate1, flow_rate2;

    // Main loop
    while (program_running) {
        // Read flow rates from sensors
        if (read_sensor(i2c_handle1, SENSOR1_ADDR, &flow_rate1) != 0) {
            flow_rate1 = -1.0; // Indicate error
        }
        if (read_sensor(i2c_handle2, SENSOR2_ADDR, &flow_rate2) != 0) {
            flow_rate2 = -1.0; // Indicate error
        }

        // Log the data
        if (flow_rate1 != -1.0 && flow_rate2 != -1.0) {
            if (log_data(flow_rate1, flow_rate2) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Skipping logging due to sensor error\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

