#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the rotary encoder
#define ENCODER_A 17
#define ENCODER_B 18

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360.0

// Global variables
volatile int encoder_count = 0;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_encoder_state();
void update_encoder_count(int state);
double calculate_angle();
int log_data(double angle);
void signal_handler(int signal);

// Structure to hold encoder state
typedef struct {
    int a;
    int b;
} EncoderState;

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(ENCODER_A, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A, PI_PUD_UP);
    gpioSetMode(ENCODER_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER_B, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read the current state of the encoder
int read_encoder_state() {
    int a = gpioRead(ENCODER_A);
    int b = gpioRead(ENCODER_B);
    return (a << 1) | b; // Combine the two bits into a single integer
}

// Function to update the encoder count based on the state
void update_encoder_count(int state) {
    static int last_state = 0;
    int delta;

    switch (state) {
        case 0: // 00
            if (last_state == 1) delta = -1; // 11
            else if (last_state == 2) delta = 1; // 10
            else delta = 0;
            break;
        case 1: // 01
            if (last_state == 0) delta = 1; // 00
            else if (last_state == 3) delta = -1; // 11
            else delta = 0;
            break;
        case 2: // 10
