#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define FIFO_DATA_REG 0x60
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t ir;
} sensor_data_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_adpd144ri(int fd, sensor_data_t *data);
void process_data(sensor_data_t data);
void control_led(int gpio, int state);
void log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Read ADPD144RI data
int read_adpd144ri(int fd, sensor_data_t *data) {
    uint8_t buffer[4];
    int result;

    // Read 4 bytes from FIFO data register
    result = read(fd, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Combine bytes to form 16-bit values
    data->red = (buffer[0] << 8) | buffer[1];
    data->ir = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Process sensor data
void process_data(sensor_data_t data) {
    if (data.ir > IR_THRESHOLD) {
        control_led(LED_GPIO, 1); // Turn LED on
    } else {
        control_led(LED_GPIO, 0); // Turn LED off
    }
}

// Control LED
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Log data to file
void log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u\n", timestamp, data.red, data.ir);
    fflush(fp); // Ensure data is written to file immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, ADPD144RI_ADDR);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_adpd144ri(i2c_fd, &sensor_data) == 0) {
            // Process data
            process_data(sensor_data);

            // Log data
            log_data(log_file, sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Wait for next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

