#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to configure GPIO pin as input with pull-down resistor
int configure_gpio_input(int gpio_pin) {
    gpioSetMode(gpio_pin, PI_INPUT);
    gpioSetPullUpDown(gpio_pin, PI_PUD_DOWN);
    return 0;
}

// Interrupt service routine (ISR) to count rising edges
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate RPM
double calculate_rpm(int pulse_count) {
    return (double)pulse_count * 60.0; // 1 pulse per revolution
}

// Function to log RPM to file
int log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
        fflush(log_file); // Ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Configure GPIO pin
    if (configure_gpio_input(GPIO_PIN) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register ISR
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "ISR registration failed\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Reset pulse count
        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate RPM
        double rpm = calculate_rpm(current_pulse_count);

        // Log RPM
        if (log_rpm(rpm) != 0) {
            running = 0; // Exit loop if logging fails
        }

        // Sleep for 1 second
        gpioDelay(1000); // pigpio's replacement for time_sleep
    }

    // Cleanup
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL); // Disable ISR
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();

    printf("RPM monitoring stopped.\n");

    return 0;
}

