#include <unistd.h>

// Constants
#define I2C_ADDR 0x39
#define PART_ID_REG 0x00
#define FIFO_DATA_REG 0x04 // Example address, adjust based on datasheet
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t ir;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_gpio();
int read_part_id();
sensor_data_t read_sensor_data();
void control_led(int on);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x39, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output.\n", LED_GPIO);
        return -1;
    }
    return 0;
}

// Read PART_ID register
int read_part_id() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PART_ID_REG, buf, 2); // Read 2 bytes
    if (result < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", result);
        return -1;
    }
    uint16_t part_id = (buf[0] << 8) | buf[1];
    printf("PART_ID: 0x%04X\n", part_id);
    return part_id;
}

// Read sensor data (Red and IR)
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buf[4]; // Assuming 2 bytes for Red and 2 for IR
    int result = i2cReadI2CBlockData(i2c_handle, FIFO_DATA_REG, buf, 4);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        data.red = 0; // Set default values in case of error
        data.ir = 0;
        return data;
    }

    data.red = (buf[0] << 8) | buf[1];
    data.ir = (buf[2] << 8) | buf[3];

    return data;
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%u,%u\n", timestamp, data.red, data.ir);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Verify sensor presence
    if (read_part_id() != 0x1441) { // Replace with the expected PART_ID value
        fprintf(stderr, "Incorrect PART_ID, sensor not present.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();

        // Control LED based on IR threshold
        if (data.ir > IR_THRESHOLD) {
            control_led(1); // Turn on LED
        } else {
            control_led(0); // Turn off LED
        }

        // Log data
        log_data(data);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

