#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define AUDIO_PIN 17
#define GAIN_PIN 18
#define GAIN_LOW 0
#define GAIN_HIGH 1
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "audio_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GAIN_PIN, PI_OUTPUT);
    gpioWrite(GAIN_PIN, GAIN_LOW); // Set gain to 60dB

    gpioSetMode(AUDIO_PIN, PI_INPUT);
    gpioSetPullUpDown(AUDIO_PIN, PI_PUD_DOWN); // Optional: Set pull-down resistor

    return 0;
}

// Function to detect rising edge
int detect_rising_edge() {
    int current_value = gpioRead(AUDIO_PIN);
    gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 10ms
    int next_value = gpioRead(AUDIO_PIN);

    return (current_value == 0 && next_value == 1) ? 1 : 0;
}

// Function to log audio event
int log_audio_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s LEVEL 1\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Audio sampling started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (detect_rising_edge()) {
            if (log_audio_event() != 0) {
                fprintf(stderr, "Error logging audio event.\n");
            }
        }
    }

    // Clean up
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

