#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x36
#define START_MEASUREMENT_COMMAND 0x3608
#define FLOW_LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_flow_data(int16_t *raw_flow);
uint8_t calculate_crc8(const uint8_t *data, size_t length);
float convert_to_flow_rate(int16_t raw_flow);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Initialize the sensor
int initialize_sensor() {
    char command[2] = {(START_MEASUREMENT_COMMAND >> 8) & 0xFF, START_MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read flow data from the sensor
int read_flow_data(int16_t *raw_flow) {
    uint8_t buffer[3];
    int result = i2cReadDevice(i2c_handle, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *raw_flow = (int16_t)((buffer[0] << 8) | buffer[1]);

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw flow value to flow rate in uL/min
float convert_to_flow_rate(int16_t raw_flow) {
    return (float)raw_flow / 1000.0;
}

// Log flow rate to CSV file
int log_flow_rate(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f\n", timestamp, flow_rate);
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t raw_flow;
    float flow_rate;
    uint8_t crc;
    uint8_t data[2];

    while (!terminate) {
        // Read flow data
        if (read_flow_data(&raw_flow) == 0) {
            // Extract CRC byte
            data[0] = (raw_flow >> 8) & 0xFF;
            data[1] = raw_flow & 0xFF;
            crc = calculate_crc8(data, 2);

            // Validate CRC
            if (crc == (uint8_t)(raw_flow >> 16)) {
                // Convert to flow rate
                flow_rate = convert_to_flow_rate(raw_flow);

                // Log flow rate
                log_flow_rate(flow_rate);
            } else {
                fprintf(stderr, "CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read flow data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

