// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x70
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t tvoc;
    uint16_t eco2;
    float iaq;
} sensor_data_t;

// Function prototypes
int read_sensor_data(uint8_t *data);
sensor_data_t process_sensor_data(const uint8_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IAQ,TVOC,ECO2\n");
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 7);
    if (result < 0) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return 1;
    }
    return 0;
}

// Function to process sensor data
sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t sensor_data;

    // Extract TVOC (bytes 1-2, big-endian)
    sensor_data.tvoc = (uint16_t)((data[1] << 8) | data[2]);

    // Extract eCO2 (bytes 5-6, big-endian)
    sensor_data.eco2 = (uint16_t)((data[5] << 8) | data[6]);

    // Calculate IAQ index
    float tvoc_contribution = sensor_data.tvoc / 10.0;
    float eco2_contribution = (sensor_data.eco2 - 400) / 50.0;
    sensor_data.iaq = 100 - tvoc_contribution - eco2_contribution;

    // Clamp IAQ value between 0 and 100
    if (sensor_data.iaq < 0) sensor_data.iaq = 0;
    if (sensor_data.iaq > 100) sensor_data.iaq = 100;

    return sensor_data;
}

// Function to log data to file
int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%u,%u\n", timestamp, data->iaq, data->tvoc, data->eco2);
    fflush(log_file);

    return 0;
}

// Function to cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    uint8_t sensor_data[7];
    sensor_data_t processed_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data)) {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds...\n", READ_INTERVAL_SEC);
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        // Process sensor data
        processed_data = process_sensor_data(sensor_data);

        // Log data
        log_data(&processed_data);

        // Wait for the next interval
        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup
    cleanup();

    return 0;
}

