#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define CONSUMER "ttp223_tamper"
#define POLL_INTERVAL_NS 100000000 // 100 milliseconds
#define INTRUSION_THRESHOLD_S 5

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static time_t intrusion_start_time = 0;
static int intrusion_detected = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO line
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = CONSUMER;
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        return -1;
    }
    return value;
}

// Function to handle intrusion detection
void handle_intrusion() {
    if (intrusion_detected == 0) {
        time_t current_time = time(NULL);
        if (current_time - intrusion_start_time >= INTRUSION_THRESHOLD_S) {
            printf("Intrusion detected!\n");
            intrusion_detected = 1; // Set flag to prevent repeated alerts
        }
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    struct timespec sleep_time = {0, POLL_INTERVAL_NS};
    int sensor_value;

    fprintf(stderr, "Monitoring sensor... Press Ctrl+C to exit.\n");

    while (keep_running) {
        sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        if (sensor_value == 1) {
            if (intrusion_detected == 0) {
                intrusion_start_time = time(NULL);
            }
            handle_intrusion();
        } else {
            intrusion_detected = 0; // Reset intrusion flag
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup_gpio();
    fprintf(stderr, "Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

