#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define BITS_PER_SAMPLE 16
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define PCM_DEVICE "default"

snd_pcm_t *pcm_handle = NULL;
FILE *audio_file = NULL;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;

// Function to handle Ctrl+C signal
void signal_handler(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        if (pcm_handle) {
            snd_pcm_close(pcm_handle);
        }
        if (audio_file) {
            fclose(audio_file);
        }
        if (gpio_line) {
            gpiod_line_release(gpio_line);
        }
        if (gpio_chip) {
            gpiod_chip_close(gpio_chip);
        }
        exit(0);
    }
}

// Function to initialize GPIO
int initialize_gpio() {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "audio_capture", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output\n", GPIO_PIN);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to set GPIO pin value
void set_gpio_value(int value) {
    gpiod_line_set_value(gpio_line, value);
}

// Function to initialize ALSA
int initialize_alsa() {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(&pcm_handle, PCM_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device %s: %s\n", PCM_DEVICE, snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S32_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_rate(pcm_handle, hw_params, SAMPLE_RATE, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    return 0;
}

// Function to capture audio data
int capture_audio() {
    int err;
    char buffer[1024];
    int frames = 1024 / NUM_CHANNELS; // Number of frames to read
    int16_t *sample_ptr;
    int i;

    while (1) {
        err = snd_pcm_readi(pcm_handle, buffer, frames);
        if (err == -EPIPE) {
            /* EPIPE means overrun */
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Error reading PCM: %s\n", snd_strerror(err));
            return -1;
        } else if (err != frames) {
            fprintf(stderr, "Short read, read %d frames\n", err);
        } else {
            // Process and write data to file
            for (i = 0; i < frames; i++) {
                // Extract 24-bit data from 32-bit frame (left-justified)
                int32_t raw_sample = ((int32_t*)buffer)[i];
                int32_t left_justified = raw_sample >> 8; // Shift right by 8 bits

                // Right-shift to get 16-bit PCM sample
                int16_t pcm_sample = (int16_t)(left_justified >> 8); // Shift right by 8 bits

                // Write to file
                sample_ptr = (int16_t *)buffer;
                fwrite(&sample_ptr[i], sizeof(int16_t), 1, audio_file);
            }
        }
    }
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Set GPIO pin to select left channel
    set_gpio_value(1);

    // Initialize ALSA
    if (initialize_alsa() != 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Open audio file for writing
    audio_file = fopen("audio_capture.pcm", "wb");
    if (!audio_file) {
        fprintf(stderr, "Error opening audio file\n");
        snd_pcm_close(pcm_handle);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Capture audio data
    if (capture_audio() != 0) {
        fprintf(stderr, "Audio capture failed\n");
        fclose(audio_file);
        snd_pcm_close(pcm_handle);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Clean up resources (should not reach here in normal operation due to signal handler)
    fclose(audio_file);
    snd_pcm_close(pcm_handle);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

