#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Constants
#define FLAME_SENSOR_GPIO 4
#define FAN_GPIO 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_MS 50
#define FLAME_TIMEOUT_S 10
#define LOG_FILE "flame_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static time_t flame_start_time = 0;
static int flame_detected = 0;

// Function prototypes
void log_event(const char *message);
int initialize_gpio();
void cleanup_gpio();
void flame_detected_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to log events with ISO-8601 timestamp
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", buf, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 1000); // Set range to 1000 for percentage calculation

    log_event("System started");
    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    gpioPWM(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }

    log_event("System shutdown");
}

// Callback function for flame detection
void flame_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Flame detected (LOW signal)
        if (!flame_detected) {
            flame_detected = 1;
            flame_start_time = time(NULL);
            log_event("Flame detected");
        }
    } else if (level == 1) { // Flame ended (HIGH signal)
        if (flame_detected) {
            flame_detected = 0;
            time_t now = time(NULL);
            double flame_duration = difftime(now, flame_start_time);
            double duty_cycle = 0.0;

            // Exponential scaling of duty cycle
            if (flame_duration > 0) {
                duty_cycle = 0.8 * (1.0 - exp(-flame_duration / 5.0)); // Adjust the divisor for desired curve
                if (duty_cycle > 0.8) duty_cycle = 0.8; // Cap at 80%
            }

            int pwm_value = (int)(duty_cycle * 1000.0); // Convert to PWM value (0-1000)
            gpioPWM(FAN_GPIO, pwm_value);
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Flame ended, duration: %.2f seconds, duty cycle: %.2f, PWM: %d", flame_duration, duty_cycle, pwm_value);
            log_event(log_message);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Signal received, shutting down...");
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Set up callback function for flame sensor
    gpioSetAlertFuncEx(FLAME_SENSOR_GPIO, flame_detected_callback, NULL);

    // Main loop
    while (running) {
        if (flame_detected) {
            time_t now = time(NULL);
            if (difftime(now, flame_start_time) > FLAME_TIMEOUT_S) {
                log_event("Flame timeout: No flame detected for 10 seconds");
                flame_detected = 0;
                gpioPWM(FAN_GPIO, 0); // Turn off fan
            }
        }
        gpioDelay(10); // Check every 10ms
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

