        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Write log file header
int write_log_file_header(FILE *fp, radar_config_t config) {
    uint8_t header[64]; // Adjust size as needed
    uint32_t magic = MAGIC_NUMBER;
    memcpy(header, &magic, sizeof(magic));

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    memcpy(header + sizeof(magic), &ts.tv_sec, sizeof(ts.tv_sec));
    memcpy(header + sizeof(magic) + sizeof(ts.tv_sec), &ts.tv_nsec, sizeof(ts.tv_nsec));

    memcpy(header + sizeof(magic) + sizeof(ts.tv_sec) + sizeof(ts.tv_nsec), &config.start_frequency, sizeof(config.start_frequency));
    memcpy(header + sizeof(magic) + sizeof(ts.tv_sec) + sizeof(ts.tv_nsec) + sizeof(config.start_frequency), &config.end_frequency, sizeof(config.end_frequency));
    memcpy(header + sizeof(magic) + sizeof(ts.tv_sec) + sizeof(ts.tv_nsec) + sizeof(config.start_frequency) + sizeof(config.end_frequency), &config.chirps, sizeof(config.chirps));
    memcpy(header + sizeof(magic) + sizeof(ts.tv_sec) + sizeof(ts.tv_nsec) + sizeof(config.start_frequency) + sizeof(config.end_frequency) + sizeof(config.chirps), &config.samples, sizeof(config.samples));
    memcpy(header + sizeof(magic) + sizeof(ts.tv_sec) + sizeof(ts.tv_nsec) + sizeof(config.start_frequency) + sizeof(config.end_frequency) + sizeof(config.chirps) + sizeof(config.samples), &config.frame_period, sizeof(config.frame_period));

    if (fwrite(header, 1, sizeof(header), fp) != sizeof(header)) {
        fprintf(stderr, "Error writing header to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Assert trigger signal
int assert_trigger() {
    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioWrite(TRIGGER_GPIO, 1); // Assert trigger
    gpioDelay(100); // 100 us delay
    gpioWrite(TRIGGER_GPIO, 0); // De-assert trigger
    return 0;
}

// Wait for data-ready interrupt
int wait_for_data_ready() {
    gpioSetMode(DATA_READY_GPIO, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_GPIO, PI_PUD_DOWN); // Optional: Set pull-down resistor

    // Wait for the GPIO to go high
    int count = 0;
    while (gpioRead(DATA_READY_GPIO) == 0 && count < 1000) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        count++;
    }

    if (count >= 1000) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }
    return 0;
}

// Read heatmap data via SPI
int read_heatmap_data(uint8_t *data, int data_len) {
    char tx_buf[1] = {0}; // Dummy data for SPI transfer
    int bytes_read = spiXfer(spi_handle, tx_buf, (char *)data, data_len);
    if (bytes_read != data_len) {
        fprintf(stderr, "SPI transfer failed: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Write heatmap data to file
int write_heatmap_data_to_file(FILE *fp, uint8_t *data, int data_len, struct timespec ts) {
    uint32_t frame_num = frame_number++;
    if (fwrite(&frame_num, sizeof(frame_num), 1, fp) != 1) {
        fprintf(stderr, "Error writing frame number to file: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(&ts.tv_sec, sizeof(ts.tv_sec), 1, fp) != 1) {
        fprintf(stderr, "Error writing timestamp seconds to file: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(&ts.tv_nsec, sizeof(ts.tv_nsec), 1, fp) != 1) {
        fprintf(stderr, "Error writing timestamp nanoseconds to file: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(data, 1, data_len, fp) != data_len) {
        fprintf(stderr, "Error writing data to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open SPI channel
    if (open_spi_channel() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("radar_data.bin", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write log file header
    radar_config_t config = {
        .start_frequency = 77.0,
        .end_frequency = 79.0,
        .chirps = 64,
        .samples = 256,
        .frame_period = 0.1
    };

    if (write_log_file_header(log_file, config) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    uint8_t *data = (uint8_t *)malloc(FRAME_SIZE);
    if (data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup();
        return 1;
    }

    while (!terminate) {
        // Assert trigger
        if (assert_trigger() != 0) {
            break;
        }

        // Wait for data ready
        if (wait_for_data_ready() != 0) {
            break;
        }

        // Read heatmap data
        if (read_heatmap_data(data, FRAME_SIZE) != 0) {
            break;
        }

        // Get timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        // Write data to file
        if (write_heatmap_data_to_file(log_file, data, FRAME_SIZE, ts) != 0) {
            break;
        }
    }

    // Cleanup resources
    free(data);
    cleanup();

    return 0;
}

