#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 20
#define POLL_INTERVAL_NS 100000000 // 100 milliseconds in nanoseconds
#define LOG_FILE "flame_log.txt"

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
int log_message(const char *message) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        return -1; // Indicate failure
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the message is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        free(timestamp);
        return -1;
    }

    free(timestamp);
    return 0;
}

int main() {
    int prev_value = -1; // Initialize to an invalid value
    int current_value;
    int ret;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the GPIO line for input
    ret = gpiod_line_request_input(line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop to poll the sensor
    while (keep_running) {
        current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Check for state transition
        if (current_value != prev_value) {
            if (current_value == 0) {
                log_message("Flame Detected");
            } else {
                log_message("Flame Cleared");
            }
            prev_value = current_value;
        }

        // Sleep for the specified interval
        struct timespec sleep_time = {0, POLL_INTERVAL_NS};
        nanosleep(&sleep_time, NULL);
    }

    // Clean up resources before exiting
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

