#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define the GPIO pins connected to the TTP226 sensor channels
const int gpio_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int i, state;

    // Register the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure the GPIO pins as inputs
    for (i = 0; i < num_channels; i++) {
        gpioSetMode(gpio_pins[i], PI_INPUT);
    }

    // Main loop to read and log the sensor data
    while (!terminate) {
        for (i = 0; i < num_channels; i++) {
            // Read the state of the GPIO pin
            state = gpioRead(gpio_pins[i]);

            // Log the state to the console
            printf("Channel %d: %d\n", i + 1, state);
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

