#include <pigpio.h>

// Define the GPIO pins connected to the touch sensor channels
const int touch_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = sizeof(touch_pins) / sizeof(touch_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

int main() {
    int i, status;
    int sensor_values[8];
    int timestamp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure each GPIO pin as input with a pull-down resistor
    for (i = 0; i < num_channels; i++) {
        status = gpioSetMode(touch_pins[i], PI_INPUT);
        if (status != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input: %d\n", touch_pins[i], status);
            gpioTerminate();
            return 1;
        }

        status = gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN);
        if (status != 0) {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d: %d\n", touch_pins[i], status);
            gpioTerminate();
            return 1;
        }
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to read and log sensor data
    while (!terminate) {
        timestamp = gpioTick();

        // Read the state of each touch sensor channel
        for (i = 0; i < num_channels; i++) {
            sensor_values[i] = gpioRead(touch_pins[i]);
        }

        // Print the sensor data in the specified format
        printf("[%+6d ms] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               timestamp, sensor_values[0], sensor_values[1], sensor_values[2], sensor_values[3],
               sensor_values[4], sensor_values[5], sensor_values[6], sensor_values[7]);

        // Delay for 100 ms
        gpioDelay(100000);
    }

    // Terminate pigpio before exiting
    gpioTerminate();

    return 0;
}

