#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the 8 channels
const int gpio_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the state of all 8 channels
int read_sensor_data(int *data) {
    for (int i = 0; i < num_channels; i++) {
        data[i] = gpioRead(gpio_pins[i]);
        if (data[i] < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", gpio_pins[i]);
            return -1; // Indicate an error
        }
    }
    return 0; // Indicate success
}

// Function to format the sensor data into a CSV string
char* format_csv_data(int *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30]; // ISO-8601 timestamp format
    static char csv_string[100]; // Static buffer to hold the CSV string

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    snprintf(csv_string, sizeof(csv_string), "%s,%d,%d,%d,%d,%d,%d,%d,%d",
             timestamp, data[0], data[1], data[2], data[3], data[4], data[5], data[6], data[7]);

    return csv_string;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs
    for (int i = 0; i < num_channels; i++) {
        gpioSetMode(gpio_pins[i], PI_INPUT);
        gpioSetPullUpDown(gpio_pins[i], PI_PUD_OFF); // Disable pull-up/down resistors
    }

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    int sensor_data[num_channels];

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Format data into CSV string
            char *csv_data = format_csv_data(sensor_data);

            // Print CSV string to console
            printf("%s\n", csv_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Delay for 50 milliseconds
        gpioDelay(50);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

