#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_KEY_REG 0x07
#define CHLIST_REG 0x08
#define ALS_FORCE_REG 0x0A
#define UV_INDEX_REG 0x2C
#define ALS_VIS_REG 0x22

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(float *uv_index, int *als_visible);
int log_data(float uv_index, int als_visible);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    // Verify PART ID
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART ID: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    // Write HW_KEY
    if (i2cWriteByteData(i2c_handle, HW_KEY_REG, 0x17) < 0) {
        fprintf(stderr, "Error writing HW_KEY: %s\n", strerror(errno));
        return -1;
    }

    // Configure CHLIST
    if (i2cWriteByteData(i2c_handle, CHLIST_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing CHLIST: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read UV index and Visible ALS data
int read_sensor_data(float *uv_index, int *als_visible) {
    // Trigger measurement
    if (i2cWriteByteData(i2c_handle, ALS_FORCE_REG, 0x01) < 0) {
        fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
        return -1;
    }

    // Read UV index
    int uv = i2cReadByteData(i2c_handle, UV_INDEX_REG);
    if (uv < 0) {
        fprintf(stderr, "Error reading UV index: %s\n", strerror(errno));
        return -1;
    }
    *uv_index = (float)uv / 10.0; // Convert to UV index

    // Read Visible ALS
    int als_vis = i2cReadWordData(i2c_handle, ALS_VIS_REG);
    if (als_vis < 0) {
        fprintf(stderr, "Error reading Visible ALS: %s\n", strerror(errno));
        return -1;
    }
    *als_visible = als_vis;

    return 0;
}

// Function to log data to a CSV file
int log_data(float uv_index, int als_visible) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float uv_index;
    int als_visible;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&uv_index, &als_visible) == 0) {
            printf("UV Index: %.2f, Visible ALS: %d\n", uv_index, als_visible);
            log_data(uv_index, als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

