#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define ALARM_GPIO 17
#define SCALE_FACTOR 0.036
#define ALARM_THRESHOLD 0.5
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, int *flow, int *temperature);
uint8_t crc8(const uint8_t *data, size_t len);
float convert_flow(int raw_flow);
float calculate_average_flow(float flow1, float flow2);
void log_data(float flow1, float flow2, float average_flow);
void control_alarm(float average_flow);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize sensor
int init_sensor(int i2c_handle) {
    char buf[2];
    buf[0] = 0x36;
    buf[1] = 0x08;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to send start measurement command.\n");
        return -1;
    }
    gpioDelay(100); // Wait 100ms
    return 0;
}

// Read sensor data
int read_sensor_data(int i2c_handle, int *flow, int *temperature) {
    char buf[9];
    if (i2cReadDevice(i2c_handle, buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read sensor data.\n");
        return -1;
    }

    // Extract raw values
    int16_t raw_flow = (buf[0] << 8) | buf[1];
    int16_t raw_temperature = (buf[3] << 8) | buf[4];

    // CRC check for flow
    uint8_t crc_flow = buf[2];
    uint8_t crc_calculated_flow = crc8((uint8_t *)buf, 2);
    if (crc_flow != crc_calculated_flow) {
        fprintf(stderr, "Error: CRC check failed for flow.\n");
        return -1;
    }

    // CRC check for temperature
    uint8_t crc_temperature = buf[5];
    uint8_t crc_calculated_temperature = crc8((uint8_t *)buf + 3, 2);
    if (crc_temperature != crc_calculated_temperature) {
        fprintf(stderr, "Error: CRC check failed for temperature.\n");
        return -1;
    }

    *flow = raw_flow;
    *temperature = raw_temperature;
    return 0;
}

// CRC8 calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw flow to ml/min
float convert_flow(int raw_flow) {
    return (float)raw_flow * SCALE_FACTOR;
}

// Calculate average flow
float calculate_average_flow(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// Log data to file
void log_data(float flow1, float flow2, float average_flow) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Flow1: %.2f ml/min, Flow2: %.2f ml/min, Average: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            flow1, flow2, average_flow);
    fflush(log_file);
}

// Control alarm
void control_alarm(float average_flow) {
    if (average_flow < ALARM_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // High
    } else {
        gpioWrite(ALARM_GPIO, 0); // Low
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C devices
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error: Could not open I2C device for sensor 1.\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error: Could not open I2C device for sensor 2.\n");
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (init_sensor(i2c_handle1) != 0) {
        fprintf(stderr, "Error: Failed to initialize sensor 1.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Error: Failed to initialize sensor 2.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int flow1, temperature1, flow2, temperature2;
    float flow_rate1, flow_rate2, average_flow;

    // Main loop
    while (!terminate) {
        // Read sensor 1
        if (read_sensor_data(i2c_handle1, &flow1, &temperature1) == 0) {
            flow_rate1 = convert_flow(flow1);
        } else {
            flow_rate1 = -1.0; // Indicate error
        }

        // Read sensor 2
        if (read_sensor_data(i2c_handle2, &flow2, &temperature2) == 0) {
            flow_rate2 = convert_flow(flow2);
        } else {
            flow_rate2 = -1.0; // Indicate error
        }

        // Calculate average flow
        if (flow_rate1 >= 0.0 && flow_rate2 >= 0.0) {
            average_flow = calculate_average_flow(flow_rate1, flow_rate2);
        } else {
            average_flow = -1.0; // Indicate error
        }

        // Log data
        if (flow_rate1 >= 0.0 && flow_rate2 >= 0.0 && average_flow >= 0.0) {
            log_data(flow_rate1, flow_rate2, average_flow);
        }

        // Control alarm
        if (average_flow >= 0.0) {
            control_alarm(average_flow);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioWrite(ALARM_GPIO, 0); // Set alarm low on exit
    gpioTerminate();

    return 0;
}

