#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <math.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define D7S_ADDRESS 0x55
#define MODE_CONTROL 0x1D
#define OPERATING_STATUS 0x1B
#define ACCEL_X_LSB 0x2A
#define ACCEL_X_MSB 0x2B
#define ACCEL_Y_LSB 0x2C
#define ACCEL_Y_MSB 0x2D
#define ACCEL_Z_LSB 0x2E
#define ACCEL_Z_MSB 0x2F
#define SCALING_FACTOR 0.0009765625
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *csv_file = NULL;

// Structure to hold sensor data
typedef struct {
    double x;
    double y;
    double z;
} sensor_data_t;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value);
int i2c_read_word(int fd, uint8_t reg, int16_t *value);
int i2c_init(int fd);
int d7s_init(int fd);
sensor_data_t read_sensor_data(int fd);
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size);
int log_data(FILE *fp, const char *timestamp, double x, double y, double z);
void signal_handler(int sig);

// I2C write function with retry
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        if (write(fd, &value, 1) != 1) {
            fprintf(stderr, "Error writing value: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        result = 0; // Success
        break;
    }

    return result;
}

// I2C read function with retry
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        if (read(fd, value, 1) != 1) {
            fprintf(stderr, "Error reading value: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        result = 0; // Success
        break;
    }

    return result;
}

// I2C read word function with retry
int i2c_read_word(int fd, uint8_t reg, int16_t *value) {
    int retries = 0;
    int result = -1;
    uint8_t buffer[2];

    while (retries < MAX_RETRIES) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error writing register address for word read: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        if (read(fd, buffer, 2) != 2) {
            fprintf(stderr, "Error reading word: %s\n", strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        *value = (int16_t)((buffer[1] << 8) | buffer[0]); // Little-endian
        result = 0; // Success
        break;
    }

    return result;
}

// I2C initialization function
int i2c_init(int fd) {
    if (ioctl(fd, I2C_SLAVE, D7S_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// D7S initialization function
int d7s_init(int fd) {
    int status = 0;
    int retries = 0;

    // Set MODE_CONTROL to 0x10
    if (i2c_write_byte(fd, MODE_CONTROL, 0x10) != 0) {
        fprintf(stderr, "Error writing to MODE_CONTROL\n");
        return -1;
    }

    // Wait for operating status to be active (bit 0 of 0x1B is 1)
    while (retries < 10) {
        uint8_t operating_status;
        if (i2c_read_byte(fd, OPERATING_STATUS, &operating_status) == 0) {
            if (operating_status & 0x01) {
                return 0; // Success
            }
        } else {
            fprintf(stderr, "Error reading operating status\n");
        }
        usleep(100000); // 100ms
        retries++;
    }

    fprintf(stderr, "D7S did not become active within 1 second\n");
    return -1;
}

// Function to read sensor data
sensor_data_t read_sensor_data(int fd) {
    sensor_data_t data;
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_word(fd, ACCEL_X_LSB, &raw_x) != 0) {
        fprintf(stderr, "Error reading X acceleration\n");
        data.x = 0.0; // Indicate error
    } else {
        data.x = (double)raw_x * SCALING_FACTOR;
    }

    if (i2c_read_word(fd, ACCEL_Y_LSB, &raw_y) != 0) {
        fprintf(stderr, "Error reading Y acceleration\n");
        data.y = 0.0; // Indicate error
    } else {
        data.y = (double)raw_y * SCALING_FACTOR;
    }

    if (i2c_read_word(fd, ACCEL_Z_LSB, &raw_z) != 0) {
        fprintf(stderr, "Error reading Z acceleration\n");
        data.z = 0.0; // Indicate error
    } else {
        data.z = (double)raw_z * SCALING_FACTOR;
    }

    return data;
}

// Function to get ISO-8601 timestamp
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_str;
}

// Function to log data to CSV file
int log_data(FILE *fp, const char *timestamp, double x, double y, double z) {
    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    keep_running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (i2c_init(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize D7S sensor
    if (d7s_init(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Open CSV file in append mode
    csv_file = fopen("fan_health.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,x,y,z\n");
    }
    rewind(csv_file);

    // Main loop
    char timestamp_str[32];
    sensor_data_t sensor_data;

    while (keep_running) {
        // Read sensor data
        sensor_data = read_sensor_data(i2c_fd);

        // Get timestamp
        get_iso8601_timestamp(timestamp_str, sizeof(timestamp_str));

        // Log data to CSV file
        if (log_data(csv_file, timestamp_str, sensor_data.x, sensor_data.y, sensor_data.z) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Close I2C device and CSV file
    close(i2c_fd);
    fclose(csv_file);

    return 0;
}

