#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18

// Define the stall log file name
#define STALL_LOG_FILE "stall_log.txt"

// Define the stall duration threshold (in seconds)
#define STALL_DURATION 2

// Global variable to track the program's running state
volatile sig_atomic_t running = 1;

// Function prototypes
int read_sensor(int gpio);
int is_stalled(int sensor1_value, int sensor2_value);
void log_stall(const char *timestamp);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid sensor reading from GPIO %d\n", gpio);
        return -1; // Indicate an error
    }
    return value;
}

// Function to determine if a stall has occurred
int is_stalled(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
}

// Function to log a stall event to the log file
void log_stall(const char *timestamp) {
    FILE *fp = fopen(STALL_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", STALL_LOG_FILE);
        return;
    }

    // Check if the file is empty. If so, write the header.
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Stall Detected\n");
    }

    fprintf(fp, "%s,Stall Detected\n", timestamp);
    fclose(fp);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Conveyor belt monitoring system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            // Handle sensor read error (e.g., retry or exit)
            fprintf(stderr, "Error reading sensors, exiting.\n");
            break;
        }

        // Check for stall condition
        if (is_stalled(sensor1_value, sensor2_value)) {
            // Stall detected, wait for the specified duration
            time_t start_time = time(NULL);
            while (is_stalled(read_sensor(SENSOR_1_GPIO), read_sensor(SENSOR_2_GPIO))) {
                if (time(NULL) - start_time >= STALL_DURATION) {
                    // Stall duration exceeded, log the event
                    time_t now = time(NULL);
                    struct tm *tstruct = localtime(&now);
                    char timestamp[80];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

                    log_stall(timestamp);
                    printf("Stall detected and logged at %s\n", timestamp);
                    break; // Exit the stall detection loop
                }
                gpioDelay(100); // Check every 100ms
            }
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

