#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define TMAG5170_ADDR 0x0E
#define DEVICE_ID_REG 0x00
#define DEVICE_ID_VALUE 0x8D
#define CONFIG_REG 0x0B
#define X_REG 0x01
#define Y_REG 0x03
#define Z_REG 0x05
#define CSV_FILE "magnetic_log.csv"
#define SLEEP_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Get ISO-8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp.\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Initialize the sensor
int initialize_sensor() {
    // Verify device ID
    int device_id = i2cReadByteData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error: Failed to read device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != DEVICE_ID_VALUE) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%02X (expected 0x%02X)\n", device_id, DEVICE_ID_VALUE);
        return -1;
    }

    // Configure sensor for continuous conversion mode, all axes enabled, 50 mT range
    int config_result = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00); // Continuous mode, all axes enabled
    if (config_result < 0) {
        fprintf(stderr, "Error: Failed to write configuration: %d\n", config_result);
        return -1;
    }

    return 0;
}

// Read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int16_t raw_x, raw_y, raw_z;

    // Read X axis data
    raw_x = i2cReadWordData(i2c_handle, X_REG);
    if (raw_x < 0) {
        fprintf(stderr, "Error: Failed to read X data: %d\n", raw_x);
        data.x = 0.0; // Set to 0.0 to avoid using uninitialized value
    } else {
        data.x = (float)raw_x * 0.08; // Convert to mT
    }

    // Read Y axis data
    raw_y = i2cReadWordData(i2c_handle, Y_REG);
    if (raw_y < 0) {
        fprintf(stderr, "Error: Failed to read Y data: %d\n", raw_y);
        data.y = 0.0;
    } else {
        data.y = (float)raw_y * 0.08; // Convert to mT
    }

    // Read Z axis data
    raw_z = i2cReadWordData(i2c_handle, Z_REG);
    if (raw_z < 0) {
        fprintf(stderr, "Error: Failed to read Z data: %d\n", raw_z);
        data.z = 0.0;
    } else {
        data.z = (float)raw_z * 0.08; // Convert to mT
    }

    return data;
}

// Log data to CSV file
void log_data(sensor_data_t data) {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to get timestamp.\n");
        return;
    }

    // Check if the file is newly created and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk
    free(timestamp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        gpioDelay(SLEEP_MS * 1000); // Sleep for 100 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

