#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to read the water level sensor
int read_water_level() {
    return gpioRead(GPIO_PIN);
}

// Function to log an alert message to the log file
void log_alert(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    fprintf(fp, "%s ALERT: Water detected\n", timestamp);
    fclose(fp);
}

// Function to get the current timestamp in the format YYYY-MM-DD HH:MM:SS
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    char timestamp[20];
    int pigpio_initialized = 1; // Flag to track pigpio initialization status

    while (running) {
        if (pigpio_initialized) {
            int water_level = read_water_level();

            if (water_level == 1) {
                get_timestamp(timestamp);
                printf("%s ALERT: Water detected\n", timestamp);
                log_alert(timestamp);
            } else if (water_level < 0) {
                fprintf(stderr, "Error reading GPIO pin\n");
                get_timestamp(timestamp);
                FILE *fp = fopen(LOG_FILE, "a");
                if (fp != NULL) {
                    fprintf(fp, "%s ERROR: Failed to read GPIO pin\n", timestamp);
                    fclose(fp);
                }
                gpioTerminate();
                pigpio_initialized = 0; // Set flag to false
                fprintf(stderr, "Attempting to re-initialize pigpio in 60 seconds...\n");
                sleep(60);
                if (initialize_pigpio() == 0) {
                    gpioSetMode(GPIO_PIN, PI_INPUT);
                    pigpio_initialized = 1; // Set flag to true after successful re-initialization
                    printf("pigpio re-initialized successfully.\n");
                } else {
                    fprintf(stderr, "Failed to re-initialize pigpio.\n");
                }
            }
        } else {
            // pigpio is not initialized, wait before retrying
            sleep(5); // Wait 5 seconds before retrying initialization
            if (initialize_pigpio() == 0) {
                gpioSetMode(GPIO_PIN, PI_INPUT);
                pigpio_initialized = 1; // Set flag to true after successful re-initialization
                printf("pigpio re-initialized successfully.\n");
            } else {
                fprintf(stderr, "Failed to re-initialize pigpio.\n");
            }
        }

        gpioDelay(2000); // Poll every 2 seconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

