#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Mutex for protecting pulse_count
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
int initialize_gpio();
void cleanup();
void log_rpm(int rpm);

// Interrupt callback function
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
}

// Log RPM to file and stdout
void log_rpm(int rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    char log_message[100];
    snprintf(log_message, sizeof(log_message), "%s %d\n", timestamp, rpm);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        perror("fopen");
        return;
    }

    if (fprintf(log_file, "%s", log_message) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        perror("fprintf");
    }

    fflush(log_file); // Ensure data is written to disk
    printf("%s", log_message);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    while (running) {
        // Reset pulse count
        pthread_mutex_lock(&pulse_mutex);
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds

        // Calculate RPM
        int rpm = pulse_count * 60;

        // Log RPM
        log_rpm(rpm);
    }

    cleanup();
    return 0;
}

