#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the number of states in the quadrature state machine
#define NUM_STATES 4

// Structure to hold the current state of the quadrature encoder
typedef struct {
    int state;
    pthread_mutex_t mutex;
} QuadratureState;

// Global variables
QuadratureState quadrature_state;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data);
void log_rotation(const char *direction);
void initialize_quadrature_state(QuadratureState *state);
int get_next_state(int current_state, int sensor_a_value, int sensor_b_value);
const char *determine_direction(int current_state, int next_state);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Interrupt service routine for Sensor A
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data) {
    int sensor_b_value = gpioRead(SENSOR_B_PIN);
    pthread_mutex_lock(&quadrature_state.mutex);
    int current_state = quadrature_state.state;
    int next_state = get_next_state(current_state, level, sensor_b_value);
    const char *direction = determine_direction(current_state, next_state);
    quadrature_state.state = next_state;
    pthread_mutex_unlock(&quadrature_state.mutex);
    log_rotation(direction);
}

// Interrupt service routine for Sensor B
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data) {
    int sensor_a_value = gpioRead(SENSOR_A_PIN);
    pthread_mutex_lock(&quadrature_state.mutex);
    int current_state = quadrature_state.state;
    int next_state = get_next_state(current_state, sensor_a_value, level);
    const char *direction = determine_direction(current_state, next_state);
    quadrature_state.state = next_state;
    pthread_mutex_unlock(&quadrature_state.mutex);
    log_rotation(direction);
}

// Function to log the rotation direction to a file
void log_rotation(const char *direction) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    struct tm *tm_info = localtime(&ts.tv_sec);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(timestamp + strlen(timestamp), 10, ".%03ld", ts.tv_nsec / 1000000);

    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", timestamp, direction);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to initialize the quadrature state
void initialize_quadrature_state(QuadratureState *state) {
    state->state = 0; // Initial state
    if (pthread_mutex_init(&state->mutex, NULL) != 0) {
        fprintf(stderr, "Error: Failed to initialize mutex.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to get the next state based on the current state and sensor values
int get_next_state(int current_state, int sensor_a_value, int sensor_b_value) {
    int next_state = -1; // Invalid state

    switch (current_state) {
        case 0:
            if (sensor_a_value == 1 && sensor_b_value == 0) next_state = 1;
            if (sensor_a_value == 0 && sensor_b_value == 1) next_state = 3;
            break;
        case 1:
            if (sensor_a_value == 1 && sensor_b_value == 1) next_state = 2;
            if (sensor_a_value == 0 && sensor_b_value == 0) next_state = 0;
            break;
        case 2:
            if (sensor_a_value == 0 && sensor_b_value == 1) next_state = 3;
            if (sensor_a_value == 1 && sensor_b_value == 0) next_state = 1;
            break;
        case 3:
            if (sensor_a_value == 0 && sensor_b_value == 0) next_state = 0;
            if (sensor_a_value == 1 && sensor_b_value == 1) next_state = 2;
            break;
    }

    return next_state;
}

// Function to determine the direction of rotation based on the current and next state
