#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *touch_line = NULL;
struct gpiod_line *led_line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler function
void signal_handler(int sig);

// Function to read the touch sensor state
int read_touch_sensor(struct gpiod_line *line);

// Function to control the LED state
void control_led(struct gpiod_line *line, int state);

// Function to log events to syslog
void log_event(const char *message);

int main() {
    // Open syslog
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_event("Error: Failed to open GPIO chip.");
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", GPIO_CHIP);
        return 1;
    }

    // Request GPIO line for touch sensor
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        log_event("Error: Failed to get touch sensor GPIO line.");
        syslog(LOG_ERR, "Failed to get touch sensor GPIO line: %d", TOUCH_SENSOR_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for LED
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        log_event("Error: Failed to get LED GPIO line.");
        syslog(LOG_ERR, "Failed to get LED GPIO line: %d", LED_PIN);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request touch sensor line as input
    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        log_event("Error: Failed to request touch sensor line as input.");
        syslog(LOG_ERR, "Failed to request touch sensor line as input");
        gpiod_line_release(led_line);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request LED line as output
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        log_event("Error: Failed to request LED line as output.");
        syslog(LOG_ERR, "Failed to request LED line as output");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_event("Program started successfully.");

    // Main loop
    while (1) {
        // Read touch sensor state
        int touch_state = read_touch_sensor(touch_line);

        // Control LED based on touch sensor state
        control_led(led_line, touch_state);

        // Wait for 50ms
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 50000000; // 50ms
        nanosleep(&delay, NULL);
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    log_event("Signal received, shutting down...");

    // Release GPIO lines
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close syslog
    closelog();

    exit(0);
}

// Function to read the touch sensor state
int read_touch_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        log_event("Error: Failed to read touch sensor value.");
        syslog(LOG_ERR, "Failed to read touch sensor value");
        return 0; // Return 0 on error to avoid unexpected behavior
    }
    return value;
}

// Function to control the LED state
void control_led(struct gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        log_event("Error: Failed to set LED value.");
        syslog(LOG_ERR, "Failed to set LED value");
    }
}

// Function to log events to syslog
void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

