#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *touch_line;
struct gpiod_line *led_line;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    terminate = 1;
}

// Function to initialize GPIO lines
int initialize_gpio()
{
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip.\n");
        return -1;
    }

    // Get touch sensor line
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Error: Could not get touch sensor line.\n");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error: Could not get LED line.\n");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request touch sensor line for input with rising edge event
    if (gpiod_line_request_rising_edge_events(touch_line, "touch_sensor") < 0) {
        fprintf(stderr, "Error: Could not request touch sensor line for rising edge events.\n");
        gpiod_line_release(led_line);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request LED line for output
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error: Could not request LED line for output.\n");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to toggle the LED state
void toggle_led()
{
    int value = gpiod_line_get_value(led_line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get LED value.\n");
        return;
    }
    if (gpiod_line_set_value(led_line, !value) < 0) {
        fprintf(stderr, "Error: Could not set LED value.\n");
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio()
{
    fprintf(stderr, "Cleaning up GPIO resources.\n");
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "Error: GPIO initialization failed.\n");
        return 1;
    }

    // Drive LED LOW at startup
    if (gpiod_line_set_value(led_line, 0) < 0) {
        fprintf(stderr, "Error: Could not set initial LED value.\n");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (!terminate) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(touch_line, DEBOUNCE_TIME_MS * 1000); // Debounce time in microseconds

        if (ret < 0) {
            fprintf(stderr, "Error: Event wait failed.\n");
            break;
        }

        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "Error: Event read failed.\n");
            break;
        }

        // Toggle the LED
        toggle_led();
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

