    // Drive LED LOW at startup
    if (gpiod_line_set_value(led_line, 0) < 0) {
        fprintf(stderr, "Error: Could not set initial LED value.\n");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (!terminate) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(touch_line, DEBOUNCE_TIME_MS * 1000); // Debounce time in microseconds

        if (ret < 0) {
            fprintf(stderr, "Error: Event wait failed.\n");
            break;
        }

        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "Error: Event read failed.\n");
            break;
        }

        // Toggle the LED
        toggle_led();
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

