#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define buffer size
#define BUFFER_SIZE 100

// Structure to store log entries
typedef struct {
    int sensor_pin;
    long timestamp;
    int state;
} LogEntry;

// Circular buffer
LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;
int overflow_count = 0;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void log_event(int sensor_pin, int state);
void print_log_buffer();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor_1_value = gpioRead(SENSOR_1_PIN);
        int sensor_2_value = gpioRead(SENSOR_2_PIN);

        // Control LEDs based on sensor values
        gpioWrite(LED_1_PIN, sensor_1_value);
        gpioWrite(LED_2_PIN, sensor_2_value);

        // Log events
        log_event(SENSOR_1_PIN, sensor_1_value);
        log_event(SENSOR_2_PIN, sensor_2_value);

        // Delay for debouncing
        gpioDelay(50000); // 50 ms
    }

    // Cleanup and exit
    cleanup_gpio();
    print_log_buffer();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_2_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_2_PIN\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio() {
    // Turn off LEDs
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);

    // Terminate pigpio
    gpioTerminate();
}

// Log an event to the circular buffer
void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    log_buffer[buffer_index].sensor_pin = sensor_pin;
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].state = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) {
        overflow_count++;
    }
}

// Print the contents of the log buffer
void print_log_buffer() {
    printf("Log Buffer Contents:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Correct order
        printf("Entry %d: Sensor Pin = %d, Timestamp = %ld, State = %d\n",
               i, log_buffer[index].sensor_pin, log_buffer[index].timestamp, log_buffer[index].state);
    }
    printf("Overflow Count: %d\n", overflow_count);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

