#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Global variables
volatile int running = 1;
FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function prototypes
int initialize_gpio();
SensorStates read_sensors();
double calculate_rpm(SensorStates current_states, SensorStates previous_states, double time_diff);
void log_data(SensorStates states);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    return 0; // Indicate success
}

// Function to read the states of the Hall-Effect sensors
SensorStates read_sensors() {
    SensorStates states;
    states.sensor1_state = gpioRead(SENSOR1_GPIO);
    states.sensor2_state = gpioRead(SENSOR2_GPIO);
    return states;
}

// Function to calculate the RPM based on sensor state changes
double calculate_rpm(SensorStates current_states, SensorStates previous_states, double time_diff) {
    int pulse_count = 0;

    if (current_states.sensor1_state != previous_states.sensor1_state) {
        pulse_count++;
    }
    if (current_states.sensor2_state != previous_states.sensor2_state) {
        pulse_count++;
    }

    // Assuming 2 pulses per revolution
    return (double)pulse_count / 2.0 / time_diff * 60.0; // RPM
}

// Function to log the timestamp and sensor states to a CSV file
void log_data(SensorStates states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, states.sensor1_state, states.sensor2_state);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Signal handler for Ctrl+C (SIGINT)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    SensorStates previous_states = read_sensors();
    time_t start_time = time(NULL);

    printf("RPM Monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        SensorStates current_states = read_sensors();
        time_t current_time = time(NULL);
        double time_diff = difftime(current_time, start_time);

        double rpm = calculate_rpm(current_states, previous_states, time_diff);

        printf("RPM: %.2f\n", rpm);

        log_data(current_states);

        previous_states = current_states;
        start_time = current_time;

        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay (microseconds)
    }

    cleanup();
    return 0;
}

