#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *heart_rate, int *spo2);
int log_data(int heart_rate, int spo2);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the Si1182 sensor
int initialize_sensor() {
    // Verify sensor presence
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure sensor for continuous measurement
    int config_result = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x01); // Example configuration
    if (config_result < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Reads heart rate and SpO2 data from the sensor
int read_sensor_data(int *heart_rate, int *spo2) {
    int hr = i2cReadByteData(i2c_handle, HEART_RATE_REG);
    if (hr < 0) {
        fprintf(stderr, "Error reading HEART_RATE register: %s\n", strerror(errno));
        return -1;
    }

    int sp = i2cReadByteData(i2c_handle, SPO2_REG);
    if (sp < 0) {
        fprintf(stderr, "Error reading SPO2 register: %s\n", strerror(errno));
        return -1;
    }

    *heart_rate = hr;
    *spo2 = sp;

    return 0;
}

// Logs the data to a file
int log_data(int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file);

    return 0;
}

