#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define constants
#define THRESHOLD_DURATION 2.0 // seconds
#define POLL_INTERVAL 0.1      // seconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int check_threshold(int gpio_pin, double duration);
void activate_alarm();
void deactivate_alarm();
void log_event(const char *event_type, int gpio_pin);
void signal_handler(int signal);

// Structure to hold sensor state and timestamp
typedef struct {
    int gpio_pin;
    double start_time;
    int tilted;
} sensor_state_t;

sensor_state_t sensor1_state = {SENSOR_1_PIN, 0.0, 0};
sensor_state_t sensor2_state = {SENSOR_2_PIN, 0.0, 0};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values. Continuing.\n");
            gpioDelay(POLL_INTERVAL * 1000000); // Delay in microseconds
            continue;
        }

        // Check threshold for sensor 1
        if (sensor1_value == 1 && !sensor1_state.tilted) {
            sensor1_state.start_time = time_time();
            sensor1_state.tilted = 1;
        } else if (sensor1_state.tilted) {
            if (check_threshold(SENSOR_1_PIN, THRESHOLD_DURATION)) {
                log_event("THRESHOLD_EXCEEDED", SENSOR_1_PIN);
                activate_alarm();
            }
        } else {
            sensor1_state.tilted = 0;
        }

        // Check threshold for sensor 2
        if (sensor2_value == 1 && !sensor2_state.tilted) {
            sensor2_state.start_time = time_time();
            sensor2_state.tilted = 1;
        } else if (sensor2_state.tilted) {
            if (check_threshold(SENSOR_2_PIN, THRESHOLD_DURATION)) {
                log_event("THRESHOLD_EXCEEDED", SENSOR_2_PIN);
                activate_alarm();
            }
        } else {
            sensor2_state.tilted = 0;
        }

        // Deactivate alarm if both sensors are LOW
        if (sensor1_value == 0 && sensor2_value == 0 && gpioRead(ALARM_PIN) == 1) {
            deactivate_alarm();
        }

        // Delay
        gpioDelay(POLL_INTERVAL * 1000000); // Delay in microseconds
    }

    // Clean up
    deactivate_alarm();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);

    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Initialize alarm to LOW

    return 0;
}

// Read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return value;
}

// Check if sensor has been HIGH for the specified duration
int check_threshold(int gpio_pin, double duration) {
    double current_time = time_time();
    if (current_time - sensor1_state.start_time >= duration) {
        return 1;
    } else if (current_time - sensor2_state.start_time >= duration) {
        return 1;
    } else {
        return 0;
    }
}

// Activate the alarm
void activate_alarm() {
    gpioWrite(ALARM_PIN, 1);
}

// Deactivate the alarm
void deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0);
}

// Log an event to the log file
void log_event(const char *event_type, int gpio_pin) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s - %s - GPIO %d\n", timestamp, event_type, gpio_pin);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

