    }

    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Reads the 3-axis acceleration data from the sensor.
int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int retries = 3;
    while (retries > 0) {
        int bytes_read = i2cReadI2CBlockData(i2c_handle, ACCEL_X_LSB, buffer, 6);
        if (bytes_read != 6) {
            fprintf(stderr, "Error reading acceleration data: %d\n", bytes_read);
            gpioDelay(100); // Wait before retrying
            retries--;
            continue;
        }

        // Convert little-endian data to signed 16-bit integers
        int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
        int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
        int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

        // Scale raw values to g-force units (adjust scaling factor as needed)
        *x = (float)x_raw / 1000.0; // Example scaling
        *y = (float)y_raw / 1000.0;
        *z = (float)z_raw / 1000.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read acceleration data after multiple retries.\n");
    return -1; // Failure
}

// Calculates the Euclidean magnitude of the acceleration vector.
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Logs the event to the seismic_events.log file.
void log_event(float magnitude) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    fprintf(log_file, "%s, Magnitude: %.2f\n", buf, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Controls the LED on GPIO 17.
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > THRESHOLD) {
                printf("Threshold exceeded! Magnitude: %.2f\n", magnitude);
                log_event(magnitude);
                control_led(1); // Turn LED on
                gpioDelay(1000);  // Wait for 1 second
                control_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        gpioDelay(SAMPLE_RATE_MS); // Wait 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

