    gpioWrite(gpio_pin, state);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs or output
    gpioSetMode(SENSOR_1, PI_INPUT);
    gpioSetMode(SENSOR_2, PI_INPUT);
    gpioSetMode(SENSOR_3, PI_INPUT);
    gpioSetMode(SENSOR_4, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1);
        int sensor2_value = read_sensor(SENSOR_2);
        int sensor3_value = read_sensor(SENSOR_3);
        int sensor4_value = read_sensor(SENSOR_4);

        // Check if any sensor detects an object (active low)
        if (sensor1_value == 0 || sensor2_value == 0 || sensor3_value == 0 || sensor4_value == 0) {
            // Turn on the LED
