        } else {
            // Turn off the LED
            control_led(LED_PIN, 0);
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // 50 ms = 50000 us
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");
    return 0;
}

