#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the flame sensors
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_27 27

// Number of sensors
#define NUM_SENSORS 5

// Debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Log file path
#define LOG_FILE "/var/log/flame_events.log"

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    int sensor_id;
    struct gpiod_line *line;
    int flame_detected;
} sensor_data_t;

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static sensor_data_t sensors[NUM_SENSORS];

// Function prototypes
void signal_handler(int sig);
int setup_gpio(struct gpiod_chip **chip, sensor_data_t *sensors);
int read_sensor(struct gpiod_line *line);
int debounce(struct gpiod_line *line);
int log_event(int sensor_id, int gpio_pin);
void cleanup(struct gpiod_chip *chip, sensor_data_t *sensors);

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_USER | LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Setup GPIO pins
int setup_gpio(struct gpiod_chip **chip, sensor_data_t *sensors) {
    int i;
    int pins[NUM_SENSORS] = {GPIO_2, GPIO_3, GPIO_4, GPIO_17, GPIO_27};

    // Open GPIO chip
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        syslog(LOG_USER | LOG_ERR, "Error opening GPIO chip: %s", strerror(errno));
        return -1;
    }

    // Request and configure each GPIO line
    for (i = 0; i < NUM_SENSORS; i++) {
        sensors[i].gpio_pin = pins[i];
        sensors[i].sensor_id = i + 1;
        sensors[i].line = gpiod_chip_get_line(*chip, sensors[i].gpio_pin);
        if (!sensors[i].line) {
            syslog(LOG_USER | LOG_ERR, "Error getting line %d: %s", sensors[i].gpio_pin, strerror(errno));
            return -1;
        }

        if (gpiod_line_request_input(sensors[i].line, "flame_monitor") < 0) {
            syslog(LOG_USER | LOG_ERR, "Error requesting line %d as input: %s", sensors[i].gpio_pin, strerror(errno));
            return -1;
        }

        sensors[i].flame_detected = 0; // Initialize flame detection status
    }

    return 0;
}

// Read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        syslog(LOG_USER | LOG_ERR, "Error reading line value: %s", strerror(errno));
        return -1;
    }
    return value;
}

// Debounce sensor reading
int debounce(struct gpiod_line *line) {
    int i, value, sum = 0;
    struct timespec delay = {0, DEBOUNCE_TIME_MS * 1000000L}; // 50ms

    for (i = 0; i < 5; i++) {
        value = read_sensor(line);
        if (value < 0) {
            return -1; // Propagate error
        }
        sum += value;
        nanosleep(&delay, NULL);
    }

    return (sum == 0) ? 0 : 1; // Return 0 if all readings are 0, 1 otherwise
}

// Log event to file
int log_event(int sensor_id, int gpio_pin) {
    FILE *fp;
    time_t rawtime;
    struct tm *info;
    char timestamp[30];

    // Get current time
    time(&rawtime);
    info = gmtime(&rawtime);

    // Format timestamp in ISO 8601 UTC format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", info);

    // Open log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_USER | LOG_ERR, "Error opening log file: %s", strerror(errno));
        return -1;
    }

    // Write event to log file
    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, gpio_pin);

    // Close log file
    fclose(fp);

    return 0;
}

// Cleanup resources
void cleanup(struct gpiod_chip *chip, sensor_data_t *sensors) {
    int i;

    // Release GPIO lines
    for (i = 0; i < NUM_SENSORS; i++) {
        if (sensors[i].line) {
            gpiod_line_release(sensors[i].line);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    closelog();
}

int main() {
    int i, prev_value, current_value;

    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO pins
    if (setup_gpio(&chip, sensors) < 0) {
        syslog(LOG_USER | LOG_ERR, "GPIO setup failed, exiting");
        cleanup(chip, sensors);
        return 1;
    }

    syslog(LOG_USER | LOG_INFO, "Flame monitor started");

    // Main loop
    while (!terminate) {
        for (i = 0; i < NUM_SENSORS; i++) {
            prev_value = (sensors[i].flame_detected == 0) ? 0 : 1; // Treat flame_detected as previous value
            current_value = read_sensor(sensors[i].line);

            if (current_value < 0) {
                syslog(LOG_USER | LOG_WARNING, "Error reading sensor %d, skipping", i + 1);
                continue;
            }

            // Check for rising edge (no-flame to flame)
            if (prev_value == 1 && current_value == 0) {
                // Debounce the reading
                if (debounce(sensors[i].line) == 0) {
                    // Log the event
                    if (log_event(sensors[i].sensor_id, sensors[i].gpio_pin) < 0) {
                        syslog(LOG_USER | LOG_ERR, "Error logging event for sensor %d", i + 1);
                    } else {
                        syslog(LOG_USER | LOG_INFO, "Flame detected on sensor %d (GPIO %d)", i + 1, sensors[i].gpio_pin);
                        sensors[i].flame_detected = 0; // Update flame detection status
                    }
                }
            } else if (prev_value == 0 && current_value == 1) {
                sensors[i].flame_detected = 1; // Update flame detection status
            }
        }

        sleep(1); // Poll every second
    }

    // Cleanup resources before exiting
    cleanup(chip, sensors);

    return 0;
}

