#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define the GPIO pins connected to the TTP226 sensor
const int pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_pins = sizeof(pins) / sizeof(pins[0]);

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[8] = {NULL};

// Function prototypes
int initialize_gpio();
int read_sensor_data(int *data);
void log_state_change(int index, int pin, int state);
void cleanup_gpio();
void signal_handler(int sig);

// Structure to hold previous sensor states
struct {
    int state[8];
} previous_state = {{0}};

int main() {
    int sensor_data[8];

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data. Continuing.\n");
            continue; // Continue to the next iteration
        }

        // Check for state changes and log them
        for (int i = 0; i < num_pins; i++) {
            if (sensor_data[i] != previous_state.state[i]) {
                log_state_change(i, pins[i], sensor_data[i]);
                previous_state.state[i] = sensor_data[i];
            }
        }

        // Wait for 50 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    int i;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request GPIO lines
    for (i = 0; i < num_pins; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", pins[i], strerror(errno));
            cleanup_gpio();
            return -1;
        }

        // Request line for input
        if (gpiod_line_request_input(lines[i], "touch_sensor") < 0) {
            fprintf(stderr, "Error requesting line %d for input: %s\n", pins[i], strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int *data) {
    int i;

    for (i = 0; i < num_pins; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading value from line %d: %s\n", pins[i], strerror(errno));
            return -1;
        }
        data[i] = value;
    }

    return 0;
}

// Function to log state changes
void log_state_change(int index, int pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s - Sensor %d (BCM %d): %s\n", timestamp, index, pin, state ? "Touched" : "Released");
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    int i;

    if (chip) {
        for (i = 0; i < num_pins; i++) {
            if (lines[i]) {
                gpiod_line_release(lines[i]);
            }
        }
        gpiod_chip_close(chip);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up and exiting.\n", sig);
    cleanup_gpio();
    exit(0);
