#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define CONFIG_REG 0x00
#define ALS_REG 0x04
#define LED_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int configure_veml7700();
int read_als_data(uint16_t *raw_data);
float convert_to_lux(uint16_t raw_data);
int set_led_brightness(float lux);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, shutting down...\n");
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure VEML7700 sensor
int configure_veml7700() {
    uint16_t config_value = 0x0000; // ALS gain 1/8, integration time 100ms
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = config_value & 0xFF;        // Low byte
    buf[2] = (config_value >> 8) & 0xFF; // High byte

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ALS data from VEML7700
int read_als_data(uint16_t *raw_data) {
    char reg = ALS_REG;
    char buf[2];
    int result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ALS register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read ALS data: %d\n", result);
        return -1;
    }

    *raw_data = (buf[1] << 8) | buf[0]; // Little-endian
    return 0;
}

// Convert raw data to lux
float convert_to_lux(uint16_t raw_data) {
    return (float)raw_data * 0.0576;
}

// Set LED brightness based on lux value
int set_led_brightness(float lux) {
    int brightness = 0;
    if (lux < 100) {
        brightness = 100;
    } else if (lux < 500) {
        brightness = 75;
    } else if (lux < 1000) {
        brightness = 50;
    } else {
        brightness = 25;
    }

    gpioPWM(LED_GPIO, brightness);
    return brightness;
}

// Log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Lux: %.2f, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure VEML7700 sensor
    if (configure_veml7700() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t raw_data;
    float lux;
    int brightness;
    int error_code;

    // Main loop
    while (!terminate) {
        error_code = 0;

        // Read ALS data
        if (read_als_data(&raw_data) != 0) {
            fprintf(stderr, "Error reading ALS data\n");
            error_code = 1;
        } else {
            // Convert to lux
            lux = convert_to_lux(raw_data);

            // Set LED brightness
            brightness = set_led_brightness(lux);

            // Log data
            log_data(lux, brightness, error_code);
        }

        sleep(1);
    }

    // Cleanup
    gpioPWM(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

