#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define LED_PIN 17
#define TOUCH_PINS_START 2
#define NUM_TOUCH_PINS 8

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensors();
int debounce_touch(int channel);
int log_touch_event(int channel);
int control_led(int state);
void signal_handler(int signal);
void cleanup();

// Structure to hold the last touch time for each channel
struct touch_state {
    unsigned long last_touch_time[8];
};

struct touch_state touch_states = {{0}};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Security Keypad running. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_detected = read_touch_sensors();

        if (touch_detected) {
            for (int i = 0; i < NUM_TOUCH_PINS; i++) {
                if (gpioRead(TOUCH_PINS_START + i) == 1) {
                    if (debounce_touch(i) == 0) {
                        log_touch_event(i + 1);
                        control_led(1); // Turn LED on
                    }
                }
            }
        } else {
            // Check if all channels are released
            int all_released = 1;
            for (int i = 0; i < NUM_TOUCH_PINS; i++) {
                if (gpioRead(TOUCH_PINS_START + i) == 1) {
                    all_released = 0;
                    break;
                }
            }
            if (all_released) {
                control_led(0); // Turn LED off
            }
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output for LED
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set GPIO 2-9 as inputs with pull-down resistors
    for (int i = 0; i < NUM_TOUCH_PINS; i++) {
        gpioSetMode(TOUCH_PINS_START + i, PI_INPUT);
        gpioSetPullUpDown(TOUCH_PINS_START + i, PI_PUD_DOWN);
    }

    return 0;
}

// Read touch sensors
int read_touch_sensors() {
    for (int i = 0; i < NUM_TOUCH_PINS; i++) {
        if (gpioRead(TOUCH_PINS_START + i) == 1) {
            return 1; // At least one touch detected
        }
    }
    return 0; // No touch detected
}

// Debounce touch sensor
int debounce_touch(int channel) {
    unsigned long current_time = gpioTick();
    if (current_time - touch_states.last_touch_time[channel] > DEBOUNCE_TIME * 1000) {
        touch_states.last_touch_time[channel] = current_time;
        return 0; // Valid touch
    } else {
        return 1; // Debounced
    }
}

// Log touch event to file
int log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Error writing to log file!\n");
        return 1;
    }
}

// Control LED state
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Cleanup resources
void cleanup() {
    control_led(0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
}

