            log_event("Error reading flame sensor.");
        }

        gpioDelay(500); // Wait 500 milliseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
