#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define DEBOUNCE_MS 50
#define LOG_FILE "touch_log.txt"

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
int log_message(const char *message) {
    char *timestamp = get_timestamp();
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the message is written immediately
    return 0;
}

int main() {
    int ret;
    int value;
    int prev_value = 0; // Store the previous value for debouncing

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line for input with pull-down
    ret = gpiod_line_request_input(line, "touch_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for input: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to monitor the touch sensor
    while (keep_running) {
        // Read the value of the GPIO line
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error: Could not read GPIO line value: %s\n", strerror(errno));
            break; // Exit the loop on error
        }

        // Debouncing and state change detection
        if (value != prev_value) {
            if (value == 1) {
                if (log_message("Touch Detected") != 0) {
                    fprintf(stderr, "Error: Failed to log touch detected event.\n");
                }
            } else {
                if (log_message("Touch Released") != 0) {
                    fprintf(stderr, "Error: Failed to log touch released event.\n");
                }
            }
            prev_value = value;
        }

        // Sleep for the debounce interval
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = DEBOUNCE_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    fprintf(stderr, "Cleaning up...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    fprintf(stderr, "Exiting.\n");
    return 0;
}

