#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdbool.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "path_log.csv"

// Structure to hold GPIO line information
typedef struct {
    struct gpiod_line *line;
    int pin;
} gpio_line_t;

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *middle_line = NULL;
static struct gpiod_line *right_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int get_iso8601_timestamp(char *timestamp);
int log_data(FILE *fp, const char *timestamp, int left, int middle, int right);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp in ISO 8601 format
int get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting time information: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, 32, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    return 0;
}

// Function to log the data to the CSV file
int log_data(FILE *fp, const char *timestamp, int left, int middle, int right) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to setup the GPIO lines
int setup_gpio(void) {
    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get the GPIO lines
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);

    if (!left_line || !middle_line || !right_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup_gpio();
        return -1;
    }

    // Request the lines as inputs
    if (gpiod_line_request_input(left_line, "left_sensor") < 0 ||
        gpiod_line_request_input(middle_line, "middle_sensor") < 0 ||
        gpiod_line_request_input(right_line, "right_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to cleanup the GPIO lines
void cleanup_gpio(void) {
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Setup GPIO
    if (setup_gpio() < 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    // Main loop
    char timestamp[32];
    int left_value, middle_value, right_value;
    struct timespec sleep_time = {0, 50000000}; // 50 milliseconds

    while (!terminate) {
        // Read sensor values
        left_value = read_sensor(left_line);
        middle_value = read_sensor(middle_line);
        right_value = read_sensor(right_line);

        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensor values, exiting.\n");
            break;
        }

        // Get timestamp
        if (get_iso8601_timestamp(timestamp) < 0) {
            fprintf(stderr, "Error getting timestamp, exiting.\n");
            break;
        }

        // Log data
        if (log_data(log_file, timestamp, left_value, middle_value, right_value) < 0) {
            fprintf(stderr, "Error logging data, exiting.\n");
            break;
        }

        // Sleep for 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    fclose(log_file);
    cleanup_gpio();

    return 0;
}

