#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24

// Define GPIO chip
#define GPIO_CHIP "gpiochip4"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int setup_gpio(void);
int setup_touch_line(void);
int setup_led_line(void);
int read_touch_sensor(void);
int toggle_led(int current_state);
int log_event(int led_state);
void signal_handler(int sig);
void cleanup(void);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", sig);
    terminate = 1;
}

// Setup GPIO chip
int setup_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    return 0;
}

// Setup touch sensor line
int setup_touch_line(void) {
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Error getting touch sensor line %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(touch_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting touch sensor line %d as input: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        return -1;
    }

    return 0;
}

// Setup LED line
int setup_led_line(void) {
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line %d: %s\n", LED_PIN, strerror(errno));
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(led_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line %d as output: %s\n", LED_PIN, strerror(errno));
        return -1;
    }

    return 0;
}

// Read touch sensor
int read_touch_sensor(void) {
    int value = gpiod_line_get_value(touch_line);
    if (value < 0) {
        fprintf(stderr, "Error reading touch sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Toggle LED state
int toggle_led(int current_state) {
    int new_state = !current_state;
    int ret = gpiod_line_set_value(led_line, new_state);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
        return -1;
    }
    return new_state;
}

// Log event to file
int log_event(int led_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, LED State: %d\n", timestamp, led_state);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup(void) {
    fprintf(stderr, "Cleaning up resources...\n");

    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    fprintf(stderr, "Cleanup complete.\n");
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (setup_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize touch sensor line
    if (setup_touch_line() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize LED line
    if (setup_led_line() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int led_state = 0; // Initial LED state (off)
    gpiod_line_set_value(led_line, led_state); // Set initial LED state

    // Main loop
    while (!terminate) {
        int touch_value = read_touch_sensor();
        if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor, exiting...\n");
            break;
        }

        if (touch_value == 1) {
            led_state = toggle_led(led_state);
            if (led_state < 0) {
                fprintf(stderr, "Error toggling LED, exiting...\n");
                break;
            }
            if (log_event(led_state) < 0) {
                fprintf(stderr, "Error logging event, exiting...\n");
                break;
            }
            printf("Touch detected! LED toggled to state: %d\n", led_state);
        }

        // Poll for a short duration to avoid busy-waiting
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

