#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static unsigned long last_touch_time = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int toggle_led();
int log_touch_event();
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int led_state;
} ProgramState;

ProgramState state = {0}; // Initialize LED state to off

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read the touch sensor
        if (read_touch_sensor() == 1) {
            // Debounce the touch
            unsigned long current_time = gpioTick();
            if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) {
                // Toggle the LED
                if (toggle_led() != 0) {
                    fprintf(stderr, "Failed to toggle LED.\n");
                }

                // Log the touch event
                if (log_touch_event() != 0) {
                    fprintf(stderr, "Failed to log touch event.\n");
                }

                // Update the last touch time
                last_touch_time = current_time;
            }
        }

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup and exit
    gpioWrite(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Toggle the LED
int toggle_led() {
    state.led_state = !state.led_state; // Toggle the LED state
    if (gpioWrite(LED_PIN, state.led_state) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
        return 1;
    }
    return 0;
}

// Log the touch event with timestamp
int log_touch_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(log_file, "%s: Touch detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file!\n");
        return 1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    running = 0;
}

