#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    int sensor3_state;
} SensorStates;

SensorStates current_states = {0, 0, 0}; // Initialize all states to 0 (magnet removed)

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int log_event(int gpio, int state);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }

    gpioTerminate();
    printf("pigpio terminated.\n");

    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR1_GPIO);
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR1_GPIO);
        return 1;
    }

    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR2_GPIO);
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR2_GPIO);
        return 1;
    }

    if (gpioSetMode(SENSOR3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR3_GPIO);
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR3_GPIO);
        return 1;
    }

    return 0;
}

// Function to read sensor state
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO%d: %d\n", gpio, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to log events to file
int log_event(int gpio, int state) {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return 1;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s - Sensor %d: %s\n", timestamp, gpio, state ? "Magnet Present" : "Magnet Removed");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }
    free(timestamp);
    return 0;
}

// Function to get ISO-8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return buffer;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("magnet_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Initial sensor readings
    int sensor1_initial = read_sensor(SENSOR1_GPIO);
    int sensor2_initial = read_sensor(SENSOR2_GPIO);
    int sensor3_initial = read_sensor(SENSOR3_GPIO);

    if (sensor1_initial < 0 || sensor2_initial < 0 || sensor3_initial < 0) {
        fprintf(stderr, "Error during initial sensor readings\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    current_states.sensor1_state = sensor1_initial;
    current_states.sensor2_state = sensor2_initial;
    current_states.sensor3_state = sensor3_initial;

    // Main loop
    while (program_running) {
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        int sensor3_value = read_sensor(SENSOR3_GPIO);

        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0) {
            fprintf(stderr, "Error reading sensors in main loop\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Check for state changes and log them
        if (sensor1_value != current_states.sensor1_state) {
            log_event(SENSOR1_GPIO, sensor1_value);
            current_states.sensor1_state = sensor1_value;
        }
        if (sensor2_value != current_states.sensor2_state) {
            log_event(SENSOR2_GPIO, sensor2_value);
            current_states.sensor2_state = sensor2_value;
        }
        if (sensor3_value != current_states.sensor3_state) {
            log_event(SENSOR3_GPIO, sensor3_value);
            current_states.sensor3_state = sensor3_value;
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Clean up (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

