#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x03
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A
#define MOVING_AVG_SIZE 5
#define MIN_BPM 30
#define MAX_BPM 220

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for moving average filter
typedef struct {
    float buffer[MOVING_AVG_SIZE];
    int index;
    int count;
} MovingAverageFilter;

// Function prototypes
int initialize_sensor();
int read_heart_rate();
float convert_to_bpm(int raw_value);
void apply_moving_average(MovingAverageFilter *filter, float new_value, float *filtered_value);
int validate_bpm(float bpm);
int log_data(float bpm);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize the sensor
int initialize_sensor() {
    int part_id, hw_rev;

    // Verify PART_ID
    part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x02) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Verify HW_REV
    hw_rev = i2cReadByteData(i2c_handle, HW_REV_REG);
    if (hw_rev < 0) {
        fprintf(stderr, "Error reading HW_REV: %d\n", hw_rev);
        return -1;
    }
    if (hw_rev != 0x01) {
        fprintf(stderr, "Incorrect HW_REV: 0x%02X\n", hw_rev);
        return -1;
    }

    // Configure LED current
    if (i2cWriteByteData(i2c_handle, LED_CURRENT_REG, 0x3F) < 0) {
        fprintf(stderr, "Error writing LED current\n");
        return -1;
    }

    // Configure averaging
    if (i2cWriteByteData(i2c_handle, AVERAGING_REG, 0x04) < 0) {
        fprintf(stderr, "Error writing averaging\n");
        return -1;
    }

    // Enable sensor
    if (i2cWriteByteData(i2c_handle, ENABLE_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing enable\n");
        return -1;
    }

    return 0;
}

// Read heart rate data
int read_heart_rate() {
    int raw_value;
    int retries = 3;

    while (retries > 0) {
        raw_value = i2cReadWordData(i2c_handle, HEART_RATE_REG);
        if (raw_value >= 0) {
            return raw_value;
        } else {
            fprintf(stderr, "I2C read error, retrying... (%d retries left)\n", retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read heart rate after multiple retries\n");
    return -1;
}

// Convert raw value to BPM
float convert_to_bpm(int raw_value) {
    return (float)raw_value * 0.5;
}

// Apply moving average filter
void apply_moving_average(MovingAverageFilter *filter, float new_value, float *filtered_value) {
    filter->buffer[filter->index] = new_value;
    filter->index = (filter->index + 1) % MOVING_AVG_SIZE;
    if (filter->count < MOVING_AVG_SIZE) {
        filter->count++;
    }

    float sum = 0.0;
    for (int i = 0; i < filter->count; i++) {
        sum += filter->buffer[i];
    }

    *filtered_value = sum / filter->count;
}

// Validate BPM
int validate_bpm(float bpm) {
    return (bpm >= MIN_BPM && bpm <= MAX_BPM);
}

// Log data to file
int log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Moving average filter
    MovingAverageFilter filter = {{0.0}, 0, 0};

    // Main loop
    while (!terminate) {
        // Read heart rate
        int raw_value = read_heart_rate();
        if (raw_value >= 0) {
            // Convert to BPM
            float bpm = convert_to_bpm(raw_value);

            // Apply moving average filter
            float filtered_bpm;
            apply_moving_average(&filter, bpm, &filtered_bpm);

            // Validate BPM
            if (validate_bpm(filtered_bpm)) {
                // Log data
                log_data(filtered_bpm);
                printf("BPM: %.2f\n", filtered_bpm);
            } else {
                fprintf(stderr, "Invalid BPM: %.2f\n", filtered_bpm);
            }
        } else {
            fprintf(stderr, "Failed to read heart rate\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup
    cleanup();

    return 0;
}

