// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(void);
int read_sensor(int channel);
void update_counter(int increment);
void update_display(int value);
void log_touch_event(int channel, int counter_value);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int i;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request input lines for TTP226 outputs
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, TTP226_BASE_PIN + i);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", TTP226_BASE_PIN + i, strerror(errno));
            cleanup_gpio();
            return -1;
        }

        ret = gpiod_line_request(lines[i], NULL, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as input: %s\n", TTP226_BASE_PIN + i, strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    // Request output lines for counter display
    for (i = 0; i < NUM_CHANNELS; i++) {
        output_lines[i] = gpiod_chip_get_line(chip, COUNTER_BASE_PIN + i);
        if (!output_lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", COUNTER_BASE_PIN + i, strerror(errno));
            cleanup_gpio();
            return -1;
        }

        ret = gpiod_line_request(output_lines[i], NULL, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as output: %s\n", COUNTER_BASE_PIN + i, strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    int i;

    // Release input lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Release output lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (output_lines[i]) {
            gpiod_line_release(output_lines[i]);
        }
    }

