    counter += increment;
    if (counter > 255) {
        counter = 0;
    } else if (counter < 0) {
        counter = 255;
    }
}

// Update the display based on the counter value
void update_display(int value) {
    int i;
    int bit;

    for (i = 0; i < NUM_CHANNELS; i++) {
        bit = (value >> i) & 1;
        int ret = gpiod_line_set_value(output_lines[i], bit);
        if (ret < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n", COUNTER_BASE_PIN + i, strerror(errno));
        }
    }
}

// Log touch event to file
void log_touch_event(int channel, int counter_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel + 1, counter_value);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Warning: Log file not opened. Touch event not logged to file.\n");
    }
}

