    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Warning: Could not open log file: %s\n", strerror(errno));
    }

    // Stabilization delay
    delay.tv_sec = 0;
    delay.tv_nsec = 200 * 1000 * 1000; // 200 ms
    nanosleep(&delay, NULL);

    // Main loop
    while (!terminate) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            current_state = read_sensor(i);
            if (current_state < 0) {
                continue; // Skip to the next channel on error
            }

            if (current_state == 1 && previous_state[i] == 0) {
                // Rising edge detected
                update_counter(1);
                update_display(counter);
