#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO17 17
#define GPIO18 18

// Define log file path
#define LOG_FILE "/var/log/tilt_events.log"

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Polling interval in milliseconds
#define POLL_INTERVAL 100

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line18;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Structure to hold the last event time for debouncing
typedef struct {
    struct timespec last_event_time;
} debounce_state_t;

static debounce_state_t debounce_state17, debounce_state18;

// Function prototypes
int setup_gpio(void);
int read_sensor(int gpio);
int log_event(int sensor_number);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", sig);
    terminate = 1;
}

// Setup GPIO lines
int setup_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request GPIO line 17
    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO17, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO line 18
    line18 = gpiod_chip_get_line(chip, GPIO18);
    if (!line18) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO18, strerror(errno));
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return -1;
    }

    // Configure GPIO lines as input with pull-up resistor
    ret = gpiod_line_request_input(line17, "tilt_sensor_17", 0); // 0 for no flags, using default pull-up
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO17, strerror(errno));
        gpiod_line_release(line18);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(line18, "tilt_sensor_18", 0); // 0 for no flags, using default pull-up
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO18, strerror(errno));
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(int gpio) {
    int value;
    struct gpiod_line *line;

    if (gpio == GPIO17) {
        line = line17;
    } else if (gpio == GPIO18) {
        line = line18;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio);
        return -1;
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", gpio, strerror(errno));
        return -1;
    }

    return value;
}

// Log event to file
int log_event(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Cleanup resources
void cleanup(void) {
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    struct timespec sleep_time;
    int sensor17_value, sensor18_value;
    struct timespec current_time;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize sleep time
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = POLL_INTERVAL * 1000000; // Convert milliseconds to nanoseconds

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Setup GPIO
    if (setup_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Initialize debounce times
    clock_gettime(CLOCK_MONOTONIC, &debounce_state17.last_event_time);
    clock_gettime(CLOCK_MONOTONIC, &debounce_state18.last_event_time);

    // Main loop
    while (!terminate) {
        // Read sensor values
        sensor17_value = read_sensor(GPIO17);
        sensor18_value = read_sensor(GPIO18);

        if (sensor17_value < 0 || sensor18_value < 0) {
            fprintf(stderr, "Error reading sensor values. Exiting.\n");
            break;
        }

        // Check for tilt event on sensor 1 (GPIO17)
        if (sensor17_value == 0) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            double time_diff = (current_time.tv_sec - debounce_state17.last_event_time.tv_sec) * 1000.0;
            time_diff += (current_time.tv_nsec - debounce_state17.last_event_time.tv_nsec) / 1000000.0;

            if (time_diff > DEBOUNCE_TIME) {
                log_event(1);
                clock_gettime(CLOCK_MONOTONIC, &debounce_state17.last_event_time);
            }
        }

        // Check for tilt event on sensor 2 (GPIO18)
        if (sensor18_value == 0) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            double time_diff = (current_time.tv_sec - debounce_state18.last_event_time.tv_sec) * 1000.0;
            time_diff += (current_time.tv_nsec - debounce_state18.last_event_time.tv_nsec) / 1000000.0;

            if (time_diff > DEBOUNCE_TIME) {
                log_event(2);
                clock_gettime(CLOCK_MONOTONIC, &debounce_state18.last_event_time);
            }
        }

        // Sleep for the polling interval
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

