#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define sampling rate and period
#define SAMPLE_RATE 8000
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)

// Define LED on time
#define LED_ON_TIME_MS 100

// Global flag for signal handling
volatile sig_atomic_t terminate_flag = 0;

// Signal handler function
void signal_handler(int signal) {
    terminate_flag = 1;
    fprintf(stderr, "Signal received, terminating...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set MIC_PIN as input\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN as output\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read microphone data
int read_microphone() {
    return gpioRead(MIC_PIN);
}

// Function to control the LED
int control_led(int on) {
    if (gpioWrite(LED_PIN, on) != 0) {
        fprintf(stderr, "Failed to write to LED_PIN\n");
        return -1;
    }
    return 0;
}

// Function to get timestamp
void get_timestamp(char *timestamp) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = (ts.tv_nsec / 1000000);
    sprintf(timestamp, "%ld.%03ld", ts.tv_sec, milliseconds);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Program started, sampling at %d Hz\n", SAMPLE_RATE);

    // Main loop
    while (!terminate_flag) {
        // Read microphone data
        int mic_value = read_microphone();
        if (mic_value < 0) {
            fprintf(stderr, "Error reading microphone data\n");
            break;
        }

        // Check for peak
        if (mic_value == 1) {
            // Get timestamp
            char timestamp[30];
            get_timestamp(timestamp);

            // Print timestamp
            printf("%s\n", timestamp);

            // Turn LED on
            if (control_led(1) != 0) {
                fprintf(stderr, "Error turning LED on\n");
                break;
            }

            // Wait for LED on time
            gpioDelay(LED_ON_TIME_MS * 1000); // Convert ms to us

            // Turn LED off
            if (control_led(0) != 0) {
                fprintf(stderr, "Error turning LED off\n");
                break;
            }
        }

        // Delay for sampling period
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up
    fprintf(stderr, "Cleaning up...\n");
    control_led(0); // Ensure LED is off
    gpioTerminate();

    fprintf(stderr, "Program terminated\n");
    return 0;
}

