#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x49
#define ALS_VIS_LSB_REG 0x24
#define ALS_VIS_MSB_REG 0x25
#define READ_INTERVAL_MS 100

// Global variables
int i2c_fd = -1; // I2C file descriptor
volatile sig_atomic_t terminate = 0; // Termination flag

// Function prototypes
int i2c_init(const char *bus, int addr);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int16_t combine_lsb_msb(uint8_t lsb, uint8_t msb);
void log_data(int16_t value);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// I2C initialization function
int i2c_init(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading data");
        return -1;
    }

    return 0;
}

// Combine LSB and MSB into a 16-bit value
int16_t combine_lsb_msb(uint8_t lsb, uint8_t msb) {
    return (int16_t)((msb << 8) | lsb);
}

// Log data to the console
void log_data(int16_t value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Raw ALS Visible: %d\n", timestamp, value);
}

int main() {
    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return 1;
    }

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS, SI1175_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    printf("I2C initialized successfully.\n");

    // Main loop
    while (!terminate) {
        uint8_t lsb, msb;
        int16_t als_value;

        // Read ALS visible data
        if (i2c_read_bytes(i2c_fd, ALS_VIS_LSB_REG, &lsb, 1) != 0) {
            fprintf(stderr, "Error reading ALS LSB. Retrying in %d ms.\n", READ_INTERVAL_MS);
            usleep(READ_INTERVAL_MS * 1000); // Sleep for READ_INTERVAL_MS milliseconds
            continue;
        }

        if (i2c_read_bytes(i2c_fd, ALS_VIS_MSB_REG, &msb, 1) != 0) {
            fprintf(stderr, "Error reading ALS MSB. Retrying in %d ms.\n", READ_INTERVAL_MS);
            usleep(READ_INTERVAL_MS * 1000); // Sleep for READ_INTERVAL_MS milliseconds
            continue;
        }

        // Combine LSB and MSB
        als_value = combine_lsb_msb(lsb, msb);

        // Log the data
        log_data(als_value);

        // Sleep for the specified interval
        usleep(READ_INTERVAL_MS * 1000); // Sleep for READ_INTERVAL_MS milliseconds
    }

    // Clean up
    if (i2c_fd != -1) {
        close(i2c_fd);
        printf("I2C connection closed.\n");
    }

    return 0;
}

