#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for left, middle, and right sensors
#define LEFT_PIN 2
#define MIDDLE_PIN 3
#define RIGHT_PIN 4

// Global variables for GPIO lines and chip
struct gpiod_line *left_line = NULL;
struct gpiod_line *middle_line = NULL;
struct gpiod_line *right_line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines if they are open
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }

    // Close the GPIO chip if it is open
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int ret;
    int left_value, middle_value, right_value;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO lines for left, middle, and right sensors
    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    if (!left_line) {
        perror("Error getting left GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    middle_line = gpiod_chip_get_line(chip, MIDDLE_PIN);
    if (!middle_line) {
        perror("Error getting middle GPIO line");
        gpiod_line_release(left_line);
        gpiod_chip_close(chip);
        return 1;
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    if (!right_line) {
        perror("Error getting right GPIO line");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for input
    ret = gpiod_line_request_input(left_line, "left_sensor");
    if (ret < 0) {
        perror("Error requesting left GPIO line for input");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(middle_line, "middle_sensor");
    if (ret < 0) {
        perror("Error requesting middle GPIO line for input");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(right_line, "right_sensor");
    if (ret < 0) {
        perror("Error requesting right GPIO line for input");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to read sensor values
    while (1) {
        // Read the value of the left sensor
        ret = gpiod_line_get_value(left_line);
        if (ret < 0) {
            perror("Error reading left GPIO line value");
            break;
        }
        left_value = ret;

        // Read the value of the middle sensor
        ret = gpiod_line_get_value(middle_line);
        if (ret < 0) {
            perror("Error reading middle GPIO line value");
            break;
        }
        middle_value = ret;

        // Read the value of the right sensor
        ret = gpiod_line_get_value(right_line);
        if (ret < 0) {
            perror("Error reading right GPIO line value");
            break;
        }
        right_value = ret;

        // Print the sensor values to stdout
        printf("L:%d M:%d R:%d\n", left_value, middle_value, right_value);

        // Wait for 100 milliseconds
        usleep(100000);
    }

    // Clean up GPIO lines and chip before exiting
    gpiod_line_release(left_line);
    gpiod_line_release(middle_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);

    return 0;
}

