#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the touch sensor channels
#define CH1_PIN 5
#define CH2_PIN 6
#define CH3_PIN 13
#define CH4_PIN 19
#define CH5_PIN 26
#define CH6_PIN 12
#define CH7_PIN 16
#define CH8_PIN 20

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the state of a single channel
int read_channel(int pin) {
    return gpioRead(pin);
}

// Function to log the sensor data with a timestamp
void log_data(int ch1, int ch2, int ch3, int ch4, int ch5, int ch6, int ch7, int ch8) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
    printf("[%lf] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
           timestamp, ch1, ch2, ch3, ch4, ch5, ch6, ch7, ch8);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(CH1_PIN, PI_INPUT);
    gpioSetMode(CH2_PIN, PI_INPUT);
    gpioSetMode(CH3_PIN, PI_INPUT);
    gpioSetMode(CH4_PIN, PI_INPUT);
    gpioSetMode(CH5_PIN, PI_INPUT);
    gpioSetMode(CH6_PIN, PI_INPUT);
    gpioSetMode(CH7_PIN, PI_INPUT);
    gpioSetMode(CH8_PIN, PI_INPUT);

    // Main loop to read and log sensor data
    while (!terminate) {
        int ch1 = read_channel(CH1_PIN);
        int ch2 = read_channel(CH2_PIN);
        int ch3 = read_channel(CH3_PIN);
        int ch4 = read_channel(CH4_PIN);
        int ch5 = read_channel(CH5_PIN);
        int ch6 = read_channel(CH6_PIN);
        int ch7 = read_channel(CH7_PIN);
        int ch8 = read_channel(CH8_PIN);

        log_data(ch1, ch2, ch3, ch4, ch5, ch6, ch7, ch8);

        gpioDelay(200); // Delay for 200 ms
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    return 0;
}

