#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency and range
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

// Define fade duration and steps
#define FADE_DURATION 5.0 // seconds
#define FADE_STEPS 50

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void set_led_color(int red, int green, int blue);
void hsv_to_rgb(float hue, float saturation, float value, int *red, int *green, int *blue);
void fade_color(int start_red, int start_green, int start_blue, int end_red, int end_green, int end_blue);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize GPIO pins and pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set RED_PIN to output");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GREEN_PIN to output");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set BLUE_PIN to output");
        gpioTerminate();
        return -1;
    }

    // Set PWM frequency and range
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for RED_PIN");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GREEN_PIN");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for BLUE_PIN");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range for RED_PIN");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range for GREEN_PIN");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range for BLUE_PIN");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Set the color of the RGB LED
void set_led_color(int red, int green, int blue) {
    // Invert the PWM values for common-anode LED
    int inv_red = 255 - red;
    int inv_green = 255 - green;
    int inv_blue = 255 - blue;

    // Clamp the values to the valid range
    if (inv_red < 0) inv_red = 0;
    if (inv_red > 255) inv_red = 255;
    if (inv_green < 0) inv_green = 0;
    if (inv_green > 255) inv_green = 255;
    if (inv_blue < 0) inv_blue = 0;
    if (inv_blue > 255) inv_blue = 255;

    // Set the PWM duty cycle for each color channel
    gpioPWM(RED_PIN, inv_red);
    gpioPWM(GREEN_PIN, inv_green);
    gpioPWM(BLUE_PIN, inv_blue);
}

// Convert HSV color to RGB color
void hsv_to_rgb(float hue, float saturation, float value, int *red, int *green, int *blue) {
    if (saturation == 0.0) {
        // Achromatic (gray)
        *red = *green = *blue = (int)(value * 255);
        return;
    }

    hue = fmodf(hue, 360.0); // Ensure hue is within 0-360
    hue /= 60.0;
    int i = (int)hue;
    float f = hue - i;
    float p = value * (1 - saturation);
    float q = value * (1 - saturation * f);
    float t = value * (1 - saturation * (1 - f));

    switch (i) {
        case 0:
            *red = (int)(value * 255);
            *green = (int)(t * 255);
            *blue = (int)(p * 255);
            break;
        case 1:
            *red = (int)(q * 255);
            *green = (int)(value * 255);
            *blue = (int)(p * 255);
            break;
        case 2:
            *red = (int)(p * 255);
            *green = (int)(value * 255);
            *blue = (int)(t * 255);
            break;
        case 3:
            *red = (int)(p * 255);
            *green = (int)(q * 255);
            *blue = (int)(value * 255);
            break;
        case 4:
            *red = (int)(t * 255);
            *green = (int)(p * 255);
            *blue = (int)(value * 255);
            break;
        default: // case 5:
            *red = (int)(value * 255);
            *green = (int)(p * 255);
            *blue = (int)(q * 255);
            break;
    }
}

// Fade between two colors
void fade_color(int start_red, int start_green, int start_blue, int end_red, int end_green, int end_blue) {
    float red_diff   = (float)(end_red   - start_red)   / FADE_STEPS;
    float green_diff = (float)(end_green - start_green) / FADE_STEPS;
    float blue_diff  = (float)(end_blue  - start_blue)  / FADE_STEPS;

    int current_red   = start_red;
    int current_green = start_green;
    int current_blue  = start_blue;

    for (int i = 0; i < FADE_STEPS; i++) {
        current_red   += (int)red_diff;
        current_green += (int)green_diff;
        current_blue  += (int)blue_diff;

        set_led_color(current_red, current_green, current_blue);
        gpioDelay((int)(FADE_DURATION * 1000000 / FADE_STEPS)); // Delay in microseconds
    }

    // Ensure the final color is set exactly
    set_led_color(end_red, end_green, end_blue);
}

int main() {
    // Open syslog for logging
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator
    srand(time(NULL));

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Mood lamp started");

    // Main loop
    while (!terminate) {
        // Generate random hue
        float hue = (float)rand() / RAND_MAX * 360.0;

        // Convert HSV to RGB
        int red, green, blue;
        hsv_to_rgb(hue, 1.0, 1.0, &red, &green, &blue);

        // Fade to the new color
        int current_red, current_green, current_blue;
        set_led_color(0, 0, 0);
        gpioDelay(1000); // Small delay to ensure LED is off before reading
        gpioGetPWMdutycycle(RED_PIN, &current_red);
        gpioGetPWMdutycycle(GREEN_PIN, &current_green);
        gpioGetPWMdutycycle(BLUE_PIN, &current_blue);
        current_red = 255 - current_red;
        current_green = 255 - current_green;
        current_blue = 255 - current_blue;

        fade_color(current_red, current_green, current_blue, red, green, blue);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Turn off the LED
    set_led_color(0, 0, 0);

    // Release GPIO resources
    gpioTerminate();

    // Close syslog
    closelog();

    syslog(LOG_INFO, "Mood lamp terminated");

    return 0;
}

