#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// GPIO pin for LED
#define LED_PIN 17

// Red value threshold for LED control
#define RED_THRESHOLD 200

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables for cleanup
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration parameters (example values, adjust as needed)
#define RED_GAIN 1.0
#define RED_OFFSET 0.0
#define GREEN_GAIN 1.0
#define GREEN_OFFSET 0.0
#define BLUE_GAIN 1.0
#define BLUE_OFFSET 0.0
#define CLEAR_GAIN 1.0
#define CLEAR_OFFSET 0.0

// Function prototypes
int tcs34725_init(int fd);
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *calibrated_red, float *calibrated_green, float *calibrated_blue, float *calibrated_clear);
void gpio_set_output(struct gpiod_line *line, int value);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    terminate = 1;
}

// Initialize the TCS34725 sensor
int tcs34725_init(int fd) {
    uint8_t data[2];

    // Power on and enable RGBC
    data[0] = TCS34725_ENABLE;
    data[1] = 0x03; // PON | AEN
    if (write(fd, data, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Set integration time (ATIME = 0x00 for 2.4ms)
    data[0] = TCS34725_ATIME;
    data[1] = 0x00;
    if (write(fd, data, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Set gain (CONTROL = 0x00 for 1x)
    data[0] = TCS34725_CONTROL;
    data[1] = 0x00;
