#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define WS2812B_GPIO 18
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define LUX_MIN 0
#define LUX_MAX 1000
#define PWM_RANGE 255

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int init_i2c();
int read_bh1750(float *lux);
int map_lux_to_brightness(float lux);
int set_led_brightness(int brightness);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read BH1750 sensor
int read_bh1750(float *lux) {
    char config[1] = {BH1750_CONTINUOUS_HIGH_RES_MODE};
    char data[2];
    int retries = 3;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
            fprintf(stderr, "Error writing to I2C device, retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        gpioDelay(180000); // 180ms delay

        if (i2cReadDevice(i2c_handle, data, 2) != 2) {
            fprintf(stderr, "Error reading from I2C device, retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        unsigned int raw_value = (data[0] << 8) | data[1];
        *lux = (float)raw_value / 1.2;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read BH1750 after multiple retries.\n");
    return -1; // Failure
}

// Map lux to brightness (logarithmic mapping)
int map_lux_to_brightness(float lux) {
    if (lux < LUX_MIN) lux = LUX_MIN;
    if (lux > LUX_MAX) lux = LUX_MAX;

    // Logarithmic mapping
    float normalized_lux = (log10(lux + 1) - log10(LUX_MIN + 1)) / (log10(LUX_MAX + 1) - log10(LUX_MIN + 1));
    int brightness = (int)(normalized_lux * PWM_RANGE);

    return brightness;
}

// Set LED strip brightness using hardware PWM
int set_led_brightness(int brightness) {
    gpioPWM(WS2812B_GPIO, brightness);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(WS2812B_GPIO, 0); // Turn off LEDs
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for WS2812B
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    gpioSetPWMrange(WS2812B_GPIO, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int brightness;

    printf("Starting light sensor and LED control...\n");

    while (!terminate) {
        // Read light sensor
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);

            // Set LED brightness
            set_led_brightness(brightness);

            printf("Brightness: %d\n", brightness);
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        gpioDelay(500000); // 500ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

