#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define APA102_MOSI 10
#define APA102_SCLK 11
#define NUM_LEDS 30
#define NUM_CHANNELS 3
#define NUM_PIXELS (NUM_LEDS * NUM_CHANNELS)
#define NUM_BYTES (NUM_PIXELS * 4 + 4)
#define NUM_BYTES_PADDED (NUM_BYTES + (4 - (NUM_BYTES % 4)))
#define NUM_BYTES_PADDED2 (NUM_BYTES_PADDED + (4 - (NUM_BYTES_PADDED % 4)))

// Global variables
int i2c_handle_low = -1;
int i2c_handle_high = -1;
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int init_bh1750(int i2c_handle);
float read_bh1750(int i2c_handle);
float average_lux(float lux_values[], int num_sensors);
int map_lux_to_brightness(float average_lux);
void set_apa102_brightness(int brightness);
void fade_brightness(int target_brightness);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, cleaning up...\n", signal);
}

// Initialize BH1750 sensor
int init_bh1750(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, 0x00, 0x21) != 0) {
        fprintf(stderr, "Error initializing BH1750\n");
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
float read_bh1750(int i2c_handle) {
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading BH1750 data\n");
        return -1.0;
    }
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    return (float)raw_value / 1.2;
}

// Average lux readings
float average_lux(float lux_values[], int num_sensors) {
    float sum = 0.0;
    int count = 0;
    for (int i = 0; i < 2; i++) {
        if (lux_values[i] >= 0.0) {
            sum += lux_values[i];
            count++;
        }
    }
    if (count > 0) {
        return sum / count;
    } else {
        return 0.0;
    }
}

// Map lux to brightness level (0-31)
int map_lux_to_brightness(float average_lux) {
    int brightness = 31 - (int)(average_lux / 10.0); // Adjust divisor for desired sensitivity
    if (brightness < 0) {
        brightness = 0;
    } else if (brightness > 31) {
        brightness = 31;
    }
    return brightness;
}

// Set APA102 brightness
void set_apa102_brightness(int brightness) {
    char data[NUM_BYTES_PADDED2];
    int i;

    // Start frame (4 bytes of 0x00)
    for (i = 0; i < 4; i++) {
        data[i] = 0x00;
    }

    // LED data frames
    for (i = 0; i < NUM_PIXELS; i++) {
        data[4 + (i * 4)] = 0xE0 | brightness; // Global brightness
        data[4 + (i * 4) + 1] = 0x00; // Blue
        data[4 + (i * 4) + 2] = 0x00; // Green
        data[4 + (i * 4) + 3] = 0x00; // Red
    }

    // End frame (at least 4 bytes of 0xFF)
    for (i = 0; i < 4; i++) {
        data[NUM_BYTES_PADDED + i] = 0xFF;
    }

    // Pad to a multiple of 4 bytes
    for (i = 0; i < (NUM_BYTES_PADDED2 - NUM_BYTES_PADDED - 4); i++) {
        data[NUM_BYTES_PADDED + 4 + i] = 0xFF;
    }

    spiWrite(spi_handle, data, NUM_BYTES_PADDED2);
}

// Fade brightness smoothly
void fade_brightness(int target_brightness) {
    int current_brightness = 0; // Assume starting from 0
    int step = (target_brightness - current_brightness) / 5; // 5 steps for 500ms fade

    for (int i = 0; i < 5; i++) {
        current_brightness += step;
        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > 31) current_brightness = 31;
        set_apa102_brightness(current_brightness);
        gpioDelay(100); // 100ms delay
    }
    set_apa102_brightness(target_brightness);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    // Turn off the LED strip
    set_apa102_brightness(0);

    // Close I2C handles
    if (i2c_handle_low != -1) {
        i2cClose(i2c_handle_low);
    }
    if (i2c_handle_high != -1) {
        i2cClose(i2c_handle_high);
    }

    // Close SPI handle
    if (spi_handle != -1) {
        spiClose(spi_handle);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle_low = i2cOpen(1, BH1750_ADDR_LOW, 0);
    if (i2c_handle_low < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X\n", BH1750_ADDR_LOW);
    } else {
        if (init_bh1750(i2c_handle_low) != 0) {
            i2cClose(i2c_handle_low);
            i2c_handle_low = -1;
        }
    }

    i2c_handle_high = i2cOpen(1, BH1750_ADDR_HIGH, 0);
    if (i2c_handle_high < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X\n", BH1750_ADDR_HIGH);
    } else {
        if (init_bh1750(i2c_handle_high) != 0) {
            i2cClose(i2c_handle_high);
            i2c_handle_high = -1;
        }
    }

    // Open SPI channel
    spi_handle = spiOpen(0, 1000000, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    float lux_values[2];
    int num_sensors = 0;
    if (i2c_handle_low != -1) num_sensors++;
    if (i2c_handle_high != -1) num_sensors++;

    while (!terminate) {
        // Read lux values from sensors
        lux_values[0] = -1.0; // Initialize to invalid value
        lux_values[1] = -1.0; // Initialize to invalid value
        if (i2c_handle_low != -1) {
            lux_values[0] = read_bh1750(i2c_handle_low);
        }
        if (i2c_handle_high != -1) {
            lux_values[1] = read_bh1750(i2c_handle_high);
        }

        // Average lux readings
        float average_lux_value = average_lux(lux_values, num_sensors);

        // Map lux to brightness
        int target_brightness = map_lux_to_brightness(average_lux_value);

        // Fade brightness
        fade_brightness(target_brightness);

        // Delay
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

