            i2cClose(i2c_handle_high);
            i2c_handle_high = -1;
        }
    }

    // Open SPI channel
    spi_handle = spiOpen(0, 1000000, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    float lux_values[2];
    int num_sensors = 0;
    if (i2c_handle_low != -1) num_sensors++;
    if (i2c_handle_high != -1) num_sensors++;

    while (!terminate) {
        // Read lux values from sensors
        lux_values[0] = -1.0; // Initialize to invalid value
        lux_values[1] = -1.0; // Initialize to invalid value
        if (i2c_handle_low != -1) {
            lux_values[0] = read_bh1750(i2c_handle_low);
        }
        if (i2c_handle_high != -1) {
            lux_values[1] = read_bh1750(i2c_handle_high);
        }

        // Average lux readings
        float average_lux_value = average_lux(lux_values, num_sensors);

        // Map lux to brightness
        int target_brightness = map_lux_to_brightness(average_lux_value);

        // Fade brightness
        fade_brightness(target_brightness);

        // Delay
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

