// Constants
#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_REG 0x04
#define WS2812B_GPIO 18
#define PWM_FREQUENCY 800000 // 800 kHz
#define PWM_RANGE 1000       // PWM range for finer control
#define LUX_MAX 120000.0
#define GAMMA 2.2

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int veml7700_init();
int read_veml7700_data(uint16_t *raw_data);
float calculate_lux(uint16_t raw_data);
int map_lux_to_brightness(float lux);
int set_led_brightness(int brightness);
void signal_handler(int signal);
int i2c_write_byte_data(int handle, uint8_t reg, uint8_t data);
int i2c_read_word_data(int handle, uint8_t reg, uint16_t *data);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// VEML7700 initialization function
int veml7700_init() {
    uint8_t config_data[2] = {0x00, 0x00}; // Integration time 100ms, Gain 1/8
    int retries = 3;

    while (retries > 0) {
        if (i2cWriteI2CBlockData(i2c_handle, VEML7700_CONFIG_REG, config_data, 2) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to VEML7700 config register: %s\n", strerror(errno));
            gpioDelay(100000); // 100 ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to initialize VEML7700 after multiple retries.\n");
    return -1; // Failure
}

// Function to read data from VEML7700
int read_veml7700_data(uint16_t *raw_data) {
    int retries = 3;
    while (retries > 0) {
        if (i2cReadWordData(i2c_handle, VEML7700_ALS_REG, (char*)raw_data) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from VEML7700 ALS register: %s\n", strerror(errno));
            gpioDelay(100000); // 100 ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read VEML7700 data after multiple retries.\n");
    return -1; // Failure
}

// Function to calculate lux value
float calculate_lux(uint16_t raw_data) {
    return (float)raw_data * 0.0288;
}

// Function to map lux value to brightness (0-255)
int map_lux_to_brightness(float lux) {
    float normalized_lux = lux / LUX_MAX;
    float gamma_corrected = pow(normalized_lux, 1.0 / GAMMA);
    int brightness = (int)(255.0 * gamma_corrected);
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    return brightness;
}

// Function to set LED brightness using PWM
int set_led_brightness(int brightness) {
    int pwm_value = (int)(((float)brightness / 255.0) * PWM_RANGE);
    gpioPWM(WS2812B_GPIO, pwm_value);
    return 0;
}

// Helper function to write a byte to an I2C register
int i2c_write_byte_data(int handle, uint8_t reg, uint8_t data) {
    return i2cWriteByteData(handle, reg, data);
}

// Helper function to read a word from an I2C register
int i2c_read_word_data(int handle, uint8_t reg, uint16_t *data) {
    return i2cReadWordData(handle, reg, (char*)data);
}

