    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0); // Bus 1, address 0x10, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700
    if (veml7700_init() != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(WS2812B_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(WS2812B_GPIO, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t raw_data;
    float lux;
    int brightness;

    // Main loop
    while (!terminate) {
        // Read data from VEML7700
        if (read_veml7700_data(&raw_data) == 0) {
            // Calculate lux value
            lux = calculate_lux(raw_data);

            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);

            // Set LED brightness
            set_led_brightness(brightness);

            // Print lux and brightness values
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Delay
        gpioDelay(200000); // 200 ms
    }

    // Cleanup
    set_led_brightness(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

