#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define constants
#define POLL_INTERVAL_MS 50
#define SELF_TEST_READS 5
#define SELF_TEST_DELAY_MS 100
#define LED_BLINK_DURATION_MS 500
#define ERROR_BLINK_DURATION_MS 100
#define ERROR_BUZZER_SHORT_MS 200
#define ERROR_BUZZER_LONG_MS 600
#define ERROR_PATTERN_REPEATS 3

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *flame_line, *buzzer_line, *led_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
int read_flame_sensor(void);
int activate_buzzer(void);
int deactivate_buzzer(void);
int activate_led(void);
int deactivate_led(void);
void log_event(const char *event);
void signal_handler(int sig);
void cleanup(void);
int self_test(void);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        terminate = 1;
    }
}

// GPIO initialization
int gpio_init(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        perror("Error getting flame sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Error getting buzzer line");
        gpiod_chip_close(chip);
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_detector", 0) < 0) {
        perror("Error requesting buzzer line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "flame_detector", 0) < 0) {
        perror("Error requesting LED line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(flame_line, "flame_detector") < 0) {
        perror("Error requesting flame sensor line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read flame sensor
int read_flame_sensor(void) {
    int value = gpiod_line_get_value(flame_line);
    if (value < 0) {
        perror("Error reading flame sensor value");
        return -1;
    }
    return value;
}

// Activate buzzer
int activate_buzzer(void) {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        perror("Error activating buzzer");
        return -1;
    }
    return 0;
}

// Deactivate buzzer
int deactivate_buzzer(void) {
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        perror("Error deactivating buzzer");
        return -1;
    }
    return 0;
}

// Activate LED
int activate_led(void) {
    if (gpiod_line_set_value(led_line, 1) < 0) {
        perror("Error activating LED");
        return -1;
    }
    return 0;
}

// Deactivate LED
int deactivate_led(void) {
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("Error deactivating LED");
        return -1;
    }
    return 0;
}

// Log event with timestamp
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, event);
}

// Self-test function
int self_test(void) {
    // Blink LED twice
    for (int i = 0; i < 2; i++) {
        if (activate_led() < 0) return -1;
        usleep(LED_BLINK_DURATION_MS * 1000);
        if (deactivate_led() < 0) return -1;
        usleep(LED_BLINK_DURATION_MS * 1000);
    }

    // Read flame sensor multiple times
    int low_count = 0;
    for (int i = 0; i < SELF_TEST_READS; i++) {
        int value = read_flame_sensor();
        if (value < 0) return -1;
        if (value == 0) {
            low_count++;
        }
        usleep(SELF_TEST_DELAY_MS * 1000);
    }

    // Check for sensor fault
    if (low_count == SELF_TEST_READS) {
        log_event("Self-test failed: Flame sensor consistently reads LOW.");
        return -1;
    }

    log_event("Self-test passed.");
    return 0;
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up GPIO lines...\n");
    if (flame_line) gpiod_line_release(flame_line);
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
}

int main(void) {
    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Run self-test
    if (self_test() < 0) {
        // Error pattern
        for (int i = 0; i < 5; i++) {
            activate_led();
            usleep(ERROR_BLINK_DURATION_MS * 1000);
            deactivate_led();
            usleep(ERROR_BLINK_DURATION_MS * 1000);
        }

        // Buzzer pattern
        for (int i = 0; i < ERROR_PATTERN_REPEATS; i++) {
            activate_buzzer();
            usleep(ERROR_BUZZER_SHORT_MS * 1000);
            deactivate_buzzer();
            usleep(ERROR_BUZZER_SHORT_MS * 1000);
            activate_buzzer();
            usleep(ERROR_BUZZER_LONG_MS * 1000);
            deactivate_buzzer();
            usleep(ERROR_BUZZER_SHORT_MS * 1000);
        }

        cleanup();
        return 1;
    }

    // Main loop
    int flame_detected = 0;
    while (!terminate) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            log_event("Error reading flame sensor, exiting...");
            break;
        }

        if (sensor_value == 0 && !flame_detected) {
            log_event("Flame detected!");
            activate_buzzer();
            activate_led();
            flame_detected = 1;
        } else if (sensor_value == 1 && flame_detected) {
            // Wait for sensor to read HIGH for POLL_INTERVAL_MS
            int high_count = 0;
            for (int i = 0; i < 5; i++) { // Check 5 times within POLL_INTERVAL_MS
                int value = read_flame_sensor();
                if (value < 0) {
                    log_event("Error reading flame sensor, exiting...");
                    break;
                }
                if (value == 1) {
                    high_count++;
                }
                usleep(POLL_INTERVAL_MS * 1000 / 5); // Divide POLL_INTERVAL_MS into 5 checks
            }

            if (high_count == 5) {
                log_event("Flame gone!");
                deactivate_buzzer();
                deactivate_led();
                flame_detected = 0;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

