#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio"
#define BUFFER_SIZE 60

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int i2c_setup(const char *device);
int bh1750_init(int fd);
int bh1750_read_raw(int fd, uint16_t *raw_value);
float raw_to_lux(uint16_t raw_value);
void circular_buffer_init(CircularBuffer *cb);
void circular_buffer_add(CircularBuffer *cb, float value);
float circular_buffer_average(CircularBuffer *cb);
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);
float calculate_blink_rate(float avg_lux);
void signal_handler(int signal);

// I2C setup function
int i2c_setup(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// BH1750 initialization function
int bh1750_init(int fd) {
    uint8_t mode = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &mode, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// BH1750 read raw value function
int bh1750_read_raw(int fd, uint16_t *raw_value) {
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }
    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Raw value to lux conversion function
float raw_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Circular buffer initialization function
void circular_buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    memset(cb->buffer, 0, sizeof(cb->buffer));
}

// Circular buffer add function
void circular_buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Circular buffer average function
float circular_buffer_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

