int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        perror("Error writing to GPIO direction file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO write function
int gpio_write(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }

    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d.  Must be 0 or 1.\n", value);
        close(fd);
        return -1;
    }

    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);

    if (write(fd, val_str, 1) != 1) {
        perror("Error writing to GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Calculate blink rate function
float calculate_blink_rate(float avg_lux) {
    float rate = 0.5 + (avg_lux / 1000.0) * 4.5;
    if (rate < 0.5) {
        rate = 0.5;
    } else if (rate > 5.0) {
        rate = 5.0;
    }
    return rate;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    CircularBuffer lux_buffer;
    uint16_t raw_value;
    float lux_value;
    float avg_lux;
    float blink_rate;
    struct timespec sleep_time;
    int i2c_retries = 3; // Number of retries for I2C read

    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_DEVICE);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed. Exiting.\n");
        return 1;
    }

    // Initialize BH1750
    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO export failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }
    if (gpio_set_direction(GPIO_PIN, "out") < 0) {
        fprintf(stderr, "GPIO direction setting failed. Exiting.\n");
        gpio_unexport(GPIO_PIN);
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    circular_buffer_init(&lux_buffer);

    // Main loop
    while (program_running) {
        // Read raw value from BH1750 with retries
        int read_success = 0;
        for (int i = 0; i < i2c_retries; i++) {
            if (bh1750_read_raw(i2c_fd, &raw_value) == 0) {
                read_success = 1;
                break;
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", i + 1, i2c_retries);
                usleep(10000); // Wait 10ms before retrying
            }
        }

        if (!read_success) {
            fprintf(stderr, "I2C read failed after multiple retries. Skipping sample.\n");
            sleep(1); // Wait 1 second before next sample
            continue;
        }

        // Convert raw value to lux
        lux_value = raw_to_lux(raw_value);

        // Add lux value to circular buffer
        circular_buffer_add(&lux_buffer, lux_value);

        // Calculate average lux
        avg_lux = circular_buffer_average(&lux_buffer);

        // Calculate blink rate
        blink_rate = calculate_blink_rate(avg_lux);

        // Blink LED
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = (long)(500.0 * 1000000.0 / blink_rate); // Half period in nanoseconds
        for (int i = 0; i < (int)(blink_rate * 2); i++) { // Blink for 1 second
            if (gpio_write(GPIO_PIN, 1) < 0) {
                fprintf(stderr, "GPIO write failed. Exiting.\n");
                program_running = 0;
                break;
            }
            nanosleep(&sleep_time, NULL);
            if (gpio_write(GPIO_PIN, 0) < 0) {
                fprintf(stderr, "GPIO write failed. Exiting.\n");
                program_running = 0;
                break;
            }
            nanosleep(&sleep_time, NULL);
        }

        // Wait 1 second
        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpio_unexport(GPIO_PIN);
    close(i2c_fd);

    return 0;
}

