#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define segment patterns for digits 0-9 (common cathode)
const unsigned char segment_patterns[] = {
    0b00111111, // 0
    0b00000110, // 1
    0b01011011, // 2
    0b01001111, // 3
    0b01100110, // 4
    0b01101101, // 5
    0b01111101, // 6
    0b00000111, // 7
    0b01111111, // 8
    0b01101111  // 9
};

// Global variables for GPIO lines and chip
struct gpiod_line *data_line = NULL;
struct gpiod_line *clock_line = NULL;
struct gpiod_line *latch_line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (data_line) {
        gpiod_line_release(data_line);
    }
    if (clock_line) {
        gpiod_line_release(clock_line);
    }
    if (latch_line) {
        gpiod_line_release(latch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to shift out data to the 74HC595
void shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        // Set data line
        int ret = gpiod_line_set_value(data_line, (data >> i) & 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting data line value: %d\n", ret);
            exit(1);
        }

        // Clock high
        ret = gpiod_line_set_value(clock_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting clock line high: %d\n", ret);
            exit(1);
        }
        struct timespec delay = {0, 1000}; // 1us delay
        nanosleep(&delay, NULL);

        // Clock low
        ret = gpiod_line_set_value(clock_line, 0);
        if (ret < 0) {
