    }
    exit(0);
}

int main() {
    int ret;
    struct gpiod_line_event event;
    struct timespec timeout;
    int led_state = 0; // 0: off, 1: on

    // Set up signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request LED line as output
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(led_line, "blink_button", 0); // Initial value: 0 (off)
    if (ret < 0) {
        perror("Error requesting LED line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request button line as input with pull-up
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(button_line, "blink_button");
    if (ret < 0) {
        perror("Error requesting button line as input");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request falling edge event detection on button line
    ret = gpiod_line_request_rising_edge_events(button_line, "blink_button");
    if (ret < 0) {
        perror("Error requesting rising edge events");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Blink LED with button monitoring
    while (1) {
        // Toggle LED state
        led_state = !led_state;
        ret = gpiod_line_set_value(led_line, led_state);
        if (ret < 0) {
            perror("Error setting LED value");
            gpiod_line_release(led_line);
            gpiod_line_release(button_line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Wait for 1 second
        sleep(1);

        // Check for button press (rising edge event)
        timeout.tv_sec = 1; // 1 second timeout
        timeout.tv_nsec = 0;

        ret = gpiod_line_event_wait(button_line, &timeout);
        if (ret > 0) {
            // Button pressed, stop blinking
            gpiod_line_set_value(led_line, 0); // Turn off LED
            printf("Button pressed! Stopping blinking.\n");
            break; // Exit the loop
        } else if (ret < 0) {
            perror("Error waiting for button event");
            gpiod_line_release(led_line);
            gpiod_line_release(button_line);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Clean up and exit
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

