#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_GPIO 5
#define BLINK_DELAY_MS 750

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

int main() {
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO5 as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Blinking LED on GPIO%d. Press Ctrl+C to exit.\n", LED_GPIO);

    while (program_running) {
        // Turn LED on
        gpioWrite(LED_GPIO, 1);
        printf("LED ON\n");
        fflush(stdout); // Ensure output is immediately visible
        gpioDelay(BLINK_DELAY_MS * 1000); // Delay in microseconds

        // Turn LED off
        gpioWrite(LED_GPIO, 0);
        printf("LED OFF\n");
        fflush(stdout); // Ensure output is immediately visible
        gpioDelay(BLINK_DELAY_MS * 1000); // Delay in microseconds
    }

    // Clean up before exiting
    gpioWrite(LED_GPIO, 0); // Ensure LED is off
    gpioTerminate(); // Terminate pigpio

    return 0;
}

