#define ADPD188BI_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define LED_GPIO 18
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_MS 500
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_als(uint16_t *als);
int read_color(uint16_t *red, uint16_t *green, uint16_t *blue);
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
void set_led_brightness(uint16_t als);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize the sensor
int initialize_sensor() {
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, MODE_REG, 0x01);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to MODE register: %s\n", strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Read ALS data
int read_als(uint16_t *als) {
    int result;
    int retries = 3;
    uint8_t lsb, msb;

    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, ALS_LSB_REG);
        if (result >= 0) {
            lsb = (uint8_t)result;
            result = i2cReadByteData(i2c_handle, ALS_MSB_REG);
            if (result >= 0) {
                msb = (uint8_t)result;
                *als = (msb << 8) | lsb;
                return 0; // Success
            } else {
                fprintf(stderr, "Error reading ALS MSB: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "Error reading ALS LSB: %s\n", strerror(errno));
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries--;
    }
    fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
    return -1; // Failure
}

// Read color data
int read_color(uint16_t *red, uint16_t *green, uint16_t *blue) {
    int result;
    int retries = 3;
    uint8_t red_lsb, red_msb, green_lsb, green_msb, blue_lsb, blue_msb;

    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, RED_REG);
        if (result >= 0) {
            red_lsb = (uint8_t)result;
            result = i2cReadByteData(i2c_handle, RED_REG + 1);
            if (result >= 0) {
                red_msb = (uint8_t)result;
                *red = (red_msb << 8) | red_lsb;

                result = i2cReadByteData(i2c_handle, GREEN_REG);
                if (result >= 0) {
                    green_lsb = (uint8_t)result;
                    result = i2cReadByteData(i2c_handle, GREEN_REG + 1);
                    if (result >= 0) {
                        green_msb = (uint8_t)result;
                        *green = (green_msb << 8) | green_lsb;

                        result = i2cReadByteData(i2c_handle, BLUE_REG);
                        if (result >= 0) {
                            blue_lsb = (uint8_t)result;
                            result = i2cReadByteData(i2c_handle, BLUE_REG + 1);
                            if (result >= 0) {
                                blue_msb = (uint8_t)result;
                                *blue = (blue_msb << 8) | blue_lsb;
                                return 0; // Success
                            } else {
                                fprintf(stderr, "Error reading BLUE MSB: %s\n", strerror(errno));
                            }
                        } else {
                            fprintf(stderr, "Error reading BLUE LSB: %s\n", strerror(errno));
                        }
                    } else {
                        fprintf(stderr, "Error reading GREEN MSB: %s\n", strerror(errno));
                    }
                } else {
                    fprintf(stderr, "Error reading GREEN LSB: %s\n", strerror(errno));
                }
            } else {
                fprintf(stderr, "Error reading RED MSB: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "Error reading RED LSB: %s\n", strerror(errno));
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries--;
    }
    fprintf(stderr, "Failed to read color data after multiple retries.\n");
    return -1; // Failure
}

// Log data to CSV file
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file); // Ensure data is written to file immediately
}

// Set LED brightness based on ALS value
void set_led_brightness(uint16_t als) {
    // Map ALS value (0-65535) to PWM duty cycle (0-255)
    int duty_cycle = (int)(((float)als / 65535.0) * PWM_RANGE);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    gpioPWM(LED_GPIO, duty_cycle);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(LED_GPIO, 0); // Turn off LED
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    uint16_t als, red, green, blue;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_als(&als) == 0 && read_color(&red, &green, &blue) == 0) {
            // Log data
            log_data(als, red, green, blue);

            // Set LED brightness
            set_led_brightness(als);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

