    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    // Combine MSB and LSB, shift right by 2 bits, and convert to g
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2;
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

    *x = (float)raw_x / SENSITIVITY * GRAVITY;
    *y = (float)raw_y / SENSITIVITY * GRAVITY;
    *z = (float)raw_z / SENSITIVITY * GRAVITY;

    return 0;
}

// Calculates the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Logs impact data to a file
void log_impact(float x, float y, float z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                log_impact(x, y, z, magnitude);
                printf("Impact detected! Magnitude: %.3f m/s^2\n", magnitude);
            }
        }

        // Delay for 50 ms
        gpioDelay(SAMPLE_PERIOD * 1000); // pigpioDelay takes microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

