#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F
#define WHO_AM_I_VALUE 0xD3
#define SAMPLE_RATE 20 // Hz
#define SAMPLE_PERIOD (1.0 / SAMPLE_RATE) // seconds
#define CALIBRATION_SAMPLES 100
#define ALERT_THRESHOLD 50.0 // dps
#define SENSITIVITY 0.00875 // dps/LSB

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static double x_offset = 0.0;
static double y_offset = 0.0;
static double z_offset = 0.0;

// Function prototypes
int i2c_write_reg(int fd, unsigned char reg, unsigned char value);
int i2c_read_reg(int fd, unsigned char reg, unsigned char *value);
int i2c_read_block(int fd, unsigned char reg, unsigned char *data, int len);
int gyro_init(int fd);
int gyro_read_raw(int fd, int16_t *x, int16_t *y, int16_t *z);
double gyro_calibrate(int fd);
void gyro_log_data(FILE *fp, double x, double y, double z);
void signal_handler(int sig);
int check_sensor_presence(int fd);

// I2C write function
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C block read function
int i2c_read_block(int fd, unsigned char reg, unsigned char *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading block from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Gyroscope initialization function
int gyro_init(int fd) {
    // Check sensor presence
    if (check_sensor_presence(fd) != 0) {
        fprintf(stderr, "Gyroscope not found.\n");
        return -1;
    }

    // Configure CTRL_REG1
    if (i2c_write_reg(fd, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Error configuring CTRL_REG1.\n");
        return -1;
    }

    // Configure CTRL_REG4
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Error configuring CTRL_REG4.\n");
        return -1;
    }

    return 0;
}

// Gyroscope read raw data function
int gyro_read_raw(int fd, int16_t *x, int16_t *y, int16_t *z) {
    unsigned char data[6];

    if (i2c_read_block(fd, OUT_X_L, data, 6) != 0) {
        fprintf(stderr, "Error reading raw data.\n");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Gyroscope calibration function
double gyro_calibrate(int fd) {
    int16_t x, y, z;
    double x_sum = 0.0, y_sum = 0.0, z_sum = 0.0;

    printf("Calibrating gyroscope... Please keep the sensor stationary.\n");
    sleep(2); // Allow time for the sensor to settle

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (gyro_read_raw(fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Error reading raw data during calibration.\n");
            return 0.0; // Return 0.0 to avoid further issues
        }
        x_sum += x;
        y_sum += y;
        z_sum += z;
        usleep((int)(SAMPLE_PERIOD * 1000000)); // Sleep for the sample period
    }

    x_offset = x_sum / CALIBRATION_SAMPLES;
    y_offset = y_sum / CALIBRATION_SAMPLES;
    z_offset = z_sum / CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", x_offset, y_offset, z_offset);
    return 0.0; // Return 0.0 to indicate success
}

// Gyroscope log data function
void gyro_log_data(FILE *fp, double x, double y, double z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

// Check sensor presence function
int check_sensor_presence(int fd) {
    unsigned char who_am_i;

    if (i2c_read_reg(fd, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register.\n");
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    printf("Gyroscope found with WHO_AM_I value: 0x%02X\n", who_am_i);
    return 0;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = (long)(SAMPLE_PERIOD * 1000000000); // Convert seconds to nanoseconds

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize gyroscope
    if (gyro_init(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Calibrate gyroscope
    gyro_calibrate(i2c_fd);

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int16_t raw_x, raw_y, raw_z;
    double x_dps, y_dps, z_dps;

    // Main loop
    while (keep_running) {
        // Read raw data
        if (gyro_read_raw(i2c_fd, &raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees per second
            x_dps = (raw_x - x_offset) * SENSITIVITY;
            y_dps = (raw_y - y_offset) * SENSITIVITY;
            z_dps = (raw_z - z_offset) * SENSITIVITY;

            // Log data
            gyro_log_data(log_file, x_dps, y_dps, z_dps);

            // Check for alerts
            if (fabs(x_dps) > ALERT_THRESHOLD || fabs(y_dps) > ALERT_THRESHOLD || fabs(z_dps) > ALERT_THRESHOLD) {
                fprintf(stderr, "ALERT: High angular velocity detected!\n");
                fprintf(log_file, "ALERT: High angular velocity detected! X=%.2f, Y=%.2f, Z=%.2f\n", x_dps, y_dps, z_dps);
                fflush(log_file);
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data.\n");
        }

        // Sleep for the sample period
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

