#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL345 Registers
#define ADXL345_DEVID   0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32

// I2C Address
#define ADXL345_ADDRESS 0x53

// GPIO Pin for LED
#define LED_PIN 17

// Scaling factor for ±2g range (3.9 mg/LSB)
#define SCALE_FACTOR 0.0039

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_adxl345();
accelerometer_data_t read_accelerometer_data();
void log_data(accelerometer_data_t data);
void control_led(accelerometer_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the ADXL345
int initialize_adxl345() {
    // Verify DEVID register
    int devid = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading DEVID register: %d\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Error: Invalid DEVID (0x%X)\n", devid);
        return -1;
    }

    // Set full resolution and ±2g range
    int config = i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, 0x08);
    if (config < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register: %d\n", config);
        return -1;
    }

    // Enable measurement mode
    int power_ctl = i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08);
    if (power_ctl < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register: %d\n", power_ctl);
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char raw_data[6];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw_data, 6);

    if (bytes_read != 6) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", bytes_read);
        data.x = 0.0; // Indicate error
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes, convert to g units
    int16_t x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
