#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// LSM303DLHC I2C addresses
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define MR_REG_M 0x02
#define OUT_X_L_A 0x28
#define OUT_X_H_M 0x03

// Sensitivity values (adjust as needed based on your sensor's datasheet)
#define ACCEL_SENSITIVITY 0.001 // 1 mg/LSB = 0.001 g/LSB
#define MAG_SENSITIVITY 0.0014  // 0.08 mGauss/LSB = 0.0014 Gauss/LSB

// Global variables for I2C handles and program state
int accel_handle = -1;
int mag_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_accelerometer(int handle);
int init_magnetometer(int handle);
int read_accelerometer_data(int handle, float *x, float *y, float *z);
int read_magnetometer_data(int handle, float *x, float *y, float *z);
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the accelerometer
int init_accelerometer(int handle) {
    if (i2cWriteByteData(handle, CTRL_REG1_A, 0x27) != 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A\n");
        return -1;
    }
    return 0;
}

// Initialize the magnetometer
int init_magnetometer(int handle) {
    if (i2cWriteByteData(handle, MR_REG_M, 0x00) != 0) {
        fprintf(stderr, "Error writing to magnetometer MR_REG_M\n");
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integers
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g's
    *x = (float)raw_x * ACCEL_SENSITIVITY;
    *y = (float)raw_y * ACCEL_SENSITIVITY;
    *z = (float)raw_z * ACCEL_SENSITIVITY;

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integers
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to Gauss
    *x = (float)raw_x * MAG_SENSITIVITY;
    *y = (float)raw_y * MAG_SENSITIVITY;
    *z = (float)raw_z * MAG_SENSITIVITY;

    return 0;
}

// Calculate tilt-compensated heading
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float mag_x_comp = mag_x * cos(pitch) + mag_z * sin(pitch);
    float mag_y_comp = mag_x * sin(roll) * sin(pitch) + mag_y * cos(roll) - mag_z * sin(roll) * cos(pitch);

    float heading = atan2(mag_y_comp, mag_x_comp) * 180 / M_PI;

    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Log data to file
void log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles
    accel_handle = i2cOpen(1, ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Error opening I2C device for accelerometer: %d\n", accel_handle);
        gpioTerminate();
        return 1;
    }

    mag_handle = i2cOpen(1, MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Error opening I2C device for magnetometer: %d\n", mag_handle);
        i2cClose(accel_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (init_accelerometer(accel_handle) != 0) {
        fprintf(stderr, "Accelerometer initialization failed\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    if (init_magnetometer(mag_handle) != 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the log file is new and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
    float heading;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_accelerometer_data(accel_handle, &accel_x, &accel_y, &accel_z) != 0) {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (read_magnetometer_data(mag_handle, &mag_x, &mag_y, &mag_z) != 0) {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate heading
        heading = calculate_heading(accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);

        // Log data
        log_data(heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);

        // Wait 100 ms
        gpioDelay(100);
    }

    // Close I2C handles and log file
    i2cClose(accel_handle);
    i2cClose(mag_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

