        // Wait 100 ms
        gpioDelay(100);
    }

    // Close I2C handles and log file
    i2cClose(accel_handle);
    i2cClose(mag_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

