#define VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define VL6180X_REG_SYSTEM_MODE_GPIO1 0x010
#define VL6180X_REG_SYSRANGE_START 0x018
#define VL6180X_REG_RESULT_RANGE_STATUS 0x04D
#define VL6180X_REG_RESULT_RANGE_VAL 0x062

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl6180x_init();
int read_distance();
void log_data(int distance, const char *status);
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// VL6180X initialization function
int vl6180x_init() {
    // Mandatory initialization sequence
    if (i2cWriteByteData(i2c_handle, 0x016, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x016\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x010, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x010\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x018, 0x01) < 0) {
        fprintf(stderr, "Error writing to register 0x018\n");
        return -1;
    }

    return 0;
}

// Function to read distance from VL6180X
int read_distance() {
    int range_status, distance;

    // Start a range measurement
    if (i2cWriteByteData(i2c_handle, VL6180X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting range measurement\n");
        return -1;
    }

    // Wait for measurement to complete (adjust delay as needed)
    gpioDelay(5000); // 5ms

    // Read range status
    range_status = i2cReadByteData(i2c_handle, VL6180X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance
    distance = i2cReadByteData(i2c_handle, VL6180X_REG_RESULT_RANGE_VAL);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

