    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        distance = read_distance();

        if (distance >= 0) {
            if (distance < 100) {
                door_status = "DOOR_OPEN";
            } else {
                door_status = "DOOR_CLOSED";
            }
            log_data(distance, door_status);
        } else {
            fprintf(stderr, "Error reading distance, attempting re-initialization...\n");
            log_data(-1, "ERROR");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // Wait 1 second before re-initializing
            i2c_handle = i2cOpen(I2C_BUS, VL6180X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (vl6180x_init() < 0) {
                    fprintf(stderr, "VL6180X re-initialization failed\n");
                    terminate = 1;
                }
            }
        }

        gpioDelay(100000); // 100ms delay
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

