#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor I2C addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define I2C bus
#define I2C_BUS 1

// Define control register address
#define CONTROL_REG 0x00

// Define data register address
#define DATA_REG 0x01

// Define enable measurement value
#define ENABLE_MEASUREMENT 0x80

// Define sampling interval (10 ms)
#define SAMPLING_INTERVAL 10000 // microseconds

// Define log file name
#define LOG_FILE "audio_log.dat"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data and timestamp
typedef struct {
    int16_t sensor1_data;
    int16_t sensor2_data;
    int tdoa;
    struct timespec timestamp;
} sensor_data_t;

// Function prototypes
int initialize_i2c(int bus, int addr);
int configure_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle);
int16_t convert_to_signed_16bit(uint16_t raw_data);
int calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data);
int log_data(FILE *fp, struct timespec ts, int16_t sensor1_data, int16_t sensor2_data, int tdoa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to configure the sensor
int configure_sensor(int i2c_handle) {
    int result = i2cWriteByteData(i2c_handle, CONTROL_REG, ENABLE_MEASUREMENT);
    if (result < 0) {
        fprintf(stderr, "Error writing to control register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle) {
    int raw_data = i2cReadWordData(i2c_handle, DATA_REG);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", raw_data);
        return -1;
    }
    return raw_data;
}

// Function to convert raw data to signed 16-bit integer
int16_t convert_to_signed_16bit(uint16_t raw_data) {
    return (int16_t)raw_data;
}

// Function to calculate TDOA
int calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data) {
    return sensor1_data - sensor2_data;
}

// Function to log data to file
int log_data(FILE *fp, struct timespec ts, int16_t sensor1_data, int16_t sensor2_data, int tdoa) {
    if (fprintf(fp, "%ld,%ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, sensor1_data, sensor2_data, tdoa) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Configure both sensors
    if (configure_sensor(i2c_handle1) < 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (configure_sensor(i2c_handle2) < 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    // Main loop
    while (!terminate) {
        sensor_data_t data;
        struct timespec ts;

        // Read sensor data
        int raw_sensor1_data = read_sensor_data(i2c_handle1);
        int raw_sensor2_data = read_sensor_data(i2c_handle2);

        if (raw_sensor1_data >= 0 && raw_sensor2_data >= 0) {
            // Convert raw data to signed 16-bit integers
            data.sensor1_data = convert_to_signed_16bit((uint16_t)raw_sensor1_data);
            data.sensor2_data = convert_to_signed_16bit((uint16_t)raw_sensor2_data);

            // Calculate TDOA
            data.tdoa = calculate_tdoa(data.sensor1_data, data.sensor2_data);

            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                // Log data
                if (log_data(log_file, ts, data.sensor1_data, data.sensor2_data, data.tdoa) < 0) {
                    terminate = 1; // Stop logging on error
                }
            } else {
                fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
                terminate = 1; // Stop logging on error
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping sample.\n");
        }

        // Delay for sampling interval
        gpioDelay(SAMPLING_INTERVAL);
    }

    // Close I2C handles and log file
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

