#define Y_ACCEL 0x0C
#define Z_ACCEL 0x0E

// Sensitivities
#define GYRO_SENSITIVITY 0.005  // deg/sec/LSB
#define ACCEL_SENSITIVITY 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0b11000000000 // SPI_MODE_3 (CPOL=1, CPHA=1), 16-bit words

// Global Variables
static int spi_handle;
static FILE *fp;
static volatile int running = 1;

// Function Prototypes
int read_register(int handle, uint8_t reg);
int write_register(int handle, uint8_t reg, uint16_t value);
int read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z);
int log_data(FILE *fp, struct timespec ts, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void cleanup(int signum);

// Function to read a single register from the ADIS16488A
int read_register(int handle, uint8_t reg) {
    char tx[2], rx[2];
    tx[0] = 0x00; // MSB is 0 for read
    tx[1] = reg;  // Register address

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed in read_register: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(40); // Stall for 40 microseconds

    tx[0] = 0x00; // Dummy read
    tx[1] = 0x00; // Dummy read

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed in read_register (dummy read): %s\n", strerror(errno));
        return -1;
    }

    return (rx[0] << 8) | rx[1]; // Combine the two bytes into a 16-bit value
}

// Function to write a single register to the ADIS16488A
int write_register(int handle, uint8_t reg, uint16_t value) {
    char tx[3];
    tx[0] = 0x80; // MSB is 1 for write
    tx[1] = reg;  // Register address
    tx[2] = value & 0xFF; //LSB

    if (spiXfer(handle, tx, NULL, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed in write_register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read IMU data and convert to physical units
int read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    raw_gyro_x = read_register(handle, X_GYRO);
    raw_gyro_y = read_register(handle, Y_GYRO);
    raw_gyro_z = read_register(handle, Z_GYRO);
    raw_accel_x = read_register(handle, X_ACCEL);
    raw_accel_y = read_register(handle, Y_ACCEL);
    raw_accel_z = read_register(handle, Z_ACCEL);

    if (raw_gyro_x == -1 || raw_gyro_y == -1 || raw_gyro_z == -1 ||
        raw_accel_x == -1 || raw_accel_y == -1 || raw_accel_z == -1) {
        fprintf(stderr, "Error: Failed to read IMU data.\n");
        return -1;
