void cleanup(int signum) {
    printf("Cleaning up and exiting...\n");
    running = 0;
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
}

