    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    // Register cleanup function
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop
    while (running) {
        // Read IMU data
        result = read_imu_data(spi_handle, &gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z);
        if (result != 0) {
            fprintf(stderr, "Error: Failed to read IMU data. Skipping sample.\n");
            gpioDelay(100); // Delay for 100ms
            continue;
        }

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Error: Failed to get timestamp: %s\n", strerror(errno));
            gpioDelay(100); // Delay for 100ms
            continue;
        }

        // Log data to CSV file
        if (log_data(fp, ts, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z) != 0) {
            fprintf(stderr, "Error: Failed to log data. Skipping sample.\n");
        }

        // Delay for 100ms (non-blocking)
        int start_time = time(NULL);
        while (time(NULL) - start_time < 0.1 && running) {
            gpioDelay(1); // Check every 1ms
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    cleanup(0);

    return 0;
}

