#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>

// Define constants
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_MODE 3
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define GYRO_SCALE 0.02  // dps/LSB
#define ACCL_SCALE 0.00025 // g/LSB

// Register addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t address, uint16_t *data);
void read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z, float *accl_x, float *accl_y, float *accl_z);
void log_data(float gyro_x, float gyro_y, float gyro_z, float accl_x, float accl_y, float accl_z);
void signal_handler(int sig);
int gpio_init(void);
void gpio_set_cs(int level);
void gpio_release(void);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// SPI initialization function
int spi_init(void) {
    char spi_device_path[20];
    snprintf(spi_device_path, sizeof(spi_device_path), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);

    spi_fd = open(spi_device_path, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t address, uint16_t *data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Set MSB for read operation
    address |= 0x80;
    tx_buf[0] = address;
    tx_buf[1] = 0x00; // Dummy byte for reading

    struct spi_ioc_transfer transfer[2];
    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)NULL; // No receive on first transfer
    transfer[0].len = 1;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    transfer[1].tx_buf = (unsigned long)NULL; // No transmit on second transfer
    transfer[1].rx_buf = (unsigned long)rx_buf;
    transfer[1].len = 2; // Read 2 bytes
    transfer[1].speed_hz = SPI_SPEED;
    transfer[1].bits_per_word = 8;

    gpio_set_cs(0); // Assert CS
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        gpio_set_cs(1); // De-assert CS
        return -1;
    }
    gpio_set_cs(1); // De-assert CS

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Read IMU data function
void read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z, float *accl_x, float *accl_y, float *accl_z) {
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accl_x, raw_accl_y, raw_accl_z;

    if (spi_transfer(XGYRO_OUT, &raw_gyro_x) != 0) return;
    if (spi_transfer(YGYRO_OUT, &raw_gyro_y) != 0) return;
    if (spi_transfer(ZGYRO_OUT, &raw_gyro_z) != 0) return;
    if (spi_transfer(XACCL_OUT, &raw_accl_x) != 0) return;
    if (spi_transfer(YACCL_OUT, &raw_accl_y) != 0) return;
    if (spi_transfer(ZACCL_OUT, &raw_accl_z) != 0) return;

    *gyro_x = (float)((int16_t)raw_gyro_x) * GYRO_SCALE;
    *gyro_y = (float)((int16_t)raw_gyro_y) * GYRO_SCALE;
    *gyro_z = (float)((int16_t)raw_gyro_z) * GYRO_SCALE;
    *accl_x = (float)((int16_t)raw_accl_x) * ACCL_SCALE;
    *accl_y = (float)((int16_t)raw_accl_y) * ACCL_SCALE;
    *accl_z = (float)((int16_t)raw_accl_z) * ACCL_SCALE;
}

// Log data function
void log_data(float gyro_x, float gyro_y, float gyro_z, float accl_x, float accl_y, float accl_z) {
    printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps | Accel: X=%.2f g, Y=%.2f g, Z=%.2f g\n",
           gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z);
}

// GPIO initialization function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_PIN);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "imu_cs", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Set chip select function
void gpio_set_cs(int level) {
    gpiod_line_set_value(cs_line, level);
}

// Release GPIO resources function
void gpio_release(void) {
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        gpio_release();
        return EXIT_FAILURE;
    }

    float gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z;

    // Main loop
    while (!terminate) {
        read_imu_data(&gyro_x, &gyro_y, &gyro_z, &accl_x, &accl_y, &accl_z);
        log_data(gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z);
        usleep(100000); // 100 ms
    }

    // Cleanup
    close(spi_fd);
    gpio_release();

    fprintf(stderr, "Program terminated successfully.\n");
    return EXIT_SUCCESS;
}

