#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16448 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec/LSB
#define ACCL_SCALE 0.00025 // g/LSB

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

// Function to read a 16-bit register from the ADIS16448
int16_t read_adis16448_register(int spi_handle, uint8_t register_address) {
    char tx_buffer[2];
    char rx_buffer[2];
    int status;

    // Set bit 15 of the register address to indicate a read operation
    tx_buffer[0] = (register_address | 0x8000) >> 8; // MSB
    tx_buffer[1] = (register_address | 0x8000) & 0xFF; // LSB

    // Perform the first SPI transfer
    status = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    if (status != 0) {
        fprintf(stderr, "Error during first SPI transfer: %d\n", status);
        return -1; // Indicate an error
    }

    // Stall for at least 40 microseconds
    gpioDelay(40);

    // Prepare the dummy transfer (0x0000)
    tx_buffer[0] = 0x00;
    tx_buffer[1] = 0x00;

    // Perform the second SPI transfer
    status = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);
    if (status != 0) {
        fprintf(stderr, "Error during second SPI transfer: %d\n", status);
        return -1; // Indicate an error
    }

    // Combine the received bytes into a 16-bit value
    int16_t data = (rx_buffer[0] << 8) | rx_buffer[1];

    return data;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("ADIS16448 IMU Reader\n");

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        int16_t gyro_x_raw = read_adis16448_register(spi_handle, X_GYRO_OUT);
        int16_t gyro_y_raw = read_adis16448_register(spi_handle, Y_GYRO_OUT);
        int16_t gyro_z_raw = read_adis16448_register(spi_handle, Z_GYRO_OUT);

        // Read accelerometer data
        int16_t accl_x_raw = read_adis16448_register(spi_handle, X_ACCL_OUT);
        int16_t accl_y_raw = read_adis16448_register(spi_handle, Y_ACCL_OUT);
        int16_t accl_z_raw = read_adis16448_register(spi_handle, Z_ACCL_OUT);

        // Check for read errors
        if (gyro_x_raw == -1 || gyro_y_raw == -1 || gyro_z_raw == -1 ||
            accl_x_raw == -1 || accl_y_raw == -1 || accl_z_raw == -1) {
            fprintf(stderr, "Error reading IMU data, retrying...\n");
            gpioDelay(10); // Small delay before retrying
            continue;       // Skip to the next iteration
        }

        // Convert raw data to physical units
        float gyro_x = gyro_x_raw * GYRO_SCALE;
        float gyro_y = gyro_y_raw * GYRO_SCALE;
        float gyro_z = gyro_z_raw * GYRO_SCALE;
        float accl_x = accl_x_raw * ACCL_SCALE;
        float accl_y = accl_y_raw * ACCL_SCALE;
        float accl_z = accl_z_raw * ACCL_SCALE;

        // Print the data
        printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s | Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
               gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z);

        // Wait 100 ms
        gpioDelay(100);
    }

    // Close SPI handle and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

