int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result, retries = 3;
    while (retries > 0) {
        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            perror("Failed to write to register");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "Failed to write to register after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to initialize the MPU-6886
int init_mpu6886(int fd) {
    int who_am_i;

    // Verify sensor presence
    who_am_i = i2c_read_reg(fd, WHO_AM_I);
    if (who_am_i != 0x86) {
        fprintf(stderr, "MPU-6886 not found. WHO_AM_I = 0x%x\n", who_am_i);
        return -1;
    }
    printf("MPU-6886 found!\n");

    // Wake up the sensor
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake up MPU-6886\n");
        return -1;
    }

    // Set accelerometer range to +-2g
    if (i2c_write_reg(fd, ACCEL_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        return -1;
    }

    // Set gyroscope range to +-250 dps
    if (i2c_write_reg(fd, GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Failed to set gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read raw accelerometer and gyroscope data
int read_raw_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buf[14];
    int result, retries = 3;
    uint8_t reg = ACCEL_XOUT_H;

    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address for reading data");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }
        result = read(fd, buf, 14);
        if (result == 14) {
            *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
            *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
            *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
            *gyro_x = (int16_t)((buf[8] << 8) | buf[9]);
            *gyro_y = (int16_t)((buf[10] << 8) | buf[11]);
            *gyro_z = (int16_t)((buf[12] << 8) | buf[13]);
            return 0; // Success
        } else {
            perror("Failed to read data");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    fprintf(stderr, "Failed to read data after multiple retries.\n");
    return -1; // Indicate failure
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6886
    if (init_mpu6886(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6886 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 50000000; // 50ms

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    while (1) {
        if (read_raw_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            printf("Accel: X=%d, Y=%d, Z=%d  Gyro: X=%d, Y=%d, Z=%d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        nanosleep(&sleep_time, NULL);
    }

    // This point will not be reached due to the infinite loop, but included for completeness
    close(i2c_fd);
    return 0;
}

