#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// ADXL345 Registers
#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36
#define ADXL345_ID 0x00

// GPIO Pin for LED
#define LED_PIN 17

// I2C Bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int initialize_adxl345();
accelerometer_data_t read_accelerometer_data();
double calculate_magnitude(accelerometer_data_t data);
void log_impact(accelerometer_data_t data, double magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the ADXL345
int initialize_adxl345() {
    // Verify device ID
    int device_id = i2cReadByteData(i2c_handle, ADXL345_ID);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%X\n", device_id);
        return -1;
    }

    // Set to full resolution mode and +-2g range
    int status = i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, 0x0B);
    if (status < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register: %d\n", status);
        return -1;
    }

    // Enable measurement mode
    status = i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08);
    if (status < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char raw_data[6];

    int status = i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw_data, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", status);
        data.x = 0; data.y = 0; data.z = 0; // Return 0s on error
        return data;
    }

    data.x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    data.y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    data.z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    return data;
}

// Function to calculate the magnitude of the acceleration vector
double calculate_magnitude(accelerometer_data_t data) {
    double x = (double)data.x / 256.0;
    double y = (double)data.y / 256.0;
    double z = (double)data.z / 256.0;
    return sqrt(x * x + y * y + z * z);
}

// Function to log impact data to a file
void log_impact(accelerometer_data_t data, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Magnitude: %.2f g, X: %d, Y: %d, Z: %d\n",
            timestamp, magnitude, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (initialize_adxl345() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        double magnitude = calculate_magnitude(data);

        if (magnitude > 2.5) {
            printf("Impact detected! Magnitude: %.2f g\n", magnitude);
            gpioWrite(LED_PIN, 1); // Turn on LED
            gpioDelay(500);         // Wait 500 ms
            gpioWrite(LED_PIN, 0); // Turn off LED
            log_impact(data, magnitude);
        }

        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

