#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I 0x0D
#define WHO_AM_I_VALUE 0x1A
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define XOUT_L 0x01
#define XOUT_H 0x02
#define YOUT_L 0x03
#define YOUT_H 0x04
#define ZOUT_L 0x05
#define ZOUT_H 0x06
#define LED_GPIO 17 // BCM numbering
#define THRESHOLD 2.0f
#define LED_ON_TIME_MS 500
#define POLL_INTERVAL_MS 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, unsigned char reg);
int i2c_write_register(int fd, unsigned char reg, unsigned char value);
int read_acceleration_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void control_led(int on);
void log_impact(float magnitude);
void signal_handler(int sig);
int setup();
void cleanup();

// I2C read register function
int i2c_read_register(int fd, unsigned char reg) {
    unsigned char buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return buf[0];
}

// I2C write register function
int i2c_write_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register");
        return -1;
    }
    return 0;
}

// Read acceleration data function
int read_acceleration_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    unsigned char buf[6];
    buf[0] = XOUT_L | 0x80; // Read multiple bytes starting from XOUT_L

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address for multi-read");
        return -1;
    }

    if (read(fd, buf, 6) != 6) {
        perror("Failed to read acceleration data");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Calculate magnitude function
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 1024.0f;
    float y_g = (float)y / 1024.0f;
    float z_g = (float)z / 1024.0f;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Control LED function
void control_led(int on) {
    int ret = gpiod_line_set_value(gpio_line, on);
    if (ret < 0) {
        perror("Failed to set LED value");
    }
}

// Log impact function
void log_impact(float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: Impact detected! Magnitude: %.2f\n", timestamp, magnitude);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup function
int setup() {
    // I2C setup
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    // Verify sensor identity
    int who_am_i = i2c_read_register(i2c_fd, WHO_AM_I);
    if (who_am_i < 0 || who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        close(i2c_fd);
        return -1;
    }

    // Initialize accelerometer (active mode, 800 Hz)
    if (i2c_write_register(i2c_fd, CTRL_REG1, 0x01) < 0) return -1; // Active mode, 800 Hz
    if (i2c_write_register(i2c_fd, CTRL_REG2, 0x00) < 0) return -1; // +/- 2g range

    // GPIO setup
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "accelerometer_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return -1;
    }

    // Log file setup
    log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup
    if (setup() < 0) {
        fprintf(stderr, "Setup failed, exiting.\n");
        return 1;
    }

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration_data(i2c_fd, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > THRESHOLD) {
                control_led(1); // Turn LED on
                log_impact(magnitude);
                usleep(LED_ON_TIME_MS * 1000); // Wait for 500ms
                control_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        usleep(POLL_INTERVAL_MS * 1000); // Poll every 100ms
    }

    // Cleanup
    cleanup();

    return 0;
}

