#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TMAG5273_ADDR 0x35
#define X_REG 0x10
#define Y_REG 0x11
#define Z_REG 0x12
#define SENSITIVITY 0.1 // mGauss/LSB
#define LOG_FILE "magnetic_field_log.csv"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
sensor_data_t read_sensor_data(int fd);
char* format_data_for_csv(sensor_data_t data);
int write_to_log(const char *data);
void signal_handler(int sig);
int check_file_exists(const char *filename);

// I2C read function
int i2c_read_word(int fd, uint8_t reg) {
    int result;
    uint8_t buffer[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buffer, 2) != 2) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }

    result = (buffer[1] << 8) | buffer[0];
    return result;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;

    if (write(fd, buffer, 2) != 2) {
        fprintf(stderr, "Error writing data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data(int fd) {
    sensor_data_t data;
    int16_t raw_x, raw_y, raw_z;

    raw_x = i2c_read_word(fd, X_REG);
    raw_y = i2c_read_word(fd, Y_REG);
    raw_z = i2c_read_word(fd, Z_REG);

    if (raw_x == -1 || raw_y == -1 || raw_z == -1) {
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        fprintf(stderr, "Error reading sensor data.\n");
        return data;
    }

    data.x = (float)raw_x * SENSITIVITY;
    data.y = (float)raw_y * SENSITIVITY;
    data.z = (float)raw_z * SENSITIVITY;

    return data;
}

// Function to format data for CSV
char* format_data_for_csv(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    static char buffer[256]; // Static buffer to avoid memory allocation issues

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", t);
    snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), ",%.2f,%.2f,%.2f\n", data.x, data.y, data.z);

    return buffer;
}

// Function to write data to log file
int write_to_log(const char *data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s", data) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    terminate = 1;
}

// Function to check if a file exists
int check_file_exists(const char *filename) {
    if (access(filename, F_OK) == 0) {
        return 1; // File exists
    } else {
        return 0; // File does not exist
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data(i2c_fd);
        char *csv_data = format_data_for_csv(data);
        if (write_to_log(csv_data) != 0) {
            fprintf(stderr, "Error writing data to log.\n");
        }
        sleep(1);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

