#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_ID_REG 0x00
#define ADXL345_ID_VALUE 0xE5
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_MAP 0x2F
#define ADXL345_THRESH_FF 0x28
#define ADXL345_TIME_FF 0x29
#define ADXL345_INT_SOURCE 0x30

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

#define THRESH_FF_VALUE 0x0A // ~300 mg
#define TIME_FF_VALUE 0x20   // ~100 ms

#define FREEFALL_LOG_FILE "freefall_log.csv"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_block_read(int fd, uint8_t reg, uint8_t *data, int len);
int adxl345_init(int fd);
int adxl345_configure_freefall(int fd);
int adxl345_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
void log_freefall_event(int16_t x, int16_t y, int16_t z);
void interrupt_handler();
void signal_handler(int sig);
int setup_gpio_interrupt();
void cleanup();

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
  uint8_t buf[2];
  buf[0] = reg;
  buf[1] = value;

  if (write(fd, buf, 2) != 2) {
    perror("I2C write failed");
    return -1;
  }
  return 0;
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
  if (write(fd, &reg, 1) != 1) {
    perror("I2C write (register select) failed");
    return -1;
  }

  if (read(fd, value, 1) != 1) {
    perror("I2C read failed");
    return -1;
  }
  return 0;
}

// I2C block read function
int i2c_block_read(int fd, uint8_t reg, uint8_t *data, int len) {
  if (write(fd, &reg, 1) != 1) {
    perror("I2C write (register select) failed");
    return -1;
  }

  if (read(fd, data, len) != len) {
    perror("I2C block read failed");
    return -1;
  }
  return 0;
}

// ADXL345 initialization function
int adxl345_init(int fd) {
  uint8_t id;

  // Verify device ID
  if (i2c_read_reg(fd, ADXL345_ID_REG, &id) != 0) {
    fprintf(stderr, "Failed to read ADXL345 ID\n");
    return -1;
  }

  if (id != ADXL345_ID_VALUE) {
    fprintf(stderr, "Incorrect ADXL345 ID: 0x%02X\n", id);
    return -1;
  }

  // Set to standby mode
  if (i2c_write_reg(fd, ADXL345_POWER_CTL, 0x00) != 0) {
    fprintf(stderr, "Failed to set standby mode\n");
    return -1;
  }

  // Configure data format (full resolution, +/- 2g range)
  if (i2c_write_reg(fd, ADXL345_DATA_FORMAT, 0x0B) != 0) {
    fprintf(stderr, "Failed to set data format\n");
    return -1;
  }

  return 0;
}

// ADXL345 freefall configuration function
int adxl345_configure_freefall(int fd) {
  // Set freefall threshold
  if (i2c_write_reg(fd, ADXL345_THRESH_FF, THRESH_FF_VALUE) != 0) {
    fprintf(stderr, "Failed to set freefall threshold\n");
    return -1;
  }

  // Set freefall time
  if (i2c_write_reg(fd, ADXL345_TIME_FF, TIME_FF_VALUE) != 0) {
    fprintf(stderr, "Failed to set freefall time\n");
    return -1;
  }

  // Enable freefall interrupt
  if (i2c_write_reg(fd, ADXL345_INT_ENABLE, 0x04) != 0) {
    fprintf(stderr, "Failed to enable freefall interrupt\n");
    return -1;
  }

  // Map interrupt to INT1
  if (i2c_write_reg(fd, ADXL345_INT_MAP, 0x00) != 0) {
    fprintf(stderr, "Failed to map interrupt to INT1\n");
    return -1;
  }

  return 0;
}

// ADXL345 acceleration data reading function
int adxl345_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
  uint8_t data[6];

  if (i2c_block_read(fd, ADXL345_DATAX0, data, 6) != 0) {
    fprintf(stderr, "Failed to read acceleration data\n");
    return -1;
  }

  *x = (int16_t)((data[1] << 8) | data[0]);
  *y = (int16_t)((data[3] << 8) | data[2]);
  *z = (int16_t)((data[5] << 8) | data[4]);

  return 0;
}

// Log freefall event function
void log_freefall_event(int16_t x, int16_t y, int16_t z) {
  time_t rawtime;
  struct tm *timeinfo;
  char timestamp[30];
  struct timespec ts;

  clock_gettime(CLOCK_REALTIME, &ts);
  time(&rawtime);
  timeinfo = localtime(&rawtime);

  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
  snprintf(timestamp + strlen(timestamp), 5, ".%03ld", ts.tv_nsec / 1000000);

  fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
  fflush(log_file);
}

// Interrupt handler function
void interrupt_handler() {
  uint8_t int_source;
  int16_t x, y, z;

  // Read INT_SOURCE to clear the interrupt
  if (i2c_read_reg(i2c_fd, ADXL345_INT_SOURCE, &int_source) != 0) {
    fprintf(stderr, "Failed to read INT_SOURCE\n");
    return;
  }

  // Check if freefall interrupt occurred
  if (int_source & 0x04) {
    // Read acceleration data
    if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) == 0) {
      log_freefall_event(x, y, z);
    } else {
      fprintf(stderr, "Failed to read acceleration data in interrupt handler\n");
    }
  }
}

// Signal handler function
void signal_handler(int sig) {
  fprintf(stderr, "Signal received, cleaning up...\n");
  terminate = 1;
}

// GPIO interrupt setup function
int setup_gpio_interrupt() {
  struct gpiod_line_event event;
  struct timespec timeout = {0, 1000000}; // 1ms timeout

  // Request GPIO line for input
  gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
  if (!gpio_line) {
    perror("Failed to get GPIO line");
    return -1;
  }

  if (gpiod_line_request(gpio_line, "freefall_detector", GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
    perror("Failed to request GPIO line");
    return -1;
  }

  // Open event file descriptor
  int event_fd = gpiod_line_event_get_fd(gpio_line);
  if (event_fd < 0) {
    perror("Failed to get GPIO event file descriptor");
    return -1;
  }

  // Wait for falling edge
  if (read(event_fd, &event, sizeof(event)) < 0) {
    perror("Failed to read GPIO event");
    return -1;
  }

  // Check if the event is a falling edge
  if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
    interrupt_handler();
  }

  close(event_fd);
  return 0;
}

// Cleanup function
void cleanup() {
  // Disable interrupts
  if (i2c_fd != -1) {
    i2c_write_reg(i2c_fd, ADXL345_INT_ENABLE, 0x00);
  }

  // Release GPIO line
  if (gpio_line) {
    gpiod_line_release(gpio_line);
  }

  // Close I2C file descriptor
  if (i2c_fd != -1) {
    close(i2c_fd);
  }

  // Close GPIO chip
  if (gpio_chip) {
    gpiod_chip_close(gpio_chip);
  }

  // Close log file
  if (log_file) {
    fclose(log_file);
  }
}

int main() {
  // Install signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Open I2C bus
  i2c_fd = open(I2C_BUS, O_RDWR);
  if (i2c_fd < 0) {
    perror("Failed to open I2C bus");
    return 1;
  }

  // Set I2C slave address
  if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
    perror("Failed to set I2C slave address");
    close(i2c_fd);
    return 1;
  }

  // Initialize ADXL345
  if (adxl345_init(i2c_fd) != 0) {
    fprintf(stderr, "ADXL345 initialization failed\n");
    close(i2c_fd);
    return 1;
  }

  // Configure freefall detection
  if (adxl345_configure_freefall(i2c_fd) != 0) {
    fprintf(stderr, "ADXL345 freefall configuration failed\n");
    close(i2c_fd);
    return 1;
  }

  // Open log file
  log_file = fopen(FREEFALL_LOG_FILE, "a");
  if (log_file == NULL) {
    perror("Failed to open log file");
    close(i2c_fd);
    return 1;
  }

  // Write header if the file is newly created
  fseek(log_file, 0, SEEK_END);
  long file_size = ftell(log_file);
  if (file_size == 0) {
    fprintf(log_file, "Timestamp,X,Y,Z\n");
  }
  fflush(log_file);

  // Open GPIO chip
  gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
  if (!gpio_chip) {
    perror("Failed to open GPIO chip");
    fclose(log_file);
    close(i2c_fd);
    return 1;
  }

  // Main loop
  while (!terminate) {
    if (setup_gpio_interrupt() != 0) {
      fprintf(stderr, "GPIO interrupt setup failed\n");
      break;
    }
  }

  // Cleanup and exit
  cleanup();
  return 0;
}

