  }

  if (gpiod_line_request(gpio_line, "freefall_detector", GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
    perror("Failed to request GPIO line");
    return -1;
  }

  // Open event file descriptor
  int event_fd = gpiod_line_event_get_fd(gpio_line);
  if (event_fd < 0) {
    perror("Failed to get GPIO event file descriptor");
    return -1;
  }

  // Wait for falling edge
  if (read(event_fd, &event, sizeof(event)) < 0) {
    perror("Failed to read GPIO event");
    return -1;
  }

  // Check if the event is a falling edge
  if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
    interrupt_handler();
  }

  close(event_fd);
  return 0;
}

// Cleanup function
void cleanup() {
  // Disable interrupts
  if (i2c_fd != -1) {
    i2c_write_reg(i2c_fd, ADXL345_INT_ENABLE, 0x00);
  }

  // Release GPIO line
  if (gpio_line) {
    gpiod_line_release(gpio_line);
  }

  // Close I2C file descriptor
  if (i2c_fd != -1) {
    close(i2c_fd);
  }

  // Close GPIO chip
  if (gpio_chip) {
    gpiod_chip_close(gpio_chip);
  }

  // Close log file
  if (log_file) {
    fclose(log_file);
  }
}

int main() {
  // Install signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Open I2C bus
  i2c_fd = open(I2C_BUS, O_RDWR);
  if (i2c_fd < 0) {
    perror("Failed to open I2C bus");
    return 1;
  }

  // Set I2C slave address
  if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
    perror("Failed to set I2C slave address");
    close(i2c_fd);
    return 1;
  }

  // Initialize ADXL345
  if (adxl345_init(i2c_fd) != 0) {
    fprintf(stderr, "ADXL345 initialization failed\n");
    close(i2c_fd);
    return 1;
  }

  // Configure freefall detection
  if (adxl345_configure_freefall(i2c_fd) != 0) {
    fprintf(stderr, "ADXL345 freefall configuration failed\n");
    close(i2c_fd);
    return 1;
  }

  // Open log file
  log_file = fopen(FREEFALL_LOG_FILE, "a");
  if (log_file == NULL) {
    perror("Failed to open log file");
    close(i2c_fd);
    return 1;
  }

  // Write header if the file is newly created
  fseek(log_file, 0, SEEK_END);
  long file_size = ftell(log_file);
  if (file_size == 0) {
    fprintf(log_file, "Timestamp,X,Y,Z\n");
  }
  fflush(log_file);

  // Open GPIO chip
  gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
  if (!gpio_chip) {
    perror("Failed to open GPIO chip");
    fclose(log_file);
    close(i2c_fd);
    return 1;
  }

  // Main loop
  while (!terminate) {
    if (setup_gpio_interrupt() != 0) {
      fprintf(stderr, "GPIO interrupt setup failed\n");
      break;
    }
  }

  // Cleanup and exit
  cleanup();
  return 0;
}

