#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR WHO_AM_I register
#define WHO_AM_I 0x0F

// LSM6DSR WHO_AM_I value
#define WHO_AM_I_VALUE 0x6A

// LSM6DSR CTRL1_XL register
#define CTRL1_XL 0x10

// LSM6DSR CTRL2_G register
#define CTRL2_G 0x11

// LSM6DSR OUTX_L_XL register
#define OUTX_L_XL 0x28

// LSM6DSR OUTX_L_G register
#define OUTX_L_G 0x22

// Scaling factors
#define ACCEL_SCALE 0.061  // mg/LSB for +-2g range
#define GYRO_SCALE 8.75   // mdps/LSB for +-250 dps range

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2  // g
#define IMPACT_THRESHOLD 2.5   // g
#define IMPACT_WINDOW 1.0      // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x;
    float accel_y;
    float accel_z;
    float gyro_x;
    float gyro_y;
    float gyro_z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int check_sensor();
int configure_sensor();
sensor_data_t read_sensor_data();
float calculate_acceleration_magnitude(sensor_data_t data);
void log_data(sensor_data_t data);
void fall_detection(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0); // I2C bus 1, address 0x6A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Check if the sensor is present by reading the WHO_AM_I register
int check_sensor() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: 0x%X (expected 0x%X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }
    printf("LSM6DSR sensor found!\n");
    return 0;
}

// Configure the sensor for +-2g accelerometer and +-250 dps gyroscope range at 104 Hz ODR
int configure_sensor() {
    // Configure accelerometer: +-2g, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x60) < 0) { // 0x60 = 01100000
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: +-250 dps, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x60) < 0) { // 0x60 = 01100000
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Read accelerometer and gyroscope data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[12];

    // Read accelerometer data (6 bytes)
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.accel_x = data.accel_y = data.accel_z = 0.0;
        data.gyro_x = data.gyro_y = data.gyro_z = 0.0;
        return data;
    }

    // Read gyroscope data (6 bytes)
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer + 6, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        data.accel_x = data.accel_y = data.accel_z = 0.0;
        data.gyro_x = data.gyro_y = data.gyro_z = 0.0;
        return data;
    }

    // Convert raw data to g and dps
    int16_t raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    int16_t raw_gyro_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t raw_gyro_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t raw_gyro_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    data.accel_x = (float)raw_accel_x * ACCEL_SCALE / 1000.0;
    data.accel_y = (float)raw_accel_y * ACCEL_SCALE / 1000.0;
    data.accel_z = (float)raw_accel_z * ACCEL_SCALE / 1000.0;
    data.gyro_x = (float)raw_gyro_x * GYRO_SCALE / 1000.0;
    data.gyro_y = (float)raw_gyro_y * GYRO_SCALE / 1000.0;
    data.gyro_z = (float)raw_gyro_z * GYRO_SCALE / 1000.0;

    return data;
}

// Calculate the magnitude of the acceleration vector
float calculate_acceleration_magnitude(sensor_data_t data) {
    return sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);
}

// Log the sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z, data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Fall detection state machine
void fall_detection(sensor_data_t data) {
    static enum { IDLE, FREEFALL, IMPACT } state = IDLE;
    static time_t freefall_start_time = 0;
    float acceleration_magnitude = calculate_acceleration_magnitude(data);

    switch (state) {
        case IDLE:
            if (acceleration_magnitude < FREEFALL_THRESHOLD) {
                state = FREEFALL;
                time(&freefall_start_time);
            }
            break;
        case FREEFALL:
            if (acceleration_magnitude > IMPACT_THRESHOLD) {
                time_t current_time;
                time(&current_time);
                double time_diff = difftime(current_time, freefall_start_time);
                if (time_diff <= IMPACT_WINDOW) {
                    state = IMPACT;
                    printf("FALL DETECTED!\n");
                } else {
                    state = IDLE;
                }
            } else if (difftime(time(NULL), freefall_start_time) > IMPACT_WINDOW) {
                state = IDLE;
            }
            break;
        case IMPACT:
            state = IDLE;
            break;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Check if the sensor is present
    if (check_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t data = read_sensor_data();

        // Log the data
        log_data(data);

        // Perform fall detection
        fall_detection(data);

        // Delay for 1/104 seconds (approximately 9.6 ms)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close the log file
    fclose(log_file);

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

