#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADIS16266 Register Addresses
#define X_GYRO_OUT 0x14
#define WHO_AM_I 0x02

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Scaling factor for X_GYRO_OUT
#define GYRO_SCALE 0.0305

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data);
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data);
float convert_gyro_data(uint16_t raw_data);
void log_data(FILE *fp, float gyro_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read a 16-bit register from the ADIS16266
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set bit 7 of the register address to indicate a read operation
    tx_buf[0] = reg_addr | 0x80;
    tx_buf[1] = 0x00; // Dummy byte

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: spiXfer (read) failed with code %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *data = (rx_buf[0] << 8) | rx_buf[1];

    return 0;
}

// Function to write a 16-bit register to the ADIS16266
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set bit 7 of the register address to 0 to indicate a write operation
    tx_buf[0] = reg_addr & 0x7F;
    tx_buf[1] = data & 0xFF; //LSB

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: spiXfer (write) failed with code %d\n", result);
        return -1;
    }

    return 0;
}

// Function to convert raw gyroscope data to degrees per second
float convert_gyro_data(uint16_t raw_data) {
    // Check for overflow (bit 15 is set)
    if (raw_data & 0x8000) {
        // Convert to signed 16-bit integer
        int16_t signed_data = (int16_t)raw_data;
        return (float)signed_data * GYRO_SCALE;
    } else {
        return (float)raw_data * GYRO_SCALE;
    }
}

// Function to log the timestamp and gyroscope reading to a file
void log_data(FILE *fp, float gyro_rate) {
    time_t rawtime;
