#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDRESS 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F
#define WHO_AM_I_VALUE 0xD3
#define SENSITIVITY 8.75 // mdps/LSB
#define SENSITIVITY_SCALE 114.285 // dps/LSB
#define SAMPLE_RATE_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gyro();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *dps_x, float *dps_y, float *dps_z);
void log_data(struct timespec ts, float dps_x, float dps_y, float dps_z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int initialize_gyro() {
    int retries = 3;
    int status;

    // Verify WHO_AM_I register
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (status >= 0 && status == WHO_AM_I_VALUE) {
            break;
        } else {
            fprintf(stderr, "WHO_AM_I check failed (attempt %d): %d\n", 4 - retries, status);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "WHO_AM_I check failed after multiple retries. Exiting.\n");
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, all axes enabled)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "CTRL_REG1 write failed (attempt %d): %d\n", 4 - retries, status);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "CTRL_REG1 write failed after multiple retries. Exiting.\n");
        return -1;
    }

    // Configure CTRL_REG4 (Full-scale range +-250 dps)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "CTRL_REG4 write failed (attempt %d): %d\n", 4 - retries, status);
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "CTRL_REG4 write failed after multiple retries. Exiting.\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "I2C block read failed: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert raw data to degrees per second
void convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *dps_x, float *dps_y, float *dps_z) {
    *dps_x = (float)raw_x / SENSITIVITY_SCALE;
    *dps_y = (float)raw_y / SENSITIVITY_SCALE;
    *dps_z = (float)raw_z / SENSITIVITY_SCALE;
}

// Log data to file
void log_data(struct timespec ts, float dps_x, float dps_y, float dps_z) {
    fprintf(log_file, "%ld.%09ld,%f,%f,%f\n", ts.tv_sec, ts.tv_nsec, dps_x, dps_y, dps_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the gyroscope
    if (initialize_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Main loop
    struct timespec ts;
    int16_t raw_x, raw_y, raw_z;
    float dps_x, dps_y, dps_z;

    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees per second
            convert_to_dps(raw_x, raw_y, raw_z, &dps_x, &dps_y, &dps_z);

            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
            } else {
                // Log data
                log_data(ts, dps_x, dps_y, dps_z);
            }
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }

        // Delay for 10 ms
        gpioDelay(SAMPLE_RATE_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

