#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
int log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Exiting gracefully.\n");
        running = 0;
    }
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    return 0;
}

// Read flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value == PI_BAD_GPIO) {
        fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
        return -1; // Indicate an error
    }
    return value;
}

// Log event to file
int log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s - %s\n", timestamp, message);

    if (log_file != NULL) {
        fprintf(log_file, "%s", log_message);
        fflush(log_file); // Ensure immediate write
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE_NAME);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == -1) {
            log_event("ERROR: Failed to read sensor value.");
        } else {
            if (sensor_value == 0) {
                log_event("Flame detected: YES");
                printf("FLAME DETECTED!\n");
            } else {
                log_event("Flame detected: NO");
            }
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup
    if (log_file != NULL) {
        fclose(log_file);
