#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x53
#define SAMPLE_INTERVAL_MS 100
#define CSV_FILENAME "vibration_log.csv"

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *csv_file = NULL;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int16_t combine_acceleration(uint8_t lsb, uint8_t msb);
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }

    int bytes_read = read(fd, buf, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error reading I2C data: %s (read %d bytes, expected %d)\n", strerror(errno), bytes_read, len);
        return -1;
    }

    return 0;
}

// Combine acceleration data
int16_t combine_acceleration(uint8_t lsb, uint8_t msb) {
    return (int16_t)((msb << 8) | lsb);
}

// Log data to CSV file
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }
    rewind(csv_file);

    // Main loop
    uint8_t buffer[6];
    int16_t x, y, z;

    while (keep_running) {
        // Read acceleration data
        if (i2c_read_bytes(i2c_fd, 0x28, buffer, 6) == 0) {
            // Combine acceleration data
            x = combine_acceleration(buffer[0], buffer[1]);
            y = combine_acceleration(buffer[2], buffer[3]);
            z = combine_acceleration(buffer[4], buffer[5]);

            // Log data to CSV file
            if (log_data(csv_file, x, y, z) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Sleep for 100ms
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Close I2C bus and CSV file
    close(i2c_fd);
    fclose(csv_file);

    return 0;
}

