#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "conveyor_log.txt"

// Global variables for GPIO lines and chip
struct gpiod_line *sensor1_line = NULL;
struct gpiod_line *sensor2_line = NULL;
struct gpiod_chip *chip = NULL;

// Global variable for log file
FILE *log_file = NULL;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int log_data(FILE *fp, int sensor1_state, int sensor2_state);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);

    // Close GPIO lines if they are open
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }

    // Close GPIO chip if it is open
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file if it is open
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

// Function to read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to log data to file
int log_data(FILE *fp, int sensor1_state, int sensor2_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    if (fprintf(fp, "%ld.%03ld, %d, %d\n", ts.tv_sec, ts.tv_nsec / 1000000, sensor1_state, sensor2_state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SENSOR1_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SENSOR2_PIN, strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input with pull-up
    if (gpiod_line_request_input(sensor1_line, "conveyor_monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for input: %s\n", SENSOR1_PIN, strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(sensor2_line, "conveyor_monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for input: %s\n", SENSOR2_PIN, strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_state = read_sensor(sensor1_line);
        int sensor2_state = read_sensor(sensor2_line);

        if (sensor1_state == -1 || sensor2_state == -1) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        log_data(log_file, sensor1_state, sensor2_state);

        if (sensor1_state == 1 && sensor2_state == 1) {
            printf("Conveyor halted!\n");
        }

        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (in case the loop breaks due to an error)
    signal_handler(SIGTERM);

    return 0;
}

