#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define DATA_REG_BASE 0x01
#define DATA_REG_COUNT 6
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE_HZ)
#define TILT_THRESHOLD_DEG 45.0
#define LOG_FILE "fall_log.txt"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_reg(int fd, unsigned char reg, unsigned char value);
int i2c_read_reg(int fd, unsigned char reg, unsigned char *value);
int i2c_block_read(int fd, unsigned char reg, unsigned char *data, int len);
int init_accelerometer(int fd);
void read_accelerometer_data(int fd, short *x, short *y, short *z);
double calculate_tilt_angle(short x, short y, short z);
void log_fall_event(short x, short y, short z);
void signal_handler(int sig);

// I2C write function
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C block read function
int i2c_block_read(int fd, unsigned char reg, unsigned char *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C block read failed");
        return -1;
    }
    return 0;
}

