#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define LIS3MDL_ADDR 0x1E
#define WHO_AM_I 0x0F
#define WHO_AM_I_VALUE 0x3D
#define CTRL_REG1 0x20
#define CTRL_REG4 0x24
#define CTRL_REG3 0x22
#define OUT_X_L 0x28
#define SCALE_FACTOR 0.146 // mG/LSB
#define METAL_DETECT_THRESHOLD 800.0 // mG
#define LOG_FILE "magnetic_log.txt"
#define MAX_RETRIES 3

// Calibration offsets (example values, replace with your calibration)
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

// Function to initialize the LIS3MDL magnetometer
int init_magnetometer(int fd) {
    uint8_t retries = 0;
    uint8_t who_am_i;

    // Verify sensor presence
    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
            perror("Error: Could not set I2C slave address");
            return -1;
        }

        who_am_i = i2c_smbus_read_byte_data(fd, WHO_AM_I);
        if (who_am_i < 0) {
            perror("Error: Could not read WHO_AM_I register");
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        if (who_am_i == WHO_AM_I_VALUE) {
            break; // Sensor found
        } else {
            fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VALUE);
            retries++;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Error: Failed to verify sensor presence after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Configure magnetometer
    uint8_t config_data[3];
    config_data[0] = CTRL_REG1; // Continuous conversion mode, 80 Hz ODR, high-performance
    config_data[1] = 0x70;
    config_data[2] = CTRL_REG4; // +/- 4 gauss
    config_data[3] = 0x0C;
    config_data[4] = CTRL_REG3; // Continuous conversion mode
    config_data[5] = 0x00;

    for (int i = 0; i < 3; i++) {
        if (ioctl(fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
            perror("Error: Could not set I2C slave address");
            return -1;
        }
        if (i2c_smbus_write_byte_data(fd, config_data[2*i], config_data[2*i+1]) < 0) {
            perror("Error: Could not write to configuration register");
            return -1;
        }
    }

    return 0;
}

// Function to read magnetometer data
magnetometer_data_t read_magnetometer_data(int fd) {
    magnetometer_data_t data;
    int16_t raw_x, raw_y, raw_z;
    uint8_t buffer[6];

    if (ioctl(fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        data.x = data.y = data.z = 0.0; // Return default values on error
        return data;
    }

    if (i2c_smbus_read_i2c_block_data(fd, OUT_X_L, (char *)buffer, 6) != 6) {
        perror("Error: Could not read magnetometer data");
        data.x = data.y = data.z = 0.0; // Return default values on error
        return data;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Apply calibration and convert to milliGauss
    data.x = (float)raw_x * SCALE_FACTOR + X_OFFSET;
    data.y = (float)raw_y * SCALE_FACTOR + Y_OFFSET;
    data.z = (float)raw_z * SCALE_FACTOR + Z_OFFSET;

    return data;
}

// Function to log magnetometer data to a file
int log_data(FILE *fp, magnetometer_data_t data) {
    if (fprintf(fp, "%.2f,%.2f,%.2f\n", data.x, data.y, data.z) < 0) {
        perror("Error: Could not write to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Function to check for metal detection
void check_metal_detection(magnetometer_data_t data) {
    float magnitude = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > METAL_DETECT_THRESHOLD) {
        fprintf(stderr, "Metal detected! Magnitude: %.2f mG\n", magnitude);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C device");
        return 1;
    }

    // Initialize magnetometer
    if (init_magnetometer(i2c_fd) != 0) {
        fprintf(stderr, "Error: Magnetometer initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Could not open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    struct timespec sleep_time = {0, 100000000}; // 10 Hz (100 ms)
    magnetometer_data_t data;

    while (keep_running) {
        data = read_magnetometer_data(i2c_fd);
        if (data.x != 0.0 || data.y != 0.0 || data.z != 0.0) {
            if (log_data(log_file, data) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }
            check_metal_detection(data);
        }
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

