// ADXL354B Register Addresses
#define ADXL354B_PARTID 0x01
#define ADXL354B_RESET 0x1F
#define ADXL354B_POWER_CTL 0x2D
#define ADXL354B_STATUS 0x04
#define ADXL354B_XDATA_L 0x08
#define ADXL354B_XDATA_H 0x09
#define ADXL354B_XDATA_XL 0x0A
#define ADXL354B_YDATA_L 0x0B
#define ADXL354B_YDATA_H 0x0C
#define ADXL354B_YDATA_XL 0x0D
#define ADXL354B_ZDATA_L 0x0E
#define ADXL354B_ZDATA_H 0x0F
#define ADXL354B_ZDATA_XL 0x10

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int adxl354b_read_register(int handle, uint8_t reg);
int adxl354b_write_register(int handle, uint8_t reg, uint8_t value);
int adxl354b_reset(int handle);
int adxl354b_start_measurement(int handle);
int adxl354b_read_acceleration(int handle, float *x, float *y, float *z);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// Function to read a single register from the ADXL354B
int adxl354b_read_register(int handle, uint8_t reg) {
    char tx[2], rx[2];
    tx[0] = reg | 0x80; // Set read bit (bit 7)
    tx[1] = 0x00; // Dummy byte for reading

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI read error: %s\n", strerror(errno));
        return -1;
    }

    return rx[1];
}

// Function to write a single register in the ADXL354B
int adxl354b_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx[2], rx[2];
    tx[0] = reg | 0xC0; // Set write bit (bit 7) and multi-byte bit (bit 6)
    tx[1] = value;

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI write error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to reset the ADXL354B
int adxl354b_reset(int handle) {
    if (adxl354b_write_register(handle, ADXL354B_RESET, 0x52) != 0) {
        fprintf(stderr, "Reset failed\n");
        return -1;
    }
    gpioDelay(1); // Wait 1 ms
    return 0;
}

// Function to start measurement mode
int adxl354b_start_measurement(int handle) {
    // Clear RUN bit in POWER_CTL register
    if (adxl354b_write_register(handle, ADXL354B_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to clear RUN bit\n");
        return -1;
    }

    // Wait for STABLE bit in STATUS register
    int timeout = 100; // 100 * 10ms = 1 second timeout
    while ((adxl354b_read_register(handle, ADXL354B_STATUS) & 0x01) == 0) {
        gpioDelay(10); // Wait 10 ms
        if (--timeout <= 0) {
            fprintf(stderr, "Timeout waiting for STABLE bit\n");
            return -1;
        }
    }

    // Set RUN bit in POWER_CTL register
    if (adxl354b_write_register(handle, ADXL354B_POWER_CTL, 0x02) != 0) {
        fprintf(stderr, "Failed to set RUN bit\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL354B
int adxl354b_read_acceleration(int handle, float *x, float *y, float *z) {
    char tx[7], rx[7];
    tx[0] = ADXL354B_XDATA_L | 0xC0; // Read XDATA_L, XDATA_H, XDATA_XL
    memset(tx + 1, 0x00, 6); // Dummy bytes

    if (spiXfer(handle, tx, rx, 7) != 0) {
        fprintf(stderr, "SPI read error: %s\n", strerror(errno));
        return -1;
    }

    // Combine the 3 bytes for each axis into a 20-bit signed integer
    int32_t x_raw = ((int32_t)rx[2] << 12) | ((int32_t)rx[1] << 4) | ((int32_t)rx[0] >> 4);
    int32_t y_raw = ((int32_t)rx[5] << 12) | ((int32_t)rx[4] << 4) | ((int32_t)rx[3] >> 4);
    int32_t z_raw = ((int32_t)rx[8] << 12) | ((int32_t)rx[7] << 4) | ((int32_t)rx[6] >> 4);

    // Sign extend to 32 bits
    if (x_raw & 0x80000) x_raw |= 0xFFF00000;
    if (y_raw & 0x80000) y_raw |= 0xFFF00000;
    if (z_raw & 0x80000) z_raw |= 0xFFF00000;

    // Convert to g's
    *x = (float)x_raw * 0.0000039;
    *y = (float)y_raw * 0.0000039;
    *z = (float)z_raw * 0.0000039;

    return 0;
}

// Function to log data to a file
void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.6f g, Y: %.6f g, Z: %.6f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Check sensor presence
    int partid = adxl354b_read_register(spi_handle, ADXL354B_PARTID);
    if (partid != 0x1D) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X\n", partid);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Reset the sensor
    if (adxl354b_reset(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B reset failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Start measurement mode
    if (adxl354b_start_measurement(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B start measurement failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    // Main loop
    while (!terminate) {
        if (adxl354b_read_acceleration(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

