#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADIS16362 Register Addresses
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCL 0x0A
#define Y_ACCL 0x0C
#define Z_ACCL 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec/LSB
#define ACCL_SCALE 0.0025 // g/LSB

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double x_gyro;
    double y_gyro;
    double z_gyro;
    double x_accel;
    double y_accel;
    double z_accel;
} imu_data_t;

// Function prototypes
int read_register(int reg_addr, int *data);
imu_data_t process_data(int x_gyro_raw, int y_gyro_raw, int z_gyro_raw, int x_accel_raw, int y_accel_raw, int z_accel_raw);
int log_data(imu_data_t data);
void signal_handler(int signal);

// Function to read data from a specific register
int read_register(int reg_addr, int *data) {
    char tx_buf[2];
    char rx_buf[2];
    int status;

    // Set MSB of register address for read operation
    tx_buf[0] = reg_addr | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte

    status = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (status != 0) {
        fprintf(stderr, "Error: spiXfer failed with code %d\n", status);
        return -1; // Indicate failure
    }

    *data = (rx_buf[0] << 8) | rx_buf[1]; // Combine bytes into 16-bit data
    return 0; // Indicate success
}

// Function to process raw data and convert to physical units
imu_data_t process_data(int x_gyro_raw, int y_gyro_raw, int z_gyro_raw, int x_accel_raw, int y_accel_raw, int z_accel_raw) {
    imu_data_t data;

    data.x_gyro = (double)x_gyro_raw * GYRO_SCALE;
    data.y_gyro = (double)y_gyro_raw * GYRO_SCALE;
    data.z_gyro = (double)z_gyro_raw * GYRO_SCALE;
    data.x_accel = (double)x_accel_raw * ACCL_SCALE;
    data.y_accel = (double)y_accel_raw * ACCL_SCALE;
    data.z_accel = (double)z_accel_raw * ACCL_SCALE;

    return data;
}

// Function to log data to a file
int log_data(imu_data_t data) {
    struct timespec ts;
    char timestamp[30];
    int status;

    // Get current timestamp
    status = clock_gettime(CLOCK_REALTIME, &ts);
    if (status == -1) {
        fprintf(stderr, "Error: clock_gettime failed\n");
        return -1;
    }

    // Format timestamp
    snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

    // Write data to file
    fprintf(log_file, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, data.x_gyro, data.y_gyro, data.z_gyro, data.x_accel, data.y_accel, data.z_accel);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int x_gyro_raw, y_gyro_raw, z_gyro_raw, x_accel_raw, y_accel_raw, z_accel_raw;
    imu_data_t imu_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw data from registers
        if (read_register(X_GYRO, &x_gyro_raw) != 0) continue;
        if (read_register(Y_GYRO, &y_gyro_raw) != 0) continue;
        if (read_register(Z_GYRO, &z_gyro_raw) != 0) continue;
        if (read_register(X_ACCL, &x_accel_raw) != 0) continue;
        if (read_register(Y_ACCL, &y_accel_raw) != 0) continue;
        if (read_register(Z_ACCL, &z_accel_raw) != 0) continue;

        // Process data
        imu_data = process_data(x_gyro_raw, y_gyro_raw, z_gyro_raw, x_accel_raw, y_accel_raw, z_accel_raw);

        // Log data
        if (log_data(imu_data) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Delay for approximately 10 ms (100 Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

