        fprintf(stderr, "Error: clock_gettime failed\n");
        return -1;
    }

    // Format timestamp
    snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

    // Write data to file
    fprintf(log_file, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, data.x_gyro, data.y_gyro, data.z_gyro, data.x_accel, data.y_accel, data.z_accel);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int x_gyro_raw, y_gyro_raw, z_gyro_raw, x_accel_raw, y_accel_raw, z_accel_raw;
    imu_data_t imu_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw data from registers
        if (read_register(X_GYRO, &x_gyro_raw) != 0) continue;
        if (read_register(Y_GYRO, &y_gyro_raw) != 0) continue;
        if (read_register(Z_GYRO, &z_gyro_raw) != 0) continue;
        if (read_register(X_ACCL, &x_accel_raw) != 0) continue;
        if (read_register(Y_ACCL, &y_accel_raw) != 0) continue;
        if (read_register(Z_ACCL, &z_accel_raw) != 0) continue;

        // Process data
        imu_data = process_data(x_gyro_raw, y_gyro_raw, z_gyro_raw, x_accel_raw, y_accel_raw, z_accel_raw);

        // Log data
        if (log_data(imu_data) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Delay for approximately 10 ms (100 Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

