#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 17
#define POLL_INTERVAL_MS 1000

static volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int rc;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read the sensor value
        int sensor_value = gpioRead(GPIO_PIN);

        // Check for obstacle detection (LOW signal)
        if (sensor_value == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the start of the self-parking sequence
            printf("[%s] Self-parking sequence started\n", timestamp);

            // Simulate self-parking sequence (1 second)
            gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds

            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the completion of the self-parking sequence
            printf("[%s] Self-parking sequence completed\n", timestamp);
        }

        // Wait for the next poll interval
        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

