#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the sensors
#define GPIO17 17
#define GPIO27 27

// Global variables for GPIO lines and chip
struct gpiod_line *line17 = NULL;
struct gpiod_line *line27 = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to read sensor values
int read_sensors(struct gpiod_line *line17, struct gpiod_line *line27, int *sensor1_value, int *sensor2_value);

// Function to log obstacle detection status
void log_status(int sensor1_value, int sensor2_value);

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        perror("Error getting GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    line27 = gpiod_chip_get_line(chip, GPIO27);
    if (!line27) {
        perror("Error getting GPIO line 27");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for input
    if (gpiod_line_request_input(line17, "obstacle_sensor_1") < 0) {
        perror("Error requesting GPIO line 17 for input");
        gpiod_line_release(line27);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line27, "obstacle_sensor_2") < 0) {
        perror("Error requesting GPIO line 27 for input");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    int sensor1_value, sensor2_value;
    while (1) {
        // Read the sensor values
        if (read_sensors(line17, line27, &sensor1_value, &sensor2_value) != 0) {
            fprintf(stderr, "Error reading sensors, exiting.\n");
            break;
        }

        // Log the obstacle detection status
        log_status(sensor1_value, sensor2_value);

        // Wait for 100 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Release the GPIO lines and close the chip
    gpiod_line_release(line17);
    gpiod_line_release(line27);
    gpiod_chip_close(chip);

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully.\n", sig);

    // Release the GPIO lines if they are open
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line27) {
        gpiod_line_release(line27);
    }

    // Close the GPIO chip if it is open
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read sensor values
int read_sensors(struct gpiod_line *line17, struct gpiod_line *line27, int *sensor1_value, int *sensor2_value) {
    int value17, value27;

    value17 = gpiod_line_get_value(line17);
    if (value17 < 0) {
        perror("Error reading GPIO line 17");
        return -1;
    }

    value27 = gpiod_line_get_value(line27);
    if (value27 < 0) {
        perror("Error reading GPIO line 27");
        return -1;
    }

    *sensor1_value = value17;
    *sensor2_value = value27;

    return 0;
}

// Function to log obstacle detection status
void log_status(int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor 1: %s, Sensor 2: %s\n", timestamp,
           sensor1_value == 0 ? "Obstacle Detected" : "Path Clear",
           sensor2_value == 0 ? "Obstacle Detected" : "Path Clear");
}

