#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// ADIS16266 Register Addresses
#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08
#define ADIS16266_MSC_CTRL  0x24

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// CS Pin
#define CS_PIN 8

// Scale Factor
#define SCALE_FACTOR 0.02 // deg/sec/LSB

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(uint8_t address, int16_t *data);
int spi_write_register(uint8_t address, uint16_t data);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// SPI Read Register Function
int spi_read_register(uint8_t address, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB for read operation
    address |= 0x80;

    tx_buf[0] = address;
    tx_buf[1] = 0x00; // Dummy byte for reading

    gpioWrite(CS_PIN, 0); // Assert CS
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deassert CS

    if (result != 2) {
        fprintf(stderr, "SPI read error: %s\n", strerror(errno));
        return -1;
    }

    *data = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    return 0;
}

// SPI Write Register Function
int spi_write_register(uint8_t address, uint16_t data) {
    char tx_buf[3];

    tx_buf[0] = address & 0x7F; // Clear MSB for write operation
    tx_buf[1] = (data >> 8) & 0xFF; // MSB
    tx_buf[2] = data & 0xFF;      // LSB

    gpioWrite(CS_PIN, 0); // Assert CS
    int result = spiWrite(spi_handle, tx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deassert CS

    if (result != 3) {
        fprintf(stderr, "SPI write error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Initialization Function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deassert CS initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Configure ADIS16266 (Data Ready Mode)
    if (spi_write_register(ADIS16266_MSC_CTRL, 0x0004) != 0) {
        fprintf(stderr, "Failed to configure ADIS16266\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup Function
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    int16_t x_gyro, y_gyro, z_gyro;
    float x_rate, y_rate, z_rate;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (spi_read_register(ADIS16266_XGYRO_OUT, &x_gyro) == 0 &&
            spi_read_register(ADIS16266_YGYRO_OUT, &y_gyro) == 0 &&
            spi_read_register(ADIS16266_ZGYRO_OUT, &z_gyro) == 0) {

            // Convert to angular rates
            x_rate = x_gyro * SCALE_FACTOR;
            y_rate = y_gyro * SCALE_FACTOR;
            z_rate = z_gyro * SCALE_FACTOR;

            // Log data
            printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_rate, y_rate, z_rate);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    cleanup();

    return 0;
}

