#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01

// Global variables for I2C handle and program termination
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700() {
    // Verify sensor presence
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0xC7\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: Active mode, 100 Hz ODR, hybrid mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01 | (0x02 << 2)) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure magnetometer: Hybrid mode, 100 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, M_CTRL_REG1, 0x1F) < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG1\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, M_CTRL_REG2, 0x20) < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG2\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and magnetometer data
int read_fxos8700(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char buffer[12];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 12);
    if (result < 0) {
        fprintf(stderr, "Error reading data block: %d\n", result);
        return -1;
    }

    // Extract accelerometer data (14-bit, left-aligned)
    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2;
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

    // Extract magnetometer data (16-bit, left-aligned)
    *mag_x = (int16_t)((buffer[6] << 8) | buffer[7]);
    *mag_y = (int16_t)((buffer[8] << 8) | buffer[9]);
    *mag_z = (int16_t)((buffer[10] << 8) | buffer[11]);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to read and print data
    int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;
    while (!terminate) {
        if (read_fxos8700(&accel_x, &accel_y, &accel_z, &mag_x, &mag_y, &mag_z) == 0) {
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Mag: X=%6d, Y=%6d, Z=%6d\n",
                   accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Clean up resources before exiting
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

