#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_RATE_MS 100

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write_byte(int fd, unsigned char reg, unsigned char value);
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len);
int adxl345_init(int fd);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
void log_event(const char *message);
void signal_handler(int signal);

// I2C write function
int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// ADXL345 initialization function
int adxl345_init(int fd) {
    // Set data format: +/- 2g range
    if (i2c_write_byte(fd, DATA_FORMAT, 0x08) != 0) {
        fprintf(stderr, "Failed to set data format\n");
        return -1;
    }

    // Enable measurement mode
    if (i2c_write_byte(fd, POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Failed to enable measurement mode\n");
        return -1;
    }

    return 0;
}

// Read acceleration data function
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    unsigned char buf[6];

    if (i2c_read_bytes(fd, DATAX0, buf, 6) != 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Calculate tilt angle function
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
