#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5 // seconds
#define SAMPLE_INTERVAL 1 // milliseconds
#define PAUSE_DURATION 1 // seconds

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int main(int argc, char *argv[]) {
    int threshold;
    int i;
    int high_count;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Validate command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    threshold = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    fprintf(stdout, "Noise monitoring started. Threshold: %d\n", threshold);

    while (!terminate) {
        high_count = 0;

        // Sample GPIO pin for WINDOW_SIZE seconds
        for (i = 0; i < WINDOW_SIZE * 1000; ++i) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL); // Delay for 1 ms
        }

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Check if threshold is exceeded
        if (high_count > threshold) {
            printf("%s ALERT: Noise level exceeded threshold (%d > %d)\n", timestamp, high_count, threshold);
        } else {
            printf("%s Normal: Noise level within acceptable range (%d <= %d)\n", timestamp, high_count, threshold);
        }

        // Pause for PAUSE_DURATION seconds
        sleep(PAUSE_DURATION);
    }

    // Terminate pigpio
    gpioTerminate();
    fprintf(stdout, "Noise monitoring stopped.\n");

    return 0;
}

