#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define log file name
#define LOG_FILE "access_log.txt"

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip;
static struct gpiod_line *door_a_line;
static struct gpiod_line *door_b_line;
static FILE *log_file;

// Function prototypes
int generate_code(int *code);
int validate_code(int code, int correct_code);
int unlock_door(int pin);
int lock_door(int pin);
int log_access(int code);
void signal_handler(int sig);
int setup_gpio();
int cleanup_gpio();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to generate a random 6-digit code
int generate_code(int *code) {
    srand(time(NULL));
    *code = (rand() % 900000) + 100000;
    return 0;
}

// Function to validate the entered code
int validate_code(int code, int correct_code) {
    return (code == correct_code);
}

// Function to unlock a door
int unlock_door(int pin) {
    int ret = gpiod_line_set_value(pin, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to lock a door
int lock_door(int pin) {
    int ret = gpiod_line_set_value(pin, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to log access to a file
int log_access(int code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s,%06d\n", timestamp, code);
    fclose(log_file);
    return 0;
}

// Function to setup GPIO lines
int setup_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_A_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_B_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        return -1;
    }

    int ret = gpiod_line_request_output(door_a_line, "door_access", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", DOOR_A_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        gpiod_line_release(door_b_line);
        return -1;
    }

    ret = gpiod_line_request_output(door_b_line, "door_access", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", DOOR_B_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        gpiod_line_release(door_b_line);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines
int cleanup_gpio() {
    if (door_a_line) {
        gpiod_line_set_value(door_a_line, 0);
        gpiod_line_release(door_a_line);
    }
    if (door_b_line) {
        gpiod_line_set_value(door_b_line, 0);
        gpiod_line_release(door_b_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

int main() {
    int correct_code;
    int entered_code;
    char input[7]; // 6 digits + null terminator
    struct timespec sleep_time;
    sleep_time.tv_sec = 5;
    sleep_time.tv_nsec = 0;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() < 0) {
        return 1;
    }

    // Generate initial code
    if (generate_code(&correct_code) < 0) {
        cleanup_gpio();
        return 1;
    }

    printf("Generated code: %06d\n", correct_code);

    // Main loop
    while (!terminate) {
        printf("Enter code: ");
        if (fgets(input, sizeof(input), stdin) == NULL) {
            fprintf(stderr, "Error reading input: %s\n", strerror(errno));
            continue;
        }

        // Remove trailing newline
        input[strcspn(input, "\n")] = 0;

        // Validate input
        if (strlen(input) != 6 || input[0] == '0') {
            fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
            continue;
        }

        // Convert input to integer
        entered_code = atoi(input);

        // Validate code
        if (validate_code(entered_code, correct_code)) {
            printf("Access granted!\n");

            // Unlock Door A
            if (unlock_door(door_a_line) < 0) {
                terminate = 1; // Exit on error
                break;
            }

            // Wait for 5 seconds
            nanosleep(&sleep_time, NULL);

            // Lock Door A
            if (lock_door(door_a_line) < 0) {
                terminate = 1; // Exit on error
                break;
            }

            // Log access
            if (log_access(correct_code) < 0) {
                terminate = 1; // Exit on error
                break;
            }

            // Generate new code
            if (generate_code(&correct_code) < 0) {
                terminate = 1; // Exit on error
                break;
            }

            printf("New code: %06d\n", correct_code);
        } else {
            printf("Access denied\n");
        }
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

