#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define ONE_TIME_HIGH_RES_MODE_2 0x21
#define LOG_FILE "light_log.txt"

int i2c_fd = -1;
FILE *log_file = NULL;

// Function to handle Ctrl+C signal
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to write a command to the BH1750 sensor
int write_command(int command) {
    unsigned char buf[1];
    buf[0] = command;

    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from the BH1750 sensor
int read_data(unsigned char *data, int len) {
    if (read(i2c_fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to calculate illuminance in lux
float calculate_lux(unsigned int raw_value) {
    return (float)raw_value / 1.2;
}

// Function to log the illuminance data to a file
int log_data(float lux_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value);
    fclose(log_file);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C bus
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    printf("I2C initialized successfully.\n");

    while (1) {
        // Send One-Time High-Resolution Mode 2 command
        if (write_command(ONE_TIME_HIGH_RES_MODE_2) < 0) {
            fprintf(stderr, "Failed to send command. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Wait for conversion time (180 ms)
        usleep(180000); // 180 ms

        // Read 2 bytes of data
        unsigned char data[2];
        if (read_data(data, 2) < 0) {
            fprintf(stderr, "Failed to read data. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Combine the two bytes into a 16-bit unsigned integer
        unsigned int raw_value = (data[0] << 8) | data[1];

        // Calculate illuminance in lux
        float lux_value = calculate_lux(raw_value);

        // Log the illuminance data
        if (log_data(lux_value) < 0) {
            fprintf(stderr, "Failed to log data. Retrying in 5 seconds.\n");
        }

        printf("Lux: %.2f\n", lux_value);

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

