#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define GPIO_PWM 18
#define PORT 12345
#define SECRET_KEY "MySecretKey"
#define MOTION_PREFIX "MOTION_DETECTED:"
#define PLAYBACK_DURATION 5 // seconds
#define SAMPLE_INTERVAL 20 // milliseconds
#define FREQUENCY_MIN 220
#define FREQUENCY_MAX 880

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_mpr121();
int read_mpr121_data(int *touch_data);
float map_to_frequency(int max_touch_value);
void set_pwm_frequency(float frequency);
void handle_client(int client_socket);
void signal_handler(int signum);
void cleanup();

// Signal handler
void signal_handler(int signum) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signum);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (new_socket >= 0) {
        close(new_socket);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioPWM(GPIO_PWM, 0); // Stop PWM
    gpioTerminate();
}

// Initialize MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure electrode sensitivity and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x0A) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x05) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Configure filter settings (example)
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) { // Filter configuration
        fprintf(stderr, "Error: Failed to set filter configuration\n");
        return -1;
    }

    // Enable electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x3F) < 0) { // Enable all 12 electrodes
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }

    // Start sensor
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) { // Enable sensor
        fprintf(stderr, "Error: Failed to enable sensor\n");
        return -1;
    }

    return 0;
}

// Read MPR121 data
int read_mpr121_data(int *touch_data) {
    char buf[24];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 24) < 0) {
        fprintf(stderr, "Error: Failed to read MPR121 data\n");
        return -1;
    }

    for (int i = 0; i < 12; i++) {
        touch_data[i] = ((buf[2 * i + 1] << 8) | buf[2 * i]);
    }
    return 0;
}

// Map touch value to frequency (logarithmic scale)
float map_to_frequency(int max_touch_value) {
    // Avoid division by zero and handle cases where max_touch_value is very small
    double normalized_value = (double)max_touch_value / 1023.0; // Assuming 10-bit ADC
    normalized_value = fmax(0.0, fmin(1.0, normalized_value)); // Clamp to [0, 1]

    // Logarithmic mapping
    double log_min = log10(FREQUENCY_MIN);
    double log_max = log10(FREQUENCY_MAX);
    double log_freq = log_min + normalized_value * (log_max - log_min);

    return pow(10, log_freq);
}

// Set PWM frequency
void set_pwm_frequency(float frequency) {
    gpioSetPWMfrequency(GPIO_PWM, (int)frequency);
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data");
        close(client_socket);
        return;
    }

    buffer[bytes_received] = '\0';
    printf("Received: %s\n", buffer);

    // Validate message format
    if (strncmp(buffer, MOTION_PREFIX, strlen(MOTION_PREFIX)) == 0) {
        char *secret_start = strstr(buffer, SECRET_KEY);
        if (secret_start != NULL && secret_start == buffer + strlen(MOTION_PREFIX)) {
            printf("Secret key validated. Playing theremin...\n");

            // Open log file
            log_file = fopen("frequency_log.txt", "a");
            if (log_file == NULL) {
                perror("Error opening log file");
                close(client_socket);
                return;
            }

            // Play theremin for 5 seconds
            int touch_data[12];
            time_t start_time = time(NULL);
            while (time(NULL) - start_time < PLAYBACK_DURATION) {
                if (read_mpr121_data(touch_data) == 0) {
                    int max_touch_value = 0;
                    for (int i = 0; i < 12; i++) {
                        if (touch_data[i] > max_touch_value) {
                            max_touch_value = touch_data[i];
                        }
                    }

                    float frequency = map_to_frequency(max_touch_value);
                    set_pwm_frequency(frequency);

                    // Log frequency
                    time_t now = time(NULL);
                    struct tm *tstruct = localtime(&now);
                    char buf[80];
                    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
                    fprintf(log_file, "%s: Frequency = %.2f Hz\n", buf, frequency);
                    fflush(log_file); // Ensure data is written to file immediately
                } else {
                    fprintf(stderr, "Error reading MPR121 data during playback\n");
                }
                gpioDelay(SAMPLE_INTERVAL); // Sample every 20ms
            }

            // Stop PWM and close log file
            gpioPWM(GPIO_PWM, 0);
            fclose(log_file);
            printf("Theremin playback finished.\n");
        } else {
            fprintf(stderr, "Invalid secret key.\n");
        }
    } else {
        fprintf(stderr, "Invalid message format.\n");
    }

    close(client_socket);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 to PWM mode
    gpioSetMode(GPIO_PWM, PI_OUTPUT);

    // Set PWM range (optional, adjust as needed)
    gpioSetPWMrange(GPIO_PWM, 1000); // Example range

    // Set PWM duty cycle to 0 initially
    gpioPWM(GPIO_PWM, 0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("Error creating socket");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Error binding socket");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("Error listening on socket");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    // Accept connections and handle clients
    while (program_running) {
        struct sockaddr_in client_address;
        int client_address_len = sizeof(client_address);
        new_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&client_address_len);
        if (new_socket < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        handle_client(new_socket);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

