        perror("Error receiving data");
        close(client_socket);
        return;
    }

    buffer[bytes_received] = '\0';
    printf("Received: %s\n", buffer);

    // Validate message format
    if (strncmp(buffer, MOTION_PREFIX, strlen(MOTION_PREFIX)) == 0) {
        char *secret_start = strstr(buffer, SECRET_KEY);
        if (secret_start != NULL && secret_start == buffer + strlen(MOTION_PREFIX)) {
            printf("Secret key validated. Playing theremin...\n");

            // Open log file
            log_file = fopen("frequency_log.txt", "a");
            if (log_file == NULL) {
                perror("Error opening log file");
                close(client_socket);
                return;
            }

            // Play theremin for 5 seconds
            int touch_data[12];
            time_t start_time = time(NULL);
            while (time(NULL) - start_time < PLAYBACK_DURATION) {
                if (read_mpr121_data(touch_data) == 0) {
                    int max_touch_value = 0;
                    for (int i = 0; i < 12; i++) {
                        if (touch_data[i] > max_touch_value) {
                            max_touch_value = touch_data[i];
                        }
                    }

                    float frequency = map_to_frequency(max_touch_value);
                    set_pwm_frequency(frequency);

                    // Log frequency
                    time_t now = time(NULL);
                    struct tm *tstruct = localtime(&now);
                    char buf[80];
                    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
                    fprintf(log_file, "%s: Frequency = %.2f Hz\n", buf, frequency);
                    fflush(log_file); // Ensure data is written to file immediately
                } else {
                    fprintf(stderr, "Error reading MPR121 data during playback\n");
                }
                gpioDelay(SAMPLE_INTERVAL); // Sample every 20ms
            }

            // Stop PWM and close log file
            gpioPWM(GPIO_PWM, 0);
            fclose(log_file);
            printf("Theremin playback finished.\n");
        } else {
            fprintf(stderr, "Invalid secret key.\n");
        }
    } else {
        fprintf(stderr, "Invalid message format.\n");
    }

    close(client_socket);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 to PWM mode
    gpioSetMode(GPIO_PWM, PI_OUTPUT);

    // Set PWM range (optional, adjust as needed)
    gpioSetPWMrange(GPIO_PWM, 1000); // Example range

    // Set PWM duty cycle to 0 initially
    gpioPWM(GPIO_PWM, 0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("Error creating socket");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Error binding socket");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("Error listening on socket");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    // Accept connections and handle clients
    while (program_running) {
        struct sockaddr_in client_address;
        int client_address_len = sizeof(client_address);
        new_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&client_address_len);
        if (new_socket < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        handle_client(new_socket);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

