#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define LSM303_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define GPIO_PIN 17
#define PWM_PERIOD 1000000 // 1 kHz
#define SAMPLE_RATE_MS 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_lsm303();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
int set_led_brightness(double magnitude);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// I2C initialization
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// GPIO initialization
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "magnetometer_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// LSM303 initialization
int init_lsm303() {
    uint8_t data[2];
    data[0] = CTRL_REG1_M;
    data[1] = 0x18; // 10 Hz continuous conversion

    if (write(i2c_fd, data, 2) != 2) {
        perror("Error writing to CTRL_REG1_M");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    uint8_t reg = OUT_X_L_M;

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading magnetometer data");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate magnitude of Z-axis field
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return fabs((double)z);
}

// Set LED brightness using PWM
int set_led_brightness(double magnitude) {
    // Scale magnitude to PWM duty cycle (0-PWM_PERIOD)
    uint32_t duty_cycle = (uint32_t)((magnitude / 1000.0) * PWM_PERIOD); // Assuming max magnitude is around 1000
    if (duty_cycle > PWM_PERIOD) {
        duty_cycle = PWM_PERIOD;
    }

    // Calculate on and off times
    uint32_t on_time = duty_cycle;
    uint32_t off_time = PWM_PERIOD - duty_cycle;

    // Set GPIO high for on_time and low for off_time
    gpiod_line_set_value(gpio_line, 1); // High
    usleep(on_time); // Microseconds
    gpiod_line_set_value(gpio_line, 0); // Low
    usleep(off_time); // Microseconds

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Release GPIO
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close I2C
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("magnetometer.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(log_file, "%s I2C initialization failed\n", __TIME__);
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(log_file, "%s GPIO initialization failed\n", __TIME__);
        cleanup();
        return 1;
    }

    // Initialize LSM303
    if (init_lsm303() != 0) {
        fprintf(log_file, "%s LSM303 initialization failed\n", __TIME__);
        cleanup();
        return 1;
    }

    int16_t x, y, z;
    double magnitude;

    // Main loop
    while (!terminate) {
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);
            set_led_brightness(magnitude);
        } else {
            fprintf(log_file, "%s Error reading magnetometer data\n", __TIME__);
        }

        usleep(SAMPLE_RATE_MS * 1000); // Sleep for 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

