#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L Registers
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Configuration values
#define CONFIG_A_VALUE 0x70 // 8-sample averaging, 15 Hz output rate
#define CONFIG_B_VALUE 0x20 // Gain setting of 1.3 Gauss
#define MODE_CONTINUOUS 0x00 // Continuous measurement mode

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Hard-iron offset values
float x_offset = 0.0;
float y_offset = 0.0;
float z_offset = 0.0;

// Running average window size
#define WINDOW_SIZE 100

// Hard-iron offset history
float x_history[WINDOW_SIZE];
float y_history[WINDOW_SIZE];
float z_history[WINDOW_SIZE];
int history_index = 0;

// Function prototypes
int init_hmc5883l();
int read_raw_data(int16_t *x, int16_t *y, int16_t *z);
void update_hard_iron_offsets(int16_t x, int16_t y, int16_t z);
void apply_hard_iron_offsets(int16_t x, int16_t y, int16_t z, float *x_corrected, float *y_corrected, float *z_corrected);
void print_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the HMC5883L sensor
int init_hmc5883l() {
    // Set Configuration Register A
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, CONFIG_A_VALUE) < 0) {
        fprintf(stderr, "Error writing to Configuration Register A: %s\n", strerror(errno));
        return -1;
    }

    // Set Configuration Register B
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, CONFIG_B_VALUE) < 0) {
        fprintf(stderr, "Error writing to Configuration Register B: %s\n", strerror(errno));
        return -1;
    }

    // Set Mode Register to continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, MODE_CONTINUOUS) < 0) {
        fprintf(stderr, "Error writing to Mode Register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read raw data from the HMC5883L sensor
int read_raw_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Update hard-iron offsets using a running average
void update_hard_iron_offsets(int16_t x, int16_t y, int16_t z) {
    x_history[history_index] = x;
    y_history[history_index] = y;
    z_history[history_index] = z;

    x_offset = 0.0;
    y_offset = 0.0;
    z_offset = 0.0;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        x_offset += x_history[i];
        y_offset += y_history[i];
        z_offset += z_history[i];
    }

    x_offset /= WINDOW_SIZE;
    y_offset /= WINDOW_SIZE;
    z_offset /= WINDOW_SIZE;

    history_index = (history_index + 1) % WINDOW_SIZE;
}

// Apply hard-iron offsets to raw data
void apply_hard_iron_offsets(int16_t x, int16_t y, int16_t z, float *x_corrected, float *y_corrected, float *z_corrected) {
    *x_corrected = x - x_offset;
    *y_corrected = y - y_offset;
    *z_corrected = z - z_offset;
}

// Print the offset-corrected data
void print_data(float x, float y, float z) {
    printf("X: %.2f, Y: %.2f, Z: %.2f\n", x, y, z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L sensor
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float corrected_x, corrected_y, corrected_z;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Update hard-iron offsets
            update_hard_iron_offsets(raw_x, raw_y, raw_z);

            // Apply hard-iron offsets
            apply_hard_iron_offsets(raw_x, raw_y, raw_z, &corrected_x, &corrected_y, &corrected_z);

            // Print the data
            print_data(corrected_x, corrected_y, corrected_z);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Delay for 500 ms
        gpioDelay(500000); // 500 ms = 500000 us
    }

    // Clean up resources
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

