#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D registers
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define INT1_CFG 0x30
#define OUT_X_L_A 0x28

// GPIO pin for interrupt
#define GPIO_PIN 23

// Circular buffer size
#define BUFFER_SIZE 64

// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} acceleration_data_t;

// Global variables
int i2c_fd;
struct gpiod_chip *gpio_chip;
struct gpiod_line *gpio_line;
acceleration_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_byte(int reg);
int i2c_write_byte(int reg, int value);
int lsm303d_init();
int read_acceleration(acceleration_data_t *data);
void interrupt_handler();
void signal_handler(int sig);
void dump_buffer();

// I2C read byte function
int i2c_read_byte(int reg) {
    int result = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return result;
}

// I2C write byte function
int i2c_write_byte(int reg, int value) {
    int result = i2c_smbus_write_byte_data(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// LSM303D initialization function
int lsm303d_init() {
    int who_am_i;

    // Verify WHO_AM_I register
    who_am_i = i2c_read_byte(WHO_AM_I);
    if (who_am_i != 0x49) {
        fprintf(stderr, "WHO_AM_I check failed: 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer
    if (i2c_write_byte(CTRL_REG1, 0x57) < 0) return -1; // 50 Hz ODR, all axes enabled
    if (i2c_write_byte(CTRL_REG4, 0x00) < 0) return -1; // +-2g full scale
    if (i2c_write_byte(INT1_CFG, 0x2A) < 0) return -1; // Any-axis-high event
    if (i2c_write_byte(0x2B, 0x7D) < 0) return -1; // Threshold 2000 mg
    if (i2c_write_byte(0x2C, 0x00) < 0) return -1; // Duration 0

    return 0;
}

// Read acceleration data function
int read_acceleration(acceleration_data_t *data) {
    char buffer[6];
    int result = i2c_smbus_read_i2c_block_data(i2c_fd, OUT_X_L_A | 0x80, 6, buffer);
    if (result < 0) {
        fprintf(stderr, "I2C block read error: %s\n", strerror(errno));
        return -1;
    }

    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Interrupt handler function
void interrupt_handler() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    printf("Interrupt occurred at: %s\n", buf);
    dump_buffer();
}

// Dump buffer function
void dump_buffer() {
    int start_index = (buffer_index - 10 + BUFFER_SIZE) % BUFFER_SIZE;
    printf("Last 10 samples:\n");
    for (int i = 0; i < 10; i++) {
        int index = (start_index + i) % BUFFER_SIZE;
        printf("  [%d] X: %6d, Y: %6d, Z: %6d\n", index, circular_buffer[index].x, circular_buffer[index].y, circular_buffer[index].z);
    }
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);

    // Disable accelerometer
    i2c_write_byte(CTRL_REG1, 0x00);

    // Close I2C file descriptor
    close(i2c_fd);

    // Release GPIO line
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);

    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize LSM303D
    if (lsm303d_init() < 0) {
        fprintf(stderr, "LSM303D initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for input with rising edge event
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "lsm303d_mon";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(gpio_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Set up interrupt handler
    struct gpiod_line_event event;
    memset(&event, 0, sizeof(event));
    event.event_type = GPIOD_LINE_EVENT_RISING_EDGE;
    event.consumer = "lsm303d_mon";

    ret = gpiod_line_event_wait(gpio_line, &event, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to wait for GPIO event: %s\n", strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    acceleration_data_t data;
    while (program_running) {
        if (read_acceleration(&data) == 0) {
            circular_buffer[buffer_index] = data;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        usleep(10000); // 10 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

