#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for solenoids
#define SOLENOID1_GPIO 17
#define SOLENOID2_GPIO 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *solenoid1_line = NULL;
struct gpiod_line *solenoid2_line = NULL;
struct gpiod_chip *gpiochip = NULL;

// Function prototypes
int gpio_init(void);
void solenoid1_on(void);
void solenoid1_off(void);
void solenoid2_on(void);
void solenoid2_off(void);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);

    // De-energize both solenoids
    solenoid1_off();
    solenoid2_off();

    // Close GPIO lines
    if (solenoid1_line) {
        gpiod_line_release(solenoid1_line);
    }
    if (solenoid2_line) {
        gpiod_line_release(solenoid2_line);
    }

    // Close GPIO chip
    if (gpiochip) {
        gpiod_chip_close(gpiochip);
    }

    fprintf(stderr, "Cleanup complete. Exiting.\n");
    exit(0);
}

// Initialize GPIO lines
int gpio_init(void) {
    int ret;

    // Open GPIO chip
    gpiochip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpiochip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Get line for solenoid 1
    solenoid1_line = gpiod_chip_get_line(gpiochip, SOLENOID1_GPIO);
    if (!solenoid1_line) {
        fprintf(stderr, "Error getting line for GPIO %d: %s\n", SOLENOID1_GPIO, strerror(errno));
        gpiod_chip_close(gpiochip);
        return -1;
    }

    // Get line for solenoid 2
    solenoid2_line = gpiod_chip_get_line(gpiochip, SOLENOID2_GPIO);
    if (!solenoid2_line) {
        fprintf(stderr, "Error getting line for GPIO %d: %s\n", SOLENOID2_GPIO, strerror(errno));
        gpiod_line_release(solenoid1_line);
        gpiod_chip_close(gpiochip);
        return -1;
    }

    // Request lines for output
    ret = gpiod_line_request_output(solenoid1_line, "solenoid1", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d for output: %s\n", SOLENOID1_GPIO, strerror(errno));
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        gpiod_chip_close(gpiochip);
        return -1;
    }

    ret = gpiod_line_request_output(solenoid2_line, "solenoid2", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d for output: %s\n", SOLENOID2_GPIO, strerror(errno));
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        gpiod_chip_close(gpiochip);
        return -1;
    }

