#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <errno.h>

// Define GPIO pins for door locks
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define UART device paths
#define UART0_DEVICE "/dev/serial0"
#define UART1_DEVICE "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define expected code
#define EXPECTED_CODE "123456"

// Define timeout in seconds
#define TIMEOUT_SECONDS 5

// Define unlock duration in seconds
#define UNLOCK_DURATION 2

// Global variables for UART file descriptors
int uart0_fd = -1;
int uart1_fd = -1;

// Function prototypes
int initialize_gpio();
int open_serial_port(const char *device);
int read_code(int fd, char *code, int timeout_seconds);
int compare_codes(const char *code1, const char *code2, const char *expected_code);
int control_locks(int lock1_gpio, int lock2_gpio, int unlock);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Cleaning up and exiting.\n", signal);

    // Set both locks to LOW (locked)
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);

    // Close UART file descriptors
    if (uart0_fd != -1) {
        close(uart0_fd);
    }
    if (uart1_fd != -1) {
        close(uart1_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Initialize pigpio and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);

    // Set both locks to LOW (locked) initially
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);

    return 0;
}

// Open a serial port
int open_serial_port(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening serial port %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios options;
    tcgetattr(fd, &options);
    options.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;
    tcflush(fd, TCIFLUSH);
    tcsetattr(fd, TCSANOW, &options);

    return fd;
}

// Read a 6-digit code from a serial port with timeout
int read_code(int fd, char *code, int timeout_seconds) {
    time_t start_time = time(NULL);
    int i = 0;

    // Clear the code buffer
    memset(code, 0, 7); // 6 digits + null terminator

    while (1) {
        fd_set readfds;
        struct timeval tv;

        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        tv.tv_sec = 1; // Check every second
        tv.tv_usec = 0;

        int retval = select(fd + 1, &readfds, NULL, NULL, &tv);

        if (retval == -1) {
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            return -1;
        } else if (retval) {
            // Data is available to read
            int c = getchar();
            if (c == EOF) {
                fprintf(stderr, "Error reading from serial port\n");
                return -1;
            }

            if (c >= '0' && c <= '9') {
                code[i++] = (char)c;
                if (i == 6) {
                    code[i] = '\0'; // Null-terminate the string
                    return 0; // Code received successfully
                }
            } else {
                // Non-digit character, reset the buffer
                i = 0;
            }
        } else {
            // Timeout
            if (time(NULL) - start_time >= timeout_seconds) {
                fprintf(stderr, "Timeout reading code from serial port\n");
                return -1;
            }
        }
    }
}

// Compare two codes in constant time
int compare_codes(const char *code1, const char *code2, const char *expected_code) {
    if (strlen(code1) != strlen(expected_code) || strlen(code2) != strlen(expected_code)) {
        return 0; // Codes are not the same length
    }

    int result = 0;
    for (int i = 0; i < strlen(expected_code); i++) {
        result |= (code1[i] ^ expected_code[i]);
        result |= (code2[i] ^ expected_code[i]);
    }

    return (result == 0);
}

// Control the door locks
int control_locks(int lock1_gpio, int lock2_gpio, int unlock) {
    if (gpioWrite(lock1_gpio, unlock) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", lock1_gpio);
        return -1;
    }
    if (gpioWrite(lock2_gpio, unlock) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", lock2_gpio);
        return -1;
    }

    if (unlock) {
        gpioDelay(UNLOCK_DURATION * 1000000); // Delay for unlock duration (in microseconds)
    }

    if (gpioWrite(lock1_gpio, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", lock1_gpio);
        return -1;
    }
    if (gpioWrite(lock2_gpio, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", lock2_gpio);
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open serial ports
    uart0_fd = open_serial_port(UART0_DEVICE);
    if (uart0_fd == -1) {
        gpioTerminate();
        return 1;
    }

    uart1_fd = open_serial_port(UART1_DEVICE);
    if (uart1_fd == -1) {
        close(uart0_fd);
        gpioTerminate();
        return 1;
    }

    char code0[7] = {0}; // 6 digits + null terminator
    char code1[7] = {0}; // 6 digits + null terminator

    // Main loop
    while (1) {
        // Read code from UART0
        if (read_code(uart0_fd, code0, TIMEOUT_SECONDS) == 0) {
            printf("Code from UART0: %s\n", code0);
        } else {
            code0[0] = '\0'; // Reset code if read fails
        }

        // Read code from UART1
        if (read_code(uart1_fd, code1, TIMEOUT_SECONDS) == 0) {
            printf("Code from UART1: %s\n", code1);
        } else {
            code1[0] = '\0'; // Reset code if read fails
        }

        // Check if both codes are valid and match the expected code
        if (strlen(code0) == 6 && strlen(code1) == 6 && compare_codes(code0, code1, EXPECTED_CODE)) {
            printf("Codes match. Unlocking doors.\n");
            if (control_locks(LOCK1_GPIO, LOCK2_GPIO, 1) != 0) {
                fprintf(stderr, "Error controlling locks\n");
            }
            printf("Doors locked.\n");
        }

        gpioDelay(100000); // Small delay to prevent busy-waiting
    }

    return 0;
}

