#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_TIME 1  // seconds
#define PIR_READ_INTERVAL 50 // milliseconds
#define PIR_TIMEOUT 10 // seconds

// Global variables
static volatile int running = 1;
static volatile unsigned long last_motion_time = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_relay(int state);
void log_event(int priority, const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    log_event(LOG_INFO, "Received signal, shutting down...");
    control_relay(0); // Ensure relay is off
    gpioTerminate();   // Terminate pigpio
    closelog();        // Close syslog
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    log_event(LOG_INFO, "GPIO initialisation complete");
    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Control relay state
int control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    return 0;
}

// Log events to syslog
void log_event(int priority, const char *message) {
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    log_event(LOG_INFO, "Door strike system started");

    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            unsigned long current_time = time(NULL);
            if (last_motion_time == 0) {
                last_motion_time = current_time;
            }

            if (difftime(current_time, last_motion_time) > PIR_TIMEOUT) {
                log_event(LOG_WARNING, "PIR sensor timeout, de-energizing relay");
                control_relay(0);
                last_motion_time = 0; // Reset timeout
            } else {
                log_event(LOG_INFO, "Motion detected, activating relay");
                control_relay(1);
                gpioDelay(RELAY_ON_TIME * 1000); // Delay for 1 second
                control_relay(0);
                log_event(LOG_INFO, "Relay deactivated");
                last_motion_time = 0; // Reset timeout after successful strike
            }
        } else {
            last_motion_time = 0; // Reset timeout if no motion
        }

        gpioDelay(PIR_READ_INTERVAL); // Delay for 50ms
    }

    log_event(LOG_INFO, "Door strike system stopped");
    return 0;
}

