// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int mpu6050_init(int fd);
accel_data_t read_acceleration(int fd);
void buffer_add(circular_buffer_t *buffer, accel_data_t data);
accel_data_t buffer_get_latest(circular_buffer_t *buffer);
void *timer_callback(void *arg);
void signal_handler(int sig);
int create_sysfs_file(const char *path);
int write_sysfs_file(int fd, const char *data);
void cleanup();

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write (register select) failed: %s", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// MPU6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU6050
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) != 0) {
        syslog(LOG_ERR, "Failed to wake up MPU6050");
        return -1;
    }

    // Set accelerometer range to +-2g
    if (i2c_write_byte(fd, ACCEL_CONFIG, 0x00) != 0) {
        syslog(LOG_ERR, "Failed to set accelerometer range");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
accel_data_t read_acceleration(int fd) {
    uint8_t data[6];
    accel_data_t accel_data;

    if (i2c_read_bytes(fd, ACCEL_XOUT_H, data, 6) != 0) {
        syslog(LOG_ERR, "Failed to read acceleration data");
        accel_data.x = 0.0;
        accel_data.y = 0.0;
        accel_data.z = 0.0;
        return accel_data;
    }

    // Combine high and low bytes, and scale to g
    accel_data.x = (double)((int16_t)((data[0] << 8) | data[1])) / 16384.0;
    accel_data.y = (double)((int16_t)((data[2] << 8) | data[3])) / 16384.0;
    accel_data.z = (double)((int16_t)((data[4] << 8) | data[5])) / 16384.0;

    return accel_data;
}

// Function to add data to the circular buffer
void buffer_add(circular_buffer_t *buffer, accel_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Function to get the latest data from the circular buffer
accel_data_t buffer_get_latest(circular_buffer_t *buffer) {
    pthread_mutex_lock(&buffer->mutex);
    accel_data_t latest_data = buffer->data[(buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE];
    pthread_mutex_unlock(&buffer->mutex);
    return latest_data;
}

