// Define GPIO pins for the relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define prime number intervals (in seconds)
#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize a GPIO pin as output
int initialize_gpio(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", pin);
        return -1;
    }
    return 0;
}

// Function to toggle a relay
void toggle_relay(int pin) {
    int current_level = gpioRead(pin);
    if (gpioWrite(pin, !current_level) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", pin);
    }
}

// Function to turn off a relay
void turn_off_relay(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", pin);
    }
}

// Function to handle the timing and toggling of a relay
void handle_relay(int pin, int interval) {
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (program_running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        if (elapsed_time >= interval) {
            toggle_relay(pin);
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }
        gpioDelay(100); // Small delay to prevent busy-waiting
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio(RELAY1_PIN) != 0 ||
        initialize_gpio(RELAY2_PIN) != 0 ||
        initialize_gpio(RELAY3_PIN) != 0 ||
        initialize_gpio(RELAY4_PIN) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop to handle relays
    while (program_running) {
        handle_relay(RELAY1_PIN, INTERVAL1);
        handle_relay(RELAY2_PIN, INTERVAL2);
        handle_relay(RELAY3_PIN, INTERVAL3);
        handle_relay(RELAY4_PIN, INTERVAL4);
    }

    // Turn off all relays before exiting
    turn_off_relay(RELAY1_PIN);
    turn_off_relay(RELAY2_PIN);
    turn_off_relay(RELAY3_PIN);
    turn_off_relay(RELAY4_PIN);

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

