    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate the relay for a specified duration
int activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Turn relay on
    gpioDelay(RELAY_ON_TIME * 1000000); // Delay for 3 seconds (microseconds)
    gpioWrite(RELAY_PIN, 0); // Turn relay off
    return 0;
}

// Log alarm event to file
int log_alarm() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening alarm_log.txt");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
    fclose(fp);
    return 0;
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound-activated relay system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 1) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_activation_time) >= DEBOUNCE_TIME) {
                printf("Sound detected! Activating relay.\n");
                activate_relay();
                log_alarm();
                last_activation_time = current_time;
            } else {
                printf("Sound detected, but debouncing...\n");
            }
        }

        gpioDelay(POLL_INTERVAL * 1000); // Delay for 100ms (microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate(); // Terminate pigpio

    return 0;
}

