#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75
#define GYRO_XOUT_H 0x43

// Gyroscope sensitivity (LSB/deg/s)
#define GYRO_SENSITIVITY 131.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (deg/s)
#define ANGULAR_VELOCITY_THRESHOLD 50.0f

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Structure for circular buffer
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_fd = -1; // I2C file descriptor
circular_buffer_t gyro_buffer;
bool running = true; // Flag to control the main loop

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
gyro_data_t read_gyro_data(int fd);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
gyro_data_t get_latest_data(circular_buffer_t *buffer);
float calculate_magnitude(gyro_data_t data);
void threshold_callback(gyro_data_t data);
void signal_handler(int signal);
int initialize_i2c(const char *device);
void cleanup();

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return value;
}

// I2C read multiple bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data(int fd) {
    gyro_data_t data;
    uint8_t raw_data[6];

    if (i2c_read_bytes(fd, GYRO_XOUT_H, raw_data, 6) != 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        data.x = 0.0f;
        data.y = 0.0f;
        data.z = 0.0f;
        return data;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    int16_t gyro_x = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    int16_t gyro_y = (int16_t)((raw_data[2] << 8) | raw_data[3]);
    int16_t gyro_z = (int16_t)((raw_data[4] << 8) | raw_data[5]);

    // Convert to degrees per second
    data.x = (float)gyro_x / GYRO_SENSITIVITY;
    data.y = (float)gyro_y / GYRO_SENSITIVITY;
    data.z = (float)gyro_z / GYRO_SENSITIVITY;

    return data;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get the latest data from the circular buffer
gyro_data_t get_latest_data(circular_buffer_t *buffer) {
    if (buffer->count == 0) {
        gyro_data_t empty_data = {0.0f, 0.0f, 0.0f};
        return empty_data;
    }
    int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->data[index];
}

// Calculate the magnitude of the angular velocity vector
float calculate_magnitude(gyro_data_t data) {
    return sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Threshold callback function
void threshold_callback(gyro_data_t data) {
    printf("Threshold exceeded! X: %.2f, Y: %.2f, Z: %.2f\n", data.x, data.y, data.z);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = false;
}

// Initialize I2C
int initialize_i2c(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

int main() {
    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = initialize_i2c("/dev/i2c-1");
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Wake up the MPU-6050
    if (i2c_write_byte(i2c_fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake up MPU-6050. Exiting.\n");
        cleanup();
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2c_read_byte(i2c_fd, WHO_AM_I);
    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I returned 0x%x, expected 0x68. Exiting.\n", who_am_i);
        cleanup();
        return 1;
    }

    printf("MPU-6050 initialized successfully.\n");

    // Main loop
    while (running) {
        gyro_data_t gyro_data = read_gyro_data(i2c_fd);
        add_to_buffer(&gyro_buffer, gyro_data);

        float magnitude = calculate_magnitude(gyro_data);

        if (magnitude > ANGULAR_VELOCITY_THRESHOLD) {
            threshold_callback(gyro_data);
        }

        usleep(10000); // 10ms delay
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

