void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to log errors with timestamp
void log_error(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[256];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld: %s\n", tmbuf, tv.tv_usec, message);

    if (error_log_file != NULL) {
        fprintf(error_log_file, "%s", buf);
        fflush(error_log_file);
    } else {
        fprintf(stderr, "%s", buf);
    }
}

// Function to read CO2 concentration from the MH-Z19B sensor
int read_co2(int uart_handle, unsigned char *response) {
    int bytes_read = 0;
    int start_time = time(NULL);

    // Send the read command
    if (serWrite(uart_handle, read_command, READ_COMMAND_LENGTH) != READ_COMMAND_LENGTH) {
        log_error("Failed to write read command to UART.");
        return -1;
    }

    // Wait for data to be available with timeout
    while (serDataAvailable(uart_handle) < READ_RESPONSE_LENGTH && (time(NULL) - start_time) < (TIMEOUT_MS / 1000.0)) {
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    if (serDataAvailable(uart_handle) < READ_RESPONSE_LENGTH) {
        log_error("Timeout waiting for data from UART.");
        return -1;
    }

    // Read the response
    bytes_read = serRead(uart_handle, response, READ_RESPONSE_LENGTH);
    if (bytes_read != READ_RESPONSE_LENGTH) {
        log_error("Failed to read complete response from UART.");
        return -1;
    }

    return 0;
}

// Function to validate the checksum of the response
int validate_checksum(const unsigned char *response) {
    unsigned char checksum = 0;
    for (int i = 1; i < 8; i++) {
        checksum += response[i];
    }
    checksum = 0xFF - checksum + 1;

    if (checksum != response[8]) {
        log_error("Checksum validation failed.");
        return -1;
    }
    return 0;
}

// Function to extract the CO2 concentration from the response
int extract_co2(const unsigned char *response) {
    return (response[2] << 8) | response[3];
}

// Function to log the CO2 data to a file and stdout
void log_data(int co2_ppm, int error_flag) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[256];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "{\"timestamp\": \"%s.%06ld\", \"co2_ppm\": %d, \"error\": %d}\n", tmbuf, tv.tv_usec, co2_ppm, error_flag);

    printf("%s", buf);

    if (log_file != NULL) {
        fprintf(log_file, "%s", buf);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the UART
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        log_error("Failed to open UART.");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file.");
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    // Open the error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file.\n");
        fclose(log_file);
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char response[READ_RESPONSE_LENGTH];
    int co2_ppm;
    int error_flag;

    // Main loop
    while (1) {
        error_flag = 0;

        // Read CO2 concentration
        if (read_co2(uart_handle, response) != 0) {
            error_flag = 1;
        } else {
            // Validate checksum
            if (validate_checksum(response) != 0) {
                error_flag = 1;
            } else {
                // Extract CO2 concentration
                co2_ppm = extract_co2(response);
            }
        }

        // Log the data
        if (error_flag == 0) {
            log_data(co2_ppm, error_flag);
        } else {
            log_data(0, error_flag); // Log 0 ppm on error
        }

        gpioDelay(READ_INTERVAL_SEC * 1000); // Wait for the next reading
    }

    // The following lines will never be reached due to the infinite loop.
    fclose(log_file);
    fclose(error_log_file);
    serClose(uart_handle);
    gpioTerminate();
    return 0;
}

