#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03

// Hard-iron offsets
#define HARD_IRON_X_OFFSET 100
#define HARD_IRON_Y_OFFSET -50

// GPIO pin for output
#define GPIO_PIN 17

// Target heading
#define TARGET_HEADING 90.0

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold heading data
typedef struct {
    float heading;
} HeadingData;

// Circular buffer
HeadingData heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int initialize_hmc5883l();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
void apply_hard_iron_compensation(int16_t *x, int16_t *y);
void update_circular_buffer(float heading);
void control_gpio(float heading);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(GPIO_PIN, 0); // Set GPIO low
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the HMC5883L
int initialize_hmc5883l() {
    // Configure register A
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A register\n");
        return -1;
    }

    // Configure register B
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B register\n");
        return -1;
    }

    // Configure register MODE
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE register\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate heading
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Function to apply hard-iron compensation
void apply_hard_iron_compensation(int16_t *x, int16_t *y) {
    *x -= HARD_IRON_X_OFFSET;
    *y -= HARD_IRON_Y_OFFSET;
}

// Function to update the circular buffer
void update_circular_buffer(float heading) {
    heading_buffer[buffer_index].heading = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to control GPIO based on heading deviation
void control_gpio(float heading) {
    float deviation = fabs(heading - TARGET_HEADING);
    if (deviation > 10.0) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO high
    } else {
        gpioWrite(GPIO_PIN, 0); // Set GPIO low
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading;

    // Main loop
    while (1) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Apply hard-iron compensation
            apply_hard_iron_compensation(&x, &y);

            // Calculate heading
            heading = calculate_heading(x, y);

            // Update circular buffer
            update_circular_buffer(heading);

            // Control GPIO
            control_gpio(heading);

            // Print heading (for debugging)
            printf("Heading: %.2f\n", heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    return 0;
}

