#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Define GPIO pins for relays
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22

// Define I2C bus and address for BH1750 sensor
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define lux thresholds
#define LUX_THRESHOLD_RED 50
#define LUX_THRESHOLD_GREEN 150
#define LUX_THRESHOLD_BLUE 300

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750();
void set_relay_state(int red, int green, int blue);
void log_data(int lux, int red, int green, int blue);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read lux value from BH1750 sensor
int read_bh1750() {
    unsigned char config_cmd = 0x10; // Continuous high-resolution mode
    unsigned char buffer[2];
    int lux = -1; // Default to error value

    // Configure sensor for continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, config_cmd) != 0) {
        fprintf(stderr, "Error configuring BH1750: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(120); // Wait for at least 120ms

    // Read 2 bytes of data
    if (i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 2) != 2) {
        fprintf(stderr, "Error reading BH1750 data: %s\n", strerror(errno));
        return -1;
    }

    // Convert raw data to lux value
    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    lux = raw_value / 1.2;

    return lux;
}

// Function to set the state of the relays
void set_relay_state(int red, int green, int blue) {
    gpioWrite(RED_RELAY_PIN, red);
    gpioWrite(GREEN_RELAY_PIN, green);
    gpioWrite(BLUE_RELAY_PIN, blue);
}

// Function to log data to file
void log_data(int lux, int red, int green, int blue) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Lux: %d, Red: %d, Green: %d, Blue: %d\n", timestamp, lux, red, green, blue);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Initialization function
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_RELAY_PIN, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("lighting_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off all relays
    set_relay_state(0, 0, 0);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int lux = read_bh1750();

        if (lux == -1) {
            fprintf(stderr, "Error reading lux value, using previous state.\n");
        } else {
            int red = 0, green = 0, blue = 0;

            if (lux < LUX_THRESHOLD_RED) {
                red = 1;
            } else if (lux < LUX_THRESHOLD_GREEN) {
                green = 1;
            } else if (lux < LUX_THRESHOLD_BLUE) {
                blue = 1;
            } else {
                red = green = blue = 1;
            }

            set_relay_state(red, green, blue);
            log_data(lux, red, green, blue);
        }

        sleep(1);
    }

    // Cleanup
    cleanup();

    printf("Smart Lighting System terminated.\n");
    return 0;
}

