    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("lighting_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off all relays
    set_relay_state(0, 0, 0);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int lux = read_bh1750();

        if (lux == -1) {
            fprintf(stderr, "Error reading lux value, using previous state.\n");
        } else {
            int red = 0, green = 0, blue = 0;

            if (lux < LUX_THRESHOLD_RED) {
                red = 1;
            } else if (lux < LUX_THRESHOLD_GREEN) {
                green = 1;
            } else if (lux < LUX_THRESHOLD_BLUE) {
                blue = 1;
            } else {
                red = green = blue = 1;
            }

            set_relay_state(red, green, blue);
            log_data(lux, red, green, blue);
        }

        sleep(1);
    }

    // Cleanup
    cleanup();

    printf("Smart Lighting System terminated.\n");
    return 0;
}

