#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define SERVO_GPIO 18
#define PWM_CHIP 2
#define PWM_NUM 0
#define PWM_PERIOD 20000 // 20ms (50Hz)
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 5

// MPU6050 Registers
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_CONFIG 0x1A
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_ACCEL_CONFIG 0x1C

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *data, int len);
int i2c_write_byte(int fd, unsigned char reg, unsigned char value);
int init_mpu6050(int fd);
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll);
int set_servo_angle(int angle);
int log_data(float pitch, float roll, int servo_angle);
void signal_handler(int sig);
int export_pwm(int chip, int num);
int unexport_pwm(int chip, int num);
int set_pwm_period(int chip, int num, int period);
int set_pwm_duty_cycle(int chip, int num, int duty_cycle);
int enable_pwm(int chip, int num);
int disable_pwm(int chip, int num);

// I2C read function with exponential backoff
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *data, int len) {
    int retries = 0;
    int delay_ms = 10;
    int result;

    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            perror("Error: Could not set I2C slave address");
            return -1;
        }

        if (write(fd, &reg, 1) != 1) {
            perror("Error: Could not write register address");
            return -1;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C read failed (attempt %d/%d), retrying in %dms\n", retries + 1, MAX_RETRIES, delay_ms);
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            retries++;
        }
    }

    fprintf(stderr, "Error: I2C read failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// I2C write function with exponential backoff
int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    int retries = 0;
    int delay_ms = 10;
    unsigned char buf[2];
    int result;

    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            perror("Error: Could not set I2C slave address");
            return -1;
        }

        buf[0] = reg;
        buf[1] = value;

        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C write failed (attempt %d/%d), retrying in %dms\n", retries + 1, MAX_RETRIES, delay_ms);
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            retries++;
        }
    }

    fprintf(stderr, "Error: I2C write failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Initialize MPU6050
int init_mpu6050(int fd) {
    // Wake up the MPU6050
    if (i2c_write_byte(fd, MPU6050_PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050\n");
        return -1;
    }

    // Set sample rate divider
    if (i2c_write_byte(fd, MPU6050_SMPLRT_DIV, 7) < 0) { // Sample rate = 1kHz / (7+1) = 125 Hz
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    // Configure DLPF (Digital Low Pass Filter)
    if (i2c_write_byte(fd, MPU6050_CONFIG, 0x03) < 0) { // Set DLPF_CFG to 3 for ~44 Hz bandwidth
        fprintf(stderr, "Error: Could not configure DLPF\n");
        return -1;
    }

