int i2c_read_bytes(int fd, unsigned char reg, unsigned char *data, int len) {
    int retries = 0;
    int delay_ms = 10;
    int result;

    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            perror("Error: Could not set I2C slave address");
            return -1;
        }

        if (write(fd, &reg, 1) != 1) {
            perror("Error: Could not write register address");
            return -1;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C read failed (attempt %d/%d), retrying in %dms\n", retries + 1, MAX_RETRIES, delay_ms);
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            retries++;
        }
    }

    fprintf(stderr, "Error: I2C read failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

