        // Set servo angle (example: map pitch to servo angle)
        servo_angle = (int)(pitch * 180.0 / 90.0); // Map pitch (-90 to 90) to servo angle (0 to 180)
        if (servo_angle < 0) servo_angle = 0;
        if (servo_angle > 180) servo_angle = 180;

        // Set servo angle
        if (set_servo_angle(servo_angle) < 0) {
            fprintf(stderr, "Error: Could not set servo angle\n");
        }

        // Log data
        if (log_data(pitch, roll, servo_angle) < 0) {
            fprintf(stderr, "Error: Could not log data\n");
        }

        usleep(50000); // 50ms delay
    }

    // Cleanup
    disable_pwm(PWM_CHIP, PWM_NUM);
    unexport_pwm(PWM_CHIP, PWM_NUM);
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

