#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define fade duration (seconds)
#define FADE_DURATION 1800

// Define schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on_off;
} schedule_entry_t;

// Global variables
static volatile int running = 1;
static schedule_entry_t *schedule = NULL;
static int schedule_size = 0;

// Function prototypes
int read_schedule(const char *filename, schedule_entry_t **schedule, int *schedule_size);
int parse_schedule_entry(const char *line, schedule_entry_t *entry);
int compare_schedule_entry(const schedule_entry_t *entry, const struct tm *current_time);
void fade_lamp(int relay_number, int on_off);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to read the schedule from a file
int read_schedule(const char *filename, schedule_entry_t **schedule, int *schedule_size) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    // Determine the number of lines in the file
    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        count++;
    }

    // Allocate memory for the schedule
    *schedule = (schedule_entry_t *)malloc(count * sizeof(schedule_entry_t));
    if (*schedule == NULL) {
        perror("Error allocating memory for schedule");
        fclose(fp);
        return -1;
    }

    // Rewind the file pointer to the beginning
    rewind(fp);

    // Read the schedule entries
    int i = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (parse_schedule_entry(line, &(*schedule)[i]) != 0) {
            fprintf(stderr, "Error parsing schedule entry: %s", line);
            free(*schedule);
            fclose(fp);
            return -1;
        }
        i++;
    }

    *schedule_size = count;
    fclose(fp);
    return 0;
}

// Function to parse a schedule entry from a line of text
int parse_schedule_entry(const char *line, schedule_entry_t *entry) {
    if (sscanf(line, "%d:%d:%d,%d,%d", &entry->hour, &entry->minute, &entry->second, &entry->relay_number, &entry->on_off) != 5) {
        fprintf(stderr, "Invalid schedule entry format: %s", line);
        return -1;
    }

    // Validate the data
    if (entry->hour < 0 || entry->hour > 23 ||
        entry->minute < 0 || entry->minute > 59 ||
        entry->second < 0 || entry->second > 59 ||
        entry->relay_number < 1 || entry->relay_number > 4 ||
        (entry->on_off != 1 && entry->on_off != 0)) {
        fprintf(stderr, "Invalid values in schedule entry: %s", line);
        return -1;
    }

    return 0;
}

// Function to compare a schedule entry with the current time
int compare_schedule_entry(const schedule_entry_t *entry, const struct tm *current_time) {
    return (entry->hour == current_time->tm_hour &&
            entry->minute == current_time->tm_min &&
            entry->second == current_time->tm_sec);
}

// Function to fade the lamp brightness using PWM
void fade_lamp(int relay_number, int on_off) {
    int gpio_pin;
    switch (relay_number) {
        case 1:
            gpio_pin = RELAY1_GPIO;
            break;
        case 2:
            gpio_pin = RELAY2_GPIO;
            break;
        case 3:
            gpio_pin = RELAY3_GPIO;
            break;
        case 4:
            gpio_pin = RELAY4_GPIO;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    int start_duty = (on_off == 1) ? 0 : 100;
    int end_duty = (on_off == 1) ? 100 : 0;
    int duty_cycle = start_duty;
    int increment = (end_duty - start_duty) / FADE_DURATION;

    for (int i = 0; i <= FADE_DURATION; i++) {
        gpioPWM(gpio_pin, duty_cycle);
        duty_cycle += increment;
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;
        gpioDelay(1000); // 1 second delay
    }
}

// Function to cleanup GPIO resources
void cleanup() {
    printf("Cleaning up GPIO resources...\n");
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_GPIO, PWM_FREQUENCY);

    // Read the schedule from the file
    if (read_schedule(SCHEDULE_FILE, &schedule, &schedule_size) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart Home Lighting System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Get the current time
        time_t now = time(NULL);
        struct tm current_time;
        localtime_r(&now, &current_time);

        // Check the schedule
        for (int i = 0; i < schedule_size; i++) {
            if (compare_schedule_entry(&schedule[i], &current_time)) {
                printf("Matching schedule entry found: %d:%d:%d, Relay %d, %s\n",
                       schedule[i].hour, schedule[i].minute, schedule[i].second,
                       schedule[i].relay_number, schedule[i].on_off ? "ON" : "OFF");
                fade_lamp(schedule[i].relay_number, schedule[i].on_off);
            }
        }

        sleep(1); // Check every second
    }

    // Cleanup and exit
    free(schedule);
    cleanup();
    return 0;
}

