#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 30.0     // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define MEASUREMENT_INTERVAL 60 // ms

// Global variable for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the ultrasonic sensor
float measureDistance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    triggerSensor();

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 10000) {
        fprintf(stderr, "Error: Echo pin did not go high (timeout).\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 10000) {
        fprintf(stderr, "Error: Echo pin did not go low (timeout).\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    // Calculate the pulse width in microseconds
    diff_tick = end_tick - start_tick;
    if (diff_tick < 0) {
        diff_tick += 0xFFFFFFFF; // Handle tick rollover
    }

    // Calculate the distance in centimeters
    float distance = (diff_tick / 1000000.0) * SPEED_OF_SOUND / 2.0;

    return distance;
}

// Function to map distance to frequency
float mapDistanceToFrequency(float distance) {
    // Clamp the distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Linearly map the distance to the frequency range
    float frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);

    return frequency;
}

// Function to set the buzzer frequency
void setBuzzerFrequency(float frequency) {
    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
    gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Measure the distance
        float distance = measureDistance();

        if (distance > 0) {
            // Map the distance to a frequency
            float frequency = mapDistanceToFrequency(distance);

            // Set the buzzer frequency
            setBuzzerFrequency(frequency);

            // Print the distance and frequency (for debugging)
            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        } else {
            // Handle measurement error
            fprintf(stderr, "Error: Distance measurement failed.\n");
        }

        // Wait for the next measurement
        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Convert ms to us
    }

    // Clean up and exit
    gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
    gpioTerminate();
    printf("Theremin stopped.\n");
    return 0;
}

