#include <signal.h>
#include <pigpio.h>
#include <math.h>
#include <unistd.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to generate a proximity value based on a sine wave
float generate_proximity_value() {
    static double phase = 0.0;
    phase += 0.1; // Increment phase for smooth oscillation
    if (phase > 2.0 * M_PI) {
        phase -= 2.0 * M_PI; // Keep phase within 0 to 2*pi
    }
    return 0.5 + 0.5 * sin(phase); // Sine wave oscillating between 0 and 1
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RED_PIN to output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GREEN_PIN to output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BLUE_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency for each pin
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for RED_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != 0) {
