#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity factor for ±250 deg/s
#define GYRO_SENSITIVITY 131.0

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Log file name
#define LOG_FILE "gyro_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Function prototypes
int init_i2c(int address);
int write_register(int fd, uint8_t reg, uint8_t value);
int read_block(int fd, uint8_t reg, uint8_t *data, int len);
gyro_data_t read_gyro_data(int fd);
void convert_gyro_data(gyro_data_t raw_data, float *x, float *y, float *z);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    terminate = 1;
}

// Initialize I2C
int init_i2c(int address) {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Write to a register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return 0;
}

// Read a block of data
int read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for block read: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading block of data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data(int fd) {
    gyro_data_t data;
    uint8_t buffer[6];

    if (read_block(fd, GYRO_XOUT_H, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return 0 values on error
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Convert raw gyroscope data to degrees/second
void convert_gyro_data(gyro_data_t raw_data, float *x, float *y, float *z) {
    *x = (float)raw_data.x / GYRO_SENSITIVITY;
    *y = (float)raw_data.y / GYRO_SENSITIVITY;
    *z = (float)raw_data.z / GYRO_SENSITIVITY;
}

// Log data to file
void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Wake up the MPU-6050
    if (write_register(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        gyro_data_t raw_data = read_gyro_data(i2c_fd);
        float x, y, z;
        convert_gyro_data(raw_data, &x, &y, &z);
        log_data(log_file, x, y, z);
        usleep(100000); // 100 ms
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

