#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define PWM frequency and duty cycle
#define PWM_FREQUENCY 440 // Hz
#define PWM_DUTY_CYCLE 128 // 50% of 255

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define melody data (frequency, duration in ms)
const unsigned char melody[] = {
    262, 250, 0, 294, 250, 0, 330, 250, 0, 349, 250, 0, 392, 250, 0, 440, 250, 0, 494, 250, 0, 523, 250, 0, 587, 250, 0, 659, 250, 0, 698, 250, 0, 784, 250, 0, 880, 250, 0, 988, 250, 0, 1047, 250, 0, 0, 0 // End marker
};

// Global variables
volatile int running = 1;
volatile unsigned long last_interrupt_time = 0;

// Function prototypes
void signal_handler(int signal);
void button_interrupt_handler(int gpio, int level, unsigned int tick, void *user_data);
void play_melody();
void stop_melody();

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    stop_melody();
    gpioTerminate();
    exit(0);
}

// Interrupt handler for button press
void button_interrupt_handler(int gpio, int level, unsigned unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();

    if (current_time - last_interrupt_time > DEBOUNCE_TIME * 1000) {
        last_interrupt_time = current_time;

        if (level == 0) { // Button pressed (active low)
            printf("Button pressed!\n");
            play_melody();
        } else if (level == 1) { // Button released
            printf("Button released!\n");
            stop_melody();
        }
    }
}

// Function to play the melody
void play_melody() {
    int i = 0;
    while (melody[i] != 0) {
        int frequency = melody[i++];
        int duration = melody[i++];

        if (frequency == 0) {
            gpioDelay(duration * 1000); // Rest
        } else {
            gpioHardwarePWM(BUZZER_PIN, frequency, PWM_DUTY_CYCLE);
            gpioDelay(duration * 1000);
        }
    }
    stop_melody(); // Stop after melody is done
}

// Function to stop the melody
void stop_melody() {
    gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop PWM
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", BUTTON_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", BUZZER_PIN);
        gpioTerminate();
        return 1;
    }

    // Enable internal pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set interrupt handler for button press
    if (gpioSetISRFuncEx(BUTTON_PIN, EITHER_EDGE, 0, button_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for GPIO%d\n", BUTTON_PIN);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Musical doorbell running. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    return 0;
}

