#define GPIO_PIN 17
#define CHIP_NAME "gpiochip0"
#define LOG_FILE "vibration_events.log"
#define DEFAULT_TIMEOUT_MS 1000
#define WINDOW_SIZE 5

// Structure to hold the last few sensor readings
typedef struct {
    int readings[WINDOW_SIZE];
    int index;
} SlidingWindow;

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static int timeout_ms = DEFAULT_TIMEOUT_MS;
static SlidingWindow window = {{0}, 0};

// Function prototypes
void signal_handler(int sig);
int init_gpio(void);
void cleanup_gpio(void);
int read_sensor(void);
int log_event(int value);
void update_window(int value);
bool check_earthquake_alert(void);
char* get_iso8601_timestamp(void);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize GPIO
int init_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", CHIP_NAME);
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return -1;
