#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define MR_REG_M 0x02
#define CRA_REG_M 0x00
#define OUT_X_MSB 0x03
#define OUT_X_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define OUT_Y_MSB 0x07
#define OUT_Y_LSB 0x08

// Calibration offsets
#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f

// Global variables for signal handling
volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
        keep_running = 0;
    }
}

// Function to initialize the I2C interface
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to write a byte to an I2C register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C register");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("Error reading from I2C register");
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from I2C registers
int read_registers(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Error reading from I2C registers");
        return -1;
    }
    return 0;
}

// Function to read raw magnetometer data
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    if (read_registers(fd, OUT_X_MSB, buffer, 6) < 0) {
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 4;
    *z = (int16_t)((buffer[2] << 8) | buffer[3]) >> 4;
    *y = (int16_t)((buffer[4] << 8) | buffer[5]) >> 4;

    return 0;
}

// Function to calibrate magnetometer data
void calibrate_data(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z) {
    *calibrated_x = (float)x - X_OFFSET;
    *calibrated_y = (float)y - Y_OFFSET;
    *calibrated_z = (float)z - Z_OFFSET;
}

// Function to calculate compass heading
float calculate_heading(float x, float y) {
    float heading = atan2f(y, x) * 180.0f / M_PI;
    if (heading < 0) {
        heading += 360.0f;
    }
    return heading;
}

// Function to map heading to compass direction
const char *map_heading_to_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) return "N";
    if (heading >= 22.5 && heading < 67.5) return "NE";
    if (heading >= 67.5 && heading < 112.5) return "E";
    if (heading >= 112.5 && heading < 157.5) return "SE";
    if (heading >= 157.5 && heading < 202.5) return "S";
    if (heading >= 202.5 && heading < 247.5) return "SW";
    if (heading >= 247.5 && heading < 292.5) return "W";
    if (heading >= 292.5 && heading < 337.5) return "NW";
    return "Unknown";
}

// Function to log data to CSV file
int log_data(FILE *fp, float x, float y, float z, float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, x, y, z, heading);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(LSM303_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Configure magnetometer
    if (write_register(i2c_fd, MR_REG_M, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }
    if (write_register(i2c_fd, CRA_REG_M, 0x14) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen("mag_log.csv", "a+");
    if (log_file == NULL) {
        perror("Error opening CSV file");
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }

    int16_t raw_x, raw_y, raw_z;
    float calibrated_x, calibrated_y, calibrated_z, heading;
    const char *direction;

    // Main loop
    while (keep_running) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &raw_x, &raw_y, &raw_z) == 0) {
            // Calibrate data
            calibrate_data(raw_x, raw_y, raw_z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Map heading to direction
            direction = map_heading_to_direction(heading);

            // Print heading and direction to console
            printf("Heading: %.2f degrees, Direction: %s\n", heading, direction);

            // Log data to CSV file
            log_data(log_file, calibrated_x, calibrated_y, calibrated_z, heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data. Skipping sample.\n");
        }

        sleep(1);
    }

    // Close I2C device and CSV file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

