#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
int read_soil_moisture();
void control_relay(int relay_number, int state);
void log_event(int relay_number, int moisture_level);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d. Terminating program.\n", sig);
    terminate = 1;
}

// Function to initialize the GPIO lines
int initialize_gpio() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        return -1;
    }

    // Request the GPIO lines as outputs
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        fprintf(stderr, "Error getting GPIO line.\n");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "irrigation_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(relay1_line, &config, 1); // Initial state: HIGH (relay OFF)
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", RELAY1_PIN, strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(relay2_line, &config, 1); // Initial state: HIGH (relay OFF)
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", RELAY2_PIN, strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(relay3_line, &config, 1); // Initial state: HIGH (relay OFF)
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", RELAY3_PIN, strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(relay4_line, &config, 1); // Initial state: HIGH (relay OFF)
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", RELAY4_PIN, strerror(-ret));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to cleanup the GPIO lines
void cleanup_gpio() {
    if (relay1_line) {
        gpiod_line_set_value(relay1_line, 1); // Deactivate relay
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_set_value(relay2_line, 1); // Deactivate relay
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_set_value(relay3_line, 1); // Deactivate relay
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_set_value(relay4_line, 1); // Deactivate relay
        gpiod_line_release(relay4_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to read the simulated soil moisture level
int read_soil_moisture() {
    return rand() % 101; // Returns a value between 0 and 100
}

// Function to control the relay state
void control_relay(int relay_number, int state) {
    struct gpiod_line *line;

    switch (relay_number) {
        case 1:
            line = relay1_line;
            break;
        case 2:
            line = relay2_line;
            break;
        case 3:
            line = relay3_line;
            break;
        case 4:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    if (gpiod_line_set_value(line, state) < 0) {
        fprintf(stderr, "Error setting GPIO line value for relay %d: %s\n", relay_number, strerror(errno));
    }
}

// Function to log the event to a file
void log_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Relay: %d, Moisture: %d\n", timestamp, relay_number, moisture_level);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    int moisture_level;
    int i;

    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    fprintf(stderr, "Smart Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read the soil moisture level
        moisture_level = read_soil_moisture();

        // Check if irrigation is needed
        if (moisture_level < 30) {
            // Activate relays sequentially
            for (i = 1; i <= 4; i++) {
                if (terminate) break; // Check for termination signal
                control_relay(i, 0); // Activate relay (LOW)
                log_event(i, moisture_level);
                sleep(5); // Keep relay active for 5 seconds
                control_relay(i, 1); // Deactivate relay (HIGH)
                if (i < 4) sleep(1); // 1-second gap between relays
            }
        }

        sleep(10); // Check every 10 seconds
    }

    // Cleanup and exit
    fprintf(stderr, "Cleaning up and exiting.\n");
    cleanup_gpio();
    fclose(log_file);

    return 0;
}

