#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Define moisture threshold
#define MOISTURE_THRESHOLD 50

// Define servo pulse widths
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_NEUTRAL_PULSE_WIDTH 1500

// Define watering angles and durations
#define NUM_WATERING_STEPS 5
const int watering_angles[NUM_WATERING_STEPS] = {0, 45, 90, 135, 180};
const int watering_duration = 2000; // milliseconds

// Define valve open and close durations
#define VALVE_OPEN_DURATION 5000 // milliseconds
#define VALVE_CLOSE_DURATION 5000 // milliseconds

// Define delay between moisture readings
#define MOISTURE_READING_DELAY 5000 // milliseconds

// Global flag for graceful shutdown
volatile sig_atomic_t terminate_flag = 0;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating gracefully...\n", signal);
    terminate_flag = 1;
}

// Function to set servo angle
int set_servo_angle(int gpio, int angle) {
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    int result = gpioServo(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo angle for GPIO %d: %d\n", gpio, result);
        return -1;
    }
    return 0;
}

// Function to open the valve
int open_valve() {
    int retries = 3;
    int result = -1;
    while (retries > 0) {
        result = set_servo_angle(VALVE_SERVO_PIN, 90);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "Failed to open valve, retrying... (%d retries remaining)\n", retries - 1);
        gpioDelay(100); // 100 ms delay
        retries--;
    }
    fprintf(stderr, "Critical error: Failed to open valve after multiple retries!\n");
    return -1; // Failure
}

// Function to close the valve
int close_valve() {
    int retries = 3;
    int result = -1;
    while (retries > 0) {
        result = set_servo_angle(VALVE_SERVO_PIN, 0);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "Failed to close valve, retrying... (%d retries remaining)\n", retries - 1);
        gpioDelay(100); // 100 ms delay
        retries--;
    }
    fprintf(stderr, "Critical error: Failed to close valve after multiple retries!\n");
    return -1; // Failure
}

// Function to water the plant
void water_plant() {
    printf("Starting watering cycle...\n");

    // Open the valve
    if (open_valve() != 0) {
        fprintf(stderr, "Failed to open valve, aborting watering cycle.\n");
        return;
    }

    // Sweep the nozzle through the defined angles
    for (int i = 0; i < NUM_WATERING_STEPS; i++) {
        printf("Moving nozzle to %d degrees...\n", watering_angles[i]);
        if (set_servo_angle(NOZZLE_SERVO_PIN, watering_angles[i]) != 0) {
            fprintf(stderr, "Failed to set nozzle angle, continuing to next angle.\n");
            continue; // Continue to the next angle
        }
        gpioDelay(watering_duration); // Hold for the specified duration
    }

    // Close the valve
    if (close_valve() != 0) {
        fprintf(stderr, "Failed to close valve, but continuing anyway.\n");
    }

    printf("Watering cycle complete.\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
