#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity factor for ±250 deg/sec
#define GYRO_SENSITIVITY 131.0

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Log file
#define LOG_FILE "gyro_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050(int fd) {
    // Wake up the sensor
    if (i2c_smbus_write_byte_data(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, gyro_data_t *data) {
    int16_t raw_x, raw_y, raw_z;
    uint8_t buffer[6];

    // Read 6 bytes of gyroscope data
    if (read(fd, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert raw values to degrees/second
    data->x = (float)raw_x / GYRO_SENSITIVITY;
    data->y = (float)raw_y / GYRO_SENSITIVITY;
    data->z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Function to log data to file
int log_data(FILE *fp, gyro_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Write data to log file
    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z) < 0) {
        fprintf(stderr, "Error: Could not write to log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    gyro_data_t gyro_data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            // Log data
            if (log_data(log_file, gyro_data) != 0) {
                terminate = 1; // Stop logging on error
            }
        } else {
            terminate = 1; // Stop logging on error
        }

        // Sleep for 100ms (10 Hz sampling rate)
        usleep(100000);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

