    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    printf("Door unlocked.\n");
    return 0;
}

int main() {
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for motor control pins
    result = gpioSetMode(IN1, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting mode for IN1: %d\n", result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetMode(IN2, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting mode for IN2: %d\n", result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetMode(IN3, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting mode for IN3: %d\n", result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetMode(IN4, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting mode for IN4: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for button pins with pull-up resistors
    result = gpioSetMode(LOCK_BUTTON, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting mode for LOCK_BUTTON: %d\n", result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    if (result != 0) {
        fprintf(stderr, "Error setting pull-up for LOCK_BUTTON: %d\n", result);
        gpioTerminate();
        return 1;
    }

    result = gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    if (result != 0) {
        fprintf(stderr, "Error setting mode for UNLOCK_BUTTON: %d\n", result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);
    if (result != 0) {
        fprintf(stderr, "Error setting pull-up for UNLOCK_BUTTON: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Automatic door lock system started. Press LOCK button to lock, UNLOCK button to unlock. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for lock button press (active low)
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("LOCK button pressed.\n");
            lock_door();
            gpioDelay(200000); // Debounce delay (200 ms)
        }

        // Check for unlock button press (active low)
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("UNLOCK button pressed.\n");
            unlock_door();
            gpioDelay(200000); // Debounce delay (200 ms)
        }

        gpioDelay(1000); // Small delay to prevent busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioTerminate();

    return 0;
}

