#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define RELAY_GPIO 18
#define DISTANCE_THRESHOLD 50 // cm
#define POLLING_INTERVAL_MS 100

// VL53L1X Register Addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MODE 0x0021
#define VL53L1X_REG_START_STOP 0x0000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void control_relay(int gpio_pin, int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// VL53L1X Initialization function
int vl53l1x_init(int i2c_handle) {
    // Software reset
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_START_STOP, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset VL53L1X\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Set ranging mode to short distance
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x02) < 0) {
        fprintf(stderr, "Error: Failed to set ranging mode\n");
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_START_STOP, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging\n");
        return -1;
    }

    return 0;
}

// VL53L1X Distance Reading function
int vl53l1x_read_distance(int i2c_handle) {
    uint8_t status;
    uint8_t msb, lsb;
    int distance;

    // Check interrupt status
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read interrupt status\n");
        return -1;
    }

    if (status & 0x04) { // New data ready
        // Read distance data (MSB and LSB)
        msb = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        lsb = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1);

        if (msb < 0 || lsb < 0) {
            fprintf(stderr, "Error: Failed to read distance data\n");
            return -1;
        }

        // Combine MSB and LSB to get the distance in mm
        distance = (msb << 8) | lsb;

        // Convert mm to cm
        distance = distance / 10;

        return distance;
    } else {
        return -1; // No data ready
    }
}

// Relay Control function
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main() {
    int distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity-based door system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        distance = vl53l1x_read_distance(i2c_handle);

        if (distance >= 0) {
            printf("Distance: %d cm\n", distance);

            if (distance <= DISTANCE_THRESHOLD) {
                control_relay(RELAY_GPIO, 1); // Open door
            } else {
                control_relay(RELAY_GPIO, 0); // Close door
            }
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(RELAY_GPIO, 0); // Ensure relay is off
    gpioTerminate();

    return 0;
}

