#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from an I2C register
int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize the MPU-6050
int init_mpu6050(int fd) {
    // Wake up the MPU-6050
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        return -1;
    }

    // Set gyroscope full-scale range to ±250 dps
    if (i2c_write_reg(fd, GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Failed to set gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buf[6];

    if (i2c_read_regs(fd, GYRO_XOUT_H, buf, 6) != 0) {
        fprintf(stderr, "Failed to read gyroscope data\n");
        return -1;
    }

    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to convert raw gyroscope data to degrees per second
void convert_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps) {
