#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define GPIO22 22

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOGFILE "watering_log.txt"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line18, *line27, *line22;
static FILE *logfile;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void water_plant(int gpio_pin);
void log_watering_event(int gpio_pin);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    line18 = gpiod_chip_get_line(chip, GPIO18);
    line27 = gpiod_chip_get_line(chip, GPIO27);
    line22 = gpiod_chip_get_line(chip, GPIO22);

    if (!line17 || !line18 || !line27 || !line22) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return -1;
    }

    if (gpiod_line_request_output(line17, "watering", 1) < 0) {
        perror("Error requesting GPIO17 as output");
        cleanup_gpio();
        return -1;
    }
    if (gpiod_line_request_output(line18, "watering", 1) < 0) {
        perror("Error requesting GPIO18 as output");
        cleanup_gpio();
        return -1;
    }
    if (gpiod_line_request_output(line27, "watering", 1) < 0) {
        perror("Error requesting GPIO27 as output");
        cleanup_gpio();
        return -1;
    }
    if (gpiod_line_request_output(line22, "watering", 1) < 0) {
        perror("Error requesting GPIO22 as output");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Cleanup GPIO lines
void cleanup_gpio() {
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (line27) gpiod_line_release(line27);
    if (line22) gpiod_line_release(line22);
    if (chip) gpiod_chip_close(chip);
}

// Water the plant by activating the relay
void water_plant(int gpio_pin) {
    struct gpiod_line *line = NULL;
    switch (gpio_pin) {
        case GPIO17: line = line17; break;
        case GPIO18: line = line18; break;
        case GPIO27: line = line27; break;
        case GPIO22: line = line22; break;
        default: fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin); return;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO value to LOW");
        return;
    }
    sleep(5);
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO value to HIGH");
    }
}

// Log watering event to file
void log_watering_event(int gpio_pin) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(logfile, "%s - Watered plant connected to GPIO %d\n", timestamp, gpio_pin);
    fflush(logfile); // Ensure the log is written immediately
}

// Cleanup function to be called on exit
void cleanup() {
    cleanup_gpio();
    if (logfile) fclose(logfile);
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    logfile = fopen(LOGFILE, "a");
    if (!logfile) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    time_t last_watering_time = 0;
    while (!terminate) {
        time_t current_time = time(NULL);

        // Water plants every 24 hours
        if (difftime(current_time, last_watering_time) >= 86400.0) {
            printf("Starting watering cycle...\n");
            water_plant(GPIO17);
            log_watering_event(GPIO17);
            water_plant(GPIO18);
            log_watering_event(GPIO18);
            water_plant(GPIO27);
            log_watering_event(GPIO27);
            water_plant(GPIO22);
            log_watering_event(GPIO22);
            last_watering_time = current_time;
            printf("Watering cycle complete.\n");
        }

        sleep(60); // Check every 60 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

