#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 18
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define sunrise duration and step
#define SUNRISE_DURATION 1800 // 30 minutes in seconds
#define STEP_DELAY 1 // 1 second

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_gpio_mode(int gpio, int mode);
int initialize_pwm(int gpio, int frequency);
int set_pwm_duty_cycle(int gpio, int duty_cycle);
void simulate_sunrise();
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Received termination signal. Shutting down...");
    }
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }
    log_event("pigpio initialised successfully");
    return 0;
}

// Function to set the mode of a GPIO pin
int set_gpio_mode(int gpio, int mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        char message[100];
        sprintf(message, "Failed to set GPIO %d mode to %d", gpio, mode);
        log_event(message);
        return -1;
    }
    char message[100];
    sprintf(message, "GPIO %d mode set to %d", gpio, mode);
    log_event(message);
    return 0;
}

// Function to initialize PWM on a GPIO pin
int initialize_pwm(int gpio, int frequency) {
    if (gpioSetPWMfrequency(gpio, frequency) != frequency) {
        char message[100];
        sprintf(message, "Failed to set PWM frequency on GPIO %d to %d", gpio, frequency);
        log_event(message);
        return -1;
    }
    char message[100];
    sprintf(message, "PWM frequency set to %d on GPIO %d", frequency, gpio);
    log_event(message);
    return 0;
}

// Function to set the PWM duty cycle on a GPIO pin
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        char message[100];
        sprintf(message, "Failed to set PWM duty cycle on GPIO %d to %d", gpio, duty_cycle);
        log_event(message);
        return -1;
    }
    char message[100];
    sprintf(message, "PWM duty cycle set to %d on GPIO %d", duty_cycle, gpio);
    log_event(message);
    return 0;
}

// Function to simulate the sunrise effect
void simulate_sunrise() {
    int duty_cycle = 0;
    while (program_running && duty_cycle <= 255) {
        if (set_pwm_duty_cycle(RELAY1_GPIO, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY2_GPIO, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY3_GPIO, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY4_GPIO, duty_cycle) != 0) {
            log_event("Error setting PWM duty cycle. Aborting sunrise simulation.");
            break;
        }

        duty_cycle++;
        gpioDelay(STEP_DELAY * 1000); // Delay for 1 second (1000 ms)
    }

    if (duty_cycle > 255) {
        log_event("Sunrise simulation complete.");
    } else {
        log_event("Sunrise simulation interrupted.");
    }
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set GPIO modes to output
    if (set_gpio_mode(RELAY1_GPIO, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY2_GPIO, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY3_GPIO, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY4_GPIO, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize PWM on each GPIO pin
    if (initialize_pwm(RELAY1_GPIO, PWM_FREQUENCY) != 0 ||
        initialize_pwm(RELAY2_GPIO, PWM_FREQUENCY) != 0 ||
        initialize_pwm(RELAY3_GPIO, PWM_FREQUENCY) != 0 ||
        initialize_pwm(RELAY4_GPIO, PWM_FREQUENCY) != 0) {
        gpioTerminate();
        return 1;
    }

    // Simulate sunrise
    simulate_sunrise();

    // Clean up and terminate pigpio
    gpioTerminate();
    log_event("pigpio terminated");

    return 0;
}

