#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define WHO_AM_I 0x75
#define GYRO_XOUT_H 0x43

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data and timestamp
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
void check_threshold(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    int retries = 3;
    while (retries > 0) {
        // Wake up the sensor
        if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
            fprintf(stderr, "Error writing to PWR_MGMT_1, retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Set sample rate divider
        if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
            fprintf(stderr, "Error writing to SMPLRT_DIV, retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Set gyroscope configuration
        if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
            fprintf(stderr, "Error writing to GYRO_CONFIG, retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Verify WHO_AM_I register
        int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (who_am_i < 0) {
            fprintf(stderr, "Error reading WHO_AM_I, retrying...\n");
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }
        if (who_am_i != 0x68) {
            fprintf(stderr, "WHO_AM_I returned 0x%x, expected 0x68, retrying...\n", who_am_i);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        printf("MPU-6050 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Failure
}

// Function to read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    // Read 6 bytes of gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data.\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to degrees per second (sensitivity: 131 LSB/deg/s)
    *x = (float)raw_x / 131.0;
    *y = (float)raw_y / 131.0;
    *z = (float)raw_z / 131.0;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(float x, float y, float z) {
    clock_gettime(CLOCK_REALTIME, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check if any axis exceeds the threshold
void check_threshold(float x, float y, float z) {
    if (fabs(x) > 250.0 || fabs(y) > 250.0 || fabs(z) > 250.0) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn off the LED

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Add data to the circular buffer
            add_to_buffer(x, y, z);

            // Check threshold and control LED
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Re-initializing...\n");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // 1 second delay
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            }
            if (init_mpu6050() != 0) {
                terminate = 1;
            }
        }

        gpioDelay(50000); // 50ms delay (20 Hz)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

