#define SAMPLE_INTERVAL_NS 10000000 // 10 ms

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float convert_to_dps(int16_t raw_data);
int log_data(FILE *fp, struct timespec ts, float x_rate, float y_rate, float z_rate);
void signal_handler(int sig);
int setup();
void cleanup();

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
        .delay_usecs = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

// Read gyroscope data function
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[1] = {GYRO_XOUT_H | 0x80}; // Read multiple bytes
    uint8_t rx_buf[6];

    if (spi_transfer(fd, tx_buf, rx_buf, 6) < 0) {
        return -1;
    }

    *x = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    *y = (int16_t)((rx_buf[2] << 8) | rx_buf[3]);
    *z = (int16_t)((rx_buf[4] << 8) | rx_buf[5]);

    return 0;
}

// Convert raw data to degrees per second
float convert_to_dps(int16_t raw_data) {
    return (float)raw_data / GYRO_SCALE_FACTOR;
}

// Log data to file
int log_data(FILE *fp, struct timespec ts, float x_rate, float y_rate, float z_rate) {
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup function
int setup() {
    // SPI setup
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // GPIO setup
    gpio_chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_GPIO_LINE);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "gyro_cs", 1) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return -1;
    }

    // Log file setup
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(cs_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1); // De-assert CS
        gpiod_line_release(cs_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    struct timespec ts;
    int16_t raw_x, raw_y, raw_z;
    float x_rate, y_rate, z_rate;
    int retries;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup
    if (setup() < 0) {
        fprintf(stderr, "Setup failed, exiting\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < 3) {
            if (read_gyro_data(spi_fd, &raw_x, &raw_y, &raw_z) == 0) {
                break; // Success
            } else {
                fprintf(stderr, "Gyro read failed, retrying (%d/3)\n", retries + 1);
                retries++;
                usleep(1000); // Wait before retrying
            }
        }

        if (retries == 3) {
            fprintf(stderr, "Gyro read failed after 3 retries, skipping\n");
            nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = SAMPLE_INTERVAL_NS}, NULL);
            continue;
        }

        // Convert to degrees per second
        x_rate = convert_to_dps(raw_x);
        y_rate = convert_to_dps(raw_y);
        z_rate = convert_to_dps(raw_z);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get timestamp");
            nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = SAMPLE_INTERVAL_NS}, NULL);
            continue;
        }

        // Log data
        if (log_data(log_file, ts, x_rate, y_rate, z_rate) < 0) {
            fprintf(stderr, "Failed to log data, continuing\n");
        }

        // Wait for the next sample
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = SAMPLE_INTERVAL_NS}, NULL);
    }

    // Cleanup
    cleanup();

    return 0;
}

