#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/time.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 3900000 // 3.9 MHz
#define SPI_MODE 0
#define MPU6050_ADDR 0x68 // I2C address (not used directly, but for register addresses)
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define LED_GPIO 17
#define BUFFER_SIZE 64
#define ANGULAR_VELOCITY_THRESHOLD 200.0 // deg/s

// Data structure for gyroscope readings
typedef struct {
    struct timeval timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// SPI handle
int spi_handle;

// Function prototypes
int spi_read_register(int handle, uint8_t reg);
int spi_write_register(int handle, uint8_t reg, uint8_t value);
int read_gyro_data(int handle, float *x, float *y, float *z);
void add_to_buffer(gyro_data_t data);
void print_buffer();
void blink_led(int gpio, int duration_ms);
void signal_handler(int signal);

// Function to read a single byte from an MPU-6050 register over SPI
int spi_read_register(int handle, uint8_t reg) {
    char tx[2], rx[2];
    tx[0] = reg | 0x80; // Set MSB to 1 for read operation
    tx[1] = 0x00;       // Dummy byte for reading

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI read error: %s\n", strerror(errno));
        return -1;
    }

    return rx[1];
}

// Function to write a single byte to an MPU-6050 register over SPI
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx[2];
    tx[0] = reg & 0x7F; // Set MSB to 0 for write operation
    tx[1] = value;

    if (spiWrite(handle, tx, 2) != 0) {
        fprintf(stderr, "SPI write error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read gyroscope data from the MPU-6050
int read_gyro_data(int handle, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;
    int x_h, x_l, y_h, y_l, z_h, z_l;

    x_h = spi_read_register(handle, GYRO_XOUT_H);
    x_l = spi_read_register(handle, GYRO_XOUT_H + 1);
    y_h = spi_read_register(handle, GYRO_YOUT_H);
    y_l = spi_read_register(handle, GYRO_YOUT_H + 1);
    z_h = spi_read_register(handle, GYRO_ZOUT_H);
    z_l = spi_read_register(handle, GYRO_ZOUT_H + 1);

    if (x_h == -1 || x_l == -1 || y_h == -1 || y_l == -1 || z_h == -1 || z_l == -1) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    raw_x = (int16_t)((x_h << 8) | x_l);
    raw_y = (int16_t)((y_h << 8) | y_l);
    raw_z = (int16_t)((z_h << 8) | z_l);

    *x = (float)raw_x / 131.0;
    *y = (float)raw_y / 131.0;
    *z = (float)raw_z / 131.0;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(gyro_data_t data) {
    gyro_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%ld.%06ld,%f,%f,%f\n",
               gyro_buffer[i].timestamp.tv_sec,
               gyro_buffer[i].timestamp.tv_usec,
               gyro_buffer[i].x,
               gyro_buffer[i].y,
               gyro_buffer[i].z);
    }
}

// Function to blink an LED
void blink_led(int gpio, int duration_ms) {
    gpioWrite(gpio, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    gpioWrite(gpio, 0); // Turn LED off
    gpioDelay(duration_ms * 1000); // Delay in microseconds
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    print_buffer();
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;
    struct timeval tv;

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(spi_handle, &x, &y, &z) == 0) {
            // Get timestamp
            gettimeofday(&tv, NULL);

            // Store data in the circular buffer
            gyro_data_t data;
            data.timestamp = tv;
            data.x = x;
            data.y = y;
            data.z = z;
            add_to_buffer(data);

            // Check for angular velocity threshold
            if (fabs(x) > ANGULAR_VELOCITY_THRESHOLD ||
                fabs(y) > ANGULAR_VELOCITY_THRESHOLD ||
                fabs(z) > ANGULAR_VELOCITY_THRESHOLD) {
                blink_led(LED_GPIO, 500);
            }
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }

        gpioDelay(10000); // Delay 10ms (10000 microseconds)
    }

    return 0;
}

