#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;

// Function prototypes
int i2c_read_register(int fd, unsigned char reg);
int i2c_write_register(int fd, unsigned char reg, unsigned char value);
int read_sensor_data(int fd, unsigned short *ambient_light, unsigned short *proximity);
void log_data(FILE *fp, unsigned short ambient_light, unsigned short proximity);
void set_gpio_output(struct gpiod_line *line, int value);
void signal_handler(int signum);

// I2C read function with retry
int i2c_read_register(int fd, unsigned char reg) {
    int retries = 3;
    int result;

    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("I2C write error");
            retries--;
            usleep(10000); // 10 ms delay
            continue;
        }

        result = read(fd, &reg, 1);
        if (result == 1) {
            return reg;
        } else {
            perror("I2C read error");
            retries--;
            usleep(10000); // 10 ms delay
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Indicate failure
}

// I2C write function with retry
int i2c_write_register(int fd, unsigned char reg, unsigned char value) {
    int retries = 3;
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;

    while (retries > 0) {
        if (write(fd, buf, 2) == 2) {
            return 0; // Success
        } else {
            perror("I2C write error");
            retries--;
            usleep(10000); // 10 ms delay
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to read sensor data
int read_sensor_data(int fd, unsigned short *ambient_light, unsigned short *proximity) {
    unsigned char ambient_light_low, ambient_light_high, proximity_low, proximity_high;

    ambient_light_low = i2c_read_register(fd, AMBIENT_LIGHT_REG);
    ambient_light_high = i2c_read_register(fd, AMBIENT_LIGHT_REG + 1);
    proximity_low = i2c_read_register(fd, PROXIMITY_REG);
    proximity_high = i2c_read_register(fd, PROXIMITY_REG + 1);

    if (ambient_light_low == -1 || ambient_light_high == -1 || proximity_low == -1 || proximity_high == -1) {
        return -1; // Indicate failure
    }

    *ambient_light = (unsigned short)((ambient_light_high << 8) | ambient_light_low);
    *proximity = (unsigned short)((proximity_high << 8) | proximity_low);

    return 0; // Success
}

// Function to log data to file
void log_data(FILE *fp, unsigned short ambient_light, unsigned short proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,AmbientLight:%04X,Proximity:%04X\n", timestamp, ambient_light, proximity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Function to set GPIO output
void set_gpio_output(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Failed to set GPIO value");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }

    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    unsigned short ambient_light, proximity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "biometric_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);

            if (proximity > 100) {
                set_gpio_output(gpio_line, 1); // Set GPIO high
            } else {
                set_gpio_output(gpio_line, 0); // Set GPIO low
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        usleep(100000); // 100 ms delay
    }

    return 0;
}

