#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define GYRO_X_REG 0x02
#define GYRO_Y_REG 0x04
#define SENSITIVITY 200.0 // LSB/deg/s
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE) // microseconds
#define MAX_REINIT_ATTEMPTS 3

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_gyro_register(int handle, uint8_t reg);
int16_t convert_to_int16(uint8_t msb, uint8_t lsb);
double convert_to_deg_per_sec(int16_t raw_data);
void log_data(FILE *fp, double timestamp, int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);
int initialize_spi();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read a single gyro register
int read_gyro_register(int handle, uint8_t reg) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg | 0x80; // Set read bit
    tx_buf[1] = 0x00;       // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed for register 0x%02X\n", reg);
        return -1; // Indicate failure
    }

    return rx_buf[1]; // Return the received data
}

// Function to convert two bytes to a 16-bit signed integer
int16_t convert_to_int16(uint8_t msb, uint8_t lsb) {
    return (int16_t)((msb << 8) | lsb);
}

// Function to convert raw data to degrees per second
double convert_to_deg_per_sec(int16_t raw_data) {
    return (double)raw_data / SENSITIVITY;
}

// Function to log data to a CSV file
void log_data(FILE *fp, double timestamp, int16_t x_rate, int16_t y_rate) {
    fprintf(fp, "%.6f,%d,%d\n", timestamp, x_rate, y_rate);
    fflush(fp); // Ensure data is written to disk immediately
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (%d)\n", spi_handle);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the CSV file for logging
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open gyro_data.csv for writing\n");
        gpioTerminate();
        return 1;
    }

    // Write the header row to the CSV file
    fprintf(fp, "timestamp,X_rate,Y_rate\n");

    // Initialize SPI with retry logic
    int reinit_attempts = 0;
    while (initialize_spi() != 0 && reinit_attempts < MAX_REINIT_ATTEMPTS) {
        fprintf(stderr, "Attempting to re-initialize SPI (attempt %d/%d)...\n", reinit_attempts + 1, MAX_REINIT_ATTEMPTS);
        reinit_attempts++;
        gpioDelay(1000); // Wait 1 second before retrying
    }

    if (spi_handle < 0) {
        fprintf(stderr, "Error: Failed to initialize SPI after multiple attempts\n");
        fclose(fp);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read X and Y axis data
        int x_msb = read_gyro_register(spi_handle, GYRO_X_REG);
        int x_lsb = read_gyro_register(spi_handle, GYRO_X_REG + 1);
        int y_msb = read_gyro_register(spi_handle, GYRO_Y_REG);
        int y_lsb = read_gyro_register(spi_handle, GYRO_Y_REG + 1);

        if (x_msb < 0 || x_lsb < 0 || y_msb < 0 || y_lsb < 0) {
            fprintf(stderr, "Error: Failed to read gyro data\n");
            break; // Exit loop on read error
        }

        // Convert to 16-bit signed integers
        int16_t x_rate = convert_to_int16((uint8_t)x_msb, (uint8_t)x_lsb);
        int16_t y_rate = convert_to_int16((uint8_t)y_msb, (uint8_t)y_lsb);

        // Get timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

        // Log the data
        log_data(fp, timestamp, x_rate, y_rate);

        // Delay for the sample period
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up
    spiClose(spi_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

