#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define constants
#define ALERT_DURATION_MS 2000
#define SIMULTANEOUS_DURATION_MS 500
#define DEBOUNCE_DELAY_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int sensor1_state = 0;
static int sensor2_state = 0;
static unsigned long sensor1_last_change = 0;
static unsigned long sensor2_last_change = 0;

// Function prototypes
void signal_handler(int signal);
void log_event(const char *message);
void alert_callback(int gpio, int level, unsigned int tick, void *user_data);
void sensor1_callback(int gpio, int level, unsigned int tick, void *user_data);
void sensor2_callback(int gpio, int level, unsigned int tick, void *user_data);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Set alert pin LOW
    gpioWrite(ALERT_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Logging function
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", buf, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Alert callback function
void alert_callback(int gpio, int level, unsigned int tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user_data; // unused

    gpioWrite(ALERT_PIN, 1);
    gpioDelay(ALERT_DURATION_MS * 1000); // Convert ms to microseconds
    gpioWrite(ALERT_PIN, 0);
}

// Sensor 1 callback function
void sensor1_callback(int gpio, int level, unsigned int tick, void *user_data) {
    (void)gpio; // unused
    (void)user_data; // unused
    unsigned long now = gpioTick();

    if (now - sensor1_last_change > DEBOUNCE_DELAY_MS * 1000) {
        sensor1_state = level;
        sensor1_last_change = now;

        if (sensor1_state == 1 && sensor2_state == 1) {
            unsigned long start_time = now;
            while (sensor1_state == 1 && sensor2_state == 1 && running) {
                gpioDelay(10 * 1000); // Check every 10ms
                if (!running) break;
            }
            unsigned long end_time = gpioTick();

            if ((end_time - start_time) >= SIMULTANEOUS_DURATION_MS * 1000 && running) {
                log_event("Seismic event detected!");
                gpioSetAlertFunc(ALERT_PIN, alert_callback, NULL);
            }
        }
    }
}

// Sensor 2 callback function
void sensor2_callback(int gpio, int level, unsigned int tick, void *user_data) {
    (void)gpio; // unused
    (void)user_data; // unused
    unsigned long now = gpioTick();

    if (now - sensor2_last_change > DEBOUNCE_DELAY_MS * 1000) {
        sensor2_state = level;
        sensor2_last_change = now;

        if (sensor1_state == 1 && sensor2_state == 1) {
            unsigned long start_time = now;
            while (sensor1_state == 1 && sensor2_state == 1 && running) {
                gpioDelay(10 * 1000); // Check every 10ms
                if (!running) break;
            }
            unsigned long end_time = gpioTick();

            if ((end_time - start_time) >= SIMULTANEOUS_DURATION_MS * 1000 && running) {
                log_event("Seismic event detected!");
                gpioSetAlertFunc(ALERT_PIN, alert_callback, NULL);
            }
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register callbacks
    gpioSetAlertFuncEx(SENSOR_1_PIN, sensor1_callback, NULL);
    gpioSetAlertFuncEx(SENSOR_2_PIN, sensor2_callback, NULL);

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100 * 1000); // Check every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(ALERT_PIN, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

