#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define LED_GPIO 17
#define THRESHOLD 20.0
#define SENSITIVITY 200.0
#define BUFFER_SIZE 100

// Structure for circular buffer entry
typedef struct {
    struct timespec timestamp;
    float angular_rate;
} buffer_entry_t;

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;
buffer_entry_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int spi_read_register(uint8_t address, uint16_t *data);
float convert_to_deg_per_sec(int16_t raw_data);
void add_to_buffer(struct timespec timestamp, float angular_rate);
void check_threshold(float angular_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// SPI read register function
int spi_read_register(uint8_t address, uint16_t *data) {
    char tx_buffer[2];
    char rx_buffer[2];

    // Set MSB for read operation
    address |= 0x80;

    tx_buffer[0] = address;
    tx_buffer[1] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    *data = (rx_buffer[0] << 8) | rx_buffer[1];
    return 0;
}

// Convert raw data to degrees per second
float convert_to_deg_per_sec(int16_t raw_data) {
    return (float)raw_data / SENSITIVITY;
}

// Add data to circular buffer
void add_to_buffer(struct timespec timestamp, float angular_rate) {
    circular_buffer[buffer_index].timestamp = timestamp;
    circular_buffer[buffer_index].angular_rate = angular_rate;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check if angular rate exceeds threshold and control LED
void check_threshold(float angular_rate) {
    if (fabs(angular_rate) > THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    uint16_t raw_data;
    int16_t rate_x;
    float angular_rate;
    struct timespec ts;

    // Main loop
    while (!terminate) {
        // Read X-axis angular rate
        if (spi_read_register(0x02, &raw_data) == 0) {
            rate_x = (int16_t)raw_data; // Combine high and low bytes
            angular_rate = convert_to_deg_per_sec(rate_x);

            // Get timestamp
            if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
                perror("clock_gettime");
            } else {
                // Add data to circular buffer
                add_to_buffer(ts, angular_rate);

                // Check threshold and control LED
                check_threshold(angular_rate);

                // Print angular rate (optional)
                printf("Angular Rate: %.2f deg/s\n", angular_rate);
            }
        } else {
            fprintf(stderr, "Failed to read angular rate\n");
        }

        gpioDelay(10); // Delay for 10ms
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

