#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for relays
#define RED_RELAY_PIN 17
#define YELLOW_RELAY_PIN 22
#define GREEN_RELAY_PIN 23
#define YELLOW2_RELAY_PIN 24

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define GPIO line names
#define RED_RELAY_LINE "gpio17"
#define YELLOW_RELAY_LINE "gpio22"
#define GREEN_RELAY_LINE "gpio23"
#define YELLOW2_RELAY_LINE "gpio24"

// Define traffic light states
typedef enum {
    RED,
    RED_YELLOW,
    GREEN,
    YELLOW,
    NUM_STATES
} traffic_light_state_t;

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *red_line, *yellow_line, *green_line, *yellow2_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void set_relay_state(int pin, int state);
void traffic_light_cycle();
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up and exiting...\n");
    terminate = 1;
}

// Function to initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return -1;
    }

    red_line = gpiod_chip_get_line(chip, RED_RELAY_PIN);
    yellow_line = gpiod_chip_get_line(chip, YELLOW_RELAY_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_RELAY_PIN);
    yellow2_line = gpiod_chip_get_line(chip, YELLOW2_RELAY_PIN);

    if (!red_line || !yellow_line || !green_line || !yellow2_line) {
        fprintf(stderr, "Error: Could not get GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(red_line, "traffic_light", 0) < 0 ||
        gpiod_line_request_output(yellow_line, "traffic_light", 0) < 0 ||
        gpiod_line_request_output(green_line, "traffic_light", 0) < 0 ||
        gpiod_line_request_output(yellow2_line, "traffic_light", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line as output\n");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio() {
    if (red_line) gpiod_line_release(red_line);
    if (yellow_line) gpiod_line_release(yellow_line);
    if (green_line) gpiod_line_release(green_line);
    if (yellow2_line) gpiod_line_release(yellow2_line);
    if (chip) gpiod_chip_close(chip);
}

// Function to set relay state (active low)
void set_relay_state(int pin, int state) {
    struct gpiod_line *line;
    if (pin == RED_RELAY_PIN) line = red_line;
    else if (pin == YELLOW_RELAY_PIN) line = yellow_line;
    else if (pin == GREEN_RELAY_PIN) line = green_line;
    else if (pin == YELLOW2_RELAY_PIN) line = yellow2_line;
    else {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", pin);
        return;
    }

    int value = state ? 1 : 0; // Active low: 1 = OFF, 0 = ON
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Could not set GPIO value for pin %d\n", pin);
    }
}

// Function to cycle through traffic light states
void traffic_light_cycle() {
    traffic_light_state_t state = RED;

    while (!terminate) {
        switch (state) {
            case RED:
                printf("State: RED\n");
                set_relay_state(RED_RELAY_PIN, 1); // OFF
                set_relay_state(YELLOW_RELAY_PIN, 1); // OFF
                set_relay_state(GREEN_RELAY_PIN, 1); // OFF
                set_relay_state(YELLOW2_RELAY_PIN, 1); // OFF
                sleep(10);
                state = RED_YELLOW;
                break;
            case RED_YELLOW:
                printf("State: RED + YELLOW\n");
                set_relay_state(RED_RELAY_PIN, 1); // OFF
                set_relay_state(YELLOW_RELAY_PIN, 0); // ON
                set_relay_state(GREEN_RELAY_PIN, 1); // OFF
                set_relay_state(YELLOW2_RELAY_PIN, 1); // OFF
                sleep(2);
                state = GREEN;
                break;
            case GREEN:
                printf("State: GREEN\n");
                set_relay_state(RED_RELAY_PIN, 1); // OFF
                set_relay_state(YELLOW_RELAY_PIN, 1); // OFF
                set_relay_state(GREEN_RELAY_PIN, 0); // ON
                set_relay_state(YELLOW2_RELAY_PIN, 1); // OFF
                sleep(10);
                state = YELLOW;
                break;
            case YELLOW:
                printf("State: YELLOW\n");
                set_relay_state(RED_RELAY_PIN, 1); // OFF
                set_relay_state(YELLOW_RELAY_PIN, 1); // OFF
                set_relay_state(GREEN_RELAY_PIN, 1); // OFF
                set_relay_state(YELLOW2_RELAY_PIN, 0); // ON
                sleep(3);
                state = RED;
                break;
            default:
                fprintf(stderr, "Error: Invalid traffic light state\n");
                state = RED; // Reset to a valid state
                break;
        }
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        return 1;
    }

    // Run traffic light cycle
    traffic_light_cycle();

    // Cleanup GPIO
    cleanup_gpio();

    printf("Exiting cleanly.\n");
    return 0;
}

