    if (i2c_handle < 0) {
        log_message("Failed to open I2C device");
        return -1;
    }
    log_message("I2C initialized");
    return 0;
}

// Configure MPR121
int configure_mpr121() {
    // Reset MPR121
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        log_message("Failed to reset MPR121");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x00) < 0) {
        log_message("Failed to set MPR121 to stop mode");
        return -1;
    }

    // Enable electrode 0
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) {
        log_message("Failed to enable electrode 0");
        return -1;
    }

    // Touch threshold
    if (i2cWriteByteData(i2c_handle, 0x41, 0x0A) < 0) {
        log_message("Failed to set touch threshold");
        return -1;
    }

    // Release threshold
    if (i2cWriteByteData(i2c_handle, 0x42, 0x08) < 0) {
        log_message("Failed to set release threshold");
        return -1;
    }

    // Debounce
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x21) < 0) {
        log_message("Failed to set debounce");
        return -1;
    }

    // Charge time
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x0D) < 0) {
        log_message("Failed to set charge time");
        return -1;
    }

    // Run mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0D) < 0) {
        log_message("Failed to set run mode");
        return -1;
    }

    log_message("MPR121 configured");
    return 0;
}

// Read touch status
int read_touch_status(uint16_t *status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        log_message("Failed to read touch status");
        return -1;
    }

    *status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Toggle relay
void toggle_relay() {
    int current_state = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_state);
    log_message(current_state == 0 ? "Relay ON" : "Relay OFF");
}

// Log message with timestamp
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

int main() {
    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Configure MPR121
    if (configure_mpr121() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    uint16_t last_touch_status = 0;
    int relay_state = 0; // 0 = OFF, 1 = ON

    log_message("Program started");

    while (program_running) {
        uint16_t touch_status;
        if (read_touch_status(&touch_status) == 0) {
            // Check if electrode 0 is touched and debounce
            if ((touch_status & 0x01) && !(last_touch_status & 0x01)) {
                gpioDelay(100); // Debounce delay
                if (read_touch_status(&touch_status) == 0 && (touch_status & 0x01)) {
                    toggle_relay();
                    relay_state = !relay_state;
                }
            }
            last_touch_status = touch_status;
        }

        gpioDelay(10); // Check every 10ms
    }

    // Cleanup
    log_message("Cleaning up...");
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay on exit
    gpioTerminate();
    fclose(log_file);

    return 0;
}

