#include <string.h>

// Define GPIO pins for solenoids
#define SOLENOID1_PIN 17
#define SOLENOID2_PIN 27

// Define dispense duration and delay
#define DISPENSE_DURATION_MS 1000
#define SOLENOID1_DURATION_MS (DISPENSE_DURATION_MS / 2)
#define SOLENOID2_DURATION_MS (DISPENSE_DURATION_MS / 2)
#define DISPENSE_DELAY_S 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int dispense();
int log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nCtrl+C detected. Shutting down gracefully...\n");
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID1_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SOLENOID2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID2_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to dispense
int dispense() {
    // Activate solenoid 1
    if (gpioWrite(SOLENOID1_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid 1 (GPIO%d)\n", SOLENOID1_PIN);
        return 1;
    }
    gpioDelay(SOLENOID1_DURATION_MS * 1000); // Convert ms to microseconds

    // Deactivate solenoid 1
    if (gpioWrite(SOLENOID1_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid 1 (GPIO%d)\n", SOLENOID1_PIN);
        return 1;
    }

    // Activate solenoid 2
    if (gpioWrite(SOLENOID2_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid 2 (GPIO%d)\n", SOLENOID2_PIN);
        return 1;
    }
    gpioDelay(SOLENOID2_DURATION_MS * 1000); // Convert ms to microseconds

    // Deactivate solenoid 2
    if (gpioWrite(SOLENOID2_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid 2 (GPIO%d)\n", SOLENOID2_PIN);
        return 1;
    }

    return 0;
}

// Function to log events to a file
int log_event(const char *message) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Dispense
        if (dispense() != 0) {
            fprintf(stderr, "Dispense failed\n");
        } else {
            // Log the event
            char log_message[256];
            snprintf(log_message, sizeof(log_message), "Dispensed: Solenoid 1 (GPIO%d) for %d ms, Solenoid 2 (GPIO%d) for %d ms", SOLENOID1_PIN, SOLENOID1_DURATION_MS, SOLENOID2_PIN, SOLENOID2_DURATION_MS);
            if (log_event(log_message) != 0) {
                fprintf(stderr, "Failed to log dispense event\n");
            }
        }

        // Wait before next dispense
        gpioDelay(DISPENSE_DELAY_S * 1000000); // Convert seconds to microseconds
    }

    // Cleanup
    gpioWrite(SOLENOID1_PIN, 0);
    gpioWrite(SOLENOID2_PIN, 0);
    gpioTerminate();

    printf("Dispensing system stopped.\n");
    return 0;
}

