#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENABLE 24

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENABLE 25

// PID Gains
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

// Obstacle Avoidance Threshold
#define OBSTACLE_THRESHOLD 20.0

// PWM Range
#define PWM_RANGE 255

// Control Loop Interval (ms)
#define CONTROL_INTERVAL 50

// Global Variables
static volatile int running = 1;
FILE *log_file = NULL;

// PID Variables
double integral = 0.0;
double previous_error = 0.0;

// Function Prototypes
void signal_handler(int signal);
void stop_motors();
void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed);
double simulate_tilt_error();
double simulate_distance();
int pid_control(double tilt_error);
void set_motor_speed(int motor, int speed);

// Signal Handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Stopping motors and exiting.\n");
        running = 0;
    }
}

// Stop Motors
void stop_motors() {
    gpioPWM(MOTOR_A_FORWARD, 0);
    gpioPWM(MOTOR_A_BACKWARD, 0);
    gpioPWM(MOTOR_B_FORWARD, 0);
    gpioPWM(MOTOR_B_BACKWARD, 0);
}

// Log Data
void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Simulate Tilt Error
double simulate_tilt_error() {
    return ((double)rand() / RAND_MAX) * 20.0 - 10.0; // Random value between -10.0 and 10.0
}

// Simulate Distance
double simulate_distance() {
    return ((double)rand() / RAND_MAX) * 398.0 + 2.0; // Random value between 2.0 and 400.0
}

// PID Control
int pid_control(double tilt_error) {
    double proportional = Kp * tilt_error;
    integral += Ki * tilt_error * (CONTROL_INTERVAL / 1000.0); // Integrate over time
    double derivative = Kd * (tilt_error - previous_error) / (CONTROL_INTERVAL / 1000.0); // Differentiate over time

    double output = proportional + integral + derivative;

    previous_error = tilt_error;

    // Clamp the output to the range -255 to 255
    if (output > 255.0) {
        output = 255.0;
    } else if (output < -255.0) {
        output = -255.0;
    }

    return (int)output;
}

// Set Motor Speed
void set_motor_speed(int motor, int speed) {
    if (speed > 0) {
        gpioPWM(motor, speed);
        gpioWrite(motor == MOTOR_A_FORWARD ? MOTOR_A_BACKWARD : MOTOR_B_BACKWARD, 0);
    } else if (speed < 0) {
        gpioPWM(motor == MOTOR_A_FORWARD ? MOTOR_A_BACKWARD : MOTOR_B_BACKWARD, -speed);
        gpioWrite(motor, 0);
    } else {
        gpioPWM(motor, 0);
        gpioWrite(motor == MOTOR_A_FORWARD ? MOTOR_A_BACKWARD : MOTOR_B_BACKWARD, 0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    // Enable motors
    gpioWrite(MOTOR_A_ENABLE, 1);
    gpioWrite(MOTOR_B_ENABLE, 1);

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Self-balancing robot simulation started. Press Ctrl+C to exit.\n");

    while (running) {
        // Simulate sensor data
        double tilt_error = simulate_tilt_error();
        double distance = simulate_distance();

        // PID control
        int motor_output = pid_control(tilt_error);

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            set_motor_speed(MOTOR_A_FORWARD, -PWM_RANGE / 2);
            set_motor_speed(MOTOR_B_FORWARD, -PWM_RANGE / 2);
            motor_a_speed = -PWM_RANGE / 2;
            motor_b_speed = -PWM_RANGE / 2;
        } else {
            set_motor_speed(MOTOR_A_FORWARD, motor_output);
            set_motor_speed(MOTOR_B_FORWARD, motor_output);
            motor_a_speed = motor_output;
            motor_b_speed = motor_output;
        }

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay(CONTROL_INTERVAL);
    }

    // Stop motors
    stop_motors();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

