int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                if (sensitivity <= 0.0) {
                    fprintf(stderr, "Error: Sensitivity must be positive.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Initialize ALSA (if available)
#ifdef ALSA_AVAILABLE
    snd_pcm_t *pcm = NULL;
    snd_pcm_hw_params_t *hw_params = NULL;
    snd_pcm_sw_params_t *sw_params = NULL;
    int rc;

    // Open PCM device for capture
    rc = snd_pcm_open(&pcm, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (rc < 0) {
        fprintf(stderr, "unable to open pcm device: %s\n", snd_strerror(rc));
        cleanup();
        return 1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&hw_params);

    // Fill with default values
    rc = snd_pcm_hw_params_any(pcm, hw_params);
    if (rc < 0) {
        fprintf(stderr, "unable to fill hw_params: %s\n", snd_strerror(rc));
        cleanup();
        return 1;
    }

    // Set access type to interleaved
    rc = snd_pcm_hw_params_set_access(pcm, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (rc < 0) {
        fprintf(stderr, "unable to set access: %s\n", snd_strerror(rc));
        cleanup();
        return 1;
    }

    // Set format to 16-bit signed little-endian
    snd_pcm_format_t format = SND_PCM_FORMAT_S16_LE;
    rc = snd_pcm_hw_params_set_format(pcm, hw_params, format);
    if (rc < 0) {
        fprintf(stderr, "unable to set format: %s\n", snd_strerror(rc));
        cleanup();
        return 1;
    }

    // Set sample rate
    unsigned int rate = SAMPLE_RATE;
    rc = snd_pcm_hw_params_set_rate_near(pcm, hw_params, &rate, 0);
    if (rc < 0) {
        fprintf(stderr, "unable to set rate: %s\n", snd_strerror(rc));
        cleanup();
        return 1;
    }

    // Set number of channels to 1
    rc = snd_pcm_hw_params_set_channels(pcm, hw_params, 1);
    if (rc < 0) {
        fprintf(stderr, "unable to set channels: %s\n", snd_strerror(rc));
        cleanup();
        return 1;
    }

    // Set period size
    snd_pcm_uframes_t frames = SAMPLE_SIZE;
    rc = snd_pcm_hw_params_set_period_size_near(pcm, hw_params, &frames, 0);
    if (rc < 0) {
        fprintf(stderr, "unable to set period size: %s\n", snd_strerror(rc));
        cleanup();
        return 1;
    }

    // Apply hardware parameters
    rc = snd_pcm_hw_params(pcm, hw_params);
    if (rc < 0) {
        fprintf(stderr, "unable to set hw parameters: %s\n", snd_strerror(rc));
        cleanup();
        return 1;
    }

    // Allocate software parameters object
    snd_pcm_sw_params_alloca(&sw_params);

    // Get current software parameters
    rc = snd_pcm_sw_params_current(pcm, sw_params);
    if (rc < 0) {
        fprintf(stderr, "unable to get current sw parameters: %s\n", snd_strerror(rc));
        cleanup();
        return 1;
    }

    // Set start threshold to period size
    rc = snd_pcm_sw_params_set_start_threshold(pcm, sw_params, frames);
    if (rc < 0) {
        fprintf(stderr, "unable to set start threshold: %s\n", snd_strerror(rc));
        cleanup();
        return 1;
    }

    // Apply software parameters
    rc = snd_pcm_sw_params(pcm, sw_params);
    if (rc < 0) {
        fprintf(stderr, "unable to set sw parameters: %s\n", snd_strerror(rc));
        cleanup();
        return 1;
    }

    // Prepare PCM for use
    rc = snd_pcm_prepare(pcm);
    if (rc < 0) {
        fprintf(stderr, "unable to prepare pcm: %s\n", snd_strerror(rc));
        cleanup();
        return 1;
    }
#endif

    // Allocate audio buffer
    int *audio_buffer = (int *)malloc(SAMPLE_SIZE * sizeof(int));
    if (audio_buffer == NULL) {
        fprintf(stderr, "Failed to allocate audio buffer\n");
        cleanup();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Capture audio (or simulate)
#ifdef ALSA_AVAILABLE
        if (capture_audio(audio_buffer, SAMPLE_SIZE) < 0) {
            fprintf(stderr, "Error capturing audio\n");
        }
#else
        simulate_audio(audio_buffer, SAMPLE_SIZE);
#endif

        // Calculate RMS amplitude
        float rms_amplitude = calculate_rms(audio_buffer, SAMPLE_SIZE);

        // Map amplitude to color
        int red, green, blue;
        map_amplitude_to_color(rms_amplitude * sensitivity, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Print status message
        printf("RMS Amplitude: %.2f, Red: %d, Green: %d, Blue: %d\n", rms_amplitude, red, green, blue);

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup
    free(audio_buffer);
    cleanup();

    return 0;
}

