#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the relays
#define GPIO_PIN_1 17
#define GPIO_PIN_2 27
#define GPIO_PIN_3 22
#define GPIO_PIN_4 23

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define GPIO line names
#define GPIO_LINE_1 "gpio17"
#define GPIO_LINE_2 "gpio27"
#define GPIO_LINE_3 "gpio22"
#define GPIO_LINE_4 "gpio23"

// Define the number of relays
#define NUM_RELAYS 4

// Define the number of PWM steps
#define NUM_PWM_STEPS 10

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 51840

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_RELAYS];
int running = 1;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void set_relay_state(int pin, int state);
void set_relay_duty_cycle(int pin, int duty_cycle);
void sunrise();
void daytime();
void sunset();
void nighttime();
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up and exiting...\n", sig);
    running = 0;
    cleanup_gpio();
    exit(0);
}

// Function to initialize the GPIO lines
int initialize_gpio() {
    int i;
    int pin;
    char line_name[20];

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return -1;
    }

    // Request each GPIO line as an output
    for (i = 0; i < NUM_RELAYS; i++) {
        pin = (i == 0) ? GPIO_PIN_1 : ((i == 1) ? GPIO_PIN_2 : ((i == 2) ? GPIO_PIN_3 : GPIO_PIN_4));
        snprintf(line_name, sizeof(line_name), (i == 0) ? GPIO_LINE_1 : ((i == 1) ? GPIO_LINE_2 : ((i == 2) ? GPIO_LINE_3 : GPIO_LINE_4)));

        lines[i] = gpiod_line_get(chip, line_name);
        if (!lines[i]) {
            fprintf(stderr, "Error: Could not get GPIO line '%s'\n", line_name);
            cleanup_gpio();
            return -1;
        }

        if (gpiod_line_request_output(lines[i], "sunrise_simulator", 0) < 0) {
            fprintf(stderr, "Error: Could not request GPIO line '%s' as output\n", line_name);
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Function to cleanup the GPIO lines
void cleanup_gpio() {
    int i;

    // Release each GPIO line
    for (i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to set the state of a relay (0 for ON, 1 for OFF)
void set_relay_state(int pin, int state) {
    int i;
    for (i = 0; i < NUM_RELAYS; i++) {
        if ((i == 0 && pin == GPIO_PIN_1) || (i == 1 && pin == GPIO_PIN_2) || (i == 2 && pin == GPIO_PIN_3) || (i == 3 && pin == GPIO_PIN_4)) {
            gpiod_line_set_value(lines[i], state);
            break;
        }
    }
}

// Function to set the duty cycle of a relay using PWM-like toggling
void set_relay_duty_cycle(int pin, int duty_cycle) {
    int i;
    for (i = 0; i < NUM_RELAYS; i++) {
        if ((i == 0 && pin == GPIO_PIN_1) || (i == 1 && pin == GPIO_PIN_2) || (i == 2 && pin == GPIO_PIN_3) || (i == 3 && pin == GPIO_PIN_4)) {
            // Calculate the on and off times based on the duty cycle
            int on_time = (int)(((float)duty_cycle / NUM_PWM_STEPS) * 1000); // milliseconds
            int off_time = 1000 - on_time;

            // Toggle the relay
            gpiod_line_set_value(lines[i], 0); // ON
            usleep(on_time * 1000);           // Sleep for on_time milliseconds
            gpiod_line_set_value(lines[i], 1); // OFF
            usleep(off_time * 1000);           // Sleep for off_time milliseconds
            break;
        }
    }
}

// Function to simulate sunrise
void sunrise() {
    int i;
    for (i = 0; i < NUM_PWM_STEPS; i++) {
        set_relay_duty_cycle(GPIO_PIN_1, i + 1);
        set_relay_duty_cycle(GPIO_PIN_2, i + 1);
        set_relay_duty_cycle(GPIO_PIN_3, i + 1);
        set_relay_duty_cycle(GPIO_PIN_4, i + 1);
        usleep(SUNRISE_DURATION * 1000 / NUM_PWM_STEPS); // Sleep for a fraction of the sunrise duration
    }
}

// Function to simulate daytime
void daytime() {
    set_relay_state(GPIO_PIN_1, 1);
    set_relay_state(GPIO_PIN_2, 1);
    set_relay_state(GPIO_PIN_3, 1);
    set_relay_state(GPIO_PIN_4, 1);
    sleep(DAYTIME_DURATION);
}

// Function to simulate sunset
void sunset() {
    int i;
    for (i = NUM_PWM_STEPS - 1; i >= 0; i--) {
        set_relay_duty_cycle(GPIO_PIN_1, i + 1);
        set_relay_duty_cycle(GPIO_PIN_2, i + 1);
        set_relay_duty_cycle(GPIO_PIN_3, i + 1);
        set_relay_duty_cycle(GPIO_PIN_4, i + 1);
        usleep(SUNSET_DURATION * 1000 / NUM_PWM_STEPS); // Sleep for a fraction of the sunset duration
    }
}

// Function to simulate nighttime
void nighttime() {
    set_relay_state(GPIO_PIN_1, 0);
    set_relay_state(GPIO_PIN_2, 0);
    set_relay_state(GPIO_PIN_3, 0);
    set_relay_state(GPIO_PIN_4, 0);
    sleep(NIGHTTIME_DURATION);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO lines
    if (initialize_gpio() < 0) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        return 1;
    }

    // Main loop
    while (running) {
        sunrise();
        daytime();
        sunset();
        nighttime();
    }

    // Cleanup GPIO lines before exiting
    cleanup_gpio();

    return 0;
}

