#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define MOTION_SENSOR_PIN 17
#define LOG_FILE_PATH "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"
#define VIDEO_DURATION 5 // seconds

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle SIGINT signal (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y%m%dT%H%M%S%z", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
int log_message(const char *message) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for log message.\n");
        return -1;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the message is written to the file immediately
        free(timestamp);
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.\n");
        free(timestamp);
        return -1;
    }
}

// Function to record a video using raspivid
int record_video() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for video filename.\n");
        return -1;
    }

    char filename[100];
    snprintf(filename, sizeof(filename), "%s%s.h264", VIDEO_DIR, timestamp);

    char command[200];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, VIDEO_DURATION * 1000); // Duration in milliseconds

    int status = system(command);
    free(timestamp);

    if (status == 0) {
        char log_message_buffer[200];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Video recorded: %s", filename);
        log_message(log_message_buffer);
        return 0;
    } else {
        fprintf(stderr, "Failed to record video. System command returned status: %d\n", status);
        return -1;
    }
}

// Function to detect motion with debouncing
int detect_motion() {
    static int last_trigger_time = 0;
    int current_time = gpioTick();

    if (gpioRead(MOTION_SENSOR_PIN) == 0) { // Obstacle detected (active low)
        if (current_time - last_trigger_time > 200000) { // Debounce: 200ms = 200000 microseconds
            last_trigger_time = current_time;
            return 1; // Motion detected
        }
    }
    return 0; // No motion detected
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as input
    gpioSetMode(MOTION_SENSOR_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (detect_motion()) {
            printf("Motion detected!\n");
            if (record_video() != 0) {
                fprintf(stderr, "Failed to record video.\n");
            }
        }
        gpioDelay(50); // Check every 50ms
    }

    // Clean up
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

