#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define MEASUREMENT_INTERVAL 200  // milliseconds
#define MAX_ECHO_DURATION 23200   // microseconds (4 meters)
#define TIMEOUT_DURATION 100      // milliseconds
#define SPEED_OF_SOUND 34300      // cm/s
#define PIGPIO_INIT_RETRIES 3

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int timeout_flag = 0;
static FILE *log_file = NULL;
static pthread_mutex_t mutex;
static int running = 1;

// Function prototypes
void trigger_pulse();
void echo_rising_edge_callback(int gpio, int level, uint32_t tick, void *user_data);
void echo_falling_edge_callback(int gpio, int level, uint32_t tick, void *user_data);
void timeout_callback(int timer_id, void *user_data);
void signal_handler(int signal);
double calculate_distance(uint32_t pulse_width);
int log_distance(double distance);

// Function to send a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for rising edge of ECHO signal
void echo_rising_edge_callback(int gpio, int level, uint32_t tick, void *user_data) {
    pthread_mutex_lock(&mutex);
    start_tick = tick;
    echo_received = 1;
    timeout_flag = 0; // Reset timeout flag
    pthread_mutex_unlock(&mutex);
}

// Callback function for falling edge of ECHO signal
void echo_falling_edge_callback(int gpio, int level, uint32_t tick, void *user_data) {
    pthread_mutex_lock(&mutex);
    end_tick = tick;
    pthread_mutex_unlock(&mutex);
}

// Callback function for timeout
void timeout_callback(int timer_id, void *user_data) {
    pthread_mutex_lock(&mutex);
    timeout_flag = 1;
    pthread_mutex_unlock(&mutex);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;

    // Cancel callbacks
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioSetTimerFuncEx(0, 0, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    // Destroy mutex
    pthread_mutex_destroy(&mutex);

    exit(0);
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to log distance to file
int log_distance(double distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%ld,%.2f\n", timestamp_ns, distance) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    int pigpio_init_retries = PIGPIO_INIT_RETRIES;
    int init_result;

    // Initialize pigpio
    while (pigpio_init_retries > 0) {
        init_result = gpioInitialise();
        if (init_result >= 0) {
            printf("pigpio initialized successfully.\n");
            break;
        } else {
            fprintf(stderr, "pigpio initialisation failed: %d. Retrying...\n", init_result);
            pigpio_init_retries--;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    if (init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed after multiple retries. Exiting.\n");
        return 1;
    }

    // Initialize mutex
