#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_GPIO 17
#define DEFAULT_FREEFALL_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int configure_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int detect_freefall(float magnitude, float threshold);
int detect_impact(float magnitude, float threshold);
void activate_buzzer();
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initializes the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initializes the I2C connection
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configures the LIS3DH accelerometer
int configure_lis3dh() {
    char buf[2];
    int retries = 0;

    // Configure CTRL_REG1 (0x20) - 100 Hz data rate, enable all axes
    buf[0] = CTRL_REG1;
    buf[1] = 0x77; // 0b01110111
    while (i2cWriteDevice(i2c_handle, buf, 2) != 0 && retries < MAX_RETRIES) {
        fprintf(stderr, "Error writing to CTRL_REG1, retrying...\n");
        retries++;
        gpioDelay(1000); // Wait 1ms before retrying
    }
    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to write to CTRL_REG1 after multiple retries\n");
        return -1;
    }

    // Configure CTRL_REG4 (0x23) - ±2g full scale
    retries = 0;
    buf[0] = CTRL_REG4;
    buf[1] = 0x00; // 0b00000000
    while (i2cWriteDevice(i2c_handle, buf, 2) != 0 && retries < MAX_RETRIES) {
        fprintf(stderr, "Error writing to CTRL_REG4, retrying...\n");
        retries++;
        gpioDelay(1000); // Wait 1ms before retrying
    }
    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to write to CTRL_REG4 after multiple retries\n");
        return -1;
    }

    return 0;
}

// Reads acceleration data from the LIS3DH
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int retries = 0;

    while (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buf, 6) != 6 && retries < MAX_RETRIES) {
        fprintf(stderr, "Error reading acceleration data, retrying...\n");
        retries++;
        gpioDelay(1000); // Wait 1ms before retrying
    }
    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to read acceleration data after multiple retries\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Calculates the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 16384.0f;
    float y_g = (float)y / 16384.0f;
    float z_g = (float)z / 16384.0f;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Detects freefall
int detect_freefall(float magnitude, float threshold) {
    return (magnitude < threshold) ? 1 : 0;
}

// Detects impact
int detect_impact(float magnitude, float threshold) {
    return (magnitude > threshold) ? 1 : 0;
}

// Activates the buzzer for 1 second
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    gpioDelay(1000000);        // Wait for 1 second
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
}

// Cleans up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    // Print usage information if arguments are invalid
    if (freefall_threshold <= 0 || impact_threshold <= 0) {
        fprintf(stderr, "Usage: %s [freefall_threshold] [impact_threshold]\n", argv[0]);
        fprintf(stderr, "  freefall_threshold: Minimum acceleration magnitude to consider as freefall (default: %.2f)\n", DEFAULT_FREEFALL_THRESHOLD);
        fprintf(stderr, "  impact_threshold: Minimum acceleration magnitude to consider as impact (default: %.2f)\n", DEFAULT_IMPACT_THRESHOLD);
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure LIS3DH
    if (configure_lis3dh() != 0) {
        cleanup();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is initially off

    int16_t x, y, z;
    float magnitude;
    int freefall_detected = 0;

    printf("Fall detection system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Detect freefall
            if (detect_freefall(magnitude, freefall_threshold)) {
                freefall_detected = 1;
                printf("Freefall detected! Magnitude: %.2f g\n", magnitude);
            } else if (freefall_detected) {
                // Detect impact
                if (detect_impact(magnitude, impact_threshold)) {
                    printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                    activate_buzzer();
                    freefall_detected = 0; // Reset freefall flag after impact
                }
            } else {
                //printf("Magnitude: %.2f g\n", magnitude);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying initialization...\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            if (initialize_pigpio() != 0 || initialize_i2c() != 0 || configure_lis3dh() != 0) {
                fprintf(stderr, "Failed to re-initialize. Exiting.\n");
                break;
            }
        }

        gpioDelay(10000); // 10ms delay (100 Hz)
    }

    cleanup();
    return 0;
}

