    if (!program_running) return 0; // Check for termination signal
    if (move_motor(1, STEPS_PER_SIDE) != 0) return -1; // Move X-axis
    if (!program_running) return 0; // Check for termination signal
    if (move_motor(2, STEPS_PER_SIDE) != 0) return -1; // Move Y-axis
    if (!program_running) return 0; // Check for termination signal
    if (move_motor(1, -STEPS_PER_SIDE) != 0) return -1; // Move X-axis back
    if (!program_running) return 0; // Check for termination signal
    if (move_motor(2, -STEPS_PER_SIDE) != 0) return -1; // Move Y-axis back
    return 0;
}

// Function to stop the motors
void stop_motors() {
    int in1, in2, in3, in4;

    in1 = MOTOR1_IN1;
    in2 = MOTOR1_IN2;
    in3 = MOTOR1_IN3;
    in4 = MOTOR1_IN4;
    write_gpio(in1, 0);
    write_gpio(in2, 0);
    write_gpio(in3, 0);
    write_gpio(in4, 0);

    in1 = MOTOR2_IN1;
    in2 = MOTOR2_IN2;
    in3 = MOTOR2_IN3;
    in4 = MOTOR2_IN4;
    write_gpio(in1, 0);
    write_gpio(in2, 0);
    write_gpio(in3, 0);
    write_gpio(in4, 0);
}

