    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set GPIO pin modes
    if (set_gpio_mode(MOTOR1_IN1, PI_OUTPUT) != 0 ||
        set_gpio_mode(MOTOR1_IN2, PI_OUTPUT) != 0 ||
        set_gpio_mode(MOTOR1_IN3, PI_OUTPUT) != 0 ||
        set_gpio_mode(MOTOR1_IN4, PI_OUTPUT) != 0 ||
        set_gpio_mode(MOTOR2_IN1, PI_OUTPUT) != 0 ||
        set_gpio_mode(MOTOR2_IN2, PI_OUTPUT) != 0 ||
        set_gpio_mode(MOTOR2_IN3, PI_OUTPUT) != 0 ||
        set_gpio_mode(MOTOR2_IN4, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    // Draw the square
    printf("Drawing square...\n");
    if (draw_square() != 0) {
        fprintf(stderr, "Error drawing square\n");
    }

    // Stop the motors
    stop_motors();

    // Terminate pigpio
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

