#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0
#define LOG_FILE "/var/log/high_acceleration.log"
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
float threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int address);
int configure_sensor();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int check_threshold(float x, float y, float z, float threshold);
int log_event(float x, float y, float z);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// I2C initialization function
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Sensor configuration function
int configure_sensor() {
    // Configure CTRL_REG1 (ODR = 100 Hz, Enable X, Y, Z axes)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4 (High resolution mode)
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Acceleration data reading function
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Data conversion function
float convert_to_g(int16_t raw_value) {
    return (float)raw_value * 0.0009765625;
}

// Threshold checking function
int check_threshold(float x, float y, float z, float threshold) {
    if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
        return 1;
    }
    return 0;
}

// Logging function
int log_event(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - High acceleration detected: X=%.4f g, Y=%.4f g, Z=%.4f g\n", s, x, y, z);
    fclose(fp);
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address. Must be between 0x08 and 0x77.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold. Must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c(i2c_address) != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int16_t raw_x, raw_y, raw_z;
    float x_g, y_g, z_g;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to g
            x_g = convert_to_g(raw_x);
            y_g = convert_to_g(raw_y);
            z_g = convert_to_g(raw_z);

            // Check threshold
            if (check_threshold(x_g, y_g, z_g, threshold)) {
                // Log event
                if (log_event(x_g, y_g, z_g) == 0) {
                    // Shutdown system
                    printf("Threshold exceeded. Shutting down system.\n");
                    system("sudo shutdown -h now");
                } else {
                    fprintf(stderr, "Failed to log event.\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying.\n");
        }

        // Sleep for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

