#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define THRESHOLD_MT 5.0
#define THRESHOLD_MT_X100 (THRESHOLD_MT * 100)
#define CONVERSION_FACTOR 25.0
#define POLL_ATTEMPTS 50
#define POLL_DELAY_US 1000 // 1 ms
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int start_measurement();
int read_magnetic_field(int16_t *field_raw);
float convert_to_millitesla(int16_t field_raw);
int check_threshold(float field_mT_x100);
int control_relay(int state);
int log_event(const char *event_type, const char *message);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    int16_t raw_value;
    float millitesla;
} sensor_data_t;

int main() {
    sensor_data_t sensor_data;
    int result;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize the system
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Check magnetic_events.txt for details.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Start measurement
        if (start_measurement() != 0) {
            log_event("ERROR", "Failed to start measurement.");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay before next attempt
            continue;
        }

        // Read magnetic field
        if (read_magnetic_field(&sensor_data.raw_value) != 0) {
            log_event("ERROR", "Failed to read magnetic field.");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay before next attempt
            continue;
        }

        // Convert to milliTesla
        sensor_data.millitesla = convert_to_millitesla(sensor_data.raw_value);

        // Check threshold
        if (check_threshold(sensor_data.millitesla * 100) == 1) {
            // Activate relay
            if (control_relay(1) != 0) {
                log_event("ERROR", "Failed to activate relay.");
            }
            log_event("RELAY", "Activated");
        } else {
            // Deactivate relay
            if (control_relay(0) != 0) {
                log_event("ERROR", "Failed to deactivate relay.");
            }
            log_event("RELAY", "Deactivated");
        }

        // Log sensor data
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Raw: %d, mT: %.2f", sensor_data.raw_value, sensor_data.millitesla);
        log_event("SENSOR", log_message);

        // Delay before next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

// Initialize pigpio and I2C
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("ERROR", "pigpio initialisation failed");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("ERROR", "Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is initially off

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Start a one-shot measurement
int start_measurement() {
    int result = i2cWriteByteData(i2c_handle, 0xC1, 0x01);
    if (result != 0) {
        log_event("ERROR", "Failed to start measurement (write 0x01 to 0xC1)");
        return 1;
    }

    // Poll until conversion is complete (0x00 in register 0xC1)
    int attempts = 0;
    while (attempts < POLL_ATTEMPTS) {
        int status = i2cReadByteData(i2c_handle, 0xC1);
        if (status < 0) {
            log_event("ERROR", "Failed to read status register (0xC1)");
            return 1;
        }

        if (status == 0x00) {
            return 0; // Measurement complete
        }

        gpioDelay(POLL_DELAY_US);
        attempts++;
    }

    // Timeout
    log_event("ERROR", "Measurement timeout");
    return 1;
}

// Read magnetic field data
int read_magnetic_field(int16_t *field_raw) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0xC0, buffer, 2);
    if (result != 2) {
        log_event("ERROR", "Failed to read magnetic field data");
        return 1;
    }

    // Combine bytes into signed 16-bit value
    *field_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    return 0;
}

// Convert raw value to milliTesla
float convert_to_millitesla(int16_t field_raw) {
    return (float)field_raw * CONVERSION_FACTOR / 1000.0;
}

// Check if magnetic field exceeds threshold
int check_threshold(float field_mT_x100) {
    return (field_mT_x100 > THRESHOLD_MT_X100) ? 1 : 0;
}

// Control the relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Log events to file
int log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s [%s] %s\n", timestamp, event_type, message);
    fflush(log_file); // Ensure immediate write to file
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    terminate = 1;

    // Deactivate relay
    gpioWrite(RELAY_GPIO, 0);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    fclose(log_file);

    exit(0);
}

