#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define START_MEASUREMENT_CMD1 0x36
#define START_MEASUREMENT_CMD2 0x08
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define SCALE_FACTOR 1.0 / 1500.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define CRC_XOR 0x00

// Global variables
static volatile int running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_pigpio();
int open_i2c_handle(int bus, int addr);
int write_i2c_data(int handle, uint8_t *data, int count);
int read_i2c_data(int handle, uint8_t *data, int count);
int crc8(const uint8_t *data, int len);
float convert_to_ml_min(int16_t raw_value);
void control_relay(int gpio, int state);
void log_flow_data(float flow1, float flow2);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open an I2C handle
int open_i2c_handle(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Function to write data to an I2C device
int write_i2c_data(int handle, uint8_t *data, int count) {
    int result = i2cWriteDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read data from an I2C device
int read_i2c_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8
int crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw value to ml/min
float convert_to_ml_min(int16_t raw_value) {
    return (float)raw_value * SCALE_FACTOR;
}

// Function to control the relay
void control_relay(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Function to log flow data
void log_flow_data(float flow1, float flow2) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s, Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min\n", timestamp, flow1, flow2);
    fflush(log_file);
}

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    control_relay(RELAY_GPIO, 0); // De-energize relay

    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C handles
    i2c_handle1 = open_i2c_handle(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = open_i2c_handle(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Configure relay GPIO
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(RELAY_GPIO, 0); // Initialize relay to de-energized state

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Start measurement command
    uint8_t start_cmd[2] = {START_MEASUREMENT_CMD1, START_MEASUREMENT_CMD2};
    if (write_i2c_data(i2c_handle1, start_cmd, 2) != 0) {
        cleanup();
        return 1;
    }
    if (write_i2c_data(i2c_handle2, start_cmd, 2) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        uint8_t data1[3];
        uint8_t data2[3];
        int16_t raw_value1, raw_value2;
        float flow1, flow2;

        // Read data from sensor 1
        if (read_i2c_data(i2c_handle1, data1, 3) == 0) {
            raw_value1 = (data1[0] << 8) | data1[1];
            if (crc8(data1, 2) == data1[2]) {
                flow1 = convert_to_ml_min(raw_value1);
            } else {
                fprintf(stderr, "CRC check failed for sensor 1\n");
                flow1 = -1.0; // Indicate error
            }
        } else {
            fprintf(stderr, "Failed to read data from sensor 1\n");
            flow1 = -1.0; // Indicate error
        }

        // Read data from sensor 2
        if (read_i2c_data(i2c_handle2, data2, 3) == 0) {
            raw_value2 = (data2[0] << 8) | data2[1];
            if (crc8(data2, 2) == data2[2]) {
                flow2 = convert_to_ml_min(raw_value2);
            } else {
                fprintf(stderr, "CRC check failed for sensor 2\n");
                flow2 = -1.0; // Indicate error
            }
        } else {
            fprintf(stderr, "Failed to read data from sensor 2\n");
            flow2 = -1.0; // Indicate error
        }

        // Control relay based on flow rates
        if (flow1 >= 0.0 && flow2 >= 0.0) {
            if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
                control_relay(RELAY_GPIO, 1); // Energize relay
            } else {
                control_relay(RELAY_GPIO, 0); // De-energize relay
            }
        } else {
            fprintf(stderr, "Error reading flow data, not controlling relay\n");
        }

        // Log flow data
        if (flow1 >= 0.0 && flow2 >= 0.0) {
            log_flow_data(flow1, flow2);
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

