                flow2 = convert_to_ml_min(raw_value2);
            } else {
                fprintf(stderr, "CRC check failed for sensor 2\n");
                flow2 = -1.0; // Indicate error
            }
        } else {
            fprintf(stderr, "Failed to read data from sensor 2\n");
            flow2 = -1.0; // Indicate error
        }

        // Control relay based on flow rates
        if (flow1 >= 0.0 && flow2 >= 0.0) {
            if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
                control_relay(RELAY_GPIO, 1); // Energize relay
            } else {
                control_relay(RELAY_GPIO, 0); // De-energize relay
            }
        } else {
            fprintf(stderr, "Error reading flow data, not controlling relay\n");
        }

        // Log flow data
        if (flow1 >= 0.0 && flow2 >= 0.0) {
            log_flow_data(flow1, flow2);
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

