#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define constants
#define MOTOR_RUN_TIME 5 // seconds
#define POLL_INTERVAL 200 // milliseconds
#define DRY_READINGS_REQUIRED 3

// Global variables
volatile sig_atomic_t program_running = 1;
int dry_readings_count = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int start);
int stop_motor();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
    stop_motor();
    gpioTerminate();
    closelog();
    exit(0);
}

// Logging function
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO modes
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        log_message(LOG_ERR, "Failed to set RAIN_SENSOR_PIN to input");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_ENA_PIN to output");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_IN1_PIN to output");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_IN2_PIN to output");
        gpioTerminate();
        return -1;
    }

    // Set pull-up resistor on rain sensor pin
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    log_message(LOG_INFO, "GPIO initialisation complete");
    return 0;
}

// Read rain sensor value
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Control the motor (start or stop)
int control_motor(int start) {
    if (start) {
        log_message(LOG_INFO, "Starting motor");
        if (gpioWrite(MOTOR_ENA_PIN, 1) != 0) {
            log_message(LOG_WARNING, "Failed to set MOTOR_ENA_PIN HIGH");
            return -1;
        }
        if (gpioWrite(MOTOR_IN1_PIN, 1) != 0) {
            log_message(LOG_WARNING, "Failed to set MOTOR_IN1_PIN HIGH");
            return -1;
        }
        if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
            log_message(LOG_WARNING, "Failed to set MOTOR_IN2_PIN LOW");
            return -1;
        }
        gpioDelay(MOTOR_RUN_TIME * 1000000); // Run for 5 seconds
        return 0;
    } else {
        log_message(LOG_INFO, "Stopping motor");
        if (gpioWrite(MOTOR_ENA_PIN, 0) != 0) {
            log_message(LOG_WARNING, "Failed to set MOTOR_ENA_PIN LOW");
            return -1;
        }
        if (gpioWrite(MOTOR_IN1_PIN, 0) != 0) {
            log_message(LOG_WARNING, "Failed to set MOTOR_IN1_PIN LOW");
            return -1;
        }
        if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
            log_message(LOG_WARNING, "Failed to set MOTOR_IN2_PIN LOW");
            return -1;
        }
        return 0;
    }
}

// Stop the motor
int stop_motor() {
    return control_motor(0);
}

int main() {
    // Open syslog
    openlog("rain_window", LOG_PID, LOG_USER);
    log_message(LOG_INFO, "Starting rain-actuated window controller");

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialisation failed, exiting");
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_rain_state = 1; // Assume dry initially

    // Main loop
    while (program_running) {
        int rain_state = read_rain_sensor();

        if (rain_state == 0) { // Rain detected (LOW)
            dry_readings_count = 0; // Reset dry readings counter
            if (last_rain_state == 1) { // Transition from dry to wet
                log_message(LOG_INFO, "Rain detected, closing window");
                if (control_motor(1) != 0) {
                    log_message(LOG_WARNING, "Motor control failed");
                }
            }
            last_rain_state = 0;
        } else { // Dry (HIGH)
            dry_readings_count++;
            if (dry_readings_count >= DRY_READINGS_REQUIRED) {
                // Only trigger if it was previously raining
                if (last_rain_state == 0) {
                    log_message(LOG_INFO, "No rain detected for 600ms, ready to open window");
                }
            }
            last_rain_state = 1;
        }

        gpioDelay(POLL_INTERVAL * 1000); // Poll every 200ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();
    closelog();
    return 0;
}

