#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000
#define STOP_PULSE_WIDTH 0

// Debounce delay (milliseconds)
#define DEBOUNCE_DELAY 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C and SIGTERM
void signal_handler(int signal) {
    printf("\nCaught signal %d, shutting down...\n", signal);
    program_running = 0;
}

// Function to set the servo pulse width
int set_servo_pulse_width(int pulse_width) {
    int result = gpioServo(SERVO_PIN, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to handle the lock button press
void handle_lock_button() {
    printf("Lock button pressed\n");
    if (set_servo_pulse_width(LOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Failed to lock the door\n");
    }
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
}

// Function to handle the unlock button press
void handle_unlock_button() {
    printf("Unlock button pressed\n");
    if (set_servo_pulse_width(UNLOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Failed to unlock the door\n");
    }
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);

    // Enable internal pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for lock button press
        if (gpioRead(LOCK_BUTTON) == 0) {
            handle_lock_button();
        }

        // Check for unlock button press
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            handle_unlock_button();
        }

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    // Stop the servo
    printf("Stopping servo...\n");
    if (set_servo_pulse_width(STOP_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Failed to stop the servo\n");
    }

    // Terminate pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

