#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_PIN 4
#define FLOODLIGHT_PIN 17

// Define floodlight duration
#define FLOODLIGHT_DURATION 60 // seconds

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_floodlight(int state);
int log_event(const char *event_type, int duration);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int pir_pin;
    int floodlight_pin;
    int floodlight_duration;
    char *log_file_name;
} Config;

Config config = {PIR_PIN, FLOODLIGHT_PIN, FLOODLIGHT_DURATION, "security_log.txt"};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file. Turning off floodlight and exiting.\n");
        control_floodlight(0); // Turn off floodlight
        gpioTerminate();       // Release pigpio resources
        return 1;
    }

    // Main loop
    int last_pir_state = 0;
    while (running) {
        int pir_state = read_pir_sensor();

        if (pir_state == 1 && last_pir_state == 0) {
            // Motion detected
            printf("Motion detected!\n");
            if (control_floodlight(1) == 0) {
                if (log_event("Activation", 0) != 0) {
                    fprintf(stderr, "Error logging activation event.\n");
                }
                gpioDelay(config.floodlight_duration * 1000); // Wait for floodlight duration
                if (control_floodlight(0) == 0) {
                    if (log_event("Deactivation", config.floodlight_duration) != 0) {
                        fprintf(stderr, "Error logging deactivation event.\n");
                    }
                } else {
                    fprintf(stderr, "Error turning off floodlight.\n");
                }
            } else {
                fprintf(stderr, "Error turning on floodlight.\n");
            }
        }

        last_pir_state = pir_state;
        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    printf("Exiting cleanly.\n");
    control_floodlight(0); // Ensure floodlight is off
    fclose(log_file);       // Close log file
    gpioTerminate();       // Release pigpio resources

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(config.pir_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(config.floodlight_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set floodlight pin mode\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read PIR sensor state
int read_pir_sensor() {
    return gpioRead(config.pir_pin);
}

// Control the floodlight
int control_floodlight(int state) {
    if (gpioWrite(config.floodlight_pin, state) != 0) {
        fprintf(stderr, "Failed to write to floodlight pin\n");
        return 1;
    }
    return 0;
}

// Log events to file
int log_event(const char *event_type, int duration) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(log_file, "%s - %s - Duration: %d seconds\n", timestamp, event_type, duration) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return 1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    running = 0;
}

