#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <stdarg.h>
#include <errno.h>
#include <gpiod.h>
#include <pthread.h>
#include <math.h>

// Constants
#define SERVO_GPIO 17
#define PIR_GPIO 4
#define TCP_PORT 5000
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 1
#define MAX_PULSE_WIDTH 2
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define SERVER_BUFFER_SIZE 1024
#define CLIENT_BUFFER_SIZE 256

// Global variables
static volatile int running = 1;
static int server_fd = -1;
static int client_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static FILE *log_file = NULL;
static pthread_t servo_thread;

// Function prototypes
void log_message(int priority, const char *format, ...);
int init_gpio(void);
void cleanup_gpio(void);
void *servo_control_thread(void *arg);
int set_servo_angle(int angle);
int read_pir_sensor(void);
void handle_client(int client_fd);
void signal_handler(int signum);
int create_socket(void);
void bind_socket(int socket_fd);
void listen_socket(int socket_fd);
int accept_connection(int socket_fd);
void close_socket(int socket_fd);

// Logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Get current time
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    // Log to syslog
    syslog(priority, "%s: ", buf);
    vsyslog(priority, format, args);

    // Log to file
    fprintf(log_file, "%s: ", buf);
    vfprintf(log_file, format, args);
    fflush(log_file);

    va_end(args);
}

// GPIO initialization function
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(servo_line, "servo_control", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo GPIO line as output: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        log_message(LOG_ERR, "Failed to request PIR GPIO line as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// GPIO cleanup function
void cleanup_gpio(void) {
    if (servo_line) {
        gpiod_line_release(servo_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Servo control thread function
void *servo_control_thread(void *arg) {
    int angle = *((int *)arg);
    free(arg);
    set_servo_angle(angle);
    pthread_exit(NULL);
}

// Set servo angle function
int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        log_message(LOG_ERR, "Invalid servo angle: %d", angle);
        return -1;
    }

    // Calculate pulse width (1-2ms for 0-180 degrees)
    float pulse_width = MIN_PULSE_WIDTH + (float)(angle) / MAX_ANGLE * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH);

    // Calculate period and high time in nanoseconds
    int period_ns = 1000000000 / PWM_FREQUENCY; // Period in nanoseconds
    int high_time_ns = (int)(pulse_width * 1000000); // High time in nanoseconds

    // Calculate sleep times
    int sleep_time_ns = period_ns - high_time_ns;

    // Set servo line high
    if (gpiod_line_set_value(servo_line, 1) < 0) {
        log_message(LOG_ERR, "Failed to set servo line high: %s", strerror(errno));
        return -1;
    }
    usleep(high_time_ns / 1000); // Convert nanoseconds to microseconds

    // Set servo line low
    if (gpiod_line_set_value(servo_line, 0) < 0) {
        log_message(LOG_ERR, "Failed to set servo line low: %s", strerror(errno));
        return -1;
    }
    usleep(sleep_time_ns / 1000); // Convert nanoseconds to microseconds

    return 0;
}

// Read PIR sensor function
int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read PIR sensor value: %s", strerror(errno));
        return -1;
    }
    return value;
}

// Handle client connection function
void handle_client(int client_fd) {
    char buffer[CLIENT_BUFFER_SIZE];
    ssize_t bytes_received;

    while (running) {
        memset(buffer, 0, sizeof(buffer));
        bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            log_message(LOG_INFO, "Received: %s", buffer);

            if (strncmp(buffer, "SERVO", 5) == 0) {
                int angle = atoi(buffer + 6);
                if (angle >= MIN_ANGLE && angle <= MAX_ANGLE) {
                    int *angle_ptr = malloc(sizeof(int));
                    if (angle_ptr == NULL) {
                        log_message(LOG_ERR, "Failed to allocate memory for angle");
                        break;
                    }
                    *angle_ptr = angle;
                    if (pthread_create(&servo_thread, NULL, servo_control_thread, (void *)angle_ptr) != 0) {
                        log_message(LOG_ERR, "Failed to create servo thread: %s", strerror(errno));
                        free(angle_ptr);
                        break;
                    }
                    pthread_detach(servo_thread);
                    char response[32];
                    snprintf(response, sizeof(response), "SERVO:OK");
                    send(client_fd, response, strlen(response), 0);
                } else {
                    log_message(LOG_ERR, "Invalid servo angle: %d", angle);
                    send(client_fd, "SERVO:Invalid angle", strlen("SERVO:Invalid angle"), 0);
                }
            } else if (strncmp(buffer, "PIR", 3) == 0) {
                int pir_value = read_pir_sensor();
                if (pir_value >= 0) {
                    char response[16];
                    snprintf(response, sizeof(response), "PIR:%d", pir_value);
                    send(client_fd, response, strlen(response), 0);
                } else {
                    send(client_fd, "PIR:Error", strlen("PIR:Error"), 0);
                }
            } else {
                log_message(LOG_ERR, "Invalid command: %s", buffer);
                send(client_fd, "Invalid command", strlen("Invalid command"), 0);
            }
        } else if (bytes_received == 0) {
            log_message(LOG_INFO, "Client disconnected");
            break;
        } else {
            log_message(LOG_ERR, "Receive failed: %s", strerror(errno));
            break;
        }
    }

    close(client_fd);
    client_fd = -1;
}

// Signal handler function
void signal_handler(int signum) {
    log_message(LOG_INFO, "Signal received: %d", signum);
    running = 0;
    if (client_fd != -1) {
        close_socket(client_fd);
    }
    if (server_fd != -1) {
        close_socket(server_fd);
    }
    cleanup_gpio();
    closelog();
    fclose(log_file);
    exit(0);
}

// Socket creation function
int create_socket(void) {
    int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        log_message(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        return -1;
    }
    return socket_fd;
}

// Socket binding function
void bind_socket(int socket_fd) {
    struct sockaddr_in address;
