#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Callback function for MQTT messages
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, payload);

        if (strcmp(payload, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
            syslog(LOG_INFO, "Turning relay ON");
        } else if (strcmp(payload, "OFF") == 0) {
            gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
            syslog(LOG_INFO, "Turning relay OFF");
        } else {
            syslog(LOG_ERR, "Invalid payload: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty payload received");
    }
}

int main() {
    // Initialize syslog
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state
    syslog(LOG_INFO, "GPIO17 set as output and initialized to LOW");

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new mosquitto client instance
    mosq = mosquitto_new("relay_controller_1", true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto client instance");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set callbacks
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to the MQTT broker
    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    // Subscribe to the MQTT topic
    rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to topic: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        rc = mosquitto_loop(mosq, -1, 1); // -1 timeout means block indefinitely
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_WARNING, "mosquitto_loop error: %s, reconnecting...", mosquitto_strerror(rc));
            mosquitto_disconnect(mosq);
            sleep(5);
            rc = mosquitto_reconnect(mosq);
            if (rc != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "Failed to reconnect: %s", mosquitto_strerror(rc));
                // If reconnect fails, exit the loop
                running = 0;
            }
        }
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();
    closelog();

    return 0;
}

