#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO1_PULSE_WIDTH 1000
#define SERVO2_PULSE_WIDTH 1500
#define SERVO3_PULSE_WIDTH 2000
#define SERVO4_PULSE_WIDTH 500
#define SERVO5_PULSE_WIDTH 2500

#define PWM_FREQUENCY 50
#define PWM_RANGE 20000 // 20ms period = 20000 us

int main() {
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    result = gpioSetMode(SERVO1_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode: %d\n", SERVO1_PIN, result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetMode(SERVO2_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode: %d\n", SERVO2_PIN, result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetMode(SERVO3_PIN, PI_OUTPUT);
    if (result != 0) {
