        gpioTerminate();
        return 1;
    }
    result = gpioSetMode(SERVO4_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode: %d\n", SERVO4_PIN, result);
        gpioTerminate();
        return 1;
