    result = gpioSetMode(SERVO5_PIN, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode: %d\n", SERVO5_PIN, result);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency and range for each pin
    result = gpioSetPWMfrequency(SERVO1_PIN, PWM_FREQUENCY);
