    if (result != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d: %d\n", SERVO2_PIN, result);
        gpioTerminate();
        return 1;
    }

    result = gpioSetPWMfrequency(SERVO3_PIN, PWM_FREQUENCY);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d: %d\n", SERVO3_PIN, result);
        gpioTerminate();
        return 1;
    }
    result = gpioSetPWMrange(SERVO3_PIN, PWM_RANGE);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d: %d\n", SERVO3_PIN, result);
        gpioTerminate();
        return 1;
    }

