    if (result != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d: %d\n", SERVO5_PIN, result);
        gpioTerminate();
        return 1;
    }

    // Set pulse widths for each servo
    result = gpioPWM(SERVO1_PIN, SERVO1_PULSE_WIDTH);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %d\n", SERVO1_PIN, result);
        gpioTerminate();
        return 1;
    }
    result = gpioPWM(SERVO2_PIN, SERVO2_PULSE_WIDTH);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %d\n", SERVO2_PIN, result);
        gpioTerminate();
        return 1;
    }
    result = gpioPWM(SERVO3_PIN, SERVO3_PULSE_WIDTH);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %d\n", SERVO3_PIN, result);
        gpioTerminate();
        return 1;
    }
    result = gpioPWM(SERVO4_PIN, SERVO4_PULSE_WIDTH);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %d\n", SERVO4_PIN, result);
        gpioTerminate();
        return 1;
    }
    result = gpioPWM(SERVO5_PIN, SERVO5_PULSE_WIDTH);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %d\n", SERVO5_PIN, result);
        gpioTerminate();
        return 1;
    }

    // Wait for 3 seconds
    sleep(3);

    // Stop PWM and release resources
    gpioPWM(SERVO1_PIN, 0);
    gpioPWM(SERVO2_PIN, 0);
    gpioPWM(SERVO3_PIN, 0);
    gpioPWM(SERVO4_PIN, 0);
    gpioPWM(SERVO5_PIN, 0);

    gpioTerminate();

    return 0;
}

