#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

// Encoder A
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// Target RPM
#define TARGET_RPM 50.0

// PI Controller Gains
#define KP 0.5
#define KI 0.05

// PWM Frequency
#define PWM_FREQUENCY 10000 // 10 kHz

// Control Period
#define CONTROL_PERIOD_MS 100

// Stall Detection Time (seconds)
#define STALL_TIME 2

// Encoder Ticks Per Revolution
#define ENCODER_TICKS 64.0

// Global Variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
double integral_a = 0.0;
double integral_b = 0.0;
time_t last_a_tick = time(NULL);
time_t last_b_tick = time(NULL);

// Mutexes for thread safety
pthread_mutex_t mutex_a = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t mutex_b = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
void set_motor_speed(int motor_pwm, int motor_dir, int speed);
double calculate_rpm(int encoder_count);
double pi_controller(double target_rpm, double actual_rpm, double *integral);
void signal_handler(int signal);

// Structure to pass data to the control loop thread
typedef struct {
    int motor_a_pwm;
    int motor_a_dir;
    int motor_b_pwm;
    int motor_b_dir;
} MotorPins;

// Control loop thread function
void *control_loop(void *arg) {
    MotorPins *pins = (MotorPins *)arg;
    int motor_a_pwm = pins->motor_a_pwm;
    int motor_a_dir = pins->motor_a_dir;
    int motor_b_pwm = pins->motor_b_pwm;
    int motor_b_dir = pins->motor_b_dir;

    while (1) {
        // Read encoder counts
        pthread_mutex_lock(&mutex_a);
        int current_a_count = encoder_a_count;
        pthread_mutex_unlock(&mutex_a);

        pthread_mutex_lock(&mutex_b);
        int current_b_count = encoder_b_count;
        pthread_mutex_unlock(&mutex_b);

        // Calculate RPM
        double rpm_a = calculate_rpm(current_a_count);
        double rpm_b = calculate_rpm(current_b_count);

        // PI Controller
        double output_a = pi_controller(TARGET_RPM, rpm_a, &integral_a);
        double output_b = pi_controller(TARGET_RPM, rpm_b, &integral_b);

        // Stall Detection
        time_t now = time(NULL);
        if (current_a_count == 0 && difftime(now, last_a_tick) > STALL_TIME) {
            printf("WARNING: Motor A Stalled!\n");
        }
        if (current_b_count == 0 && difftime(now, last_b_tick) > STALL_TIME) {
            printf("WARNING: Motor B Stalled!\n");
        }

        // Set Motor Speeds
        set_motor_speed(motor_a_pwm, motor_a_dir, (int)output_a);
        set_motor_speed(motor_b_pwm, motor_b_dir, (int)output_b);

        // Print Data
        printf("Motor A: RPM=%.2f, PWM=%d | Motor B: RPM=%.2f, PWM=%d\n", rpm_a, gpioGetPWMdutycycle(motor_a_pwm), rpm_b, gpioGetPWMdutycycle(motor_b_pwm));

        // Reset encoder counts
        pthread_mutex_lock(&mutex_a);
        encoder_a_count = 0;
        last_a_tick = now;
        pthread_mutex_unlock(&mutex_a);

        pthread_mutex_lock(&mutex_b);
        encoder_b_count = 0;
        last_b_tick = now;
        pthread_mutex_unlock(&mutex_b);

        gpioDelay(CONTROL_PERIOD_MS * 1000); // Delay for control period
    }

    return NULL;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR_A_PWM, 255);
    gpioSetPWMrange(MOTOR_B_PWM, 255);

    // Register interrupt handlers
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for Encoder A A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for Encoder A B\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for Encoder B A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for Encoder B B\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Create control loop thread
    pthread_t control_thread;
    MotorPins pins = {MOTOR_A_PWM, MOTOR_A_DIR, MOTOR_B_PWM, MOTOR_B_DIR};
    if (pthread_create(&control_thread, NULL, control_loop, &pins) != 0) {
        fprintf(stderr, "Failed to create control loop thread\n");
        gpioTerminate();
        return 1;
    }

    // Wait for Ctrl+C
    pthread_join(control_thread, NULL);

    // Clean up
    gpioTerminate();
    return 0;
}

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    pthread_mutex_lock(&mutex_a);
    encoder_a_count++;
    pthread_mutex_unlock(&mutex_a);
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    pthread_mutex_lock(&mutex_b);
    encoder_b_count++;
    pthread_mutex_unlock(&mutex_b);
}

// Set Motor Speed
void set_motor_speed(int motor_pwm, int motor_dir, int speed) {
    // Clamp speed to 0-255
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;

    // Set direction
    gpioWrite(motor_dir, (speed > 0) ? 1 : 0); // Forward if speed > 0, backward if speed < 0

    // Set PWM duty cycle
    gpioPWM(motor_pwm, speed);
}

// Calculate RPM
double calculate_rpm(int encoder_count) {
    double rpm = (double)encoder_count / ENCODER_TICKS * 60.0 / (CONTROL_PERIOD_MS / 1000.0);
    return rpm;
}

// PI Controller
double pi_controller(double target_rpm, double actual_rpm, double *integral) {
    double error = target_rpm - actual_rpm;

    // Proportional term
    double proportional = KP * error;

    // Integral term
    *integral += KI * error * (CONTROL_PERIOD_MS / 1000.0);

    // Anti-windup
    if (*integral > 255) *integral = 255;
    if (*integral < 0) *integral = 0;

    // Calculate output
    double output = proportional + *integral;

    // Clamp output
    if (output > 255) output = 255;
    if (output < 0) output = 0;

    return output;
}

// Signal handler
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Stopping motors and exiting.\n");

    // Stop motors
    gpioWrite(MOTOR_A_DIR, 0);
    gpioWrite(MOTOR_B_DIR, 0);
    gpioPWM(MOTOR_A_PWM, 0);
    gpioPWM(MOTOR_B_PWM, 0);

    // Clean up
    gpioTerminate();

    exit(0);
}

