// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        // Turn off the relay
        gpioWrite(RELAY_PIN, 0);
        // Release pigpio resources
        gpioTerminate();
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as input
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to debounce the touch sensor
int debounce_touch() {
    if (read_touch_sensor() == 1) {
        gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
        if (read_touch_sensor() == 1) {
            return 1;
        }
    }
    return 0;
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", RELAY_PIN);
        return 1;
    }
    return 0;
}

