    printf("%s Relay is now %s\n", timestamp, state ? "ON" : "OFF");
    return 0;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (debounce_touch()) {
            if (toggle_relay() != 0) {
                fprintf(stderr, "Failed to toggle relay\n");
            } else {
                log_relay_state(relay_state);
            }

            // Wait for touch release
            while (read_touch_sensor() == 1) {
                gpioDelay(1000); // 1ms delay
            }
        }

        gpioDelay(10000); // 10ms delay
    }

    return 0;
}

