#include <time.h>
#include <string.h>

// Define GPIO pins
#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIME 1 // seconds

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file;
int running = 1;

// Function prototypes
double calculate_lpm(int pulses);
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);

// Function to calculate LPM
double calculate_lpm(int pulses) {
    return (pulses / PULSES_PER_LITER) * 60.0;
}

// ISR function for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to control the solenoid valve
void control_solenoid(double lpm) {
    static int solenoid_state = 1; // 1 = open, 0 = closed

    if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == 1) {
        gpioWrite(SOLENOID_PIN, 0); // Close solenoid
        solenoid_state = 0;
        log_data(lpm, solenoid_state);
    } else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == 0) {
        gpioWrite(SOLENOID_PIN, 1); // Open solenoid
        solenoid_state = 1;
        log_data(lpm, solenoid_state);
    }
}

// Function to log data to file
void log_data(double lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d\n", signal);
    log_data(0.0, 1); // Log the event
    gpioWrite(SOLENOID_PIN, 1); // Open solenoid
    if (log_file != NULL) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Initialize solenoid to open state
    gpioWrite(SOLENOID_PIN, 1);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up ISR for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, DEBOUNCE_TIME, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Sample pulse count
        int current_pulse_count;
        pthread_mutex_lock(&pulse_mutex);
        current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate LPM
        double lpm = calculate_lpm(current_pulse_count);

        // Control solenoid
        control_solenoid(lpm);

        // Log data
        log_data(lpm, gpioRead(SOLENOID_PIN));

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_PIN, 1);
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();

    return 0;
}

