// HX711 read function
long read_hx711(int data_pin, int sck_pin) {
    long value = 0;
    int i;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(sck_pin, PI_OUTPUT);

    // Wait for data pin to go low (HX711 ready)
    int timeout = 0;
    while (gpioRead(data_pin) == 1 && timeout < 1000) {
        gpioDelay(1); // 1ms delay
        timeout++;
    }

    if (timeout >= 1000) {
        fprintf(stderr, "Error: HX711 timeout waiting for data pin to go low.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1); // 1us delay
        value = value << 1;
        if (gpioRead(data_pin)) {
            value++;
        }
        gpioWrite(sck_pin, 0);
        gpioDelay(1); // 1us delay
    }

    // Apply the 25th clock pulse for gain 128
    gpioWrite(sck_pin, 1);
    gpioDelay(1); // 1us delay
    gpioWrite(sck_pin, 0);
    gpioDelay(1); // 1us delay

    // Convert to signed 2's complement
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

// HX711 calibration function
double calibrate_hx711(int data_pin, int sck_pin, double known_weight) {
    long raw_value = read_hx711(data_pin, sck_pin);
    if (raw_value == -1) {
        fprintf(stderr, "Error: Calibration failed due to HX711 timeout.\n");
        return -1.0;
    }
    return (double)known_weight / raw_value;
}

