int set_servo_pulse_width(int servo_pin, int pulse_width) {
    if (pulse_width < 1000 || pulse_width > 2000) {
        fprintf(stderr, "Error: Invalid pulse width. Must be between 1000 and 2000.\n");
        return -1;
    }

    gpioPWM(servo_pin, pulse_width / 10); // pigpio PWM range is 0-1000
