    // Assuming a linear relationship between weight and pulse width
    // Map target weight to pulse width range (1000-2000)
    double pulse_width = 1000.0 + (target_weight / calibration_factor) * (1000.0); // Adjust the scaling factor as needed
    if (pulse_width < 1000.0) pulse_width = 1000.0;
    if (pulse_width > 2000.0) pulse_width = 2000.0;
    return pulse_width;
}

