        buffer[read_size] = '\0';
        target_weight = atof(buffer);
        printf("Received target weight: %.2f grams\n", target_weight);
    } else {
        fprintf(stderr, "Error: Failed to receive target weight from client.\n");
        strcpy(error_message, "Failed to receive target weight");
        send(client_socket, error_message, strlen(error_message), 0);
        close(client_socket);
        return -1;
    }

