        strcpy(error_message, "Failed to read HX711 value");
        send(client_socket, error_message, strlen(error_message), 0);
        close(client_socket);
        return -1;
    }
    actual_weight = (double)raw_value * config.calibration_factor;

    // Send actual weight back to client
    char weight_str[256];
    snprintf(weight_str, sizeof(weight_str), "%.2f", actual_weight);
    if (send(client_socket, weight_str, strlen(weight_str), 0) < 0) {
