    if (result != 0) {
        fprintf(stderr, "Warning: Failed to read hx711_data_pin from config file. Using default value 23.\n");
        config->hx711_data_pin = 23;
    }

    result = config_read_int(ini, "hx711_sck_pin", &config->hx711_sck_pin);
    if (result != 0) {
        fprintf(stderr, "Warning: Failed to read hx711_sck_pin from config file. Using default value 24.\n");
        config->hx711_sck_pin = 24;
    }

    result = config_read_int(ini, "servo_pin", &config->servo_pin);
    if (result != 0) {
        fprintf(stderr, "Warning: Failed to read servo_pin from config file. Using default value 18.\n");
        config->servo_pin = 18;
    }

