    if (result != 0) {
        fprintf(stderr, "Warning: Failed to read calibration_factor from config file. Using default value 1.0.\n");
        config->calibration_factor = 1.0;
    }

    result = config_read_string(ini, "server_ip", config->server_ip, sizeof(config->server_ip));
    if (result != 0) {
