    gpioTerminate();
    close(socket_desc);
    exit(0);
}

int main() {
    int client_socket;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    double known_weight = 100.0; // Known weight for calibration in grams

    // Read configuration from file
    if (read_config("config.ini", &config) != 0) {
        fprintf(stderr, "Using default configuration values.\n");
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Calibrate HX711
    printf("Calibrating HX711...\n");
    config.calibration_factor = calibrate_hx711(config.hx711_data_pin, config.hx711_sck_pin, known_weight);
    if (config.calibration_factor <= 0) {
        fprintf(stderr, "Error: HX711 calibration failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }
    printf("Calibration factor: %.2f\n", config.calibration_factor);

    // Create socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc == -1) {
        fprintf(stderr, "Error: Could not create socket.\n");
        gpioTerminate();
        return 1;
    }

    // Prepare the sockaddr_in structure
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(config.server_ip);
    server_addr.sin_port = htons(config.server_port);

    // Bind
    if (bind(socket_desc, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error: Bind failed.\n");
        gpioTerminate();
        close(socket_desc);
        return 1;
    }
    printf("Bind done\n");

    // Listen
    listen(socket_desc, 3);

    // Accept incoming connections
    printf("Waiting for incoming connections...\n");
    while (running) {
        client_socket = accept(socket_desc, (struct sockaddr *)&client_addr, &client_len);
        if (client_socket < 0) {
            fprintf(stderr, "Error: Accept failed.\n");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted\n");

        // Handle client connection
        handle_client(client_socket);
    }

    // Clean up
    gpioTerminate();
    close(socket_desc);

    return 0;
}

