#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Default debounce time in milliseconds
#define DEFAULT_DEBOUNCE_TIME 50

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile int running = 1; // Flag to control the main loop
static int debounce_time = DEFAULT_DEBOUNCE_TIME;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int debounce_touch(int current_state);
int toggle_relay();
int log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, shutting down gracefully...\n", signal);
        running = 0; // Stop the main loop
        gpioWrite(RELAY_PIN, 0); // Turn off the relay
        gpioTerminate(); // Terminate pigpio
        exit(0); // Exit the program
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially OFF
    return 0; // Indicate success
}

// Read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Debounce the touch sensor
int debounce_touch(int current_state) {
    int stable_count = 0;
