#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <termios.h>
#include <signal.h>
#include <unistd.h>

#define SERVO_PIN 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define ANGLE_INCREMENT 10

volatile sig_atomic_t terminate = 0;
struct termios orig_termios;

void signal_handler(int signum) {
    terminate = 1;
}

// Function to initialize the terminal in raw mode
int init_raw_mode() {
    struct termios new_termios;

    if (tcgetattr(STDIN_FILENO, &orig_termios) != 0) {
        perror("tcgetattr");
        return -1;
    }

    new_termios = orig_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    new_termios.c_cc[VMIN] = 0;  // Non-blocking read
    new_termios.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) != 0) {
        perror("tcsetattr");
        return -1;
    }

    return 0;
}

// Function to restore the original terminal settings
void restore_term_mode() {
    tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);
}

// Function to map angle to pulse width
int angle_to_pulse_width(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d)\n", angle);
        return -1; // Indicate an error
    }
    return (int)(((float)(angle) / (MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);
}

// Function to set the servo angle
int set_servo_angle(int angle) {
    int pulse_width = angle_to_pulse_width(angle);
    if (pulse_width == -1) {
        return -1; // Propagate the error
    }

    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d)\n", pulse_width);
        return -1;
    }

    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

int main() {
    int angle = 90; // Initial angle
    int pulse_width;
    char input;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize raw terminal mode
    if (init_raw_mode() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set initial servo position
    if (set_servo_angle(angle) != 0) {
        restore_term_mode();
        gpioTerminate();
        return 1;
    }

    printf("Servo control program. Use '+' to increase, '-' to decrease, 'q' to quit.\n");

    while (!terminate) {
        if (read(STDIN_FILENO, &input, 1) == 1) {
            switch (input) {
                case '+':
                    angle += ANGLE_INCREMENT;
                    if (angle > MAX_ANGLE) {
                        angle = MAX_ANGLE;
                    }
                    break;
                case '-':
                    angle -= ANGLE_INCREMENT;
                    if (angle < MIN_ANGLE) {
                        angle = MIN_ANGLE;
                    }
                    break;
                case 'q':
                    terminate = 1;
                    break;
                default:
                    // Ignore other inputs
                    break;
            }

            if (set_servo_angle(angle) == 0) {
                printf("Angle: %d\n", angle);
            } else {
                fprintf(stderr, "Failed to set servo angle.\n");
            }
        }
        usleep(10000); // Small delay to prevent busy-waiting
    }

    // Stop PWM pulses
    gpioServo(SERVO_PIN, 0);

    // Restore terminal settings
    restore_term_mode();

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

