    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to set up a GPIO pin as input with pull-up
int setup_gpio(int pin) {
    struct gpiod_line *line = NULL;
    struct gpiod_line_request_config config;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "conveyor_motor_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to clean up GPIO resources
void cleanup_gpio(void) {
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_release(line3);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to log data to a file
void log_data(int pin, double rpm) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%.2f\n", buf, pin, rpm);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to calculate RPM
double calculate_rpm(int pulse_count, double time_elapsed) {
    return (pulse_count / time_elapsed) * 60.0;
}

// Interrupt handler for sensor events
void sensor_interrupt_handler(struct gpiod_line_event *event) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    unsigned long long current_time = (unsigned long long)ts.tv_sec * 1000000000ULL + ts.tv_nsec;

    if (event->line == sensor1.line) {
        if (current_time - sensor1.last_event_time > DEBOUNCE_TIME_MS * 1000000ULL) {
            sensor1.pulse_count++;
            sensor1.last_event_time = current_time;
        }
    } else if (event->line == sensor2.line) {
        if (current_time - sensor2.last_event_time > DEBOUNCE_TIME_MS * 1000000ULL) {
            sensor2.pulse_count++;
            sensor2.last_event_time = current_time;
        }
    } else if (event->line == sensor3.line) {
        if (current_time - sensor3.last_event_time > DEBOUNCE_TIME_MS * 1000000ULL) {
            sensor3.pulse_count++;
            sensor3.last_event_time = current_time;
        }
    }
}

int main() {
    struct timespec start_time, current_time;
    double time_elapsed;
    int ret;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen("motor_rpm.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Initialize GPIO pins
    if (setup_gpio(SENSOR1_PIN) != 0) {
        fclose(log_file);
        return 1;
    }
    sensor1.line = line1;

    if (setup_gpio(SENSOR2_PIN) != 0) {
        cleanup_gpio();
        fclose(log_file);
        return 1;
    }
    sensor2.line = line2;

    if (setup_gpio(SENSOR3_PIN) != 0) {
        cleanup_gpio();
        fclose(log_file);
        return 1;
    }
    sensor3.line = line3;

    // Get the start time
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Main loop
    while (running) {
        // Wait for events on the GPIO lines
        ret = gpiod_line_event_wait(line1, -1); // Wait indefinitely
        if (ret > 0) {
            struct gpiod_line_event event;
            event.line = line1;
            sensor_interrupt_handler(&event);
        } else if (ret < 0) {
            fprintf(stderr, "Error waiting for event on line 1: %s\n", strerror(errno));
            running = 0;
        }

        ret = gpiod_line_event_wait(line2, -1); // Wait indefinitely
        if (ret > 0) {
            struct gpiod_line_event event;
            event.line = line2;
            sensor_interrupt_handler(&event);
        } else if (ret < 0) {
            fprintf(stderr, "Error waiting for event on line 2: %s\n", strerror(errno));
            running = 0;
        }

        ret = gpiod_line_event_wait(line3, -1); // Wait indefinitely
        if (ret > 0) {
            struct gpiod_line_event event;
            event.line = line3;
            sensor_interrupt_handler(&event);
        } else if (ret < 0) {
            fprintf(stderr, "Error waiting for event on line 3: %s\n", strerror(errno));
            running = 0;
        }

        // Check if it's time to log data
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        time_elapsed = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        if (time_elapsed >= LOGGING_INTERVAL_SEC) {
            // Calculate RPM for each sensor
            double rpm1 = calculate_rpm(sensor1.pulse_count, LOGGING_INTERVAL_SEC);
            double rpm2 = calculate_rpm(sensor2.pulse_count, LOGGING_INTERVAL_SEC);
            double rpm3 = calculate_rpm(sensor3.pulse_count, LOGGING_INTERVAL_SEC);

            // Log the data
            log_data(SENSOR1_PIN, rpm1);
            log_data(SENSOR2_PIN, rpm2);
            log_data(SENSOR3_PIN, rpm3);

            // Print the data to stdout
            printf("Sensor %d: %.2f RPM\n", SENSOR1_PIN, rpm1);
            printf("Sensor %d: %.2f RPM\n", SENSOR2_PIN, rpm2);
            printf("Sensor %d: %.2f RPM\n", SENSOR3_PIN, rpm3);

            // Reset pulse counts and start time
            sensor1.pulse_count = 0;
            sensor2.pulse_count = 0;
            sensor3.pulse_count = 0;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }
    }

    // Clean up resources
    cleanup_gpio();
    fclose(log_file);

    return 0;
}

