#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define FAILSAFE_TIMEOUT_SEC 10

// Global variables
volatile int running = 1;
int relay_state = 0; // 0 = OFF, 1 = ON
time_t touch_start_time;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
void signal_handler(int signal);
void cleanup();

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize touch start time
    touch_start_time = time(NULL);

    // Main loop
    while (running) {
        int touch_value = read_touch_sensor();

        if (touch_value == 1) {
            // Rising edge detected
            relay_state = !relay_state; // Toggle relay state
            control_relay(relay_state);
            touch_start_time = time(NULL); // Reset touch start time
        } else if (touch_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading touch sensor. Exiting.\n");
            running = 0; // Exit the loop
        }

        // Failsafe mechanism
        if (touch_value == 1 && (time(NULL) - touch_start_time) > FAILSAFE_TIMEOUT_SEC) {
            fprintf(stderr, "Failsafe triggered: Touch sensor continuously HIGH for %d seconds. Turning relay OFF.\n", FAILSAFE_TIMEOUT_SEC);
            control_relay(0); // Turn relay OFF
            relay_state = 0; // Update relay state
            // Ignore further toggles until touch is released
            while (read_touch_sensor() == 1 && running) {
                gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Wait for touch to release
            }
            touch_start_time = time(NULL); // Reset touch start time after release
        }

        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read touch sensor value
int read_touch_sensor() {
    int value = gpioRead(TOUCH_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO%d\n", TOUCH_SENSOR_PIN);
        return PI_BAD_GPIO; // Indicate an error
    }
    return value;
}

// Control relay state
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", RELAY_PIN);
        return 1;
    }
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0; // Set the flag to exit the main loop
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    control_relay(0); // Turn relay OFF
    gpioTerminate();   // Terminate pigpio
    printf("Cleanup complete. Exiting.\n");
}

