#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define constants
#define PULSES_PER_LITER 450.0
#define KP 1.0
#define SAMPLE_INTERVAL_MS 100

// Global variables
volatile int pulse_count = 0;
double target_flow_rate = 0.0;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_flow_rate(int pulse_count);
double proportional_control(double target_flow_rate, double actual_flow_rate);
void log_data(double flow_rate, int valve_position);
void signal_handler(int signal);

// Interrupt service routine for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to calculate flow rate in L/min
double calculate_flow_rate(int pulse_count) {
    return (double)pulse_count / PULSES_PER_LITER * 60.0;
}

// Proportional controller function
double proportional_control(double target_flow_rate, double actual_flow_rate) {
    double error = target_flow_rate - actual_flow_rate;
    double output = KP * error;
    return output;
}

// Function to log data to file
void log_data(double flow_rate, int valve_position) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return 1;
    }

    char *token = strtok(argv[1], "-t");
    if (token == NULL || strcmp(token, "-t") != 0) {
        fprintf(stderr, "Invalid command-line argument format. Use -t <target_flow_rate>\n");
        return 1;
    }

    token = strtok(NULL, "-t");
    if (token == NULL) {
        fprintf(stderr, "Target flow rate not specified.\n");
        return 1;
    }

    char *endptr;
    target_flow_rate = strtod(token, &endptr);
    if (*endptr != '\0' || target_flow_rate <= 0.0) {
        fprintf(stderr, "Invalid target flow rate. Must be a positive number.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    // Enable the valve
    gpioWrite(VALVE_ENABLE_PIN, 1);

    // Set PWM range (0-255)
    gpioSetPWMrange(VALVE_PWM_PIN, 255);

    // Register interrupt handler for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for flow sensor\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int valve_position = 0;
    int accumulated_pulse_count = 0;

    // Main loop
    while (running) {
        // Accumulate pulse count for the sampling interval
        accumulated_pulse_count += pulse_count;
        pulse_count = 0; // Reset pulse count for the next interval

        // Calculate flow rate
        double actual_flow_rate = calculate_flow_rate(accumulated_pulse_count);
        accumulated_pulse_count = 0; // Reset accumulated pulse count

        // Proportional control
        double pwm_output = proportional_control(target_flow_rate, actual_flow_rate);

        // Clamp PWM output to [0, 255]
        if (pwm_output < 0) {
            pwm_output = 0;
        } else if (pwm_output > 255) {
            pwm_output = 255;
        }

        valve_position = (int)pwm_output;

        // Set valve PWM duty cycle
        gpioPWM(VALVE_PWM_PIN, valve_position);

        // Log data
        log_data(actual_flow_rate, valve_position);

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    gpioPWM(VALVE_PWM_PIN, 0); // Set PWM to 0
    gpioWrite(VALVE_ENABLE_PIN, 0); // Drive enable low
    fclose(log_file); // Close log file
    gpioTerminate(); // Terminate pigpio

    return 0;
}

