#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 100000

// Define valid RFID tag
const unsigned char valid_tag[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};
#define TAG_LENGTH 10

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define lock disengage time in seconds
#define LOCK_DISCHARGE_TIME 5

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rfid(unsigned char *tag);
int validate_tag(const unsigned char *tag, const unsigned char *valid_tag, int tag_length);
int read_button();
void disengage_locks();
void engage_locks();
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);

// Function to read RFID tag from SPI
int read_rfid(unsigned char *tag) {
    char rx_buffer[TAG_LENGTH];
    int result;

    result = spiRead(spi_handle, rx_buffer, TAG_LENGTH);

    if (result != TAG_LENGTH) {
        log_event("RFID Read Failure", "Failed to read RFID tag from SPI.");
        return -1; // Indicate failure
    }

    memcpy(tag, rx_buffer, TAG_LENGTH);
    return 0; // Indicate success
}

// Function to validate RFID tag
int validate_tag(const unsigned char *tag, const unsigned char *valid_tag, int tag_length) {
    if (memcmp(tag, valid_tag, tag_length) == 0) {
        return 0; // Tag is valid
    } else {
        return -1; // Tag is invalid
    }
}

// Function to read button state with debouncing
int read_button() {
    static int last_state = 1; // Initialize to released state (HIGH)
    static unsigned long last_debounce_time = 0;
    int current_state = gpioRead(BUTTON_PIN);
    unsigned long now = gpioTick();

    if (current_state != last_state) {
        last_debounce_time = now;
    }

    if ((now - last_debounce_time) > DEBOUNCE_TIME * 1000) { // Convert ms to microseconds
        if (current_state == 0) { // Button is pressed (active low)
            last_state = current_state;
            return 1; // Button press detected
        }
    }

    last_state = current_state;
    return 0; // No button press detected
}

// Function to disengage locks
void disengage_locks() {
    gpioWrite(LOCK1_PIN, 0); // Set LOW to disengage
    gpioWrite(LOCK2_PIN, 0); // Set LOW to disengage
    gpioDelay(LOCK_DISCHARGE_TIME * 1000000); // Wait for 5 seconds (microseconds)
}

// Function to engage locks
void engage_locks() {
    gpioWrite(LOCK1_PIN, 1); // Set HIGH to engage
    gpioWrite(LOCK2_PIN, 1); // Set HIGH to engage
}

// Function to log events
void log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s - %s - %s\n", buf, event_type, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, cleaning up...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable internal pull-up resistor

    // Open log file
    log_file = fopen("/var/log/door_access.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    unsigned char rfid_tag[TAG_LENGTH];
    int tag_valid = 0;
    int button_pressed = 0;

    printf("Two-factor authentication system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // RFID Authentication
        if (!tag_valid) {
            if (read_rfid(rfid_tag) == 0) {
                if (validate_tag(rfid_tag, valid_tag, TAG_LENGTH) == 0) {
                    log_event("RFID Authentication", "Valid RFID tag read.");
                    tag_valid = 1;
                } else {
                    log_event("RFID Authentication", "Invalid RFID tag.");
                }
            } else {
                // RFID read failure already logged in read_rfid function
            }
        }

        // Button Press Authentication
        if (tag_valid && !button_pressed) {
            if (read_button()) {
                log_event("Button Press", "Button pressed.");
                button_pressed = 1;
            }
        }

        // Access Granted
        if (tag_valid && button_pressed) {
            log_event("Access Granted", "Both authentication factors successful.");
            disengage_locks();
            engage_locks();
            tag_valid = 0; // Reset for next authentication
            button_pressed = 0; // Reset for next authentication
        }

        gpioDelay(100000); // Check every 100ms
    }

    // Clean up
    printf("Releasing locks and closing SPI...\n");
    engage_locks(); // Ensure locks are engaged on exit
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

