#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <gpiod.h>

// Motor 1 GPIOs
#define ENA 23
#define IN1 24
#define IN2 25

// Motor 2 GPIOs
#define ENB 12
#define IN3 16
#define IN4 20

// Encoder 1 GPIOs
#define ENC1_A 5
#define ENC1_B 6

// Encoder 2 GPIOs
#define ENC2_A 26
#define ENC2_B 19

// Encoder pulses per revolution
#define PPR 600

// Target RPM for Motor 1
#define TARGET_RPM_MOTOR1 60.0

// Target RPM for Motor 2
#define TARGET_RPM_MOTOR2 60.0

// PWM frequency (Hz)
#define PWM_FREQUENCY 100.0

// PWM period (seconds)
#define PWM_PERIOD (1.0 / PWM_FREQUENCY)

// Sample time (seconds)
#define SAMPLE_TIME 0.1

// PID gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global variables
static volatile int encoder1_count = 0;
static volatile int encoder2_count = 0;
static volatile double last_error1 = 0.0;
static volatile double integral1 = 0.0;
static volatile double last_error2 = 0.0;
static volatile double integral2 = 0.0;
static struct gpiod_chip *chip;
static struct gpiod_line *ena_line, *in1_line, *in2_line, *enb_line, *in3_line, *in4_line, *enc1_a_line, *enc1_b_line, *enc2_a_line, *enc2_b_line;
static FILE *log_file;
static volatile bool running = true;

// Mutexes for encoder counts
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
int initialize_gpio();
void *encoder1_thread(void *arg);
void *encoder2_thread(void *arg);
double calculate_rpm(int encoder_count, double elapsed_time);
double calculate_pid(double setpoint, double actual_value, double *last_error, double *integral);
void set_motor_speed(int motor_number, double pid_output);
void log_data(double rpm1, double rpm2, double p1, double i1, double d1, double output1, double p2, double i2, double d2, double output2);
void signal_handler(int signal);
void cleanup();

// Structure to pass data to encoder threads
typedef struct {
    int enc_a_gpio;
    int enc_b_gpio;
    int *encoder_count;
    pthread_mutex_t *mutex;
} encoder_data_t;

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,P1,I1,D1,Output1,P2,I2,D2,Output2\n");
    fflush(log_file);

    // Create encoder threads
    pthread_t encoder1_thread_id, encoder2_thread_id;
    encoder_data_t encoder1_data = {ENC1_A, ENC1_B, &encoder1_count, &encoder1_mutex};
    encoder_data_t encoder2_data = {ENC2_A, ENC2_B, &encoder2_count, &encoder2_mutex};

    if (pthread_create(&encoder1_thread_id, NULL, encoder1_thread, &encoder1_data) != 0) {
        perror("Failed to create encoder 1 thread");
        cleanup();
        return 1;
    }

    if (pthread_create(&encoder2_thread_id, NULL, encoder2_thread, &encoder2_data) != 0) {
        perror("Failed to create encoder 2 thread");
        cleanup();
        return 1;
    }

    // Main control loop
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        // Calculate RPM for each motor
        double rpm1 = calculate_rpm(encoder1_count, elapsed_time);
        double rpm2 = calculate_rpm(encoder2_count, elapsed_time);

        // Calculate PID output for each motor
        double output1 = calculate_pid(TARGET_RPM_MOTOR1, rpm1, &last_error1, &integral1);
        double output2 = calculate_pid(TARGET_RPM_MOTOR2, rpm2, &last_error2, &integral2);

        // Set motor speeds
        set_motor_speed(1, output1);
        set_motor_speed(2, output2);

        // Log data
        double p1 = KP * (TARGET_RPM_MOTOR1 - rpm1);
        double i1 = KI * integral1;
        double d1 = KD * (rpm1 - (last_error1 + (TARGET_RPM_MOTOR1 - rpm1) * SAMPLE_TIME));
        double p2 = KP * (TARGET_RPM_MOTOR2 - rpm2);
        double i2 = KI * integral2;
        double d2 = KD * (rpm2 - (last_error2 + (TARGET_RPM_MOTOR2 - rpm2) * SAMPLE_TIME));

        log_data(rpm1, rpm2, p1, i1, d1, output1, p2, i2, d2, output2);

        // Reset encoder counts
        pthread_mutex_lock(&encoder1_mutex);
        encoder1_count = 0;
        pthread_mutex_unlock(&encoder1_mutex);
        pthread_mutex_lock(&encoder2_mutex);
        encoder2_count = 0;
        pthread_mutex_unlock(&encoder2_mutex);

        // Wait for the next sample time
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        while (running) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;
            if (elapsed_time >= SAMPLE_TIME) break;
            usleep(1000); // Sleep for 1 ms
        }
    }

    // Join encoder threads
    pthread_join(encoder1_thread_id, NULL);
    pthread_join(encoder2_thread_id, NULL);

    // Cleanup
    cleanup();

    return 0;
}

int initialize_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    // Request GPIO lines
    ena_line = gpiod_chip_get_line(chip, ENA);
    in1_line = gpiod_chip_get_line(chip, IN1);
    in2_line = gpiod_chip_get_line(chip, IN2);
    enb_line = gpiod_chip_get_line(chip, ENB);
    in3_line = gpiod_chip_get_line(chip, IN3);
    in4_line = gpiod_chip_get_line(chip, IN4);
    enc1_a_line = gpiod_chip_get_line(chip, ENC1_A);
    enc1_b_line = gpiod_chip_get_line(chip, ENC1_B);
    enc2_a_line = gpiod_chip_get_line(chip, ENC2_A);
    enc2_b_line = gpiod_chip_get_line(chip, ENC2_B);

    if (!ena_line || !in1_line || !in2_line || !enb_line || !in3_line || !in4_line || !enc1_a_line || !enc1_b_line || !enc2_a_line || !enc2_b_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request lines for output
    if (gpiod_line_request_output(ena_line, "motor_control", 0) < 0 ||
        gpiod_line_request_output(in1_line, "motor_control", 0) < 0 ||
        gpiod_line_request_output(in2_line, "motor_control", 0) < 0 ||
        gpiod_line_request_output(enb_line, "motor_control", 0) < 0 ||
        gpiod_line_request_output(in3_line, "motor_control", 0) < 0 ||
        gpiod_line_request_output(in4_line, "motor_control", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request lines for input with rising and falling edge events
    if (gpiod_line_request_input(enc1_a_line, "motor_control") < 0 ||
        gpiod_line_request_input(enc1_b_line, "motor_control") < 0 ||
        gpiod_line_request_input(enc2_a_line, "motor_control") < 0 ||
        gpiod_line_request_input(enc2_b_line, "motor_control") < 0) {
        perror("Failed to request GPIO line for input");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_rising_edge_events(enc1_a_line, NULL) < 0 ||
        gpiod_line_request_falling_edge_events(enc1_a_line, NULL) < 0 ||
        gpiod_line_request_rising_edge_events(enc2_a_line, NULL) < 0 ||
        gpiod_line_request_falling_edge_events(enc2_a_line, NULL) < 0) {
        perror("Failed to request GPIO line for edge events");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void *encoder1_thread(void *arg) {
    encoder_data_t *data = (encoder_data_t *)arg;
    struct gpiod_line_event event;
    int ret;
    int current_b_value;

    while (running) {
        ret = gpiod_line_event_wait(data->enc_a_line, NULL);
        if (ret < 0) {
            perror("Failed to wait for encoder 1 event");
            break;
        }

        ret = gpiod_line_event_read(data->enc_a_line, &event);
        if (ret < 0) {
            perror("Failed to read encoder 1 event");
            break;
        }

        current_b_value = gpiod_line_get_value(data->enc_b_line);
        if (current_b_value < 0) {
            perror("Failed to read encoder 1 B value");
            break;
        }

        pthread_mutex_lock(data->mutex);
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            if (current_b_value == 0) {
                encoder1_count++;
            } else {
                encoder1_count--;
            }
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            if (current_b_value == 0) {
                encoder1_count--;
            } else {
                encoder1_count++;
            }
        }
        pthread_mutex_unlock(data->mutex);
    }

    return NULL;
}

void *encoder2_thread(void *arg) {
    encoder_data_t *data = (encoder_data_t *)arg;
    struct gpiod_line_event event;
    int ret;
    int current_b_value;

    while (running) {
        ret = gpiod_line_event_wait(data->enc_a_line, NULL);
        if (ret < 0) {
            perror("Failed to wait for encoder 2 event");
            break;
        }

        ret = gpiod_line_event_read(data->enc_a_line, &event);
        if (ret < 0) {
            perror("Failed to read encoder 2 event");
            break;
        }

        current_b_value = gpiod_line_get_value(data->enc_b_line);
        if (current_b_value < 0) {
            perror("Failed to read encoder 2 B value");
            break;
        }

        pthread_mutex_lock(data->mutex);
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            if (current_b_value == 0) {
                encoder2_count++;
            } else {
                encoder2_count--;
            }
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            if (current_b_value == 0) {
                encoder2_count--;
            } else {
                encoder2_count++;
            }
        }
        pthread_mutex_unlock(data->mutex);
    }

    return NULL;
}

double calculate_rpm(int encoder_count, double elapsed_time) {
    double pulses_per_second = (double)encoder_count / elapsed_time;
    double rpm = (pulses_per_second / PPR) * 60.0;
    return rpm;
}

double calculate_pid(double setpoint, double actual_value, double *last_error, double *integral) {
    double error = setpoint - actual_value;
    *integral += error * SAMPLE_TIME;
    double derivative = (error - *last_error) / SAMPLE_TIME;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *last_error = error;
    return output;
}

void set_motor_speed(int motor_number, double pid_output) {
    int ena_gpio, in1_gpio, in2_gpio, enb_gpio, in3_gpio, in4_gpio;
    struct gpiod_line *ena, *in1, *in2, *enb, *in3, *in4;

    if (motor_number == 1) {
        ena_gpio = ENA;
        in1_gpio = IN1;
        in2_gpio = IN2;
        ena = ena_line;
        in1 = in1_line;
        in2 = in2_line;
    } else if (motor_number == 2) {
        ena_gpio = ENB;
        in1_gpio = IN3;
        in2_gpio = IN4;
        ena = enb_line;
        in1 = in3_line;
        in2 = in4_line;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor_number);
        return;
    }

    // Clamp PID output to 0-100
    if (pid_output < 0.0) pid_output = 0.0;
    if (pid_output > 100.0) pid_output = 100.0;

    // Calculate on and off times for PWM
    double on_time = PWM_PERIOD * (pid_output / 100.0);
    double off_time = PWM_PERIOD - on_time;

    // Set motor direction and enable
    if (pid_output > 0.0) {
        if (gpiod_line_set_value(in1, 1) < 0) {
            perror("Failed to set IN1 high");
        }
        if (gpiod_line_set_value(in2, 0) < 0) {
            perror("Failed to set IN2 low");
        }
        if (gpiod_line_set_value(ena, 1) < 0) {
            perror("Failed to set ENA high");
        }
    } else {
        if (gpiod_line_set_value(in1, 0) < 0) {
            perror("Failed to set IN1 low");
        }
        if (gpiod_line_set_value(in2, 1) < 0) {
            perror("Failed to set IN2 high");
        }
        if (gpiod_line_set_value(ena, 1) < 0) {
            perror("Failed to set ENA high");
        }
    }

    // Software PWM
    while (pid_output > 0.0 && running) {
        if (gpiod_line_set_value(ena, 1) < 0) {
            perror("Failed to set ENA high");
        }
        usleep(on_time * 1000000); // Convert seconds to microseconds
        if (gpiod_line_set_value(ena, 0) < 0) {
            perror("Failed to set ENA low");
        }
        usleep(off_time * 1000000); // Convert seconds to microseconds
    }

    // Stop the motor if PID output is 0
    if (pid_output == 0.0) {
        if (gpiod_line_set_value(ena, 0) < 0) {
            perror("Failed to set ENA low");
        }
    }
}

void log_data(double rpm1, double rpm2, double p1, double i1, double d1, double output1, double p2, double i2, double d2, double output2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, rpm1, rpm2, p1, i1, d1, output1, p2, i2, d2, output2);
    fflush(log_file);
}

void signal_handler(int signal) {
