    running = false;
}

void cleanup() {
    // Stop motors
    if (gpiod_line_set_value(ena_line, 0) < 0) perror("Failed to set ENA low");
    if (gpiod_line_set_value(in1_line, 0) < 0) perror("Failed to set IN1 low");
