#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define TOUCH_STATUS_REG 0x00
#define RELEASE_STATUS_REG 0x01
#define LOG_FILE "relay_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init(int i2c_handle);
int read_touch_status(int i2c_handle);
void control_relay(int gpio_pin, int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
        control_relay(RELAY_GPIO, 0); // Deactivate relay
        if (i2c_handle >= 0) {
            i2cClose(i2c_handle);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

// MPR121 initialization function
int mpr121_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed.\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure filtering (example values)
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // MHDR
        fprintf(stderr, "Error: MHDR configuration failed.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x01) < 0) { // NHDR
        fprintf(stderr, "Error: NHDR configuration failed.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x05) < 0) { // NCLR
        fprintf(stderr, "Error: NCLR configuration failed.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x05) < 0) { // FDLR
        fprintf(stderr, "Error: FDLR configuration failed.\n");
        return -1;
    }

    // Set touch and release thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x30) < 0) { // Touch threshold
            fprintf(stderr, "Error: Touch threshold configuration failed for electrode %d.\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x10) < 0) { // Release threshold
            fprintf(stderr, "Error: Release threshold configuration failed for electrode %d.\n", i);
            return -1;
        }
    }

    // Enable run mode
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) {
        fprintf(stderr, "Error: Run mode configuration failed.\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(int i2c_handle) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, TOUCH_STATUS_REG, buf, 2) != 2) {
