#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "valve_log.txt"

// Global variables for GPIO lines and chip
struct gpiod_line *valve1_line = NULL;
struct gpiod_line *valve2_line = NULL;
struct gpiod_chip *gpio_chip = NULL;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio(void);
int open_valve(int valve_number);
int close_valve(int valve_number);
int log_event(int valve_number, int duration_ms);
void cleanup_gpio(void);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nCaught signal %d, cleaning up and exiting...\n", signum);
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Get GPIO line for valve 1
    valve1_line = gpiod_chip_get_line(gpio_chip, VALVE1_GPIO);
    if (!valve1_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", VALVE1_GPIO, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Get GPIO line for valve 2
    valve2_line = gpiod_chip_get_line(gpio_chip, VALVE2_GPIO);
    if (!valve2_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", VALVE2_GPIO, strerror(errno));
        gpiod_line_release(valve1_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(valve1_line, "valve1", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", VALVE1_GPIO, strerror(errno));
        gpiod_line_release(valve2_line);
        gpiod_line_release(valve1_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(valve2_line, "valve2", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", VALVE2_GPIO, strerror(errno));
        gpiod_line_release(valve1_line);
        gpiod_line_release(valve2_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to open a valve
int open_valve(int valve_number) {
    int ret;

    if (valve_number == 1) {
        ret = gpiod_line_set_value(valve1_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", VALVE1_GPIO, strerror(errno));
            return -1;
        }
    } else if (valve_number == 2) {
        ret = gpiod_line_set_value(valve2_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", VALVE2_GPIO, strerror(errno));
            return -1;
        }
    } else {
        fprintf(stderr, "Invalid valve number: %d\n", valve_number);
        return -1;
    }

    return 0;
}

// Function to close a valve
int close_valve(int valve_number) {
    int ret;

    if (valve_number == 1) {
        ret = gpiod_line_set_value(valve1_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", VALVE1_GPIO, strerror(errno));
            return -1;
        }
    } else if (valve_number == 2) {
        ret = gpiod_line_set_value(valve2_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", VALVE2_GPIO, strerror(errno));
            return -1;
        }
    } else {
        fprintf(stderr, "Invalid valve number: %d\n", valve_number);
        return -1;
    }

    return 0;
}

// Function to log an event to the log file
int log_event(int valve_number, int duration_ms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    // Get current time
    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    // Write log entry
    fprintf(log_file, "%s - Valve %d opened for %d ms\n", timestamp, valve_number, duration_ms);

    // Close log file
    fclose(log_file);

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    if (valve1_line) {
        gpiod_line_release(valve1_line);
    }
    if (valve2_line) {
        gpiod_line_release(valve2_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Automated Greenhouse Watering System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Open Valve 1 for 500 ms
        if (open_valve(1) == 0) {
            log_event(1, 500);
            usleep(500000); // 500 ms
            if (close_valve(1) != 0) {
                fprintf(stderr, "Error closing valve 1\n");
            }
        } else {
            fprintf(stderr, "Error opening valve 1\n");
        }

        // Pause for 5 seconds
        sleep(5);

        // Open Valve 2 for 1000 ms
        if (open_valve(2) == 0) {
            log_event(2, 1000);
            usleep(1000000); // 1000 ms
            if (close_valve(2) != 0) {
                fprintf(stderr, "Error closing valve 2\n");
            }
        } else {
            fprintf(stderr, "Error opening valve 2\n");
        }

        // Pause for 10 seconds
        sleep(10);
    }

    return 0;
}

