    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE0_THRESHOLD + 2 * i, 0x10) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d.\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE0_RELEASE + 2 * i, 0x0A) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d.\n", i);
            return -1;
        }
    }

    // Configure filter/charge time and electrode current
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x20) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121_CONFIG1.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG2, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121_CONFIG2.\n");
        return -1;
    }

