        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }

    *touch_status = ((unsigned short)buf[1] << 8) | (unsigned short)buf[0];
    return 0;
}

// Toggle Relay function
void toggle_relay() {
    int current_state = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_state);
}

