    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned short touch_status;
    int relay_state = 0; // 0 = off, 1 = on

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                toggle_relay();
                relay_state = !relay_state;
                printf("Touch detected! Relay is now %s\n", relay_state ? "ON" : "OFF");
            }
        } else {
            fprintf(stderr, "Error reading touch status, retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

