#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_1 17
#define PIR_SENSOR_2 22
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int last_unlock_time = 0;

// Function prototypes
void signal_handler(int signal);
void log_event(const char *event_type, int gpio);
void unlock_door();
void pir_callback(int gpio, int level, uint32_t tick);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to log events to a file
void log_event(const char *event_type, int gpio) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    if (log_file != NULL) {
        fprintf(log_file, "%ld.%03ld: %s (GPIO %d)\n", ts.tv_sec, milliseconds, event_type, gpio);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to unlock the door
void unlock_door() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long current_time = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

    if (current_time - last_unlock_time >= RATE_LIMIT_MS) {
        gpioWrite(RELAY_PIN, 1); // Activate relay
        log_event("Door unlocked", RELAY_PIN);
        gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay for 500ms
        gpioWrite(RELAY_PIN, 0); // Deactivate relay
        last_unlock_time = current_time;
    } else {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long milliseconds = ts.tv_nsec / 1000000;
        fprintf(log_file, "%ld.%03ld: Rate limited\n", ts.tv_sec, milliseconds);
        fflush(log_file);
    }
}

// Callback function for PIR sensor events
void pir_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge detected
        unlock_door();
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PIR_SENSOR_1, PI_INPUT);
    gpioSetMode(PIR_SENSOR_2, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistors for PIR sensors
    gpioSetPullUpDown(PIR_SENSOR_1, PI_PUD_DOWN);
    gpioSetPullUpDown(PIR_SENSOR_2, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up callbacks for PIR sensors
    gpioSetAlertFuncEx(PIR_SENSOR_1, pir_callback, NULL);
    gpioSetAlertFuncEx(PIR_SENSOR_2, pir_callback, NULL);

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(POLL_INTERVAL_MS * 1000); // Non-blocking delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();

    return 0;
}

