#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define the number of steps in a pattern
#define MIN_STEPS 5
#define MAX_STEPS 15

// Define the duration of each step in milliseconds
#define MIN_DURATION 50
#define MAX_DURATION 200

// Define the PWM range
#define PWM_RANGE 255

// Define the PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define the number of patterns to generate and play
#define NUM_PATTERNS 10

// Define the duration of the program in seconds
#define PROGRAM_DURATION 60

// Global flag to signal program shutdown
volatile sig_atomic_t shutdown_flag = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, shutting down gracefully...\n");
        shutdown_flag = 1;
    }
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to generate a random haptic feedback pattern
int generate_pattern(int *motor1_duties, int *motor2_duties, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        motor1_duties[i] = rand() % (PWM_RANGE + 1); // Random duty cycle between 0 and 255
        motor2_duties[i] = rand() % (PWM_RANGE + 1); // Random duty cycle between 0 and 255
        durations[i] = (rand() % (MAX_DURATION - MIN_DURATION + 1)) + MIN_DURATION; // Random duration between 50 and 200 ms
    }
    return 0;
}

// Function to play a haptic feedback pattern
void play_pattern(int *motor1_duties, int *motor2_duties, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        gpioPWM(MOTOR1_PIN, motor1_duties[i]);
        gpioPWM(MOTOR2_PIN, motor2_duties[i]);
        gpioDelay(durations[i] * 1000); // Convert ms to us
    }
}

// Function to stop the vibration motors
void stop_motors() {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
}

// Function to clean up and terminate the pigpio library
void cleanup() {
    stop_motors();
    gpioTerminate();
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop to generate and play haptic feedback patterns
    time_t start_time = time(NULL);
    while (!shutdown_flag && (time(NULL) - start_time) < PROGRAM_DURATION) {
        // Generate a random number of steps for the pattern
        int num_steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;

        // Allocate memory for the pattern data
        int *motor1_duties = (int *)malloc(num_steps * sizeof(int));
        int *motor2_duties = (int *)malloc(num_steps * sizeof(int));
        int *durations = (int *)malloc(num_steps * sizeof(int));

        if (motor1_duties == NULL || motor2_duties == NULL || durations == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            free(motor1_duties);
            free(motor2_duties);
            free(durations);
            cleanup();
            return 1;
        }

        // Generate the pattern
        generate_pattern(motor1_duties, motor2_duties, durations, num_steps);

        // Play the pattern
        play_pattern(motor1_duties, motor2_duties, durations, num_steps);

        // Free the allocated memory
        free(motor1_duties);
        free(motor2_duties);
        free(durations);
    }

    // Clean up and terminate the pigpio library
    cleanup();

    return 0;
}

