// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define calibration file
#define CALIBRATION_FILE "calibration.txt"

// Define log file
#define LOG_FILE "weight_log.txt"

// Define timeout duration (milliseconds)
#define TIMEOUT_MS 500

// Define weight threshold (kg)
#define WEIGHT_THRESHOLD 10.0

// Global variables
double scale_factor = 1.0;
double offset = 0.0;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_hx711();
double convert_to_weight(int raw_value);
void control_solenoid(double weight);
void log_data(int raw_value, double weight);
void load_calibration();
void save_calibration();
void startup_calibration();
void signal_handler(int signal);

// HX711 read function with timeout
int read_hx711() {
    int i;
    int data = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low (start of transmission)
    int timeout_count = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_count < TIMEOUT_MS) {
        gpioDelay(1); // Wait 1 ms
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_MS) {
        fprintf(stderr, "Error: HX711 read timeout\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Short delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Short delay
    }

    // Pulse the clock pin 1 more time to set the HX711 for the next reading
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Short delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Convert raw value to weight
double convert_to_weight(int raw_value) {
    return (raw_value - offset) / scale_factor;
}

// Control solenoid based on weight
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Lock
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Unlock
    }
}

// Log data to file
void log_data(int raw_value, double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Raw: %d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_value, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

// Load calibration data from file
void load_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Calibration file not found. Using default values.\n");
        return;
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Warning: Invalid calibration data. Using default values.\n");
        fclose(fp);
        return;
    }

    fclose(fp);
    printf("Calibration data loaded: scale_factor = %.2f, offset = %.2f\n", scale_factor, offset);
}

// Save calibration data to file
void save_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return;
    }

    fprintf(fp, "%lf %lf", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved: scale_factor = %.2f, offset = %.2f\n", scale_factor, offset);
}

// Perform startup calibration
void startup_calibration() {
    printf("Starting startup calibration...\n");
    double sum = 0.0;
    for (int i = 0; i < 100; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: HX711 read timeout during startup calibration. Skipping.\n");
            continue; // Skip to the next iteration
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    offset = sum / 100.0;
    printf("Startup calibration complete. Offset = %.2f\n", offset);
    save_calibration();
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d. Cleaning up...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    load_calibration();

    // Perform startup calibration
    startup_calibration();

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file for writing.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = convert_to_weight(raw_value);
            control_solenoid(weight);
            log_data(raw_value, weight);
            printf("Raw: %d, Weight: %.2f kg\n", raw_value, weight);
        } else {
            fprintf(stderr, "Error: HX711 read failed. Skipping.\n");
        }
        gpioDelay(500); // Read every 500 ms
    }

    // Cleanup
    gpioWrite(SOLENOID_PIN, 0); // Release solenoid
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

