#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17

// Define weight threshold (in grams)
#define WEIGHT_THRESHOLD 100.0

// Define solenoid activation time (in seconds)
#define SOLENOID_ACTIVATION_TIME 5

// Define timeout for HX711 read (in milliseconds)
#define HX711_TIMEOUT 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
double convert_to_grams(int raw_value);
void activate_solenoid();
void log_event(const char *message);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Structure to hold configuration data
typedef struct {
    int dt_pin;
    int sck_pin;
    int solenoid_pin;
    double weight_threshold;
    int solenoid_activation_time;
    int hx711_timeout;
} Config;

Config config = {HX711_DT, HX711_SCK, SOLENOID_PIN, WEIGHT_THRESHOLD, SOLENOID_ACTIVATION_TIME, HX711_TIMEOUT};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.dt_pin, PI_INPUT);
    gpioSetMode(config.sck_pin, PI_OUTPUT);
    gpioSetMode(config.solenoid_pin, PI_OUTPUT);

    gpioWrite(config.solenoid_pin, 0); // Ensure solenoid is initially off

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(config.solenoid_pin, 0); // Ensure solenoid is off
    gpioTerminate();
}

// Function to read data from HX711
int read_hx711() {
    int i;
    int data = 0;
    long start_time;

    gpioWrite(config.sck_pin, 0);

    // Wait for DT to go low (HX711 ready)
    start_time = gpioTick();
    while (gpioRead(config.dt_pin) == 1) {
        if (gpioTick() - start_time > config.hx711_timeout * 1000) {
            fprintf(stderr, "HX711 timeout error\n");
            return -1; // Timeout error
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(config.sck_pin, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(config.dt_pin)) {
            data++;
        }
        gpioWrite(config.sck_pin, 0);
        gpioDelay(1); // Small delay
    }

    // Apply the 25th clock pulse for gain 128
    gpioWrite(config.sck_pin, 1);
    gpioDelay(1); // Small delay
    gpioWrite(config.sck_pin, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Function to convert raw value to grams (example calibration)
double convert_to_grams(int raw_value) {
    // Replace with your actual calibration factor
    double calibration_factor = 0.01; // Example: 0.01 grams per raw unit
    return (double)raw_value * calibration_factor;
}

// Function to activate the solenoid lock
void activate_solenoid() {
    gpioWrite(config.solenoid_pin, 1); // Activate solenoid
    gpioDelay(config.solenoid_activation_time * 1000); // Wait for activation time
    gpioWrite(config.solenoid_pin, 0); // Deactivate solenoid
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
