    int dt_pin;
    int sck_pin;
    int solenoid_pin;
    double weight_threshold;
    int solenoid_activation_time;
    int hx711_timeout;
} Config;

Config config = {HX711_DT, HX711_SCK, SOLENOID_PIN, WEIGHT_THRESHOLD, SOLENOID_ACTIVATION_TIME, HX711_TIMEOUT};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.dt_pin, PI_INPUT);
    gpioSetMode(config.sck_pin, PI_OUTPUT);
    gpioSetMode(config.solenoid_pin, PI_OUTPUT);

    gpioWrite(config.solenoid_pin, 0); // Ensure solenoid is initially off

    return 0;
}

