#define WEIGHT_THRESHOLD 5.0

// Define solenoid activation time (in seconds)
#define SOLENOID_ACTIVATION_TIME 5

// Define timeout duration (in milliseconds)
#define TIMEOUT_DURATION 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static double calibration_factor = 0.0;

// Function prototypes
int read_hx711();
double convert_to_kg(int raw_value, double calibration_factor);
int calibrate_load_cell();
int control_solenoid(int state);
int log_event(double weight);
void signal_handler(int signal);
int load_calibration();
int save_calibration(double calibration_factor);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    control_solenoid(0); // Unlock the solenoid
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read raw data from HX711
int read_hx711() {
    int i;
    int data = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low (start of transmission)
    int timeout_count = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Wait 1 microsecond
        timeout_count++;
        if (timeout_count > TIMEOUT_DURATION * 1000) { // 100ms timeout
            fprintf(stderr, "Error: HX711 timeout waiting for data line to go low.\n");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low delay
    }

    // Apply the 25th clock pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw value to kilograms
double convert_to_kg(int raw_value, double calibration_factor) {
    return (double)raw_value / calibration_factor;
}

