    if (fp == NULL) {
        printf("Calibration file not found. Please calibrate the load cell.\n");
        return -1;
    }

    if (fscanf(fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Error: Invalid calibration factor in file.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Calibration factor loaded: %lf\n", calibration_factor);
    return 0;
}

// Function to save calibration factor to file
int save_calibration(double calibration_factor) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open calibration file for writing.\n");
        return -1;
    }

    fprintf(fp, "%lf", calibration_factor);
    fclose(fp);
    return 0;
}

