    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Load calibration factor from file
    if (load_calibration() != 0) {
        // If calibration file doesn't exist or is invalid, calibrate the load cell
        if (calibrate_load_cell() != 0) {
            fprintf(stderr, "Error: Calibration failed. Exiting.\n");
            gpioTerminate();
            return 1;
        }
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

