#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_PIN 16
#define RELAY_PIN 20

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *sensor_line = NULL;
struct gpiod_line *relay_line = NULL;
struct gpiod_chip *chip = NULL;

// Global variable for relay state
int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int read_sensor(struct gpiod_line *line);
int toggle_relay(struct gpiod_line *line, int *relay_state);
int log_event(const char *event);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to toggle the relay state
int toggle_relay(struct gpiod_line *line, int *relay_state) {
    *relay_state = !(*relay_state); // Toggle the state
    int ret = gpiod_line_set_value(line, *relay_state);
    if (ret < 0) {
        fprintf(stderr, "Error setting relay value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return 0;
}

// Function to log the event to a file
int log_event(const char *event) {
    FILE *fp = fopen("relay_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s: %s\n", timestamp, event);
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);

    if (!sensor_line || !relay_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input and output
    if (gpiod_line_request_input(sensor_line, "obstacle_sensor") < 0) {
