#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIOCHIP "gpiochip0"
#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"

// Global variables for signal handling
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

// Signal handler function
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nSignal received, terminating...\n");
}

// Function to read the watering duration from the configuration file
static int read_duration(const char *filename)
{
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening configuration file: %s\n", strerror(errno));
        return -1;
    }

    char line_buffer[256];
    if (fgets(line_buffer, sizeof(line_buffer), fp) == NULL) {
        if (feof(fp)) {
            fprintf(stderr, "Configuration file is empty.\n");
        } else {
            fprintf(stderr, "Error reading configuration file: %s\n", strerror(errno));
        }
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Parse the duration from the line
    char *key = strtok(line_buffer, "=");
    char *value = strtok(NULL, "=");

    if (key == NULL || value == NULL || strcmp(key, "duration") != 0) {
        fprintf(stderr, "Invalid configuration file format. Expected 'duration=<seconds>'.\n");
        return -1;
    }

    char *endptr;
    long duration = strtol(value, &endptr, 10);

    if (*endptr != '\0' || duration <= 0 || duration > 3600) {
        fprintf(stderr, "Invalid duration value. Must be a positive integer between 1 and 3600.\n");
        return -1;
    }

    return (int)duration;
}

// Function to initialize the GPIO line
static int initialize_gpio()
{
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Set initial value to 0 (valve off)
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting initial GPIO value: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to turn the valve on
static int valve_on()
{
    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error turning valve ON: %s\n", strerror(errno));
        return -1;
    }
    printf("Valve ON\n");
    return 0;
}

// Function to turn the valve off
static int valve_off()
{
    int ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error turning valve OFF: %s\n", strerror(errno));
        return -1;
    }
    printf("Valve OFF\n");
    return 0;
}

// Function to perform a signal-safe sleep
static int signal_safe_sleep(long seconds)
{
    struct timespec req, rem;
    req.tv_sec = seconds;
    req.tv_nsec = 0;

    while (seconds > 0) {
        if (nanosleep(&req, &rem) == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, adjust remaining time
                req = rem;
            } else {
                fprintf(stderr, "Error in nanosleep: %s\n", strerror(errno));
                return -1;
            }
        }
        seconds = req.tv_sec;
    }
    return 0;
}

// Function to cleanup GPIO resources
static void cleanup_gpio()
{
    if (line) {
        valve_off(); // Ensure valve is off before releasing
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main()
{
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Read watering duration from configuration file
    int duration = read_duration(CONFIG_FILE);
    if (duration < 0) {
        return EXIT_FAILURE;
    }

    printf("Watering duration: %d seconds\n", duration);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Turn valve on
        if (valve_on() < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        // Wait for the configured duration
        if (signal_safe_sleep(duration) < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        // Turn valve off
        if (valve_off() < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        // Wait for a while before the next watering cycle (optional)
        signal_safe_sleep(60); // Wait 60 seconds
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    printf("Watering system terminated.\n");
    return EXIT_SUCCESS;
}

