    config.consumer = "watering_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Set initial value to 0 (valve off)
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting initial GPIO value: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to turn the valve on
static int valve_on()
{
    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error turning valve ON: %s\n", strerror(errno));
        return -1;
    }
    printf("Valve ON\n");
    return 0;
}

// Function to turn the valve off
static int valve_off()
{
    int ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error turning valve OFF: %s\n", strerror(errno));
        return -1;
    }
    printf("Valve OFF\n");
    return 0;
}

// Function to perform a signal-safe sleep
static int signal_safe_sleep(long seconds)
{
    struct timespec req, rem;
    req.tv_sec = seconds;
    req.tv_nsec = 0;

    while (seconds > 0) {
        if (nanosleep(&req, &rem) == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, adjust remaining time
                req = rem;
            } else {
                fprintf(stderr, "Error in nanosleep: %s\n", strerror(errno));
                return -1;
            }
        }
        seconds = req.tv_sec;
    }
    return 0;
}

// Function to cleanup GPIO resources
static void cleanup_gpio()
{
    if (line) {
        valve_off(); // Ensure valve is off before releasing
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main()
{
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Read watering duration from configuration file
    int duration = read_duration(CONFIG_FILE);
    if (duration < 0) {
        return EXIT_FAILURE;
    }

    printf("Watering duration: %d seconds\n", duration);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Turn valve on
        if (valve_on() < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        // Wait for the configured duration
        if (signal_safe_sleep(duration) < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        // Turn valve off
        if (valve_off() < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        // Wait for a while before the next watering cycle (optional)
        signal_safe_sleep(60); // Wait 60 seconds
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    printf("Watering system terminated.\n");
    return EXIT_SUCCESS;
}

