int running = 1;

// Function prototypes
int read_sensor(int gpio);
void set_motor_speed(int forward_gpio, int backward_gpio, int speed);
void stop_motors();
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_motor_speed, int right_motor_speed);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to set motor speed
void set_motor_speed(int forward_gpio, int backward_gpio, int speed) {
    if (speed > 0) {
        gpioPWM(forward_gpio, speed);
        gpioPWM(backward_gpio, 0);
    } else if (speed < 0) {
        gpioPWM(forward_gpio, 0);
        gpioPWM(backward_gpio, -speed);
    } else {
        gpioPWM(forward_gpio, 0);
        gpioPWM(backward_gpio, 0);
    }
}

// Function to stop motors
void stop_motors() {
    gpioPWM(LEFT_MOTOR_FORWARD, 0);
    gpioPWM(LEFT_MOTOR_BACKWARD, 0);
    gpioPWM(RIGHT_MOTOR_FORWARD, 0);
    gpioPWM(RIGHT_MOTOR_BACKWARD, 0);
}

