        } else if (left_sensor == 0) {
            left_motor_speed = BASE_SPEED / 2;
            right_motor_speed = BASE_SPEED;
        } else if (right_sensor == 0) {
            left_motor_speed = BASE_SPEED;
            right_motor_speed = BASE_SPEED / 2;
        } else {
            stop_motors();
        }

        // Set motor speeds
        set_motor_speed(LEFT_MOTOR_FORWARD, LEFT_MOTOR_BACKWARD, left_motor_speed);
        set_motor_speed(RIGHT_MOTOR_FORWARD, RIGHT_MOTOR_BACKWARD, right_motor_speed);

        // Log data
        log_data(left_sensor, middle_sensor, right_sensor, left_motor_speed, right_motor_speed);

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup
    stop_motors();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

