#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define GROW_LAMP_GPIO 23
#define LUX_THRESHOLD 150
#define I2C_BUS 1
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_bh1750(int i2c_handle);
void control_relay(int gpio_pin, int state);
void log_data(FILE *log_file, int lux, int relay_state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read illuminance from BH1750 sensor
int read_bh1750(int i2c_handle) {
    int lux = -1; // Initialize to an error value
    char buf[2];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(180000); // Delay in microseconds

    // Read two bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert to lux value
    lux = (buf[0] << 8) | buf[1];
    return lux;
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log data to file
void log_data(FILE *log_file, int lux, int relay_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), 10, ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s Lux: %d, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int lux;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO23 as output
    gpioSetMode(GROW_LAMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read illuminance
        lux = read_bh1750(i2c_handle);

        if (lux >= 0) {
            // Control relay based on lux value
            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(GROW_LAMP_GPIO, 1);
                relay_state = 1;
                log_data(log_file, lux, relay_state);
                printf("Lux: %d, Relay: ON\n", lux);
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(GROW_LAMP_GPIO, 0);
                relay_state = 0;
                log_data(log_file, lux, relay_state);
                printf("Lux: %d, Relay: OFF\n", lux);
            } else {
                log_data(log_file, lux, relay_state);
                printf("Lux: %d, Relay: %s\n", lux, relay_state ? "ON" : "OFF");
            }
        } else {
            fprintf(stderr, "Error reading lux value\n");
            log_data(log_file, -1, relay_state); // Log error
        }

        // Wait before next reading
        gpioDelay(500000); // 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(GROW_LAMP_GPIO, 0); // Turn off relay
    fclose(log_file);
    gpioTerminate();

    return 0;
}

