#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse widths (microseconds)
#define LOCK_PULSE_WIDTH 1000
#define UNLOCK_PULSE_WIDTH 2000

// Debounce delay (milliseconds)
#define DEBOUNCE_DELAY 100

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to set the servo position
void set_servo_position(int pulse_width) {
    if (pulse_width < 500) {
        pulse_width = 500;
    } else if (pulse_width > 2500) {
        pulse_width = 2500;
    }
    gpioServo(SERVO_PIN, pulse_width);
    printf("Servo set to pulse width: %d\n", pulse_width);
}

// Function to read the lock button state with debouncing
int read_lock_button() {
    int button_state = gpioRead(LOCK_BUTTON_PIN);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    return (button_state == 0) ? 1 : 0; // Active low
}

// Function to read the unlock button state with debouncing
int read_unlock_button() {
    int button_state = gpioRead(UNLOCK_BUTTON_PIN);
