#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *motor1_line = NULL;
struct gpiod_line *motor2_line = NULL;
struct gpiod_chip *gpio_chip = NULL;

// Signal handler function
void signal_handler(int sig);

// Function to initialize GPIO lines
int initialize_gpio();

// Function to cleanup GPIO lines
void cleanup_gpio();

// Function to pulse motor 1
void pulse_motor1();

// Function to pulse motor 2
void pulse_motor2();

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO lines
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO lines. Exiting.\n");
        return 1;
    }

    // Main loop to pulse the motors
    while (1) {
        pulse_motor1();
        pulse_motor2();
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d. Cleaning up and exiting.\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio() {
    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO line for motor 1
    motor1_line = gpiod_chip_get_line(gpio_chip, MOTOR1_GPIO);
    if (!motor1_line) {
        perror("Error getting GPIO line for motor 1");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Get GPIO line for motor 2
    motor2_line = gpiod_chip_get_line(gpio_chip, MOTOR2_GPIO);
    if (!motor2_line) {
        perror("Error getting GPIO line for motor 2");
        gpiod_line_release(motor1_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request GPIO line for motor 1 as output
    if (gpiod_line_request_output(motor1_line, "motor1", 0) < 0) {
        perror("Error requesting GPIO line for motor 1 as output");
        gpiod_line_release(motor1_line);
        gpiod_line_release(motor2_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request GPIO line for motor 2 as output
    if (gpiod_line_request_output(motor2_line, "motor2", 0) < 0) {
        perror("Error requesting GPIO line for motor 2 as output");
        gpiod_line_release(motor1_line);
        gpiod_line_release(motor2_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio() {
    // Set both motors to LOW (off)
    if (motor1_line) {
        gpiod_line_set_value(motor1_line, 0);
        gpiod_line_release(motor1_line);
    }
    if (motor2_line) {
        gpiod_line_set_value(motor2_line, 0);
        gpiod_line_release(motor2_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

// Function to pulse motor 1
void pulse_motor1() {
    // Turn motor 1 on
    if (gpiod_line_set_value(motor1_line, 1) < 0) {
        perror("Error setting motor 1 value");
    }

    // Wait for 200 ms
    usleep(200000); // 200 ms

    // Turn motor 1 off
    if (gpiod_line_set_value(motor1_line, 0) < 0) {
        perror("Error setting motor 1 value");
    }
}

// Function to pulse motor 2
void pulse_motor2() {
    // Turn motor 2 on
    if (gpiod_line_set_value(motor2_line, 1) < 0) {
        perror("Error setting motor 2 value");
    }

    // Wait for 300 ms
    usleep(300000); // 300 ms

    // Turn motor 2 off
    if (gpiod_line_set_value(motor2_line, 0) < 0) {
        perror("Error setting motor 2 value");
    }
}

