#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <zmq.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ endpoint
#define ZMQ_ENDPOINT "tcp://*:5555"

// Define message topic
#define SOUND_ALERTS_TOPIC "SOUND_ALERTS"

// Global variables for GPIO and ZeroMQ resources
struct gpiod_chip *chip = NULL;
struct gpiod_line *sound_sensor_line = NULL;
struct gpiod_line *alarm_led_line = NULL;
void *zmq_context = NULL;
void *zmq_pub_socket = NULL;
void *zmq_sub_socket = NULL;

// Function prototypes
int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **sound_sensor_line, struct gpiod_line **alarm_led_line);
int setup_zmq(void **context, void **pub_socket, void **sub_socket);
int publish_alert(void *socket);
int subscribe_alert(void *socket);
void signal_handler(int signum);
void cleanup(void);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        cleanup();
        exit(0);
    }
}

// GPIO setup function
int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **sound_sensor_line, struct gpiod_line **alarm_led_line) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *sound_sensor_line = gpiod_chip_get_line(*chip, SOUND_SENSOR_PIN);
    if (!*sound_sensor_line) {
        perror("Error getting sound sensor line");
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_input(*sound_sensor_line, "sound_sensor") < 0) {
        perror("Error requesting sound sensor line as input");
        gpiod_chip_close(*chip);
        return -1;
    }

    *alarm_led_line = gpiod_chip_get_line(*chip, ALARM_LED_PIN);
    if (!*alarm_led_line) {
        perror("Error getting alarm LED line");
        gpiod_chip_close(*chip);
        gpiod_line_release(*sound_sensor_line);
        return -1;
    }

    if (gpiod_line_request_output(*alarm_led_line, "alarm_led", 0) < 0) {
        perror("Error requesting alarm LED line as output");
        gpiod_chip_close(*chip);
        gpiod_line_release(*sound_sensor_line);
        return -1;
    }

    return 0;
}

// ZeroMQ setup function
int setup_zmq(void **context, void **pub_socket, void **sub_socket) {
    *context = zmq_ctx_new();
    if (!*context) {
        perror("Error creating ZeroMQ context");
        return -1;
    }

    *pub_socket = zmq_socket(*context, ZMQ_PUB);
    if (!*pub_socket) {
        perror("Error creating ZeroMQ publisher socket");
        zmq_ctx_destroy(*context);
        return -1;
    }

    if (zmq_bind(*pub_socket, ZMQ_ENDPOINT) < 0) {
        perror("Error binding ZeroMQ publisher socket");
        zmq_close(*pub_socket);
        zmq_ctx_destroy(*context);
        return -1;
    }

    *sub_socket = zmq_socket(*context, ZMQ_SUB);
    if (!*sub_socket) {
        perror("Error creating ZeroMQ subscriber socket");
        zmq_close(*pub_socket);
        zmq_ctx_destroy(*context);
        return -1;
    }

    if (zmq_connect(*sub_socket, ZMQ_ENDPOINT) < 0) {
        perror("Error connecting ZeroMQ subscriber socket");
        zmq_close(*sub_socket);
        zmq_close(*pub_socket);
        zmq_ctx_destroy(*context);
        return -1;
    }

    if (zmq_setsockopt(*sub_socket, ZMQ_SUBSCRIBE, SOUND_ALERTS_TOPIC, strlen(SOUND_ALERTS_TOPIC)) < 0) {
        perror("Error setting ZeroMQ subscription option");
        zmq_close(*sub_socket);
        zmq_close(*pub_socket);
        zmq_ctx_destroy(*context);
        return -1;
    }

    return 0;
}

// Publish alert function
int publish_alert(void *socket) {
    char *message = "SOUND_DETECTED";
    int rc = zmq_send(socket, message, strlen(message), 0);
    if (rc < 0) {
        perror("Error sending ZeroMQ message");
        return -1;
    }
    return 0;
}

// Subscribe alert function
int subscribe_alert(void *socket) {
    char buffer[256];
    int rc = zmq_recv(socket, buffer, sizeof(buffer), 0);
    if (rc < 0) {
        perror("Error receiving ZeroMQ message");
        return -1;
    }
    buffer[rc] = '\0';
    printf("Received alert: %s\n", buffer);

    // Light the alarm LED for 1 second
    if (gpiod_line_set_value(alarm_led_line, 1) < 0) {
        perror("Error setting alarm LED value");
        return -1;
    }
    sleep(1);
    if (gpiod_line_set_value(alarm_led_line, 0) < 0) {
        perror("Error setting alarm LED value");
        return -1;
    }
    return 0;
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Close GPIO lines and chip
    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close ZeroMQ sockets and context
    if (zmq_pub_socket) {
        zmq_close(zmq_pub_socket);
    }
    if (zmq_sub_socket) {
        zmq_close(zmq_sub_socket);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        // Sound sensor mode
        printf("Running in sound_sensor mode...\n");

        // Setup GPIO
        if (setup_gpio(&chip, &sound_sensor_line, &alarm_led_line) < 0) {
            return 1;
        }

        // Setup ZeroMQ
        if (setup_zmq(&zmq_context, &zmq_pub_socket, NULL) < 0) {
            cleanup();
            return 1;
        }

        // Main loop
        while (1) {
            int value = gpiod_line_get_value(sound_sensor_line);
            if (value < 0) {
                perror("Error reading sound sensor value");
                cleanup();
                return 1;
            }

            if (value == 0) {
                // Sound detected
                printf("Sound detected!\n");
                if (publish_alert(zmq_pub_socket) < 0) {
                    cleanup();
                    return 1;
                }
            }

            usleep(10000); // 10 ms
        }

    } else if (strcmp(argv[1], "alarm_node") == 0) {
        // Alarm node mode
        printf("Running in alarm_node mode...\n");

        // Setup GPIO
        if (setup_gpio(&chip, NULL, &alarm_led_line) < 0) {
            return 1;
        }

        // Setup ZeroMQ
        if (setup_zmq(&zmq_context, NULL, &zmq_sub_socket) < 0) {
            cleanup();
            return 1;
        }

        // Main loop
        while (1) {
            if (subscribe_alert(zmq_sub_socket) < 0) {
                cleanup();
                return 1;
            }
        }

    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        return 1;
    }

    return 0;
}

