#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

// Constants
#define GPIO_PIN 17
#define PULSE_BUFFER_SIZE 64
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"

// NEC timings (in microseconds)
#define NEC_HDR_MARK 9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560

// Global variables
static volatile int pulse_count = 0;
static volatile uint32_t pulse_times[PULSE_BUFFER_SIZE];
static volatile int nec_data[32];
static volatile int nec_index = 0;
static struct mosquitto *mqtt_client = NULL;
static volatile int running = 1;

// Function prototypes
void signal_handler(int signal);
void alert_callback(int gpio, int level, uint32_t tick);
int decode_nec();
int validate_checksum(int address, int command);
void publish_mqtt(int address, int command);
void log_message(int address, int command);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Alert callback function to capture pulse timings
void alert_callback(int gpio, int level, uint32_t tick) {
    if (pulse_count < PULSE_BUFFER_SIZE) {
        pulse_times[pulse_count++] = tick;
    } else {
        syslog(LOG_ERR, "Pulse buffer overflow!");
        pulse_count = 0; // Reset buffer
    }
}

// Function to decode NEC IR signal
int decode_nec() {
    int address = 0;
    int command = 0;
    int inv_command = 0;
    int i;

    // Check for valid header
    if (pulse_count < 34) {
        syslog(LOG_ERR, "Incomplete NEC frame received.");
        pulse_count = 0;
        return -1;
    }

    // Decode data bits
    for (i = 0; i < 32; i++) {
        int pulse_duration = pulse_times[i * 2 + 2] - pulse_times[i * 2 + 1];
        if (pulse_duration > NEC_ONE_SPACE * 0.8 && pulse_duration < NEC_ONE_SPACE * 1.2) {
            nec_data[i] = 1;
        } else if (pulse_duration > NEC_ZERO_SPACE * 0.8 && pulse_duration < NEC_ZERO_SPACE * 1.2) {
            nec_data[i] = 0;
        } else {
            syslog(LOG_ERR, "Invalid pulse duration: %d", pulse_duration);
            pulse_count = 0;
            return -1;
        }
    }

    // Extract address and command
    address = 0;
    for (i = 0; i < 8; i++) {
        address |= (nec_data[i] << i);
    }

    command = 0;
    for (i = 8; i < 16; i++) {
        command |= (nec_data[i] << (i - 8));
    }

    inv_command = 0;
    for (i = 16; i < 24; i++) {
        inv_command |= (nec_data[i] << (i - 16));
    }

    // Validate checksum
    if (!validate_checksum(address, command)) {
        syslog(LOG_ERR, "Checksum validation failed.");
        pulse_count = 0;
        return -1;
    }

    // Validate inverted command
    if (inv_command != ((~command) & 0xFF)) {
        syslog(LOG_ERR, "Inverted command validation failed.");
        pulse_count = 0;
        return -1;
    }

    return address << 16 | command;
}

// Function to validate NEC checksum
int validate_checksum(int address, int command) {
    int checksum = 0;
    for (int i = 0; i < 8; i++) {
        checksum += (address >> i) & 1;
        checksum += (command >> i) & 1;
    }
    return (checksum & 0xFF) == 0;
}

// Function to publish decoded command to MQTT broker
void publish_mqtt(int address, int command) {
    char payload[64];
    snprintf(payload, sizeof(payload), "{\"address\": %d, \"command\": %d}", address, command);

    int ret = mosquitto_publish(mqtt_client, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
    }
}

// Function to log decoded command to syslog
void log_message(int address, int command) {
    syslog(LOG_INFO, "Decoded: Address = 0x%02X, Command = 0x%02X", address, command);
}

int main() {
    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Register alert callback
    gpioSetAlertFunc(GPIO_PIN, alert_callback);

    // Initialize MQTT
    mosquitto_lib_init();
    mqtt_client = mosquitto_new(NULL, true, NULL);
    if (!mqtt_client) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        gpioTerminate();
        closelog();
        return 1;
    }

    int ret = mosquitto_connect(mqtt_client, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mqtt_client);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mqtt_client);

    // Main loop
    while (running) {
        if (pulse_count >= 34) {
            int decoded_value = decode_nec();
            if (decoded_value != -1) {
                int address = (decoded_value >> 16) & 0xFF;
                int command = decoded_value & 0xFF;
                log_message(address, command);
                publish_mqtt(address, command);
            }
            pulse_count = 0; // Reset pulse count after processing
        }
        gpioDelay(1000); // Check every 1 ms
    }

    // Clean up
    mosquitto_loop_stop(mqtt_client, false);
    mosquitto_disconnect(mqtt_client);
    mosquitto_destroy(mqtt_client);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

