#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x24
#define BH1750_ADDR_3 0x25
#define BH1750_ADDR_4 0x26
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
int udp_socket = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

float read_bh1750(int address) {
    unsigned char buf[2];
    int result;

    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C slave address");
        return NAN;
    }

    if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Failed to write to I2C device");
        return NAN;
    }

    usleep(180000); // 180 ms

    result = read(i2c_fd, buf, 2);
    if (result != 2) {
        perror("Failed to read from I2C device");
        return NAN;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    return (float)raw_value / 1.2;
}

char* format_data(float lux1, float lux2, float lux3, float lux4) {
    static char buffer[256];
    snprintf(buffer, sizeof(buffer), "1,%.2f;2,%.2f;3,%.2f;4,%.2f", lux1, lux2, lux3, lux4);
    return buffer;
}

int send_udp_packet(const char* data) {
    struct sockaddr_in addr;
    int addrlen = sizeof(addr);

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(udp_socket, data, strlen(data), 0, (struct sockaddr*)&addr, addrlen) < 0) {
        perror("Failed to send UDP packet");
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Set multicast TTL to 1 for local network
    int ttl = 1;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Failed to set multicast TTL");
        close(i2c_fd);
        close(udp_socket);
        return 1;
    }

    while (program_running) {
        float lux1 = read_bh1750(BH1750_ADDR_1);
        float lux2 = read_bh1750(BH1750_ADDR_2);
        float lux3 = read_bh1750(BH1750_ADDR_3);
        float lux4 = read_bh1750(BH1750_ADDR_4);

        char* data = format_data(lux1, lux2, lux3, lux4);

        if (send_udp_packet(data) != 0) {
            fprintf(stderr, "Failed to send UDP packet, but continuing...\n");
        }

        sleep(1);
    }

    close(i2c_fd);
    close(udp_socket);

    return 0;
}

