int init_i2c(const char *device, int address) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read airflow data from the sensor
int read_airflow(int fd, unsigned short *raw_value) {
    unsigned char buffer[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Write a zero-length message to start the sensor
        if (write(fd, buffer, 0) != 0) {
            perror("Error writing to I2C device");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
