        if (read(fd, buffer, 2) != 2) {
            perror("Error reading from I2C device");
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Combine the two bytes into a 14-bit value
        *raw_value = (buffer[0] << 8) | buffer[1];
        *raw_value &= 0x3FFF; // Mask to 14 bits

