#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define AS7341_ADDR 0x39
#define WHO_AM_I 0x24
#define ENABLE 0x80
#define CFG6 0xAF
#define SP_EN 0x01
#define F1 0x60
#define F8 0x73
#define NUM_CHANNELS 10

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t stop_flag = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
} sensor_data_t;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int init_sensor(int fd);
sensor_data_t read_sensor_data(int fd);
float calculate_lux(sensor_data_t data);
void log_data(FILE *fp, sensor_data_t data, float lux);
void signal_handler(int sig);

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Sensor initialization function
int init_sensor(int fd) {
    uint8_t who_am_i;
    if (i2c_read_bytes(fd, WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x19) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02x\n", who_am_i);
        return -1;
    }

    // Power on the sensor
    if (i2c_write_byte(fd, ENABLE, 0x03) != 0) {
        fprintf(stderr, "Failed to power on sensor\n");
        return -1;
    }

    // Configure SMUX
    if (i2c_write_byte(fd, CFG6, 0x03) != 0) {
        fprintf(stderr, "Failed to configure SMUX\n");
        return -1;
    }

    // Enable spectral measurement
    if (i2c_write_byte(fd, ENABLE, 0x03 | SP_EN) != 0) {
        fprintf(stderr, "Failed to enable spectral measurement\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data(int fd) {
    sensor_data_t data;
    uint8_t buffer[NUM_CHANNELS * 2];

    if (i2c_read_bytes(fd, F1, buffer, NUM_CHANNELS * 2) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        // Initialize to 0 in case of failure
        data.f1 = data.f2 = data.f3 = data.f4 = data.f5 = data.f6 = data.f7 = data.f8 = data.clear = data.nir = 0;
        return data;
    }

    data.f1 = (buffer[1] << 8) | buffer[0];
    data.f2 = (buffer[3] << 8) | buffer[2];
    data.f3 = (buffer[5] << 8) | buffer[4];
    data.f4 = (buffer[7] << 8) | buffer[6];
    data.f5 = (buffer[9] << 8) | buffer[8];
    data.f6 = (buffer[11] << 8) | buffer[10];
    data.f7 = (buffer[13] << 8) | buffer[12];
    data.f8 = (buffer[15] << 8) | buffer[14];
    data.clear = (buffer[17] << 8) | buffer[16];
    data.nir = (buffer[19] << 8) | buffer[18];

    return data;
}

// Function to calculate lux (simplified approximation)
float calculate_lux(sensor_data_t data) {
    // This is a placeholder.  A real lux calculation would be more complex.
    // and based on the sensor's datasheet.
    return (float)(data.f1 + data.f2 + data.f3 + data.f4 + data.f5 + data.f6 + data.f7 + data.f8 + data.clear + data.nir) / 10.0;
}

// Function to log data to a file
void log_data(FILE *fp, sensor_data_t data, float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            data.f1, data.f2, data.f3, data.f4, data.f5, data.f6, data.f7, data.f8, data.clear, data.nir, lux);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, exiting...\n", sig);
    stop_flag = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (init_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!stop_flag) {
        // Read sensor data
        sensor_data_t data = read_sensor_data(i2c_fd);

        // Calculate lux
        float lux = calculate_lux(data);

        // Log data
        log_data(log_file, data, lux);

        // Wait 5 seconds
        sleep(5);
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

