#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define UDP_MULTICAST_ADDR "239.255.255.250"
#define UDP_MULTICAST_PORT 5000
#define SLEEP_SECONDS 1
#define LUX_CONVERSION_FACTOR 1.2

// Global variables for cleanup
int i2c_fd = -1;
int udp_socket = -1;

// Function prototypes
int init_i2c(const char *device);
int write_i2c(int fd, uint8_t addr, uint8_t data);
int read_i2c(int fd, uint8_t addr, uint8_t *data, int len);
float read_bh1750(int fd);
char* format_lux_to_string(float lux);
int send_udp_multicast(const char *message, const char *address, int port);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (udp_socket != -1) {
            close(udp_socket);
        }
        exit(0);
    }
}

// Initialize I2C device
int init_i2c(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Write a byte to the I2C device
int write_i2c(int fd, uint8_t addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Read bytes from the I2C device
int read_i2c(int fd, uint8_t addr, uint8_t *data, int len) {
    if (write(fd, &addr, 1) != 1) {
        perror("Error writing address to I2C device");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Read ambient light from BH1750 sensor
float read_bh1750(int fd) {
    uint8_t data[2];
    int raw_value;

    // Send power-on command
    if (write_i2c(fd, 0x00, 0x01) < 0) {
        fprintf(stderr, "Error sending power-on command\n");
        return -1.0;
    }
    usleep(200000); // Wait 200ms

    // Send continuous high-resolution mode command
    if (write_i2c(fd, 0x00, 0x10) < 0) {
        fprintf(stderr, "Error sending continuous high-resolution mode command\n");
        return -1.0;
    }
    usleep(200000); // Wait 200ms

    // Read 16-bit raw value
    if (read_i2c(fd, 0x00, data, 2) < 0) {
        fprintf(stderr, "Error reading raw value\n");
        return -1.0;
    }

    // Convert big-endian to integer
    raw_value = (data[0] << 8) | data[1];

    // Convert to lux
    return (float)raw_value / LUX_CONVERSION_FACTOR;
}

// Format lux value to string
char* format_lux_to_string(float lux) {
    char *str = (char*)malloc(20 * sizeof(char)); // Allocate memory for the string
    if (str == NULL) {
        perror("Error allocating memory");
        return NULL;
    }
    snprintf(str, 20, "%.2f", lux);
    return str;
}

// Send UDP multicast message
int send_udp_multicast(const char *message, const char *address, int port) {
    struct sockaddr_in addr;
    int ttl = 1;

    // Create socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating socket");
        return -1;
    }

    // Set TTL
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL");
        close(udp_socket);
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(address);
    addr.sin_port = htons(port);

    // Send message
    if (sendto(udp_socket, message, strlen(message), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP multicast message");
        close(udp_socket);
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_DEVICE);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read ambient light
        float lux = read_bh1750(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Failed to read BH1750 value. Retrying in %d seconds.\n", SLEEP_SECONDS);
            sleep(SLEEP_SECONDS);
            continue;
        }

        // Format lux value to string
        char *lux_str = format_lux_to_string(lux);
        if (lux_str == NULL) {
            fprintf(stderr, "Failed to format lux value. Retrying in %d seconds.\n", SLEEP_SECONDS);
            sleep(SLEEP_SECONDS);
            continue;
        }

        // Send UDP multicast message
        if (send_udp_multicast(lux_str, UDP_MULTICAST_ADDR, UDP_MULTICAST_PORT) < 0) {
            fprintf(stderr, "Failed to send UDP multicast message. Retrying in %d seconds.\n", SLEEP_SECONDS);
        }

        // Free allocated memory
        free(lux_str);

        // Sleep for 1 second
        sleep(SLEEP_SECONDS);
    }

    return 0;
}

