#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD_SIZE 8
const unsigned char MAGIC_WORD[MAGIC_WORD_SIZE] = {0x02, 0x04, 0x03, 0x06, 0x08, 0x05, 0x07, 0x09};
#define TLV_TYPE_DETECTED_OBJECTS 6
#define MAX_RANGE 100.0 // meters
#define MAX_VELOCITY 50.0 // m/s
#define CSV_FILE "radar_data.csv"
#define BUFFER_SIZE 2048

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold radar data
typedef struct {
    double timestamp;
    int object_index;
    double range_m;
    double velocity_mps;
} RadarData;

// Function prototypes
int initialize_uart();
void close_resources();
void signal_handler(int signal);
int read_uart_data(unsigned char *buffer, int buffer_size);
int find_magic_word(const unsigned char *buffer, int buffer_size);
int parse_tlv(const unsigned char *buffer, int buffer_size, RadarData *radar_data, int *num_objects);
int validate_payload(const unsigned char *payload, int payload_size);
void write_data_to_csv(const RadarData *radar_data, int num_objects);
double get_timestamp();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    return 0;
}

// Close UART and CSV file
void close_resources() {
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
    }
    gpioTerminate();
}

// Read data from UART
int read_uart_data(unsigned char *buffer, int buffer_size) {
    int bytes_read = serRead(uart_handle, buffer, buffer_size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %d\n", bytes_read);
        return -1;
    }
    return bytes_read;
}

// Find the magic word in the buffer
int find_magic_word(const unsigned char *buffer, int buffer_size) {
    for (int i = 0; i <= buffer_size - MAGIC_WORD_SIZE; ++i) {
        if (memcmp(buffer + i, MAGIC_WORD, MAGIC_WORD_SIZE) == 0) {
            return i; // Return the index of the magic word
        }
    }
    return -1; // Magic word not found
}

// Parse TLV data
int parse_tlv(const unsigned char *buffer, int buffer_size, RadarData *radar_data, int *num_objects) {
    int index = 0;
    *num_objects = 0;

    while (index < buffer_size - 4) { // Ensure enough bytes for type and length
        unsigned short tlv_type = (buffer[index + 1] << 8) | buffer[index];
        unsigned short tlv_length = (buffer[index + 3] << 8) | buffer[index + 2];

        if (index + 4 + tlv_length > buffer_size) {
            fprintf(stderr, "TLV length exceeds buffer size. Skipping.\n");
            return -1; // Malformed TLV
        }

        if (tlv_type == TLV_TYPE_DETECTED_OBJECTS) {
            // Process detected objects TLV
            const unsigned char *payload = buffer + index + 4;
            if (validate_payload(payload, tlv_length)) {
                // Extract range and velocity from payload (example format)
                // Assuming each object has a range (float) and velocity (float)
                int object_count = tlv_length / 8; // 4 bytes for range + 4 bytes for velocity
                if (object_count > 0) {
                    *num_objects = object_count;
                    for (int i = 0; i < object_count; ++i) {
                        radar_data[i].range_m = *((float *)(payload + i * 8));
                        radar_data[i].velocity_mps = *((float *)(payload + i * 8 + 4));
                        radar_data[i].timestamp = get_timestamp();
                        radar_data[i].object_index = i;
                    }
                }
            } else {
                fprintf(stderr, "Invalid payload in detected objects TLV.\n");
                return -1;
            }
        }

        index += 4 + tlv_length; // Move to the next TLV
    }

    return 0;
}

// Validate payload data
int validate_payload(const unsigned char *payload, int payload_size) {
    // Basic validation: check for reasonable range and velocity values
    // This is a placeholder; implement more robust validation based on AWR1642 data format
    if (payload_size % 8 != 0) return 0; // Ensure payload size is a multiple of 8 (range + velocity)

    int num_objects = payload_size / 8;
    for (int i = 0; i < num_objects; ++i) {
        float range = *((float *)(payload + i * 8));
        float velocity = *((float *)(payload + i * 8 + 4));

        if (range < 0 || range > MAX_RANGE || velocity < -MAX_VELOCITY || velocity > MAX_VELOCITY) {
            return 0; // Invalid data
        }
    }
    return 1; // Payload is valid
}

// Write data to CSV file
void write_data_to_csv(const RadarData *radar_data, int num_objects) {
    for (int i = 0; i < num_objects; ++i) {
        fprintf(csv_file, "%lf,%d,%lf,%lf\n", radar_data[i].timestamp, radar_data[i].object_index, radar_data[i].range_m, radar_data[i].velocity_mps);
    }
}

// Get timestamp in seconds
double get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        close_resources();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    rewind(csv_file);

    unsigned char buffer[BUFFER_SIZE];
    int bytes_read;
    int magic_word_index;
    RadarData radar_data[10]; // Assuming a maximum of 10 objects
    int num_objects;

    fprintf(stderr, "Starting data acquisition...\n");

    while (!terminate) {
        bytes_read = read_uart_data(buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            magic_word_index = find_magic_word(buffer, bytes_read);
            if (magic_word_index != -1) {
                // Magic word found, parse TLV data
                if (parse_tlv(buffer + magic_word_index, bytes_read - magic_word_index, radar_data, &num_objects) == 0) {
                    // Write data to CSV file
                    write_data_to_csv(radar_data, num_objects);
                } else {
                    fprintf(stderr, "Error parsing TLV data.\n");
                }
            } else {
                // Magic word not found, continue reading
                continue;
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, retrying...\n");
            gpioDelay(100); // Wait before retrying
        }
    }

    // Close resources before exiting
    close_resources();
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

