#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define LINE_BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
char line_buffer[LINE_BUFFER_SIZE];
int line_buffer_index = 0;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
}

// Function to initialize the UART
int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds timeout (5 * 0.1 seconds)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART
int read_uart(int fd, char *buffer, int buffer_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        } else {
            buffer[bytes_read] = '\0'; // Null-terminate the buffer
            return bytes_read;
        }
    }
}

// Function to parse the data
int parse_data(const char *data) {
    char *token;
    char *line = strdup(data); // Duplicate the string for strtok
    if (line == NULL) {
        fprintf(stderr, "Error duplicating string: %s\n", strerror(errno));
        return -1;
    }

    token = strtok(line, ",");
    if (token == NULL) {
        fprintf(stderr, "Error parsing timestamp\n");
        free(line);
        return -1;
    }
    long timestamp = strtol(token, NULL, 10);

    token = strtok(NULL, "\n");
    if (token == NULL) {
        fprintf(stderr, "Error parsing range\n");
        free(line);
        return -1;
    }
    float range = strtof(token, NULL);

    free(line);

    // Validate data
    if (range < 0.0 || range > 100.0) {
        fprintf(stderr, "Invalid range value: %.2f\n", range);
        return -1;
    }

    return 0;
}

// Function to log the data
void log_data(long timestamp, float range) {
    time_t rawtime = timestamp;
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&rawtime);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    printf("UART initialized. Reading data...\n");

    while (program_running) {
        int bytes_read = read_uart(uart_fd, line_buffer + line_buffer_index, LINE_BUFFER_SIZE - line_buffer_index - 1);
        if (bytes_read > 0) {
            line_buffer_index += bytes_read;

            // Check for newline character
            for (int i = 0; i < line_buffer_index; ++i) {
                if (line_buffer[i] == '\n') {
                    line_buffer[i] = '\0'; // Null-terminate the line
                    int parse_result = parse_data(line_buffer);
                    if (parse_result == 0) {
                        // Extract timestamp and range from the line
                        char *token;
                        char *line_copy = strdup(line_buffer);
                        if (line_copy == NULL) {
                            fprintf(stderr, "Error duplicating string: %s\n", strerror(errno));
                            continue;
                        }
                        token = strtok(line_copy, ",");
                        if (token != NULL) {
                            long timestamp = strtol(token, NULL, 10);
                            token = strtok(NULL, "\n");
                            if (token != NULL) {
                                float range = strtof(token, NULL);
                                log_data(timestamp, range);
                            }
                        }
                        free(line_copy);
                    } else {
                        fprintf(stderr, "Error parsing data: %s\n", line_buffer);
                    }

                    // Reset the line buffer
                    line_buffer_index = 0;
                    break; // Exit the inner loop after processing the line
                }
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting...\n");
            break;
        }
    }

    // Close UART
    if (uart_fd != -1) {
        close(uart_fd);
        printf("UART closed.\n");
    }

    return EXIT_SUCCESS;
}

