        fprintf(stderr, "Error parsing range\n");
        free(line);
        return -1;
    }
    float range = strtof(token, NULL);

    free(line);

    // Validate data
    if (range < 0.0 || range > 100.0) {
        fprintf(stderr, "Invalid range value: %.2f\n", range);
        return -1;
    }

    return 0;
}

// Function to log the data
void log_data(long timestamp, float range) {
    time_t rawtime = timestamp;
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&rawtime);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    printf("UART initialized. Reading data...\n");

    while (program_running) {
        int bytes_read = read_uart(uart_fd, line_buffer + line_buffer_index, LINE_BUFFER_SIZE - line_buffer_index - 1);
        if (bytes_read > 0) {
            line_buffer_index += bytes_read;

            // Check for newline character
            for (int i = 0; i < line_buffer_index; ++i) {
                if (line_buffer[i] == '\n') {
                    line_buffer[i] = '\0'; // Null-terminate the line
                    int parse_result = parse_data(line_buffer);
                    if (parse_result == 0) {
                        // Extract timestamp and range from the line
                        char *token;
                        char *line_copy = strdup(line_buffer);
                        if (line_copy == NULL) {
                            fprintf(stderr, "Error duplicating string: %s\n", strerror(errno));
                            continue;
                        }
                        token = strtok(line_copy, ",");
                        if (token != NULL) {
                            long timestamp = strtol(token, NULL, 10);
                            token = strtok(NULL, "\n");
                            if (token != NULL) {
                                float range = strtof(token, NULL);
                                log_data(timestamp, range);
                            }
                        }
                        free(line_copy);
                    } else {
                        fprintf(stderr, "Error parsing data: %s\n", line_buffer);
                    }

                    // Reset the line buffer
                    line_buffer_index = 0;
                    break; // Exit the inner loop after processing the line
                }
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting...\n");
            break;
        }
    }

    // Close UART
    if (uart_fd != -1) {
        close(uart_fd);
        printf("UART closed.\n");
    }

    return EXIT_SUCCESS;
}

