#include <termios.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define serial port parameters
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int serial_fd = -1;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to configure a GPIO pin as input with pull-up resistor
int configure_gpio_input(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to read the state of a sensor
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", pin);
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log sensor data to the console
void log_sensor_data(int left, int middle, int right) {
    char timestamp[20];
    get_timestamp(timestamp);
    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to send an emergency stop message over the serial port
int send_emergency_stop() {
    const char *message = "EMERGENCY STOP!\n";
    ssize_t bytes_written = write(serial_fd, message, strlen(message));
    if (bytes_written < 0) {
        perror("Error writing to serial port");
        return -1;
    }
    return 0;
}

// Function to initialize the serial port
int initialize_serial_port() {
    serial_fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial_fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(serial_fd, &tty) != 0) {
        perror("Error getting serial port attributes");
        close(serial_fd);
        serial_fd = -1;
        return -1;
    }

    cfsetospeed(&tty, B115200);
    cfsetispeed(&tty, B115200);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    tty.c_lflag &= ~ECHOE;
    tty.c_lflag &= ~ECHONL;
    tty.c_lflag &= ~ISIG;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK|BRKINT|PARMRK|ISTRIP|INLCR|IGNCR|ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;  // Non-blocking read
    tty.c_cc[VTIME] = 5; // Timeout of 0.5 seconds

    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        perror("Error setting serial port attributes");
        close(serial_fd);
        serial_fd = -1;
        return -1;
    }

    return 0;
}

// Function to close the serial port
void close_serial_port() {
    if (serial_fd != -1) {
        close(serial_fd);
        serial_fd = -1;
    }
}

// Function to terminate the pigpio library
void terminate_pigpio() {
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    if (configure_gpio_input(LEFT_SENSOR_PIN) != 0 ||
        configure_gpio_input(MIDDLE_SENSOR_PIN) != 0 ||
        configure_gpio_input(RIGHT_SENSOR_PIN) != 0) {
        terminate_pigpio();
        return 1;
    }

    // Initialize the serial port
    if (initialize_serial_port() != 0) {
        terminate_pigpio();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        // Log sensor data
        log_sensor_data(left_value, middle_value, right_value);

        // Check for emergency stop condition
        if (left_value == 0 && middle_value == 0 && right_value == 0) {
            if (send_emergency_stop() != 0) {
                fprintf(stderr, "Failed to send emergency stop message\n");
            }
        }

        // Delay for 100ms (10Hz)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    close_serial_port();
    terminate_pigpio();

    return 0;
}

